INSERT INTO `fc_meta` (k, v) VALUES ('schema_version', '28') ON DUPLICATE KEY UPDATE v = VALUES(v);
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('html-base','html',1,NULL,'published','{"title":{"it":"HTML base","en":"HTML Basics"},"short":{"it":"HTML base","en":"HTML Basics"},"desc":{"it":"Il linguaggio con cui è fatta ogni pagina web: tag, testi, link, immagini, liste, tabelle, moduli, contenitori e come controllare il codice.","en":"The language every web page is made of: tags, text, links, images, lists, tables, forms, containers and how to check your code."},"level":{"it":"Base","en":"Basics"},"categories":["frontend"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('html-intermediate','html',2,'html-base','published','{"title":{"it":"HTML intermedio","en":"Intermediate HTML"},"short":{"it":"HTML intermedio","en":"HTML Intermediate"},"desc":{"it":"Attributi globali, link interni, testo ricco, iframe, tabelle accessibili, figure e date, moduli più completi e come si inviano.","en":"Global attributes, internal links, rich text, iframes, accessible tables, figures and dates, fuller forms and how they are sent."},"level":{"it":"Intermedio","en":"Intermediate"},"categories":["frontend"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('html-advanced','html',3,'html-intermediate','published','{"title":{"it":"HTML avanzato","en":"Advanced HTML"},"short":{"it":"HTML avanzato","en":"Advanced HTML"},"desc":{"it":"Pagine semantiche e accessibili: struttura, moduli ricchi, contenuti multimediali, metadati e SEO, popover e finestre di dialogo, caricamento delle risorse e immagini responsive.","en":"Semantic, accessible pages: structure, rich forms, media, metadata and SEO, popovers and dialogs, resource loading and responsive images."},"level":{"it":"Avanzato","en":"Advanced"},"categories":["frontend"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('css-base','css',4,'html-base','published','{"title":{"it":"CSS base","en":"CSS Basics"},"short":{"it":"CSS base","en":"CSS Basics"},"desc":{"it":"Dai forma alle pagine: selettori, colori, testi, box model, posizionamento, cascata, sfondi, unità di misura e dimensioni flessibili.","en":"Give pages their shape: selectors, colours, text, box model, positioning, the cascade, backgrounds, units and flexible sizes."},"level":{"it":"Base","en":"Basics"},"categories":["frontend"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('css-intermediate','css',5,'css-base','published','{"title":{"it":"CSS intermedio","en":"Intermediate CSS"},"short":{"it":"CSS intermedio","en":"CSS Intermediate"},"desc":{"it":"Selettori avanzati, stati, tipografia, overflow, menu e bottoni, proprietà logiche, stile dei moduli, immagini e filtri.","en":"Advanced selectors, states, typography, overflow, menus and buttons, logical properties, form styling, images and filters."},"level":{"it":"Intermedio","en":"Intermediate"},"categories":["frontend"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('css-advanced','css',6,'css-intermediate','published','{"title":{"it":"CSS avanzato","en":"Advanced CSS"},"short":{"it":"CSS avanzato","en":"Advanced CSS"},"desc":{"it":"Impaginazioni moderne: flexbox, grid e aree, responsive, variabili, animazioni, :has() e container query, livelli a cascata e colori moderni.","en":"Modern layouts: flexbox, grid and areas, responsive design, variables, animations, :has() and container queries, cascade layers and modern colours."},"level":{"it":"Avanzato","en":"Advanced"},"categories":["frontend"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('css-animations','css',7,'css-intermediate','published','{"title":{"it":"Animazioni con CSS","en":"CSS Animations"},"short":{"it":"Animazioni","en":"Animations"},"desc":{"it":"Transizioni, trasformazioni e 3D, keyframes, tempi, entrate e uscite, animazioni legate allo scorrimento, transizioni di vista e animazioni rispettose.","en":"Transitions, transforms and 3D, keyframes, timing, entry and exit, scroll-driven animations, view transitions and respectful animation."},"level":{"it":"Avanzato","en":"Advanced"},"categories":["frontend"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('scss','scss',8,'css-intermediate','published','{"title":{"it":"SCSS","en":"SCSS"},"short":{"it":"SCSS","en":"SCSS"},"desc":{"it":"CSS con i superpoteri: variabili, annidamento, mixin e `@content`, funzioni, moduli e `@forward`, condizioni e cicli.","en":"CSS with superpowers: variables, nesting, mixins and `@content`, functions, modules and `@forward`, conditions and loops."},"level":{"it":"Preprocessori","en":"Preprocessors"},"categories":["frontend"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('sass','sass',9,'scss','published','{"title":{"it":"Sass (sintassi indentata)","en":"Sass (indented syntax)"},"short":{"it":"Sass","en":"Sass"},"desc":{"it":"La sintassi originale di Sass: niente graffe né punti e virgola, conta il rientro.","en":"The original Sass syntax: no braces or semicolons, indentation is what counts."},"level":{"it":"Preprocessori","en":"Preprocessors"},"categories":["frontend"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('savcomponents-base','savcomponents',10,'css-base','published','{"title":{"it":"SavComponents base","en":"SavComponents Basics"},"short":{"it":"SavComponents base","en":"SavComponents Basics"},"desc":{"it":"Componenti web pronti da usare come normali tag HTML, senza framework né build: installazione, pulsanti e badge, card e griglie, avvisi e toast, campi di form che funzionano con i form nativi, tag e avatar, liste e sezioni a scomparsa, codici e password.","en":"Ready-made web components used as plain HTML tags, with no framework and no build step: installation, buttons and badges, cards and grids, alerts and toasts, form fields that work with native forms, tags and avatars, lists and collapsible sections, codes and passwords."},"level":{"it":"Base","en":"Basics"},"categories":["frontend","design"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('savcomponents-intermediate','savcomponents',11,'savcomponents-base','published','{"title":{"it":"SavComponents intermedio","en":"Intermediate SavComponents"},"short":{"it":"SavComponents intermedio","en":"Intermediate SavComponents"},"desc":{"it":"Dai componenti all’interfaccia completa: modalità chiara e scura, i cinque stili, token e temi su misura, dialoghi e drawer, navigazione, eventi e validazione da JavaScript, tabelle, grafici e codice, icone e integrazione nei framework, menu laterali e telefoni.","en":"From components to a complete interface: light and dark mode, the five styles, tokens and custom themes, dialogs and drawers, navigation, events and validation from JavaScript, tables, charts and code, icons and framework integration, side menus and phones."},"level":{"it":"Intermedio","en":"Intermediate"},"categories":["frontend","design"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('savcomponents-advanced','savcomponents',12,'savcomponents-intermediate','published','{"title":{"it":"SavComponents avanzato","en":"Advanced SavComponents"},"short":{"it":"SavComponents avanzato","en":"Advanced SavComponents"},"desc":{"it":"Spingere la libreria oltre le basi: stile profondo con ::part(), forme e Tilt su misura, dati dal vivo e ricerca dal server, grafici, trascinamento, framework e rendering sul server, ospitare, aggiornare e accessibilità.","en":"Taking the library beyond the basics: deep styling with ::part(), shapes and a custom Tilt, live data and server search, charts, drag and drop, frameworks and server rendering, hosting, upgrading and accessibility."},"level":{"it":"Avanzato","en":"Advanced"},"categories":["frontend","design"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('tailwind','tailwind',13,'css-base','published','{"title":{"it":"Tailwind CSS","en":"Tailwind CSS"},"short":{"it":"Tailwind","en":"Tailwind"},"desc":{"it":"Lo stile scritto con le classi di Tailwind v4: spazi, colori, flex e griglie, schermi diversi, stati, group e peer, valori e utilità su misura, container query e installazione.","en":"Styling with Tailwind v4 classes: spacing, colours, flex and grids, screen sizes, states, group and peer, custom values and utilities, container queries and installation."},"level":{"it":"Base","en":"Basics"},"categories":["frontend"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('bootstrap','bootstrap',14,'css-base','published','{"title":{"it":"Bootstrap","en":"Bootstrap"},"short":{"it":"Bootstrap","en":"Bootstrap"},"desc":{"it":"Uno dei framework CSS più diffusi, nella versione stabile 5.3: griglia a 12 colonne e breakpoint, classi di utilità, componenti come navbar, card, modali, accordion, offcanvas e form, il JavaScript di Bootstrap, helper di accessibilità, temi e personalizzazione.","en":"One of the most widespread CSS frameworks, in its stable 5.3 release: 12-column grid and breakpoints, utility classes, components such as navbars, cards, modals, accordions, offcanvas panels and forms, Bootstrap’s JavaScript, accessibility helpers, themes and customisation."},"level":{"it":"Base","en":"Basics"},"categories":["frontend","design"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('js-base','js',15,'html-base','published','{"title":{"it":"JavaScript base","en":"JavaScript Basics"},"short":{"it":"JS base","en":"JS Basics"},"desc":{"it":"Il linguaggio del web: variabili, condizioni, cicli, funzioni, array e oggetti, metodi di stringhe e numeri, ambito e riferimenti.","en":"The language of the web: variables, conditions, loops, functions, arrays and objects, string and number methods, scope and references."},"level":{"it":"Base","en":"Basics"},"categories":["frontend","backend"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('js-intermediate','js',16,'js-base','published','{"title":{"it":"JavaScript intermedio","en":"Intermediate JavaScript"},"short":{"it":"JS intermedio","en":"JS Intermediate"},"desc":{"it":"Fai reagire le pagine: DOM, eventi e delega, metodi degli array, Map e Set, ordinare e copiare, sintassi moderna, JSON e salvataggio dati.","en":"Make pages react: DOM, events and delegation, array methods, Map and Set, sorting and copying, modern syntax, JSON and saving data."},"level":{"it":"Intermedio","en":"Intermediate"},"categories":["frontend","backend"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('js-advanced','js',17,'js-intermediate','published','{"title":{"it":"JavaScript avanzato","en":"Advanced JavaScript"},"short":{"it":"JS avanzato","en":"JS Advanced"},"desc":{"it":"Promise, async/await, fetch, moduli, classi, closure e il ciclo degli eventi, prototipi e `this`, generatori, richieste annullabili.","en":"Promises, async/await, fetch, modules, classes, closures and the event loop, prototypes and `this`, generators, cancellable requests."},"level":{"it":"Avanzato","en":"Advanced"},"categories":["frontend","backend"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('ts','ts',18,'js-intermediate','published','{"title":{"it":"TypeScript","en":"TypeScript"},"short":{"it":"TypeScript","en":"TypeScript"},"desc":{"it":"JavaScript con i tipi: errori trovati prima di eseguire, interfacce, unioni e generici, tipi calcolati e TypeScript con Node.","en":"JavaScript with types: errors found before running, interfaces, unions and generics, computed types and TypeScript with Node."},"level":{"it":"Intermedio","en":"Intermediate"},"categories":["frontend","backend"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('angular-base','angular',19,'ts','published','{"title":{"it":"Angular base","en":"Angular Basics"},"short":{"it":"Angular base","en":"Angular Basics"},"desc":{"it":"Componenti, template, binding, eventi, `@if` e `@for`, signal, servizi, classi dinamiche, pipe ed effect: le basi del framework di Google.","en":"Components, templates, bindings, events, `@if` and `@for`, signals, services, dynamic classes, pipes and effects: the basics of Google’s framework."},"level":{"it":"Base","en":"Basics"},"categories":["frontend"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('angular-intermediate','angular',20,'angular-base','published','{"title":{"it":"Angular intermedio","en":"Intermediate Angular"},"short":{"it":"Angular intermedio","en":"Angular Intermediate"},"desc":{"it":"Componenti che si parlano, rotte e caricamento pigro, moduli reattivi e Signal Forms, RxJS e resource, guardie per un’app completa.","en":"Components that talk, routes and lazy loading, reactive forms and Signal Forms, RxJS and resources, guards for a complete app."},"level":{"it":"Intermedio","en":"Intermediate"},"categories":["frontend"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('vue-base','vue',21,'js-base','published','{"title":{"it":"Vue base","en":"Vue Basics"},"short":{"it":"Vue base","en":"Vue Basics"},"desc":{"it":"Componenti in un file, dati reattivi con `ref`, direttive, eventi e liste, classi dinamiche, slot e `v-model` sui componenti: interfacce vive con poco codice.","en":"Single-file components, reactive data with `ref`, directives, events and lists, dynamic classes, slots and `v-model` on components: live interfaces with little code."},"level":{"it":"Base","en":"Basics"},"categories":["frontend"]}');
