INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('react-base','react',23,'js-base','published','{"title":{"it":"React base","en":"React Basics"},"short":{"it":"React base","en":"React Basics"},"desc":{"it":"La libreria più usata per le interfacce: componenti e JSX, props, stato con `useState` e aggiornamenti immutabili, eventi, liste, stato condiviso e ref.","en":"The most used library for interfaces: components and JSX, props, state with `useState` and immutable updates, events, lists, shared state and refs."},"level":{"it":"Base","en":"Basics"},"categories":["frontend"]}');
