INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('nextjs','next',25,'react-intermediate','published','{"title":{"it":"Next.js","en":"Next.js"},"short":{"it":"Next.js","en":"Next.js"},"desc":{"it":"Il framework React per siti e app completi: rotte da cartelle, componenti server e client, dati e cache (anche con `\\"use cache\\"`), route handler, server action, errori, proxy e pubblicazione.","en":"The React framework for complete sites and apps: folder-based routes, server and client components, data and caching (including `\\"use cache\\"`), route handlers, server actions, errors, proxy and deployment."},"level":{"it":"Avanzato","en":"Advanced"},"categories":["frontend","backend"]}');
