INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('python-base','python',30,NULL,'published','{"title":{"it":"Python base","en":"Python Basics"},"short":{"it":"Python base","en":"Python Basics"},"desc":{"it":"Il linguaggio più amato per iniziare: variabili, condizioni, cicli, liste e funzioni, stringhe, input e tipi, tuple e insiemi, funzioni integrate.","en":"The best-loved language to start with: variables, conditions, loops, lists and functions, strings, input and types, tuples and sets, built-in functions."},"level":{"it":"Base","en":"Basics"},"categories":["backend","data"]}');
