INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('sql-base','sql',37,NULL,'published','{"title":{"it":"SQL base","en":"SQL Basics"},"short":{"it":"SQL base","en":"SQL Basics"},"desc":{"it":"Parlare con i database: tabelle, `SELECT`, filtri, ordinamento, inserimenti e modifiche, `NULL` e `CASE`, funzioni e `ALTER TABLE`.","en":"Talking to databases: tables, `SELECT`, filters, sorting, inserts and updates, `NULL` and `CASE`, functions and `ALTER TABLE`."},"level":{"it":"Base","en":"Basics"},"categories":["data","backend"]}');
