INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('mysql','mysql',40,'sql-base','published','{"title":{"it":"MySQL","en":"MySQL"},"short":{"it":"MySQL","en":"MySQL"},"desc":{"it":"Uno dei database più diffusi sul web: client, InnoDB, `utf8mb4`, upsert, colonne JSON, utenti e permessi, `EXPLAIN ANALYZE`, backup e replica, versioni LTS.","en":"One of the most widely used databases on the web: client, InnoDB, `utf8mb4`, upserts, JSON columns, users and privileges, `EXPLAIN ANALYZE`, backups and replication, LTS versions."},"level":{"it":"Intermedio","en":"Intermediate"},"categories":["data","backend"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('mariadb','mariadb',41,'mysql','published','{"title":{"it":"MariaDB","en":"MariaDB"},"short":{"it":"MariaDB","en":"MariaDB"},"desc":{"it":"Il fork libero di MySQL: compatibilità, `RETURNING`, sequenze, tabelle con la storia dei dati, motori e cluster Galera, ricerca vettoriale, tipi propri e versioni.","en":"The open fork of MySQL: compatibility, `RETURNING`, sequences, tables that keep data history, engines and Galera clusters, vector search, its own types and versions."},"level":{"it":"Intermedio","en":"Intermediate"},"categories":["data","backend"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('postgresql','postgresql',42,'sql-base','published','{"title":{"it":"PostgreSQL","en":"PostgreSQL"},"short":{"it":"PostgreSQL","en":"PostgreSQL"},"desc":{"it":"Il database open source più avanzato: `psql`, tipi ricchi, upsert con `ON CONFLICT`, JSONB, ruoli ed `EXPLAIN`, PL/pgSQL e trigger, MVCC e `VACUUM`, ricerca full-text, pgvector e PostGIS.","en":"The most advanced open source database: `psql`, rich types, upserts with `ON CONFLICT`, JSONB, roles and `EXPLAIN`, PL/pgSQL and triggers, MVCC and `VACUUM`, full-text search, pgvector and PostGIS."},"level":{"it":"Intermedio","en":"Intermediate"},"categories":["data","backend"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('sqlite','sqlite',43,'sql-base','published','{"title":{"it":"SQLite","en":"SQLite"},"short":{"it":"SQLite","en":"SQLite"},"desc":{"it":"Il database in un file, dentro telefoni, browser e app: shell `sqlite3`, tipi flessibili e tabelle `STRICT`, `PRAGMA`, date, uso da Python, upsert, JSON e ricerca full-text FTS5.","en":"The database in a file, inside phones, browsers and apps: the `sqlite3` shell, flexible types and `STRICT` tables, `PRAGMA`, dates, use from Python, upserts, JSON and FTS5 full-text search."},"level":{"it":"Intermedio","en":"Intermediate"},"categories":["data","mobile","desktop"]}');
