INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('ai-base','ai',59,NULL,'published','{"title":{"it":"Fondamenti di AI","en":"AI Fundamentals"},"short":{"it":"AI base","en":"AI Basics"},"desc":{"it":"Che cos’è davvero l’intelligenza artificiale: machine learning, deep learning, AI generativa, dati, addestramento, modelli linguistici e loro limiti, tipi di apprendimento, AI multimodale e un po’ di storia.","en":"What artificial intelligence really is: machine learning, deep learning, generative AI, data, training, language models and their limits, kinds of learning, multimodal AI and a bit of history."},"level":{"it":"Base","en":"Basics"},"categories":["ai"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('llm-base','llm',60,'ai-base','published','{"title":{"it":"LLM: come funzionano","en":"LLMs: how they work"},"short":{"it":"LLM","en":"LLMs"},"desc":{"it":"Che cosa c’è dentro un modello linguistico: token, previsione della parola successiva, transformer e attenzione, addestramento, finestra di contesto, temperatura e allucinazioni, modelli che ragionano e come scegliere un modello.","en":"What is inside a language model: tokens, next-token prediction, transformers and attention, training, context window, temperature and hallucinations, reasoning models and how to choose a model."},"level":{"it":"Base","en":"Basics"},"categories":["ai"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('prompt-base','prompt',61,NULL,'published','{"title":{"it":"Prompt engineering base","en":"Prompt Engineering Basics"},"short":{"it":"Prompt base","en":"Prompt Basics"},"desc":{"it":"Scrivere richieste che funzionano: chiarezza, contesto, ruolo, esempi, formato della risposta, miglioramento passo per passo, ricette per i compiti comuni, verifiche e domande neutre.","en":"Writing requests that work: clarity, context, role, examples, answer format, step-by-step improvement, recipes for common tasks, checks and neutral questions."},"level":{"it":"Base","en":"Basics"},"categories":["ai"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('ai-ethics','ai',62,'ai-base','published','{"title":{"it":"AI responsabile e privacy","en":"Responsible AI and Privacy"},"short":{"it":"AI responsabile","en":"Responsible AI"},"desc":{"it":"Usare l’AI senza fare danni: bias ed equità, dati personali, diritto d’autore, AI Act europeo, buone abitudini, etichette sui contenuti generati, decisioni automatiche e diritti, impatto su ambiente e lavoro.","en":"Using AI without causing harm: bias and fairness, personal data, copyright, the EU AI Act, good habits, labels on generated content, automated decisions and rights, impact on environment and work."},"level":{"it":"Base","en":"Basics"},"categories":["ai"]}');
