INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('web-security','security',109,NULL,'published','{"title":{"it":"Sicurezza web (OWASP)","en":"Web Security (OWASP)"},"short":{"it":"Sicurezza web","en":"Web Security"},"desc":{"it":"Le vulnerabilità più comuni delle applicazioni web secondo la OWASP Top 10 2025 e come evitarle: injection, XSS, password, passkey e sessioni, controllo degli accessi, CSRF, CORS e intestazioni di sicurezza, crittografia e segreti.","en":"The most common web application vulnerabilities according to the OWASP Top 10 2025 and how to avoid them: injection, XSS, passwords, passkeys and sessions, access control, CSRF, CORS and security headers, cryptography and secrets."},"level":{"it":"Intermedio","en":"Intermediate"},"categories":["security"]}');
