INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('powerbi','powerbi',114,'excel','published','{"title":{"it":"Power BI","en":"Power BI"},"short":{"it":"Power BI","en":"Power BI"},"desc":{"it":"Dai dati ai cruscotti: Power Query, modello dati e relazioni, misure DAX, variabili e iteratori, report interattivi, intelligenza temporale e RLS, il servizio, Fabric e Copilot.","en":"From data to dashboards: Power Query, data model and relationships, DAX measures, variables and iterators, interactive reports, time intelligence and RLS, the service, Fabric and Copilot."},"level":{"it":"Base","en":"Basics"},"categories":["productivity","data"]}');
INSERT INTO `fc_courses` (`id`,`family`,`sort`,`after_id`,`status`,`data`) VALUES ('ux-base','ux',115,NULL,'published','{"title":{"it":"UX: le basi","en":"UX Basics"},"short":{"it":"UX base","en":"UX Basics"},"desc":{"it":"Che cos’è la user experience: conoscere gli utenti e i loro bisogni, il processo di design, le euristiche di usabilità e i primi test, il microcopy, affordance e modelli mentali, l’accessibilità fin dall’inizio.","en":"What user experience is: knowing users and their needs, the design process, usability heuristics and first tests, microcopy, affordances and mental models, accessibility from the start."},"level":{"it":"Base","en":"Basics"},"categories":["design"]}');
