INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-intermediate' AND slug = 'figure-time'),2,2,'{"it":"A che cosa serve `datetime` su `<time>`?","en":"What is `datetime` on `<time>` for?"}','[{"it":"Mostra un orologio nella pagina","en":"It shows a clock on the page"},{"it":"Imposta il fuso orario della pagina","en":"It sets the page’s time zone"},{"it":"Mette la data in grassetto","en":"It makes the date bold"},{"it":"Dà la data in un formato che i programmi capiscono","en":"It gives the date in a format programs understand"}]',3,'{"it":"Il testo visibile può essere «ieri» o «17 novembre».","en":"The visible text can be “yesterday” or “17 November”."}',NULL);
