INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-intermediate' AND slug = 'form-send'),3,2,'{"it":"Che cosa fa un `<button>` senza `type` dentro un modulo?","en":"What does a `<button>` with no `type` do inside a form?"}','[{"it":"Svuota il modulo","en":"It clears the form"},{"it":"Niente, finché non ha JavaScript","en":"Nothing, until it has JavaScript"},{"it":"Apre una nuova finestra","en":"It opens a new window"},{"it":"Invia il modulo","en":"It submits the form"}]',3,'{"it":"Il tipo predefinito è `submit`.","en":"The default type is `submit`."}',NULL);
