INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'semantic'),2,2,'{"it":"Quale tag è adatto a un post che ha senso anche da solo?","en":"Which tag suits a post that makes sense on its own?"}','[{"it":"<div>","en":"<div>"},{"it":"<article>","en":"<article>"},{"it":"<aside>","en":"<aside>"},{"it":"<nav>","en":"<nav>"}]',1,'{"it":"`<article>` è un contenuto autonomo e riutilizzabile.","en":"`<article>` is self-contained, reusable content."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'semantic'),3,2,'{"it":"Quale tag contiene i collegamenti di navigazione principali?","en":"Which tag holds the main navigation links?"}','[{"it":"<menu-bar>","en":"<menu-bar>"},{"it":"<links>","en":"<links>"},{"it":"<nav>","en":"<nav>"},{"it":"<header>","en":"<header>"}]',2,'{"it":"`<nav>` identifica i blocchi di navigazione.","en":"`<nav>` identifies navigation blocks."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'rich-forms'),1,2,'{"it":"Perché due `radio` si escludano a vicenda devono avere…","en":"For two `radio` inputs to exclude one another they must have…"}','[{"it":"Lo stesso `id`","en":"The same `id`"},{"it":"Lo stesso `name`","en":"The same `name`"},{"it":"Lo stesso `value`","en":"The same `value`"},{"it":"La stessa `label`","en":"The same `label`"}]',1,'{"it":"Lo stesso `name` li rende un unico gruppo.","en":"The same `name` makes them a single group."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'rich-forms'),2,2,'{"it":"Quale attributo valida un campo con un’espressione regolare?","en":"Which attribute validates a field with a regular expression?"}','[{"it":"regex","en":"regex"},{"it":"pattern","en":"pattern"},{"it":"match","en":"match"},{"it":"validate","en":"validate"}]',1,'{"it":"`pattern` contiene l’espressione che il valore deve rispettare.","en":"`pattern` holds the expression the value must match."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'rich-forms'),3,2,'{"it":"Quale coppia dà un titolo a un gruppo di campi?","en":"Which pair gives a title to a group of fields?"}','[{"it":"<group> <title>","en":"<group> <title>"},{"it":"<fieldset> <legend>","en":"<fieldset> <legend>"},{"it":"<form> <label>","en":"<form> <label>"},{"it":"<section> <h6>","en":"<section> <h6>"}]',1,'{"it":"`<legend>` è la didascalia del `<fieldset>`.","en":"`<legend>` is the caption of the `<fieldset>`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'media'),1,2,'{"it":"Quale attributo rimanda il caricamento di un’immagine?","en":"Which attribute delays the loading of an image?"}','[{"it":"defer","en":"defer"},{"it":"async","en":"async"},{"it":"loading=\\"lazy\\"","en":"loading=\\"lazy\\""},{"it":"preload","en":"preload"}]',2,'{"it":"Il browser la scarica quando sta per entrare nello schermo.","en":"The browser downloads it when it is about to enter the screen."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'media'),2,2,'{"it":"Perché indicare `width` e `height` su `<img>`?","en":"Why set `width` and `height` on `<img>`?"}','[{"it":"Per comprimere il file e scaricarlo più in fretta","en":"To compress the file and download it faster"},{"it":"Per riservare lo spazio ed evitare salti","en":"To reserve the space and avoid jumps"},{"it":"Per il SEO","en":"For SEO"},{"it":"Sono obbligatori","en":"They are mandatory"}]',1,'{"it":"Il browser conosce le proporzioni prima di scaricare il file.","en":"The browser knows the proportions before downloading the file."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'media'),3,2,'{"it":"Quale tag aggiunge i sottotitoli a un video?","en":"Which tag adds subtitles to a video?"}','[{"it":"<source>","en":"<source>"},{"it":"<caption>","en":"<caption>"},{"it":"<track>","en":"<track>"},{"it":"<subtitle>","en":"<subtitle>"}]',2,'{"it":"`<track kind=\\"captions\\">` collega un file di sottotitoli.","en":"`<track kind=\\"captions\\">` links a subtitle file."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'a11y'),1,2,'{"it":"Quale elemento funziona già da tastiera?","en":"Which element already works with the keyboard?"}','[{"it":"<div onclick>","en":"<div onclick>"},{"it":"<span>","en":"<span>"},{"it":"<button>","en":"<button>"},{"it":"<p>","en":"<p>"}]',2,'{"it":"`<button>` riceve il focus e si attiva con Invio e Spazio.","en":"`<button>` gets focus and activates with Enter and Space."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'a11y'),2,2,'{"it":"Come dai un nome a un pulsante con solo un’icona?","en":"How do you name a button that only has an icon?"}','[{"it":"title-text","en":"title-text"},{"it":"aria-label","en":"aria-label"},{"it":"name","en":"name"},{"it":"alt","en":"alt"}]',1,'{"it":"`aria-label` è il nome che legge lo screen reader.","en":"`aria-label` is the name the screen reader reads."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'a11y'),3,2,'{"it":"Qual è la prima regola di ARIA?","en":"What is the first rule of ARIA?"}','[{"it":"Usarla ovunque","en":"Use it everywhere"},{"it":"Preferire i tag HTML adatti","en":"Prefer suitable HTML tags"},{"it":"Metterla solo nei `div`","en":"Only put it on `div`s"},{"it":"Sostituisce le `label`","en":"It replaces `label`s"}]',1,'{"it":"L’HTML nativo porta con sé ruolo, stato e tastiera.","en":"Native HTML brings role, state and keyboard along."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'meta'),1,2,'{"it":"Quale meta è indispensabile per i telefoni?","en":"Which meta is essential for phones?"}','[{"it":"charset","en":"charset"},{"it":"viewport","en":"viewport"},{"it":"keywords","en":"keywords"},{"it":"author","en":"author"}]',1,'{"it":"Senza `viewport` il telefono mostra la pagina come su un computer, rimpicciolita.","en":"Without `viewport` the phone shows the page as on a computer, shrunk."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'meta'),2,2,'{"it":"Quali tag creano una sezione apribile senza JavaScript?","en":"Which tags create a collapsible section with no JavaScript?"}','[{"it":"<open> <close>","en":"<open> <close>"},{"it":"<details> <summary>","en":"<details> <summary>"},{"it":"<toggle> <item>","en":"<toggle> <item>"},{"it":"<section> <h2>","en":"<section> <h2>"}]',1,'{"it":"`<summary>` è la riga sempre visibile su cui si tocca.","en":"`<summary>` is the always-visible line you tap."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'meta'),3,2,'{"it":"Da dove vengono le anteprime dei link condivisi?","en":"Where do the previews of shared links come from?"}','[{"it":"Dai meta Open Graph","en":"From Open Graph metas"},{"it":"Da `<title>` soltanto","en":"From `<title>` alone"},{"it":"Dal CSS","en":"From CSS"},{"it":"Da `<footer>`","en":"From `<footer>`"}]',0,'{"it":"Le app leggono `og:title`, `og:description` e `og:image`.","en":"Apps read `og:title`, `og:description` and `og:image`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'data-attrs'),1,3,'{"it":"Quale attributo è valido?","en":"Which attribute is valid?"}','[{"it":"data-id","en":"data-id"},{"it":"id-data","en":"id-data"},{"it":"my:data","en":"my:data"},{"it":"data_","en":"data_"}]',0,'{"it":"Inizia sempre con `data-`.","en":"It always starts with `data-`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'data-attrs'),2,3,'{"it":"Il contenuto di `<template>` si vede subito?","en":"Is the content of `<template>` shown at once?"}','[{"it":"Sì","en":"Yes"},{"it":"No","en":"No"},{"it":"Solo su telefono","en":"Only on phones"},{"it":"Solo in grassetto","en":"Only in bold"}]',1,'{"it":"Resta nascosto finché uno script non lo copia.","en":"It stays hidden until a script copies it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'data-attrs'),3,3,'{"it":"A che cosa servono i `data-*`?","en":"What are `data-*` for?"}','[{"it":"A salvare dati su un elemento","en":"To keep data on an element"},{"it":"A collegare un database","en":"To connect a database"},{"it":"A cambiare font","en":"To change fonts"},{"it":"A inviare email","en":"To send emails"}]',0,'{"it":"Sono comodi per passare dati dall’HTML al JavaScript.","en":"They are handy for passing data from HTML to JavaScript."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'seo'),1,3,'{"it":"Che cosa decide `og:image`?","en":"What does `og:image` decide?"}','[{"it":"L’immagine quando condividi","en":"The image when you share"},{"it":"Il logo del browser","en":"The browser logo"},{"it":"La favicon","en":"The favicon"},{"it":"Lo sfondo","en":"The background"}]',0,'{"it":"`og` sta per Open Graph.","en":"`og` stands for Open Graph."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'seo'),2,3,'{"it":"A che cosa serve `rel=\\"canonical\\"`?","en":"What is `rel=\\"canonical\\"` for?"}','[{"it":"Indica l’indirizzo ufficiale","en":"It gives the official address"},{"it":"Blocca i motori","en":"It blocks engines"},{"it":"Apre una scheda","en":"It opens a tab"},{"it":"Carica il CSS","en":"It loads CSS"}]',0,'{"it":"Evita che più URL contino come pagine doppie.","en":"It stops several URLs counting as duplicate pages."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'seo'),3,3,'{"it":"Dove vanno questi tag?","en":"Where do these tags go?"}','[{"it":"<head>","en":"<head>"},{"it":"<body>","en":"<body>"},{"it":"<footer>","en":"<footer>"},{"it":"<main>","en":"<main>"}]',0,'{"it":"Sono metadati: stanno in `head`.","en":"They are metadata: they live in `head`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'popover-dialog'),1,3,'{"it":"Quale attributo collega un pulsante al suo popover?","en":"Which attribute links a button to its popover?"}','[{"it":"target","en":"target"},{"it":"aria-controls","en":"aria-controls"},{"it":"popovertarget","en":"popovertarget"},{"it":"for","en":"for"}]',2,'{"it":"Il valore è l’`id` dell’elemento con `popover`.","en":"Its value is the `id` of the element with `popover`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'popover-dialog'),2,3,'{"it":"Che cosa fa un dialogo modale al resto della pagina?","en":"What does a modal dialog do to the rest of the page?"}','[{"it":"La ricarica da capo","en":"It reloads it from scratch"},{"it":"La rende inattiva finché non si chiude","en":"It makes it inert until it closes"},{"it":"La manda in stampa","en":"It sends it to the printer"},{"it":"Niente: si può ancora cliccare tutto","en":"Nothing: everything can still be clicked"}]',1,'{"it":"Così l’utente risponde prima di andare avanti.","en":"So the user answers before moving on."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'popover-dialog'),3,3,'{"it":"Quale valore di `command` chiude un `<dialog>`?","en":"Which `command` value closes a `<dialog>`?"}','[{"it":"open","en":"open"},{"it":"hide","en":"hide"},{"it":"show-modal","en":"show-modal"},{"it":"close","en":"close"}]',3,'{"it":"`show-modal` lo apre, `close` lo chiude.","en":"`show-modal` opens it, `close` closes it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'loading'),1,3,'{"it":"Quando parte uno script con `defer`?","en":"When does a script with `defer` run?"}','[{"it":"Subito, fermando la pagina","en":"At once, stopping the page"},{"it":"Solo quando l’utente clicca","en":"Only when the user clicks"},{"it":"Dopo la lettura dell’HTML, in ordine","en":"After the HTML is read, in order"},{"it":"Mai, se la pagina è lunga","en":"Never, if the page is long"}]',2,'{"it":"Si scarica intanto, ma aspetta l’HTML.","en":"It downloads meanwhile, but waits for the HTML."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'loading'),2,3,'{"it":"Quale script può usare `async` senza problemi?","en":"Which script can use `async` safely?"}','[{"it":"Uno script di statistiche indipendente","en":"An independent analytics script"},{"it":"Uno che usa le funzioni di un altro script","en":"One that uses another script’s functions"},{"it":"Lo script principale che costruisce la pagina","en":"The main script that builds the page"},{"it":"Uno che deve partire per ultimo","en":"One that must run last"}]',0,'{"it":"`async` non garantisce l’ordine.","en":"`async` does not guarantee order."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'loading'),3,3,'{"it":"Come si carica di base uno script `type=\\"module\\"`?","en":"How is a `type=\\"module\\"` script loaded by default?"}','[{"it":"Bloccando la pagina","en":"Blocking the page"},{"it":"Solo in Chrome","en":"Only in Chrome"},{"it":"Solo dopo un clic","en":"Only after a click"},{"it":"Differito, come con `defer`","en":"Deferred, as with `defer`"}]',3,'{"it":"Non serve aggiungere `defer`.","en":"There is no need to add `defer`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'srcset-sizes'),1,3,'{"it":"Che cosa dice `800w` in `srcset`?","en":"What does `800w` say in `srcset`?"}','[{"it":"Che l’immagine si mostra a 800px","en":"That the image is shown at 800px"},{"it":"Che il file è largo 800 pixel","en":"That the file is 800 pixels wide"},{"it":"Che il file pesa 800 KB","en":"That the file weighs 800 KB"},{"it":"Che va bene per schermi da 800px in su","en":"That it suits screens from 800px up"}]',1,'{"it":"`w` descrive il file; la larghezza mostrata la dice `sizes`.","en":"`w` describes the file; the displayed width is given by `sizes`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'srcset-sizes'),2,3,'{"it":"Che cosa indica l’attributo `sizes`?","en":"What does the `sizes` attribute state?"}','[{"it":"Il peso di ogni file","en":"The weight of each file"},{"it":"I formati disponibili","en":"The available formats"},{"it":"Quanto sarà larga l’immagine sulla pagina","en":"How wide the image will be on the page"},{"it":"Quante immagini ci sono","en":"How many images there are"}]',2,'{"it":"Il browser lo sa prima ancora di applicare il CSS.","en":"The browser knows it even before applying the CSS."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-advanced' AND slug = 'srcset-sizes'),3,3,'{"it":"Quando conviene `<picture>` invece di `srcset`?","en":"When is `<picture>` better than `srcset`?"}','[{"it":"Per tutte le immagini piccole","en":"For all small images"},{"it":"Sempre, perché è più recente","en":"Always, because it is newer"},{"it":"Mai, perché è deprecato","en":"Never, because it is deprecated"},{"it":"Quando cambi inquadratura o formato","en":"When you change the crop or the format"}]',3,'{"it":"Per la sola dimensione bastano `srcset` e `sizes`.","en":"For size alone `srcset` and `sizes` are enough."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'selectors'),1,1,'{"it":"Quale selettore sceglie la classe `nota`?","en":"Which selector picks the class `nota`?"}','[{"it":"#nota","en":"#nota"},{"it":".nota","en":".nota"},{"it":"nota","en":"nota"},{"it":"*nota","en":"*nota"}]',1,'{"it":"Il punto indica la classe, il cancelletto l’id.","en":"The dot marks a class, the hash an id."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'selectors'),2,1,'{"it":"Che cosa sceglie `nav a`?","en":"What does `nav a` pick?"}','[{"it":"`nav` e tutti i link","en":"`nav` and all the links"},{"it":"I link dentro `nav`","en":"The links inside `nav`"},{"it":"Solo il primo link","en":"Only the first link"},{"it":"Nulla","en":"Nothing"}]',1,'{"it":"Lo spazio è il combinatore discendente.","en":"The space is the descendant combinator."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'selectors'),3,1,'{"it":"Che cos’è `:hover`?","en":"What is `:hover`?"}','[{"it":"Una pseudo-classe","en":"A pseudo-class"},{"it":"Una proprietà","en":"A property"},{"it":"Un id","en":"An id"},{"it":"Un tag","en":"A tag"}]',0,'{"it":"Le pseudo-classi indicano uno stato o una posizione.","en":"Pseudo-classes mark a state or a position."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'colors'),1,1,'{"it":"Quale proprietà cambia il colore del testo?","en":"Which property changes the text colour?"}','[{"it":"text-color","en":"text-color"},{"it":"font-color","en":"font-color"},{"it":"color","en":"color"},{"it":"foreground","en":"foreground"}]',2,'{"it":"Si chiama semplicemente `color`.","en":"It is simply called `color`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'colors'),2,1,'{"it":"Quanto vale `2rem` se la base è 16px?","en":"What is `2rem` when the base is 16px?"}','[{"it":"2px","en":"2px"},{"it":"16px","en":"16px"},{"it":"32px","en":"32px"},{"it":"200px","en":"200px"}]',2,'{"it":"`rem` moltiplica la dimensione di base: 2 × 16.","en":"`rem` multiplies the base size: 2 × 16."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'colors'),3,1,'{"it":"Perché `font-family` elenca più caratteri?","en":"Why does `font-family` list several fonts?"}','[{"it":"Li usa tutti insieme","en":"It uses them all together"},{"it":"Se il primo manca usa il successivo","en":"If the first is missing it uses the next"},{"it":"Per il grassetto","en":"For bold"},{"it":"È obbligatorio","en":"It is mandatory"}]',1,'{"it":"L’ultimo di solito è una famiglia generica come `serif`.","en":"The last one is usually a generic family such as `serif`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'box'),1,1,'{"it":"Quale strato è lo spazio interno?","en":"Which layer is the inner space?"}','[{"it":"margin","en":"margin"},{"it":"padding","en":"padding"},{"it":"border","en":"border"},{"it":"outline","en":"outline"}]',1,'{"it":"Il `padding` sta tra il contenuto e il bordo.","en":"`padding` sits between the content and the border."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'box'),2,1,'{"it":"Con `border-box`, una scatola `width: 300px` e `padding: 20px` è larga…","en":"With `border-box`, a box with `width: 300px` and `padding: 20px` is…"}','[{"it":"300px","en":"300px wide"},{"it":"320px","en":"320px wide"},{"it":"340px","en":"340px wide"},{"it":"260px","en":"260px wide"}]',0,'{"it":"Il padding sta dentro i 300px: resta meno spazio al contenuto.","en":"The padding fits within the 300px: less room remains for the content."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'box'),3,1,'{"it":"Che cosa fa `margin: 0 auto`?","en":"What does `margin: 0 auto` do?"}','[{"it":"Toglie il bordo","en":"Removes the border"},{"it":"Centra orizzontalmente un blocco","en":"Centres a block horizontally"},{"it":"Centra il testo","en":"Centres the text"},{"it":"Nasconde il blocco","en":"Hides the block"}]',1,'{"it":"I margini laterali automatici si dividono lo spazio libero.","en":"Automatic side margins share the free space."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'display'),1,1,'{"it":"Quale elemento è `inline` di natura?","en":"Which element is `inline` by default?"}','[{"it":"<div>","en":"<div>"},{"it":"<p>","en":"<p>"},{"it":"<a>","en":"<a>"},{"it":"<h1>","en":"<h1>"}]',2,'{"it":"`<a>` scorre nel testo senza andare a capo.","en":"`<a>` flows in the text without a line break."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'display'),2,1,'{"it":"Qual è la differenza tra `display: none` e `visibility: hidden`?","en":"What is the difference between `display: none` and `visibility: hidden`?"}','[{"it":"Nessuna","en":"None"},{"it":"Il primo toglie anche lo spazio","en":"The first removes the space too"},{"it":"Il secondo toglie lo spazio","en":"The second removes the space"},{"it":"Il primo è solo per il testo","en":"The first is only for text"}]',1,'{"it":"`visibility: hidden` lascia un buco della stessa misura.","en":"`visibility: hidden` leaves a hole of the same size."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'display'),3,1,'{"it":"Quale valore scorre nel testo e accetta `width`?","en":"Which value flows in the text and accepts `width`?"}','[{"it":"block","en":"block"},{"it":"inline","en":"inline"},{"it":"inline-block","en":"inline-block"},{"it":"flow","en":"flow"}]',2,'{"it":"È una via di mezzo tra `inline` e `block`.","en":"It is halfway between `inline` and `block`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'position'),1,1,'{"it":"Rispetto a cosa si posiziona un elemento `absolute`?","en":"What is an `absolute` element positioned against?"}','[{"it":"Sempre la pagina","en":"Always the page"},{"it":"Il primo antenato posizionato","en":"The nearest positioned ancestor"},{"it":"L’elemento precedente","en":"The previous element"},{"it":"Lo schermo","en":"The screen"}]',1,'{"it":"Per questo si mette `position: relative` sul contenitore.","en":"That is why you set `position: relative` on the container."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'position'),2,1,'{"it":"Quale valore resta fermo durante lo scorrimento della pagina?","en":"Which value stays still while the page scrolls?"}','[{"it":"static","en":"static"},{"it":"relative","en":"relative"},{"it":"fixed","en":"fixed"},{"it":"float","en":"float"}]',2,'{"it":"`fixed` si aggancia allo schermo.","en":"`fixed` is anchored to the screen."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'position'),3,1,'{"it":"Quale proprietà decide cosa sta sopra?","en":"Which property decides what is on top?"}','[{"it":"z-index","en":"z-index"},{"it":"layer","en":"layer"},{"it":"top","en":"top"},{"it":"order-top","en":"order-top"}]',0,'{"it":"Funziona sugli elementi posizionati e sui figli di flex e grid.","en":"It works on positioned elements and on flex and grid children."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'cascade'),1,2,'{"it":"Chi vince tra `.nota` e `#box` sullo stesso elemento?","en":"Which wins between `.nota` and `#box` on the same element?"}','[{"it":".nota","en":".nota"},{"it":"#box","en":"#box"},{"it":"L’ultima scritta","en":"The last one written"},{"it":"Nessuna","en":"Neither"}]',1,'{"it":"L’`id` ha una specificità più alta della classe.","en":"An `id` has higher specificity than a class."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'cascade'),2,2,'{"it":"Con la stessa specificità chi vince?","en":"With the same specificity, which wins?"}','[{"it":"La prima scritta","en":"The first written"},{"it":"L’ultima scritta","en":"The last written"},{"it":"La più corta","en":"The shortest"},{"it":"Nessuna","en":"Neither"}]',1,'{"it":"È il senso della parola «cascata».","en":"That is the meaning of the word “cascade”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'cascade'),3,2,'{"it":"Quale proprietà si eredita?","en":"Which property is inherited?"}','[{"it":"margin","en":"margin"},{"it":"border","en":"border"},{"it":"color","en":"color"},{"it":"padding","en":"padding"}]',2,'{"it":"Il colore del testo passa dai genitori ai figli.","en":"The text colour passes from parents to children."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'backgrounds'),1,2,'{"it":"Quale funzione crea una sfumatura?","en":"Which function creates a gradient?"}','[{"it":"linear-gradient()","en":"linear-gradient()"},{"it":"fade()","en":"fade()"},{"it":"blend()","en":"blend()"},{"it":"mix()","en":"mix()"}]',0,'{"it":"Esiste anche `radial-gradient()`.","en":"There is also `radial-gradient()`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'backgrounds'),2,2,'{"it":"Che cosa fa il terzo valore di `box-shadow: 0 4px 12px`?","en":"What does the third value of `box-shadow: 0 4px 12px` do?"}','[{"it":"La sfocatura","en":"The blur"},{"it":"Il colore","en":"The colour"},{"it":"Il raggio","en":"The radius"},{"it":"L’opacità","en":"The opacity"}]',0,'{"it":"Più è alto, più l’ombra è morbida.","en":"The higher it is, the softer the shadow."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'backgrounds'),3,2,'{"it":"Quale proprietà mette un’ombra al testo?","en":"Which property puts a shadow on text?"}','[{"it":"text-shadow","en":"text-shadow"},{"it":"font-shadow","en":"font-shadow"},{"it":"shadow","en":"shadow"},{"it":"box-shadow","en":"box-shadow"}]',0,'{"it":"`box-shadow` vale per la scatola.","en":"`box-shadow` is for the box."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'units'),1,2,'{"it":"`50%` di che cosa?","en":"`50%` of what?"}','[{"it":"Del contenitore","en":"Of the container"},{"it":"Dello schermo, sempre","en":"Of the screen, always"},{"it":"Del testo","en":"Of the text"},{"it":"Del file","en":"Of the file"}]',0,'{"it":"Le percentuali guardano al genitore.","en":"Percentages look at the parent."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'units'),2,2,'{"it":"Quanto vale `100vh`?","en":"What is `100vh`?"}','[{"it":"Tutta l’altezza dello schermo","en":"The full height of the screen"},{"it":"100 pixel","en":"100 pixels"},{"it":"La larghezza","en":"The width"},{"it":"Il doppio del testo","en":"Twice the text"}]',0,'{"it":"`vh` è l’1% dell’altezza della finestra.","en":"`vh` is 1% of the window height."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'units'),3,2,'{"it":"Da che cosa dipende `rem`?","en":"What does `rem` depend on?"}','[{"it":"Dalla radice del documento","en":"On the root of the document"},{"it":"Dal genitore","en":"On the parent"},{"it":"Dallo schermo","en":"On the screen"},{"it":"Da nulla","en":"On nothing"}]',0,'{"it":"`r` sta per root.","en":"`r` stands for root."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'attach'),1,2,'{"it":"Qual è il modo migliore per dare lo stile a un sito intero?","en":"What is the best way to style a whole site?"}','[{"it":"L’attributo `style` su ogni elemento","en":"The `style` attribute on every element"},{"it":"Un blocco `<style>` in ogni pagina","en":"A `<style>` block in every page"},{"it":"Un file esterno collegato con `<link>`","en":"An external file linked with `<link>`"},{"it":"Un’immagine con i colori","en":"An image with the colours"}]',2,'{"it":"Un file, tutte le pagine, una sola modifica.","en":"One file, every page, a single change."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'attach'),2,2,'{"it":"Che cosa dice `rel=\\"stylesheet\\"`?","en":"What does `rel=\\"stylesheet\\"` say?"}','[{"it":"Che il file è un’immagine","en":"That the file is an image"},{"it":"Che il file è un foglio di stile","en":"That the file is a stylesheet"},{"it":"Che il link si apre in una nuova scheda","en":"That the link opens in a new tab"},{"it":"Che la pagina è in italiano","en":"That the page is in Italian"}]',1,'{"it":"`rel` descrive la relazione con il file collegato.","en":"`rel` describes the relation with the linked file."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'attach'),3,2,'{"it":"Come si scrive un commento nel CSS?","en":"How do you write a comment in CSS?"}','[{"it":"// nota","en":"// nota"},{"it":"<!-- nota -->","en":"<!-- nota -->"},{"it":"# nota","en":"# nota"},{"it":"/* nota */","en":"/* nota */"}]',3,'{"it":"`<!-- -->` è il commento dell’HTML.","en":"`<!-- -->` is the HTML comment."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'sizes'),1,2,'{"it":"Che cosa fa `max-width: 960px`?","en":"What does `max-width: 960px` do?"}','[{"it":"La scatola è sempre larga 960px","en":"The box is always 960px wide"},{"it":"Al massimo 960px, e si stringe se c’è meno spazio","en":"At most 960px, and it shrinks if there is less room"},{"it":"Almeno 960px, anche sui telefoni","en":"At least 960px, even on phones"},{"it":"La scatola è alta 960px","en":"The box is 960px tall"}]',1,'{"it":"È un tetto, non una misura fissa.","en":"It is a ceiling, not a fixed size."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'sizes'),2,2,'{"it":"Con `width: 320px` e `aspect-ratio: 16 / 9`, quanto è alta la scatola?","en":"With `width: 320px` and `aspect-ratio: 16 / 9`, how tall is the box?"}','[{"it":"320px","en":"320px"},{"it":"90px","en":"90px"},{"it":"160px","en":"160px"},{"it":"180px","en":"180px"}]',3,'{"it":"320 ÷ 16 × 9 = 180.","en":"320 ÷ 16 × 9 = 180."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'sizes'),3,2,'{"it":"Perché evitare un `height` fisso su una scatola con del testo?","en":"Why avoid a fixed `height` on a box with text?"}','[{"it":"Se il testo cresce, esce dalla scatola","en":"If the text grows, it spills out of the box"},{"it":"Perché `height` è vietato","en":"Because `height` is forbidden"},{"it":"Perché rallenta la pagina","en":"Because it slows the page down"},{"it":"Perché cambia il colore del testo","en":"Because it changes the text colour"}]',0,'{"it":"Meglio `min-height`: un minimo, senza tetto.","en":"Better `min-height`: a minimum, with no ceiling."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'combinators'),1,1,'{"it":"Che cosa sceglie `ul > li`?","en":"What does `ul > li` pick?"}','[{"it":"I figli diretti","en":"The direct children"},{"it":"Tutti i discendenti","en":"All descendants"},{"it":"Il primo","en":"The first one"},{"it":"Nulla","en":"Nothing"}]',0,'{"it":"Il `>` si ferma al primo livello.","en":"The `>` stops at the first level."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'combinators'),2,1,'{"it":"Che cosa sceglie `h1 + p`?","en":"What does `h1 + p` pick?"}','[{"it":"Il `p` subito dopo `h1`","en":"The `p` right after `h1`"},{"it":"Tutti i `p`","en":"All `p`s"},{"it":"`h1` e `p`","en":"`h1` and `p`"},{"it":"I `p` dentro `h1`","en":"The `p`s inside `h1`"}]',0,'{"it":"`+` è il fratello adiacente.","en":"`+` is the adjacent sibling."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'combinators'),3,1,'{"it":"Che cosa significa `[href$=\\".pdf\\"]`?","en":"What does `[href$=\\".pdf\\"]` mean?"}','[{"it":"Finisce con .pdf","en":"Ends with .pdf"},{"it":"Inizia con .pdf","en":"Starts with .pdf"},{"it":"Contiene pdf","en":"Contains pdf"},{"it":"Costa pdf","en":"Costs pdf"}]',0,'{"it":"Il dollaro indica la fine.","en":"The dollar marks the end."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'states'),1,1,'{"it":"Quale pseudo-classe vale mentre premi?","en":"Which pseudo-class applies while pressing?"}','[{"it":":active","en":":active"},{"it":":press","en":":press"},{"it":":hover","en":":hover"},{"it":":down","en":":down"}]',0,'{"it":"`:hover` è il passaggio del mouse.","en":"`:hover` is the mouse passing over."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'states'),2,1,'{"it":"Perché `:focus-visible` è utile?","en":"Why is `:focus-visible` useful?"}','[{"it":"Mostra il focus a chi usa la tastiera","en":"It shows focus to keyboard users"},{"it":"Nasconde il mouse","en":"It hides the mouse"},{"it":"Cambia il font","en":"It changes the font"},{"it":"Blocca il click","en":"It blocks the click"}]',0,'{"it":"Non disturba chi clicca col mouse.","en":"It does not bother those clicking with a mouse."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'states'),3,1,'{"it":"Quando vale `input:invalid`?","en":"When does `input:invalid` apply?"}','[{"it":"Il valore non rispetta le regole","en":"The value breaks the rules"},{"it":"Il campo è vuoto sempre","en":"The field is always empty"},{"it":"Il campo è nascosto","en":"The field is hidden"},{"it":"Mai","en":"Never"}]',0,'{"it":"Dipende da `required`, `type`, `pattern`.","en":"It depends on `required`, `type`, `pattern`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'typography'),1,1,'{"it":"Quale proprietà cambia lo spazio tra le righe?","en":"Which property changes the space between lines?"}','[{"it":"line-height","en":"line-height"},{"it":"row-gap","en":"row-gap"},{"it":"letter-spacing","en":"letter-spacing"},{"it":"margin","en":"margin"}]',0,'{"it":"Un valore tra 1.4 e 1.7 è comodo.","en":"A value from 1.4 to 1.7 is comfortable."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'typography'),2,1,'{"it":"Che cos’è `65ch`?","en":"What is `65ch`?"}','[{"it":"Circa 65 caratteri","en":"About 65 characters"},{"it":"65 pixel","en":"65 pixels"},{"it":"65% dello schermo","en":"65% of the screen"},{"it":"65 righe","en":"65 lines"}]',0,'{"it":"Si basa sulla larghezza dello zero.","en":"It is based on the width of the zero."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'typography'),3,1,'{"it":"Che cosa carica un font personale?","en":"What loads a custom font?"}','[{"it":"@font-face","en":"@font-face"},{"it":"@import-font","en":"@import-font"},{"it":"font-load","en":"font-load"},{"it":"@text","en":"@text"}]',0,'{"it":"Si indicano nome e file.","en":"You give a name and a file."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'overflow'),1,1,'{"it":"Quale valore mette le barre solo se servono?","en":"Which value adds scrollbars only if needed?"}','[{"it":"auto","en":"auto"},{"it":"scroll","en":"scroll"},{"it":"hidden","en":"hidden"},{"it":"bars","en":"bars"}]',0,'{"it":"`scroll` le mostra sempre.","en":"`scroll` always shows them."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'overflow'),2,1,'{"it":"`z-index` funziona su un normale elemento `static`, fuori da flex e grid?","en":"Does `z-index` work on a plain `static` element, outside flex and grid?"}','[{"it":"No","en":"No"},{"it":"Sì","en":"Yes"},{"it":"Solo sui link","en":"Only on links"},{"it":"Solo su `body`","en":"Only on `body`"}]',0,'{"it":"Serve un elemento posizionato, oppure un figlio di un contenitore flex o grid.","en":"It needs a positioned element, or a child of a flex or grid container."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'overflow'),3,1,'{"it":"Che cosa aggiunge `text-overflow: ellipsis`?","en":"What does `text-overflow: ellipsis` add?"}','[{"it":"I puntini","en":"An ellipsis"},{"it":"Una barra","en":"A scrollbar"},{"it":"Un’ombra","en":"A shadow"},{"it":"Un link","en":"A link"}]',0,'{"it":"Funziona con `overflow: hidden`.","en":"It works with `overflow: hidden`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'components'),1,2,'{"it":"Che cosa toglie la sottolineatura?","en":"What removes the underline?"}','[{"it":"text-decoration: none","en":"text-decoration: none"},{"it":"underline: 0","en":"underline: 0"},{"it":"border: none","en":"border: none"},{"it":"font-style: none","en":"font-style: none"}]',0,'{"it":"I link la hanno di serie.","en":"Links have it by default."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'components'),2,2,'{"it":"Quale cursore indica che si può cliccare?","en":"Which cursor shows you can click?"}','[{"it":"pointer","en":"pointer"},{"it":"hand","en":"hand"},{"it":"click","en":"click"},{"it":"finger","en":"finger"}]',0,'{"it":"`cursor: pointer`.","en":"`cursor: pointer`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'components'),3,2,'{"it":"Quanto dovrebbe essere alto un bottone su telefono?","en":"How high should a button be on phones?"}','[{"it":"Almeno 44px","en":"At least 44px"},{"it":"10px","en":"10px"},{"it":"Non importa","en":"It does not matter"},{"it":"500px","en":"500px"}]',0,'{"it":"Le dita sono meno precise del mouse.","en":"Fingers are less precise than a mouse."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'logical'),1,2,'{"it":"In italiano, qual è la direzione `inline`?","en":"In English, what is the `inline` direction?"}','[{"it":"Verticale","en":"Vertical"},{"it":"Orizzontale","en":"Horizontal"},{"it":"Diagonale","en":"Diagonal"},{"it":"Dipende dallo schermo","en":"It depends on the screen"}]',1,'{"it":"È la direzione in cui scorre una riga di testo.","en":"It is the direction a line of text runs in."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'logical'),2,2,'{"it":"Che cosa fa `margin-inline: auto` su un blocco con una larghezza?","en":"What does `margin-inline: auto` do on a block with a width?"}','[{"it":"Toglie tutti i margini","en":"It removes all margins"},{"it":"Lo centra in verticale","en":"It centres it vertically"},{"it":"Lo centra orizzontalmente","en":"It centres it horizontally"},{"it":"Niente, non è valido","en":"Nothing, it is not valid"}]',2,'{"it":"È il `margin: 0 auto` logico.","en":"It is the logical `margin: 0 auto`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'logical'),3,2,'{"it":"Quale proprietà è la larghezza logica?","en":"Which property is the logical width?"}','[{"it":"block-size","en":"block-size"},{"it":"line-width","en":"line-width"},{"it":"size-x","en":"size-x"},{"it":"inline-size","en":"inline-size"}]',3,'{"it":"`block-size` è l’altezza.","en":"`block-size` is the height."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'forms-style'),1,2,'{"it":"Quale proprietà colora checkbox e radio?","en":"Which property colours checkboxes and radios?"}','[{"it":"color","en":"color"},{"it":"fill","en":"fill"},{"it":"accent-color","en":"accent-color"},{"it":"tint","en":"tint"}]',2,'{"it":"Una riga sola, anche su `:root`, perché si eredita.","en":"A single line, even on `:root`, because it is inherited."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'forms-style'),2,2,'{"it":"Qual è la differenza tra `:user-invalid` e `:invalid`?","en":"What is the difference between `:user-invalid` and `:invalid`?"}','[{"it":"`:user-invalid` scatta solo dopo che l’utente ha interagito","en":"`:user-invalid` only fires after the user has interacted"},{"it":"Nessuna, sono sinonimi","en":"None, they are synonyms"},{"it":"`:user-invalid` controlla i dati sul server","en":"`:user-invalid` checks the data on the server"},{"it":"`:invalid` vale solo dopo l’invio","en":"`:invalid` only applies after submitting"}]',0,'{"it":"Niente bordi rossi prima ancora di cominciare a scrivere.","en":"No red borders before you even start typing."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'forms-style'),3,2,'{"it":"Perché scrivere `font: inherit` sui campi?","en":"Why write `font: inherit` on fields?"}','[{"it":"Rende il testo in grassetto","en":"It makes the text bold"},{"it":"È obbligatorio nei moduli","en":"It is mandatory in forms"},{"it":"Velocizza l’invio del modulo","en":"It speeds up sending the form"},{"it":"Di serie i campi non ereditano il font della pagina","en":"By default fields do not inherit the page font"}]',3,'{"it":"Altrimenti il testo dei campi sembra di un’altra pagina.","en":"Otherwise the field text looks like it belongs to another page."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'images-filters'),1,2,'{"it":"Quale valore di `object-fit` riempie la scatola tagliando l’immagine?","en":"Which `object-fit` value fills the box by cropping the image?"}','[{"it":"contain","en":"contain"},{"it":"fill","en":"fill"},{"it":"none","en":"none"},{"it":"cover","en":"cover"}]',3,'{"it":"`fill` invece la deforma per farla entrare.","en":"`fill` stretches it to fit instead."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'images-filters'),2,2,'{"it":"Che cosa fa `filter: grayscale(1)`?","en":"What does `filter: grayscale(1)` do?"}','[{"it":"Rende l’elemento in bianco e nero","en":"It makes the element black and white"},{"it":"Nasconde l’elemento","en":"It hides the element"},{"it":"Inverte i colori","en":"It inverts the colours"},{"it":"Lo sfoca","en":"It blurs it"}]',0,'{"it":"`0` lascia i colori, `1` li toglie del tutto.","en":"`0` keeps the colours, `1` removes them completely."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'images-filters'),3,2,'{"it":"Su che cosa agisce `backdrop-filter`?","en":"What does `backdrop-filter` act on?"}','[{"it":"Sull’elemento stesso","en":"On the element itself"},{"it":"Su ciò che sta dietro l’elemento","en":"On what is behind the element"},{"it":"Solo sul testo","en":"Only on the text"},{"it":"Solo sui figli","en":"Only on the children"}]',1,'{"it":"Serve uno sfondo almeno in parte trasparente per vedere l’effetto.","en":"It needs an at least partly transparent background to show."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'flex'),1,2,'{"it":"Quale proprietà distribuisce lungo l’asse principale?","en":"Which property distributes along the main axis?"}','[{"it":"align-items","en":"align-items"},{"it":"justify-content","en":"justify-content"},{"it":"flex-wrap","en":"flex-wrap"},{"it":"gap","en":"gap"}]',1,'{"it":"Con `flex-direction: row` l’asse principale è orizzontale.","en":"With `flex-direction: row` the main axis is horizontal."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'flex'),2,2,'{"it":"Dove si scrive `display: flex`?","en":"Where do you write `display: flex`?"}','[{"it":"Sul contenitore","en":"On the container"},{"it":"Su ogni figlio","en":"On each child"},{"it":"Su `html`","en":"On `html`"},{"it":"Sul primo figlio","en":"On the first child"}]',0,'{"it":"Il contenitore diventa flex e i figli diretti ne seguono le regole.","en":"The container becomes flex and its direct children follow its rules."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'flex'),3,2,'{"it":"Come centri un elemento in entrambi i sensi?","en":"How do you centre an element both ways?"}','[{"it":"margin: center","en":"margin: center"},{"it":"`align-content` e `text-align` su `middle`","en":"`align-content` and `text-align` set to `middle`"},{"it":"`justify-content` e `align-items` su `center`","en":"`justify-content` and `align-items` set to `center`"},{"it":"float: center","en":"float: center"}]',2,'{"it":"Sono i due assi del contenitore flex.","en":"They are the two axes of the flex container."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'grid'),1,2,'{"it":"Che cos’è l’unità `fr`?","en":"What is the `fr` unit?"}','[{"it":"Una frazione dello spazio libero","en":"A fraction of the free space"},{"it":"Un pixel","en":"A pixel"},{"it":"La larghezza del font","en":"The width of the font"},{"it":"Un frame","en":"A frame"}]',0,'{"it":"`1fr 2fr` divide lo spazio in tre parti: una e due.","en":"`1fr 2fr` splits the space into three parts: one and two."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'grid'),2,2,'{"it":"Come scrivi tre colonne uguali?","en":"How do you write three equal columns?"}','[{"it":"grid-columns: 3 equal-width auto-fill","en":"grid-columns: 3 equal-width auto-fill"},{"it":"grid-template-columns: repeat(3, 1fr)","en":"grid-template-columns: repeat(3, 1fr)"},{"it":"grid: 3","en":"grid: 3"},{"it":"flex: 3","en":"flex: 3"}]',1,'{"it":"`repeat()` evita di ripetere `1fr 1fr 1fr`.","en":"`repeat()` saves writing `1fr 1fr 1fr`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'grid'),3,2,'{"it":"Che cosa fa `grid-column: 1 / 3`?","en":"What does `grid-column: 1 / 3` do?"}','[{"it":"Occupa tre colonne","en":"It takes three columns"},{"it":"Va dalla linea 1 alla linea 3","en":"It goes from line 1 to line 3"},{"it":"Divide per tre","en":"It divides by three"},{"it":"Crea tre righe","en":"It creates three rows"}]',1,'{"it":"Le linee sono i bordi tra le colonne: l’elemento occupa due colonne.","en":"Lines are the edges between columns: the element takes two columns."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'responsive'),1,2,'{"it":"Che cosa significa *mobile first*?","en":"What does *mobile first* mean?"}','[{"it":"Sviluppare solo per telefoni e nascondere il sito ai computer","en":"Developing for phones only and hiding the site from computers"},{"it":"Partire dal telefono e aggiungere regole per gli schermi grandi","en":"Starting from the phone and adding rules for large screens"},{"it":"Usare un’app","en":"Using an app"},{"it":"Nascondere il desktop","en":"Hiding the desktop"}]',1,'{"it":"Si usano media query con `min-width`.","en":"It uses media queries with `min-width`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'responsive'),2,2,'{"it":"Quando si applica `@media (min-width: 700px)`?","en":"When does `@media (min-width: 700px)` apply?"}','[{"it":"Sotto i 700px","en":"Under 700px"},{"it":"Da 700px in su","en":"From 700px up"},{"it":"Solo a 700px","en":"Only at 700px"},{"it":"Sempre","en":"Always"}]',1,'{"it":"`min-width` significa «almeno questa larghezza».","en":"`min-width` means “at least this width”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'responsive'),3,2,'{"it":"Che cosa fa `clamp(1rem, 4vw, 2rem)`?","en":"What does `clamp(1rem, 4vw, 2rem)` do?"}','[{"it":"Sceglie a caso","en":"Picks at random"},{"it":"Tiene `4vw` tra 1rem e 2rem","en":"Keeps `4vw` between 1rem and 2rem"},{"it":"Somma i valori","en":"Adds the values"},{"it":"Blocca il font","en":"Locks the font"}]',1,'{"it":"Un valore fluido, con un minimo e un massimo.","en":"A fluid value, with a minimum and a maximum."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'variables'),1,2,'{"it":"Come si dichiara una variabile CSS?","en":"How do you declare a CSS variable?"}','[{"it":"$brand: red","en":"$brand: red"},{"it":"--brand: red","en":"--brand: red"},{"it":"@brand: red","en":"@brand: red"},{"it":"var brand = red","en":"var brand = red"}]',1,'{"it":"Inizia con due trattini e si dichiara dentro un selettore.","en":"It starts with two dashes and is declared inside a selector."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'variables'),2,2,'{"it":"Dove si dichiarano di solito le variabili globali?","en":"Where are global variables usually declared?"}','[{"it":":root","en":":root"},{"it":"head","en":"head"},{"it":"body::before","en":"body::before"},{"it":"@global","en":"@global"}]',0,'{"it":"`:root` è l’elemento radice, cioè `html`.","en":"`:root` is the root element, that is `html`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'variables'),3,2,'{"it":"A cosa serve il secondo argomento di `var()`?","en":"What is the second argument of `var()` for?"}','[{"it":"Al tipo","en":"The type"},{"it":"Al valore di riserva","en":"The fallback value"},{"it":"Alla durata","en":"The duration"},{"it":"All’unità","en":"The unit"}]',1,'{"it":"Si usa se la variabile non è definita.","en":"It is used if the variable is not defined."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'motion'),1,2,'{"it":"Quale proprietà anima il passaggio tra due stati?","en":"Which property animates the change between two states?"}','[{"it":"animation-state","en":"animation-state"},{"it":"transition","en":"transition"},{"it":"change","en":"change"},{"it":"keyframes","en":"keyframes"}]',1,'{"it":"Si scrive sullo stato di partenza, con durata e curva.","en":"It goes on the starting state, with duration and curve."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'motion'),2,2,'{"it":"Con che cosa si definiscono i passaggi di un’animazione?","en":"What defines the steps of an animation?"}','[{"it":"@media","en":"@media"},{"it":"@keyframes","en":"@keyframes"},{"it":"@animate","en":"@animate"},{"it":"@steps","en":"@steps"}]',1,'{"it":"Poi si applica con la proprietà `animation`.","en":"It is then applied with the `animation` property."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'motion'),3,2,'{"it":"Quale media query rispetta chi chiede meno movimento?","en":"Which media query respects those asking for less motion?"}','[{"it":"prefers-reduced-motion","en":"prefers-reduced-motion"},{"it":"no-animation","en":"no-animation"},{"it":"motion: off","en":"motion: off"},{"it":"reduced-data","en":"reduced-data"}]',0,'{"it":"Il sistema operativo la espone come preferenza di accessibilità.","en":"The operating system exposes it as an accessibility preference."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'pseudo'),1,3,'{"it":"Che cosa serve sempre a `::before`?","en":"What does `::before` always need?"}','[{"it":"content","en":"content"},{"it":"display","en":"display"},{"it":"width","en":"width"},{"it":"color","en":"color"}]',0,'{"it":"Senza `content` non viene creato nulla.","en":"Without `content` nothing is created."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'pseudo'),2,3,'{"it":"Quali elementi sceglie `li:nth-child(even)`?","en":"Which elements does `li:nth-child(even)` pick?"}','[{"it":"I pari","en":"The even ones"},{"it":"I dispari","en":"The odd ones"},{"it":"Il primo","en":"The first"},{"it":"Tutti","en":"All of them"}]',0,'{"it":"`even` è pari, `odd` dispari.","en":"`even` is even, `odd` is odd."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'pseudo'),3,3,'{"it":"Come si scrive uno pseudo-elemento?","en":"How is a pseudo-element written?"}','[{"it":"Con `::`","en":"With `::`"},{"it":"Con `#`","en":"With `#`"},{"it":"Con `$`","en":"With `$`"},{"it":"Con `@`","en":"With `@`"}]',0,'{"it":"Due punti doppi lo distinguono da una pseudo-classe.","en":"The double colon sets it apart from a pseudo-class."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'modern'),1,3,'{"it":"Che cosa sceglie `.card:has(img)`?","en":"What does `.card:has(img)` pick?"}','[{"it":"Le card con un’immagine","en":"Cards with an image"},{"it":"Le immagini","en":"The images"},{"it":"Tutte le card","en":"All cards"},{"it":"Nulla","en":"Nothing"}]',0,'{"it":"Si guarda dentro, ma viene scelto il genitore.","en":"It looks inside, but the parent is picked."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'modern'),2,3,'{"it":"A che cosa guarda `@container`?","en":"What does `@container` look at?"}','[{"it":"Al contenitore","en":"The container"},{"it":"Allo schermo","en":"The screen"},{"it":"Al font","en":"The font"},{"it":"Al server","en":"The server"}]',0,'{"it":"Un componente si adatta allo spazio che ha davvero.","en":"A component adapts to the space it really has."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'modern'),3,3,'{"it":"Il CSS moderno può annidare le regole?","en":"Can modern CSS nest rules?"}','[{"it":"Sì","en":"Yes"},{"it":"No, solo SCSS","en":"No, only SCSS"},{"it":"Solo in `@media`","en":"Only in `@media`"},{"it":"Solo con JavaScript","en":"Only with JavaScript"}]',0,'{"it":"Il nesting ora è nel CSS nativo, con `&`.","en":"Nesting is now in native CSS, with `&`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'layers'),1,3,'{"it":"Tra due livelli, quale regola vince?","en":"Between two layers, which rule wins?"}','[{"it":"Quella con il selettore più specifico","en":"The one with the more specific selector"},{"it":"Quella del livello che viene dopo nell’ordine","en":"The one in the layer that comes later in the order"},{"it":"Quella scritta per prima nel file","en":"The one written first in the file"},{"it":"Nessuna: si annullano a vicenda","en":"Neither: they cancel each other out"}]',1,'{"it":"L’ordine dei livelli conta prima della specificità.","en":"Layer order counts before specificity."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'layers'),2,3,'{"it":"Qual è la specificità di `:where(.nota)`?","en":"What is the specificity of `:where(.nota)`?"}','[{"it":"0,1,0","en":"0,1,0"},{"it":"0,0,1","en":"0,0,1"},{"it":"1,0,0","en":"1,0,0"},{"it":"0,0,0","en":"0,0,0"}]',3,'{"it":"`:where()` azzera sempre la specificità.","en":"`:where()` always sets specificity to zero."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'layers'),3,3,'{"it":"Uno stile fuori dai livelli e uno dentro un livello: chi vince?","en":"A style outside the layers and one inside a layer: which wins?"}','[{"it":"Sempre quello dentro il livello","en":"Always the one inside the layer"},{"it":"Dipende dalla lunghezza del file","en":"It depends on the file length"},{"it":"Quello fuori dai livelli","en":"The one outside the layers"},{"it":"Il browser segnala un errore","en":"The browser reports an error"}]',2,'{"it":"Vale per le dichiarazioni normali; con `!important` l’ordine si rovescia.","en":"This holds for normal declarations; with `!important` the order flips."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'grid-areas'),1,3,'{"it":"Che cosa rappresenta ogni stringa di `grid-template-areas`?","en":"What does each string of `grid-template-areas` represent?"}','[{"it":"Una colonna","en":"A column"},{"it":"Una riga","en":"A row"},{"it":"Un singolo elemento","en":"A single item"},{"it":"Un livello di profondità","en":"A depth layer"}]',1,'{"it":"Le parole della stringa sono le celle di quella riga.","en":"The words in the string are the cells of that row."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'grid-areas'),2,3,'{"it":"Come lasci vuota una cella in `grid-template-areas`?","en":"How do you leave a cell empty in `grid-template-areas`?"}','[{"it":"_","en":"_"},{"it":"none","en":"none"},{"it":"0","en":"0"},{"it":".","en":"."}]',3,'{"it":"Uno o più punti di fila valgono come cella vuota.","en":"One or more dots in a row count as an empty cell."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'grid-areas'),3,3,'{"it":"A che cosa serve `subgrid`?","en":"What is `subgrid` for?"}','[{"it":"A far allineare i figli di più card sulle righe del genitore","en":"To line up the children of several cards on the parent’s rows"},{"it":"A creare una griglia dentro una tabella","en":"To create a grid inside a table"},{"it":"A nascondere le righe vuote","en":"To hide empty rows"},{"it":"A rendere la griglia più veloce","en":"To make the grid faster"}]',0,'{"it":"La griglia figlia eredita le tracce invece di crearne di nuove.","en":"The child grid inherits the tracks instead of making new ones."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'colors-modern'),1,3,'{"it":"Che cosa indica il primo valore di `oklch(65% 0.2 40)`?","en":"What does the first value of `oklch(65% 0.2 40)` stand for?"}','[{"it":"La tinta","en":"The hue"},{"it":"La saturazione","en":"The saturation"},{"it":"La luminosità percepita","en":"The perceived lightness"},{"it":"La trasparenza","en":"The transparency"}]',2,'{"it":"Poi vengono croma e tinta.","en":"Chroma and hue come next."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'colors-modern'),2,3,'{"it":"Che cosa serve perché `light-dark()` cambi con il tema?","en":"What does `light-dark()` need to change with the theme?"}','[{"it":"`color-scheme: light dark`","en":"`color-scheme: light dark`"},{"it":"Una riga di JavaScript","en":"A line of JavaScript"},{"it":"Una media query in ogni regola","en":"A media query in every rule"},{"it":"Un’immagine di sfondo","en":"A background image"}]',0,'{"it":"Senza `color-scheme` il browser usa sempre il primo valore.","en":"Without `color-scheme` the browser always uses the first value."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'colors-modern'),3,3,'{"it":"Che cosa produce `color-mix(in oklch, red, white 30%)`?","en":"What does `color-mix(in oklch, red, white 30%)` produce?"}','[{"it":"Un rosso più scuro del 30%","en":"A red 30% darker"},{"it":"Un rosso con il 30% di bianco","en":"A red with 30% white"},{"it":"Un rosso trasparente al 30%","en":"A red 30% transparent"},{"it":"Un errore: si mescolano solo i grigi","en":"An error: only greys can be mixed"}]',1,'{"it":"La percentuale dice quanto pesa il secondo colore.","en":"The percentage says how much the second colour weighs."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'transitions'),1,2,'{"it":"Dove si scrive `transition`?","en":"Where does `transition` go?"}','[{"it":"Sullo stato normale","en":"On the normal state"},{"it":"Solo su `:hover`","en":"Only on `:hover`"},{"it":"Nell’HTML","en":"In the HTML"},{"it":"In `@media`","en":"In `@media`"}]',0,'{"it":"Così l’effetto vale nei due sensi.","en":"So the effect works both ways."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'transitions'),2,2,'{"it":"Quanto dura `.3s`?","en":"How long is `.3s`?"}','[{"it":"300 millisecondi","en":"300 milliseconds"},{"it":"3 secondi","en":"3 seconds"},{"it":"30 secondi","en":"30 seconds"},{"it":"3 minuti","en":"3 minutes"}]',0,'{"it":"Tra 150 e 300ms un’interfaccia sembra rapida.","en":"Between 150 and 300ms an interface feels quick."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'transitions'),3,2,'{"it":"Si può animare `display`?","en":"Can you animate `display`?"}','[{"it":"Di solito no","en":"Usually not"},{"it":"Sempre","en":"Always"},{"it":"Solo in rosso","en":"Only in red"},{"it":"Solo nei link","en":"Only in links"}]',0,'{"it":"Si anima ciò che ha valori intermedi, come `opacity`. `display` non ne ha: al massimo, con `transition-behavior: allow-discrete`, si sceglie quando scatta.","en":"You animate what has in-between values, like `opacity`. `display` has none: at most, with `transition-behavior: allow-discrete`, you choose when it flips."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'transforms'),1,2,'{"it":"Quale funzione sposta?","en":"Which function moves?"}','[{"it":"translate()","en":"translate()"},{"it":"move()","en":"move()"},{"it":"shift()","en":"shift()"},{"it":"go()","en":"go()"}]',0,'{"it":"Esistono `translateX` e `translateY`.","en":"There are `translateX` and `translateY`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'transforms'),2,2,'{"it":"`transform` sposta gli altri elementi?","en":"Does `transform` move other elements?"}','[{"it":"No","en":"No"},{"it":"Sì","en":"Yes"},{"it":"Solo i fratelli","en":"Only siblings"},{"it":"Solo il genitore","en":"Only the parent"}]',0,'{"it":"Lo spazio occupato resta quello di prima.","en":"The space taken stays as before."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'transforms'),3,2,'{"it":"Che cosa cambia `transform-origin`?","en":"What does `transform-origin` change?"}','[{"it":"Il punto di riferimento","en":"The reference point"},{"it":"La durata","en":"The duration"},{"it":"Il colore","en":"The colour"},{"it":"La curva","en":"The curve"}]',0,'{"it":"Una rotazione da un angolo sembra una porta.","en":"A rotation from a corner looks like a door."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'keyframes'),1,2,'{"it":"Che cosa definisce `@keyframes`?","en":"What does `@keyframes` define?"}','[{"it":"Le tappe di un’animazione","en":"The stages of an animation"},{"it":"Un font","en":"A font"},{"it":"Una variabile","en":"A variable"},{"it":"Una media query","en":"A media query"}]',0,'{"it":"Si usa poi con `animation`.","en":"It is then used with `animation`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'keyframes'),2,2,'{"it":"Come si ripete per sempre?","en":"How does it repeat for ever?"}','[{"it":"infinite","en":"infinite"},{"it":"loop","en":"loop"},{"it":"always","en":"always"},{"it":"repeat","en":"repeat"}]',0,'{"it":"Oppure un numero di giri.","en":"Or a number of rounds."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'keyframes'),3,2,'{"it":"`from` e `to` equivalgono a…","en":"`from` and `to` are the same as…"}','[{"it":"0% e 100%","en":"0% e 100%"},{"it":"1 e 2","en":"1 e 2"},{"it":"start e end","en":"start e end"},{"it":"A e B","en":"A e B"}]',0,'{"it":"Per le tappe intermedie servono le percentuali.","en":"In-between stages need percentages."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'timing'),1,2,'{"it":"Quale curva frena alla fine?","en":"Which curve brakes at the end?"}','[{"it":"ease-out","en":"ease-out"},{"it":"ease-in","en":"ease-in"},{"it":"linear","en":"linear"},{"it":"step","en":"step"}]',0,'{"it":"È la più naturale per ciò che entra in scena.","en":"It is the most natural for things entering the scene."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'timing'),2,2,'{"it":"Che cosa fa `forwards`?","en":"What does `forwards` do?"}','[{"it":"Tiene l’ultima tappa","en":"Keeps the last stage"},{"it":"Salta avanti","en":"Skips ahead"},{"it":"Va più veloce","en":"Goes faster"},{"it":"Ripete","en":"Repeats"}]',0,'{"it":"Senza, l’elemento torna com’era.","en":"Without it, the element goes back to how it was."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'timing'),3,2,'{"it":"Perché scaglionare i ritardi in una lista?","en":"Why stagger delays in a list?"}','[{"it":"Per un effetto a cascata","en":"For a cascade effect"},{"it":"Per pesare meno","en":"To weigh less"},{"it":"Per la SEO","en":"For SEO"},{"it":"Per il colore","en":"For colour"}]',0,'{"it":"L’occhio segue meglio una cosa alla volta.","en":"The eye follows one thing at a time better."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'respect'),1,2,'{"it":"Quali proprietà conviene animare?","en":"Which properties are best to animate?"}','[{"it":"`transform` e `opacity`","en":"`transform` and `opacity`"},{"it":"`width` e `height`","en":"`width` and `height`"},{"it":"`margin` e `top`","en":"`margin` and `top`"},{"it":"`font-size`","en":"`font-size`"}]',0,'{"it":"Non costringono a ricalcolare la pagina.","en":"They do not force the page to be recalculated."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'respect'),2,2,'{"it":"Che cosa rispetta `prefers-reduced-motion`?","en":"What does `prefers-reduced-motion` respect?"}','[{"it":"Chi chiede meno movimento","en":"People asking for less movement"},{"it":"Chi ha uno schermo piccolo","en":"People with a small screen"},{"it":"Chi usa Safari","en":"Safari users"},{"it":"Chi è offline","en":"Offline users"}]',0,'{"it":"È una preferenza del sistema operativo.","en":"It is an operating system preference."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'respect'),3,2,'{"it":"A che cosa deve servire un’animazione?","en":"What should an animation do?"}','[{"it":"A spiegare","en":"Explain"},{"it":"A distrarre","en":"Distract"},{"it":"A rallentare","en":"Slow things down"},{"it":"A stupire sempre","en":"Always amaze"}]',0,'{"it":"Se non aiuta a capire, togliila.","en":"If it does not help understanding, remove it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'individual-3d'),1,3,'{"it":"Che vantaggio hanno `translate`, `rotate` e `scale` separate?","en":"What is the advantage of separate `translate`, `rotate` and `scale`?"}','[{"it":"Sono più veloci di `opacity`","en":"They are faster than `opacity`"},{"it":"Funzionano senza unità di misura","en":"They work without units"},{"it":"Ognuna si cambia senza riscrivere le altre","en":"Each one changes without rewriting the others"},{"it":"Spostano anche gli elementi vicini","en":"They also move nearby elements"}]',2,'{"it":"Con `transform` dovresti ripetere tutta la lista di funzioni.","en":"With `transform` you would have to repeat the whole list of functions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'individual-3d'),2,3,'{"it":"Che cosa succede se riduci `perspective` da 1000px a 300px?","en":"What happens if you reduce `perspective` from 1000px to 300px?"}','[{"it":"L’effetto 3D diventa più forte","en":"The 3D effect gets stronger"},{"it":"L’effetto 3D sparisce","en":"The 3D effect disappears"},{"it":"L’elemento si rimpicciolisce","en":"The element shrinks"},{"it":"Niente, conta solo sui telefoni","en":"Nothing, it only matters on phones"}]',0,'{"it":"È come guardare la scena da più vicino.","en":"It is like looking at the scene from closer up."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'individual-3d'),3,3,'{"it":"Che cosa fa `rotate: y 180deg`?","en":"What does `rotate: y 180deg` do?"}','[{"it":"Ruota nel piano dello schermo","en":"It rotates in the plane of the screen"},{"it":"Sposta l’elemento in verticale","en":"It moves the element vertically"},{"it":"Capovolge solo il testo","en":"It flips only the text"},{"it":"Gira l’elemento attorno all’asse verticale","en":"It turns the element around the vertical axis"}]',3,'{"it":"Come una moneta che mostra il retro.","en":"Like a coin showing its back."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'entry-exit'),1,3,'{"it":"Che cosa definisce `@starting-style`?","en":"What does `@starting-style` define?"}','[{"it":"Lo stile della pagina all’apertura","en":"The page style when it opens"},{"it":"Lo stato da cui parte la transizione d’entrata","en":"The state the entry transition starts from"},{"it":"L’ultima tappa di un’animazione","en":"The last stage of an animation"},{"it":"Lo stile di stampa","en":"The print style"}]',1,'{"it":"Vale solo nel primo istante in cui l’elemento viene disegnato.","en":"It only applies at the first moment the element is drawn."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'entry-exit'),2,3,'{"it":"Perché serve `allow-discrete` su `display`?","en":"Why does `display` need `allow-discrete`?"}','[{"it":"Per animare `display` a valori intermedi","en":"To animate `display` through in-between values"},{"it":"Per rendere la transizione più veloce","en":"To make the transition faster"},{"it":"Per far scattare `display` al momento giusto","en":"To make `display` flip at the right moment"},{"it":"Per nascondere l’elemento ai lettori di schermo","en":"To hide the element from screen readers"}]',2,'{"it":"`display` non ha valori intermedi: si sceglie solo quando cambia.","en":"`display` has no in-between values: you only choose when it changes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'entry-exit'),3,3,'{"it":"Che cosa succede nei browser che non supportano `@starting-style`?","en":"What happens in browsers that do not support `@starting-style`?"}','[{"it":"La pagina va in errore","en":"The page breaks"},{"it":"L’elemento non compare mai","en":"The element never appears"},{"it":"Il CSS viene ignorato tutto","en":"All the CSS is ignored"},{"it":"L’elemento compare senza animazione","en":"The element appears without animation"}]',3,'{"it":"È un miglioramento progressivo.","en":"It is a progressive enhancement."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'scroll-driven'),1,3,'{"it":"Qual è la differenza tra `scroll()` e `view()`?","en":"What is the difference between `scroll()` and `view()`?"}','[{"it":"`scroll()` segue lo scorrimento del contenitore, `view()` il passaggio dell’elemento nello schermo","en":"`scroll()` follows the container’s scrolling, `view()` the element passing through the screen"},{"it":"Sono due nomi della stessa cosa","en":"They are two names for the same thing"},{"it":"`view()` funziona solo con i video","en":"`view()` only works with videos"},{"it":"`scroll()` serve solo in orizzontale","en":"`scroll()` is only for horizontal scrolling"}]',0,'{"it":"Barra di avanzamento con `scroll()`, comparse con `view()`.","en":"A progress bar with `scroll()`, reveals with `view()`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'scroll-driven'),2,3,'{"it":"Perché `animation-timeline` va scritta dopo `animation`?","en":"Why must `animation-timeline` come after `animation`?"}','[{"it":"Per una questione di stile","en":"As a matter of style"},{"it":"Perché la scorciatoia `animation` la azzera","en":"Because the `animation` shorthand resets it"},{"it":"Perché il browser legge il CSS al contrario","en":"Because the browser reads CSS backwards"},{"it":"Non importa l’ordine","en":"The order does not matter"}]',1,'{"it":"Una scorciatoia reimposta tutte le sue sotto-proprietà.","en":"A shorthand resets all of its sub-properties."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'scroll-driven'),3,3,'{"it":"Che durata serve a un’animazione guidata dallo scorrimento?","en":"What duration does a scroll-driven animation need?"}','[{"it":"Almeno 1 secondo","en":"At least 1 second"},{"it":"Esattamente 100ms","en":"Exactly 100ms"},{"it":"Una durata per ogni pagina","en":"One duration per page"},{"it":"Nessuna: il tempo lo sostituisce lo scorrimento","en":"None: scrolling replaces time"}]',3,'{"it":"Di solito si usa la curva `linear`, per seguire il dito alla pari.","en":"The `linear` curve is usually used, to follow the finger evenly."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'view-transitions'),1,3,'{"it":"Che cosa fa `view-transition-name` su un elemento?","en":"What does `view-transition-name` do on an element?"}','[{"it":"Gli dà un titolo per i motori di ricerca","en":"It gives it a title for search engines"},{"it":"Lo nasconde durante la transizione","en":"It hides it during the transition"},{"it":"Lo fa animare dalla vecchia alla nuova posizione","en":"It makes it animate from the old position to the new one"},{"it":"Lo carica prima degli altri","en":"It loads it before the others"}]',2,'{"it":"Lo stesso nome lega i due stati dell’elemento.","en":"The same name links the element’s two states."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'view-transitions'),2,3,'{"it":"Come si attivano le transizioni tra due pagine dello stesso sito?","en":"How do you turn on transitions between two pages of the same site?"}','[{"it":"@view-transition { navigation: auto; }","en":"@view-transition { navigation: auto; }"},{"it":"<meta name=\\"transition\\">","en":"<meta name=\\"transition\\">"},{"it":"transition: page 1s;","en":"transition: page 1s;"},{"it":"@keyframes page","en":"@keyframes page"}]',0,'{"it":"La regola va nel CSS di entrambe le pagine.","en":"The rule goes in the CSS of both pages."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'view-transitions'),3,3,'{"it":"Che cosa succede in un browser senza supporto?","en":"What happens in a browser without support?"}','[{"it":"La pagina non si apre","en":"The page does not open"},{"it":"La pagina cambia normalmente, senza animazione","en":"The page changes normally, without animation"},{"it":"Compare un avviso all’utente","en":"A warning appears for the user"},{"it":"Il sito diventa lento","en":"The site becomes slow"}]',1,'{"it":"Nessun danno: solo niente effetto.","en":"No harm: just no effect."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'intro'),1,2,'{"it":"Il browser sa leggere un file `.scss`?","en":"Can the browser read a `.scss` file?"}','[{"it":"Sì, sempre","en":"Yes, always"},{"it":"No, va compilato in CSS","en":"No, it must be compiled to CSS"},{"it":"Solo Chrome","en":"Only Chrome"},{"it":"Solo con JavaScript attivo","en":"Only with JavaScript on"}]',1,'{"it":"Il compilatore trasforma SCSS in CSS.","en":"The compiler turns SCSS into CSS."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'intro'),2,2,'{"it":"Con quale simbolo inizia una variabile SCSS?","en":"Which symbol starts an SCSS variable?"}','[{"it":"--","en":"--"},{"it":"@","en":"@"},{"it":"$","en":"$"},{"it":"#","en":"#"}]',2,'{"it":"`$` per Sass, `--` per le variabili CSS.","en":"`$` for Sass, `--` for CSS variables."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'intro'),3,2,'{"it":"Un file CSS valido è anche SCSS valido?","en":"Is a valid CSS file also valid SCSS?"}','[{"it":"Sì","en":"Yes"},{"it":"No","en":"No"},{"it":"Solo senza commenti","en":"Only with no comments"},{"it":"Solo senza media query","en":"Only with no media queries"}]',0,'{"it":"Per questo si può iniziare rinominando il file.","en":"That is why you can start by renaming the file."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'nesting'),1,2,'{"it":"Che cosa indica `&`?","en":"What does `&` stand for?"}','[{"it":"Il selettore genitore","en":"The parent selector"},{"it":"Una variabile","en":"A variable"},{"it":"Tutti i figli","en":"All the children"},{"it":"Un commento","en":"A comment"}]',0,'{"it":"Viene sostituito dal selettore che lo contiene.","en":"It is replaced by the selector containing it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'nesting'),2,2,'{"it":"In che cosa si compila `.a { &:hover { … } }`?","en":"What does `.a { &:hover { … } }` compile to?"}','[{"it":".a :hover","en":".a :hover"},{"it":".a:hover","en":".a:hover"},{"it":".hover .a","en":".hover .a"},{"it":":hover.a","en":":hover.a"}]',1,'{"it":"`&` unisce senza spazio.","en":"`&` joins with no space."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'nesting'),3,2,'{"it":"Perché non annidare troppo?","en":"Why not nest too deep?"}','[{"it":"Il compilatore si blocca","en":"The compiler stops"},{"it":"I selettori diventano lunghi e difficili da sovrascrivere","en":"Selectors become long and hard to override"},{"it":"Il browser rallenta del tutto","en":"The browser stalls completely"},{"it":"Non è permesso","en":"It is not allowed"}]',1,'{"it":"Lo stesso annidamento aumenta anche la specificità.","en":"Nesting also raises specificity."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'mixins'),1,2,'{"it":"Come si usa un mixin?","en":"How do you use a mixin?"}','[{"it":"@use","en":"@use"},{"it":"@include","en":"@include"},{"it":"@mixin","en":"@mixin"},{"it":"@apply","en":"@apply"}]',1,'{"it":"`@mixin` lo definisce, `@include` lo inserisce.","en":"`@mixin` defines it, `@include` inserts it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'mixins'),2,2,'{"it":"Quale vantaggio hanno i mixin rispetto a `@extend`?","en":"What advantage do mixins have over `@extend`?"}','[{"it":"Accettano parametri","en":"They accept parameters"},{"it":"Sono più corti","en":"They are shorter"},{"it":"Non si compilano","en":"They are not compiled"},{"it":"Funzionano in HTML","en":"They work in HTML"}]',0,'{"it":"Un mixin produce regole diverse a seconda degli argomenti.","en":"A mixin produces different rules depending on its arguments."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'mixins'),3,2,'{"it":"Che cosa fa un selettore `%segnaposto` da solo?","en":"What does a `%placeholder` selector do alone?"}','[{"it":"Produce CSS","en":"It produces CSS"},{"it":"Nulla finché non viene esteso","en":"Nothing until it is extended"},{"it":"Dà errore","en":"It raises an error"},{"it":"Crea una classe","en":"It creates a class"}]',1,'{"it":"È pensato solo per `@extend`.","en":"It is meant only for `@extend`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'modules'),1,2,'{"it":"Con quale regola si carica un modulo?","en":"Which rule loads a module?"}','[{"it":"@use","en":"@use"},{"it":"@load","en":"@load"},{"it":"@require","en":"@require"},{"it":"@module","en":"@module"}]',0,'{"it":"`@use` sostituisce il vecchio `@import`.","en":"`@use` replaces the old `@import`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'modules'),2,2,'{"it":"Come si chiama un partial?","en":"How is a partial named?"}','[{"it":"colori.part.scss","en":"colori.part.scss"},{"it":"_colori.scss","en":"_colori.scss"},{"it":"#colori.scss","en":"#colori.scss"},{"it":"colori_.css","en":"colori_.css"}]',1,'{"it":"Il trattino basso dice di non compilarlo da solo.","en":"The underscore says not to compile it alone."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'modules'),3,2,'{"it":"A che cosa serve `#{ }`?","en":"What is `#{ }` for?"}','[{"it":"A commentare","en":"To comment"},{"it":"A interpolare un valore in un nome","en":"To interpolate a value into a name"},{"it":"A importare un file parziale nel foglio principale","en":"To import a partial file into the main stylesheet"},{"it":"A selezionare un id","en":"To select an id"}]',1,'{"it":"Si chiama interpolazione.","en":"It is called interpolation."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'functions'),1,2,'{"it":"Che cosa restituisce una `@function`?","en":"What does an `@function` give back?"}','[{"it":"Un valore","en":"A value"},{"it":"Delle regole","en":"Rules"},{"it":"Un file","en":"A file"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Le regole sono il lavoro dei mixin.","en":"Rules are the job of mixins."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'functions'),2,2,'{"it":"Quale parola chiude una funzione?","en":"Which word ends a function?"}','[{"it":"@return","en":"@return"},{"it":"@end","en":"@end"},{"it":"@give","en":"@give"},{"it":"@out","en":"@out"}]',0,'{"it":"`@return` indica il risultato.","en":"`@return` gives the result."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'functions'),3,2,'{"it":"Quanto vale `spazio(2)` nell’esempio?","en":"What is `spazio(2)` in the example?"}','[{"it":"16px","en":"16px"},{"it":"8px","en":"8px"},{"it":"2px","en":"2px"},{"it":"10px","en":"10px"}]',0,'{"it":"2 × 8px.","en":"2 × 8px."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'architecture'),1,3,'{"it":"Con che cosa inizia un file parziale?","en":"What does a partial file start with?"}','[{"it":"_","en":"_"},{"it":"-","en":"-"},{"it":"@","en":"@"},{"it":"$","en":"$"}]',0,'{"it":"Il trattino basso dice al compilatore di non crearne un `.css`.","en":"The underscore tells the compiler not to create a `.css` for it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'architecture'),2,3,'{"it":"Nel `@use` si scrive il `_`?","en":"Do you write the `_` in `@use`?"}','[{"it":"No","en":"No"},{"it":"Sì, sempre","en":"Yes, always"},{"it":"Solo in Sass","en":"Only in Sass"},{"it":"Solo due volte","en":"Only twice"}]',0,'{"it":"Basta il nome: `@use \\"bottoni\\"`.","en":"The name is enough: `@use \\"bottoni\\"`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'architecture'),3,3,'{"it":"Quanti CSS produce di solito il progetto?","en":"How many CSS files does the project usually produce?"}','[{"it":"Uno","en":"One"},{"it":"Uno per parziale","en":"One per partial"},{"it":"Nessuno","en":"None"},{"it":"Due","en":"Two"}]',0,'{"it":"Un solo file è più veloce da scaricare.","en":"A single file is quicker to download."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'content-blocks'),1,3,'{"it":"Che cosa inserisce `@content` dentro un mixin?","en":"What does `@content` insert inside a mixin?"}','[{"it":"I parametri del mixin","en":"The mixin’s parameters"},{"it":"Un file parziale","en":"A partial file"},{"it":"Il blocco passato tra graffe con `@include`","en":"The block passed in braces with `@include`"},{"it":"Il contenuto HTML dell’elemento","en":"The element’s HTML content"}]',2,'{"it":"Il blocco viaggia insieme a `@include`.","en":"The block travels with `@include`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'content-blocks'),2,3,'{"it":"Dove si scrive il blocco per `@content`?","en":"Where do you write the block for `@content`?"}','[{"it":"Come stringa tra parentesi","en":"As a string in brackets"},{"it":"Tra graffe subito dopo `@include nome`","en":"In braces right after `@include name`"},{"it":"In un file separato","en":"In a separate file"},{"it":"Dopo un punto e virgola","en":"After a semicolon"}]',1,'{"it":"`@include schermo(700px) { … }`.","en":"`@include schermo(700px) { … }`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'content-blocks'),3,3,'{"it":"Qual è un uso tipico di `@content`?","en":"What is a typical use of `@content`?"}','[{"it":"Calcolare un colore","en":"Working out a colour"},{"it":"Importare un font","en":"Importing a font"},{"it":"Dichiarare variabili globali","en":"Declaring global variables"},{"it":"Dare un nome ai breakpoint delle media query","en":"Naming media query breakpoints"}]',3,'{"it":"Così tutto il progetto usa gli stessi punti di rottura.","en":"That way the whole project uses the same breakpoints."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'control-flow'),1,3,'{"it":"Quante classi crea `@for $i from 1 to 3`?","en":"How many classes does `@for $i from 1 to 3` create?"}','[{"it":"1","en":"1"},{"it":"2","en":"2"},{"it":"3","en":"3"},{"it":"4","en":"4"}]',1,'{"it":"`to` esclude il 3: restano 1 e 2.","en":"`to` leaves out 3: 1 and 2 remain."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'control-flow'),2,3,'{"it":"Quale regola segue un `@if` per il caso contrario?","en":"Which rule follows an `@if` for the opposite case?"}','[{"it":"@elif","en":"@elif"},{"it":"@otherwise","en":"@otherwise"},{"it":"@else","en":"@else"},{"it":"@then","en":"@then"}]',2,'{"it":"Si può anche scrivere `@else if` per una seconda condizione.","en":"You can also write `@else if` for a second condition."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'control-flow'),3,3,'{"it":"Qual è il rischio dei cicli in SCSS?","en":"What is the risk of loops in SCSS?"}','[{"it":"Il browser li esegue a ogni clic","en":"The browser runs them on every click"},{"it":"Non funzionano con le variabili","en":"They do not work with variables"},{"it":"Rendono lo SCSS illeggibile per il compilatore","en":"They make SCSS unreadable for the compiler"},{"it":"Possono produrre un CSS enorme","en":"They can produce a huge CSS file"}]',3,'{"it":"Il ciclo gira solo durante la compilazione, ma il risultato si scarica.","en":"The loop only runs while compiling, but the result is downloaded."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'forward-config'),1,3,'{"it":"Che cosa fa `!default`?","en":"What does `!default` do?"}','[{"it":"Rende la variabile costante","en":"It makes the variable constant"},{"it":"Assegna il valore solo se la variabile non ne ha già uno","en":"It assigns the value only if the variable has none yet"},{"it":"Esporta la variabile nel CSS","en":"It exports the variable to the CSS"},{"it":"Cancella la variabile","en":"It deletes the variable"}]',1,'{"it":"Così il valore si può configurare da fuori.","en":"So the value can be configured from outside."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'forward-config'),2,3,'{"it":"A che cosa serve `@forward`?","en":"What is `@forward` for?"}','[{"it":"A ripubblicare i membri di un altro modulo","en":"To republish another module’s members"},{"it":"A spostare il CSS in fondo al file","en":"To move the CSS to the end of the file"},{"it":"A compilare più in fretta","en":"To compile faster"},{"it":"A importare un file CSS normale","en":"To import a plain CSS file"}]',0,'{"it":"Chi carica il modulo vede anche ciò che inoltra.","en":"Whoever loads the module also sees what it forwards."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'forward-config'),3,3,'{"it":"Che cosa fa `@use \\"colori\\" as *`?","en":"What does `@use \\"colori\\" as *` do?"}','[{"it":"Carica tutti i file della cartella","en":"It loads every file in the folder"},{"it":"Rinomina il file in `*`","en":"It renames the file to `*`"},{"it":"Carica il modulo due volte","en":"It loads the module twice"},{"it":"Usa i membri senza spazio dei nomi","en":"It uses the members with no namespace"}]',3,'{"it":"Scrivi `$brand` invece di `colori.$brand`.","en":"You write `$brand` instead of `colori.$brand`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'indented'),1,2,'{"it":"Che cosa manca in un file `.sass`?","en":"What is missing from a `.sass` file?"}','[{"it":"Le variabili","en":"Variables"},{"it":"Le graffe e i punti e virgola","en":"Braces and semicolons"},{"it":"L’annidamento","en":"Nesting"},{"it":"I mixin","en":"Mixins"}]',1,'{"it":"Al loro posto ci sono gli a capo e il rientro (un `;` finale oggi è tollerato, ma non serve).","en":"Line breaks and indentation take their place (a trailing `;` is tolerated today, but not needed)."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'indented'),2,2,'{"it":"Che cosa definisce un blocco in `.sass`?","en":"What defines a block in `.sass`?"}','[{"it":"Le parentesi","en":"Brackets"},{"it":"Il rientro","en":"Indentation"},{"it":"La parola `end`","en":"The word `end`"},{"it":"Il colore","en":"The colour"}]',1,'{"it":"Un rientro sbagliato cambia il significato o dà errore.","en":"Wrong indentation changes the meaning or raises an error."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'indented'),3,2,'{"it":"Il CSS prodotto da `.sass` e `.scss` è diverso?","en":"Is the CSS produced by `.sass` and `.scss` different?"}','[{"it":"Sì, sempre","en":"Yes, always"},{"it":"No, è lo stesso","en":"No, it is the same"},{"it":"Solo nei colori","en":"Only in colours"},{"it":"Solo nelle media query","en":"Only in media queries"}]',1,'{"it":"Sono due sintassi dello stesso linguaggio.","en":"They are two syntaxes of the same language."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'mixins'),1,2,'{"it":"Quale simbolo definisce un mixin in `.sass`?","en":"Which symbol defines a mixin in `.sass`?"}','[{"it":"=","en":"="},{"it":"+","en":"+"},{"it":"&","en":"&"},{"it":"%","en":"%"}]',0,'{"it":"`=` equivale a `@mixin`.","en":"`=` equals `@mixin`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'mixins'),2,2,'{"it":"Quale simbolo include un mixin?","en":"Which symbol includes a mixin?"}','[{"it":"=","en":"="},{"it":"+","en":"+"},{"it":"$","en":"$"},{"it":">","en":">"}]',1,'{"it":"`+` equivale a `@include`.","en":"`+` equals `@include`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'mixins'),3,2,'{"it":"`@mixin` funziona anche in `.sass`?","en":"Does `@mixin` work in `.sass` too?"}','[{"it":"Sì","en":"Yes"},{"it":"No","en":"No"},{"it":"Solo nei partial","en":"Only in partials"},{"it":"Solo con `@use`","en":"Only with `@use`"}]',0,'{"it":"Le scorciatoie sono facoltative.","en":"The shortcuts are optional."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'choose'),1,2,'{"it":"Perché SCSS è il formato più diffuso?","en":"Why is SCSS the more common format?"}','[{"it":"È più veloce nel browser","en":"It is faster in the browser"},{"it":"È un’estensione del CSS","en":"It extends CSS"},{"it":"Produce file più piccoli","en":"It produces smaller files"},{"it":"È l’unico con i mixin","en":"It is the only one with mixins"}]',1,'{"it":"Il CSS esistente è già SCSS valido.","en":"Existing CSS is already valid SCSS."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'choose'),2,2,'{"it":"Quale opzione ricompila a ogni salvataggio?","en":"Which option recompiles on every save?"}','[{"it":"--live","en":"--live"},{"it":"--watch","en":"--watch"},{"it":"--auto","en":"--auto"},{"it":"--save","en":"--save"}]',1,'{"it":"`--watch` resta in ascolto delle modifiche.","en":"`--watch` keeps listening for changes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'choose'),3,2,'{"it":"Quale opzione minimizza il CSS?","en":"Which option minifies the CSS?"}','[{"it":"--style=compressed","en":"--style=compressed"},{"it":"--min","en":"--min"},{"it":"--small","en":"--small"},{"it":"--zip","en":"--zip"}]',0,'{"it":"Il CSS esce su una sola riga, senza spazi inutili.","en":"The CSS comes out on one line, with no needless spaces."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'maps-sass'),1,2,'{"it":"Come inizia una variabile Sass?","en":"How does a Sass variable start?"}','[{"it":"$","en":"$"},{"it":"@","en":"@"},{"it":"--","en":"--"},{"it":"#","en":"#"}]',0,'{"it":"Identica a SCSS.","en":"Same as SCSS."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'maps-sass'),2,2,'{"it":"`@each` funziona in Sass?","en":"Does `@each` work in Sass?"}','[{"it":"Sì","en":"Yes"},{"it":"Solo in SCSS","en":"Only in SCSS"},{"it":"No","en":"No"},{"it":"Solo in CSS","en":"Only in CSS"}]',0,'{"it":"Le funzioni sono le stesse.","en":"The features are the same."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'maps-sass'),3,2,'{"it":"Che cosa segna il blocco di `@each`?","en":"What marks the `@each` block?"}','[{"it":"Il rientro","en":"The indent"},{"it":"Le graffe","en":"The braces"},{"it":"Il punto e virgola","en":"The semicolon"},{"it":"Le parentesi","en":"The brackets"}]',0,'{"it":"In Sass il rientro sostituisce le graffe.","en":"In Sass indentation replaces braces."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'convert'),1,3,'{"it":"Che cosa sparisce passando a Sass?","en":"What disappears when moving to Sass?"}','[{"it":"Graffe e punti e virgola","en":"Braces and semicolons"},{"it":"Le variabili","en":"Variables"},{"it":"I mixin","en":"Mixins"},{"it":"I selettori","en":"Selectors"}]',0,'{"it":"Il resto non cambia.","en":"The rest does not change."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'convert'),2,3,'{"it":"Che cos’è `=` in Sass?","en":"What is `=` in Sass?"}','[{"it":"`@mixin`","en":"`@mixin`"},{"it":"`@include`","en":"`@include`"},{"it":"`@use`","en":"`@use`"},{"it":"`@if`","en":"`@if`"}]',0,'{"it":"`+` invece è `@include`.","en":"`+` is `@include` instead."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'convert'),3,3,'{"it":"Quale abitudine conviene?","en":"Which habit is best?"}','[{"it":"Usare una sola sintassi","en":"Using one syntax"},{"it":"Alternarle","en":"Alternating them"},{"it":"Cambiare ogni file","en":"Changing every file"},{"it":"Usarne tre","en":"Using three"}]',0,'{"it":"La coerenza rende il codice più facile da leggere.","en":"Consistency makes code easier to read."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'logic-sass'),1,3,'{"it":"A quale livello di rientro va `@else` in Sass?","en":"At which indent level does `@else` go in Sass?"}','[{"it":"Un livello più a destra del suo `@if`","en":"One level further right than its `@if`"},{"it":"Sempre a inizio riga","en":"Always at the start of the line"},{"it":"Allo stesso livello del suo `@if`","en":"At the same level as its `@if`"},{"it":"Dentro il blocco dell’`@if`","en":"Inside the `@if` block"}]',2,'{"it":"Come `if` ed `else` in Python.","en":"Like `if` and `else` in Python."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'logic-sass'),2,3,'{"it":"Come restituisce un valore una funzione Sass?","en":"How does a Sass function give back a value?"}','[{"it":"=","en":"="},{"it":"+","en":"+"},{"it":"@return","en":"@return"},{"it":"@content","en":"@content"}]',2,'{"it":"`=` e `+` sono le scorciatoie dei mixin, non delle funzioni.","en":"`=` and `+` are mixin shortcuts, not function ones."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'logic-sass'),3,3,'{"it":"Il CSS prodotto da queste regole in Sass e in SCSS è diverso?","en":"Is the CSS produced by these rules in Sass and in SCSS different?"}','[{"it":"Sì, Sass non supporta i cicli","en":"Yes, Sass does not support loops"},{"it":"Sì, Sass non ha le funzioni","en":"Yes, Sass has no functions"},{"it":"Solo nelle condizioni","en":"Only in conditions"},{"it":"No, è identico","en":"No, it is identical"}]',3,'{"it":"Le due sintassi condividono tutto il linguaggio.","en":"The two syntaxes share the whole language."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'multiline'),1,3,'{"it":"Dove può andare a capo un’istruzione senza chiudersi?","en":"Where can a statement break the line without ending?"}','[{"it":"Dentro parentesi ancora aperte","en":"Inside brackets that are still open"},{"it":"Ovunque, il rientro non conta più","en":"Anywhere, indentation no longer matters"},{"it":"Solo dopo un punto e virgola","en":"Only after a semicolon"},{"it":"Da nessuna parte","en":"Nowhere"}]',0,'{"it":"Lì l’istruzione non potrebbe finire, quindi continua.","en":"There the statement could not end, so it carries on."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'multiline'),2,3,'{"it":"Quale commento non arriva nel CSS compilato?","en":"Which comment does not reach the compiled CSS?"}','[{"it":"/* nota */","en":"/* nota */"},{"it":"/*! nota */","en":"/*! nota */"},{"it":"// nota","en":"// nota"},{"it":"<!-- nota -->","en":"<!-- nota -->"}]',2,'{"it":"`//` esiste solo nel sorgente.","en":"`//` only exists in the source."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'multiline'),3,3,'{"it":"Le graffe sono ammesse nella sintassi indentata?","en":"Are braces allowed in the indented syntax?"}','[{"it":"Sì, come in SCSS","en":"Yes, as in SCSS"},{"it":"Sì, ma solo per i mixin","en":"Yes, but only for mixins"},{"it":"No, i blocchi si aprono con il rientro","en":"No, blocks open with indentation"},{"it":"Solo nelle versioni recenti","en":"Only in recent versions"}]',2,'{"it":"Le graffe compaiono solo nell’interpolazione `#{}`.","en":"Braces only appear in `#{}` interpolation."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-base' AND slug = 'intro'),1,1,'{"it":"Che cosa serve per usare SavComponents?","en":"What do you need to use SavComponents?"}','[{"it":"Un foglio di stile e uno script","en":"A stylesheet and a script"},{"it":"React e un bundler","en":"React and a bundler"},{"it":"Node.js e npm sul server","en":"Node.js and npm on the server"},{"it":"Un plugin del browser","en":"A browser plugin"}]',0,'{"it":"`sav.css` per i token, `sav.js` per i componenti.","en":"`sav.css` for the tokens, `sav.js` for the components."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-base' AND slug = 'intro'),2,1,'{"it":"Perché la versione è scritta nell’indirizzo del CDN?","en":"Why is the version written in the CDN address?"}','[{"it":"Così un aggiornamento non cambia il sito da solo","en":"So an update does not change the site by itself"},{"it":"Perché i browser lo richiedono","en":"Because browsers require it"},{"it":"Per caricare la pagina più veloce","en":"To make the page load faster"},{"it":"Per pagare la licenza","en":"To pay for the licence"}]',0,'{"it":"Aggiorni quando vuoi tu, cambiando il numero.","en":"You update when you choose, by changing the number."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-base' AND slug = 'intro'),3,1,'{"it":"Che cos’è `<sav-button>` per il browser?","en":"What is `<sav-button>` to the browser?"}','[{"it":"Un custom element standard","en":"A standard custom element"},{"it":"Un componente React","en":"A React component"},{"it":"Un tag HTML ufficiale","en":"An official HTML tag"},{"it":"Un errore di sintassi","en":"A syntax error"}]',0,'{"it":"I custom element sono parte della piattaforma web.","en":"Custom elements are part of the web platform."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-base' AND slug = 'intro'),4,1,'{"it":"Che cosa fa la classe `sav-base` sul `<body>`?","en":"What does the `sav-base` class on `<body>` do?"}','[{"it":"Applica sfondo, testo e carattere del tema","en":"Applies the theme’s background, text and font"},{"it":"Carica lo script dei componenti","en":"Loads the components script"},{"it":"Attiva la modalità scura","en":"Turns on dark mode"},{"it":"È obbligatoria per ogni componente","en":"It is required by every component"}]',0,'{"it":"È facoltativa: i componenti funzionano anche senza.","en":"It is optional: components work without it too."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-base' AND slug = 'buttons'),1,1,'{"it":"Quale attributo sceglie il colore di significato di un pulsante?","en":"Which attribute picks a button’s colour of meaning?"}','[{"it":"variant","en":"variant"},{"it":"appearance","en":"appearance"},{"it":"color","en":"color"},{"it":"theme","en":"theme"}]',0,'{"it":"`appearance` invece cambia l’aspetto.","en":"`appearance` changes the look instead."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-base' AND slug = 'buttons'),2,1,'{"it":"Come si fa un pulsante con il solo contorno?","en":"How do you make an outline-only button?"}','[{"it":"appearance=\\"outline\\"","en":"appearance=\\"outline\\""},{"it":"variant=\\"outline\\"","en":"variant=\\"outline\\""},{"it":"border=\\"true\\"","en":"border=\\"true\\""},{"it":"style=\\"outline\\"","en":"style=\\"outline\\""}]',0,'{"it":"Aspetti: outline, soft, ghost, link.","en":"Looks: outline, soft, ghost, link."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-base' AND slug = 'buttons'),3,1,'{"it":"Che cosa serve a un pulsante con la sola icona?","en":"What does an icon-only button need?"}','[{"it":"Un `label` per gli screen reader","en":"A `label` for screen readers"},{"it":"Un `title` lunghissimo","en":"A very long `title`"},{"it":"Niente, l’icona basta","en":"Nothing, the icon is enough"},{"it":"La forma `pill`","en":"The `pill` shape"}]',0,'{"it":"Senza testo, `label` dà il nome accessibile.","en":"Without text, `label` gives the accessible name."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-base' AND slug = 'buttons'),4,1,'{"it":"Che cosa succede con l’attributo `href` su `<sav-button>`?","en":"What happens with the `href` attribute on `<sav-button>`?"}','[{"it":"Diventa un link","en":"It becomes a link"},{"it":"Invia il form","en":"It submits the form"},{"it":"Viene ignorato","en":"It is ignored"},{"it":"Scarica un file sempre","en":"It always downloads a file"}]',0,'{"it":"Aspetto da pulsante, comportamento da link.","en":"Button looks, link behaviour."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-base' AND slug = 'layout'),1,1,'{"it":"Come si mette un titolo nella zona `header` di una card?","en":"How do you put a heading in a card’s `header` area?"}','[{"it":"Con `slot=\\"header\\"` sull’elemento","en":"With `slot=\\"header\\"` on the element"},{"it":"Con `class=\\"header\\"`","en":"With `class=\\"header\\"`"},{"it":"Con `<sav-header>` dentro la card","en":"With `<sav-header>` inside the card"},{"it":"Con l’attributo `header` sulla card","en":"With the `header` attribute on the card"}]',0,'{"it":"Gli slot hanno un nome; ciò che non ne indica uno va nel corpo.","en":"Slots have names; whatever names none goes in the body."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-base' AND slug = 'layout'),2,1,'{"it":"Che cosa fa `<sav-grid min=\\"240px\\">`?","en":"What does `<sav-grid min=\\"240px\\">` do?"}','[{"it":"Crea quante colonne da 240px ci stanno","en":"Makes as many 240px columns as fit"},{"it":"Crea sempre 240 colonne","en":"Always makes 240 columns"},{"it":"Limita la griglia a 240px","en":"Limits the grid to 240px"},{"it":"Imposta lo spazio tra le celle","en":"Sets the gap between cells"}]',0,'{"it":"Per lo spazio c’è `gap`.","en":"Spacing is `gap`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-base' AND slug = 'layout'),3,1,'{"it":"Quale attributo rende una card cliccabile con effetto al passaggio?","en":"Which attribute makes a card clickable with a hover effect?"}','[{"it":"interactive","en":"interactive"},{"it":"clickable","en":"clickable"},{"it":"hover","en":"hover"},{"it":"button","en":"button"}]',0,'{"it":"`appearance` invece è elevated o flat.","en":"`appearance` is elevated or flat instead."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-base' AND slug = 'feedback'),1,1,'{"it":"Come si chiude da solo un `<sav-alert>` dopo 5 secondi?","en":"How does a `<sav-alert>` close by itself after 5 seconds?"}','[{"it":"duration=\\"5000\\"","en":"duration=\\"5000\\""},{"it":"timeout=\\"5\\"","en":"timeout=\\"5\\""},{"it":"closable=\\"5s\\"","en":"closable=\\"5s\\""},{"it":"delay=\\"5000\\"","en":"delay=\\"5000\\""}]',0,'{"it":"Il valore è in millisecondi.","en":"The value is in milliseconds."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-base' AND slug = 'feedback'),2,1,'{"it":"Dove compare un toast se non indichi `placement`?","en":"Where does a toast appear if you give no `placement`?"}','[{"it":"In basso a destra","en":"At the bottom right"},{"it":"In alto al centro","en":"At the top centre"},{"it":"Al centro dello schermo","en":"In the middle of the screen"},{"it":"In cima alla pagina","en":"At the top of the page"}]',0,'{"it":"Il valore predefinito è `bottom-end`.","en":"The default is `bottom-end`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-base' AND slug = 'feedback'),3,1,'{"it":"Quale componente usi quando non sai quanto manca alla fine?","en":"Which component do you use when you do not know how long is left?"}','[{"it":"Una progress bar con `indeterminate`","en":"A progress bar with `indeterminate`"},{"it":"Un `<sav-alert>` con `duration`","en":"A `<sav-alert>` with `duration`"},{"it":"Un `<sav-badge>` con `pulse`","en":"A `<sav-badge>` with `pulse`"},{"it":"Un `<sav-divider>`","en":"A `<sav-divider>`"}]',0,'{"it":"Senza percentuale, si mostra solo che sta lavorando.","en":"Without a percentage, it only shows that work is going on."}',NULL);
