INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-base' AND slug = 'forms'),4,1,'{"it":"Che cosa succede se un `<sav-input required>` è vuoto e invii il form?","en":"What happens if a `<sav-input required>` is empty and you submit the form?"}','[{"it":"L’invio si blocca e compare il messaggio","en":"Submission stops and the message appears"},{"it":"Il form parte lo stesso","en":"The form is sent anyway"},{"it":"La pagina si ricarica vuota","en":"The page reloads empty"},{"it":"Compare un errore in console","en":"An error appears in the console"}]',0,'{"it":"La validazione è quella del browser.","en":"Validation is the browser’s own."}',NULL);
