INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-base' AND slug = 'lists-details'),3,2,'{"it":"Dove scrivi la riga cliccabile di un `<sav-details>`?","en":"Where do you write the clickable line of a `<sav-details>`?"}','[{"it":"Tra i tag, prima del contenuto","en":"Between the tags, before the content"},{"it":"Nell’attributo `label`","en":"In the `label` attribute"},{"it":"Nell’attributo `summary`","en":"In the `summary` attribute"},{"it":"In un `<h3>` obbligatorio","en":"In a required `<h3>`"}]',2,'{"it":"Tra i tag va il contenuto che si apre (per un titolo ricco c’è lo slot `summary`).","en":"Between the tags goes the content that opens (for a rich title there is the `summary` slot)."}',NULL);
