INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-base' AND slug = 'special-fields'),2,2,'{"it":"Che cosa fa `min-strength=\\"3\\"` su `<sav-password>`?","en":"What does `min-strength=\\"3\\"` do on `<sav-password>`?"}','[{"it":"Mostra tre regole","en":"Shows three rules"},{"it":"Il form rifiuta le password con punteggio sotto 3","en":"The form refuses passwords scoring below 3"},{"it":"Chiede almeno tre simboli","en":"Asks for at least three symbols"},{"it":"Permette tre tentativi","en":"Allows three attempts"}]',1,'{"it":"Il punteggio va da 0 a 4; 0 non rifiuta mai.","en":"The score goes from 0 to 4; 0 never refuses."}',NULL);
