INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-intermediate' AND slug = 'modes-styles'),2,2,'{"it":"Si può avere una sola sezione scura in una pagina chiara?","en":"Can you have a single dark section in a light page?"}','[{"it":"Sì, con la classe sul contenitore","en":"Yes, with the class on the container"},{"it":"No, vale solo su `<html>`","en":"No, it only works on `<html>`"},{"it":"Solo con un secondo foglio di stile","en":"Only with a second stylesheet"},{"it":"Solo dentro un iframe","en":"Only inside an iframe"}]',0,'{"it":"I token si ereditano come ogni proprietà CSS.","en":"Tokens are inherited like any CSS property."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-intermediate' AND slug = 'modes-styles'),3,2,'{"it":"Perché uno stile come Brutal funziona anche in modalità scura?","en":"Why does a style like Brutal work in dark mode too?"}','[{"it":"Perché cambia solo i token di forma e profondità","en":"Because it only changes shape and depth tokens"},{"it":"Perché contiene già due temi completi","en":"Because it already contains two full themes"},{"it":"Perché disattiva i colori","en":"Because it turns colours off"},{"it":"Perché si carica dopo lo script","en":"Because it loads after the script"}]',0,'{"it":"Colore e stile sono indipendenti.","en":"Colour and style are independent."}',NULL);
