INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-intermediate' AND slug = 'tokens'),4,2,'{"it":"Che cosa fa `Sav.setTheme({ primary: \\"\\" })`?","en":"What does `Sav.setTheme({ primary: \\"\\" })` do?"}','[{"it":"Toglie il token, tornando al valore del tema","en":"Removes the token, going back to the theme’s value"},{"it":"Rende il primario trasparente","en":"Makes the primary transparent"},{"it":"Genera un errore","en":"Throws an error"},{"it":"Imposta il primario a nero","en":"Sets the primary to black"}]',0,'{"it":"Un valore vuoto rimuove la proprietà.","en":"An empty value removes the property."}',NULL);
