INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-intermediate' AND slug = 'events-validation'),1,2,'{"it":"Come impedisci che un tag venga rimosso quando l’utente tocca la ✕?","en":"How do you stop a tag from being removed when the user taps the ✕?"}','[{"it":"`preventDefault()` nell’evento `sav-remove`","en":"`preventDefault()` in the `sav-remove` event"},{"it":"`return false` nell’attributo `removable`","en":"`return false` in the `removable` attribute"},{"it":"Togliendo il tag dal DOM","en":"By removing the tag from the DOM"},{"it":"Con `stopPropagation()` sul form","en":"With `stopPropagation()` on the form"}]',0,'{"it":"`sav-remove` è annullabile.","en":"`sav-remove` is cancelable."}',NULL);
