INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-intermediate' AND slug = 'events-validation'),4,2,'{"it":"A che cosa serve `customElements.whenDefined(\\"sav-input\\")`?","en":"What is `customElements.whenDefined(\\"sav-input\\")` for?"}','[{"it":"Ad aspettare che il componente sia pronto","en":"To wait until the component is ready"},{"it":"A registrare un nuovo componente","en":"To register a new component"},{"it":"A controllare se il campo è valido","en":"To check whether the field is valid"},{"it":"A scaricare la libreria","en":"To download the library"}]',0,'{"it":"Restituisce una Promise.","en":"It returns a Promise."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-intermediate' AND slug = 'data-media'),1,3,'{"it":"Che cosa contiene un `<sav-table>`?","en":"What does a `<sav-table>` contain?"}','[{"it":"Una normale `<table>` HTML","en":"An ordinary HTML `<table>`"},{"it":"Un attributo JSON con le righe","en":"A JSON attribute with the rows"},{"it":"Dei `<sav-row>`","en":"Some `<sav-row>`s"},{"it":"Un file CSV collegato","en":"A linked CSV file"}]',0,'{"it":"I dati restano HTML accessibile.","en":"The data stays accessible HTML."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-intermediate' AND slug = 'data-media'),2,3,'{"it":"In che formato passi i dati a `<sav-chart-bar>`?","en":"In what format do you pass data to `<sav-chart-bar>`?"}','[{"it":"JSON nell’attributo `data`","en":"JSON in the `data` attribute"},{"it":"Una tabella dentro il tag","en":"A table inside the tag"},{"it":"Un file Excel","en":"An Excel file"},{"it":"Attributi `value-1`, `value-2`…","en":"`value-1`, `value-2`… attributes"}]',0,'{"it":"`labels` e `values`, oppure `series`.","en":"`labels` and `values`, or `series`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-intermediate' AND slug = 'data-media'),3,3,'{"it":"Come evidenzi le righe 3, 4 e 5 in un `<sav-code-block>`?","en":"How do you highlight lines 3, 4 and 5 in a `<sav-code-block>`?"}','[{"it":"highlight=\\"3-5\\"","en":"highlight=\\"3-5\\""},{"it":"lines=\\"3,5\\"","en":"lines=\\"3,5\\""},{"it":"mark=\\"3:5\\"","en":"mark=\\"3:5\\""},{"it":"focus=\\"3-5\\"","en":"focus=\\"3-5\\""}]',0,'{"it":"Accetta numeri e intervalli separati da virgole.","en":"It accepts numbers and ranges separated by commas."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-intermediate' AND slug = 'data-media'),4,3,'{"it":"Perché dare un `label` a un grafico?","en":"Why give a chart a `label`?"}','[{"it":"È la sua descrizione accessibile","en":"It is its accessible description"},{"it":"Per cambiarne il colore","en":"To change its colour"},{"it":"Per esportarlo in PDF","en":"To export it as a PDF"},{"it":"Senza non si disegna","en":"It does not draw without it"}]',0,'{"it":"Chi non vede il grafico ne sente il titolo.","en":"Whoever cannot see the chart hears its title."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-intermediate' AND slug = 'icons-integration'),1,3,'{"it":"Come aggiungi un’icona tua alla libreria?","en":"How do you add your own icon to the library?"}','[{"it":"Sav.registerIcon(nome, svg)","en":"Sav.registerIcon(nome, svg)"},{"it":"Sav.icon.add(svg)","en":"Sav.icon.add(svg)"},{"it":"<sav-icon src=\\"…\\">","en":"<sav-icon src=\\"…\\">"},{"it":"Sav.addIcon(svg, nome)","en":"Sav.addIcon(svg, nome)"}]',0,'{"it":"Passi il nome e le forme SVG su una griglia 24×24.","en":"You pass the name and the SVG shapes on a 24×24 grid."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-intermediate' AND slug = 'icons-integration'),2,3,'{"it":"Che cosa resta compito tuo per l’accessibilità?","en":"What remains your job for accessibility?"}','[{"it":"Label, alt e contrasto dei colori","en":"Labels, alts and colour contrast"},{"it":"La gestione della tastiera","en":"Keyboard handling"},{"it":"I ruoli ARIA di ogni componente","en":"Every component’s ARIA roles"},{"it":"Niente, fa tutto la libreria","en":"Nothing, the library does it all"}]',0,'{"it":"La libreria non conosce i tuoi contenuti.","en":"The library does not know your content."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-intermediate' AND slug = 'icons-integration'),3,3,'{"it":"Come ascolti `sav-select` di un dropdown in un’app React?","en":"How do you listen to a dropdown’s `sav-select` in a React app?"}','[{"it":"Con `addEventListener` su un riferimento all’elemento","en":"With `addEventListener` on a reference to the element"},{"it":"Non si può, serve una versione React","en":"You cannot, you need a React version"},{"it":"Con `onClick` sul dropdown","en":"With `onClick` on the dropdown"},{"it":"Con un `<form>` attorno","en":"With a `<form>` around it"}]',0,'{"it":"Sono eventi DOM standard.","en":"They are standard DOM events."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-intermediate' AND slug = 'menus-breadcrumbs'),1,3,'{"it":"Come metti un sottomenu dentro una voce di `<sav-menu>`?","en":"How do you put a submenu inside a `<sav-menu>` item?"}','[{"it":"Con un `<sav-menu slot=\\"submenu\\">` dentro la voce","en":"With a `<sav-menu slot=\\"submenu\\">` inside the item"},{"it":"Con l’attributo `submenu` sulla voce","en":"With the `submenu` attribute on the item"},{"it":"Con un `<sav-dropdown>` accanto alla voce","en":"With a `<sav-dropdown>` next to the item"},{"it":"Con un tag `<sav-submenu>`","en":"With a `<sav-submenu>` tag"}]',0,'{"it":"Un sottomenu può contenere altri sottomenu.","en":"A submenu can hold further submenus."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-intermediate' AND slug = 'menus-breadcrumbs'),2,3,'{"it":"Che cosa fa `max-items=\\"3\\"` su `<sav-breadcrumb>`?","en":"What does `max-items=\\"3\\"` do on `<sav-breadcrumb>`?"}','[{"it":"Cancella le voci oltre la terza","en":"Deletes the items after the third"},{"it":"Ripiega le voci di mezzo dietro «…»","en":"Folds the middle items behind “…”"},{"it":"Rifiuta più di tre voci","en":"Refuses more than three items"},{"it":"Divide il percorso su tre righe","en":"Splits the path over three lines"}]',1,'{"it":"Restano la prima voce e le ultime; «…» riapre il resto.","en":"The first and last items stay; “…” opens the rest."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-intermediate' AND slug = 'menus-breadcrumbs'),3,3,'{"it":"Quale attributo trasforma un `<sav-menu>` in una colonna di sole icone?","en":"Which attribute turns a `<sav-menu>` into a column of icons only?"}','[{"it":"compact","en":"compact"},{"it":"icons-only","en":"icons-only"},{"it":"collapsed","en":"collapsed"},{"it":"mini","en":"mini"}]',2,'{"it":"`collapsible` aggiunge il pulsante per aprirla e chiuderla.","en":"`collapsible` adds the button to open and close it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-intermediate' AND slug = 'phones'),1,3,'{"it":"Che cosa fa `sheet-on-mobile` su un `<sav-select>`?","en":"What does `sheet-on-mobile` do on a `<sav-select>`?"}','[{"it":"Fino a 640px la lista sale dal basso a tutta larghezza","en":"Up to 640px the list rises from the bottom, full width"},{"it":"Usa sempre il menu del sistema operativo","en":"Always uses the operating system menu"},{"it":"Nasconde il campo sui telefoni","en":"Hides the field on phones"},{"it":"Ingrandisce il testo del campo","en":"Enlarges the field’s text"}]',0,'{"it":"Per il selettore del telefono c’è `native-on-mobile`.","en":"For the phone’s own picker there is `native-on-mobile`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-intermediate' AND slug = 'phones'),2,3,'{"it":"Come mostri una `<sav-bottom-nav>` fissata in basso solo sui telefoni?","en":"How do you show a `<sav-bottom-nav>` pinned to the bottom on phones only?"}','[{"it":"sticky phone","en":"sticky phone"},{"it":"position=\\"bottom\\" small","en":"position=\\"bottom\\" small"},{"it":"fixed mobile-only","en":"fixed mobile-only"},{"it":"responsive bottom","en":"responsive bottom"}]',2,'{"it":"`mobile-only` funziona insieme a `fixed`.","en":"`mobile-only` works together with `fixed`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-intermediate' AND slug = 'phones'),3,3,'{"it":"Che cosa fa una `<sav-grid columns=\\"3\\">` su un telefono?","en":"What does a `<sav-grid columns=\\"3\\">` do on a phone?"}','[{"it":"Resta sempre a tre colonne","en":"Always stays at three columns"},{"it":"Passa a una colonna, salvo `keep` o `--mobile-columns`","en":"Drops to one column, unless `keep` or `--mobile-columns`"},{"it":"Sparisce","en":"Disappears"},{"it":"Diventa un carosello","en":"Becomes a carousel"}]',1,'{"it":"Le colonne fisse non ci starebbero su uno schermo stretto.","en":"Fixed columns would not fit on a narrow screen."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'parts-variables'),1,3,'{"it":"Quale di queste regole non raggiunge niente?","en":"Which of these rules reaches nothing?"}','[{"it":"sav-card h3 { color: red }","en":"sav-card h3 { color: red }"},{"it":"sav-card::part(header) { color: red }","en":"sav-card::part(header) { color: red }"},{"it":"sav-input input { color: red }","en":"sav-input input { color: red }"},{"it":":root { --sav-radius: 0 }","en":":root { --sav-radius: 0 }"}]',2,'{"it":"L’`<input>` vive nello shadow DOM del campo: si raggiunge con `::part(input)`.","en":"The `<input>` lives in the field’s shadow DOM: you reach it with `::part(input)`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'parts-variables'),2,3,'{"it":"Come allarghi un solo dialogo?","en":"How do you widen a single dialog?"}','[{"it":"width=\\"48rem\\"","en":"width=\\"48rem\\""},{"it":"size=\\"xl\\"","en":"size=\\"xl\\""},{"it":"style=\\"--width: 48rem\\"","en":"style=\\"--width: 48rem\\""},{"it":"style=\\"max-width: 48rem\\"","en":"style=\\"max-width: 48rem\\""}]',2,'{"it":"Il dialogo legge la variabile `--width`.","en":"The dialog reads the `--width` variable."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'parts-variables'),3,3,'{"it":"Dove trovi i nomi delle parti di un componente?","en":"Where do you find the names of a component’s parts?"}','[{"it":"Negli attributi `part` che scrivi tu nell’HTML","en":"In the `part` attributes you write in the HTML"},{"it":"Nel file `sav.css`","en":"In the `sav.css` file"},{"it":"Da nessuna parte: si indovinano","en":"Nowhere: you guess them"},{"it":"Sulla pagina del componente nella documentazione","en":"On the component’s page in the documentation"}]',3,'{"it":"Ogni pagina ha la sezione delle parti CSS.","en":"Every page has a CSS parts section."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'shapes-tilt'),1,3,'{"it":"Che cosa fa `shape=\\"rounded\\"` su un `<div>`?","en":"What does `shape=\\"rounded\\"` do on a `<div>`?"}','[{"it":"Arrotonda tutti i componenti al suo interno","en":"Rounds every component inside it"},{"it":"Arrotonda solo gli angoli del div","en":"Rounds only the div’s corners"},{"it":"Niente: vale solo sui tag sav-","en":"Nothing: it only works on sav- tags"},{"it":"Cambia lo stile di tutta la pagina","en":"Changes the style of the whole page"}]',0,'{"it":"Su un contenitore vale per tutto ciò che contiene.","en":"On a container it applies to everything inside."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'shapes-tilt'),2,3,'{"it":"Nello stile Tilt, perché un pulsante lungo pende meno di uno corto?","en":"In the Tilt style, why does a long button lean less than a short one?"}','[{"it":"Perché i pulsanti lunghi usano `shape=\\"squared\\"`","en":"Because long buttons use `shape=\\"squared\\"`"},{"it":"Perché ogni elemento alza gli angoli della stessa misura","en":"Because every element lifts its corners by the same amount"},{"it":"Per un errore di arrotondamento del browser","en":"Because of a browser rounding error"},{"it":"Perché l’angolo dipende dal numero di lettere","en":"Because the angle depends on the number of letters"}]',1,'{"it":"Stesso sollevamento su una base più lunga: angolo più piccolo.","en":"Same lift over a longer base: a smaller angle."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'shapes-tilt'),3,3,'{"it":"Come dai a tutti gli elementi lo stesso angolo di −2°?","en":"How do you give every element the same −2° angle?"}','[{"it":"transform: rotate(-2deg)","en":"transform: rotate(-2deg)"},{"it":"shape=\\"tilt-2\\"","en":"shape=\\"tilt-2\\""},{"it":"--sav-tilt-lift: -2deg","en":"--sav-tilt-lift: -2deg"},{"it":"--sav-tilt: -2deg","en":"--sav-tilt: -2deg"}]',3,'{"it":"`--sav-tilt-lift` è una lunghezza, non un angolo.","en":"`--sav-tilt-lift` is a length, not an angle."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'live-data'),1,3,'{"it":"Come passi a un grafico un oggetto JavaScript senza trasformarlo in testo?","en":"How do you pass a JavaScript object to a chart without turning it into text?"}','[{"it":"grafico.setAttribute(\\"data\\", oggetto)","en":"grafico.setAttribute(\\"data\\", oggetto)"},{"it":"grafico.data = oggetto","en":"grafico.data = oggetto"},{"it":"grafico.innerHTML = oggetto","en":"grafico.innerHTML = oggetto"},{"it":"Sav.chart(grafico, oggetto)","en":"Sav.chart(grafico, oggetto)"}]',1,'{"it":"Con `setAttribute` l’oggetto diventerebbe la stringa «[object Object]».","en":"With `setAttribute` the object would become the string “[object Object]”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'live-data'),2,3,'{"it":"Che cosa fa `no-filter` su `<sav-search>`?","en":"What does `no-filter` do on `<sav-search>`?"}','[{"it":"Mostra i suggerimenti come li manda la pagina, senza filtrarli","en":"Shows the suggestions as the page sends them, without filtering"},{"it":"Disattiva i suggerimenti","en":"Turns suggestions off"},{"it":"Toglie la ✕ che svuota il campo","en":"Removes the ✕ that empties the field"},{"it":"Accetta qualsiasi carattere","en":"Accepts any character"}]',0,'{"it":"Il filtro lo ha già fatto il server.","en":"The server has already filtered them."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'live-data'),3,3,'{"it":"Con `<sav-select multiple>`, che cosa restituisce la proprietà `.value`?","en":"With `<sav-select multiple>`, what does the `.value` property return?"}','[{"it":"Il numero di voci scelte","en":"The number of chosen entries"},{"it":"Solo il primo valore","en":"Only the first value"},{"it":"Un array dei valori scelti","en":"An array of the chosen values"},{"it":"Un oggetto FormData","en":"A FormData object"}]',2,'{"it":"Nell’attributo `value` invece la lista è separata da virgole.","en":"In the `value` attribute the list is comma-separated instead."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'charts'),1,3,'{"it":"Come metti una sopra l’altra le serie di un `<sav-chart-bar>`?","en":"How do you pile up the series of a `<sav-chart-bar>`?"}','[{"it":"mode=\\"stack\\"","en":"mode=\\"stack\\""},{"it":"stack=\\"true\\"","en":"stack=\\"true\\""},{"it":"stacked","en":"stacked"},{"it":"series-stacked","en":"series-stacked"}]',2,'{"it":"È un attributo booleano, come per le aree.","en":"It is a boolean attribute, as for areas."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'charts'),2,3,'{"it":"Quale formato accetta `<sav-chart-map>`?","en":"Which format does `<sav-chart-map>` accept?"}','[{"it":"Un oggetto con i codici dei paesi come chiavi","en":"An object with country codes as keys"},{"it":"Una lista di coordinate GPS","en":"A list of GPS coordinates"},{"it":"Un file GeoJSON da caricare","en":"A GeoJSON file to load"},{"it":"Una tabella HTML dentro il tag","en":"An HTML table inside the tag"}]',0,'{"it":"Per esempio `{\\"IT\\": 40, \\"FRA\\": 12}`.","en":"For example `{\\"IT\\": 40, \\"FRA\\": 12}`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'charts'),3,3,'{"it":"Come cambi il colore della seconda serie in tutti i grafici di una sezione?","en":"How do you change the colour of the second series in every chart of a section?"}','[{"it":"--sav-color-chart","en":"--sav-color-chart"},{"it":"--sav-chart-2","en":"--sav-chart-2"},{"it":"--sav-series-2","en":"--sav-series-2"},{"it":"color-2=\\"…\\"","en":"color-2=\\"…\\""}]',1,'{"it":"Le variabili vanno da `--sav-chart-1` a `--sav-chart-8`.","en":"The variables go from `--sav-chart-1` to `--sav-chart-8`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'drag-drop'),1,3,'{"it":"Con la tastiera, come sposti un elemento in `<sav-sortable>`?","en":"With the keyboard, how do you move an item in `<sav-sortable>`?"}','[{"it":"Tab per prenderlo e Invio per lasciarlo","en":"Tab to pick it up and Enter to drop it"},{"it":"Spazio per prenderlo, frecce per spostarlo, Spazio per lasciarlo","en":"Space to pick it up, arrows to move it, Space to drop it"},{"it":"Non si può: serve il mouse","en":"You cannot: you need the mouse"},{"it":"Ctrl e le frecce, senza prenderlo","en":"Ctrl and the arrows, without picking it up"}]',1,'{"it":"Esc annulla e lo riporta al suo posto.","en":"Esc cancels and puts it back."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'drag-drop'),2,3,'{"it":"Che cosa contiene `e.detail.order` nell’evento `sav-sort`?","en":"What does `e.detail.order` contain in the `sav-sort` event?"}','[{"it":"L’indice dell’elemento spostato","en":"The index of the moved item"},{"it":"L’HTML della lista","en":"The list’s HTML"},{"it":"I `data-id` degli elementi nel nuovo ordine","en":"The `data-id`s of the items in the new order"},{"it":"Il numero di spostamenti fatti","en":"The number of moves made"}]',2,'{"it":"Gli indici sono in `from` e `to`.","en":"The indexes are in `from` and `to`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'drag-drop'),3,3,'{"it":"Che cosa fa `max-size=\\"2000000\\"` su `<sav-dropzone>`?","en":"What does `max-size=\\"2000000\\"` do on `<sav-dropzone>`?"}','[{"it":"Accetta al massimo due file","en":"Accepts two files at most"},{"it":"Rifiuta i file più grandi di circa 2 MB","en":"Refuses files larger than about 2 MB"},{"it":"Comprime i file a 2 MB","en":"Compresses files to 2 MB"},{"it":"Limita l’area a 2000 pixel","en":"Limits the area to 2000 pixels"}]',1,'{"it":"Il valore è in byte.","en":"The value is in bytes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'frameworks-ssr'),1,3,'{"it":"Che cosa serve a Vue per usare i tag `sav-*`?","en":"What does Vue need to use the `sav-*` tags?"}','[{"it":"Un plugin SavComponents per Vue","en":"A SavComponents plugin for Vue"},{"it":"`isCustomElement` nelle opzioni del compilatore","en":"`isCustomElement` in the compiler options"},{"it":"`v-model` su ogni campo","en":"`v-model` on every field"},{"it":"Registrarli con `app.component()`","en":"Registering them with `app.component()`"}]',1,'{"it":"Così Vue non li cerca tra i suoi componenti.","en":"That way Vue does not look for them among its components."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'frameworks-ssr'),2,3,'{"it":"In Angular, come imposti un attributo su un componente sav?","en":"In Angular, how do you set an attribute on a sav component?"}','[{"it":"(nome)=\\"…\\"","en":"(nome)=\\"…\\""},{"it":"v-bind:nome=\\"…\\"","en":"v-bind:nome=\\"…\\""},{"it":"[attr.nome]=\\"…\\"","en":"[attr.nome]=\\"…\\""},{"it":"{nome}","en":"{nome}"}]',2,'{"it":"`[nome]` invece imposta la proprietà.","en":"`[name]` sets the property instead."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'frameworks-ssr'),3,3,'{"it":"Con Next.js, dove chiami `Sav.setMode()`?","en":"With Next.js, where do you call `Sav.setMode()`?"}','[{"it":"Nel codice che gira sul server","en":"In the code that runs on the server"},{"it":"Nel file di configurazione","en":"In the configuration file"},{"it":"Solo nel browser, per esempio in un effect","en":"Only in the browser, for example in an effect"},{"it":"In un middleware","en":"In a middleware"}]',2,'{"it":"Sul server `Sav` non esiste: lo crea lo script nel browser.","en":"On the server `Sav` does not exist: the script creates it in the browser."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'hosting-a11y'),1,3,'{"it":"Che cosa garantisce un aggiornamento da 1.0.0 a una 1.x?","en":"What does an update from 1.0.0 to a 1.x guarantee?"}','[{"it":"Che il sito si aggiorni da solo","en":"That the site updates itself"},{"it":"Nuovi nomi per i tag","en":"New names for the tags"},{"it":"Che i temi salvati si cancellino","en":"That saved themes get deleted"},{"it":"Stessi tag, attributi e token: niente da modificare","en":"Same tags, attributes and tokens: nothing to change"}]',3,'{"it":"Solo una nuova versione principale può chiedere modifiche.","en":"Only a new major version can ask for changes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'hosting-a11y'),2,3,'{"it":"Ospiti `sav.js` sul tuo server ma vuoi le icone da un tuo CDN: che cosa usi?","en":"You host `sav.js` on your server but want the icons from your own CDN: what do you use?"}','[{"it":"Sav.version","en":"Sav.version"},{"it":"<link rel=\\"icons\\">","en":"<link rel=\\"icons\\">"},{"it":"data-icon-base sul tag script","en":"data-icon-base sul tag script"},{"it":"icon-src su ogni sav-icon","en":"icon-src su ogni sav-icon"}]',2,'{"it":"In alternativa, `Sav.iconBase` da JavaScript.","en":"Alternatively, `Sav.iconBase` from JavaScript."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'savcomponents-advanced' AND slug = 'hosting-a11y'),3,3,'{"it":"Che cosa succede se `sav.js` viene caricato due volte?","en":"What happens if `sav.js` is loaded twice?"}','[{"it":"Ogni componente compare due volte","en":"Every component appears twice"},{"it":"La seconda copia si ferma subito perché trova già Sav","en":"The second copy stops at once because it finds Sav already"},{"it":"Il browser blocca la pagina con un errore","en":"The browser blocks the page with an error"},{"it":"La seconda copia cancella la prima","en":"The second copy wipes out the first"}]',1,'{"it":"Anche i tag già definiti non vengono ridefiniti.","en":"Tags already defined are not defined again either."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'utilities'),1,1,'{"it":"Che cosa fa `p-4`?","en":"What does `p-4` do?"}','[{"it":"Padding di 1rem","en":"Padding of 1rem"},{"it":"Margine di 4px","en":"Margin of 4px"},{"it":"4 paragrafi","en":"4 paragraphs"},{"it":"Posizione 4","en":"Position 4"}]',0,'{"it":"La scala di Tailwind va a passi di 0,25rem.","en":"Tailwind’s scale goes in steps of 0.25rem."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'utilities'),2,1,'{"it":"Dove si scrivono le classi di Tailwind?","en":"Where do you write Tailwind classes?"}','[{"it":"Nell’attributo `class` dell’HTML","en":"In the HTML `class` attribute"},{"it":"In un file .js","en":"In a .js file"},{"it":"Nel `<title>`","en":"In the `<title>`"},{"it":"Nel database","en":"In the database"}]',0,'{"it":"Lo stile vive accanto al markup.","en":"Style lives next to the markup."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'utilities'),3,1,'{"it":"Quale classe rende il testo in grassetto?","en":"Which class makes text bold?"}','[{"it":"font-bold","en":"font-bold"},{"it":"text-bold","en":"text-bold"},{"it":"bold","en":"bold"},{"it":"weight-700","en":"weight-700"}]',0,'{"it":"`font-` riguarda peso e famiglia.","en":"`font-` is about weight and family."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'flex-grid'),1,1,'{"it":"Quale classe centra gli elementi in verticale in un flex?","en":"Which class centres items vertically in a flex?"}','[{"it":"items-center","en":"items-center"},{"it":"justify-center","en":"justify-center"},{"it":"text-center","en":"text-center"},{"it":"align-middle","en":"align-middle"}]',0,'{"it":"`items-` lavora sull’asse trasversale.","en":"`items-` works on the cross axis."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'flex-grid'),2,1,'{"it":"Come si fanno 3 colonne?","en":"How do you make 3 columns?"}','[{"it":"grid grid-cols-3","en":"grid grid-cols-3"},{"it":"flex cols-3","en":"flex cols-3"},{"it":"columns 3","en":"columns 3"},{"it":"grid-3","en":"grid-3"}]',0,'{"it":"Prima `grid`, poi il numero di colonne.","en":"First `grid`, then the number of columns."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'flex-grid'),3,1,'{"it":"Che cosa fa `gap-4`?","en":"What does `gap-4` do?"}','[{"it":"Spazio tra gli elementi","en":"Space between items"},{"it":"Bordo","en":"Border"},{"it":"Ombra","en":"Shadow"},{"it":"Margine esterno","en":"Outer margin"}]',0,'{"it":"Funziona con flex e grid.","en":"It works with flex and grid."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'responsive'),1,1,'{"it":"Da quale larghezza vale `md:`?","en":"From which width does `md:` apply?"}','[{"it":"768px","en":"768px"},{"it":"640px","en":"640px"},{"it":"1024px","en":"1024px"},{"it":"320px","en":"320px"}]',0,'{"it":"`sm` 640, `md` 768, `lg` 1024.","en":"`sm` 640, `md` 768, `lg` 1024."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'responsive'),2,1,'{"it":"Che cosa significa mobile first?","en":"What does mobile first mean?"}','[{"it":"Le classi senza prefisso valgono per tutti, poi si aggiunge per schermi grandi","en":"Classes without a prefix apply to all, then you add for big screens"},{"it":"Il sito funziona solo sui telefoni","en":"The site only works on phones"},{"it":"Si scrive prima il CSS desktop, poi si tolgono le regole per i telefoni","en":"You write desktop CSS first, then remove rules for phones"},{"it":"Le immagini sono piccole","en":"Images are small"}]',0,'{"it":"Si parte dallo schermo più piccolo.","en":"You start from the smallest screen."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'responsive'),3,1,'{"it":"Come mostri un elemento solo da `lg` in su?","en":"How do you show an element only from `lg` up?"}','[{"it":"hidden lg:block","en":"hidden lg:block"},{"it":"lg:hidden","en":"lg:hidden"},{"it":"block lg:hidden","en":"block lg:hidden"},{"it":"show-lg","en":"show-lg"}]',0,'{"it":"Nascosto di base, visibile da `lg`.","en":"Hidden by default, visible from `lg`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'states'),1,1,'{"it":"Quale prefisso vale al passaggio del mouse?","en":"Which prefix applies on mouse over?"}','[{"it":"hover:","en":"hover:"},{"it":"focus:","en":"focus:"},{"it":"active:","en":"active:"},{"it":"over:","en":"over:"}]',0,'{"it":"Come la pseudo-classe `:hover`.","en":"Like the `:hover` pseudo-class."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'states'),2,1,'{"it":"Quale tono è più scuro?","en":"Which shade is darker?"}','[{"it":"bg-blue-900","en":"bg-blue-900"},{"it":"bg-blue-100","en":"bg-blue-100"},{"it":"bg-blue-300","en":"bg-blue-300"},{"it":"bg-blue-50","en":"bg-blue-50"}]',0,'{"it":"Più alto il numero, più scuro.","en":"The higher the number, the darker."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'states'),3,1,'{"it":"Che cosa fa `dark:bg-gray-900`?","en":"What does `dark:bg-gray-900` do?"}','[{"it":"Sfondo scuro solo con il tema scuro","en":"Dark background only in dark mode"},{"it":"Sfondo sempre scuro","en":"Always a dark background"},{"it":"Nasconde l’elemento","en":"Hides the element"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Il prefisso `dark:` segue il tema.","en":"The `dark:` prefix follows the theme."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'config'),1,1,'{"it":"Che cosa fa `@apply`?","en":"What does `@apply` do?"}','[{"it":"Raccoglie classi di utilità in una regola CSS","en":"Gathers utility classes into a CSS rule"},{"it":"Importa un file","en":"Imports a file"},{"it":"Applica un tema scuro a tutte le classi del file","en":"Applies a dark theme to every class in the file"},{"it":"Cancella le classi","en":"Deletes classes"}]',0,'{"it":"Utile per pochi componenti ripetuti.","en":"Useful for a few repeated components."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'config'),2,1,'{"it":"Dove aggiungi il colore del tuo marchio?","en":"Where do you add your brand colour?"}','[{"it":"Nel tema (`@theme` o configurazione)","en":"In the theme (`@theme` or config)"},{"it":"In ogni classe a mano","en":"In each class by hand"},{"it":"Nell’HTML con `style`","en":"In the HTML with `style`"},{"it":"Non si può","en":"You cannot"}]',0,'{"it":"Poi diventa una classe come `bg-brace`.","en":"Then it becomes a class like `bg-brace`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'config'),3,1,'{"it":"Perché il CSS di Tailwind resta piccolo?","en":"Why does Tailwind’s CSS stay small?"}','[{"it":"Genera solo le classi usate","en":"It generates only the classes used"},{"it":"Comprime le immagini","en":"It compresses images"},{"it":"Non usa CSS","en":"It uses no CSS"},{"it":"Lo carica da Google","en":"It loads it from Google"}]',0,'{"it":"Analizza i tuoi file e tiene ciò che serve.","en":"It scans your files and keeps what is needed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'install'),1,2,'{"it":"Che cosa scrivi nel file CSS per usare Tailwind v4?","en":"What do you write in the CSS file to use Tailwind v4?"}','[{"it":"@tailwind base;","en":"@tailwind base;"},{"it":"@use \\"tailwind\\";","en":"@use \\"tailwind\\";"},{"it":"@import \\"tailwindcss\\";","en":"@import \\"tailwindcss\\";"},{"it":"<script src=\\"tailwind.js\\">","en":"<script src=\\"tailwind.js\\">"}]',2,'{"it":"Le vecchie direttive `@tailwind` erano di v3.","en":"The old `@tailwind` directives belonged to v3."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'install'),2,2,'{"it":"A che cosa serve `@source`?","en":"What is `@source` for?"}','[{"it":"A indicare file in più da analizzare in cerca di classi","en":"To point to extra files to scan for classes"},{"it":"A importare un font","en":"To import a font"},{"it":"A pubblicare il sito","en":"To publish the site"},{"it":"A scegliere il tema scuro","en":"To choose the dark theme"}]',0,'{"it":"Il resto lo trova da solo.","en":"It finds the rest by itself."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'install'),3,2,'{"it":"Quali file salta Tailwind quando cerca le classi?","en":"Which files does Tailwind skip when looking for classes?"}','[{"it":"Tutti i file HTML","en":"All HTML files"},{"it":"I file con più di cento righe","en":"Files with more than a hundred lines"},{"it":"I file JavaScript","en":"JavaScript files"},{"it":"Quelli elencati in `.gitignore`","en":"Those listed in `.gitignore`"}]',3,'{"it":"Per includerne uno escluso si usa `@source`.","en":"To include an excluded one you use `@source`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'arbitrary'),1,2,'{"it":"Come scrivi una larghezza di esattamente 37px?","en":"How do you write a width of exactly 37px?"}','[{"it":"w-37","en":"w-37"},{"it":"w-[37px]","en":"w-[37px]"},{"it":"w(37px)","en":"w(37px)"},{"it":"width-37px","en":"width-37px"}]',1,'{"it":"Le parentesi quadre contengono un valore qualsiasi.","en":"Square brackets hold any value."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'arbitrary'),2,2,'{"it":"In v4, come usi la variabile `--brand` come sfondo?","en":"In v4, how do you use the `--brand` variable as a background?"}','[{"it":"bg-[--brand]","en":"bg-[--brand]"},{"it":"bg-var-brand","en":"bg-var-brand"},{"it":"bg-$brand","en":"bg-$brand"},{"it":"bg-(--brand)","en":"bg-(--brand)"}]',3,'{"it":"In v4 le variabili vanno tra parentesi tonde.","en":"In v4 variables go in round brackets."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'arbitrary'),3,2,'{"it":"Che cosa indica il trattino basso in `grid-cols-[200px_1fr]`?","en":"What does the underscore mean in `grid-cols-[200px_1fr]`?"}','[{"it":"Uno spazio","en":"A space"},{"it":"Una sottrazione","en":"A subtraction"},{"it":"Un commento","en":"A comment"},{"it":"Un errore","en":"A mistake"}]',0,'{"it":"Nelle classi non si possono scrivere spazi.","en":"Spaces cannot be written in classes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'group-peer'),1,2,'{"it":"Che cosa serve sul genitore per usare `group-hover:` sui figli?","en":"What does the parent need for `group-hover:` on its children?"}','[{"it":"La classe `group`","en":"The `group` class"},{"it":"La classe `parent`","en":"The `parent` class"},{"it":"L’attributo `hover`","en":"The `hover` attribute"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"`group` segna l’elemento da osservare.","en":"`group` marks the element to watch."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'group-peer'),2,2,'{"it":"Dove deve stare l’elemento con `peer`?","en":"Where must the element with `peer` sit?"}','[{"it":"Dopo l’elemento che reagisce","en":"After the element that reacts"},{"it":"Prima, come fratello dell’elemento che reagisce","en":"Before, as a sibling of the element that reacts"},{"it":"Dentro l’elemento che reagisce","en":"Inside the element that reacts"},{"it":"Ovunque nella pagina","en":"Anywhere on the page"}]',1,'{"it":"Il CSS sa guardare solo ai fratelli precedenti.","en":"CSS can only look at previous siblings."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'group-peer'),3,2,'{"it":"Quale prefisso reagisce a una casella spuntata contenuta nell’elemento?","en":"Which prefix reacts to a ticked box inside the element?"}','[{"it":"peer-checked:","en":"peer-checked:"},{"it":"group-checked:","en":"group-checked:"},{"it":"checked:","en":"checked:"},{"it":"has-checked:","en":"has-checked:"}]',3,'{"it":"`has-` guarda dentro, come `:has()`.","en":"`has-` looks inside, like `:has()`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'custom'),1,2,'{"it":"Come crei in v4 una classe che funziona anche con `hover:` e `md:`?","en":"How do you create in v4 a class that also works with `hover:` and `md:`?"}','[{"it":"Con una regola CSS normale","en":"With a normal CSS rule"},{"it":"Con `@apply` in un file JavaScript","en":"With `@apply` in a JavaScript file"},{"it":"Con `@utility`","en":"With `@utility`"},{"it":"Con `@layer base`","en":"With `@layer base`"}]',2,'{"it":"Tailwind la tratta come una delle sue.","en":"Tailwind treats it as one of its own."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'custom'),2,2,'{"it":"Che cosa crea `@custom-variant`?","en":"What does `@custom-variant` create?"}','[{"it":"Un nuovo colore","en":"A new colour"},{"it":"Un nuovo breakpoint fisso","en":"A new fixed breakpoint"},{"it":"Un nuovo file CSS","en":"A new CSS file"},{"it":"Un nuovo prefisso, come `tema-notte:`","en":"A new prefix, like `tema-notte:`"}]',3,'{"it":"Il selettore decide quando il prefisso vale.","en":"The selector decides when the prefix applies."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'custom'),3,2,'{"it":"Come carichi un plugin in v4?","en":"How do you load a plugin in v4?"}','[{"it":"@plugin \\"@tailwindcss/typography\\";","en":"@plugin \\"@tailwindcss/typography\\";"},{"it":"plugins: [typography]","en":"plugins: [typography]"},{"it":"@use \\"typography\\";","en":"@use \\"typography\\";"},{"it":"<script src=\\"typography.js\\">","en":"<script src=\\"typography.js\\">"}]',0,'{"it":"Direttamente nel CSS, come il resto della configurazione.","en":"Right in the CSS, like the rest of the configuration."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'container-motion'),1,2,'{"it":"A che cosa guarda `@md:flex-row`?","en":"What does `@md:flex-row` look at?"}','[{"it":"Alla larghezza dello schermo","en":"The screen width"},{"it":"Al sistema operativo","en":"The operating system"},{"it":"Alla larghezza del contenitore segnato con `@container`","en":"The width of the container marked with `@container`"},{"it":"All’altezza della pagina","en":"The page height"}]',2,'{"it":"`md:` guarda lo schermo, `@md:` il contenitore.","en":"`md:` looks at the screen, `@md:` at the container."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'container-motion'),2,2,'{"it":"Quale prefisso vale per chi chiede meno movimento?","en":"Which prefix applies to people asking for less motion?"}','[{"it":"motion-safe:","en":"motion-safe:"},{"it":"motion-reduce:","en":"motion-reduce:"},{"it":"reduce:","en":"reduce:"},{"it":"still:","en":"still:"}]',1,'{"it":"Segue `prefers-reduced-motion`.","en":"It follows `prefers-reduced-motion`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'tailwind' AND slug = 'container-motion'),3,2,'{"it":"Che cosa fa `duration-300` insieme a `transition`?","en":"What does `duration-300` do together with `transition`?"}','[{"it":"Ritarda la pagina di 300ms","en":"It delays the page by 300ms"},{"it":"Ripete l’animazione 300 volte","en":"It repeats the animation 300 times"},{"it":"Ingrandisce del 300%","en":"It enlarges by 300%"},{"it":"Fa durare la transizione 300ms","en":"It makes the transition last 300ms"}]',3,'{"it":"Il numero è in millisecondi.","en":"The number is in milliseconds."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bootstrap' AND slug = 'grid'),1,1,'{"it":"Quante colonne ha una riga di Bootstrap?","en":"How many columns does a Bootstrap row have?"}','[{"it":"12","en":"12"},{"it":"10","en":"10"},{"it":"16","en":"16"},{"it":"24","en":"24"}]',0,'{"it":"`.col-6` è metà.","en":"`.col-6` is half."}',NULL);
