INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bootstrap' AND slug = 'navbar'),1,2,'{"it":"Che cosa fa `.navbar-expand-lg`?","en":"What does `.navbar-expand-lg` do?"}','[{"it":"Allarga la barra a tutto schermo","en":"It widens the bar to full screen"},{"it":"Mostra il menu disteso da `lg` in su e raccolto sotto","en":"It shows the menu spread out from `lg` up and collapsed below"},{"it":"Ingrandisce il logo","en":"It enlarges the logo"},{"it":"Nasconde la barra sui computer","en":"It hides the bar on computers"}]',1,'{"it":"Come le colonne: da quel breakpoint in su.","en":"Like columns: from that breakpoint up."}',NULL);
