INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bootstrap' AND slug = 'js-api'),1,2,'{"it":"Quale componente va attivato a mano con JavaScript?","en":"Which component must be turned on by hand with JavaScript?"}','[{"it":"Il collapse","en":"The collapse"},{"it":"Il tooltip","en":"The tooltip"},{"it":"Il modale con `data-bs-toggle`","en":"The modal with `data-bs-toggle`"},{"it":"L’accordion","en":"The accordion"}]',1,'{"it":"Anche i popover: sono facoltativi per ragioni di prestazioni.","en":"Popovers too: they are opt-in for performance reasons."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bootstrap' AND slug = 'js-api'),2,2,'{"it":"Che cosa fa `bootstrap.Modal.getOrCreateInstance(el)`?","en":"What does `bootstrap.Modal.getOrCreateInstance(el)` do?"}','[{"it":"Crea un nuovo elemento HTML","en":"It creates a new HTML element"},{"it":"Scarica Bootstrap da internet","en":"It downloads Bootstrap from the internet"},{"it":"Restituisce il modale esistente o ne crea uno","en":"It gives back the existing modal or creates one"},{"it":"Chiude tutti i modali","en":"It closes every modal"}]',2,'{"it":"Così non crei due istanze per lo stesso elemento.","en":"That way you never create two instances for the same element."}',NULL);
