INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-base' AND slug = 'strings'),1,2,'{"it":"Quanto vale `\\"Fucina\\".slice(1, 3)`?","en":"What is `\\"Fucina\\".slice(1, 3)`?"}','[{"it":"\\"Fuc\\"","en":"\\"Fuc\\""},{"it":"\\"ucin\\"","en":"\\"ucin\\""},{"it":"\\"uc\\"","en":"\\"uc\\""},{"it":"\\"uci\\"","en":"\\"uci\\""}]',2,'{"it":"Prende gli indici 1 e 2: la fine è esclusa.","en":"It takes indexes 1 and 2: the end is excluded."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-base' AND slug = 'strings'),2,2,'{"it":"Che cosa fa `trim()`?","en":"What does `trim()` do?"}','[{"it":"Toglie tutti gli spazi, anche in mezzo","en":"Removes every space, even in the middle"},{"it":"Toglie gli spazi all’inizio e alla fine","en":"Removes the spaces at the start and the end"},{"it":"Taglia la stringa a metà","en":"Cuts the string in half"},{"it":"Rende la stringa minuscola","en":"Makes the string lowercase"}]',1,'{"it":"Gli spazi in mezzo restano.","en":"The spaces in the middle stay."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-base' AND slug = 'strings'),3,2,'{"it":"Dopo `let s = \\"ciao\\"; s.toUpperCase();` quanto vale `s`?","en":"After `let s = \\"ciao\\"; s.toUpperCase();` what is `s`?"}','[{"it":"\\"CIAO\\"","en":"\\"CIAO\\""},{"it":"\\"Ciao\\"","en":"\\"Ciao\\""},{"it":"undefined","en":"undefined"},{"it":"\\"ciao\\"","en":"\\"ciao\\""}]',3,'{"it":"Il metodo restituisce una stringa nuova: per tenerla serve `s = s.toUpperCase()`.","en":"The method gives back a new string: to keep it you need `s = s.toUpperCase()`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-base' AND slug = 'numbers'),1,2,'{"it":"Quanto vale `\\"5\\" + 2`?","en":"What is `\\"5\\" + 2`?"}','[{"it":"7","en":"7"},{"it":"\\"52\\"","en":"\\"52\\""},{"it":"NaN","en":"NaN"},{"it":"Dà errore","en":"It errors"}]',1,'{"it":"Se c’è una stringa, `+` unisce i testi.","en":"If there is a string, `+` joins the texts."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-base' AND slug = 'numbers'),2,2,'{"it":"Come controlli che una conversione sia fallita?","en":"How do you check that a conversion failed?"}','[{"it":"x === NaN","en":"x === NaN"},{"it":"x == undefined","en":"x == undefined"},{"it":"typeof x === \\"NaN\\"","en":"typeof x === \\"NaN\\""},{"it":"Number.isNaN(x)","en":"Number.isNaN(x)"}]',3,'{"it":"`NaN` non è uguale nemmeno a se stesso: `x === NaN` è sempre falso.","en":"`NaN` is not even equal to itself: `x === NaN` is always false."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-base' AND slug = 'numbers'),3,2,'{"it":"Che cosa restituisce `Math.floor(Math.random() * 6) + 1`?","en":"What does `Math.floor(Math.random() * 6) + 1` give back?"}','[{"it":"Un intero da 1 a 6","en":"A whole number from 1 to 6"},{"it":"Un decimale da 0 a 6","en":"A decimal from 0 to 6"},{"it":"Un intero da 0 a 5","en":"A whole number from 0 to 5"},{"it":"Sempre 6","en":"Always 6"}]',0,'{"it":"`random` va da 0 a quasi 1: per 6 dà da 0 a quasi 6, `floor` toglie i decimali, `+ 1` sposta.","en":"`random` goes from 0 to almost 1: times 6 it gives 0 to almost 6, `floor` drops the decimals, `+ 1` shifts it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-base' AND slug = 'scope'),1,2,'{"it":"Dove si vede una `const` dichiarata dentro un `if`?","en":"Where can a `const` declared inside an `if` be seen?"}','[{"it":"Ovunque nel file","en":"Anywhere in the file"},{"it":"Solo dentro quel blocco","en":"Only inside that block"},{"it":"In tutta la funzione","en":"In the whole function"},{"it":"Solo dopo l’`if`","en":"Only after the `if`"}]',1,'{"it":"`let` e `const` rispettano i blocchi.","en":"`let` and `const` respect blocks."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-base' AND slug = 'scope'),2,2,'{"it":"Con `a` oggetto, dopo `const b = a; b.punti = 5;` quanto vale `a.punti`?","en":"With `a` an object, after `const b = a; b.punti = 5;` what is `a.punti`?"}','[{"it":"Il valore che aveva prima","en":"The value it had before"},{"it":"undefined","en":"undefined"},{"it":"Dà errore","en":"It errors"},{"it":"5","en":"5"}]',3,'{"it":"`a` e `b` indicano lo stesso oggetto.","en":"`a` and `b` point to the same object."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-base' AND slug = 'scope'),3,2,'{"it":"Perché oggi si evita `var`?","en":"Why is `var` avoided today?"}','[{"it":"È più lenta di `let`","en":"It is slower than `let`"},{"it":"Non funziona nei browser","en":"It does not work in browsers"},{"it":"Ignora i blocchi e può creare confusione","en":"It ignores blocks and can cause confusion"},{"it":"Accetta solo numeri","en":"It only accepts numbers"}]',2,'{"it":"`let` e `const` sono più prevedibili.","en":"`let` and `const` are more predictable."}',NULL);
