INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-intermediate' AND slug = 'map-set'),1,3,'{"it":"Quanto vale `new Set([1, 1, 2]).size`?","en":"What is `new Set([1, 1, 2]).size`?"}','[{"it":"3","en":"3"},{"it":"1","en":"1"},{"it":"2","en":"2"},{"it":"0","en":"0"}]',2,'{"it":"Il doppione `1` conta una volta sola.","en":"The duplicate `1` counts only once."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-intermediate' AND slug = 'map-set'),2,3,'{"it":"Come leggi un valore da una Map?","en":"How do you read a value from a Map?"}','[{"it":"mappa[\\"chiave\\"]","en":"mappa[\\"chiave\\"]"},{"it":"mappa.get(\\"chiave\\")","en":"mappa.get(\\"chiave\\")"},{"it":"mappa.read(\\"chiave\\")","en":"mappa.read(\\"chiave\\")"},{"it":"mappa.chiave()","en":"mappa.chiave()"}]',1,'{"it":"Le parentesi quadre leggono le proprietà dell’oggetto, non le voci della Map.","en":"Square brackets read the object’s properties, not the Map’s entries."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-intermediate' AND slug = 'map-set'),3,3,'{"it":"Che cosa dà `Object.entries({ a: 1 })`?","en":"What does `Object.entries({ a: 1 })` give?"}','[{"it":"[\\"a\\"]","en":"[\\"a\\"]"},{"it":"[1]","en":"[1]"},{"it":"{ a: 1 }","en":"{ a: 1 }"},{"it":"[[\\"a\\", 1]]","en":"[[\\"a\\", 1]]"}]',3,'{"it":"Un array di coppie chiave-valore.","en":"An array of key-value pairs."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-intermediate' AND slug = 'sort-copy'),1,3,'{"it":"Quanto vale `[10, 9, 1].sort()`?","en":"What is `[10, 9, 1].sort()`?"}','[{"it":"[1, 9, 10]","en":"[1, 9, 10]"},{"it":"[10, 9, 1]","en":"[10, 9, 1]"},{"it":"[1, 10, 9]","en":"[1, 10, 9]"},{"it":"[9, 10, 1]","en":"[9, 10, 1]"}]',2,'{"it":"Senza funzione confronta i testi: `\\"10\\"` viene prima di `\\"9\\"`.","en":"Without a function it compares text: `\\"10\\"` comes before `\\"9\\"`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-intermediate' AND slug = 'sort-copy'),2,3,'{"it":"Quale funzione ordina i numeri dal più piccolo al più grande?","en":"Which function sorts numbers from smallest to largest?"}','[{"it":"(a, b) => a - b","en":"(a, b) => a - b"},{"it":"(a, b) => b - a","en":"(a, b) => b - a"},{"it":"(a, b) => a + b","en":"(a, b) => a + b"},{"it":"(a, b) => a * b","en":"(a, b) => a * b"}]',0,'{"it":"Un risultato negativo mette `a` prima di `b`.","en":"A negative result puts `a` before `b`."}',NULL);
