INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-advanced' AND slug = 'closures'),2,3,'{"it":"Sul thread principale, JavaScript esegue più codice insieme?","en":"On the main thread, does JavaScript run several pieces of code at once?"}','[{"it":"No, uno alla volta","en":"No, one at a time"},{"it":"Sì, sempre","en":"Yes, always"},{"it":"Solo in CSS","en":"Only in CSS"},{"it":"Solo di notte","en":"Only at night"}]',0,'{"it":"Per questo un ciclo infinito blocca tutto. Per i calcoli pesanti esistono i Web Worker, su thread separati.","en":"That is why an endless loop freezes everything. For heavy work there are Web Workers, on separate threads."}',NULL);
