INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-advanced' AND slug = 'prototypes'),1,3,'{"it":"Dove sta il metodo `saluta` di una classe?","en":"Where does a class’s `saluta` method live?"}','[{"it":"In ogni istanza, copiato","en":"In every instance, copied"},{"it":"Nel prototipo, condiviso da tutte le istanze","en":"In the prototype, shared by every instance"},{"it":"In una variabile globale","en":"In a global variable"},{"it":"Solo nel costruttore","en":"Only in the constructor"}]',1,'{"it":"Una sola copia per tutte le istanze.","en":"One copy for every instance."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-advanced' AND slug = 'prototypes'),2,3,'{"it":"Da che cosa dipende `this` in una funzione normale?","en":"What does `this` depend on in a regular function?"}','[{"it":"Da dove è scritta","en":"On where it is written"},{"it":"Dal nome del file","en":"On the file name"},{"it":"Da come viene chiamata","en":"On how it is called"},{"it":"Dal numero di argomenti","en":"On the number of arguments"}]',2,'{"it":"`oggetto.metodo()` passa `oggetto` come `this`.","en":"`object.method()` passes `object` as `this`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-advanced' AND slug = 'prototypes'),3,3,'{"it":"Perché le arrow function sono comode come callback dentro un metodo?","en":"Why are arrow functions handy as callbacks inside a method?"}','[{"it":"Sono sempre più veloci","en":"They are always faster"},{"it":"Creano un loro `this` nuovo","en":"They create a new `this` of their own"},{"it":"Non possono restituire valori","en":"They cannot give back values"},{"it":"Usano il `this` del codice intorno","en":"They use the `this` of the surrounding code"}]',3,'{"it":"Dentro `setInterval(() => …)` `this` resta l’istanza.","en":"Inside `setInterval(() => …)` `this` stays the instance."}',NULL);
