INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-advanced' AND slug = 'generators'),3,3,'{"it":"Perché `while (true) yield ++n` non blocca la pagina?","en":"Why does `while (true) yield ++n` not freeze the page?"}','[{"it":"Il browser lo ferma dopo un secondo","en":"The browser stops it after a second"},{"it":"Calcola un valore solo quando viene chiesto","en":"It computes a value only when asked"},{"it":"`yield` è asincrono","en":"`yield` is asynchronous"},{"it":"`while (true)` non gira mai","en":"`while (true)` never runs"}]',1,'{"it":"Tra un `yield` e l’altro il generatore è in pausa.","en":"Between one `yield` and the next the generator is paused."}',NULL);
