INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ts' AND slug = 'generics'),1,2,'{"it":"Perché non usare `any` al posto di `T`?","en":"Why not use `any` instead of `T`?"}','[{"it":"Si perderebbe il tipo","en":"The type would be lost"},{"it":"È più lento","en":"It is slower"},{"it":"Non compila","en":"It does not compile"},{"it":"È più lungo","en":"It is longer"}]',0,'{"it":"`T` mantiene il legame tra ingresso e uscita.","en":"`T` keeps the link between input and output."}',NULL);
