INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ts' AND slug = 'tooling'),1,3,'{"it":"Che cosa attiva `strict`?","en":"What does `strict` turn on?"}','[{"it":"Tutti i controlli severi","en":"All the strict checks"},{"it":"Il minify","en":"Minifying"},{"it":"Il server","en":"The server"},{"it":"I commenti","en":"Comments"}]',0,'{"it":"Da TypeScript 6 è acceso di default: tienilo così.","en":"Since TypeScript 6 it is on by default: keep it that way."}',NULL);
