INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ts' AND slug = 'discriminated'),1,3,'{"it":"Che cosa rende «discriminata» un’unione?","en":"What makes a union “discriminated”?"}','[{"it":"Il fatto di contenere solo numeri","en":"Containing only numbers"},{"it":"Una proprietà comune con valori fissi diversi","en":"A shared property with different fixed values"},{"it":"La parola chiave `discriminate`","en":"The `discriminate` keyword"},{"it":"Un’interfaccia che la estende","en":"An interface extending it"}]',1,'{"it":"Il valore di `tipo` dice quale forma è.","en":"The value of `tipo` tells which shape it is."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ts' AND slug = 'discriminated'),2,3,'{"it":"A che cosa serve `const mai: never = f` nel `default`?","en":"What is `const mai: never = f` in the `default` for?"}','[{"it":"A cancellare `f`","en":"To delete `f`"},{"it":"A rendere `f` facoltativo","en":"To make `f` optional"},{"it":"A convertire `f` in stringa","en":"To turn `f` into a string"},{"it":"A segnalare in compilazione i casi dimenticati","en":"To flag forgotten cases at compile time"}]',3,'{"it":"Se resta un caso non gestito, `f` non è `never` e c’è errore.","en":"If a case is left unhandled, `f` is not `never` and there is an error."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ts' AND slug = 'discriminated'),3,3,'{"it":"Che cosa promette una funzione con risultato `x is string`?","en":"What does a function with result `x is string` promise?"}','[{"it":"Che restituisce sempre una stringa","en":"That it always gives back a string"},{"it":"Che se restituisce `true`, `x` è una stringa","en":"That if it gives back `true`, `x` is a string"},{"it":"Che lancia un errore con i numeri","en":"That it throws an error with numbers"},{"it":"Che `x` diventa `any`","en":"That `x` becomes `any`"}]',1,'{"it":"Dentro `if (eStringa(v))` TypeScript tratta `v` come `string`.","en":"Inside `if (eStringa(v))` TypeScript treats `v` as `string`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ts' AND slug = 'type-ops'),1,3,'{"it":"Che cosa dà `keyof { a: 1; b: 2 }`?","en":"What does `keyof { a: 1; b: 2 }` give?"}','[{"it":"1 | 2","en":"1 | 2"},{"it":"[\\"a\\", \\"b\\"]","en":"[\\"a\\", \\"b\\"]"},{"it":"\\"a\\" | \\"b\\"","en":"\\"a\\" | \\"b\\""},{"it":"string","en":"string"}]',2,'{"it":"L’unione dei nomi delle chiavi.","en":"The union of the key names."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ts' AND slug = 'type-ops'),2,3,'{"it":"Che differenza c’è tra `: Tipo` e `satisfies Tipo`?","en":"What is the difference between `: Type` and `satisfies Type`?"}','[{"it":"Nessuna","en":"None"},{"it":"`satisfies` controlla senza allargare il tipo dedotto","en":"`satisfies` checks without widening the inferred type"},{"it":"`satisfies` spegne i controlli","en":"`satisfies` switches checks off"},{"it":"`: Tipo` funziona solo con le classi","en":"`: Type` only works with classes"}]',1,'{"it":"Hai il controllo e mantieni la precisione.","en":"You get the check and keep the precision."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ts' AND slug = 'type-ops'),3,3,'{"it":"Che effetto ha `as const` su un oggetto?","en":"What effect does `as const` have on an object?"}','[{"it":"Lo rende modificabile","en":"It makes it editable"},{"it":"Lo converte in una classe","en":"It turns it into a class"},{"it":"Lo cancella in compilazione","en":"It deletes it on compiling"},{"it":"Rende i valori letterali e in sola lettura","en":"It makes the values literal and read-only"}]',3,'{"it":"`\\"#ffffff\\"` invece di `string`.","en":"`\\"#ffffff\\"` instead of `string`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ts' AND slug = 'modern-setup'),1,3,'{"it":"Che cosa fa Node.js quando esegue un file `.ts`?","en":"What does Node.js do when it runs a `.ts` file?"}','[{"it":"Controlla i tipi e poi esegue","en":"Checks the types, then runs"},{"it":"Toglie i tipi senza controllarli ed esegue","en":"Strips the types without checking them and runs"},{"it":"Lo converte in un eseguibile","en":"Turns it into an executable"},{"it":"Rifiuta il file","en":"Rejects the file"}]',1,'{"it":"Per il controllo serve `tsc` o l’editor.","en":"Checking needs `tsc` or the editor."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ts' AND slug = 'modern-setup'),2,3,'{"it":"Quale di queste NON è sintassi cancellabile?","en":"Which of these is NOT erasable syntax?"}','[{"it":"type Stato = \\"a\\" | \\"b\\"","en":"type Stato = \\"a\\" | \\"b\\""},{"it":"interface Utente { nome: string }","en":"interface Utente { nome: string }"},{"it":"enum Colore { Rosso }","en":"enum Colore { Rosso }"},{"it":"let n: number = 1","en":"let n: number = 1"}]',2,'{"it":"Un `enum` diventa un oggetto JavaScript.","en":"An `enum` becomes a JavaScript object."}',NULL);
