INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'react-base' AND slug = 'state-updates'),1,3,'{"it":"Come aggiungi `\\"latte\\"` all’array di stato `voci`?","en":"How do you add `\\"latte\\"` to the `voci` state array?"}','[{"it":"voci.push(\\"latte\\")","en":"voci.push(\\"latte\\")"},{"it":"setVoci([...voci, \\"latte\\"])","en":"setVoci([...voci, \\"latte\\"])"},{"it":"voci[voci.length] = \\"latte\\"","en":"voci[voci.length] = \\"latte\\""},{"it":"setVoci(voci.push(\\"latte\\"))","en":"setVoci(voci.push(\\"latte\\"))"}]',1,'{"it":"Un array nuovo, con l’elemento in più.","en":"A new array, with the extra item."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'react-base' AND slug = 'state-updates'),2,3,'{"it":"Partendo da 0, dopo tre `setConta(conta + 1)` nello stesso clic quanto vale `conta`?","en":"Starting from 0, after three `setConta(conta + 1)` in the same click what is `conta`?"}','[{"it":"3","en":"3"},{"it":"0","en":"0"},{"it":"1","en":"1"},{"it":"2","en":"2"}]',2,'{"it":"Tutte e tre leggono lo stesso `conta`, cioè 0. Con `c => c + 1` arriveresti a 3.","en":"All three read the same `conta`, which is 0. With `c => c + 1` you would reach 3."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'react-base' AND slug = 'state-updates'),3,3,'{"it":"Perché non modificare direttamente un oggetto nello stato?","en":"Why not change an object in state directly?"}','[{"it":"È più lento da scrivere","en":"It is slower to write"},{"it":"Gli oggetti non possono cambiare","en":"Objects cannot change"},{"it":"Dà sempre un errore","en":"It always errors"},{"it":"React potrebbe non accorgersi del cambiamento","en":"React may not notice the change"}]',3,'{"it":"React confronta i riferimenti, non il contenuto.","en":"React compares references, not content."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'react-base' AND slug = 'lift-state'),1,3,'{"it":"Dove va lo stato condiviso da due componenti fratelli?","en":"Where does state shared by two sibling components go?"}','[{"it":"In entrambi, copiato","en":"In both, copied"},{"it":"In una variabile globale","en":"In a global variable"},{"it":"Nel genitore comune","en":"In the common parent"},{"it":"Nel primo dei due","en":"In the first of the two"}]',2,'{"it":"Poi scende ai figli con le props.","en":"Then it goes down to the children with props."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'react-base' AND slug = 'lift-state'),2,3,'{"it":"Come fa un figlio a cambiare lo stato del genitore?","en":"How does a child change the parent’s state?"}','[{"it":"Modificando le sue props","en":"By changing its props"},{"it":"Chiamando una funzione ricevuta come prop","en":"By calling a function received as a prop"},{"it":"Con `document.querySelector`","en":"With `document.querySelector`"},{"it":"Non può in nessun modo","en":"It cannot in any way"}]',1,'{"it":"Per esempio `onCambia(nuovoValore)`.","en":"For example `onCambia(newValue)`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'react-base' AND slug = 'lift-state'),3,3,'{"it":"Perché `visibili` non sta nello stato?","en":"Why is `visibili` not in state?"}','[{"it":"Si può calcolare dai dati che ci sono già","en":"It can be computed from the data already there"},{"it":"Gli array non possono stare nello stato","en":"Arrays cannot be in state"},{"it":"È troppo grande","en":"It is too big"},{"it":"React lo vieta","en":"React forbids it"}]',0,'{"it":"Meno stato, meno valori da tenere allineati.","en":"Less state, fewer values to keep in sync."}',NULL);
