INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-intermediate' AND slug = 'project'),2,3,'{"it":"Dove non vanno le password del database?","en":"Where must database passwords not go?"}','[{"it":"In un repository pubblico","en":"In a public repository"},{"it":"In una variabile d’ambiente","en":"In an environment variable"},{"it":"In un file fuori da git","en":"In a file outside git"},{"it":"Sul server","en":"On the server"}]',0,'{"it":"Un segreto su git resta nella cronologia.","en":"A secret on git stays in the history."}',NULL);
