INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-intermediate' AND slug = 'inheritance'),1,3,'{"it":"Che cosa fa `parent::saluta()`?","en":"What does `parent::saluta()` do?"}','[{"it":"Chiama la versione della classe padre","en":"Calls the parent class’s version"},{"it":"Crea un nuovo oggetto padre","en":"Creates a new parent object"},{"it":"Rende il metodo statico","en":"Makes the method static"},{"it":"Cancella il metodo del figlio","en":"Deletes the child’s method"}]',0,'{"it":"Utile per estendere un metodo invece di sostituirlo.","en":"Handy to extend a method instead of replacing it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-intermediate' AND slug = 'inheritance'),2,3,'{"it":"Come si legge una costante di classe?","en":"How do you read a class constant?"}','[{"it":"$m->VITE_MAX","en":"$m->VITE_MAX"},{"it":"Personaggio.VITE_MAX","en":"Personaggio.VITE_MAX"},{"it":"Personaggio::VITE_MAX","en":"Personaggio::VITE_MAX"},{"it":"Personaggio->VITE_MAX","en":"Personaggio->VITE_MAX"}]',2,'{"it":"Le costanti appartengono alla classe: si usa `::`.","en":"Constants belong to the class: you use `::`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-intermediate' AND slug = 'inheritance'),3,3,'{"it":"A chi appartiene una proprietà `static`?","en":"Who does a `static` property belong to?"}','[{"it":"A ogni oggetto separatamente","en":"To each object separately"},{"it":"Solo alle sottoclassi","en":"Only to subclasses"},{"it":"Solo al primo oggetto creato","en":"Only to the first object created"},{"it":"Alla classe, condivisa da tutti gli oggetti","en":"To the class, shared by all objects"}]',3,'{"it":"Per questo il contatore conta tutti i personaggi.","en":"That is why the counter counts every character."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-intermediate' AND slug = 'transactions'),1,3,'{"it":"A che cosa serve una transazione?","en":"What is a transaction for?"}','[{"it":"A rendere le query più veloci","en":"To make queries faster"},{"it":"A eseguire più operazioni come un blocco: tutte o nessuna","en":"To run several operations as one block: all or none"},{"it":"A cifrare i dati salvati","en":"To encrypt the saved data"},{"it":"A copiare il database su un altro server","en":"To copy the database to another server"}]',1,'{"it":"Il database resta sempre coerente.","en":"The database always stays consistent."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-intermediate' AND slug = 'transactions'),2,3,'{"it":"Che cosa fa `rollBack()`?","en":"What does `rollBack()` do?"}','[{"it":"Ripete l’ultima query","en":"Repeats the last query"},{"it":"Chiude la connessione al database","en":"Closes the database connection"},{"it":"Annulla le modifiche fatte dall’inizio della transazione","en":"Undoes the changes made since the transaction began"},{"it":"Salva definitivamente le modifiche","en":"Saves the changes for good"}]',2,'{"it":"`commit` invece le conferma.","en":"`commit` confirms them instead."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-intermediate' AND slug = 'transactions'),3,3,'{"it":"Come passi il valore di `:id` a `execute`?","en":"How do you pass the value of `:id` to `execute`?"}','[{"it":"execute(\\":id = 7\\")","en":"execute(\\":id = 7\\")"},{"it":"execute(7)","en":"execute(7)"},{"it":"execute(id: 7)","en":"execute(id: 7)"},{"it":"execute([\\"id\\" => 7])","en":"execute([\\"id\\" => 7])"}]',3,'{"it":"Un array con la chiave uguale al nome del segnaposto.","en":"An array whose key matches the placeholder’s name."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-intermediate' AND slug = 'uploads'),1,3,'{"it":"Quale attributo serve al `<form>` per inviare file?","en":"Which attribute does the `<form>` need to send files?"}','[{"it":"enctype=\\"multipart/form-data\\"","en":"enctype=\\"multipart/form-data\\""},{"it":"method=\\"file\\"","en":"method=\\"file\\""},{"it":"type=\\"upload\\"","en":"type=\\"upload\\""},{"it":"accept=\\"files\\"","en":"accept=\\"files\\""}]',0,'{"it":"Senza, arriva solo il nome del file.","en":"Without it, only the file name arrives."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-intermediate' AND slug = 'uploads'),2,3,'{"it":"Perché non usare `$_FILES[\\"foto\\"][\\"type\\"]` per controllare il formato?","en":"Why not use `$_FILES[\\"foto\\"][\\"type\\"]` to check the format?"}','[{"it":"Contiene sempre il valore null","en":"It always contains null"},{"it":"Lo dichiara il browser e si può falsificare","en":"The browser declares it and it can be faked"},{"it":"Funziona solo con le immagini PNG","en":"It only works with PNG images"},{"it":"È disponibile solo dopo lo spostamento","en":"It is only available after moving"}]',1,'{"it":"Meglio `finfo`, che guarda il contenuto.","en":"`finfo` is better: it looks at the content."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-intermediate' AND slug = 'uploads'),3,3,'{"it":"Quale funzione sposta il file caricato nella cartella finale?","en":"Which function moves the uploaded file to its final folder?"}','[{"it":"rename_upload()","en":"rename_upload()"},{"it":"copy_temp()","en":"copy_temp()"},{"it":"file_put_contents()","en":"file_put_contents()"},{"it":"move_uploaded_file()","en":"move_uploaded_file()"}]',3,'{"it":"Controlla anche che il file arrivi davvero da un caricamento.","en":"It also checks that the file really comes from an upload."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-intermediate' AND slug = 'router'),1,3,'{"it":"Che cos’è un front controller?","en":"What is a front controller?"}','[{"it":"Il controllo dei moduli lato browser","en":"Form validation in the browser"},{"it":"Un server proxy davanti a PHP","en":"A proxy server in front of PHP"},{"it":"Un file che riceve tutte le richieste e le smista","en":"A file that receives every request and dispatches it"},{"it":"Una classe che disegna la pagina","en":"A class that draws the page"}]',2,'{"it":"Un solo ingresso per tutta l’applicazione.","en":"One way in for the whole application."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-intermediate' AND slug = 'router'),2,3,'{"it":"Che cosa restituisce `parse_url(\\"/corsi?p=2\\", PHP_URL_PATH)`?","en":"What does `parse_url(\\"/corsi?p=2\\", PHP_URL_PATH)` return?"}','[{"it":"\\"/corsi?p=2\\"","en":"\\"/corsi?p=2\\""},{"it":"\\"/corsi\\"","en":"\\"/corsi\\""},{"it":"\\"p=2\\"","en":"\\"p=2\\""},{"it":"[\\"corsi\\", 2]","en":"[\\"corsi\\", 2]"}]',1,'{"it":"Solo il percorso, senza la query string.","en":"Only the path, without the query string."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-intermediate' AND slug = 'router'),3,3,'{"it":"Perché tenere il codice fuori da `public/`?","en":"Why keep the code outside `public/`?"}','[{"it":"Il browser non può raggiungere quei file direttamente","en":"The browser cannot reach those files directly"},{"it":"PHP li esegue più in fretta","en":"PHP runs them faster"},{"it":"Composer lo richiede per l’autoload","en":"Composer requires it for autoloading"},{"it":"Le sessioni funzionano solo così","en":"Sessions only work that way"}]',0,'{"it":"Solo `public/` è la radice del sito.","en":"Only `public/` is the site’s root."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'namespaces'),1,2,'{"it":"A che cosa serve un namespace?","en":"What is a namespace for?"}','[{"it":"A evitare conflitti tra nomi","en":"To avoid name clashes"},{"it":"A rendere il codice più veloce","en":"To make code faster"},{"it":"A criptare le classi","en":"To encrypt classes"},{"it":"A creare tabelle","en":"To create tables"}]',0,'{"it":"È come un cognome per le classi.","en":"It is like a surname for classes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'namespaces'),2,2,'{"it":"Quale file carica tutte le classi installate con Composer?","en":"Which file loads every class installed with Composer?"}','[{"it":"vendor/autoload.php","en":"vendor/autoload.php"},{"it":"composer.json","en":"composer.json"},{"it":"index.php","en":"index.php"},{"it":"autoload.ini","en":"autoload.ini"}]',0,'{"it":"Lo genera Composer.","en":"Composer generates it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'namespaces'),3,2,'{"it":"Che cosa fa `use App\\\\Utenti\\\\Utente;`?","en":"What does `use App\\\\Utenti\\\\Utente;` do?"}','[{"it":"Permette di scrivere solo `Utente`","en":"Lets you write just `Utente`"},{"it":"Crea un oggetto","en":"Creates an object"},{"it":"Include un file a mano","en":"Includes a file by hand"},{"it":"Cancella la classe","en":"Deletes the class"}]',0,'{"it":"Importa il nome, non esegue nulla.","en":"It imports the name, it runs nothing."}',NULL);
