INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'interfaces'),2,2,'{"it":"Si può fare `new` di una classe astratta?","en":"Can you `new` an abstract class?"}','[{"it":"No","en":"No"},{"it":"Sì","en":"Yes"},{"it":"Solo in PHP 8","en":"Only in PHP 8"},{"it":"Solo se è vuota","en":"Only if empty"}]',0,'{"it":"Va estesa da una classe concreta.","en":"A concrete class must extend it."}',NULL);
