INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'testing'),3,2,'{"it":"A che cosa servono i test?","en":"What are tests for?"}','[{"it":"A scoprire subito le regressioni","en":"To catch regressions at once"},{"it":"A rendere il sito più bello","en":"To make the site prettier"},{"it":"A sostituire il database","en":"To replace the database"},{"it":"A nascondere errori","en":"To hide errors"}]',0,'{"it":"Ti avvisano quando qualcosa si rompe.","en":"They warn you when something breaks."}',NULL);
