INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'security'),2,2,'{"it":"A che cosa serve un token CSRF?","en":"What is a CSRF token for?"}','[{"it":"A provare che il modulo arriva dal tuo sito","en":"To prove the form comes from your site"},{"it":"A cifrare la password prima di inviarla","en":"To encrypt the password before sending it"},{"it":"A velocizzare la sessione","en":"To speed up the session"},{"it":"A contare le visite","en":"To count visits"}]',0,'{"it":"Un altro sito non conosce il token.","en":"Another site does not know the token."}',NULL);
