INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'attributes'),1,3,'{"it":"Come si scrive un attributo in PHP?","en":"How do you write an attribute in PHP?"}','[{"it":"@Rotta(\\"/corsi\\")","en":"@Rotta(\\"/corsi\\")"},{"it":"#[Rotta(\\"/corsi\\")]","en":"#[Rotta(\\"/corsi\\")]"},{"it":"<<Rotta(\\"/corsi\\")>>","en":"<<Rotta(\\"/corsi\\")>>"},{"it":"/** Rotta(\\"/corsi\\") */","en":"/** Rotta(\\"/corsi\\") */"}]',1,'{"it":"Cancelletto e parentesi quadre, da PHP 8.0.","en":"Hash and square brackets, since PHP 8.0."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'attributes'),2,3,'{"it":"Che cosa succede se segni con `#[\\\\Override]` un metodo che il padre non ha?","en":"What happens if you mark with `#[\\\\Override]` a method the parent does not have?"}','[{"it":"PHP lo ignora in silenzio","en":"PHP silently ignores it"},{"it":"Il metodo diventa astratto","en":"The method becomes abstract"},{"it":"Errore: il metodo non sovrascrive niente","en":"Error: the method overrides nothing"},{"it":"Il metodo viene rinominato","en":"The method gets renamed"}]',2,'{"it":"Ti protegge dai refusi nei nomi dei metodi.","en":"It protects you from typos in method names."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'attributes'),3,3,'{"it":"Come legge un attributo il tuo codice?","en":"How does your code read an attribute?"}','[{"it":"Con `$_SERVER[\\"ATTRIBUTES\\"]`","en":"With `$_SERVER[\\"ATTRIBUTES\\"]`"},{"it":"Con un `include` del file della classe","en":"With an `include` of the class file"},{"it":"Lo legge solo il browser","en":"Only the browser reads it"},{"it":"Con la Reflection, ad esempio `getAttributes()`","en":"With Reflection, for example `getAttributes()`"}]',3,'{"it":"`newInstance()` crea l’oggetto attributo con i suoi argomenti.","en":"`newInstance()` builds the attribute object with its arguments."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'property-hooks'),1,3,'{"it":"Che cosa permette `public private(set) string $email`?","en":"What does `public private(set) string $email` allow?"}','[{"it":"Leggerla da fuori, scriverla solo dentro la classe","en":"Reading it from outside, writing it only inside the class"},{"it":"Scriverla da fuori ma non leggerla","en":"Writing it from outside but not reading it"},{"it":"Leggerla solo dalle sottoclassi","en":"Reading it only from subclasses"},{"it":"Assegnarla una volta sola in tutto il programma","en":"Assigning it only once in the whole program"}]',0,'{"it":"Visibilità diversa per lettura e scrittura.","en":"Different visibility for reading and writing."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'property-hooks'),2,3,'{"it":"Da quale versione di PHP esistono gli hook delle proprietà?","en":"Since which PHP version do property hooks exist?"}','[{"it":"PHP 7.4","en":"PHP 7.4"},{"it":"PHP 8.0","en":"PHP 8.0"},{"it":"PHP 8.4","en":"PHP 8.4"},{"it":"PHP 8.2","en":"PHP 8.2"}]',2,'{"it":"Arrivati a novembre 2024, insieme alla visibilità asimmetrica.","en":"They arrived in November 2024, together with asymmetric visibility."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'property-hooks'),3,3,'{"it":"Una proprietà con il solo hook `get` che non usa il proprio valore…","en":"A property with only a `get` hook that does not use its own value…"}','[{"it":"Si può scrivere ma non leggere","en":"Can be written but not read"},{"it":"Viene salvata nella sessione","en":"Is saved in the session"},{"it":"Diventa automaticamente statica","en":"Automatically becomes static"},{"it":"È calcolata a ogni lettura e non si può assegnare","en":"Is computed on every read and cannot be assigned"}]',3,'{"it":"È una proprietà virtuale.","en":"It is a virtual property."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'modern-php'),1,3,'{"it":"Che cosa restituisce `array_find`?","en":"What does `array_find` return?"}','[{"it":"L’indice di tutti gli elementi trovati","en":"The index of every item found"},{"it":"true se almeno un elemento va bene","en":"true if at least one item matches"},{"it":"Un nuovo array con gli elementi trovati","en":"A new array with the items found"},{"it":"Il primo elemento che soddisfa la condizione, oppure null","en":"The first item that meets the condition, or null"}]',3,'{"it":"Per sapere solo se c’è, usa `array_any`.","en":"To know only whether one exists, use `array_any`."}',NULL);
