INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'modern-php'),3,3,'{"it":"Che cos’è `trim(...)`?","en":"What is `trim(...)`?"}','[{"it":"Una chiamata di trim senza argomenti","en":"A call to trim with no arguments"},{"it":"Un errore di sintassi","en":"A syntax error"},{"it":"Una callable di prima classe che rappresenta trim","en":"A first-class callable standing for trim"},{"it":"Un parametro variadico","en":"A variadic parameter"}]',2,'{"it":"I tre punti fanno parte della sintassi.","en":"The three dots are part of the syntax."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'static-analysis'),1,3,'{"it":"Che cosa fa PHPStan?","en":"What does PHPStan do?"}','[{"it":"Esegue i test più in fretta","en":"Runs tests faster"},{"it":"Comprime i file PHP per il server","en":"Compresses PHP files for the server"},{"it":"Analizza il codice senza eseguirlo e trova errori","en":"Analyses code without running it and finds errors"},{"it":"Traduce PHP in JavaScript","en":"Translates PHP into JavaScript"}]',2,'{"it":"Gli errori emergono prima di arrivare in produzione.","en":"Errors show up before reaching production."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'static-analysis'),2,3,'{"it":"Che cosa significa `@param list<int> $voti`?","en":"What does `@param list<int> $voti` mean?"}','[{"it":"Che $voti ha al massimo un elemento","en":"That $voti has at most one item"},{"it":"Che $voti è un singolo intero","en":"That $voti is a single int"},{"it":"Che $voti è facoltativo","en":"That $voti is optional"},{"it":"Che $voti è una lista di interi con indici 0, 1, 2…","en":"That $voti is a list of ints indexed 0, 1, 2…"}]',3,'{"it":"`array` da solo non dice che cosa contiene.","en":"`array` alone does not say what it holds."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'static-analysis'),3,3,'{"it":"Perché PHPStan segnala `trova(7)->nome`?","en":"Why does PHPStan flag `trova(7)->nome`?"}','[{"it":"Perché `nome` non è un metodo","en":"Because `nome` is not a method"},{"it":"Perché `trova` può restituire null","en":"Because `trova` may return null"},{"it":"Perché manca `declare(strict_types=1)`","en":"Because `declare(strict_types=1)` is missing"},{"it":"Perché 7 non è una stringa","en":"Because 7 is not a string"}]',1,'{"it":"Il tipo di ritorno è `?Utente`.","en":"The return type is `?Utente`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'performance'),1,3,'{"it":"Che cosa fa OPcache?","en":"What does OPcache do?"}','[{"it":"Tiene in memoria il codice già compilato","en":"Keeps already compiled code in memory"},{"it":"Comprime le pagine prima di inviarle","en":"Compresses pages before sending them"},{"it":"Salva le sessioni nel database","en":"Saves sessions in the database"},{"it":"Riduce il peso delle immagini","en":"Shrinks images"}]',0,'{"it":"Niente ricompilazione a ogni richiesta.","en":"No recompiling on every request."}',NULL);
