INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'performance'),3,3,'{"it":"Quando il JIT di PHP aiuta davvero?","en":"When does PHP’s JIT really help?"}','[{"it":"Nelle pagine che aspettano il database","en":"In pages waiting on the database"},{"it":"Nei calcoli pesanti sulla CPU","en":"In heavy CPU computation"},{"it":"Nel caricamento delle immagini","en":"In loading images"},{"it":"Nell’invio delle email","en":"In sending emails"}]',1,'{"it":"Le attese di rete non diventano più corte.","en":"Network waits do not get shorter."}',NULL);
