INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'python-intermediate' AND slug = 'modules'),2,2,'{"it":"A che cosa serve un ambiente virtuale?","en":"What is a virtual environment for?"}','[{"it":"A tenere separate le librerie di ogni progetto","en":"To keep each project’s libraries apart"},{"it":"A rendere Python più veloce","en":"To make Python faster"},{"it":"A virtualizzare il computer","en":"To virtualise the computer"},{"it":"A cifrare il codice","en":"To encrypt code"}]',0,'{"it":"Ogni progetto, le sue versioni.","en":"Each project, its own versions."}',NULL);
