INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'python-intermediate' AND slug = 'inheritance'),1,3,'{"it":"Come eredita `Cane` da `Animale`?","en":"How does `Cane` inherit from `Animale`?"}','[{"it":"class Cane extends Animale:","en":"class Cane extends Animale:"},{"it":"class Cane(Animale):","en":"class Cane(Animale):"},{"it":"class Cane < Animale:","en":"class Cane < Animale:"},{"it":"class Cane: Animale","en":"class Cane: Animale"}]',1,'{"it":"Il genitore va tra le tonde.","en":"The parent goes in brackets."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'python-intermediate' AND slug = 'inheritance'),2,3,'{"it":"Quale metodo usa `print(oggetto)` per il testo da mostrare?","en":"Which method does `print(obj)` use for the text to show?"}','[{"it":"__init__","en":"__init__"},{"it":"__print__","en":"__print__"},{"it":"__str__","en":"__str__"},{"it":"__text__","en":"__text__"}]',2,'{"it":"Se manca, Python ripiega su `__repr__`.","en":"If missing, Python falls back to `__repr__`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'python-intermediate' AND slug = 'inheritance'),3,3,'{"it":"A che cosa serve `super().__init__(nome)`?","en":"What is `super().__init__(nome)` for?"}','[{"it":"A creare un secondo oggetto","en":"To create a second object"},{"it":"A rendere privato l’attributo nome","en":"To make the nome attribute private"},{"it":"A copiare la classe genitore","en":"To copy the parent class"},{"it":"A eseguire il costruttore della classe genitore","en":"To run the parent class’s constructor"}]',3,'{"it":"Così non riscrivi ciò che il genitore già fa.","en":"So you do not rewrite what the parent already does."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'python-intermediate' AND slug = 'lambda-sorting'),1,3,'{"it":"Che cosa fa `key=lambda s: s[1]` in `sorted`?","en":"What does `key=lambda s: s[1]` do in `sorted`?"}','[{"it":"Ordina in base al secondo elemento di ogni tupla","en":"Sorts by the second item of each tuple"},{"it":"Tiene solo il secondo elemento","en":"Keeps only the second item"},{"it":"Ordina dal più grande al più piccolo","en":"Sorts from largest to smallest"},{"it":"Salta il primo elemento della lista","en":"Skips the first item of the list"}]',0,'{"it":"Per l’ordine inverso serve `reverse=True`.","en":"Reverse order needs `reverse=True`."}',NULL);
