INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'java-intermediate' AND slug = 'enums'),3,3,'{"it":"Si può fare `new Livello(...)` fuori dall’enum?","en":"Can you do `new Livello(...)` outside the enum?"}','[{"it":"Sì, come per ogni classe","en":"Yes, as for any class"},{"it":"Solo se il costruttore è public","en":"Only if the constructor is public"},{"it":"Solo dentro un metodo static","en":"Only inside a static method"},{"it":"No, le costanti sono solo quelle dichiarate","en":"No, the constants are only those declared"}]',3,'{"it":"Il costruttore di un enum è sempre privato.","en":"An enum’s constructor is always private."}',NULL);
