INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'java-intermediate' AND slug = 'equality-sorting'),3,3,'{"it":"Che differenza c’è tra Comparable e Comparator?","en":"What is the difference between Comparable and Comparator?"}','[{"it":"Nessuna, sono sinonimi","en":"None, they are synonyms"},{"it":"Comparable è l’ordine naturale della classe, Comparator un ordine esterno a scelta","en":"Comparable is the class’s natural order, Comparator an external order of choice"},{"it":"Comparator funziona solo con i numeri","en":"Comparator only works with numbers"},{"it":"Comparable serve solo per le stringhe","en":"Comparable is only for strings"}]',1,'{"it":"Puoi avere molti Comparator per la stessa classe.","en":"You can have many Comparators for the same class."}',NULL);
