INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'java-intermediate' AND slug = 'files-nio'),3,3,'{"it":"Perché `Files.lines` sta in un try-with-resources?","en":"Why does `Files.lines` go in a try-with-resources?"}','[{"it":"Per leggerlo più in fretta","en":"To read it faster"},{"it":"Perché altrimenti legge solo la prima riga","en":"Because otherwise it reads only the first line"},{"it":"Perché lo richiede il compilatore","en":"Because the compiler requires it"},{"it":"Perché tiene aperto il file finché lo stream non viene chiuso","en":"Because it keeps the file open until the stream is closed"}]',3,'{"it":"Così il file si chiude anche in caso di errore.","en":"That way the file closes even when an error occurs."}',NULL);
