INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'java-advanced' AND slug = 'sealed-patterns'),1,3,'{"it":"Che cosa fa `permits` in un’interfaccia sealed?","en":"What does `permits` do in a sealed interface?"}','[{"it":"Dà i permessi di lettura ai file","en":"Grants read permission on files"},{"it":"Elenca le sole classi che possono implementarla","en":"Lists the only classes that may implement it"},{"it":"Rende pubblici tutti i metodi","en":"Makes every method public"},{"it":"Permette l’ereditarietà multipla","en":"Allows multiple inheritance"}]',1,'{"it":"Nessun’altra classe può aggiungersi.","en":"No other class can join."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'java-advanced' AND slug = 'sealed-patterns'),2,3,'{"it":"Perché lo switch su una `Forma` sealed non ha bisogno di `default`?","en":"Why does the switch on a sealed `Forma` need no `default`?"}','[{"it":"Perché default è vietato con i record","en":"Because default is banned with records"},{"it":"Perché restituisce sempre zero","en":"Because it always returns zero"},{"it":"Perché Java ignora i casi mancanti","en":"Because Java ignores missing cases"},{"it":"Perché il compilatore conosce tutti i casi possibili","en":"Because the compiler knows every possible case"}]',3,'{"it":"Lo switch è esaustivo.","en":"The switch is exhaustive."}',NULL);
