INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'java-advanced' AND slug = 'jvm-memory'),1,3,'{"it":"Che cosa fa il garbage collector?","en":"What does the garbage collector do?"}','[{"it":"Comprime i file JAR","en":"Compresses JAR files"},{"it":"Libera gli oggetti che nessuno può più raggiungere","en":"Frees objects nobody can reach any more"},{"it":"Cancella le variabili locali a fine metodo","en":"Deletes local variables at the end of a method"},{"it":"Ottimizza le query al database","en":"Optimises database queries"}]',1,'{"it":"Non devi liberare la memoria a mano.","en":"You do not free memory by hand."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'java-advanced' AND slug = 'jvm-memory'),2,3,'{"it":"Che cosa imposta `-Xmx1g`?","en":"What does `-Xmx1g` set?"}','[{"it":"La memoria minima del sistema","en":"The system’s minimum memory"},{"it":"La dimensione del file di log","en":"The size of the log file"},{"it":"Il numero di thread","en":"The number of threads"},{"it":"Il massimo dello heap della JVM","en":"The JVM’s maximum heap"}]',3,'{"it":"`-Xms` imposta invece la dimensione iniziale.","en":"`-Xms` sets the initial size instead."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'java-advanced' AND slug = 'jvm-memory'),3,3,'{"it":"Può esserci una perdita di memoria in Java?","en":"Can there be a memory leak in Java?"}','[{"it":"No, il GC lo impedisce sempre","en":"No, the GC always prevents it"},{"it":"Solo nel codice nativo","en":"Only in native code"},{"it":"Sì, se gli oggetti restano raggiungibili senza servire","en":"Yes, if objects stay reachable without being needed"},{"it":"Solo con più di un thread","en":"Only with more than one thread"}]',2,'{"it":"Il GC libera solo ciò che nessuno raggiunge.","en":"The GC frees only what nobody reaches."}',NULL);
