INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-base' AND slug = 'null-case'),2,2,'{"it":"Quanto vale `10 + NULL`?","en":"What is `10 + NULL`?"}','[{"it":"10","en":"10"},{"it":"0","en":"0"},{"it":"NULL","en":"NULL"},{"it":"Un errore","en":"An error"}]',2,'{"it":"Un valore sconosciuto rende sconosciuto il risultato.","en":"An unknown value makes the result unknown."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-base' AND slug = 'null-case'),3,2,'{"it":"Che cosa dà un `CASE` senza `ELSE` se nessun `WHEN` è vero?","en":"What does a `CASE` without `ELSE` give if no `WHEN` is true?"}','[{"it":"Il valore del primo `WHEN`","en":"The value of the first `WHEN`"},{"it":"Il numero zero","en":"The number zero"},{"it":"Un errore di sintassi","en":"A syntax error"},{"it":"NULL","en":"NULL"}]',3,'{"it":"Per questo conviene scrivere sempre un `ELSE`.","en":"That is why it pays to always write an `ELSE`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-base' AND slug = 'functions'),1,2,'{"it":"Che cosa fa `TRIM(''  ciao  '')`?","en":"What does `TRIM(''  ciao  '')` do?"}','[{"it":"Mette tutto il testo in maiuscolo","en":"Puts the whole text in capitals"},{"it":"Toglie gli spazi all’inizio e alla fine","en":"Removes the spaces at the start and end"},{"it":"Conta le lettere del testo","en":"Counts the letters of the text"},{"it":"Taglia il testo a metà","en":"Cuts the text in half"}]',1,'{"it":"Restituisce `''ciao''`.","en":"It returns `''ciao''`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-base' AND slug = 'functions'),2,2,'{"it":"Che cosa dà `ROUND(3.14159, 2)`?","en":"What does `ROUND(3.14159, 2)` give?"}','[{"it":"3","en":"3"},{"it":"3.15","en":"3.15"},{"it":"3.1416","en":"3.1416"},{"it":"3.14","en":"3.14"}]',3,'{"it":"Due cifre dopo la virgola.","en":"Two digits after the decimal point."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-base' AND slug = 'functions'),3,2,'{"it":"Quale modo di unire due testi funziona nella maggior parte dei database?","en":"Which way of joining two texts works in most databases?"}','[{"it":"CONCAT(a, b)","en":"CONCAT(a, b)"},{"it":"JOIN(a, b)","en":"JOIN(a, b)"},{"it":"MERGE(a, b)","en":"MERGE(a, b)"},{"it":"a & b","en":"a & b"}]',0,'{"it":"`||` è standard, ma in MySQL significa OR.","en":"`||` is standard, but in MySQL it means OR."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-base' AND slug = 'alter'),1,2,'{"it":"Quale comando aggiunge una colonna a una tabella esistente?","en":"Which command adds a column to an existing table?"}','[{"it":"CREATE TABLE … ADD","en":"CREATE TABLE … ADD"},{"it":"ALTER TABLE … ADD COLUMN","en":"ALTER TABLE … ADD COLUMN"},{"it":"UPDATE … SET COLUMN","en":"UPDATE … SET COLUMN"},{"it":"INSERT INTO … COLUMN","en":"INSERT INTO … COLUMN"}]',1,'{"it":"`ALTER` cambia la struttura, `UPDATE` i dati.","en":"`ALTER` changes the structure, `UPDATE` the data."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-base' AND slug = 'alter'),2,2,'{"it":"Che differenza c’è tra `TRUNCATE` e `DROP`?","en":"What is the difference between `TRUNCATE` and `DROP`?"}','[{"it":"`TRUNCATE` elimina la tabella, `DROP` la svuota soltanto","en":"`TRUNCATE` removes the table, `DROP` only empties it"},{"it":"Sono due nomi dello stesso identico comando","en":"They are two names for the very same command"},{"it":"`TRUNCATE` cancella solo le colonne vuote","en":"`TRUNCATE` deletes only the empty columns"},{"it":"`TRUNCATE` svuota la tabella, `DROP` la elimina del tutto","en":"`TRUNCATE` empties the table, `DROP` removes it entirely"}]',3,'{"it":"Dopo `TRUNCATE` la tabella c’è ancora, vuota.","en":"After `TRUNCATE` the table is still there, empty."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-base' AND slug = 'alter'),3,2,'{"it":"Che cosa fa `CHECK (prezzo >= 0)`?","en":"What does `CHECK (prezzo >= 0)` do?"}','[{"it":"Controlla i prezzi ogni notte","en":"Checks the prices every night"},{"it":"Arrotonda a zero i prezzi negativi","en":"Rounds negative prices to zero"},{"it":"Rifiuta i prezzi negativi","en":"Rejects negative prices"},{"it":"Ordina i prezzi dal più basso","en":"Sorts prices from the lowest"}]',2,'{"it":"Un inserimento con prezzo negativo dà errore.","en":"An insert with a negative price errors out."}',NULL);
