INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-intermediate' AND slug = 'aggregates'),2,2,'{"it":"`COUNT(email)` conta le righe con email `NULL`?","en":"Does `COUNT(email)` count rows with a `NULL` email?"}','[{"it":"No","en":"No"},{"it":"Sì","en":"Yes"},{"it":"Solo se vuota","en":"Only if empty"},{"it":"Dipende dall’ordine","en":"It depends on order"}]',0,'{"it":"`COUNT(*)` conta tutte le righe.","en":"`COUNT(*)` counts every row."}',NULL);
