INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-intermediate' AND slug = 'group-by'),1,2,'{"it":"Che differenza c’è tra `WHERE` e `HAVING`?","en":"What is the difference between `WHERE` and `HAVING`?"}','[{"it":"WHERE filtra righe, HAVING gruppi","en":"WHERE filters rows, HAVING groups"},{"it":"Nessuna","en":"None"},{"it":"HAVING è più veloce","en":"HAVING is faster"},{"it":"WHERE va dopo","en":"WHERE goes after"}]',0,'{"it":"`HAVING` vede le aggregazioni.","en":"`HAVING` sees the aggregates."}',NULL);
