INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-intermediate' AND slug = 'joins'),1,2,'{"it":"Quale JOIN tiene anche gli utenti senza ordini?","en":"Which JOIN keeps users with no orders?"}','[{"it":"LEFT JOIN","en":"LEFT JOIN"},{"it":"INNER JOIN","en":"INNER JOIN"},{"it":"CROSS JOIN","en":"CROSS JOIN"},{"it":"SELF JOIN","en":"SELF JOIN"}]',0,'{"it":"Le colonne mancanti diventano `NULL`.","en":"Missing columns become `NULL`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-intermediate' AND slug = 'joins'),2,2,'{"it":"Dove si scrive la condizione di unione?","en":"Where do you write the join condition?"}','[{"it":"Dopo `ON`","en":"After `ON`"},{"it":"Dopo `WHERE`","en":"After `WHERE`"},{"it":"Dopo `AS`","en":"After `AS`"},{"it":"Dopo `SET`","en":"After `SET`"}]',0,'{"it":"`ON tabella.col = altra.col`.","en":"`ON table.col = other.col`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-intermediate' AND slug = 'joins'),3,2,'{"it":"Che cos’è `u` in `FROM utenti u`?","en":"What is `u` in `FROM utenti u`?"}','[{"it":"Un alias della tabella","en":"A table alias"},{"it":"Una colonna","en":"A column"},{"it":"Un errore","en":"An error"},{"it":"Un indice","en":"An index"}]',0,'{"it":"Un nome corto.","en":"A short name."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-intermediate' AND slug = 'subqueries'),1,2,'{"it":"Dove può stare una sottoquery?","en":"Where can a subquery sit?"}','[{"it":"In WHERE, FROM o SELECT","en":"In WHERE, FROM or SELECT"},{"it":"Solo in WHERE","en":"Only in WHERE"},{"it":"Solo in ORDER BY","en":"Only in ORDER BY"},{"it":"Da nessuna parte","en":"Nowhere"}]',0,'{"it":"Ovunque serva un valore o una tabella.","en":"Wherever a value or table is needed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-intermediate' AND slug = 'subqueries'),2,2,'{"it":"Che cosa controlla `EXISTS`?","en":"What does `EXISTS` check?"}','[{"it":"Se la sottoquery trova almeno una riga","en":"Whether the subquery finds at least one row"},{"it":"Se la tabella della sottoquery esiste nel database","en":"Whether the subquery’s table exists in the database"},{"it":"Se un file esiste","en":"Whether a file exists"},{"it":"Il numero di colonne","en":"The number of columns"}]',0,'{"it":"Vero o falso.","en":"True or false."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-intermediate' AND slug = 'subqueries'),3,2,'{"it":"Che cosa restituisce `(SELECT AVG(prezzo) FROM prodotti)`?","en":"What does `(SELECT AVG(prezzo) FROM prodotti)` return?"}','[{"it":"Un solo valore","en":"A single value"},{"it":"Una tabella intera","en":"A whole table"},{"it":"Niente","en":"Nothing"},{"it":"Un errore","en":"An error"}]',0,'{"it":"Si può confrontare con `>`.","en":"It can be compared with `>`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-intermediate' AND slug = 'keys'),1,3,'{"it":"Che cosa impedisce una chiave esterna?","en":"What does a foreign key prevent?"}','[{"it":"Riferimenti a righe inesistenti","en":"References to missing rows"},{"it":"I doppioni","en":"Duplicates"},{"it":"I numeri negativi","en":"Negative numbers"},{"it":"Le query lente","en":"Slow queries"}]',0,'{"it":"Mantiene i dati coerenti.","en":"It keeps data consistent."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-intermediate' AND slug = 'keys'),2,3,'{"it":"Che cosa fa `ON DELETE CASCADE`?","en":"What does `ON DELETE CASCADE` do?"}','[{"it":"Cancella anche le righe collegate","en":"Also deletes linked rows"},{"it":"Blocca la cancellazione","en":"Blocks deletion"},{"it":"Duplica le righe","en":"Duplicates rows"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Le righe figlie seguono il padre.","en":"Child rows follow the parent."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-intermediate' AND slug = 'keys'),3,3,'{"it":"Su quali colonne conviene un indice?","en":"Which columns deserve an index?"}','[{"it":"Quelle usate in WHERE e JOIN","en":"Those used in WHERE and JOIN"},{"it":"Tutte, sempre","en":"All, always"},{"it":"Nessuna","en":"None"},{"it":"Solo il testo lungo","en":"Only long text"}]',0,'{"it":"Gli indici hanno un costo in scrittura.","en":"Indexes cost something on writes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-intermediate' AND slug = 'set-ops'),1,3,'{"it":"Che differenza c’è tra `UNION` e `UNION ALL`?","en":"What is the difference between `UNION` and `UNION ALL`?"}','[{"it":"`UNION ALL` toglie i doppioni, `UNION` li tiene","en":"`UNION ALL` removes duplicates, `UNION` keeps them"},{"it":"`UNION` toglie i doppioni, `UNION ALL` li tiene","en":"`UNION` removes duplicates, `UNION ALL` keeps them"},{"it":"`UNION ALL` unisce anche le colonne diverse","en":"`UNION ALL` also merges different columns"},{"it":"Nessuna, cambia solo il nome","en":"None, only the name changes"}]',1,'{"it":"Togliere i doppioni costa: se non servono, usa `UNION ALL`.","en":"Removing duplicates costs time: if you do not need it, use `UNION ALL`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-intermediate' AND slug = 'set-ops'),2,3,'{"it":"Quale operatore trova le email dei clienti che non si sono disiscritti?","en":"Which operator finds the emails of customers who have not unsubscribed?"}','[{"it":"UNION","en":"UNION"},{"it":"INTERSECT","en":"INTERSECT"},{"it":"EXCEPT","en":"EXCEPT"},{"it":"JOIN ALL","en":"JOIN ALL"}]',2,'{"it":"Le righe del primo che mancano nel secondo.","en":"The rows of the first that are missing from the second."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-intermediate' AND slug = 'set-ops'),3,3,'{"it":"Che cosa devono avere in comune le due `SELECT`?","en":"What must the two `SELECT`s have in common?"}','[{"it":"Lo stesso numero di colonne, con tipi compatibili","en":"The same number of columns, with compatible types"},{"it":"La stessa tabella nel `FROM`","en":"The same table in the `FROM`"},{"it":"Lo stesso `WHERE` su ogni riga","en":"The same `WHERE` on every row"},{"it":"Gli stessi nomi di alias per tutte le colonne","en":"The same alias names for every column"}]',0,'{"it":"I nomi vengono dalla prima query.","en":"Names come from the first query."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-intermediate' AND slug = 'more-joins'),1,3,'{"it":"A che cosa serve una self join?","en":"What is a self join for?"}','[{"it":"A copiare una tabella in un’altra","en":"Copying a table into another"},{"it":"A unire una tabella a sé stessa, per esempio per le gerarchie","en":"Joining a table to itself, for example for hierarchies"},{"it":"A unire una tabella senza alcuna condizione","en":"Joining a table with no condition at all"},{"it":"A cancellare le righe doppie di una tabella","en":"Deleting a table’s duplicate rows"}]',1,'{"it":"Due alias della stessa tabella.","en":"Two aliases of the same table."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-intermediate' AND slug = 'more-joins'),2,3,'{"it":"Come trovi i clienti che non hanno ordini?","en":"How do you find customers with no orders?"}','[{"it":"`INNER JOIN` e poi `WHERE o.id IS NOT NULL`","en":"`INNER JOIN` then `WHERE o.id IS NOT NULL`"},{"it":"`CROSS JOIN` e poi `DISTINCT`","en":"`CROSS JOIN` then `DISTINCT`"},{"it":"`RIGHT JOIN` senza nessuna condizione","en":"`RIGHT JOIN` with no condition"},{"it":"`LEFT JOIN` e poi `WHERE o.id IS NULL`","en":"`LEFT JOIN` then `WHERE o.id IS NULL`"}]',3,'{"it":"Le righe senza corrispondenza hanno `NULL` a destra.","en":"Rows without a match have `NULL` on the right."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-intermediate' AND slug = 'more-joins'),3,3,'{"it":"Quante righe dà `CROSS JOIN` tra una tabella da 10 righe e una da 5?","en":"How many rows does a `CROSS JOIN` between a 10-row and a 5-row table give?"}','[{"it":"15","en":"15"},{"it":"10","en":"10"},{"it":"50","en":"50"},{"it":"5","en":"5"}]',2,'{"it":"Ogni riga con ogni altra: 10 × 5.","en":"Every row with every other: 10 × 5."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-intermediate' AND slug = 'design'),1,3,'{"it":"Come si rappresenta una relazione molti-a-molti?","en":"How do you represent a many-to-many relationship?"}','[{"it":"Con una colonna che elenca gli id separati da virgole","en":"With a column listing the ids separated by commas"},{"it":"Con una chiave esterna in entrambe le tabelle","en":"With a foreign key in both tables"},{"it":"Con una tabella ponte che contiene le due chiavi","en":"With a junction table holding both keys"},{"it":"Con una sola tabella che contiene tutto","en":"With a single table holding everything"}]',2,'{"it":"Per esempio `iscrizioni (studente_id, corso_id)`.","en":"For example `iscrizioni (studente_id, corso_id)`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-intermediate' AND slug = 'design'),2,3,'{"it":"In una relazione uno-a-molti, dove va la chiave esterna?","en":"In a one-to-many relationship, where does the foreign key go?"}','[{"it":"Nella tabella dal lato «molti»","en":"In the table on the “many” side"},{"it":"Nella tabella dal lato «uno»","en":"In the table on the “one” side"},{"it":"In una terza tabella separata","en":"In a separate third table"},{"it":"Non serve nessuna chiave esterna","en":"No foreign key is needed"}]',0,'{"it":"Ogni ordine sa a quale cliente appartiene.","en":"Each order knows which customer it belongs to."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-intermediate' AND slug = 'design'),3,3,'{"it":"Perché evitare di ripetere il nome del cliente in ogni ordine?","en":"Why avoid repeating the customer’s name in every order?"}','[{"it":"Perché i nomi lunghi rallentano le query","en":"Because long names slow down queries"},{"it":"Perché i database non accettano testi ripetuti","en":"Because databases do not accept repeated text"},{"it":"Perché le tabelle hanno un limite di colonne","en":"Because tables have a column limit"},{"it":"Perché un cambio andrebbe fatto in tante righe","en":"Because a change would have to be made in many rows"}]',3,'{"it":"Un dato in un posto solo resta coerente.","en":"A fact in one place stays consistent."}',NULL);
