INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-advanced' AND slug = 'transactions'),3,2,'{"it":"Perché un bonifico va in una transazione?","en":"Why does a transfer belong in a transaction?"}','[{"it":"Per non perdere soldi a metà","en":"So money is not lost halfway"},{"it":"Per andare più veloce","en":"To go faster"},{"it":"Per obbligo di legge","en":"Because the law says so"},{"it":"Non serve","en":"It is not needed"}]',0,'{"it":"Due scritture, un solo esito.","en":"Two writes, one outcome."}',NULL);
