INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-advanced' AND slug = 'views'),3,2,'{"it":"Come si esegue una procedura?","en":"How do you run a procedure?"}','[{"it":"CALL","en":"CALL"},{"it":"RUN","en":"RUN"},{"it":"DO","en":"DO"},{"it":"START","en":"START"}]',0,'{"it":"`CALL nome(parametri)`; SQL Server usa `EXEC`.","en":"`CALL name(params)`; SQL Server uses `EXEC`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-advanced' AND slug = 'explain'),1,3,'{"it":"Che cosa mostra `EXPLAIN`?","en":"What does `EXPLAIN` show?"}','[{"it":"Il piano di esecuzione","en":"The execution plan"},{"it":"I dati","en":"The data"},{"it":"La struttura dei file","en":"The file structure"},{"it":"Gli utenti connessi","en":"Connected users"}]',0,'{"it":"Indici usati e righe lette.","en":"Indexes used and rows read."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-advanced' AND slug = 'explain'),2,3,'{"it":"Un indice su `(a, b)` aiuta una query che filtra solo su `b`?","en":"Does an index on `(a, b)` help a query filtering only on `b`?"}','[{"it":"Di solito no","en":"Usually not"},{"it":"Sì, sempre","en":"Yes, always"},{"it":"Solo con LIMIT","en":"Only with LIMIT"},{"it":"Solo con ORDER BY","en":"Only with ORDER BY"}]',0,'{"it":"Conta la colonna più a sinistra; lo «skip scan» di alcuni motori è un ripiego.","en":"The leftmost column matters; some engines’ “skip scan” is only a fallback."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-advanced' AND slug = 'explain'),3,3,'{"it":"Perché `WHERE YEAR(data) = 2026` può essere lento?","en":"Why can `WHERE YEAR(data) = 2026` be slow?"}','[{"it":"La funzione impedisce di usare l’indice","en":"The function prevents index use"},{"it":"Le date sono lente","en":"Dates are slow"},{"it":"2026 è un numero grande","en":"2026 is a big number"},{"it":"Non è lento","en":"It is not slow"}]',0,'{"it":"Meglio un intervallo di date.","en":"Better a date range."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-advanced' AND slug = 'window-frames'),1,3,'{"it":"Che cosa calcola `AVG(x) OVER (ORDER BY giorno ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)`?","en":"What does `AVG(x) OVER (ORDER BY giorno ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)` compute?"}','[{"it":"La media di tutta la tabella","en":"The average of the whole table"},{"it":"Una media mobile su 7 righe","en":"A moving average over 7 rows"},{"it":"La media dei primi 6 giorni","en":"The average of the first 6 days"},{"it":"La media dei 6 giorni successivi","en":"The average of the next 6 days"}]',1,'{"it":"La riga attuale più le 6 precedenti.","en":"The current row plus the 6 before it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-advanced' AND slug = 'window-frames'),2,3,'{"it":"Perché non si scrive `WHERE ROW_NUMBER() OVER (…) <= 3`?","en":"Why can you not write `WHERE ROW_NUMBER() OVER (…) <= 3`?"}','[{"it":"Perché `ROW_NUMBER` funziona solo con `GROUP BY`","en":"Because `ROW_NUMBER` only works with `GROUP BY`"},{"it":"Perché `WHERE` accetta solo numeri fissi","en":"Because `WHERE` only accepts fixed numbers"},{"it":"Perché le finestre si calcolano dopo il `WHERE`","en":"Because windows are computed after the `WHERE`"},{"it":"Perché il limite massimo sarebbe 1","en":"Because the maximum limit would be 1"}]',2,'{"it":"Si filtra dopo, con una CTE o una sottoquery.","en":"You filter afterwards, with a CTE or a subquery."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-advanced' AND slug = 'window-frames'),3,3,'{"it":"Che cosa fa `NTILE(4) OVER (ORDER BY punti)`?","en":"What does `NTILE(4) OVER (ORDER BY punti)` do?"}','[{"it":"Divide le righe in quattro gruppi di uguale grandezza","en":"Splits the rows into four equal-sized groups"},{"it":"Prende solo le prime quattro righe","en":"Takes only the first four rows"},{"it":"Moltiplica i punti per quattro","en":"Multiplies the points by four"},{"it":"Arrotonda i punti a quattro cifre","en":"Rounds the points to four digits"}]',0,'{"it":"Quartili: 1, 2, 3, 4.","en":"Quartiles: 1, 2, 3, 4."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-advanced' AND slug = 'isolation'),1,3,'{"it":"Che cos’è una *dirty read*?","en":"What is a *dirty read*?"}','[{"it":"Leggere una tabella senza indici","en":"Reading a table without indexes"},{"it":"Leggere righe cancellate dal disco","en":"Reading rows deleted from disk"},{"it":"Leggere un file corrotto","en":"Reading a corrupted file"},{"it":"Leggere dati di un’altra transazione non ancora confermati","en":"Reading another transaction’s data not yet committed"}]',3,'{"it":"Quei dati potrebbero sparire con un `ROLLBACK`.","en":"That data could vanish with a `ROLLBACK`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-advanced' AND slug = 'isolation'),2,3,'{"it":"Che cosa fa `SELECT … FOR UPDATE`?","en":"What does `SELECT … FOR UPDATE` do?"}','[{"it":"Blocca le righe lette fino alla fine della transazione","en":"Locks the rows read until the transaction ends"},{"it":"Aggiorna subito tutte le righe trovate","en":"Immediately updates every row found"},{"it":"Rende la query più veloce saltando i lock","en":"Makes the query faster by skipping locks"},{"it":"Crea una copia delle righe da modificare","en":"Creates a copy of the rows to change"}]',0,'{"it":"Così nessuno le cambia mentre decidi.","en":"So nobody changes them while you decide."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-advanced' AND slug = 'isolation'),3,3,'{"it":"Che cosa succede in un deadlock?","en":"What happens in a deadlock?"}','[{"it":"Il server si spegne per sicurezza","en":"The server shuts down for safety"},{"it":"Il database annulla una delle transazioni","en":"The database cancels one of the transactions"},{"it":"Le due transazioni aspettano per sempre","en":"Both transactions wait forever"},{"it":"Vengono confermate tutte e due","en":"Both get committed"}]',1,'{"it":"L’applicazione deve ripeterla.","en":"The application must retry it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-advanced' AND slug = 'triggers'),1,3,'{"it":"Quando parte un trigger?","en":"When does a trigger fire?"}','[{"it":"Solo quando lo chiami con `CALL`","en":"Only when you call it with `CALL`"},{"it":"A un orario fisso ogni notte","en":"At a fixed time every night"},{"it":"Prima o dopo un `INSERT`, `UPDATE` o `DELETE`","en":"Before or after an `INSERT`, `UPDATE` or `DELETE`"},{"it":"Solo quando il server si riavvia","en":"Only when the server restarts"}]',2,'{"it":"Lo fa partire la modifica stessa.","en":"The change itself fires it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-advanced' AND slug = 'triggers'),2,3,'{"it":"In un trigger su `DELETE`, quale riga è disponibile?","en":"In a trigger on `DELETE`, which row is available?"}','[{"it":"NEW","en":"NEW"},{"it":"OLD","en":"OLD"},{"it":"Sia OLD sia NEW","en":"Both OLD and NEW"},{"it":"Nessuna delle due","en":"Neither"}]',1,'{"it":"La riga cancellata, com’era.","en":"The deleted row, as it was."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sql-advanced' AND slug = 'triggers'),3,3,'{"it":"Qual è il rischio principale dei trigger?","en":"What is the main risk of triggers?"}','[{"it":"Logica nascosta, difficile da trovare e da testare","en":"Hidden logic, hard to find and test"},{"it":"Funzionano solo su tabelle vuote","en":"They only work on empty tables"},{"it":"Cancellano gli indici della tabella","en":"They delete the table’s indexes"},{"it":"Non possono scrivere in altre tabelle","en":"They cannot write to other tables"}]',0,'{"it":"Chi legge il codice dell’app non li vede.","en":"Whoever reads the app code does not see them."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'server'),1,2,'{"it":"Quale comando sceglie il database su cui lavorare?","en":"Which command picks the database to work on?"}','[{"it":"USE negozio;","en":"USE negozio;"},{"it":"OPEN negozio;","en":"OPEN negozio;"},{"it":"SELECT negozio;","en":"SELECT negozio;"},{"it":"CONNECT negozio;","en":"CONNECT negozio;"}]',0,'{"it":"Da lì in poi le query vanno su quel database.","en":"From then on queries go to that database."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'server'),2,2,'{"it":"Qual è il motore predefinito di MySQL?","en":"What is MySQL’s default engine?"}','[{"it":"MyISAM","en":"MyISAM"},{"it":"InnoDB","en":"InnoDB"},{"it":"Memory","en":"Memory"},{"it":"CSV","en":"CSV"}]',1,'{"it":"InnoDB, con transazioni e chiavi esterne.","en":"InnoDB, with transactions and foreign keys."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'server'),3,2,'{"it":"Che cosa mostra `DESCRIBE prodotti`?","en":"What does `DESCRIBE prodotti` show?"}','[{"it":"Le righe della tabella","en":"The table rows"},{"it":"Colonne, tipi e chiavi","en":"Columns, types and keys"},{"it":"Chi ha creato la tabella","en":"Who created the table"},{"it":"Lo spazio su disco","en":"The disk space"}]',1,'{"it":"È la struttura, non il contenuto.","en":"It is the structure, not the content."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'types'),1,2,'{"it":"Perché preferire `utf8mb4` a `utf8`?","en":"Why prefer `utf8mb4` to `utf8`?"}','[{"it":"È più veloce","en":"It is faster"},{"it":"Regge emoji e tutti i caratteri","en":"It holds emoji and every character"},{"it":"Occupa sempre meno spazio","en":"It always takes less space"},{"it":"È l’unico con gli indici","en":"It is the only one with indexes"}]',1,'{"it":"Il vecchio `utf8` si ferma a 3 byte.","en":"The old `utf8` stops at 3 bytes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'types'),2,2,'{"it":"Che cosa fa `ENUM(''a'', ''b'')`?","en":"What does `ENUM(''a'', ''b'')` do?"}','[{"it":"Accetta solo i valori elencati","en":"Accepts only the listed values"},{"it":"Numera le righe","en":"Numbers the rows"},{"it":"Crea due colonne","en":"Creates two columns"},{"it":"Cifra il testo","en":"Encrypts the text"}]',0,'{"it":"Un elenco chiuso di valori.","en":"A closed list of values."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'types'),3,2,'{"it":"Che cosa vieta `UNSIGNED`?","en":"What does `UNSIGNED` forbid?"}','[{"it":"I valori nulli","en":"Null values"},{"it":"I numeri negativi","en":"Negative numbers"},{"it":"I doppioni","en":"Duplicates"},{"it":"I decimali","en":"Decimals"}]',1,'{"it":"In cambio il massimo positivo raddoppia.","en":"In exchange the positive maximum doubles."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'upsert'),1,2,'{"it":"Quando scatta `ON DUPLICATE KEY UPDATE`?","en":"When does `ON DUPLICATE KEY UPDATE` fire?"}','[{"it":"Sempre","en":"Always"},{"it":"Quando una chiave unica sarebbe ripetuta","en":"When a unique key would repeat"},{"it":"Quando la tabella è vuota","en":"When the table is empty"},{"it":"Solo nelle transazioni","en":"Only in transactions"}]',1,'{"it":"Serve una chiave primaria o `UNIQUE`.","en":"It needs a primary or `UNIQUE` key."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'upsert'),2,2,'{"it":"Che cosa fa `INSERT IGNORE` con una riga doppia?","en":"What does `INSERT IGNORE` do with a duplicate row?"}','[{"it":"La salta","en":"Skips it"},{"it":"La sovrascrive","en":"Overwrites it"},{"it":"Blocca tutto con un errore","en":"Stops everything with an error"},{"it":"La duplica comunque","en":"Duplicates it anyway"}]',0,'{"it":"Niente errore, niente riga.","en":"No error, no row."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'upsert'),3,2,'{"it":"Perché `REPLACE` può essere pericoloso?","en":"Why can `REPLACE` be dangerous?"}','[{"it":"Cancella e reinserisce la riga","en":"It deletes and reinserts the row"},{"it":"È lentissimo","en":"It is very slow"},{"it":"Non esiste in MySQL","en":"It does not exist in MySQL"},{"it":"Svuota la tabella","en":"It empties the table"}]',0,'{"it":"Nuovo id e cancellazioni a cascata.","en":"New id and cascading deletes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'json'),1,2,'{"it":"Che cosa restituisce `dati->>''$.nome''`?","en":"What does `dati->>''$.nome''` return?"}','[{"it":"Il nome come testo semplice","en":"The name as plain text"},{"it":"Il nome tra virgolette JSON","en":"The name in JSON quotes"},{"it":"Tutto il documento","en":"The whole document"},{"it":"Un errore","en":"An error"}]',0,'{"it":"`->` lo darebbe tra virgolette.","en":"`->` would give it in quotes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'json'),2,2,'{"it":"Da quale simbolo parte un percorso JSON?","en":"Which symbol does a JSON path start with?"}','[{"it":"$","en":"$"},{"it":"#","en":"#"},{"it":"@","en":"@"},{"it":"&","en":"&"}]',0,'{"it":"`$` è la radice del documento.","en":"`$` is the document root."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'json'),3,2,'{"it":"Come indicizzi un campo dentro una colonna JSON?","en":"How do you index a field inside a JSON column?"}','[{"it":"Con una colonna generata","en":"With a generated column"},{"it":"Non si può","en":"You cannot"},{"it":"Con `ENUM`","en":"With `ENUM`"},{"it":"Con `REPLACE`","en":"With `REPLACE`"}]',0,'{"it":"La colonna generata si indicizza come le altre.","en":"The generated column is indexed like any other."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'users'),1,3,'{"it":"Che cosa significa `negozio.*` in un `GRANT`?","en":"What does `negozio.*` mean in a `GRANT`?"}','[{"it":"Tutte le tabelle di `negozio`","en":"Every table of `negozio`"},{"it":"Tutti i database","en":"Every database"},{"it":"Tutte le colonne di una tabella","en":"Every column of a table"},{"it":"Tutti gli utenti","en":"Every user"}]',0,'{"it":"database.tabella, con `*` come jolly.","en":"database.table, with `*` as wildcard."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'users'),2,3,'{"it":"Che cosa fa `ROLLBACK`?","en":"What does `ROLLBACK` do?"}','[{"it":"Annulla la transazione","en":"Undoes the transaction"},{"it":"Conferma la transazione","en":"Confirms the transaction"},{"it":"Riavvia il server","en":"Restarts the server"},{"it":"Cancella l’utente","en":"Deletes the user"}]',0,'{"it":"Come se non fosse successo niente.","en":"As if nothing had happened."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'users'),3,3,'{"it":"Perché l’app non deve usare `root`?","en":"Why should the app not use `root`?"}','[{"it":"Per il minimo privilegio","en":"For least privilege"},{"it":"`root` è più lento","en":"`root` is slower"},{"it":"`root` non può leggere","en":"`root` cannot read"},{"it":"È vietato dalla licenza","en":"The licence forbids it"}]',0,'{"it":"Una falla non deve poter fare tutto.","en":"A breach must not be able to do everything."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'explain'),1,3,'{"it":"Che cosa fa in più `EXPLAIN ANALYZE` rispetto a `EXPLAIN`?","en":"What does `EXPLAIN ANALYZE` do beyond `EXPLAIN`?"}','[{"it":"Crea gli indici che mancano","en":"Creates the missing indexes"},{"it":"Esegue la query e mostra tempi e righe reali","en":"Runs the query and shows real times and rows"},{"it":"Analizza la sintassi senza eseguire nulla","en":"Checks the syntax without running anything"},{"it":"Aggiorna le statistiche di tutte le tabelle","en":"Updates the statistics of every table"}]',1,'{"it":"Attenzione: la query viene eseguita davvero.","en":"Careful: the query is really executed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'explain'),2,3,'{"it":"Che cosa indica `type: ALL` nel piano?","en":"What does `type: ALL` mean in the plan?"}','[{"it":"Che usa tutti gli indici","en":"That it uses every index"},{"it":"Che restituisce tutte le colonne","en":"That it returns every column"},{"it":"Una scansione completa della tabella","en":"A full scan of the table"},{"it":"Che la query è perfetta","en":"That the query is perfect"}]',2,'{"it":"Su tabelle grandi è un segnale d’allarme.","en":"On big tables it is a warning sign."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'explain'),3,3,'{"it":"A che cosa serve un indice invisibile?","en":"What is an invisible index for?"}','[{"it":"A provare a farne a meno prima di cancellarlo","en":"To try doing without it before dropping it"},{"it":"A nascondere i dati agli utenti","en":"To hide data from users"},{"it":"A cifrare la colonna indicizzata","en":"To encrypt the indexed column"},{"it":"A risparmiare spazio su disco","en":"To save disk space"}]',0,'{"it":"Si rende di nuovo visibile in un attimo.","en":"It can be made visible again in a moment."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'backup'),1,3,'{"it":"Che cosa produce `mysqldump`?","en":"What does `mysqldump` produce?"}','[{"it":"Una copia binaria dei file del server","en":"A binary copy of the server’s files"},{"it":"Un file di istruzioni SQL che ricreano i dati","en":"A file of SQL statements that recreate the data"},{"it":"Un foglio Excel con tutte le tabelle","en":"An Excel sheet with every table"},{"it":"Un nuovo server già configurato","en":"A new, already configured server"}]',1,'{"it":"Si ripristina passandolo al client `mysql`.","en":"You restore it by feeding it to the `mysql` client."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'backup'),2,3,'{"it":"Perché usare `--single-transaction` con InnoDB?","en":"Why use `--single-transaction` with InnoDB?"}','[{"it":"Per comprimere il file di backup","en":"To compress the backup file"},{"it":"Per copiare solo una tabella alla volta","en":"To copy only one table at a time"},{"it":"Per cifrare le password nel dump","en":"To encrypt passwords in the dump"},{"it":"Per una copia coerente senza bloccare le scritture","en":"For a consistent copy without blocking writes"}]',3,'{"it":"Legge tutto da una fotografia della transazione.","en":"It reads everything from one transaction snapshot."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'backup'),3,3,'{"it":"A che cosa serve il log binario?","en":"What is the binary log for?"}','[{"it":"Al ripristino a un istante preciso e alla replica","en":"Point-in-time recovery and replication"},{"it":"A salvare gli errori di sintassi","en":"Saving syntax errors"},{"it":"A tenere le password degli utenti","en":"Keeping user passwords"},{"it":"A velocizzare le query `SELECT`","en":"Speeding up `SELECT` queries"}]',0,'{"it":"Registra ogni modifica, in ordine.","en":"It records every change, in order."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'versions'),1,3,'{"it":"Quale tipo di versione conviene di solito in produzione?","en":"Which kind of version usually suits production?"}','[{"it":"L’ultima Innovation appena uscita","en":"The latest Innovation just released"},{"it":"Una versione di sviluppo","en":"A development build"},{"it":"Una LTS, con anni di correzioni","en":"An LTS, with years of fixes"},{"it":"La versione più vecchia disponibile","en":"The oldest version available"}]',2,'{"it":"Le Innovation hanno supporto breve.","en":"Innovation releases have short support."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'versions'),2,3,'{"it":"Da quale versione MySQL ha CTE e funzioni finestra?","en":"Since which version does MySQL have CTEs and window functions?"}','[{"it":"5.7","en":"5.7"},{"it":"8.0","en":"8.0"},{"it":"9.0","en":"9.0"},{"it":"5.5","en":"5.5"}]',1,'{"it":"Prima servivano trucchi con variabili e sottoquery.","en":"Before that you needed tricks with variables and subqueries."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mysql' AND slug = 'versions'),3,3,'{"it":"A che cosa serve il tipo `VECTOR`?","en":"What is the `VECTOR` type for?"}','[{"it":"A salvare immagini in formato vettoriale","en":"Storing images in vector format"},{"it":"A salvare elenchi di testi separati da virgole","en":"Storing comma-separated lists of text"},{"it":"A salvare coordinate geografiche","en":"Storing geographic coordinates"},{"it":"A salvare gli embedding usati dall’IA","en":"Storing the embeddings used by AI"}]',3,'{"it":"Liste di numeri che rappresentano il significato di un testo.","en":"Lists of numbers representing the meaning of a text."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'fork'),1,2,'{"it":"Chi ha creato MariaDB?","en":"Who created MariaDB?"}','[{"it":"Gli sviluppatori originali di MySQL","en":"MySQL’s original developers"},{"it":"Oracle","en":"Oracle"},{"it":"Microsoft","en":"Microsoft"},{"it":"Il team di PostgreSQL","en":"The PostgreSQL team"}]',0,'{"it":"Quando Oracle stava acquisendo Sun, proprietaria di MySQL.","en":"When Oracle was acquiring Sun, the owner of MySQL."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'fork'),2,2,'{"it":"Come scopri se il server è MariaDB?","en":"How do you find out whether the server is MariaDB?"}','[{"it":"SELECT VERSION();","en":"SELECT VERSION();"},{"it":"SHOW USERS;","en":"SHOW USERS;"},{"it":"DESCRIBE server;","en":"DESCRIBE server;"},{"it":"SELECT ENGINE();","en":"SELECT ENGINE();"}]',0,'{"it":"La versione contiene “MariaDB”.","en":"The version contains “MariaDB”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'fork'),3,2,'{"it":"Il connettore MySQL di PHP funziona con MariaDB?","en":"Does PHP’s MySQL connector work with MariaDB?"}','[{"it":"Sì, il protocollo è lo stesso","en":"Yes, the protocol is the same"},{"it":"No, serve un driver diverso","en":"No, it needs another driver"},{"it":"Solo in sola lettura","en":"Only read only"},{"it":"Solo su Windows","en":"Only on Windows"}]',0,'{"it":"PDO e mysqli si collegano senza cambiare nulla.","en":"PDO and mysqli connect with no changes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'returning'),1,2,'{"it":"Che cosa aggiunge `RETURNING` a un `INSERT`?","en":"What does `RETURNING` add to an `INSERT`?"}','[{"it":"Restituisce le colonne delle righe inserite","en":"Returns the columns of the inserted rows"},{"it":"Annulla l’inserimento se qualcosa va storto","en":"Undoes the insert if something goes wrong"},{"it":"Inserisce due volte","en":"Inserts twice"},{"it":"Ordina la tabella","en":"Sorts the table"}]',0,'{"it":"Niente query in più per leggere l’id.","en":"No extra query to read the id."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'returning'),2,2,'{"it":"Si può usare `RETURNING` con `DELETE`?","en":"Can you use `RETURNING` with `DELETE`?"}','[{"it":"Sì","en":"Yes"},{"it":"No","en":"No"},{"it":"Solo con `LIMIT 1`","en":"Only with `LIMIT 1`"},{"it":"Solo da root","en":"Only as root"}]',0,'{"it":"Vedi cosa hai cancellato.","en":"You see what you deleted."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'returning'),3,2,'{"it":"Qual è l’alternativa classica di MySQL per l’ultimo id?","en":"What is MySQL’s classic alternative for the last id?"}','[{"it":"LAST_INSERT_ID()","en":"LAST_INSERT_ID()"},{"it":"NEXT_ID()","en":"NEXT_ID()"},{"it":"CURRENT_ROW()","en":"CURRENT_ROW()"},{"it":"MAX_ID()","en":"MAX_ID()"}]',0,'{"it":"Vale per l’`AUTO_INCREMENT`.","en":"It covers the `AUTO_INCREMENT`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'sequences'),1,2,'{"it":"Che cosa fa `NEXTVAL(fatture)`?","en":"What does `NEXTVAL(fatture)` do?"}','[{"it":"Dà il numero successivo","en":"Gives the next number"},{"it":"Legge senza avanzare","en":"Reads without advancing"},{"it":"Azzera la sequenza","en":"Resets the sequence"},{"it":"Cancella la sequenza","en":"Drops the sequence"}]',0,'{"it":"Ogni chiamata avanza.","en":"Every call advances."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'sequences'),2,2,'{"it":"Che cosa distingue una sequenza dall’`AUTO_INCREMENT`?","en":"What sets a sequence apart from `AUTO_INCREMENT`?"}','[{"it":"Non appartiene a una colonna","en":"It does not belong to a column"},{"it":"È più lenta","en":"It is slower"},{"it":"Conta all’indietro","en":"It counts backwards"},{"it":"Funziona solo con i testi","en":"It only works with text"}]',0,'{"it":"Si può condividere tra tabelle.","en":"It can be shared between tables."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'sequences'),3,2,'{"it":"Che cosa fa `LASTVAL`?","en":"What does `LASTVAL` do?"}','[{"it":"Legge l’ultimo valore dato, senza avanzare","en":"Reads the last value given, without advancing"},{"it":"Dà il valore massimo possibile","en":"Gives the highest possible value"},{"it":"Avanza di due","en":"Advances by two"},{"it":"Chiude la sequenza","en":"Closes the sequence"}]',0,'{"it":"Nella tua sessione.","en":"In your session."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'versioning'),1,2,'{"it":"Che cosa fa `WITH SYSTEM VERSIONING`?","en":"What does `WITH SYSTEM VERSIONING` do?"}','[{"it":"Conserva tutte le versioni delle righe","en":"Keeps every version of the rows"},{"it":"Numera le versioni del server","en":"Numbers the server versions"},{"it":"Blocca le modifiche","en":"Blocks changes"},{"it":"Crea un backup su file","en":"Creates a backup file"}]',0,'{"it":"Il passato resta interrogabile.","en":"The past stays queryable."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'versioning'),2,2,'{"it":"Come leggi la tabella com’era il 1° gennaio?","en":"How do you read the table as it was on 1 January?"}','[{"it":"FOR SYSTEM_TIME AS OF","en":"FOR SYSTEM_TIME AS OF"},{"it":"WHERE date = ","en":"WHERE date = "},{"it":"HISTORY OF","en":"HISTORY OF"},{"it":"AT VERSION","en":"AT VERSION"}]',0,'{"it":"Con un `TIMESTAMP` preciso.","en":"With a precise `TIMESTAMP`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'versioning'),3,2,'{"it":"Come togli le versioni vecchie?","en":"How do you remove old versions?"}','[{"it":"DELETE HISTORY","en":"DELETE HISTORY"},{"it":"DROP VERSIONS","en":"DROP VERSIONS"},{"it":"TRUNCATE PAST","en":"TRUNCATE PAST"},{"it":"PURGE TABLE","en":"PURGE TABLE"}]',0,'{"it":"Così lo spazio non cresce all’infinito.","en":"So space does not grow forever."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'engines'),1,3,'{"it":"A che cosa serve ColumnStore?","en":"What is ColumnStore for?"}','[{"it":"Analisi su grandi volumi","en":"Analytics on large volumes"},{"it":"Tabelle temporanee","en":"Temporary tables"},{"it":"Salvare immagini","en":"Storing images"},{"it":"Le password","en":"Passwords"}]',0,'{"it":"I dati sono salvati per colonna.","en":"Data is stored by column."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'engines'),2,3,'{"it":"Che tipo di replica offre Galera?","en":"What kind of replication does Galera offer?"}','[{"it":"Sincrona multi-master","en":"Synchronous multi-master"},{"it":"Solo backup notturni","en":"Nightly backups only"},{"it":"Asincrona a un solo master","en":"Asynchronous single master"},{"it":"Nessuna","en":"None"}]',0,'{"it":"Tutti i nodi accettano scritture.","en":"Every node accepts writes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'engines'),3,3,'{"it":"Come scegli il motore di una tabella?","en":"How do you pick a table’s engine?"}','[{"it":"Con `ENGINE=` nel `CREATE TABLE`","en":"With `ENGINE=` in `CREATE TABLE`"},{"it":"Riavviando il server","en":"By restarting the server"},{"it":"Con un `GRANT`","en":"With a `GRANT`"},{"it":"Non si può scegliere","en":"You cannot choose"}]',0,'{"it":"Ogni tabella può avere il suo.","en":"Every table can have its own."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'vector'),1,3,'{"it":"Che cosa contiene una colonna `VECTOR(384)`?","en":"What does a `VECTOR(384)` column hold?"}','[{"it":"Un testo lungo al massimo 384 caratteri","en":"A text up to 384 characters long"},{"it":"Un’immagine di 384 pixel","en":"A 384-pixel image"},{"it":"Una lista di 384 numeri, un embedding","en":"A list of 384 numbers, an embedding"},{"it":"384 righe collegate","en":"384 linked rows"}]',2,'{"it":"Il significato tradotto in numeri.","en":"Meaning turned into numbers."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'vector'),2,3,'{"it":"Come trovi i documenti più simili a una domanda?","en":"How do you find the documents most similar to a question?"}','[{"it":"Ordini per distanza dal vettore della domanda","en":"You sort by distance from the question’s vector"},{"it":"Usi `LIKE` con le parole della domanda","en":"You use `LIKE` with the question’s words"},{"it":"Ordini per `id` decrescente","en":"You sort by descending `id`"},{"it":"Usi `GROUP BY` sul testo","en":"You use `GROUP BY` on the text"}]',0,'{"it":"I più vicini sono i più simili.","en":"The nearest are the most similar."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'vector'),3,3,'{"it":"A che cosa serve `VECTOR INDEX`?","en":"What is `VECTOR INDEX` for?"}','[{"it":"A comprimere i vettori sul disco","en":"Compressing vectors on disk"},{"it":"A rendere veloce la ricerca dei vicini","en":"Making nearest-neighbour search fast"},{"it":"A calcolare gli embedding dal testo","en":"Computing embeddings from text"},{"it":"A vietare i vettori duplicati","en":"Forbidding duplicate vectors"}]',1,'{"it":"Gli embedding li calcola un modello esterno.","en":"An external model computes the embeddings."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'types'),1,3,'{"it":"Che cos’è `JSON` in MariaDB?","en":"What is `JSON` in MariaDB?"}','[{"it":"Un formato binario come JSONB","en":"A binary format like JSONB"},{"it":"Un tipo che accetta solo numeri","en":"A type that accepts only numbers"},{"it":"Una tabella speciale di sistema","en":"A special system table"},{"it":"Un alias di `LONGTEXT` con il controllo `JSON_VALID`","en":"An alias of `LONGTEXT` with the `JSON_VALID` check"}]',3,'{"it":"Si legge con funzioni come `JSON_VALUE`.","en":"You read it with functions such as `JSON_VALUE`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'types'),2,3,'{"it":"Quale tipo conviene per salvare indirizzi IP?","en":"Which type suits storing IP addresses?"}','[{"it":"INET6","en":"INET6"},{"it":"VARCHAR(4)","en":"VARCHAR(4)"},{"it":"UUID","en":"UUID"},{"it":"POINT","en":"POINT"}]',0,'{"it":"Regge IPv6 e IPv4 in modo compatto.","en":"It holds IPv6 and IPv4 compactly."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mariadb' AND slug = 'types'),3,3,'{"it":"Ogni quanto esce una LTS di MariaDB?","en":"How often does a MariaDB LTS come out?"}','[{"it":"Ogni mese","en":"Every month"},{"it":"Ogni dieci anni","en":"Every ten years"},{"it":"Ogni anno, con tre anni di correzioni","en":"Every year, with three years of fixes"},{"it":"Solo quando cambia il nome","en":"Only when the name changes"}]',2,'{"it":"La «.3» di ogni serie.","en":"The “.3” of each series."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'psql'),1,2,'{"it":"Quale meta-comando elenca le tabelle in `psql`?","en":"Which meta-command lists the tables in `psql`?"}','[{"it":"\\\\dt","en":"\\\\dt"},{"it":"\\\\l","en":"\\\\l"},{"it":"\\\\q","en":"\\\\q"},{"it":"SHOW TABLES","en":"SHOW TABLES"}]',0,'{"it":"`\\\\l` elenca i database.","en":"`\\\\l` lists the databases."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'psql'),2,2,'{"it":"A che cosa servono le virgolette doppie?","en":"What are double quotes for?"}','[{"it":"Ai nomi di tabelle e colonne","en":"Table and column names"},{"it":"Ai testi","en":"Text"},{"it":"Ai numeri","en":"Numbers"},{"it":"Ai commenti","en":"Comments"}]',0,'{"it":"I testi vanno tra apici singoli.","en":"Text goes between single quotes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'psql'),3,2,'{"it":"Che cosa diventa il nome `Clienti` senza virgolette?","en":"What does the name `Clienti` become without quotes?"}','[{"it":"clienti","en":"clienti"},{"it":"CLIENTI","en":"CLIENTI"},{"it":"Clienti","en":"Clienti"},{"it":"Un errore","en":"An error"}]',0,'{"it":"Tutto minuscolo.","en":"All lowercase."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'types'),1,2,'{"it":"Come controlli se un array contiene `''sql''`?","en":"How do you check whether an array contains `''sql''`?"}','[{"it":"`''sql'' = ANY(tag)`","en":"`''sql'' = ANY(tag)`"},{"it":"`tag LIKE ''sql''`","en":"`tag LIKE ''sql''`"},{"it":"`tag IN ''sql''`","en":"`tag IN ''sql''`"},{"it":"`HAS(tag, ''sql'')`","en":"`HAS(tag, ''sql'')`"}]',0,'{"it":"`ANY` confronta con ogni elemento.","en":"`ANY` compares with each element."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'types'),2,2,'{"it":"Quale tipo per un istante preciso nel tempo?","en":"Which type for an exact instant in time?"}','[{"it":"TIMESTAMPTZ","en":"TIMESTAMPTZ"},{"it":"DATE","en":"DATE"},{"it":"TEXT","en":"TEXT"},{"it":"INTERVAL","en":"INTERVAL"}]',0,'{"it":"Con il fuso orario.","en":"With the time zone."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'types'),3,2,'{"it":"Qual è l’alternativa standard a `SERIAL`?","en":"What is the standard alternative to `SERIAL`?"}','[{"it":"GENERATED ALWAYS AS IDENTITY","en":"GENERATED ALWAYS AS IDENTITY"},{"it":"AUTO_INCREMENT","en":"AUTO_INCREMENT"},{"it":"IDENTITY(1,1)","en":"IDENTITY(1,1)"},{"it":"ROWID","en":"ROWID"}]',0,'{"it":"È lo standard SQL.","en":"It is the SQL standard."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'upsert'),1,2,'{"it":"Che cosa rappresenta `EXCLUDED`?","en":"What does `EXCLUDED` stand for?"}','[{"it":"La riga che si voleva inserire","en":"The row you tried to insert"},{"it":"La riga già presente","en":"The row already there"},{"it":"Le righe cancellate","en":"The deleted rows"},{"it":"Le colonne escluse dalla query","en":"Columns left out of the query"}]',0,'{"it":"Da lì prendi i valori nuovi.","en":"That is where you take the new values."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'upsert'),2,2,'{"it":"Che cosa fa `ON CONFLICT DO NOTHING`?","en":"What does `ON CONFLICT DO NOTHING` do?"}','[{"it":"Salta i doppioni senza errore","en":"Skips duplicates without error"},{"it":"Svuota la tabella","en":"Empties the table"},{"it":"Annulla la transazione","en":"Rolls back the transaction"},{"it":"Inserisce comunque","en":"Inserts anyway"}]',0,'{"it":"Utile per importazioni ripetibili.","en":"Handy for repeatable imports."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'upsert'),3,2,'{"it":"Quale clausola restituisce l’id appena creato?","en":"Which clause returns the id just created?"}','[{"it":"RETURNING id","en":"RETURNING id"},{"it":"OUTPUT id","en":"OUTPUT id"},{"it":"SELECT LAST id","en":"SELECT LAST id"},{"it":"GET id","en":"GET id"}]',0,'{"it":"Vale anche per `UPDATE` e `DELETE`.","en":"It works for `UPDATE` and `DELETE` too."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'jsonb'),1,2,'{"it":"Che cosa fa `@>`?","en":"What does `@>` do?"}','[{"it":"Controlla se il documento ne contiene un altro","en":"Checks whether the document contains another"},{"it":"Concatena due documenti JSON in uno solo","en":"Concatenates two JSON documents into one"},{"it":"Confronta due date","en":"Compares two dates"},{"it":"Assegna un valore","en":"Assigns a value"}]',0,'{"it":"Il “contiene” di JSONB.","en":"JSONB’s “contains”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'jsonb'),2,2,'{"it":"Quale indice si usa per JSONB?","en":"Which index is used for JSONB?"}','[{"it":"GIN","en":"GIN"},{"it":"BTREE","en":"BTREE"},{"it":"HASH","en":"HASH"},{"it":"FULLTEXT","en":"FULLTEXT"}]',0,'{"it":"Indicizza chiavi e valori dentro il documento.","en":"It indexes keys and values inside the document."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'jsonb'),3,2,'{"it":"Perché preferire `JSONB` a `JSON`?","en":"Why prefer `JSONB` to `JSON`?"}','[{"it":"È più veloce da interrogare e si indicizza","en":"It is faster to query and can be indexed"},{"it":"Conserva gli spazi originali","en":"It keeps the original spacing"},{"it":"Occupa zero spazio","en":"It takes zero space"},{"it":"Non serve validarlo","en":"It needs no validation"}]',0,'{"it":"`JSON` tiene solo il testo.","en":"`JSON` only keeps the text."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'roles'),1,2,'{"it":"Come si chiama lo schema predefinito?","en":"What is the default schema called?"}','[{"it":"public","en":"public"},{"it":"main","en":"main"},{"it":"dbo","en":"dbo"},{"it":"default","en":"default"}]',0,'{"it":"`dbo` è di SQL Server.","en":"`dbo` belongs to SQL Server."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'roles'),2,2,'{"it":"Che cosa indica `Seq Scan` in un piano?","en":"What does `Seq Scan` mean in a plan?"}','[{"it":"Legge tutta la tabella","en":"It reads the whole table"},{"it":"Usa un indice","en":"It uses an index"},{"it":"La query è fallita","en":"The query failed"},{"it":"Legge in parallelo","en":"It reads in parallel"}]',0,'{"it":"Su tabelle grandi è un campanello.","en":"On big tables it is a warning bell."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'roles'),3,2,'{"it":"Che differenza c’è tra `EXPLAIN` e `EXPLAIN ANALYZE`?","en":"What is the difference between `EXPLAIN` and `EXPLAIN ANALYZE`?"}','[{"it":"`ANALYZE` esegue davvero la query","en":"`ANALYZE` really runs the query"},{"it":"Nessuna","en":"None"},{"it":"`ANALYZE` cancella le statistiche","en":"`ANALYZE` deletes the statistics"},{"it":"`ANALYZE` funziona solo su viste","en":"`ANALYZE` only works on views"}]',0,'{"it":"E mostra i tempi reali.","en":"And shows the real timings."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'plpgsql'),1,3,'{"it":"A che cosa servono i `$$` nel corpo di una funzione?","en":"What are the `$$` for in a function body?"}','[{"it":"Indicano una variabile globale","en":"They mark a global variable"},{"it":"Racchiudono il codice senza dover raddoppiare gli apici","en":"They wrap the code without doubling the quotes"},{"it":"Rendono la funzione più veloce","en":"They make the function faster"},{"it":"Indicano un valore in dollari","en":"They mark a value in dollars"}]',1,'{"it":"Si chiamano *dollar quoting*.","en":"It is called *dollar quoting*."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'plpgsql'),2,3,'{"it":"Che cosa deve restituire una funzione usata da un trigger?","en":"What must a function used by a trigger return?"}','[{"it":"void","en":"void"},{"it":"integer","en":"integer"},{"it":"record","en":"record"},{"it":"trigger","en":"trigger"}]',3,'{"it":"`RETURNS trigger`.","en":"`RETURNS trigger`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'plpgsql'),3,3,'{"it":"In un trigger `BEFORE UPDATE`, che cosa fa `RETURN NEW`?","en":"In a `BEFORE UPDATE` trigger, what does `RETURN NEW` do?"}','[{"it":"Salva la riga, con le eventuali modifiche","en":"Saves the row, with any changes"},{"it":"Annulla l’aggiornamento","en":"Cancels the update"},{"it":"Crea una riga nuova in un’altra tabella","en":"Creates a new row in another table"},{"it":"Restituisce la riga al client e basta","en":"Just returns the row to the client"}]',0,'{"it":"`RETURN NULL` invece la scarterebbe.","en":"`RETURN NULL` would discard it instead."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'mvcc'),1,3,'{"it":"Che cosa fa un `UPDATE` con l’MVCC?","en":"What does an `UPDATE` do under MVCC?"}','[{"it":"Sovrascrive la riga sul posto","en":"Overwrites the row in place"},{"it":"Blocca tutte le letture della tabella","en":"Blocks every read on the table"},{"it":"Scrive una nuova versione della riga","en":"Writes a new version of the row"},{"it":"Cancella la riga e basta","en":"Just deletes the row"}]',2,'{"it":"La versione vecchia resta per chi la sta leggendo.","en":"The old version stays for whoever is reading it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'mvcc'),2,3,'{"it":"Chi toglie le righe morte di solito?","en":"Who usually removes dead rows?"}','[{"it":"L’autovacuum, in background","en":"Autovacuum, in the background"},{"it":"L’amministratore, a mano ogni giorno","en":"The administrator, by hand every day"},{"it":"Il client `psql` alla chiusura","en":"The `psql` client on exit"},{"it":"Nessuno: restano per sempre","en":"Nobody: they stay forever"}]',0,'{"it":"Lancia `VACUUM` e `ANALYZE` quando servono.","en":"It runs `VACUUM` and `ANALYZE` when needed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'mvcc'),3,3,'{"it":"Qual è il difetto di `VACUUM FULL`?","en":"What is the drawback of `VACUUM FULL`?"}','[{"it":"Cancella anche le righe vive","en":"It deletes live rows too"},{"it":"Non libera mai spazio","en":"It never frees space"},{"it":"Funziona solo sulle viste","en":"It only works on views"},{"it":"Blocca la tabella mentre la riscrive","en":"It locks the table while rewriting it"}]',3,'{"it":"Il `VACUUM` normale invece non blocca.","en":"Plain `VACUUM` does not lock."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'fulltext'),1,3,'{"it":"Quale operatore confronta un `tsvector` con un `tsquery`?","en":"Which operator matches a `tsvector` against a `tsquery`?"}','[{"it":"@>","en":"@>"},{"it":"@@","en":"@@"},{"it":"LIKE","en":"LIKE"},{"it":"~~","en":"~~"}]',1,'{"it":"Si legge «corrisponde a».","en":"Read it as “matches”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'fulltext'),2,3,'{"it":"Perché indicare la lingua, come `''italian''`?","en":"Why give the language, such as `''italian''`?"}','[{"it":"Per tradurre i testi in italiano","en":"To translate texts into Italian"},{"it":"Per mostrare i risultati in italiano","en":"To show results in Italian"},{"it":"Per ordinare in ordine alfabetico italiano","en":"To sort in Italian alphabetical order"},{"it":"Per ridurre le parole alla radice e togliere le parole vuote","en":"To reduce words to their stem and remove stop words"}]',3,'{"it":"«Gatti» e «gatto» diventano la stessa radice.","en":"“Gatti” and “gatto” become the same stem."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'fulltext'),3,3,'{"it":"Quale indice si usa per una colonna `tsvector`?","en":"Which index is used for a `tsvector` column?"}','[{"it":"GIN","en":"GIN"},{"it":"BRIN","en":"BRIN"},{"it":"HASH","en":"HASH"},{"it":"Nessuno, non si può","en":"None, it is not possible"}]',0,'{"it":"Lo stesso tipo usato per JSONB.","en":"The same kind used for JSONB."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'extensions'),1,3,'{"it":"Come si attiva un’estensione in un database?","en":"How do you enable an extension in a database?"}','[{"it":"Con `INSTALL PLUGIN`","en":"With `INSTALL PLUGIN`"},{"it":"Riavviando sempre il server","en":"By always restarting the server"},{"it":"Con `CREATE EXTENSION`","en":"With `CREATE EXTENSION`"},{"it":"Con `GRANT EXTENSION`","en":"With `GRANT EXTENSION`"}]',2,'{"it":"I file però devono essere installati sul server.","en":"Its files must be installed on the server, though."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'extensions'),2,3,'{"it":"A che cosa serve PostGIS?","en":"What is PostGIS for?"}','[{"it":"Ai dati geografici: punti, aree, distanze","en":"Geographic data: points, areas, distances"},{"it":"Alle immagini e ai video","en":"Images and videos"},{"it":"Ai backup automatici","en":"Automatic backups"},{"it":"Alla posta elettronica","en":"Email"}]',0,'{"it":"Per esempio «i negozi entro 5 km».","en":"For example “shops within 5 km”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'postgresql' AND slug = 'extensions'),3,3,'{"it":"In pgvector che cosa misura `<=>`?","en":"In pgvector what does `<=>` measure?"}','[{"it":"Se due testi sono identici","en":"Whether two texts are identical"},{"it":"La distanza del coseno tra vettori","en":"The cosine distance between vectors"},{"it":"La differenza tra due date","en":"The difference between two dates"},{"it":"La lunghezza di un vettore","en":"The length of a vector"}]',1,'{"it":"`<->` misura quella euclidea.","en":"`<->` measures the Euclidean one."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'file'),1,2,'{"it":"Dove tiene i dati SQLite?","en":"Where does SQLite keep its data?"}','[{"it":"In un unico file","en":"In a single file"},{"it":"In un server remoto","en":"On a remote server"},{"it":"Solo in memoria","en":"Only in memory"},{"it":"In un file per tabella","en":"In one file per table"}]',0,'{"it":"Copi il file e hai copiato il database.","en":"Copy the file and you have copied the database."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'file'),2,2,'{"it":"Che cosa sono i comandi come `.tables`?","en":"What are commands like `.tables`?"}','[{"it":"Comandi della shell sqlite3","en":"sqlite3 shell commands"},{"it":"Istruzioni SQL standard","en":"Standard SQL statements"},{"it":"Errori di battitura","en":"Typos"},{"it":"Funzioni di Python","en":"Python functions"}]',0,'{"it":"Non funzionano da un programma.","en":"They do not work from a program."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'file'),3,2,'{"it":"Quando SQLite non è la scelta giusta?","en":"When is SQLite not the right choice?"}','[{"it":"Con molti utenti che scrivono insieme","en":"With many users writing at once"},{"it":"In un’app mobile","en":"In a mobile app"},{"it":"Per un prototipo","en":"For a prototype"},{"it":"Per i dati di un’app desktop","en":"For a desktop app’s data"}]',0,'{"it":"Le scritture sono una alla volta.","en":"Writes happen one at a time."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'types'),1,2,'{"it":"Che cosa succede inserendo `''ciao''` in una colonna `INTEGER` normale?","en":"What happens when inserting `''ciao''` into a normal `INTEGER` column?"}','[{"it":"Viene accettato come testo","en":"It is accepted as text"},{"it":"Errore","en":"Error"},{"it":"Diventa 0","en":"It becomes 0"},{"it":"Diventa NULL","en":"It becomes NULL"}]',0,'{"it":"Il tipo è solo un’affinità.","en":"The type is only an affinity."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'types'),2,2,'{"it":"Che cosa fa `STRICT`?","en":"What does `STRICT` do?"}','[{"it":"Rende obbligatori i tipi delle colonne","en":"Makes column types mandatory"},{"it":"Blocca le scritture","en":"Blocks writes"},{"it":"Cifra il file","en":"Encrypts the file"},{"it":"Vieta i NULL ovunque","en":"Forbids NULL everywhere"}]',0,'{"it":"Va in fondo al `CREATE TABLE`.","en":"It goes at the end of `CREATE TABLE`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'types'),3,2,'{"it":"Che cos’è una colonna `INTEGER PRIMARY KEY`?","en":"What is an `INTEGER PRIMARY KEY` column?"}','[{"it":"Un alias del `rowid`, si numera da sola","en":"An alias of `rowid`, it numbers itself"},{"it":"Una colonna di testo","en":"A text column"},{"it":"Una chiave esterna verso un’altra tabella","en":"A foreign key to another table"},{"it":"Un indice full text","en":"A full-text index"}]',0,'{"it":"Non serve `AUTOINCREMENT`.","en":"No `AUTOINCREMENT` needed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'pragma'),1,2,'{"it":"Le chiavi esterne sono attive di base in SQLite?","en":"Are foreign keys on by default in SQLite?"}','[{"it":"No, vanno accese","en":"No, they must be turned on"},{"it":"Sì, sempre","en":"Yes, always"},{"it":"Solo nei file .db","en":"Only in .db files"},{"it":"Solo con STRICT","en":"Only with STRICT"}]',0,'{"it":"`PRAGMA foreign_keys = ON` a ogni connessione.","en":"`PRAGMA foreign_keys = ON` at every connection."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'pragma'),2,2,'{"it":"Che vantaggio dà `journal_mode = WAL`?","en":"What does `journal_mode = WAL` give you?"}','[{"it":"Letture durante le scritture","en":"Reads during writes"},{"it":"Cifratura","en":"Encryption"},{"it":"File più piccoli sempre","en":"Always smaller files"},{"it":"Più utenti con password","en":"More users with passwords"}]',0,'{"it":"Lettori e scrittore non si bloccano.","en":"Readers and writer do not block each other."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'pragma'),3,2,'{"it":"Quale PRAGMA elenca le colonne di una tabella?","en":"Which PRAGMA lists a table’s columns?"}','[{"it":"table_info","en":"table_info"},{"it":"integrity_check","en":"integrity_check"},{"it":"foreign_keys","en":"foreign_keys"},{"it":"journal_mode","en":"journal_mode"}]',0,'{"it":"Come un `DESCRIBE`.","en":"Like a `DESCRIBE`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'dates'),1,2,'{"it":"Come si salvano di solito le date in SQLite?","en":"How are dates usually stored in SQLite?"}','[{"it":"Come testo ISO","en":"As ISO text"},{"it":"Con il tipo DATE nativo","en":"With a native DATE type"},{"it":"Come immagini","en":"As images"},{"it":"Non si possono salvare","en":"They cannot be stored"}]',0,'{"it":"Il formato ISO si ordina bene.","en":"The ISO format sorts well."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'dates'),2,2,'{"it":"Che cosa restituisce `datetime(''now'', ''+7 days'')`?","en":"What does `datetime(''now'', ''+7 days'')` return?"}','[{"it":"Tra una settimana","en":"One week from now"},{"it":"Una settimana fa","en":"One week ago"},{"it":"Il giorno della settimana","en":"The day of the week"},{"it":"Sette secondi dopo","en":"Seven seconds later"}]',0,'{"it":"Il modificatore sposta la data.","en":"The modifier moves the date."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'dates'),3,2,'{"it":"Quale funzione estrae l’anno?","en":"Which function extracts the year?"}','[{"it":"strftime(''%Y'', d)","en":"strftime(''%Y'', d)"},{"it":"year(d)","en":"year(d)"},{"it":"extract(d)","en":"extract(d)"},{"it":"date_year(d)","en":"date_year(d)"}]',0,'{"it":"Con i codici di formato come `%Y`.","en":"With format codes like `%Y`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'code'),1,3,'{"it":"Come si passano i valori a una query?","en":"How do you pass values to a query?"}','[{"it":"Con i segnaposto `?`","en":"With `?` placeholders"},{"it":"Concatenando le stringhe","en":"By concatenating strings"},{"it":"Con le f-string","en":"With f-strings"},{"it":"Con `%` sul testo","en":"With `%` on the text"}]',0,'{"it":"Così non c’è SQL injection.","en":"That way there is no SQL injection."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'code'),2,3,'{"it":"Che cosa fa `with con:`?","en":"What does `with con:` do?"}','[{"it":"Apre una transazione","en":"Opens a transaction"},{"it":"Chiude il file","en":"Closes the file"},{"it":"Crea una tabella","en":"Creates a table"},{"it":"Accende WAL","en":"Turns on WAL"}]',0,'{"it":"Commit alla fine o rollback in caso di errore.","en":"Commit at the end or rollback on error."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'code'),3,3,'{"it":"Come fai una copia del database senza fermare l’app?","en":"How do you copy the database without stopping the app?"}','[{"it":"`VACUUM INTO ''copia.db''`","en":"`VACUUM INTO ''copy.db''`"},{"it":"`DROP DATABASE`","en":"`DROP DATABASE`"},{"it":"`.quit`","en":"`.quit`"},{"it":"`PRAGMA foreign_keys`","en":"`PRAGMA foreign_keys`"}]',0,'{"it":"Oppure `con.backup()`.","en":"Or `con.backup()`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'upsert'),1,3,'{"it":"Che cosa rappresenta `excluded` in un upsert?","en":"What does `excluded` stand for in an upsert?"}','[{"it":"La riga già presente nella tabella","en":"The row already in the table"},{"it":"Le colonne escluse dall’indice","en":"The columns left out of the index"},{"it":"La riga che si voleva inserire","en":"The row you tried to insert"},{"it":"Le righe cancellate dal conflitto","en":"The rows deleted by the conflict"}]',2,'{"it":"Da lì prendi i valori nuovi.","en":"That is where you take the new values."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'upsert'),2,3,'{"it":"Perché `INSERT OR REPLACE` può essere pericoloso?","en":"Why can `INSERT OR REPLACE` be dangerous?"}','[{"it":"Cancella e reinserisce la riga, perdendo le colonne non indicate","en":"It deletes and reinserts the row, losing the columns not given"},{"it":"Funziona solo sulle tabelle `STRICT`","en":"It only works on `STRICT` tables"},{"it":"Blocca il file per sempre","en":"It locks the file forever"},{"it":"Duplica sempre la riga","en":"It always duplicates the row"}]',0,'{"it":"Meglio `ON CONFLICT … DO UPDATE`.","en":"Better `ON CONFLICT … DO UPDATE`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'upsert'),3,3,'{"it":"Da quale versione SQLite supporta `RETURNING`?","en":"Since which version does SQLite support `RETURNING`?"}','[{"it":"3.0","en":"3.0"},{"it":"2.8","en":"2.8"},{"it":"3.7","en":"3.7"},{"it":"3.35","en":"3.35"}]',3,'{"it":"Uscita nel 2021.","en":"Released in 2021."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'json'),1,3,'{"it":"Come salva il JSON SQLite?","en":"How does SQLite store JSON?"}','[{"it":"In un tipo JSON nativo con indici dedicati","en":"In a native JSON type with dedicated indexes"},{"it":"Come testo, letto dalle funzioni JSON","en":"As text, read by the JSON functions"},{"it":"In un file separato per documento","en":"In a separate file per document"},{"it":"Non può salvarlo","en":"It cannot store it"}]',1,'{"it":"Le funzioni JSON sono incluse di base.","en":"The JSON functions are built in."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'json'),2,3,'{"it":"Che cosa fa `json_each`?","en":"What does `json_each` do?"}','[{"it":"Controlla che il JSON sia valido","en":"Checks that the JSON is valid"},{"it":"Unisce più documenti in uno","en":"Merges several documents into one"},{"it":"Comprime il JSON in binario","en":"Compresses the JSON into binary"},{"it":"Trasforma gli elementi di un array in righe","en":"Turns an array’s elements into rows"}]',3,'{"it":"Si usa nel `FROM`, come una tabella.","en":"It is used in the `FROM`, like a table."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'json'),3,3,'{"it":"Come eviti di salvare JSON non valido?","en":"How do you avoid storing invalid JSON?"}','[{"it":"Con `CHECK (json_valid(dati))`","en":"With `CHECK (json_valid(dati))`"},{"it":"Con `PRAGMA json = ON`","en":"With `PRAGMA json = ON`"},{"it":"Con una tabella `STRICT JSON`","en":"With a `STRICT JSON` table"},{"it":"Non si può evitare","en":"It cannot be avoided"}]',0,'{"it":"Il vincolo rifiuta il testo sbagliato.","en":"The constraint rejects bad text."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'fts5'),1,3,'{"it":"Come si crea una tabella di ricerca FTS5?","en":"How do you create an FTS5 search table?"}','[{"it":"`CREATE TABLE … FULLTEXT`","en":"`CREATE TABLE … FULLTEXT`"},{"it":"`CREATE INDEX … USING fts5`","en":"`CREATE INDEX … USING fts5`"},{"it":"`CREATE VIRTUAL TABLE … USING fts5(…)`","en":"`CREATE VIRTUAL TABLE … USING fts5(…)`"},{"it":"`PRAGMA fts5 = ON`","en":"`PRAGMA fts5 = ON`"}]',2,'{"it":"È una tabella virtuale.","en":"It is a virtual table."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'fts5'),2,3,'{"it":"Che cosa trova `latt*`?","en":"What does `latt*` find?"}','[{"it":"Solo la parola «latt»","en":"Only the word “latt”"},{"it":"Le parole che iniziano con «latt»","en":"Words starting with “latt”"},{"it":"Le parole che finiscono con «latt»","en":"Words ending with “latt”"},{"it":"Tutte le parole tranne «latt»","en":"Every word except “latt”"}]',1,'{"it":"È una ricerca per prefisso.","en":"It is a prefix search."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sqlite' AND slug = 'fts5'),3,3,'{"it":"Come ordini i risultati per pertinenza?","en":"How do you sort results by relevance?"}','[{"it":"`ORDER BY titolo`","en":"`ORDER BY titolo`"},{"it":"`ORDER BY rowid DESC`","en":"`ORDER BY rowid DESC`"},{"it":"`ORDER BY random()`","en":"`ORDER BY random()`"},{"it":"`ORDER BY rank`","en":"`ORDER BY rank`"}]',3,'{"it":"`rank` è una colonna nascosta di FTS5.","en":"`rank` is a hidden FTS5 column."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mssql' AND slug = 'basics'),1,2,'{"it":"Come prendi le prime 5 righe in T-SQL?","en":"How do you take the first 5 rows in T-SQL?"}','[{"it":"SELECT TOP (5) …","en":"SELECT TOP (5) …"},{"it":"SELECT … LIMIT 5","en":"SELECT … LIMIT 5"},{"it":"SELECT FIRST 5 …","en":"SELECT FIRST 5 …"},{"it":"SELECT … ROWS 5","en":"SELECT … ROWS 5"}]',0,'{"it":"`LIMIT` non esiste in SQL Server.","en":"`LIMIT` does not exist in SQL Server."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mssql' AND slug = 'basics'),2,2,'{"it":"Qual è lo schema predefinito?","en":"What is the default schema?"}','[{"it":"dbo","en":"dbo"},{"it":"public","en":"public"},{"it":"main","en":"main"},{"it":"sys","en":"sys"}]',0,'{"it":"Database owner.","en":"Database owner."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mssql' AND slug = 'basics'),3,2,'{"it":"Che cos’è `GO`?","en":"What is `GO`?"}','[{"it":"Un separatore di blocchi per lo strumento","en":"A batch separator for the tool"},{"it":"Un’istruzione che avvia una transazione","en":"A statement that starts a transaction"},{"it":"Un tipo di dato","en":"A data type"},{"it":"Un ciclo","en":"A loop"}]',0,'{"it":"Il server non lo vede nemmeno.","en":"The server never even sees it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mssql' AND slug = 'types'),1,2,'{"it":"Che cosa fa `IDENTITY(1,1)`?","en":"What does `IDENTITY(1,1)` do?"}','[{"it":"Numera da 1 di 1 in 1","en":"Numbers from 1, step 1"},{"it":"Crea una colonna di testo","en":"Creates a text column"},{"it":"Rende la colonna unica e basta","en":"Just makes the column unique"},{"it":"Duplica la riga","en":"Duplicates the row"}]',0,'{"it":"È l’`AUTO_INCREMENT` di SQL Server.","en":"It is SQL Server’s `AUTO_INCREMENT`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mssql' AND slug = 'types'),2,2,'{"it":"Perché scrivere `N''Zoë''`?","en":"Why write `N''Zoë''`?"}','[{"it":"È un letterale Unicode","en":"It is a Unicode literal"},{"it":"Significa “nullo”","en":"It means “null”"},{"it":"È un numero","en":"It is a number"},{"it":"È un commento","en":"It is a comment"}]',0,'{"it":"Senza `N` i caratteri speciali possono perdersi.","en":"Without `N` special characters can get lost."}',NULL);
