INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mssql' AND slug = 'procedures'),3,2,'{"it":"Come rendi facoltativo un parametro?","en":"How do you make a parameter optional?"}','[{"it":"Gli dai un valore predefinito","en":"Give it a default value"},{"it":"Lo scrivi in minuscolo","en":"Write it in lowercase"},{"it":"Lo metti per primo","en":"Put it first"},{"it":"Non si può","en":"You cannot"}]',0,'{"it":"Per esempio `@Da DATE = NULL`.","en":"For example `@Da DATE = NULL`."}',NULL);
