INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mssql' AND slug = 'paging'),3,3,'{"it":"Che cosa fa `WHEN NOT MATCHED THEN INSERT`?","en":"What does `WHEN NOT MATCHED THEN INSERT` do?"}','[{"it":"Inserisce le righe nuove dell’origine","en":"Inserts the source’s new rows"},{"it":"Cancella le righe uguali","en":"Deletes matching rows"},{"it":"Aggiorna tutto","en":"Updates everything"},{"it":"Annulla il MERGE","en":"Cancels the MERGE"}]',0,'{"it":"Quelle che nella destinazione non ci sono.","en":"The ones missing from the target."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mssql' AND slug = 'temp'),1,3,'{"it":"Che cosa indica il `#` all’inizio del nome di una tabella?","en":"What does `#` at the start of a table name mean?"}','[{"it":"Una tabella di sistema in sola lettura","en":"A read-only system table"},{"it":"Una tabella cifrata","en":"An encrypted table"},{"it":"Una tabella temporanea della sessione","en":"A session temporary table"},{"it":"Un commento","en":"A comment"}]',2,'{"it":"Sparisce quando la sessione si chiude.","en":"It vanishes when the session closes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mssql' AND slug = 'temp'),2,3,'{"it":"Che cosa fa `SELECT … INTO #Spese`?","en":"What does `SELECT … INTO #Spese` do?"}','[{"it":"Crea la tabella e la riempie con il risultato","en":"Creates the table and fills it with the result"},{"it":"Aggiunge righe a una tabella che deve già esistere","en":"Adds rows to a table that must already exist"},{"it":"Esporta il risultato in un file","en":"Exports the result to a file"},{"it":"Assegna il risultato a una variabile","en":"Assigns the result to a variable"}]',0,'{"it":"Per aggiungere a una tabella esistente si usa `INSERT INTO … SELECT`.","en":"To add to an existing table you use `INSERT INTO … SELECT`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mssql' AND slug = 'temp'),3,3,'{"it":"Dove vengono salvate le tabelle temporanee?","en":"Where are temporary tables stored?"}','[{"it":"Nella memoria del client","en":"In the client’s memory"},{"it":"Nel database `master`","en":"In the `master` database"},{"it":"In un file accanto alla query","en":"In a file next to the query"},{"it":"Nel database di sistema `tempdb`","en":"In the `tempdb` system database"}]',3,'{"it":"È condiviso da tutto il server.","en":"It is shared by the whole server."}',NULL);
