INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mssql' AND slug = 'indexes'),3,3,'{"it":"Che cosa è meglio vedere nel piano per una ricerca su pochi valori?","en":"What is best to see in the plan for a lookup of a few values?"}','[{"it":"Table Scan","en":"Table Scan"},{"it":"Index Scan","en":"Index Scan"},{"it":"Index Seek","en":"Index Seek"},{"it":"Sort","en":"Sort"}]',2,'{"it":"Una ricerca mirata, non una lettura completa.","en":"A targeted lookup, not a full read."}',NULL);
