INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mongodb' AND slug = 'update'),2,1,'{"it":"Che cosa fa `upsert: true`?","en":"What does `upsert: true` do?"}','[{"it":"Crea il documento se non esiste","en":"Creates the document if it does not exist"},{"it":"Aggiorna tutti i documenti","en":"Updates every document"},{"it":"Annulla l’aggiornamento","en":"Undoes the update"},{"it":"Cancella i doppioni","en":"Deletes duplicates"}]',0,'{"it":"Update + insert.","en":"Update + insert."}',NULL);
