INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mongodb' AND slug = 'aggregation'),2,1,'{"it":"Che cosa significa `\\"$importo\\"` dentro `$sum`?","en":"What does `\\"$importo\\"` mean inside `$sum`?"}','[{"it":"Il valore del campo importo","en":"The value of the importo field"},{"it":"Il testo “$importo”","en":"The text “$importo”"},{"it":"Una variabile globale","en":"A global variable"},{"it":"Un errore","en":"An error"}]',0,'{"it":"Il dollaro legge il campo.","en":"The dollar reads the field."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mongodb' AND slug = 'aggregation'),3,1,'{"it":"Perché mettere `$match` all’inizio?","en":"Why put `$match` first?"}','[{"it":"Meno documenti da elaborare","en":"Fewer documents to process"},{"it":"È obbligatorio","en":"It is mandatory"},{"it":"Ordina i risultati","en":"It sorts the results"},{"it":"Crea un indice","en":"It creates an index"}]',0,'{"it":"E può usare gli indici.","en":"And it can use indexes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mongodb' AND slug = 'modeling'),1,2,'{"it":"Che cosa indica `COLLSCAN` in un explain?","en":"What does `COLLSCAN` mean in an explain?"}','[{"it":"Legge tutta la collezione","en":"It reads the whole collection"},{"it":"Usa un indice","en":"It uses an index"},{"it":"La query è vuota","en":"The query is empty"},{"it":"C’è un errore di sintassi","en":"There is a syntax error"}]',0,'{"it":"`IXSCAN` vuol dire indice.","en":"`IXSCAN` means index."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mongodb' AND slug = 'modeling'),2,2,'{"it":"Quando conviene incorporare i dati?","en":"When is embedding data a good idea?"}','[{"it":"Quando si leggono sempre insieme e sono limitati","en":"When always read together and bounded"},{"it":"Quando crescono senza limite","en":"When they grow without limit"},{"it":"Quando sono condivisi da tutti","en":"When everyone shares them"},{"it":"Mai","en":"Never"}]',0,'{"it":"Si leggono insieme, si salvano insieme.","en":"Read together, stored together."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mongodb' AND slug = 'modeling'),3,2,'{"it":"Qual è la dimensione massima di un documento?","en":"What is the maximum size of a document?"}','[{"it":"16 MB","en":"16 MB"},{"it":"1 MB","en":"1 MB"},{"it":"1 GB","en":"1 GB"},{"it":"Nessun limite","en":"No limit"}]',0,'{"it":"Un motivo in più per non incorporare array infiniti.","en":"One more reason not to embed endless arrays."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mongodb' AND slug = 'arrays'),1,2,'{"it":"Quale operatore aggiunge a un array solo se il valore manca?","en":"Which operator adds to an array only if the value is missing?"}','[{"it":"$push","en":"$push"},{"it":"$addToSet","en":"$addToSet"},{"it":"$set","en":"$set"},{"it":"$inc","en":"$inc"}]',1,'{"it":"`$push` invece aggiunge sempre.","en":"`$push` instead always adds."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mongodb' AND slug = 'arrays'),2,2,'{"it":"Perché usare `$elemMatch`?","en":"Why use `$elemMatch`?"}','[{"it":"Per contare gli elementi di un array","en":"To count an array’s elements"},{"it":"Per ordinare gli elementi di un array","en":"To sort an array’s elements"},{"it":"Per unire due array in uno","en":"To merge two arrays into one"},{"it":"Perché più condizioni valgano per lo stesso elemento","en":"So several conditions hold for the same element"}]',3,'{"it":"Altrimenti possono valere per elementi diversi.","en":"Otherwise they may hold for different elements."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mongodb' AND slug = 'arrays'),3,2,'{"it":"Che cosa aggiorna `\\"righe.$.qta\\"`?","en":"What does `\\"righe.$.qta\\"` update?"}','[{"it":"Tutti gli elementi di `righe`","en":"Every element of `righe`"},{"it":"L’ultimo elemento di `righe`","en":"The last element of `righe`"},{"it":"L’elemento trovato dal filtro","en":"The element found by the filter"},{"it":"Un nuovo campo chiamato `$`","en":"A new field called `$`"}]',2,'{"it":"Per tutti si usa `$[]`.","en":"For all of them you use `$[]`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mongodb' AND slug = 'validation'),1,2,'{"it":"Che cosa succede inserendo un documento che non rispetta il validatore?","en":"What happens when inserting a document that breaks the validator?"}','[{"it":"Viene rifiutato con un errore","en":"It is rejected with an error"},{"it":"Viene corretto in automatico","en":"It is fixed automatically"},{"it":"Viene salvato in un’altra collezione","en":"It is saved in another collection"},{"it":"Viene salvato senza i campi sbagliati","en":"It is saved without the wrong fields"}]',0,'{"it":"Con l’azione predefinita, `error`.","en":"With the default action, `error`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mongodb' AND slug = 'validation'),2,2,'{"it":"Come aggiungi un validatore a una collezione esistente?","en":"How do you add a validator to an existing collection?"}','[{"it":"Ricreando il database","en":"By recreating the database"},{"it":"Con `createIndex`","en":"With `createIndex`"},{"it":"Con un trigger","en":"With a trigger"},{"it":"Con il comando `collMod`","en":"With the `collMod` command"}]',3,'{"it":"`db.runCommand({ collMod: \\"utenti\\", validator: … })`.","en":"`db.runCommand({ collMod: \\"utenti\\", validator: … })`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mongodb' AND slug = 'validation'),3,2,'{"it":"A che cosa serve `validationAction: \\"warn\\"`?","en":"What is `validationAction: \\"warn\\"` for?"}','[{"it":"A cancellare i documenti sbagliati","en":"Deleting wrong documents"},{"it":"A registrare un avviso senza rifiutare","en":"Logging a warning without rejecting"},{"it":"A mandare un’email all’amministratore","en":"Emailing the administrator"},{"it":"A bloccare tutte le letture","en":"Blocking every read"}]',1,'{"it":"Per introdurre le regole con calma.","en":"To bring rules in gently."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mongodb' AND slug = 'transactions'),1,2,'{"it":"Serve una transazione per aggiornare un solo documento?","en":"Do you need a transaction to update a single document?"}','[{"it":"Sì, sempre","en":"Yes, always"},{"it":"Solo se il documento ha array","en":"Only if the document has arrays"},{"it":"No, è già atomico","en":"No, it is already atomic"},{"it":"Solo nei giorni festivi","en":"Only on holidays"}]',2,'{"it":"Anche se cambia più campi.","en":"Even if it changes several fields."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mongodb' AND slug = 'transactions'),2,2,'{"it":"Che cosa richiedono le transazioni multi-documento?","en":"What do multi-document transactions require?"}','[{"it":"Un replica set o un cluster sharded","en":"A replica set or a sharded cluster"},{"it":"Un server senza indici","en":"A server with no indexes"},{"it":"Una collezione con validatore","en":"A collection with a validator"},{"it":"Il pacchetto di SQL Server","en":"The SQL Server package"}]',0,'{"it":"Un singolo server autonomo non basta.","en":"A single standalone server is not enough."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mongodb' AND slug = 'transactions'),3,2,'{"it":"Che cosa garantisce `w: \\"majority\\"`?","en":"What does `w: \\"majority\\"` guarantee?"}','[{"it":"Che la scrittura sia più veloce","en":"That the write is faster"},{"it":"Che la scrittura vada su un solo server","en":"That the write goes to a single server"},{"it":"Che i dati siano cifrati","en":"That the data is encrypted"},{"it":"Che la maggioranza dei nodi abbia ricevuto la scrittura","en":"That the majority of nodes received the write"}]',3,'{"it":"Così sopravvive alla caduta del primario.","en":"So it survives the primary failing."}',NULL);
