INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'swift-intermediate' AND slug = 'actors'),1,3,'{"it":"Che cosa garantisce un actor?","en":"What does an actor guarantee?"}','[{"it":"Che il suo stato sia toccato da un compito alla volta","en":"That its state is touched by one task at a time"},{"it":"Che il codice giri sul thread principale","en":"That the code runs on the main thread"},{"it":"Che le sue funzioni non lancino errori","en":"That its functions never throw"},{"it":"Che i dati siano salvati su disco","en":"That the data is saved to disk"}]',0,'{"it":"Così le data race non sono possibili.","en":"That way data races cannot happen."}',NULL);
