INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kotlin-base' AND slug = 'strings'),3,2,'{"it":"Che cosa fa `trimIndent()` su una stringa tra tre virgolette?","en":"What does `trimIndent()` do on a triple-quoted string?"}','[{"it":"Toglie il rientro comune a tutte le righe","en":"Removes the indentation common to all lines"},{"it":"Unisce tutte le righe in una","en":"Joins all lines into one"},{"it":"Converte il testo in maiuscolo","en":"Converts the text to capitals"},{"it":"Toglie le righe vuote in mezzo al testo","en":"Removes the blank lines inside the text"}]',0,'{"it":"Toglie anche la prima e l’ultima riga se sono vuote.","en":"It also drops the first and last lines if blank."}',NULL);
