INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kotlin-base' AND slug = 'lambdas'),2,2,'{"it":"Come scrivi la chiamata se l’ultimo parametro è una lambda?","en":"How do you write the call if the last parameter is a lambda?"}','[{"it":"Solo `ripeti(3, { … })`","en":"Only `ripeti(3, { … })`"},{"it":"`ripeti(3) { … }`, con la lambda fuori dalle parentesi","en":"`ripeti(3) { … }`, with the lambda outside the brackets"},{"it":"`ripeti { … }(3)`","en":"`ripeti { … }(3)`"},{"it":"`ripeti(3) -> { … }`","en":"`ripeti(3) -> { … }`"}]',1,'{"it":"È la trailing lambda, usata ovunque in Compose.","en":"It is the trailing lambda, used everywhere in Compose."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kotlin-base' AND slug = 'lambdas'),3,2,'{"it":"Che cosa restituisce la lambda `{ x: Int -> x + 1 }`?","en":"What does the lambda `{ x: Int -> x + 1 }` return?"}','[{"it":"Sempre Unit","en":"Always Unit"},{"it":"Il valore del parametro x","en":"The value of parameter x"},{"it":"Niente: serve `return`","en":"Nothing: it needs `return`"},{"it":"Il valore dell’ultima espressione, x + 1","en":"The value of the last expression, x + 1"}]',3,'{"it":"Nelle lambda non si scrive `return`.","en":"In lambdas you do not write `return`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kotlin-base' AND slug = 'exceptions'),1,2,'{"it":"Kotlin obbliga a catturare le eccezioni come Java con le checked exception?","en":"Does Kotlin force you to catch exceptions as Java does with checked exceptions?"}','[{"it":"Sì, sempre","en":"Yes, always"},{"it":"Solo nelle funzioni suspend","en":"Only in suspend functions"},{"it":"No, non esistono eccezioni controllate","en":"No, there are no checked exceptions"},{"it":"Solo per gli errori di rete","en":"Only for network errors"}]',2,'{"it":"Sta a te decidere dove gestirle.","en":"It is up to you where to handle them."}',NULL);
