INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kotlin-intermediate' AND slug = 'scope-functions'),1,3,'{"it":"Che cosa restituisce `apply`?","en":"What does `apply` return?"}','[{"it":"Il risultato dell’ultima riga","en":"The result of the last line"},{"it":"Unit","en":"Unit"},{"it":"L’oggetto su cui è chiamata","en":"The object it is called on"},{"it":"Un Boolean","en":"A Boolean"}]',2,'{"it":"Per questo è perfetta per configurare.","en":"That is why it is perfect for configuring."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kotlin-intermediate' AND slug = 'scope-functions'),2,3,'{"it":"Quale forma esegue un blocco solo se il valore non è null?","en":"Which form runs a block only if the value is not null?"}','[{"it":"x?.let { }","en":"x?.let { }"},{"it":"x!!.run { }","en":"x!!.run { }"},{"it":"with(x) { }","en":"with(x) { }"},{"it":"x?.also = { }","en":"x?.also = { }"}]',0,'{"it":"La chiamata sicura salta il blocco se x è null.","en":"The safe call skips the block if x is null."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kotlin-intermediate' AND slug = 'scope-functions'),3,3,'{"it":"Dentro `apply`, come ti riferisci all’oggetto?","en":"Inside `apply`, how do you refer to the object?"}','[{"it":"Con `it`","en":"With `it`"},{"it":"Con `self`","en":"With `self`"},{"it":"Con `obj`","en":"With `obj`"},{"it":"Con `this`, spesso sottinteso","en":"With `this`, often implicit"}]',3,'{"it":"Per questo scrivi direttamente `nome = \\"Ada\\"`.","en":"That is why you write `nome = \\"Ada\\"` directly."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kotlin-intermediate' AND slug = 'generics'),1,3,'{"it":"Perché `val a: List<Any> = listOf(1, 2)` compila?","en":"Why does `val a: List<Any> = listOf(1, 2)` compile?"}','[{"it":"Kotlin converte gli Int in String","en":"Kotlin converts the Ints to Strings"},{"it":"List è covariante: è dichiarata con `out`","en":"List is covariant: it is declared with `out`"},{"it":"List non ha un tipo","en":"List has no type"},{"it":"Perché Any è un sottotipo di Int","en":"Because Any is a subtype of Int"}]',1,'{"it":"`MutableList` invece non lo è.","en":"`MutableList` is not."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kotlin-intermediate' AND slug = 'generics'),2,3,'{"it":"Che cosa significa `in T` in un’interfaccia?","en":"What does `in T` mean in an interface?"}','[{"it":"T può solo uscire dai metodi","en":"T can only come out of methods"},{"it":"T è un tipo interno al modulo","en":"T is a module-internal type"},{"it":"T può solo entrare, come parametro","en":"T can only go in, as a parameter"},{"it":"T è facoltativo","en":"T is optional"}]',2,'{"it":"È la controvarianza.","en":"It is contravariance."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kotlin-intermediate' AND slug = 'generics'),3,3,'{"it":"A che cosa serve `reified`?","en":"What is `reified` for?"}','[{"it":"A rendere la funzione più veloce","en":"Making the function faster"},{"it":"A creare una data class","en":"Creating a data class"},{"it":"A rendere T nullable","en":"Making T nullable"},{"it":"A conoscere il tipo T a runtime in una funzione inline","en":"Knowing type T at runtime in an inline function"}]',3,'{"it":"Permette controlli come `is T`.","en":"It allows checks such as `is T`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kotlin-intermediate' AND slug = 'compose-state'),1,3,'{"it":"Che cos’è lo state hoisting?","en":"What is state hoisting?"}','[{"it":"Salvare lo stato in un file","en":"Saving state to a file"},{"it":"Passare a una composable il valore e una funzione per cambiarlo","en":"Passing a composable the value and a function to change it"},{"it":"Mettere tutto lo stato in variabili globali","en":"Putting all state in global variables"},{"it":"Ricreare lo stato a ogni ridisegno","en":"Recreating state at every redraw"}]',1,'{"it":"Lo stato sale verso chi lo possiede.","en":"State moves up to its owner."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kotlin-intermediate' AND slug = 'compose-state'),2,3,'{"it":"Perché lo stato di una schermata sta in un ViewModel?","en":"Why does a screen’s state live in a ViewModel?"}','[{"it":"Sopravvive ai cambi di configurazione come la rotazione","en":"It survives configuration changes such as rotation"},{"it":"Disegna l’interfaccia più in fretta","en":"It draws the interface faster"},{"it":"Sostituisce il database","en":"It replaces the database"},{"it":"È obbligatorio per usare Text","en":"It is required to use Text"}]',0,'{"it":"E separa la logica dall’interfaccia.","en":"And it separates logic from the interface."}',NULL);
