INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rust-intermediate' AND slug = 'trait-objects'),1,3,'{"it":"Come metti un Cerchio e un Quadrato nello stesso Vec?","en":"How do you put a Cerchio and a Quadrato in the same Vec?"}','[{"it":"Vec<Forma>","en":"Vec<Forma>"},{"it":"Vec<impl Forma>","en":"Vec<impl Forma>"},{"it":"Vec<Box<dyn Forma>>","en":"Vec<Box<dyn Forma>>"},{"it":"Vec<T: Forma>","en":"Vec<T: Forma>"}]',2,'{"it":"Il Box dà a ogni elemento la stessa dimensione.","en":"The Box gives every element the same size."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rust-intermediate' AND slug = 'trait-objects'),2,3,'{"it":"Quando si sceglie il metodo da chiamare con `dyn Trait`?","en":"When is the method to call chosen with `dyn Trait`?"}','[{"it":"Mentre il programma gira","en":"While the program runs"},{"it":"Durante la compilazione","en":"During compilation"},{"it":"Quando si scrive il Cargo.toml","en":"When writing Cargo.toml"},{"it":"Mai: dyn non chiama metodi","en":"Never: dyn calls no methods"}]',0,'{"it":"Attraverso una tabella di metodi, la vtable.","en":"Through a table of methods, the vtable."}',NULL);
