INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rust-intermediate' AND slug = 'closures'),2,3,'{"it":"Perché in `crea_moltiplicatore` serve `move`?","en":"Why does `crea_moltiplicatore` need `move`?"}','[{"it":"Per rendere la closure più veloce","en":"To make the closure faster"},{"it":"Perché le closure non possono avere parametri","en":"Because closures cannot have parameters"},{"it":"Per poterla chiamare più volte","en":"So it can be called several times"},{"it":"Perché `k` sparisce alla fine della funzione e la closure deve possederlo","en":"Because `k` disappears at the end of the function and the closure must own it"}]',3,'{"it":"Altrimenti terrebbe un riferimento a un valore distrutto.","en":"Otherwise it would hold a reference to a dropped value."}',NULL);
