INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'what'),3,1,'{"it":"Quale di questi è AI generativa?","en":"Which of these is generative AI?"}','[{"it":"Un modello che scrive un racconto","en":"A model that writes a story"},{"it":"Un termostato","en":"A thermostat"},{"it":"Un foglio di calcolo","en":"A spreadsheet"},{"it":"Un filtro a regole fisse","en":"A fixed-rule filter"}]',0,'{"it":"Crea contenuti nuovi.","en":"It creates new content."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'data'),1,1,'{"it":"Che cosa succede durante l’addestramento?","en":"What happens during training?"}','[{"it":"Il modello regola i parametri sugli esempi","en":"The model tunes its parameters on examples"},{"it":"Il modello risponde agli utenti","en":"The model answers users"},{"it":"Si cancellano i dati","en":"The data is deleted"},{"it":"Si scrive il codice dell’app","en":"The app code is written"}]',0,'{"it":"L’inferenza viene dopo.","en":"Inference comes after."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'data'),2,1,'{"it":"Che cos’è l’inferenza?","en":"What is inference?"}','[{"it":"Usare il modello su dati nuovi","en":"Using the model on new data"},{"it":"Raccogliere dati","en":"Collecting data"},{"it":"Ripulire i dati","en":"Cleaning the data"},{"it":"Comprare GPU","en":"Buying GPUs"}]',0,'{"it":"È quello che fai quando chatti con un modello.","en":"It is what you do when you chat with a model."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'data'),3,1,'{"it":"Perché si tiene da parte un test set?","en":"Why keep a test set aside?"}','[{"it":"Per misurare il modello su dati mai visti","en":"To measure the model on unseen data"},{"it":"Per addestrare più velocemente","en":"To train faster"},{"it":"Per risparmiare spazio","en":"To save space"},{"it":"Per fare un backup","en":"To make a backup"}]',0,'{"it":"Altrimenti il voto sarebbe falsato.","en":"Otherwise the score would be inflated."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'llm'),1,1,'{"it":"Che cosa fa, alla base, un LLM?","en":"What does an LLM do, at its core?"}','[{"it":"Prevede il token successivo","en":"Predicts the next token"},{"it":"Cerca la risposta in un database","en":"Looks the answer up in a database"},{"it":"Copia pagine web intere","en":"Copies whole web pages"},{"it":"Esegue regole scritte a mano","en":"Runs hand-written rules"}]',0,'{"it":"Un token dopo l’altro.","en":"One token after another."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'llm'),2,1,'{"it":"Che cos’è un token?","en":"What is a token?"}','[{"it":"Un pezzo di testo, spesso parte di una parola","en":"A piece of text, often part of a word"},{"it":"Una password","en":"A password"},{"it":"Una moneta digitale","en":"A digital coin"},{"it":"Una riga di codice del programma","en":"A line of the program’s code"}]',0,'{"it":"Si paga e si misura in token.","en":"You pay and measure in tokens."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'llm'),3,1,'{"it":"Che cos’è la finestra di contesto?","en":"What is the context window?"}','[{"it":"Quanto testo il modello considera in una volta","en":"How much text the model considers at once"},{"it":"La finestra della chat dove scrivi","en":"The chat window where you type"},{"it":"Il tempo di risposta","en":"The response time"},{"it":"Il numero di utenti","en":"The number of users"}]',0,'{"it":"Oltre quel limite il testo non entra.","en":"Beyond that limit text does not fit."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'limits'),1,1,'{"it":"Che cos’è un’allucinazione?","en":"What is a hallucination?"}','[{"it":"Un’informazione inventata detta con sicurezza","en":"Made-up information stated confidently"},{"it":"Un errore di rete durante la risposta","en":"A network error during the answer"},{"it":"Un’immagine generata","en":"A generated image"},{"it":"Un modello spento","en":"A model that is off"}]',0,'{"it":"Plausibile non vuol dire vero.","en":"Plausible does not mean true."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'limits'),2,1,'{"it":"Che cos’è la data di taglio?","en":"What is the knowledge cutoff?"}','[{"it":"Il limite dei fatti che il modello conosce","en":"The limit of facts the model knows"},{"it":"La scadenza dell’abbonamento","en":"The subscription expiry"},{"it":"La lunghezza massima della risposta","en":"The maximum answer length"},{"it":"L’ora di manutenzione","en":"The maintenance hour"}]',0,'{"it":"Dopo quella data non sa, a meno che cerchi.","en":"After that date it does not know, unless it searches."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'limits'),3,1,'{"it":"Qual è una buona difesa dalle allucinazioni?","en":"What is a good defence against hallucinations?"}','[{"it":"Verificare le fonti citate","en":"Checking the cited sources"},{"it":"Fare domande più lunghe","en":"Asking longer questions"},{"it":"Usare il maiuscolo","en":"Using capital letters"},{"it":"Ripetere la domanda finché piace la risposta","en":"Repeating the question until you like the answer"}]',0,'{"it":"Le fonti si controllano.","en":"Sources must be checked."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'uses'),1,2,'{"it":"Suggerire un film in base a quelli visti è…","en":"Suggesting a film based on those you watched is…"}','[{"it":"Raccomandazione","en":"Recommendation"},{"it":"Visione","en":"Vision"},{"it":"Traduzione","en":"Translation"},{"it":"Compressione","en":"Compression"}]',0,'{"it":"Impara dai gusti simili.","en":"It learns from similar tastes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'uses'),2,2,'{"it":"Quale compito è ad alto rischio?","en":"Which task is high risk?"}','[{"it":"Decidere chi riceve un prestito","en":"Deciding who gets a loan"},{"it":"Suggerire una canzone","en":"Suggesting a song"},{"it":"Correggere un refuso","en":"Fixing a typo"},{"it":"Scegliere un emoji","en":"Picking an emoji"}]',0,'{"it":"Tocca diritti e opportunità.","en":"It touches rights and opportunities."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'uses'),3,2,'{"it":"Quale legge europea regola l’AI?","en":"Which European law regulates AI?"}','[{"it":"AI Act","en":"AI Act"},{"it":"GDPR Act","en":"GDPR Act"},{"it":"Digital Cookie Act","en":"Digital Cookie Act"},{"it":"Code Act","en":"Code Act"}]',0,'{"it":"Classifica i sistemi per livello di rischio.","en":"It classifies systems by risk level."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'learning'),1,2,'{"it":"Raggruppare clienti simili senza sapere in anticipo i gruppi è apprendimento…","en":"Grouping similar customers without knowing the groups in advance is…"}','[{"it":"Supervisionato, con le etichette","en":"Supervised, with labels"},{"it":"Per rinforzo, con i premi","en":"Reinforcement, with rewards"},{"it":"Non supervisionato, senza risposte","en":"Unsupervised, with no answers"},{"it":"A regole scritte a mano","en":"Based on hand-written rules"}]',2,'{"it":"Nessuno gli dice quali sono i gruppi.","en":"Nobody tells it what the groups are."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'learning'),2,2,'{"it":"Che cosa riceve un agente nell’apprendimento per rinforzo?","en":"What does an agent receive in reinforcement learning?"}','[{"it":"Premi o penalità per le sue azioni","en":"Rewards or penalties for its actions"},{"it":"Un elenco di risposte giuste già pronte","en":"A ready list of right answers"},{"it":"Solo dati senza alcun riscontro","en":"Only data with no feedback at all"},{"it":"Le regole scritte dal programmatore","en":"The rules written by the programmer"}]',0,'{"it":"Impara provando e sbagliando.","en":"It learns by trial and error."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'learning'),3,2,'{"it":"Riconoscere cifre scritte a mano da migliaia di esempi etichettati è…","en":"Recognising handwritten digits from thousands of labelled examples is…"}','[{"it":"Non supervisionato","en":"Unsupervised"},{"it":"Supervisionato","en":"Supervised"},{"it":"Per rinforzo","en":"Reinforcement"},{"it":"Nessun tipo di ML","en":"No kind of ML"}]',1,'{"it":"Ogni esempio ha la sua risposta.","en":"Each example has its answer."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'multimodal'),1,2,'{"it":"Che cosa sa fare un modello multimodale?","en":"What can a multimodal model do?"}','[{"it":"Lavorare solo con testo, ma più in fretta","en":"Work only with text, but faster"},{"it":"Funzionare senza essere addestrato","en":"Work without being trained"},{"it":"Tradurre solo tra più lingue","en":"Only translate between languages"},{"it":"Capire più tipi di dati, come testo e immagini","en":"Understand several kinds of data, like text and images"}]',3,'{"it":"Testo, immagini, audio, video.","en":"Text, images, audio, video."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'multimodal'),2,2,'{"it":"Da dove parte un modello di diffusione per creare un’immagine?","en":"Where does a diffusion model start from to create an image?"}','[{"it":"Da un’immagine presa dal web e ritoccata","en":"From a web image that it retouches"},{"it":"Da puro rumore, ripulito passo dopo passo","en":"From pure noise, cleaned step by step"},{"it":"Da un disegno fatto a mano dall’utente","en":"From a hand drawing made by the user"},{"it":"Da un archivio di immagini già pronte","en":"From an archive of ready-made images"}]',1,'{"it":"Il rumore diventa immagine.","en":"Noise becomes an image."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'multimodal'),3,2,'{"it":"Trasformare un messaggio vocale in testo è…","en":"Turning a voice message into text is…"}','[{"it":"Sintesi vocale","en":"Speech synthesis"},{"it":"Generazione di immagini","en":"Image generation"},{"it":"Riconoscimento vocale","en":"Speech recognition"},{"it":"Diffusione","en":"Diffusion"}]',2,'{"it":"Dall’audio al testo.","en":"From audio to text."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'history'),1,2,'{"it":"Quando nasce il termine “intelligenza artificiale”?","en":"When was the term “artificial intelligence” coined?"}','[{"it":"Nel 2012, con AlexNet","en":"In 2012, with AlexNet"},{"it":"Nel 1997, con Deep Blue","en":"In 1997, with Deep Blue"},{"it":"Nel 2022, con ChatGPT","en":"In 2022, with ChatGPT"},{"it":"Nel 1956, a Dartmouth","en":"In 1956, at Dartmouth"}]',3,'{"it":"Un convegno estivo negli Stati Uniti.","en":"A summer workshop in the United States."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'history'),2,2,'{"it":"Che cosa sono gli “inverni dell’AI”?","en":"What are the “AI winters”?"}','[{"it":"Periodi di delusione e pochi fondi","en":"Periods of disappointment and little funding"},{"it":"Mesi in cui i server si raffreddano","en":"Months when servers cool down"},{"it":"Versioni dell’AI per i paesi freddi","en":"AI versions for cold countries"},{"it":"Pause estive dei laboratori di ricerca","en":"Summer breaks of research labs"}]',0,'{"it":"Le promesse non mantenute costano.","en":"Broken promises cost."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-base' AND slug = 'history'),3,2,'{"it":"Quali ingredienti hanno reso possibile la svolta recente?","en":"Which ingredients made the recent breakthrough possible?"}','[{"it":"Solo computer più veloci","en":"Only faster computers"},{"it":"Dati, calcolo e algoritmi migliori insieme","en":"Data, compute and better algorithms together"},{"it":"Solo leggi più favorevoli","en":"Only more favourable laws"},{"it":"Solo più programmatori nel mondo","en":"Only more programmers in the world"}]',1,'{"it":"Servono tutti e tre.","en":"All three are needed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'tokens'),1,1,'{"it":"Che cos’è un token?","en":"What is a token?"}','[{"it":"Un pezzo di testo preso da un vocabolario fisso","en":"A piece of text from a fixed vocabulary"},{"it":"Sempre una parola intera","en":"Always a whole word"},{"it":"Una singola lettera, sempre","en":"A single letter, always"},{"it":"Una frase completa","en":"A complete sentence"}]',0,'{"it":"Spesso pezzi di parola.","en":"Often word pieces."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'tokens'),2,1,'{"it":"Qual è il compito di base di un LLM?","en":"What is an LLM’s basic task?"}','[{"it":"Prevedere il token successivo","en":"Predicting the next token"},{"it":"Cercare la risposta su Google","en":"Searching Google for the answer"},{"it":"Copiare un testo dal database","en":"Copying text from a database"},{"it":"Tradurre solo in inglese","en":"Translating into English only"}]',0,'{"it":"Un token alla volta.","en":"One token at a time."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'tokens'),3,1,'{"it":"Come nasce una risposta lunga?","en":"How is a long answer produced?"}','[{"it":"Aggiungendo un token alla volta e ripetendo","en":"By adding one token at a time and repeating"},{"it":"Tutta in un colpo solo","en":"All in one go"},{"it":"Da un modello per ogni frase","en":"From one model per sentence"},{"it":"Leggendola da un file","en":"By reading it from a file"}]',0,'{"it":"Generazione autoregressiva.","en":"Autoregressive generation."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'transformer'),1,1,'{"it":"Che cos’è un embedding?","en":"What is an embedding?"}','[{"it":"Un vettore di numeri che rappresenta il significato","en":"A vector of numbers representing meaning"},{"it":"Un’immagine del token","en":"A picture of the token"},{"it":"Il nome del modello","en":"The model’s name"},{"it":"Un file di configurazione","en":"A configuration file"}]',0,'{"it":"Significati simili, vettori vicini.","en":"Similar meanings, nearby vectors."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'transformer'),2,1,'{"it":"Che cosa fa l’attenzione?","en":"What does attention do?"}','[{"it":"Pesa quanto ogni token guarda gli altri","en":"Weighs how much each token looks at others"},{"it":"Tiene sveglio il modello","en":"Keeps the model awake"},{"it":"Cancella i token inutili dal testo","en":"Deletes useless tokens from text"},{"it":"Conta le parole","en":"Counts words"}]',0,'{"it":"Collega le parti del contesto.","en":"Links parts of the context."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'transformer'),3,1,'{"it":"Che cosa sono i parametri di un modello?","en":"What are a model’s parameters?"}','[{"it":"I numeri appresi durante l’addestramento","en":"The numbers learned during training"},{"it":"Le domande degli utenti","en":"Users’ questions"},{"it":"Le opzioni del menu","en":"The menu options"},{"it":"I server che lo ospitano","en":"The servers hosting it"}]',0,'{"it":"Detti anche pesi.","en":"Also called weights."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'training'),1,1,'{"it":"Che cosa impara il modello nel pre-addestramento?","en":"What does the model learn in pre-training?"}','[{"it":"A prevedere il token successivo su enormi testi","en":"To predict the next token over huge texts"},{"it":"A rispondere solo in italiano","en":"To answer only in Italian"},{"it":"A navigare sul web","en":"To browse the web"},{"it":"A disegnare immagini","en":"To draw pictures"}]',0,'{"it":"La fase più costosa.","en":"The most expensive phase."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'training'),2,1,'{"it":"A che cosa serve l’RLHF?","en":"What is RLHF for?"}','[{"it":"Premiare risposte utili e sicure","en":"Rewarding helpful and safe answers"},{"it":"Rendere il modello più leggero","en":"Making the model lighter"},{"it":"Aggiungere nuove lingue","en":"Adding new languages"},{"it":"Aumentare i token","en":"Increasing tokens"}]',0,'{"it":"Il feedback guida il comportamento.","en":"Feedback guides behaviour."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'training'),3,1,'{"it":"Che cos’è la data di cutoff?","en":"What is the cutoff date?"}','[{"it":"Il limite temporale dei dati di addestramento","en":"The time limit of the training data"},{"it":"Il giorno di scadenza del modello","en":"The model’s expiry day"},{"it":"L’ora di chiusura dei server","en":"The servers’ closing time"},{"it":"La data di nascita dell’azienda","en":"The company’s founding date"}]',0,'{"it":"Dopo, il modello non sa.","en":"After it, the model does not know."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'limits'),1,1,'{"it":"Che cos’è la finestra di contesto?","en":"What is the context window?"}','[{"it":"Quanti token il modello vede in una volta","en":"How many tokens the model sees at once"},{"it":"La finestra del browser","en":"The browser window"},{"it":"Il tempo di risposta","en":"The response time"},{"it":"Il numero di utenti","en":"The number of users"}]',0,'{"it":"Istruzioni, chat e risposta insieme.","en":"Instructions, chat and answer together."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'limits'),2,1,'{"it":"Che effetto ha una temperatura bassa?","en":"What does a low temperature do?"}','[{"it":"Risposte più stabili e prevedibili","en":"More stable and predictable answers"},{"it":"Risposte più creative e varie","en":"More creative and varied answers"},{"it":"Risposte più lunghe","en":"Longer answers"},{"it":"Risposte in un’altra lingua","en":"Answers in another language"}]',0,'{"it":"Prende quasi sempre il più probabile.","en":"It almost always takes the most likely."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'limits'),3,1,'{"it":"Che cos’è un’allucinazione?","en":"What is a hallucination?"}','[{"it":"Una risposta sicura ma falsa","en":"A confident but false answer"},{"it":"Un errore di connessione","en":"A connection error"},{"it":"Una risposta troppo corta","en":"An answer that is too short"},{"it":"Un’immagine generata","en":"A generated image"}]',0,'{"it":"Testo plausibile, non verificato.","en":"Plausible, unchecked text."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'tools'),1,2,'{"it":"Che cosa aggiunge la RAG?","en":"What does RAG add?"}','[{"it":"Documenti cercati e messi nel contesto","en":"Documents retrieved and put into the context"},{"it":"Più parametri al modello","en":"More parameters to the model"},{"it":"Un nuovo addestramento","en":"A new training run"},{"it":"Una GPU in più","en":"One more GPU"}]',0,'{"it":"Il modello non cambia, cambia il contesto.","en":"The model does not change, the context does."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'tools'),2,2,'{"it":"Chi esegue davvero uno strumento nel tool use?","en":"Who actually runs a tool in tool use?"}','[{"it":"Il programma intorno al modello","en":"The program around the model"},{"it":"Il modello stesso","en":"The model itself"},{"it":"L’utente a mano, sempre","en":"The user by hand, always"},{"it":"Il browser","en":"The browser"}]',0,'{"it":"Il modello chiede, il programma esegue.","en":"The model asks, the program runs."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'tools'),3,2,'{"it":"Che cos’è la prompt injection?","en":"What is prompt injection?"}','[{"it":"Istruzioni malevole nascoste nei contenuti letti","en":"Malicious instructions hidden in content being read"},{"it":"Un prompt troppo lungo","en":"A prompt that is too long"},{"it":"Un errore di battitura","en":"A typo"},{"it":"Un tipo di token","en":"A type of token"}]',0,'{"it":"Il modello può scambiarle per ordini.","en":"The model may mistake them for orders."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'reasoning'),1,2,'{"it":"Che cosa fa un modello di ragionamento prima di rispondere?","en":"What does a reasoning model do before answering?"}','[{"it":"Cerca la risposta in un archivio di soluzioni","en":"It looks the answer up in an archive of solutions"},{"it":"Chiede conferma all’utente su ogni passaggio","en":"It asks the user to confirm every step"},{"it":"Genera un ragionamento interno passo dopo passo","en":"It generates internal step-by-step reasoning"},{"it":"Si collega a un altro modello più grande","en":"It connects to another, larger model"}]',2,'{"it":"Pensa prima di parlare.","en":"It thinks before speaking."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'reasoning'),2,2,'{"it":"Su quali problemi si addestra bene il ragionamento con il rinforzo?","en":"On which problems does reinforcement train reasoning well?"}','[{"it":"Problemi verificabili, come matematica e codice","en":"Verifiable problems, like maths and code"},{"it":"Testi creativi senza una risposta giusta","en":"Creative texts with no right answer"},{"it":"Conversazioni informali e saluti","en":"Casual conversations and greetings"},{"it":"Domande sulle notizie di oggi","en":"Questions about today’s news"}]',0,'{"it":"Una risposta giusta si controlla in automatico.","en":"A right answer can be checked automatically."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'reasoning'),3,2,'{"it":"Qual è il prezzo del ragionamento?","en":"What is the price of reasoning?"}','[{"it":"Risposte sempre più brevi e vaghe","en":"Answers that are always shorter and vaguer"},{"it":"Più token e più tempo di attesa","en":"More tokens and more waiting time"},{"it":"Un modello che dimentica la conversazione","en":"A model that forgets the conversation"},{"it":"Nessuno: è sempre gratis e immediato","en":"None: it is always free and instant"}]',1,'{"it":"Si regola con lo sforzo.","en":"You tune it with the effort."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'choose'),1,2,'{"it":"Per classificare grandi volumi di testi semplici conviene di solito…","en":"To classify large volumes of simple texts you usually want…"}','[{"it":"Il modello più grande disponibile","en":"The largest model available"},{"it":"Un modello con ragionamento al massimo","en":"A model with maximum reasoning"},{"it":"Un modello che genera immagini","en":"An image-generating model"},{"it":"Un modello piccolo, veloce ed economico","en":"A small, fast and cheap model"}]',3,'{"it":"Volume alto, compito facile.","en":"High volume, easy task."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'choose'),2,2,'{"it":"Che cosa distingue un modello open-weight?","en":"What sets an open-weight model apart?"}','[{"it":"I pesi si possono scaricare e usare in proprio","en":"The weights can be downloaded and run yourself"},{"it":"Funziona solo dentro il browser","en":"It only works inside the browser"},{"it":"Non ha bisogno di hardware per girare","en":"It needs no hardware to run"},{"it":"È sempre il più capace di tutti","en":"It is always the most capable of all"}]',0,'{"it":"Utile quando i dati devono restare in casa.","en":"Useful when data must stay in-house."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-base' AND slug = 'choose'),3,2,'{"it":"Qual è il modo più affidabile di scegliere tra due modelli?","en":"What is the most reliable way to choose between two models?"}','[{"it":"Guardare solo chi è primo in classifica","en":"Looking only at who tops the leaderboard"},{"it":"Provarli su un piccolo test con i tuoi esempi","en":"Trying them on a small test with your examples"},{"it":"Scegliere quello con il nome più recente","en":"Picking the one with the newest name"},{"it":"Prendere sempre il più costoso","en":"Always taking the most expensive one"}]',1,'{"it":"I benchmark misurano compiti generici.","en":"Benchmarks measure generic tasks."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'clear'),1,1,'{"it":"Che cosa rende migliore un prompt?","en":"What makes a prompt better?"}','[{"it":"Compito, pubblico e vincoli precisi","en":"Precise task, audience and constraints"},{"it":"Essere il più breve possibile","en":"Being as short as possible"},{"it":"Usare tante emoji","en":"Using lots of emoji"},{"it":"Scrivere tutto in maiuscolo","en":"Writing everything in capitals"}]',0,'{"it":"Il modello non indovina quello che non dici.","en":"The model cannot guess what you do not say."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'clear'),2,1,'{"it":"Qual è il prompt più specifico?","en":"Which prompt is the most specific?"}','[{"it":"Riassumi questo articolo in 5 punti per un manager","en":"Summarise this article in 5 bullet points for a manager"},{"it":"Parlami un po’ di questo articolo, se vuoi","en":"Tell me a bit about this article, if you like"},{"it":"Fai qualcosa di bello","en":"Do something nice"},{"it":"Articolo","en":"Article"}]',0,'{"it":"Compito, formato e pubblico.","en":"Task, format and audience."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'clear'),3,1,'{"it":"Meglio dire “non essere prolisso” o…","en":"Better to say “don’t be verbose” or…"}','[{"it":"“Rispondi in massimo 3 frasi”","en":"“Answer in at most 3 sentences”"},{"it":"“Niente”","en":"“Nothing”"},{"it":"“Sii come vuoi”","en":"“Be however you like”"},{"it":"“Scrivi tanto”","en":"“Write a lot”"}]',0,'{"it":"Dire cosa fare è più chiaro.","en":"Saying what to do is clearer."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'context'),1,1,'{"it":"Perché spiegare il motivo di un vincolo?","en":"Why explain the reason for a constraint?"}','[{"it":"Il modello lo applica in modo più sensato","en":"The model applies it more sensibly"},{"it":"Per allungare il prompt","en":"To make the prompt longer"},{"it":"È obbligatorio","en":"It is mandatory"},{"it":"Per confondere il modello","en":"To confuse the model"}]',0,'{"it":"Capisce lo scopo, non solo la regola.","en":"It grasps the goal, not just the rule."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'context'),2,1,'{"it":"A che cosa serve assegnare un ruolo?","en":"What is assigning a role for?"}','[{"it":"Orientare stile e livello","en":"Steering style and level"},{"it":"Dare accesso a internet","en":"Giving internet access"},{"it":"Rendere il modello più veloce","en":"Making the model faster"},{"it":"Cambiare lingua","en":"Changing language"}]',0,'{"it":"Un tutor parla diverso da un avvocato.","en":"A tutor speaks differently from a lawyer."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'context'),3,1,'{"it":"Come separi un documento lungo dalle istruzioni?","en":"How do you separate a long document from the instructions?"}','[{"it":"Con tag come `<documento>`","en":"With tags like `<document>`"},{"it":"Non si separa","en":"You do not"},{"it":"Con tante righe vuote","en":"With many blank lines"},{"it":"Scrivendo in rosso","en":"Writing in red"}]',0,'{"it":"Così il modello sa cosa è cosa.","en":"So the model knows what is what."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'examples'),1,1,'{"it":"Che cos’è un prompt few-shot?","en":"What is a few-shot prompt?"}','[{"it":"Un prompt con alcuni esempi","en":"A prompt with a few examples"},{"it":"Un prompt molto breve","en":"A very short prompt"},{"it":"Un prompt senza istruzioni","en":"A prompt with no instructions"},{"it":"Un prompt in più lingue","en":"A prompt in several languages"}]',0,'{"it":"Zero, uno o pochi esempi.","en":"Zero, one or a few examples."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'examples'),2,1,'{"it":"Perché gli esempi devono essere vari?","en":"Why must examples be varied?"}','[{"it":"Per non far copiare dettagli indesiderati","en":"So unwanted details are not copied"},{"it":"Per allungare la risposta","en":"To lengthen the answer"},{"it":"Perché il modello si annoia","en":"Because the model gets bored"},{"it":"Non serve","en":"It does not matter"}]',0,'{"it":"Il modello imita tutto quello che vede.","en":"The model imitates everything it sees."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'examples'),3,1,'{"it":"Un prompt senza esempi è…","en":"A prompt with no examples is…"}','[{"it":"zero-shot","en":"zero-shot"},{"it":"one-shot","en":"one-shot"},{"it":"few-shot","en":"few-shot"},{"it":"multi-shot","en":"multi-shot"}]',0,'{"it":"Solo istruzioni.","en":"Only instructions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'format'),1,1,'{"it":"Quale formato è più comodo da leggere con il codice?","en":"Which format is easiest to read with code?"}','[{"it":"JSON","en":"JSON"},{"it":"Un tema libero","en":"A free essay"},{"it":"Una poesia","en":"A poem"},{"it":"Un elenco disordinato","en":"A messy list"}]',0,'{"it":"Ha una struttura precisa.","en":"It has a precise structure."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'format'),2,1,'{"it":"Perché descrivere i campi del JSON?","en":"Why describe the JSON fields?"}','[{"it":"Così il modello usa nomi e tipi giusti","en":"So the model uses the right names and types"},{"it":"Per abbellire il prompt e renderlo più lungo","en":"To decorate the prompt and make it longer"},{"it":"Non serve mai","en":"It is never needed"},{"it":"Per renderlo più lento","en":"To make it slower"}]',0,'{"it":"Il programma si aspetta quei campi.","en":"The program expects those fields."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'format'),3,1,'{"it":"Quando aiuta “ragiona passo per passo”?","en":"When does “reason step by step” help?"}','[{"it":"Nei problemi con più passaggi","en":"In multi-step problems"},{"it":"Per salutare","en":"For greetings"},{"it":"Mai","en":"Never"},{"it":"Solo con le immagini","en":"Only with images"}]',0,'{"it":"Spezza il problema.","en":"It breaks the problem down."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'iterate'),1,2,'{"it":"Come si migliora un prompt?","en":"How do you improve a prompt?"}','[{"it":"Provando e correggendo una cosa alla volta","en":"Trying and fixing one thing at a time"},{"it":"Cambiando tutto ogni volta","en":"Changing everything each time"},{"it":"Ripetendo la stessa richiesta","en":"Repeating the same request"},{"it":"Scrivendo più forte","en":"Writing louder"}]',0,'{"it":"Così capisci cosa ha funzionato.","en":"That way you know what worked."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'iterate'),2,2,'{"it":"Come affronti un compito molto grande?","en":"How do you tackle a very large task?"}','[{"it":"Lo spezzi in passaggi","en":"Split it into steps"},{"it":"Lo chiedi tutto in una riga","en":"Ask for it all in one line"},{"it":"Lasci perdere","en":"Give up"},{"it":"Lo chiedi in un’altra lingua","en":"Ask in another language"}]',0,'{"it":"Scaletta, sezioni, revisione.","en":"Outline, sections, review."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'iterate'),3,2,'{"it":"Che cosa conviene fare con un prompt che funziona?","en":"What should you do with a prompt that works?"}','[{"it":"Salvarlo come modello","en":"Save it as a template"},{"it":"Cancellarlo","en":"Delete it"},{"it":"Non usarlo più","en":"Never use it again"},{"it":"Renderlo più vago","en":"Make it vaguer"}]',0,'{"it":"Riusarlo fa risparmiare tempo.","en":"Reusing it saves time."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'recipes'),1,2,'{"it":"Che cosa conviene dire in un prompt di riassunto?","en":"What should a summary prompt say?"}','[{"it":"Solo “riassumi”, il resto lo decide il modello","en":"Just “summarise”, the model decides the rest"},{"it":"Che il riassunto deve essere il più lungo possibile","en":"That the summary must be as long as possible"},{"it":"Per chi è e che cosa non va perso","en":"Who it is for and what must not be lost"},{"it":"Di inventare dettagli che mancano","en":"To invent missing details"}]',2,'{"it":"Pubblico e informazioni chiave.","en":"Audience and key information."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'recipes'),2,2,'{"it":"Perché chiedere molte idee invece di una sola?","en":"Why ask for many ideas rather than one?"}','[{"it":"Le prime idee sono spesso le più banali","en":"The first ideas are often the most obvious"},{"it":"Il modello costa meno con elenchi lunghi","en":"The model costs less with long lists"},{"it":"Perché una sola idea è vietata","en":"Because a single idea is forbidden"},{"it":"Così il modello ricorda la conversazione","en":"So the model remembers the conversation"}]',0,'{"it":"Scegli tu tra molte.","en":"You choose among many."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'recipes'),3,2,'{"it":"Quale prompt di estrazione è migliore?","en":"Which extraction prompt is better?"}','[{"it":"“Dimmi cosa c’è di importante nel contratto”","en":"“Tell me what matters in the contract”"},{"it":"“Elenca le scadenze in una tabella: data | obbligo”","en":"“List the deadlines in a table: date | duty”"},{"it":"“Leggi il contratto e fammi sapere”","en":"“Read the contract and let me know”"},{"it":"“Contratto: scadenze?”","en":"“Contract: deadlines?”"}]',1,'{"it":"Che cosa estrarre e in che formato.","en":"What to extract and in what format."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'verify'),1,2,'{"it":"Quando conviene chiedere al modello di farti domande prima?","en":"When should you ask the model to question you first?"}','[{"it":"Quando il compito è banale e già chiaro","en":"When the task is trivial and already clear"},{"it":"Quando vuoi una risposta più lunga","en":"When you want a longer answer"},{"it":"Mai, perché fa perdere tempo","en":"Never, because it wastes time"},{"it":"Quando mancano informazioni importanti","en":"When important information is missing"}]',3,'{"it":"Meglio chiedere che inventare.","en":"Better to ask than to invent."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'verify'),2,2,'{"it":"Perché “perché questo codice è sicuro?” è una cattiva domanda?","en":"Why is “why is this code secure?” a bad question?"}','[{"it":"Spinge il modello a difendere il codice","en":"It pushes the model to defend the code"},{"it":"È troppo breve per essere capita","en":"It is too short to be understood"},{"it":"I modelli non leggono il codice","en":"Models do not read code"},{"it":"Contiene una parola vietata","en":"It contains a forbidden word"}]',0,'{"it":"Suggerisce già la risposta.","en":"It already suggests the answer."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-base' AND slug = 'verify'),3,2,'{"it":"Quale richiesta aiuta a scoprire errori nella risposta?","en":"Which request helps uncover mistakes in the answer?"}','[{"it":"“Rispondi con sicurezza, senza dubbi”","en":"“Answer confidently, without doubts”"},{"it":"“Elenca i punti in cui non sei sicuro”","en":"“List the points you are unsure about”"},{"it":"“Scrivi la risposta il più in fretta possibile”","en":"“Write the answer as fast as possible”"},{"it":"“Non ammettere mai di non sapere”","en":"“Never admit you do not know”"}]',1,'{"it":"L’incertezza dichiarata si può controllare.","en":"Declared uncertainty can be checked."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'bias'),1,1,'{"it":"Da dove nasce più spesso un bias?","en":"Where does bias most often come from?"}','[{"it":"Dai dati di addestramento","en":"From the training data"},{"it":"Dal colore del logo","en":"From the logo colour"},{"it":"Dalla velocità del server","en":"From server speed"},{"it":"Dal numero di utenti","en":"From the number of users"}]',0,'{"it":"Il modello riflette i dati.","en":"The model mirrors the data."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'bias'),2,1,'{"it":"Perché misurare gli errori per gruppo?","en":"Why measure errors per group?"}','[{"it":"Una buona media può nascondere un gruppo svantaggiato","en":"A good average can hide a disadvantaged group"},{"it":"Per fare più grafici e presentazioni","en":"To make more charts and presentations"},{"it":"È più veloce","en":"It is faster"},{"it":"Non serve","en":"It is not needed"}]',0,'{"it":"L’equità si vede nei dettagli.","en":"Fairness shows in the details."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'bias'),3,1,'{"it":"Che cos’è una variabile “proxy”?","en":"What is a “proxy” variable?"}','[{"it":"Una che rivela indirettamente un dato sensibile","en":"One that indirectly reveals a sensitive attribute"},{"it":"Un server intermedio tra utente e modello","en":"An intermediate server between user and model"},{"it":"Una password","en":"A password"},{"it":"Un tipo di grafico","en":"A type of chart"}]',0,'{"it":"Per esempio il CAP.","en":"For example the postcode."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'privacy'),1,1,'{"it":"Che cosa non andrebbe incollato in un chatbot pubblico?","en":"What should not be pasted into a public chatbot?"}','[{"it":"La password di un collega","en":"A colleague’s password"},{"it":"Una ricetta della nonna","en":"Grandma’s recipe"},{"it":"Una poesia di Leopardi","en":"A Leopardi poem"},{"it":"Un esercizio di matematica","en":"A maths exercise"}]',0,'{"it":"Segreti e dati altrui restano fuori.","en":"Secrets and others’ data stay out."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'privacy'),2,1,'{"it":"Che cosa significa anonimizzare?","en":"What does anonymising mean?"}','[{"it":"Togliere ciò che identifica le persone","en":"Removing what identifies people"},{"it":"Cifrare il computer","en":"Encrypting the computer"},{"it":"Cambiare nome utente","en":"Changing username"},{"it":"Usare la modalità scura","en":"Using dark mode"}]',0,'{"it":"Nomi, email, numeri, indirizzi.","en":"Names, emails, numbers, addresses."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'privacy'),3,1,'{"it":"Quale principio chiede il GDPR?","en":"Which principle does the GDPR require?"}','[{"it":"Usare il minimo di dati necessario","en":"Using the minimum data necessary"},{"it":"Raccogliere più dati possibile","en":"Collecting as much data as possible"},{"it":"Pubblicare i dati","en":"Publishing the data"},{"it":"Nessuna regola","en":"No rules"}]',0,'{"it":"Minimizzazione dei dati.","en":"Data minimisation."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'copyright'),1,1,'{"it":"In molti paesi, quando un’opera generata è protetta?","en":"In many countries, when is a generated work protected?"}','[{"it":"Se c’è un contributo creativo umano","en":"When there is human creative contribution"},{"it":"Sempre","en":"Always"},{"it":"Mai, in nessun caso","en":"Never, in any case"},{"it":"Solo se il testo supera una certa lunghezza","en":"Only if the text exceeds a certain length"}]',0,'{"it":"E le regole cambiano ancora.","en":"And the rules are still changing."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'copyright'),2,1,'{"it":"Che cosa controllare nel codice generato?","en":"What should you check in generated code?"}','[{"it":"Che non copi codice con licenze incompatibili","en":"That it does not copy code with incompatible licences"},{"it":"Che abbia tanti commenti e sia ben formattato","en":"That it has many comments and good formatting"},{"it":"Che sia colorato","en":"That it is colourful"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Le licenze contano anche per l’AI.","en":"Licences matter for AI too."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'copyright'),3,1,'{"it":"Quando dichiarare l’uso dell’AI?","en":"When should you disclose AI use?"}','[{"it":"Quando è richiesto da scuola, editore o regolamento","en":"When school, publisher or rules require it"},{"it":"Mai","en":"Never"},{"it":"Solo il lunedì","en":"Only on Mondays"},{"it":"Solo quando si generano immagini, mai per i testi","en":"Only when generating images, never for text"}]',0,'{"it":"La trasparenza evita problemi.","en":"Transparency avoids trouble."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'ai-act'),1,1,'{"it":"Su che cosa si basa l’AI Act?","en":"What is the AI Act based on?"}','[{"it":"Livelli di rischio","en":"Risk levels"},{"it":"La dimensione dell’azienda","en":"Company size"},{"it":"Il prezzo del servizio","en":"The service price"},{"it":"Il linguaggio di programmazione","en":"The programming language"}]',0,'{"it":"Più rischio, più obblighi.","en":"More risk, more duties."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'ai-act'),2,1,'{"it":"Il punteggio sociale dei cittadini è…","en":"Social scoring of citizens is…"}','[{"it":"Vietato","en":"Banned"},{"it":"Rischio minimo","en":"Minimal risk"},{"it":"Senza obblighi","en":"Without duties"},{"it":"Consigliato","en":"Recommended"}]',0,'{"it":"Rischio inaccettabile.","en":"Unacceptable risk."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'ai-act'),3,1,'{"it":"Quale obbligo principale ha un chatbot?","en":"What is a chatbot’s main duty?"}','[{"it":"Dire che è una macchina","en":"Saying it is a machine"},{"it":"Essere gratuito","en":"Being free"},{"it":"Rispondere in latino","en":"Answering in Latin"},{"it":"Nessuno","en":"None"}]',0,'{"it":"Trasparenza.","en":"Transparency."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'habits'),1,2,'{"it":"Chi è responsabile di un testo pubblicato scritto con l’AI?","en":"Who is responsible for a published text written with AI?"}','[{"it":"Chi lo pubblica","en":"Whoever publishes it"},{"it":"Il modello","en":"The model"},{"it":"Nessuno","en":"Nobody"},{"it":"Il fornitore di internet","en":"The internet provider"}]',0,'{"it":"Lo strumento non firma.","en":"The tool does not sign."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'habits'),2,2,'{"it":"Ricevi un vocale urgente di un parente che chiede soldi: che fai?","en":"You get an urgent voice message from a relative asking for money: what do you do?"}','[{"it":"Verifico chiamandolo su un altro canale","en":"Verify by calling them on another channel"},{"it":"Pago subito","en":"Pay at once"},{"it":"Inoltro a tutti","en":"Forward it to everyone"},{"it":"Rispondo con i dati della carta","en":"Reply with card details"}]',0,'{"it":"Le voci si possono clonare.","en":"Voices can be cloned."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'habits'),3,2,'{"it":"Che cos’è un deepfake?","en":"What is a deepfake?"}','[{"it":"Un contenuto falso realistico generato con l’AI","en":"A realistic fake made with AI"},{"it":"Un tipo di database","en":"A kind of database"},{"it":"Un antivirus","en":"An antivirus"},{"it":"Un errore di stampa","en":"A typo"}]',0,'{"it":"Immagini, voci, video.","en":"Images, voices, videos."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'labels'),1,2,'{"it":"Che cosa sono le credenziali di contenuto (C2PA)?","en":"What are content credentials (C2PA)?"}','[{"it":"Una password per scaricare le immagini","en":"A password to download images"},{"it":"Un filtro che rende le foto più nitide","en":"A filter that sharpens photos"},{"it":"Metadati firmati sull’origine e le modifiche di un file","en":"Signed metadata on a file’s origin and edits"},{"it":"Un archivio pubblico di tutti i deepfake","en":"A public archive of all deepfakes"}]',2,'{"it":"Raccontano la storia del file.","en":"They tell the file’s story."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'labels'),2,2,'{"it":"Una filigrana invisibile garantisce sempre di riconoscere un contenuto generato?","en":"Does an invisible watermark always guarantee spotting generated content?"}','[{"it":"Sì, non si può mai togliere né rovinare","en":"Yes, it can never be removed or damaged"},{"it":"No, a volte si rovina o manca del tutto","en":"No, it is sometimes damaged or missing"},{"it":"Sì, ma solo per i testi","en":"Yes, but only for text"},{"it":"Sì, se l’immagine è a colori","en":"Yes, if the image is in colour"}]',1,'{"it":"Aiuta, non basta.","en":"It helps, it is not enough."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'labels'),3,2,'{"it":"Che cosa chiede l’AI Act a chi pubblica un deepfake?","en":"What does the AI Act ask of whoever publishes a deepfake?"}','[{"it":"Di dichiarare che è artificiale","en":"To disclose that it is artificial"},{"it":"Di pagare una tassa per ogni immagine","en":"To pay a tax for each image"},{"it":"Di pubblicarlo solo di notte","en":"To publish it only at night"},{"it":"Niente, i deepfake sono liberi","en":"Nothing, deepfakes are unrestricted"}]',0,'{"it":"Trasparenza verso chi guarda.","en":"Transparency towards viewers."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'decisions'),1,2,'{"it":"Che diritto dà il GDPR davanti a una decisione solo automatica e importante?","en":"What right does the GDPR give against an important, solely automated decision?"}','[{"it":"Il diritto a un rimborso automatico","en":"The right to an automatic refund"},{"it":"Nessuno: l’algoritmo ha sempre ragione","en":"None: the algorithm is always right"},{"it":"Il diritto di cancellare l’algoritmo","en":"The right to delete the algorithm"},{"it":"Ottenere un intervento umano e contestarla","en":"Obtaining human intervention and contesting it"}]',3,'{"it":"Salvo alcune eccezioni previste.","en":"Save for some set exceptions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'decisions'),2,2,'{"it":"Quando la supervisione umana è solo di facciata?","en":"When is human oversight only for show?"}','[{"it":"Quando l’operatore approva tutto senza guardare","en":"When the operator approves everything without looking"},{"it":"Quando l’operatore può cambiare la decisione","en":"When the operator can change the decision"},{"it":"Quando l’operatore ha le informazioni necessarie","en":"When the operator has the information needed"},{"it":"Quando l’operatore ha il tempo di valutare","en":"When the operator has time to assess"}]',0,'{"it":"Serve potere vero di cambiare l’esito.","en":"Real power to change the outcome is needed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'decisions'),3,2,'{"it":"Che cos’è la spiegabilità?","en":"What is explainability?"}','[{"it":"Pubblicare tutto il codice sorgente del modello","en":"Publishing all the model’s source code"},{"it":"Dire in parole chiare perché il sistema ha deciso così","en":"Saying in plain words why the system decided that way"},{"it":"Rendere il modello più veloce a rispondere","en":"Making the model answer faster"},{"it":"Tradurre la decisione in più lingue","en":"Translating the decision into several languages"}]',1,'{"it":"Comprensibile per chi la riceve.","en":"Understandable to whoever receives it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'impact'),1,2,'{"it":"Perché i data center consumano acqua?","en":"Why do data centres use water?"}','[{"it":"Per lavare i dischi rigidi ogni giorno","en":"To wash the hard disks every day"},{"it":"Per produrre l’elettricità sul posto","en":"To generate electricity on site"},{"it":"Per raffreddare i server","en":"To cool the servers"},{"it":"Per stampare i risultati dei modelli","en":"To print the models’ results"}]',2,'{"it":"Il calcolo produce calore.","en":"Computing produces heat."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'impact'),2,2,'{"it":"Che cosa cambia di più l’AI nel lavoro, secondo l’esperienza finora?","en":"What does AI change most at work, judging by experience so far?"}','[{"it":"Singoli compiti più che mestieri interi","en":"Single tasks more than whole jobs"},{"it":"Nulla, perché nessuno la usa","en":"Nothing, because nobody uses it"},{"it":"Solo il lavoro dei programmatori","en":"Only programmers’ work"},{"it":"Sostituisce subito tutti i mestieri","en":"It replaces every job at once"}]',0,'{"it":"Bozze, ricerche, lavori ripetitivi.","en":"Drafts, research, repetitive work."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-ethics' AND slug = 'impact'),3,2,'{"it":"Quale scelta riduce l’impatto ambientale dell’uso dell’AI?","en":"Which choice reduces the environmental impact of using AI?"}','[{"it":"Generare dieci versioni di ogni testo","en":"Generating ten versions of every text"},{"it":"Usare un modello piccolo quando basta","en":"Using a small model when it is enough"},{"it":"Usare sempre il modello più grande","en":"Always using the largest model"},{"it":"Ripetere la stessa domanda più volte","en":"Repeating the same question several times"}]',1,'{"it":"Lo strumento giusto, senza sprechi.","en":"The right tool, without waste."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'vectors'),1,1,'{"it":"Che cos’è un vettore in ML?","en":"What is a vector in ML?"}','[{"it":"Un elenco di numeri che descrive qualcosa","en":"A list of numbers describing something"},{"it":"Una freccia disegnata sullo schermo","en":"An arrow drawn on the screen"},{"it":"Un file di testo","en":"A text file"},{"it":"Un tipo di grafico","en":"A type of chart"}]',0,'{"it":"Le caratteristiche diventano numeri.","en":"Features become numbers."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'vectors'),2,1,'{"it":"Che cosa calcola `np.dot(a, b)`?","en":"What does `np.dot(a, b)` compute?"}','[{"it":"La somma dei prodotti elemento per elemento","en":"The sum of element-wise products"},{"it":"La media degli elementi dei due vettori","en":"The mean of the two vectors’ elements"},{"it":"Il massimo","en":"The maximum"},{"it":"La lunghezza dell’array","en":"The array length"}]',0,'{"it":"Il prodotto scalare.","en":"The dot product."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'vectors'),3,1,'{"it":"Che cos’è un embedding?","en":"What is an embedding?"}','[{"it":"Un vettore che rappresenta una parola o un testo","en":"A vector representing a word or text"},{"it":"Un video incorporato in una pagina web","en":"A video embedded in a web page"},{"it":"Un file compresso","en":"A compressed file"},{"it":"Un tipo di font","en":"A kind of font"}]',0,'{"it":"Significati simili, vettori vicini.","en":"Similar meanings, nearby vectors."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'similarity'),1,1,'{"it":"Una similarità del coseno vicina a 1 significa…","en":"A cosine similarity close to 1 means…"}','[{"it":"Vettori molto simili","en":"Very similar vectors"},{"it":"Vettori opposti","en":"Opposite vectors"},{"it":"Errore","en":"Error"},{"it":"Vettori vuoti","en":"Empty vectors"}]',0,'{"it":"Stessa direzione.","en":"Same direction."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'similarity'),2,1,'{"it":"Che cosa calcola `np.linalg.norm(v)`?","en":"What does `np.linalg.norm(v)` compute?"}','[{"it":"La lunghezza del vettore","en":"The vector’s length"},{"it":"La somma","en":"The sum"},{"it":"Il numero di elementi","en":"The number of elements"},{"it":"Il valore minimo","en":"The minimum value"}]',0,'{"it":"Serve a normalizzare.","en":"It is used to normalise."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'similarity'),3,1,'{"it":"A che cosa serve la similarità nella ricerca semantica?","en":"What is similarity for in semantic search?"}','[{"it":"Trovare i testi più vicini alla domanda","en":"Finding the texts closest to the question"},{"it":"Ordinare i documenti per data di creazione","en":"Sorting documents by creation date"},{"it":"Comprimere i file","en":"Compressing files"},{"it":"Contare le parole","en":"Counting words"}]',0,'{"it":"Vicino nel significato, non nelle parole.","en":"Close in meaning, not in words."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'matrices'),1,1,'{"it":"Che cosa restituisce `X.shape` per 3 righe e 2 colonne?","en":"What does `X.shape` return for 3 rows and 2 columns?"}','[{"it":"(3, 2)","en":"(3, 2)"},{"it":"(2, 3)","en":"(2, 3)"},{"it":"6","en":"6"},{"it":"[3, 2, 1]","en":"[3, 2, 1]"}]',0,'{"it":"Prima le righe, poi le colonne.","en":"Rows first, then columns."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'matrices'),2,1,'{"it":"Che cosa fa l’operatore `@` in NumPy?","en":"What does the `@` operator do in NumPy?"}','[{"it":"Il prodotto tra matrici","en":"Matrix multiplication"},{"it":"Un commento","en":"A comment"},{"it":"Una email","en":"An email"},{"it":"La divisione","en":"Division"}]',0,'{"it":"Righe per colonne.","en":"Rows times columns."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'matrices'),3,1,'{"it":"In un dataset, che cosa è di solito una riga?","en":"In a dataset, what is a row usually?"}','[{"it":"Un esempio","en":"One example"},{"it":"Una caratteristica","en":"One feature"},{"it":"Un modello","en":"A model"},{"it":"Un errore","en":"An error"}]',0,'{"it":"Le colonne sono le caratteristiche.","en":"Columns are the features."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'probability'),1,1,'{"it":"Quanto fanno le probabilità di tutte le opzioni?","en":"What do the probabilities of all options add up to?"}','[{"it":"1","en":"1"},{"it":"100","en":"100"},{"it":"0","en":"0"},{"it":"Dipende","en":"It depends"}]',0,'{"it":"O 100%.","en":"Or 100%."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'probability'),2,1,'{"it":"Che cosa fa la softmax?","en":"What does softmax do?"}','[{"it":"Trasforma punteggi in probabilità","en":"Turns scores into probabilities"},{"it":"Ordina un elenco","en":"Sorts a list"},{"it":"Cancella i negativi","en":"Deletes negatives"},{"it":"Arrotonda i numeri","en":"Rounds numbers"}]',0,'{"it":"Positivi e con somma 1.","en":"Positive and summing to 1."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'probability'),3,1,'{"it":"Una temperatura bassa rende un LLM…","en":"A low temperature makes an LLM…"}','[{"it":"Più prevedibile","en":"More predictable"},{"it":"Più creativo","en":"More creative"},{"it":"Più lento","en":"Slower"},{"it":"Multilingue","en":"Multilingual"}]',0,'{"it":"Sceglie quasi sempre il token più probabile.","en":"It almost always picks the most likely token."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'gradient'),1,2,'{"it":"Che cosa vuole ridurre l’addestramento?","en":"What does training try to reduce?"}','[{"it":"L’errore (loss)","en":"The error (loss)"},{"it":"Il numero di dati","en":"The amount of data"},{"it":"La velocità","en":"The speed"},{"it":"I parametri a zero","en":"Parameters to zero"}]',0,'{"it":"Meno errore, modello migliore.","en":"Less error, better model."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'gradient'),2,2,'{"it":"Che cosa succede con un learning rate troppo grande?","en":"What happens with a learning rate that is too big?"}','[{"it":"Si salta oltre il minimo","en":"You overshoot the minimum"},{"it":"L’addestramento è perfetto","en":"Training is perfect"},{"it":"Il modello si spegne","en":"The model shuts down"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Passi troppo lunghi.","en":"Steps too long."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'gradient'),3,2,'{"it":"Che cosa calcola la backpropagation?","en":"What does backpropagation compute?"}','[{"it":"Le derivate di tutti i parametri","en":"The derivatives of all parameters"},{"it":"Le probabilità finali","en":"The final probabilities"},{"it":"Il numero di strati","en":"The number of layers"},{"it":"La dimensione del dataset","en":"The dataset size"}]',0,'{"it":"Così si sa come aggiornare ogni peso.","en":"So you know how to update each weight."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'statistics'),1,2,'{"it":"Che cosa misura la deviazione standard?","en":"What does the standard deviation measure?"}','[{"it":"Il valore più frequente","en":"The most frequent value"},{"it":"Il numero di elementi","en":"The number of elements"},{"it":"La differenza tra massimo e minimo","en":"The gap between maximum and minimum"},{"it":"Quanto i valori si allontanano dalla media","en":"How far values spread from the mean"}]',3,'{"it":"È la radice della varianza.","en":"It is the square root of the variance."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'statistics'),2,2,'{"it":"Dopo la standardizzazione, una colonna ha…","en":"After standardisation, a column has…"}','[{"it":"Media 0 e deviazione standard 1","en":"Mean 0 and standard deviation 1"},{"it":"Tutti i valori tra 0 e 100","en":"All values between 0 and 100"},{"it":"Solo valori interi positivi","en":"Only positive whole values"},{"it":"Gli stessi valori di prima","en":"The same values as before"}]',0,'{"it":"(x − media) / deviazione.","en":"(x − mean) / deviation."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'statistics'),3,2,'{"it":"Quale misura resiste meglio a un valore anomalo enorme?","en":"Which measure resists a huge outlier better?"}','[{"it":"La media","en":"The mean"},{"it":"La mediana","en":"The median"},{"it":"La somma","en":"The sum"},{"it":"Il massimo","en":"The maximum"}]',1,'{"it":"Guarda il valore centrale, non la somma.","en":"It looks at the middle value, not the sum."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'logs'),1,2,'{"it":"Quanto vale il logaritmo naturale di 1?","en":"What is the natural log of 1?"}','[{"it":"1","en":"1"},{"it":"e","en":"e"},{"it":"0","en":"0"},{"it":"-1","en":"-1"}]',2,'{"it":"e⁰ = 1.","en":"e⁰ = 1."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'logs'),2,2,'{"it":"Se il modello dà probabilità 0,1 alla risposta giusta, l’entropia incrociata è…","en":"If the model gives probability 0.1 to the right answer, the cross-entropy is…"}','[{"it":"Grande: era sicuro e sbagliava","en":"Large: it was confident and wrong"},{"it":"Zero: la risposta è comunque presente","en":"Zero: the answer is still there"},{"it":"Negativa, cioè un premio","en":"Negative, meaning a reward"},{"it":"Uguale a quella con probabilità 0,9","en":"Equal to the one with probability 0.9"}]',0,'{"it":"−log(0,1) ≈ 2,3.","en":"−log(0.1) ≈ 2.3."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-math' AND slug = 'logs'),3,2,'{"it":"Dove si usa l’entropia incrociata?","en":"Where is cross-entropy used?"}','[{"it":"Solo per ordinare gli elenchi","en":"Only for sorting lists"},{"it":"Come loss per classificazione e LLM","en":"As the loss for classification and LLMs"},{"it":"Per comprimere le immagini","en":"For compressing images"},{"it":"Per misurare la velocità della GPU","en":"For measuring GPU speed"}]',1,'{"it":"In PyTorch è `CrossEntropyLoss`.","en":"In PyTorch it is `CrossEntropyLoss`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'supervised'),1,2,'{"it":"Prevedere il prezzo di una casa è…","en":"Predicting a house price is…"}','[{"it":"Regressione","en":"Regression"},{"it":"Classificazione","en":"Classification"},{"it":"Clustering","en":"Clustering"},{"it":"Compressione","en":"Compression"}]',0,'{"it":"L’etichetta è un numero.","en":"The label is a number."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'supervised'),2,2,'{"it":"Che cosa contiene `y`?","en":"What does `y` contain?"}','[{"it":"L’etichetta, la risposta giusta","en":"The label, the right answer"},{"it":"Le caratteristiche","en":"The features"},{"it":"Il modello","en":"The model"},{"it":"Gli errori","en":"The errors"}]',0,'{"it":"`X` sono gli input.","en":"`X` are the inputs."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'supervised'),3,2,'{"it":"Raggruppare clienti senza etichette è…","en":"Grouping customers without labels is…"}','[{"it":"Non supervisionato","en":"Unsupervised"},{"it":"Supervisionato","en":"Supervised"},{"it":"Regressione","en":"Regression"},{"it":"Inferenza","en":"Inference"}]',0,'{"it":"Nessuna risposta giusta data.","en":"No right answer given."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'split'),1,2,'{"it":"Perché si separa un test set?","en":"Why separate a test set?"}','[{"it":"Per valutare su dati mai visti","en":"To evaluate on unseen data"},{"it":"Per addestrare due volte","en":"To train twice"},{"it":"Per risparmiare memoria","en":"To save memory"},{"it":"Per ordinare i dati","en":"To sort the data"}]',0,'{"it":"Il voto deve essere onesto.","en":"The score must be honest."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'split'),2,2,'{"it":"Che cosa fa `test_size=0.2`?","en":"What does `test_size=0.2` do?"}','[{"it":"Tiene il 20% per il test","en":"Keeps 20% for testing"},{"it":"Usa 2 esempi","en":"Uses 2 examples"},{"it":"Addestra al 20%","en":"Trains at 20%"},{"it":"Arrotonda i dati","en":"Rounds the data"}]',0,'{"it":"Il resto va all’addestramento.","en":"The rest goes to training."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'split'),3,2,'{"it":"A che cosa serve `random_state`?","en":"What is `random_state` for?"}','[{"it":"Rendere ripetibile la divisione","en":"Making the split repeatable"},{"it":"Mescolare le colonne","en":"Shuffling columns"},{"it":"Cambiare modello","en":"Changing model"},{"it":"Velocizzare","en":"Speeding up"}]',0,'{"it":"Stesso seme, stessa divisione.","en":"Same seed, same split."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'regression'),1,2,'{"it":"Quale metodo addestra un modello scikit-learn?","en":"Which method trains a scikit-learn model?"}','[{"it":"fit","en":"fit"},{"it":"predict","en":"predict"},{"it":"train","en":"train"},{"it":"learn","en":"learn"}]',0,'{"it":"`predict` lo usa dopo.","en":"`predict` uses it afterwards."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'regression'),2,2,'{"it":"Che cosa misura il MAE?","en":"What does MAE measure?"}','[{"it":"L’errore medio nella stessa unità di y","en":"The average error in y’s unit"},{"it":"La percentuale di risposte giuste","en":"The percentage of right answers"},{"it":"Il tempo di addestramento","en":"Training time"},{"it":"Il numero di caratteristiche","en":"The number of features"}]',0,'{"it":"Mean absolute error.","en":"Mean absolute error."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'regression'),3,2,'{"it":"Dove si leggono i pesi di una regressione lineare?","en":"Where do you read a linear regression’s weights?"}','[{"it":"coef_","en":"coef_"},{"it":"weights()","en":"weights()"},{"it":"params","en":"params"},{"it":"score_","en":"score_"}]',0,'{"it":"Uno per caratteristica.","en":"One per feature."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'classification'),1,2,'{"it":"Che cosa restituisce `predict_proba`?","en":"What does `predict_proba` return?"}','[{"it":"Le probabilità di ogni classe","en":"Each class’s probabilities"},{"it":"Solo la classe","en":"Only the class"},{"it":"L’errore","en":"The error"},{"it":"I pesi","en":"The weights"}]',0,'{"it":"Utile per scegliere una soglia.","en":"Handy for choosing a threshold."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'classification'),2,2,'{"it":"Perché un albero di decisione è facile da spiegare?","en":"Why is a decision tree easy to explain?"}','[{"it":"È una serie di domande sì/no","en":"It is a series of yes/no questions"},{"it":"Non usa dati","en":"It uses no data"},{"it":"È sempre perfetto","en":"It is always perfect"},{"it":"È una rete neurale","en":"It is a neural network"}]',0,'{"it":"Si può disegnare.","en":"You can draw it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'classification'),3,2,'{"it":"Che cosa limita `max_depth`?","en":"What does `max_depth` limit?"}','[{"it":"La profondità dell’albero","en":"The tree’s depth"},{"it":"Il numero di dati","en":"The amount of data"},{"it":"Il tempo","en":"Time"},{"it":"Le classi","en":"The classes"}]',0,'{"it":"Meno domande, meno memorizzazione.","en":"Fewer questions, less memorising."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'metrics'),1,3,'{"it":"Perché l’accuratezza può ingannare?","en":"Why can accuracy mislead?"}','[{"it":"Con classi sbilanciate premia chi dice sempre la classe comune","en":"With unbalanced classes it rewards always saying the common class"},{"it":"È sempre sbagliata","en":"It is always wrong"},{"it":"Funziona solo con le immagini e mai con i testi","en":"It only works with images and never with text"},{"it":"Non si può calcolare","en":"It cannot be computed"}]',0,'{"it":"Il 99% può essere inutile.","en":"99% can be useless."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'metrics'),2,3,'{"it":"Train 1.00 e test 0.71 indicano…","en":"Train 1.00 and test 0.71 indicate…"}','[{"it":"Overfitting","en":"Overfitting"},{"it":"Underfitting","en":"Underfitting"},{"it":"Un modello perfetto","en":"A perfect model"},{"it":"Dati mancanti","en":"Missing data"}]',0,'{"it":"Ha imparato a memoria.","en":"It memorised."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'metrics'),3,3,'{"it":"Il richiamo misura…","en":"Recall measures…"}','[{"it":"Quanti veri positivi trova","en":"How many real positives it finds"},{"it":"La velocità","en":"Speed"},{"it":"Quanti dati usa","en":"How much data it uses"},{"it":"La memoria occupata","en":"Memory used"}]',0,'{"it":"Per le frodi conta molto.","en":"For fraud it matters a lot."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'knn'),1,3,'{"it":"Come decide k-NN la classe di un nuovo esempio?","en":"How does k-NN decide a new example’s class?"}','[{"it":"Con una formula imparata durante l’addestramento","en":"With a formula learned during training"},{"it":"A caso tra le classi possibili","en":"At random among the possible classes"},{"it":"Con la classe più frequente tra i k vicini","en":"With the most frequent class among the k neighbours"},{"it":"Scegliendo sempre la classe più rara","en":"Always picking the rarest class"}]',2,'{"it":"Vota il vicinato.","en":"The neighbourhood votes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'knn'),2,3,'{"it":"Perché scalare i dati prima di k-NN?","en":"Why scale the data before k-NN?"}','[{"it":"Le distanze sarebbero dominate dalle colonne con numeri grandi","en":"Distances would be dominated by columns with big numbers"},{"it":"Per ridurre il numero di righe del dataset","en":"To reduce the number of rows"},{"it":"Perché k-NN accetta solo numeri negativi","en":"Because k-NN only accepts negative numbers"},{"it":"Non serve: k-NN ignora le unità di misura","en":"No need: k-NN ignores units"}]',0,'{"it":"Ogni colonna deve pesare in modo giusto.","en":"Each column must weigh fairly."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'knn'),3,3,'{"it":"Che cosa succede con k = 1?","en":"What happens with k = 1?"}','[{"it":"Il modello diventa più semplice e liscio","en":"The model becomes simpler and smoother"},{"it":"Segue ogni dettaglio e rischia l’overfitting","en":"It follows every detail and risks overfitting"},{"it":"Il modello non può fare previsioni","en":"The model cannot make predictions"},{"it":"Usa sempre la classe più frequente del dataset","en":"It always uses the dataset’s most frequent class"}]',1,'{"it":"Un solo vicino, anche se è rumore.","en":"A single neighbour, even if it is noise."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'confusion'),1,3,'{"it":"Un malato che il modello classifica come sano è…","en":"A sick person the model classifies as healthy is…"}','[{"it":"Un vero positivo","en":"A true positive"},{"it":"Un falso positivo","en":"A false positive"},{"it":"Un vero negativo","en":"A true negative"},{"it":"Un falso negativo","en":"A false negative"}]',3,'{"it":"Un positivo sfuggito.","en":"A missed positive."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'confusion'),2,3,'{"it":"Con 110 veri positivi e 30 falsi negativi, il richiamo è circa…","en":"With 110 true positives and 30 false negatives, recall is about…"}','[{"it":"0,92","en":"0,92"},{"it":"0,79","en":"0,79"},{"it":"0,11","en":"0,11"},{"it":"0,27","en":"0,27"}]',1,'{"it":"110 / (110 + 30).","en":"110 / (110 + 30)."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'confusion'),3,3,'{"it":"Che cosa succede abbassando la soglia da 0,5 a 0,3?","en":"What happens when lowering the threshold from 0.5 to 0.3?"}','[{"it":"Più positivi trovati e più falsi allarmi","en":"More positives found and more false alarms"},{"it":"Meno positivi trovati e meno falsi allarmi","en":"Fewer positives found and fewer false alarms"},{"it":"Il modello va riaddestrato da capo","en":"The model must be retrained from scratch"},{"it":"Precisione e richiamo restano identici","en":"Precision and recall stay identical"}]',0,'{"it":"Si scambia precisione con richiamo.","en":"You trade precision for recall."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'baseline'),1,3,'{"it":"Che cosa mostra `df.isna().sum()`?","en":"What does `df.isna().sum()` show?"}','[{"it":"La somma dei valori di ogni colonna","en":"The sum of each column’s values"},{"it":"Il numero di righe duplicate","en":"The number of duplicate rows"},{"it":"Il tipo di dato di ogni colonna","en":"Each column’s data type"},{"it":"Quanti valori mancano in ogni colonna","en":"How many values are missing in each column"}]',3,'{"it":"NaN contati per colonna.","en":"NaNs counted per column."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'baseline'),2,3,'{"it":"Che cosa fa `DummyClassifier(strategy=\\"most_frequent\\")`?","en":"What does `DummyClassifier(strategy=\\"most_frequent\\")` do?"}','[{"it":"Prevede sempre la classe più comune","en":"It always predicts the most common class"},{"it":"Sceglie da solo il modello migliore","en":"It picks the best model by itself"},{"it":"Toglie le righe con valori mancanti","en":"It removes rows with missing values"},{"it":"Bilancia automaticamente le classi","en":"It balances the classes automatically"}]',0,'{"it":"È il minimo da battere.","en":"It is the minimum to beat."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-base' AND slug = 'baseline'),3,3,'{"it":"La baseline fa 0,86 e il tuo modello 0,87. Che cosa ne pensi?","en":"The baseline scores 0.86 and your model 0.87. What do you make of it?"}','[{"it":"Ottimo: il modello è quasi perfetto","en":"Great: the model is nearly perfect"},{"it":"Il modello impara pochissimo di utile","en":"The model learns very little of use"},{"it":"La baseline è sbagliata e va ignorata","en":"The baseline is wrong and should be ignored"},{"it":"Bisogna togliere il test set","en":"The test set should be removed"}]',1,'{"it":"Un punto sopra il modello stupido.","en":"One point above the dumb model."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'features'),1,2,'{"it":"Che cosa fa il one-hot encoding?","en":"What does one-hot encoding do?"}','[{"it":"Trasforma categorie in colonne 0/1","en":"Turns categories into 0/1 columns"},{"it":"Cancella le categorie","en":"Deletes categories"},{"it":"Ordina i dati","en":"Sorts the data"},{"it":"Riempie i valori mancanti","en":"Fills missing values"}]',0,'{"it":"Una colonna per categoria.","en":"One column per category."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'features'),2,2,'{"it":"Che cos’è il data leakage?","en":"What is data leakage?"}','[{"it":"Informazioni del test che finiscono nell’addestramento","en":"Test information leaking into training"},{"it":"Un furto di dati dal server di addestramento","en":"A data theft from the training server"},{"it":"Un file corrotto","en":"A corrupted file"},{"it":"Un errore di rete","en":"A network error"}]',0,'{"it":"Rende il voto troppo ottimista.","en":"It makes the score too optimistic."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'features'),3,2,'{"it":"A che cosa serve `StandardScaler`?","en":"What is `StandardScaler` for?"}','[{"it":"Mettere i numeri sulla stessa scala","en":"Putting numbers on the same scale"},{"it":"Contare le righe","en":"Counting rows"},{"it":"Codificare i testi in numeri interi","en":"Encoding text as whole numbers"},{"it":"Disegnare grafici","en":"Drawing charts"}]',0,'{"it":"Media 0, deviazione 1.","en":"Mean 0, deviation 1."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'pipeline'),1,2,'{"it":"Perché usare una pipeline?","en":"Why use a pipeline?"}','[{"it":"Preparazione e modello insieme, senza leakage","en":"Preparation and model together, without leakage"},{"it":"Per rendere il modello più grande","en":"To make the model bigger"},{"it":"Per disegnare grafici","en":"To draw charts"},{"it":"Non serve mai","en":"It is never useful"}]',0,'{"it":"Impara tutto solo sul train.","en":"It learns everything on train only."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'pipeline'),2,2,'{"it":"A che cosa serve `make_column_transformer`?","en":"What is `make_column_transformer` for?"}','[{"it":"Trasformazioni diverse per colonne diverse","en":"Different transformations for different columns"},{"it":"Unire due tabelle sulla colonna comune","en":"Joining two tables on the common column"},{"it":"Rinominare colonne","en":"Renaming columns"},{"it":"Cancellare colonne","en":"Deleting columns"}]',0,'{"it":"Numeri scalati, categorie one-hot.","en":"Numbers scaled, categories one-hot."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'pipeline'),3,2,'{"it":"Come salvi una pipeline addestrata?","en":"How do you save a trained pipeline?"}','[{"it":"joblib.dump","en":"joblib.dump"},{"it":"print","en":"print"},{"it":"pipe.close()","en":"pipe.close()"},{"it":"export()","en":"export()"}]',0,'{"it":"E `joblib.load` per ricaricarla.","en":"And `joblib.load` to reload it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'ensembles'),1,2,'{"it":"Come decide una random forest?","en":"How does a random forest decide?"}','[{"it":"Fa votare molti alberi","en":"Many trees vote"},{"it":"Usa un solo albero profondo","en":"It uses one deep tree"},{"it":"A caso","en":"At random"},{"it":"Con una rete neurale","en":"With a neural network"}]',0,'{"it":"La saggezza della folla.","en":"Wisdom of the crowd."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'ensembles'),2,2,'{"it":"Che cosa fa ogni nuovo albero nel boosting?","en":"What does each new tree do in boosting?"}','[{"it":"Corregge gli errori dei precedenti","en":"Fixes the previous ones’ errors"},{"it":"Cancella gli altri","en":"Deletes the others"},{"it":"Ripete lo stesso albero","en":"Repeats the same tree"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Un passo alla volta.","en":"One step at a time."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'ensembles'),3,2,'{"it":"Su dati tabellari, quale modello è spesso il più forte?","en":"On tabular data, which model is often strongest?"}','[{"it":"Gradient boosting","en":"Gradient boosting"},{"it":"Regressione lineare sempre","en":"Linear regression always"},{"it":"Un modello linguistico","en":"A language model"},{"it":"Nessun modello","en":"No model"}]',0,'{"it":"Lo dicono molte competizioni.","en":"Many competitions show it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'tuning'),1,2,'{"it":"Che cos’è un iperparametro?","en":"What is a hyperparameter?"}','[{"it":"Una scelta fatta prima dell’addestramento","en":"A choice made before training"},{"it":"Un peso imparato","en":"A learned weight"},{"it":"Un dato di test","en":"A test datum"},{"it":"Un errore","en":"An error"}]',0,'{"it":"Come `max_depth`.","en":"Like `max_depth`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'tuning'),2,2,'{"it":"Con `cv=5` quante volte si addestra il modello?","en":"With `cv=5` how many times is the model trained?"}','[{"it":"5","en":"5"},{"it":"1","en":"1"},{"it":"10","en":"10"},{"it":"25","en":"25"}]',0,'{"it":"Una per ogni parte usata come validazione.","en":"Once per part used as validation."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'tuning'),3,2,'{"it":"Quando si usa il test set?","en":"When do you use the test set?"}','[{"it":"Una volta, alla fine","en":"Once, at the end"},{"it":"A ogni tentativo","en":"On every attempt"},{"it":"Per scegliere gli iperparametri","en":"To pick hyperparameters"},{"it":"Mai","en":"Never"}]',0,'{"it":"Altrimenti lo “consumi”.","en":"Otherwise you “use it up”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'clustering'),1,3,'{"it":"Che cosa fa k-means?","en":"What does k-means do?"}','[{"it":"Raggruppa i punti attorno a k centri","en":"Groups points around k centres"},{"it":"Prevede un prezzo","en":"Predicts a price"},{"it":"Classifica con le etichette","en":"Classifies with labels"},{"it":"Ordina alfabeticamente","en":"Sorts alphabetically"}]',0,'{"it":"Non servono etichette.","en":"No labels needed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'clustering'),2,3,'{"it":"Perché scalare i dati prima di k-means?","en":"Why scale data before k-means?"}','[{"it":"Usa le distanze","en":"It uses distances"},{"it":"Per renderlo più colorato","en":"To make it more colourful"},{"it":"Non serve","en":"It is not needed"},{"it":"Per avere meno righe","en":"To have fewer rows"}]',0,'{"it":"Una colonna in migliaia dominerebbe.","en":"A column in thousands would dominate."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'clustering'),3,3,'{"it":"Come scegli k?","en":"How do you choose k?"}','[{"it":"Provando valori e confrontando il silhouette score","en":"Trying values and comparing the silhouette score"},{"it":"Sempre 2","en":"Always 2"},{"it":"Lo sceglie il test set dopo l’addestramento","en":"The test set picks it after training"},{"it":"A caso","en":"At random"}]',0,'{"it":"Più alto è meglio.","en":"Higher is better."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'imbalanced'),1,3,'{"it":"Che cosa fa `class_weight=\\"balanced\\"`?","en":"What does `class_weight=\\"balanced\\"` do?"}','[{"it":"Duplica le righe del test set","en":"It duplicates the test set rows"},{"it":"Toglie la classe più comune","en":"It removes the most common class"},{"it":"Pesa di più gli errori sulla classe rara","en":"It weighs mistakes on the rare class more"},{"it":"Rende tutte le classi uguali nel dataset","en":"It makes all classes equal in the dataset"}]',2,'{"it":"Pesi inversi alla frequenza.","en":"Weights inverse to frequency."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'imbalanced'),2,3,'{"it":"Quale metrica è adatta per una classe rara?","en":"Which metric suits a rare class?"}','[{"it":"Average precision o F1","en":"Average precision or F1"},{"it":"Solo l’accuratezza","en":"Accuracy only"},{"it":"Il numero di righe del dataset","en":"The dataset’s row count"},{"it":"Il tempo di addestramento","en":"Training time"}]',0,'{"it":"Guardano la classe che conta.","en":"They look at the class that matters."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'imbalanced'),3,3,'{"it":"Dove va fatto il ricampionamento?","en":"Where should resampling be done?"}','[{"it":"Su tutti i dati prima della divisione","en":"On all data before the split"},{"it":"Solo sul test set","en":"On the test set only"},{"it":"Solo sul train set","en":"On the train set only"},{"it":"Su train e test separatamente","en":"On train and test separately"}]',2,'{"it":"Il test rispecchia il mondo reale.","en":"The test set mirrors the real world."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'pca'),1,3,'{"it":"Che cosa raccoglie la prima componente principale?","en":"What does the first principal component capture?"}','[{"it":"La colonna con il nome più lungo","en":"The column with the longest name"},{"it":"Solo i valori mancanti","en":"Only the missing values"},{"it":"La classe più frequente","en":"The most frequent class"},{"it":"La maggior parte della variabilità dei dati","en":"Most of the data’s variability"}]',3,'{"it":"Poi la seconda prende il resto.","en":"Then the second takes the rest."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'pca'),2,3,'{"it":"Che cosa indica `explained_variance_ratio_`?","en":"What does `explained_variance_ratio_` indicate?"}','[{"it":"La quota di variabilità tenuta da ogni componente","en":"The share of variability kept by each component"},{"it":"L’accuratezza del modello sul test","en":"The model’s test accuracy"},{"it":"Il numero di righe tolte","en":"The number of rows removed"},{"it":"Il tempo di calcolo della PCA","en":"PCA’s computation time"}]',0,'{"it":"Somma vicina a 1 = poca informazione persa.","en":"Sum near 1 = little information lost."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'pca'),3,3,'{"it":"Qual è uno svantaggio della PCA?","en":"What is a drawback of PCA?"}','[{"it":"Funziona solo con due colonne","en":"It only works with two columns"},{"it":"Le componenti sono più difficili da spiegare","en":"Components are harder to explain"},{"it":"Richiede sempre le etichette","en":"It always needs labels"},{"it":"Aumenta il numero di colonne","en":"It increases the number of columns"}]',1,'{"it":"Sono mescolanze di colonne.","en":"They are mixtures of columns."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'interpret'),1,3,'{"it":"Come misura l’importanza di una colonna la permutation importance?","en":"How does permutation importance measure a column’s importance?"}','[{"it":"Contando quante volte compare nel codice","en":"Counting how often it appears in the code"},{"it":"Guardando la lunghezza dei suoi valori","en":"Looking at the length of its values"},{"it":"Chiedendo all’utente quale preferisce","en":"Asking the user which one they prefer"},{"it":"Mescolandone i valori e misurando il calo del punteggio","en":"Shuffling its values and measuring the score drop"}]',3,'{"it":"Se il punteggio crolla, la colonna conta.","en":"If the score collapses, the column matters."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'interpret'),2,3,'{"it":"Che cosa serve per spiegare una singola previsione?","en":"What do you need to explain a single prediction?"}','[{"it":"Un metodo come SHAP","en":"A method such as SHAP"},{"it":"Il coefficiente di Pearson del dataset","en":"The dataset’s Pearson coefficient"},{"it":"Una nuova divisione train/test","en":"A new train/test split"},{"it":"Un modello più grande","en":"A larger model"}]',0,'{"it":"Spiega il contributo di ogni colonna per quel caso.","en":"It explains each column’s contribution for that case."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ml-intermediate' AND slug = 'interpret'),3,3,'{"it":"Se una colonna è molto importante per il modello, significa che…","en":"If a column is very important to the model, it means that…"}','[{"it":"È sicuramente la causa del risultato","en":"It is surely the cause of the outcome"},{"it":"Il modello vi si appoggia, ma non prova una causa","en":"The model relies on it, but it proves no cause"},{"it":"Va subito tolta dal dataset","en":"It must be removed from the dataset at once"},{"it":"Il modello è in overfitting","en":"The model is overfitting"}]',1,'{"it":"Correlazione non è causalità.","en":"Correlation is not causation."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'neurons'),1,2,'{"it":"Che cosa fa ReLU?","en":"What does ReLU do?"}','[{"it":"Azzera i valori negativi","en":"Zeroes negative values"},{"it":"Raddoppia i valori","en":"Doubles values"},{"it":"Ordina i valori","en":"Sorts values"},{"it":"Calcola la media","en":"Computes the mean"}]',0,'{"it":"max(0, x).","en":"max(0, x)."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'neurons'),2,2,'{"it":"Perché servono le attivazioni non lineari?","en":"Why are non-linear activations needed?"}','[{"it":"Altrimenti più strati equivalgono a uno","en":"Otherwise many layers equal one"},{"it":"Per velocizzare","en":"To speed up"},{"it":"Per usare meno memoria","en":"To use less memory"},{"it":"Non servono","en":"They are not needed"}]',0,'{"it":"La non linearità dà potenza.","en":"Non-linearity gives power."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'neurons'),3,2,'{"it":"`nn.Linear(4, 16)` collega…","en":"`nn.Linear(4, 16)` connects…"}','[{"it":"4 input a 16 neuroni","en":"4 inputs to 16 neurons"},{"it":"16 input a 4 neuroni","en":"16 inputs to 4 neurons"},{"it":"4 strati","en":"4 layers"},{"it":"16 immagini","en":"16 images"}]',0,'{"it":"Prima gli input, poi le uscite.","en":"Inputs first, then outputs."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'tensors'),1,2,'{"it":"Che cosa fa `y.backward()`?","en":"What does `y.backward()` do?"}','[{"it":"Calcola le derivate","en":"Computes the derivatives"},{"it":"Torna indietro di un passo","en":"Goes back one step"},{"it":"Cancella y","en":"Deletes y"},{"it":"Inverte il tensore","en":"Reverses the tensor"}]',0,'{"it":"Autograd.","en":"Autograd."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'tensors'),2,2,'{"it":"Che cosa indica `requires_grad=True`?","en":"What does `requires_grad=True` mean?"}','[{"it":"Che servono le derivate di quel tensore","en":"That tensor’s derivatives are needed"},{"it":"Che il tensore viene spostato sulla GPU","en":"That the tensor is moved to the GPU"},{"it":"Che è un intero","en":"That it is an integer"},{"it":"Che è costante","en":"That it is constant"}]',0,'{"it":"Tipico dei pesi.","en":"Typical of weights."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'tensors'),3,2,'{"it":"Come sposti un tensore sulla GPU?","en":"How do you move a tensor to the GPU?"}','[{"it":"Con `.to(\\"cuda\\")`","en":"With `.to(\\"cuda\\")`"},{"it":"Con `.gpu = True`","en":"With `.gpu = True`"},{"it":"Non si può","en":"You cannot"},{"it":"Con `print`","en":"With `print`"}]',0,'{"it":"E il modello va spostato insieme.","en":"And the model must move too."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'training'),1,2,'{"it":"Perché si chiama `zero_grad()`?","en":"Why call `zero_grad()`?"}','[{"it":"I gradienti altrimenti si sommano","en":"Otherwise gradients accumulate"},{"it":"Per cancellare il modello","en":"To delete the model"},{"it":"Per fermare l’addestramento","en":"To stop training"},{"it":"Per salvare","en":"To save"}]',0,'{"it":"PyTorch accumula per scelta.","en":"PyTorch accumulates by design."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'training'),2,2,'{"it":"Che cos’è un’epoca?","en":"What is an epoch?"}','[{"it":"Un giro completo sui dati","en":"One full pass over the data"},{"it":"Un solo esempio","en":"A single example"},{"it":"Un’ora di calcolo","en":"An hour of compute"},{"it":"Uno strato","en":"A layer"}]',0,'{"it":"Fatta di tanti batch.","en":"Made of many batches."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'training'),3,2,'{"it":"Quale loss per la classificazione?","en":"Which loss for classification?"}','[{"it":"CrossEntropyLoss","en":"CrossEntropyLoss"},{"it":"MSELoss","en":"MSELoss"},{"it":"L1Loss","en":"L1Loss"},{"it":"ReLU","en":"ReLU"}]',0,'{"it":"MSE è per la regressione.","en":"MSE is for regression."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'cnn'),1,2,'{"it":"Che cosa impara uno strato convoluzionale?","en":"What does a convolutional layer learn?"}','[{"it":"Filtri che riconoscono motivi visivi","en":"Filters recognising visual patterns"},{"it":"Le parole di una frase","en":"The words of a sentence"},{"it":"Le tabelle di un database","en":"Database tables"},{"it":"Il colore dello schermo","en":"The screen colour"}]',0,'{"it":"Bordi, forme, oggetti.","en":"Edges, shapes, objects."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'cnn'),2,2,'{"it":"Che cosa fa `MaxPool2d(2)`?","en":"What does `MaxPool2d(2)` do?"}','[{"it":"Dimezza larghezza e altezza","en":"Halves width and height"},{"it":"Raddoppia l’immagine","en":"Doubles the image"},{"it":"Aggiunge colori","en":"Adds colours"},{"it":"Ruota l’immagine","en":"Rotates the image"}]',0,'{"it":"Tiene il valore massimo di ogni blocco.","en":"Keeps the max of each block."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'cnn'),3,2,'{"it":"Che cos’è il transfer learning?","en":"What is transfer learning?"}','[{"it":"Adattare una rete già addestrata","en":"Adapting an already trained network"},{"it":"Copiare dati da un server","en":"Copying data from a server"},{"it":"Tradurre un modello","en":"Translating a model"},{"it":"Comprimere le immagini","en":"Compressing images"}]',0,'{"it":"Pochi dati, buoni risultati.","en":"Little data, good results."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'regularize'),1,3,'{"it":"Che cosa fa il dropout?","en":"What does dropout do?"}','[{"it":"Spegne a caso dei neuroni in addestramento","en":"Randomly switches off neurons in training"},{"it":"Cancella dati","en":"Deletes data"},{"it":"Ferma la rete","en":"Stops the network"},{"it":"Aggiunge strati nascosti durante l’addestramento","en":"Adds hidden layers during training"}]',0,'{"it":"La rete non dipende da un solo neurone.","en":"The network does not rely on a single neuron."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'regularize'),2,3,'{"it":"Che cos’è l’early stopping?","en":"What is early stopping?"}','[{"it":"Fermarsi quando la validazione non migliora più","en":"Stopping when validation stops improving"},{"it":"Fermarsi alla prima epoca","en":"Stopping at the first epoch"},{"it":"Spegnere il computer","en":"Turning off the computer"},{"it":"Un errore di PyTorch","en":"A PyTorch error"}]',0,'{"it":"Prima di imparare il rumore.","en":"Before learning the noise."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'regularize'),3,3,'{"it":"Che cosa fa `rete.eval()`?","en":"What does `rete.eval()` do?"}','[{"it":"Mette la rete in modalità valutazione","en":"Puts the network in evaluation mode"},{"it":"Valuta il codice Python","en":"Evaluates Python code"},{"it":"Addestra la rete","en":"Trains the network"},{"it":"Cancella i pesi","en":"Deletes the weights"}]',0,'{"it":"Il dropout si spegne.","en":"Dropout turns off."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'data'),1,3,'{"it":"Che cosa deve restituire `__getitem__`?","en":"What must `__getitem__` return?"}','[{"it":"Il numero totale di esempi","en":"The total number of examples"},{"it":"Un batch già pronto di 32 esempi","en":"A ready batch of 32 examples"},{"it":"L’esempio numero i, di solito input ed etichetta","en":"Example number i, usually input and label"},{"it":"I pesi della rete","en":"The network’s weights"}]',2,'{"it":"`__len__` dà il totale.","en":"`__len__` gives the total."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'data'),2,3,'{"it":"Che cosa fa `shuffle=True` nel DataLoader?","en":"What does `shuffle=True` do in the DataLoader?"}','[{"it":"Mescola l’ordine degli esempi a ogni epoca","en":"It shuffles the order of examples every epoch"},{"it":"Cambia le etichette a caso","en":"It changes labels at random"},{"it":"Divide i dati in train e test","en":"It splits data into train and test"},{"it":"Raddoppia il numero di esempi","en":"It doubles the number of examples"}]',0,'{"it":"Così la rete non impara l’ordine.","en":"So the network does not learn the order."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'data'),3,3,'{"it":"Che cosa comporta un batch più grande?","en":"What does a bigger batch mean?"}','[{"it":"Meno memoria usata sulla GPU","en":"Less GPU memory used"},{"it":"Più memoria usata ma GPU sfruttata meglio","en":"More memory used but the GPU used better"},{"it":"Nessuna differenza in nessun caso","en":"No difference in any case"},{"it":"Un modello con più strati","en":"A model with more layers"}]',1,'{"it":"Un compromesso.","en":"A trade-off."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'transfer'),1,3,'{"it":"Che cosa fa `p.requires_grad = False` su tutti i parametri?","en":"What does `p.requires_grad = False` on all parameters do?"}','[{"it":"Cancella i pesi della rete","en":"It deletes the network’s weights"},{"it":"Sposta la rete sulla GPU","en":"It moves the network to the GPU"},{"it":"Mette la rete in modalità valutazione","en":"It puts the network in evaluation mode"},{"it":"Congela i pesi: non vengono aggiornati","en":"It freezes the weights: they are not updated"}]',3,'{"it":"Niente gradienti, niente aggiornamenti.","en":"No gradients, no updates."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'transfer'),2,3,'{"it":"Perché si sostituisce l’ultimo strato?","en":"Why replace the last layer?"}','[{"it":"Per avere tante uscite quante sono le tue classi","en":"To have as many outputs as your classes"},{"it":"Per rendere la rete più veloce","en":"To make the network faster"},{"it":"Perché l’ultimo strato è sempre rotto","en":"Because the last layer is always broken"},{"it":"Per ridurre la dimensione delle immagini","en":"To shrink the images"}]',0,'{"it":"Le classi originali erano altre.","en":"The original classes were different."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'transfer'),3,3,'{"it":"Che cosa contiene lo `state_dict`?","en":"What does the `state_dict` contain?"}','[{"it":"Il codice Python della rete","en":"The network’s Python code"},{"it":"I pesi della rete, strato per strato","en":"The network’s weights, layer by layer"},{"it":"Le immagini di addestramento","en":"The training images"},{"it":"La storia delle loss","en":"The history of the losses"}]',1,'{"it":"L’architettura la ricrei tu.","en":"You recreate the architecture."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'sequences'),1,3,'{"it":"Che cos’è lo stato nascosto di una RNN?","en":"What is an RNN’s hidden state?"}','[{"it":"Un parametro segreto non addestrabile","en":"A secret, untrainable parameter"},{"it":"Il file in cui si salva la rete","en":"The file the network is saved to"},{"it":"L’etichetta della sequenza","en":"The sequence’s label"},{"it":"Una memoria di ciò che ha letto finora","en":"A memory of what it has read so far"}]',3,'{"it":"Passa da un passo al successivo.","en":"It passes from one step to the next."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'sequences'),2,3,'{"it":"Che cosa aggiungono le porte di una LSTM?","en":"What do an LSTM’s gates add?"}','[{"it":"Decidono cosa ricordare e cosa dimenticare","en":"They decide what to remember and what to forget"},{"it":"Permettono di leggere immagini a colori","en":"They allow reading colour images"},{"it":"Rendono la rete non addestrabile","en":"They make the network untrainable"},{"it":"Eliminano la necessità dei dati","en":"They remove the need for data"}]',0,'{"it":"Memoria più lunga e stabile.","en":"Longer, steadier memory."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-base' AND slug = 'sequences'),3,3,'{"it":"Perché i transformer hanno superato le RNN nel linguaggio?","en":"Why did transformers overtake RNNs in language?"}','[{"it":"Usano meno parametri in ogni caso","en":"They always use fewer parameters"},{"it":"Si parallelizzano meglio e collegano parti lontane del testo","en":"They parallelise better and link distant parts of the text"},{"it":"Non hanno bisogno di addestramento","en":"They need no training"},{"it":"Funzionano solo su CPU","en":"They only run on CPUs"}]',1,'{"it":"L’attention guarda tutto il contesto insieme.","en":"Attention looks at the whole context at once."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'system'),1,2,'{"it":"Chi scrive di solito il system prompt?","en":"Who usually writes the system prompt?"}','[{"it":"Chi costruisce il servizio","en":"Whoever builds the service"},{"it":"L’utente a ogni messaggio","en":"The user in each message"},{"it":"Il modello da solo","en":"The model itself"},{"it":"Nessuno","en":"Nobody"}]',0,'{"it":"Vale per tutta la conversazione.","en":"It applies to the whole conversation."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'system'),2,2,'{"it":"Che cosa conviene mettere in un system prompt?","en":"What belongs in a system prompt?"}','[{"it":"Ruolo, regole, tono e casi limite","en":"Role, rules, tone and edge cases"},{"it":"La domanda dell’utente","en":"The user’s question"},{"it":"Le password","en":"Passwords"},{"it":"Niente, meglio vuoto","en":"Nothing, better empty"}]',0,'{"it":"Il quadro generale.","en":"The general frame."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'system'),3,2,'{"it":"Perché prevedere i casi limite?","en":"Why plan for edge cases?"}','[{"it":"Così il modello sa cosa fare quando la richiesta esce dal previsto","en":"So the model knows what to do when a request goes off-script"},{"it":"Per allungare il testo e sembrare più completi","en":"To lengthen the text and look more thorough"},{"it":"Non serve","en":"It is not needed"},{"it":"Per confondere l’utente","en":"To confuse the user"}]',0,'{"it":"Sono lì che si sbaglia.","en":"That is where mistakes happen."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'reasoning'),1,2,'{"it":"Quando conviene chiedere di ragionare?","en":"When is asking for reasoning worth it?"}','[{"it":"Nei problemi con più passaggi","en":"In multi-step problems"},{"it":"Per dire “ciao”","en":"To say “hello”"},{"it":"Sempre, anche per compiti banali","en":"Always, even trivial tasks"},{"it":"Mai","en":"Never"}]',0,'{"it":"Costa tempo e token.","en":"It costs time and tokens."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'reasoning'),2,2,'{"it":"Perché separare ragionamento e risposta con tag?","en":"Why separate reasoning and answer with tags?"}','[{"it":"Per mostrare all’utente solo la risposta","en":"To show the user only the answer"},{"it":"Per abbellire","en":"To decorate"},{"it":"Per rallentare","en":"To slow down"},{"it":"È obbligatorio per legge","en":"The law requires it"}]',0,'{"it":"Il programma estrae `<risposta>`.","en":"The program extracts `<answer>`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'reasoning'),3,2,'{"it":"Che cos’è il “thinking” integrato?","en":"What is built-in “thinking”?"}','[{"it":"Un ragionamento del modello prima della risposta","en":"The model’s reasoning before the answer"},{"it":"Un plugin del browser che legge la pagina","en":"A browser plugin that reads the page"},{"it":"Un tipo di database","en":"A kind of database"},{"it":"Una modalità scura","en":"A dark mode"}]',0,'{"it":"Molti modelli recenti lo hanno.","en":"Many recent models have it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'structured'),1,2,'{"it":"Che cosa fa `enum` in uno schema?","en":"What does `enum` do in a schema?"}','[{"it":"Limita i valori ammessi","en":"Limits the allowed values"},{"it":"Numera i campi","en":"Numbers the fields"},{"it":"Cifra il testo","en":"Encrypts text"},{"it":"Rende il campo facoltativo","en":"Makes the field optional"}]',0,'{"it":"Un elenco chiuso.","en":"A closed list."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'structured'),2,2,'{"it":"Perché validare l’output nel codice?","en":"Why validate output in code?"}','[{"it":"Un modello può comunque sbagliare formato","en":"A model can still get the format wrong"},{"it":"Per allungare il programma","en":"To lengthen the program"},{"it":"Non serve mai","en":"It is never needed"},{"it":"Per cambiare lingua","en":"To change language"}]',0,'{"it":"Fidarsi è bene, controllare è meglio.","en":"Trust, but verify."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'structured'),3,2,'{"it":"Che cosa vieta `additionalProperties: false`?","en":"What does `additionalProperties: false` forbid?"}','[{"it":"Campi non previsti","en":"Unexpected fields"},{"it":"I numeri","en":"Numbers"},{"it":"Gli array","en":"Arrays"},{"it":"Le stringhe vuote","en":"Empty strings"}]',0,'{"it":"Solo i campi dello schema.","en":"Only the schema’s fields."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'chaining'),1,2,'{"it":"Perché spezzare un compito in una catena di prompt?","en":"Why split a task into a prompt chain?"}','[{"it":"Ogni passo è più semplice e verificabile","en":"Each step is simpler and verifiable"},{"it":"Per spendere di più","en":"To spend more"},{"it":"È obbligatorio","en":"It is mandatory"},{"it":"Per confondere il modello","en":"To confuse the model"}]',0,'{"it":"E puoi scegliere il modello per passo.","en":"And you can pick a model per step."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'chaining'),2,2,'{"it":"Che cos’è una eval?","en":"What is an eval?"}','[{"it":"Un insieme di casi di test con risultato atteso","en":"A set of test cases with expected results"},{"it":"Una funzione di JavaScript che esegue il codice","en":"A JavaScript function that runs code"},{"it":"Un tipo di modello","en":"A model type"},{"it":"Un abbonamento","en":"A subscription"}]',0,'{"it":"Misura invece di intuire.","en":"Measure instead of guessing."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'chaining'),3,2,'{"it":"Che cos’è LLM-as-judge?","en":"What is LLM-as-judge?"}','[{"it":"Un modello che valuta le risposte secondo criteri","en":"A model grading answers against criteria"},{"it":"Un tribunale digitale per le dispute online","en":"A digital court for online disputes"},{"it":"Un errore di sistema","en":"A system error"},{"it":"Un gioco","en":"A game"}]',0,'{"it":"Utile quando non c’è una sola risposta giusta.","en":"Useful when there is no single right answer."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'injection'),1,3,'{"it":"Che cos’è la prompt injection?","en":"What is prompt injection?"}','[{"it":"Istruzioni nascoste in un testo esterno","en":"Instructions hidden in external text"},{"it":"Un modo per velocizzare il modello","en":"A way to speed up the model"},{"it":"Un vaccino","en":"A vaccine"},{"it":"Un formato di file","en":"A file format"}]',0,'{"it":"Il dato si finge istruzione.","en":"Data pretending to be instructions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'injection'),2,3,'{"it":"Qual è la difesa più solida?","en":"What is the sturdiest defence?"}','[{"it":"Limitare i permessi e chiedere conferma per le azioni rischiose","en":"Limiting permissions and confirming risky actions"},{"it":"Scrivere nel prompt “non farti ingannare da nessun testo”","en":"Writing “do not be fooled by any text” in the prompt"},{"it":"Usare il maiuscolo","en":"Using capitals"},{"it":"Nessuna","en":"None"}]',0,'{"it":"Il prompt da solo non basta.","en":"The prompt alone is not enough."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'injection'),3,3,'{"it":"Perché mettere il testo esterno tra tag?","en":"Why put external text between tags?"}','[{"it":"Per separare dati e istruzioni","en":"To separate data from instructions"},{"it":"Per colorarlo","en":"To colour it"},{"it":"Per tradurlo","en":"To translate it"},{"it":"Per accorciarlo e risparmiare token","en":"To shorten it and save tokens"}]',0,'{"it":"Aiuta, ma non è una garanzia.","en":"It helps, but it is no guarantee."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'long-context'),1,3,'{"it":"Con documenti lunghi, dove conviene mettere la domanda?","en":"With long documents, where should the question go?"}','[{"it":"All’inizio, prima dei documenti","en":"At the start, before the documents"},{"it":"In mezzo ai documenti","en":"In the middle of the documents"},{"it":"In un messaggio separato senza documenti","en":"In a separate message without documents"},{"it":"In fondo, dopo i documenti","en":"At the end, after the documents"}]',3,'{"it":"Documenti in alto, domanda in basso.","en":"Documents on top, question at the bottom."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'long-context'),2,3,'{"it":"Perché far estrarre le citazioni prima della risposta?","en":"Why have quotes extracted before the answer?"}','[{"it":"Concentra il modello sulle parti giuste e rende verificabile","en":"It focuses the model on the right parts and makes it checkable"},{"it":"Rende la risposta più lunga e completa","en":"It makes the answer longer and fuller"},{"it":"Riduce sempre i token usati","en":"It always reduces the tokens used"},{"it":"Evita di dover leggere i documenti","en":"It avoids having to read the documents"}]',0,'{"it":"Prima le prove, poi la conclusione.","en":"Evidence first, then the conclusion."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'long-context'),3,3,'{"it":"Due documenti si contraddicono. Che cosa conviene scrivere nel prompt?","en":"Two documents contradict each other. What should the prompt say?"}','[{"it":"Niente: il modello capirà da solo","en":"Nothing: the model will work it out"},{"it":"Una regola per decidere, come “vale il più recente”","en":"A rule to decide, like “the most recent one wins”"},{"it":"Di ignorare entrambi i documenti","en":"To ignore both documents"},{"it":"Di scegliere il documento più lungo","en":"To pick the longer document"}]',1,'{"it":"Una regola esplicita evita scelte a caso.","en":"An explicit rule avoids random choices."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'reasoning-models'),1,3,'{"it":"Che cosa conviene dare a un modello che ragiona da solo?","en":"What should you give a model that reasons on its own?"}','[{"it":"Un elenco rigido di passaggi numerati","en":"A rigid list of numbered steps"},{"it":"Solo una parola chiave","en":"Just one keyword"},{"it":"Obiettivo, contesto e criteri di successo","en":"Goal, context and success criteria"},{"it":"L’ordine di non ragionare","en":"An order not to reason"}]',2,'{"it":"Il come lo trova lui.","en":"It works out the how."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'reasoning-models'),2,3,'{"it":"Quale istruzione resta utile anche con i modelli che ragionano?","en":"Which instruction stays useful with reasoning models too?"}','[{"it":"Verificare il lavoro prima di concludere","en":"Checking the work before finishing"},{"it":"Ripetere “pensa passo per passo” tre volte","en":"Repeating “think step by step” three times"},{"it":"Vietare di fare domande","en":"Forbidding questions"},{"it":"Scrivere tutto in maiuscolo","en":"Writing everything in capitals"}]',0,'{"it":"E anche formato e vincoli.","en":"And format and constraints too."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'prompt-advanced' AND slug = 'reasoning-models'),3,3,'{"it":"Come si regola quanto ragiona il modello?","en":"How do you tune how much the model reasons?"}','[{"it":"Cambiando lingua al prompt","en":"Changing the prompt’s language"},{"it":"Spesso con un parametro di sforzo","en":"Often with an effort parameter"},{"it":"Allungando il nome del modello","en":"Lengthening the model name"},{"it":"Non si può regolare in nessun modo","en":"It cannot be tuned in any way"}]',1,'{"it":"Più sforzo per i problemi difficili.","en":"More effort for hard problems."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'messages'),1,2,'{"it":"L’API ricorda la conversazione precedente?","en":"Does the API remember the previous conversation?"}','[{"it":"No, si rimanda la storia a ogni chiamata","en":"No, you resend the history each call"},{"it":"Sì, sempre","en":"Yes, always"},{"it":"Solo il lunedì","en":"Only on Mondays"},{"it":"Solo con la chiave premium","en":"Only with a premium key"}]',0,'{"it":"Ogni richiesta è indipendente.","en":"Each request is independent."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'messages'),2,2,'{"it":"Quale ruolo ha il messaggio di chi chiede?","en":"Which role does the asker’s message have?"}','[{"it":"user","en":"user"},{"it":"assistant","en":"assistant"},{"it":"system","en":"system"},{"it":"admin","en":"admin"}]',0,'{"it":"`assistant` è il modello.","en":"`assistant` is the model."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'messages'),3,2,'{"it":"Che cosa succede se la risposta raggiunge `max_tokens`?","en":"What happens if the answer hits `max_tokens`?"}','[{"it":"Si interrompe a metà","en":"It stops midway"},{"it":"Continua lo stesso","en":"It continues anyway"},{"it":"Dà errore 404","en":"It returns a 404"},{"it":"Si ripete","en":"It repeats"}]',0,'{"it":"Meglio non tenerlo troppo basso.","en":"Better not set it too low."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'tokens'),1,2,'{"it":"Che cosa si paga in un’API LLM?","en":"What do you pay for in an LLM API?"}','[{"it":"Token in ingresso e in uscita","en":"Input and output tokens"},{"it":"Il numero di parole del titolo","en":"The words in the title"},{"it":"Le ore di connessione","en":"Connection hours"},{"it":"I clic","en":"Clicks"}]',0,'{"it":"Con prezzi diversi.","en":"At different prices."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'tokens'),2,2,'{"it":"Dove leggi i token usati?","en":"Where do you read the tokens used?"}','[{"it":"usage","en":"usage"},{"it":"headers","en":"headers"},{"it":"model","en":"model"},{"it":"system","en":"system"}]',0,'{"it":"`input_tokens` e `output_tokens`.","en":"`input_tokens` and `output_tokens`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'tokens'),3,2,'{"it":"Come risparmi su un prompt lungo che si ripete?","en":"How do you save on a long prompt that repeats?"}','[{"it":"Con il prompt caching","en":"With prompt caching"},{"it":"Scrivendolo in maiuscolo","en":"Writing it in capitals"},{"it":"Rimandandolo due volte","en":"Sending it twice"},{"it":"Non si può","en":"You cannot"}]',0,'{"it":"Le parti in cache costano molto meno.","en":"Cached parts cost much less."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'streaming'),1,2,'{"it":"Perché usare lo streaming?","en":"Why use streaming?"}','[{"it":"L’utente vede il testo mentre arriva","en":"The user sees text as it arrives"},{"it":"Costa meno token","en":"It costs fewer tokens"},{"it":"Migliora la grammatica","en":"It improves grammar"},{"it":"È obbligatorio","en":"It is mandatory"}]',0,'{"it":"E si evitano i timeout.","en":"And timeouts are avoided."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'streaming'),2,2,'{"it":"Con quale tecnologia arriva spesso lo streaming al browser?","en":"Which technology often carries streaming to the browser?"}','[{"it":"Server-Sent Events","en":"Server-Sent Events"},{"it":"FTP","en":"FTP"},{"it":"SMTP","en":"SMTP"},{"it":"CSV","en":"CSV"}]',0,'{"it":"O i WebSocket.","en":"Or WebSockets."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'streaming'),3,2,'{"it":"A che cosa serve `get_final_message()`?","en":"What is `get_final_message()` for?"}','[{"it":"Avere la risposta completa alla fine","en":"Getting the complete answer at the end"},{"it":"Annullare lo stream se è troppo lungo","en":"Cancelling the stream if it is too long"},{"it":"Ricominciare","en":"Restarting"},{"it":"Cambiare modello","en":"Changing model"}]',0,'{"it":"Con testo e usage.","en":"With text and usage."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'tools'),1,2,'{"it":"Chi esegue davvero lo strumento?","en":"Who actually runs the tool?"}','[{"it":"Il tuo programma","en":"Your program"},{"it":"Il modello","en":"The model"},{"it":"Il browser dell’utente","en":"The user’s browser"},{"it":"Nessuno","en":"Nobody"}]',0,'{"it":"Il modello chiede, tu esegui.","en":"The model asks, you run."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'tools'),2,2,'{"it":"Che cosa indica `stop_reason == \\"tool_use\\"`?","en":"What does `stop_reason == \\"tool_use\\"` mean?"}','[{"it":"Il modello vuole usare uno strumento","en":"The model wants to use a tool"},{"it":"La risposta è finita","en":"The answer is over"},{"it":"C’è un errore","en":"There is an error"},{"it":"Il token è scaduto","en":"The token expired"}]',0,'{"it":"Esegui e rimanda il risultato.","en":"Run it and send the result back."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'tools'),3,2,'{"it":"Che cosa descrive `input_schema`?","en":"What does `input_schema` describe?"}','[{"it":"Gli argomenti dello strumento","en":"The tool’s arguments"},{"it":"Il risultato","en":"The result"},{"it":"Il prezzo","en":"The price"},{"it":"L’utente","en":"The user"}]',0,'{"it":"Uno schema JSON.","en":"A JSON schema."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'production'),1,3,'{"it":"Dove va tenuta la chiave API?","en":"Where should the API key be kept?"}','[{"it":"In una variabile d’ambiente sul server","en":"In an environment variable on the server"},{"it":"Nel JavaScript del sito","en":"In the site’s JavaScript"},{"it":"Nel README pubblico","en":"In the public README"},{"it":"In un commento del codice","en":"In a code comment"}]',0,'{"it":"Chi la vede la può usare.","en":"Whoever sees it can use it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'production'),2,3,'{"it":"Che cosa fai con un errore 429?","en":"What do you do with a 429 error?"}','[{"it":"Aspetti e riprovi","en":"Wait and retry"},{"it":"Cambi chiave a caso","en":"Swap keys at random"},{"it":"Riprovi all’infinito subito","en":"Retry forever at once"},{"it":"Cancelli l’account","en":"Delete the account"}]',0,'{"it":"Troppe richieste.","en":"Too many requests."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'production'),3,3,'{"it":"Riprovare serve con un errore 400?","en":"Does retrying help with a 400 error?"}','[{"it":"No, la richiesta va corretta","en":"No, the request must be fixed"},{"it":"Sì, sempre","en":"Yes, always"},{"it":"Solo di notte","en":"Only at night"},{"it":"Solo con streaming","en":"Only with streaming"}]',0,'{"it":"L’errore è nella richiesta.","en":"The error is in the request."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'structured'),1,3,'{"it":"Che cosa garantisce lo schema passato in `output_config`?","en":"What does the schema passed in `output_config` guarantee?"}','[{"it":"Che la risposta sia più breve","en":"That the answer is shorter"},{"it":"Che la risposta sia sempre vera","en":"That the answer is always true"},{"it":"Che il modello usi meno token","en":"That the model uses fewer tokens"},{"it":"Che la risposta rispetti la struttura dello schema","en":"That the answer follows the schema’s structure"}]',3,'{"it":"Il formato, non la verità del contenuto.","en":"The format, not the truth of the content."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'structured'),2,3,'{"it":"A che cosa serve `\\"strict\\": True` su uno strumento?","en":"What is `\\"strict\\": True` on a tool for?"}','[{"it":"Gli argomenti rispettano esattamente lo schema","en":"The arguments follow the schema exactly"},{"it":"Lo strumento viene eseguito dal modello","en":"The tool is run by the model"},{"it":"Lo strumento diventa obbligatorio","en":"The tool becomes mandatory"},{"it":"Lo strumento risponde più in fretta","en":"The tool answers faster"}]',0,'{"it":"Niente argomenti mancanti o in più.","en":"No missing or extra arguments."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'structured'),3,3,'{"it":"Perché controllare `stop_reason` anche con l’output strutturato?","en":"Why check `stop_reason` even with structured output?"}','[{"it":"Per sapere che modello ha risposto","en":"To know which model answered"},{"it":"Se si ferma a `max_tokens` il JSON può essere incompleto","en":"If it stops at `max_tokens` the JSON may be incomplete"},{"it":"Per contare le parole della risposta","en":"To count the answer’s words"},{"it":"Non serve mai controllarlo","en":"It never needs checking"}]',1,'{"it":"Tagliato a metà non si legge.","en":"Cut in half, it cannot be parsed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'cache-batch'),1,3,'{"it":"Dove va la parte fissa del prompt per sfruttare la cache?","en":"Where does the fixed part of the prompt go to use the cache?"}','[{"it":"Alla fine, dopo la domanda","en":"At the end, after the question"},{"it":"In un file separato mai inviato","en":"In a separate file never sent"},{"it":"All’inizio, prima delle parti che cambiano","en":"At the start, before the changing parts"},{"it":"Non conta dove va","en":"It does not matter where"}]',2,'{"it":"La cache riconosce il prefisso.","en":"The cache matches the prefix."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'cache-batch'),2,3,'{"it":"Come si abbinano i risultati di un batch alle richieste?","en":"How do you match batch results to requests?"}','[{"it":"Con il `custom_id` di ogni richiesta","en":"With each request’s `custom_id`"},{"it":"Con la posizione nell’elenco dei risultati","en":"With the position in the result list"},{"it":"Con l’ora di arrivo dei risultati","en":"With the results’ arrival time"},{"it":"Non si possono abbinare","en":"They cannot be matched"}]',0,'{"it":"L’ordine non è garantito.","en":"Order is not guaranteed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'cache-batch'),3,3,'{"it":"Quando conviene la Batch API?","en":"When is the Batch API worth it?"}','[{"it":"Per una chat dal vivo con l’utente","en":"For a live chat with the user"},{"it":"Per migliaia di richieste non urgenti","en":"For thousands of non-urgent requests"},{"it":"Per una sola domanda urgente","en":"For a single urgent question"},{"it":"Per lo streaming delle risposte","en":"For streaming answers"}]',1,'{"it":"Meno caro, ma non immediato.","en":"Cheaper, but not immediate."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'vision'),1,3,'{"it":"Come si manda un’immagine insieme a una domanda?","en":"How do you send an image together with a question?"}','[{"it":"Incollando il percorso del file nel testo","en":"Pasting the file path into the text"},{"it":"Con due richieste separate, una per blocco","en":"With two separate requests, one per block"},{"it":"Mettendo l’immagine nel system prompt come testo","en":"Putting the image in the system prompt as text"},{"it":"Con un elenco di blocchi: `image` e poi `text`","en":"With a list of blocks: `image` then `text`"}]',3,'{"it":"Più blocchi nello stesso messaggio.","en":"Several blocks in the same message."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'vision'),2,3,'{"it":"Quale `type` ha il blocco di un PDF?","en":"What `type` does a PDF block have?"}','[{"it":"document","en":"document"},{"it":"pdf","en":"pdf"},{"it":"file_text","en":"file_text"},{"it":"attachment","en":"attachment"}]',0,'{"it":"Con `media_type` application/pdf.","en":"With `media_type` application/pdf."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'vision'),3,3,'{"it":"Perché ridimensionare una foto molto grande prima di inviarla?","en":"Why resize a very large photo before sending it?"}','[{"it":"Le foto grandi non si possono codificare in base64","en":"Large photos cannot be base64-encoded"},{"it":"Le immagini si pagano in token in base alla dimensione","en":"Images are billed in tokens by size"},{"it":"Il modello legge solo immagini in bianco e nero","en":"The model only reads black-and-white images"},{"it":"Per rendere il testo più leggibile all’utente","en":"To make the text more readable to the user"}]',1,'{"it":"Meno pixel, meno token.","en":"Fewer pixels, fewer tokens."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'embeddings'),1,3,'{"it":"Che cosa fa il tokenizzatore?","en":"What does the tokeniser do?"}','[{"it":"Divide il testo in token e li numera","en":"Splits text into tokens and numbers them"},{"it":"Traduce il testo in inglese prima del modello","en":"Translates the text into English before the model"},{"it":"Corregge gli errori","en":"Fixes mistakes"},{"it":"Comprime il file","en":"Compresses the file"}]',0,'{"it":"Ogni token ha un id.","en":"Each token has an id."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'embeddings'),2,3,'{"it":"Che cosa produce uno strato di embedding?","en":"What does an embedding layer produce?"}','[{"it":"Un vettore per ogni token","en":"A vector per token"},{"it":"Una sola parola","en":"A single word"},{"it":"Un’immagine","en":"An image"},{"it":"Una probabilità","en":"A probability"}]',0,'{"it":"Imparato durante il training.","en":"Learned during training."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'embeddings'),3,3,'{"it":"Che cosa manca a un embedding da solo?","en":"What does an embedding alone lack?"}','[{"it":"Il contesto della frase","en":"The sentence context"},{"it":"I numeri","en":"Numbers"},{"it":"Il vocabolario","en":"The vocabulary"},{"it":"La GPU","en":"The GPU"}]',0,'{"it":"Ci pensa l’attention.","en":"Attention handles it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'attention'),1,3,'{"it":"Che cosa rappresenta la query?","en":"What does the query represent?"}','[{"it":"Che cosa cerca il token","en":"What the token is looking for"},{"it":"Il contenuto da passare","en":"The content to pass on"},{"it":"La posizione","en":"The position"},{"it":"Il vocabolario","en":"The vocabulary"}]',0,'{"it":"La key è cosa offre.","en":"The key is what it offers."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'attention'),2,3,'{"it":"Perché si divide per √d?","en":"Why divide by √d?"}','[{"it":"Per tenere stabili i valori prima della softmax","en":"To keep values stable before softmax"},{"it":"Per risparmiare memoria sulla GPU durante il calcolo","en":"To save GPU memory during computation"},{"it":"Per arrotondare","en":"To round"},{"it":"Non si divide","en":"You do not"}]',0,'{"it":"Prodotti troppo grandi saturano la softmax.","en":"Large products saturate the softmax."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'attention'),3,3,'{"it":"A che cosa servono più teste di attention?","en":"What are multiple attention heads for?"}','[{"it":"Imparare relazioni diverse in parallelo","en":"Learning different relations in parallel"},{"it":"Elaborare più lingue nello stesso momento","en":"Handling several languages at the same time"},{"it":"Usare meno GPU","en":"Using fewer GPUs"},{"it":"Leggere immagini","en":"Reading images"}]',0,'{"it":"Una guarda la sintassi, una i riferimenti…","en":"One watches syntax, one references…"}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'transformer'),1,3,'{"it":"Perché si aggiunge la posizione agli embedding?","en":"Why add position to the embeddings?"}','[{"it":"L’attention da sola non conosce l’ordine","en":"Attention alone does not know order"},{"it":"Per colorare i token","en":"To colour tokens"},{"it":"Per comprimere la frase e usare meno token","en":"To compress the sentence and use fewer tokens"},{"it":"Non si aggiunge","en":"It is not added"}]',0,'{"it":"“Cane morde uomo” ≠ “uomo morde cane”.","en":"“Dog bites man” ≠ “man bites dog”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'transformer'),2,3,'{"it":"Che cosa vede un token in un decoder-only?","en":"What does a token see in a decoder-only model?"}','[{"it":"Solo i token precedenti","en":"Only the previous tokens"},{"it":"Tutta la frase","en":"The whole sentence"},{"it":"Solo il successivo","en":"Only the next one"},{"it":"Nessun token","en":"No tokens"}]',0,'{"it":"Attention mascherata.","en":"Masked attention."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'transformer'),3,3,'{"it":"Per creare embedding di frasi è ottimo un modello…","en":"For making sentence embeddings a good model is…"}','[{"it":"Encoder, come BERT","en":"Encoder, like BERT"},{"it":"Solo decoder","en":"Decoder only"},{"it":"Convoluzionale","en":"Convolutional"},{"it":"K-means","en":"K-means"}]',0,'{"it":"Vede tutto il contesto.","en":"It sees the whole context."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'finetune'),1,3,'{"it":"Che cosa insegna bene il fine-tuning?","en":"What does fine-tuning teach well?"}','[{"it":"Uno stile o un comportamento","en":"A style or a behaviour"},{"it":"I fatti di ieri","en":"Yesterday’s facts"},{"it":"Una nuova lingua di programmazione dal nulla","en":"A new programming language from scratch"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Per i fatti c’è RAG.","en":"For facts there is RAG."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'finetune'),2,3,'{"it":"Che cosa provare prima del fine-tuning?","en":"What should you try before fine-tuning?"}','[{"it":"Prompt migliori e RAG","en":"Better prompts and RAG"},{"it":"Un modello più vecchio","en":"An older model"},{"it":"Più GPU","en":"More GPUs"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Più economici e flessibili.","en":"Cheaper and more flexible."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'finetune'),3,3,'{"it":"Che cos’è RLHF?","en":"What is RLHF?"}','[{"it":"Addestramento con feedback umano","en":"Training with human feedback"},{"it":"Un formato di file","en":"A file format"},{"it":"Un tipo di GPU","en":"A type of GPU"},{"it":"Un linguaggio","en":"A language"}]',0,'{"it":"Reinforcement learning from human feedback.","en":"Reinforcement learning from human feedback."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'lora'),1,3,'{"it":"Che cosa addestra LoRA?","en":"What does LoRA train?"}','[{"it":"Piccole matrici aggiuntive","en":"Small extra matrices"},{"it":"Tutti i parametri","en":"All parameters"},{"it":"Solo il tokenizzatore","en":"Only the tokeniser"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Il modello base resta congelato.","en":"The base model stays frozen."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'lora'),2,3,'{"it":"Che cosa fa la quantizzazione?","en":"What does quantisation do?"}','[{"it":"Usa meno bit per i pesi","en":"Uses fewer bits for weights"},{"it":"Aggiunge parametri","en":"Adds parameters"},{"it":"Traduce il modello","en":"Translates the model"},{"it":"Cifra i dati","en":"Encrypts data"}]',0,'{"it":"Meno memoria, poca perdita.","en":"Less memory, little loss."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'lora'),3,3,'{"it":"Che cos’è QLoRA?","en":"What is QLoRA?"}','[{"it":"LoRA su un modello quantizzato","en":"LoRA on a quantised model"},{"it":"Una GPU","en":"A GPU"},{"it":"Un dataset","en":"A dataset"},{"it":"Un tokenizzatore","en":"A tokeniser"}]',0,'{"it":"Fine-tuning su una sola GPU.","en":"Fine-tuning on a single GPU."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'generation'),1,3,'{"it":"Che cosa fa il top-p (nucleus sampling)?","en":"What does top-p (nucleus sampling) do?"}','[{"it":"Sceglie sempre il token più probabile","en":"It always picks the most likely token"},{"it":"Raddoppia la probabilità dei token rari","en":"It doubles the probability of rare tokens"},{"it":"Tiene i token più probabili fino a raggiungere la probabilità p","en":"It keeps the most likely tokens up to probability p"},{"it":"Limita la lunghezza della risposta","en":"It limits the answer length"}]',2,'{"it":"Taglia la coda improbabile.","en":"It cuts the unlikely tail."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'generation'),2,3,'{"it":"Che cosa conserva la KV cache?","en":"What does the KV cache store?"}','[{"it":"Key e value dei token già elaborati","en":"Keys and values of tokens already processed"},{"it":"Le risposte date agli altri utenti","en":"Answers given to other users"},{"it":"I pesi del modello compressi","en":"The model’s compressed weights"},{"it":"Il vocabolario del tokenizzatore","en":"The tokeniser’s vocabulary"}]',0,'{"it":"Così non si ricalcolano a ogni passo.","en":"So they are not recomputed each step."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'generation'),3,3,'{"it":"Che cosa caratterizza un modello mixture of experts?","en":"What characterises a mixture-of-experts model?"}','[{"it":"Usa sempre tutti i parametri per ogni token","en":"It always uses all parameters for every token"},{"it":"Attiva solo alcuni esperti per ogni token","en":"It activates only some experts for each token"},{"it":"È composto da più modelli indipendenti in chat tra loro","en":"It is made of several independent models chatting"},{"it":"Non ha strati di attention","en":"It has no attention layers"}]',1,'{"it":"Tanti parametri, pochi attivi alla volta.","en":"Many parameters, few active at a time."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'alignment'),1,3,'{"it":"Che cosa impara il modello di ricompensa nell’RLHF?","en":"What does the reward model learn in RLHF?"}','[{"it":"A generare risposte al posto dell’LLM","en":"To generate answers instead of the LLM"},{"it":"A tradurre le domande degli utenti","en":"To translate users’ questions"},{"it":"A comprimere i pesi del modello","en":"To compress the model’s weights"},{"it":"A prevedere quale risposta preferirebbero le persone","en":"To predict which answer people would prefer"}]',3,'{"it":"Imita i giudizi umani.","en":"It mimics human judgements."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'alignment'),2,3,'{"it":"Che cosa evita la DPO rispetto all’RLHF classico?","en":"What does DPO avoid compared with classic RLHF?"}','[{"it":"Il modello di ricompensa separato e il ciclo di rinforzo","en":"The separate reward model and the reinforcement loop"},{"it":"L’uso di coppie di risposte","en":"The use of answer pairs"},{"it":"Il fine-tuning su istruzioni","en":"Instruction fine-tuning"},{"it":"Il tokenizzatore","en":"The tokeniser"}]',0,'{"it":"Impara direttamente dalle preferenze.","en":"It learns directly from preferences."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'alignment'),3,3,'{"it":"Che campi ha un esempio di preferenza per la DPO?","en":"Which fields does a DPO preference example have?"}','[{"it":"domanda, risposta, voto da 1 a 10","en":"question, answer, score from 1 to 10"},{"it":"prompt, chosen, rejected","en":"prompt, chosen, rejected"},{"it":"input, output, etichetta","en":"input, output, label"},{"it":"testo, immagine, didascalia","en":"text, image, caption"}]',1,'{"it":"Una risposta scelta e una scartata.","en":"One chosen answer and one rejected."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'diffusion'),1,3,'{"it":"Che cosa impara a prevedere una rete di diffusione in addestramento?","en":"What does a diffusion network learn to predict in training?"}','[{"it":"La didascalia dell’immagine","en":"The image caption"},{"it":"Il colore medio dell’immagine","en":"The image’s average colour"},{"it":"Il pixel successivo, uno alla volta","en":"The next pixel, one at a time"},{"it":"Il rumore aggiunto all’immagine","en":"The noise added to the image"}]',3,'{"it":"Togliere il rumore previsto ripulisce l’immagine.","en":"Removing the predicted noise cleans the image."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'diffusion'),2,3,'{"it":"Che vantaggio ha la diffusione latente?","en":"What advantage does latent diffusion have?"}','[{"it":"Lavora in uno spazio compresso e costa meno calcolo","en":"It works in a compressed space and costs less compute"},{"it":"Non ha bisogno di un prompt","en":"It needs no prompt"},{"it":"Genera immagini senza rumore iniziale","en":"It generates images without initial noise"},{"it":"Funziona solo in bianco e nero","en":"It only works in black and white"}]',0,'{"it":"Un decodificatore torna ai pixel alla fine.","en":"A decoder returns to pixels at the end."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'dl-advanced' AND slug = 'diffusion'),3,3,'{"it":"Che cosa succede con un `guidance_scale` troppo alto?","en":"What happens with a `guidance_scale` that is too high?"}','[{"it":"Il prompt viene ignorato del tutto","en":"The prompt is ignored entirely"},{"it":"L’immagine segue troppo il prompt e diventa innaturale","en":"The image follows the prompt too hard and looks unnatural"},{"it":"La generazione diventa istantanea","en":"Generation becomes instant"},{"it":"L’immagine esce più piccola","en":"The image comes out smaller"}]',1,'{"it":"Serve un equilibrio.","en":"Balance is needed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'why'),1,3,'{"it":"Che cosa fa la “R” di RAG?","en":"What does the “R” in RAG do?"}','[{"it":"Cerca i passaggi rilevanti","en":"Retrieves the relevant passages"},{"it":"Riaddestra il modello","en":"Retrains the model"},{"it":"Riavvia il server","en":"Restarts the server"},{"it":"Riduce il prompt","en":"Reduces the prompt"}]',0,'{"it":"Retrieval.","en":"Retrieval."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'why'),2,3,'{"it":"Qual è un vantaggio di RAG sul fine-tuning per i fatti?","en":"What is an advantage of RAG over fine-tuning for facts?"}','[{"it":"Si aggiorna cambiando i documenti","en":"It updates by changing documents"},{"it":"Non serve nessun documento","en":"No documents needed"},{"it":"Costa sempre di più","en":"It always costs more"},{"it":"Rende il modello più grande","en":"It makes the model bigger"}]',0,'{"it":"Niente riaddestramento.","en":"No retraining."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'why'),3,3,'{"it":"Quando si può fare a meno della ricerca?","en":"When can you skip retrieval?"}','[{"it":"Se i documenti stanno tutti nel contesto","en":"If all documents fit in the context"},{"it":"Mai","en":"Never"},{"it":"Se i documenti sono milioni","en":"If there are millions of documents"},{"it":"Se il modello è piccolo","en":"If the model is small"}]',0,'{"it":"La soluzione più semplice prima.","en":"Simplest solution first."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'chunking'),1,3,'{"it":"Perché aggiungere sovrapposizione tra blocchi?","en":"Why add overlap between chunks?"}','[{"it":"Per non spezzare un concetto a metà","en":"To avoid cutting a concept in half"},{"it":"Per occupare più spazio","en":"To use more space"},{"it":"Per confondere la ricerca","en":"To confuse search"},{"it":"Non serve","en":"It is useless"}]',0,'{"it":"Il contesto attraversa il taglio.","en":"Context crosses the cut."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'chunking'),2,3,'{"it":"Qual è il modo migliore di dividere un manuale?","en":"What is the best way to split a manual?"}','[{"it":"Per titoli e paragrafi","en":"By headings and paragraphs"},{"it":"Ogni 10 caratteri","en":"Every 10 characters"},{"it":"A caso","en":"At random"},{"it":"Un blocco unico gigante","en":"One giant chunk"}]',0,'{"it":"Segui la struttura.","en":"Follow the structure."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'chunking'),3,3,'{"it":"A che cosa servono i metadati?","en":"What is metadata for?"}','[{"it":"Filtrare e citare le fonti","en":"Filtering and citing sources"},{"it":"Colorare il testo","en":"Colouring text"},{"it":"Aumentare i token","en":"Increasing tokens"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Documento, pagina, data.","en":"Document, page, date."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'vectors'),1,3,'{"it":"Che cosa misura `<=>` in pgvector?","en":"What does `<=>` measure in pgvector?"}','[{"it":"La distanza del coseno","en":"Cosine distance"},{"it":"L’uguaglianza esatta","en":"Exact equality"},{"it":"La lunghezza del testo","en":"Text length"},{"it":"La data","en":"The date"}]',0,'{"it":"Più piccola, più simile.","en":"Smaller, more similar."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'vectors'),2,3,'{"it":"A che cosa serve l’indice HNSW?","en":"What is the HNSW index for?"}','[{"it":"Ricerca veloce dei vettori vicini","en":"Fast nearest-vector search"},{"it":"Ordinare per data","en":"Sorting by date"},{"it":"Cifrare i dati","en":"Encrypting data"},{"it":"Comprimere il testo","en":"Compressing text"}]',0,'{"it":"Approssimata ma rapidissima.","en":"Approximate but very fast."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'vectors'),3,3,'{"it":"Che cos’è la ricerca ibrida?","en":"What is hybrid search?"}','[{"it":"Vettori più parole chiave","en":"Vectors plus keywords"},{"it":"Ricerca su due server","en":"Search on two servers"},{"it":"Ricerca a voce","en":"Voice search"},{"it":"Ricerca senza indice","en":"Search without an index"}]',0,'{"it":"Trova anche codici e nomi esatti.","en":"It also finds exact codes and names."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'prompt'),1,3,'{"it":"Che cosa deve fare il modello se la risposta non è nei documenti?","en":"What should the model do if the answer is not in the documents?"}','[{"it":"Dirlo chiaramente","en":"Say so clearly"},{"it":"Inventarla","en":"Make it up"},{"it":"Rispondere a un’altra domanda","en":"Answer another question"},{"it":"Non rispondere mai più","en":"Never answer again"}]',0,'{"it":"Meglio “non lo so” che un’invenzione.","en":"Better “I don’t know” than a fabrication."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'prompt'),2,3,'{"it":"Perché indicare la fonte di ogni blocco?","en":"Why give each chunk’s source?"}','[{"it":"Per poter citare e verificare","en":"To be able to cite and verify"},{"it":"Per allungare il prompt","en":"To lengthen the prompt"},{"it":"Per il copyright del modello","en":"For the model’s copyright"},{"it":"Non serve","en":"It is not needed"}]',0,'{"it":"L’utente può controllare.","en":"The user can check."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'prompt'),3,3,'{"it":"Che cosa succede con troppi blocchi poco pertinenti?","en":"What happens with too many barely relevant chunks?"}','[{"it":"Il modello si confonde e si spende di più","en":"The model gets confused and costs rise"},{"it":"La risposta migliora sempre","en":"The answer always improves"},{"it":"Niente","en":"Nothing"},{"it":"Il database si cancella","en":"The database is deleted"}]',0,'{"it":"Qualità prima della quantità.","en":"Quality over quantity."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'evaluate'),1,3,'{"it":"Quali sono i due punti di errore di RAG?","en":"What are RAG’s two failure points?"}','[{"it":"Ricerca e generazione","en":"Retrieval and generation"},{"it":"Tastiera e mouse","en":"Keyboard and mouse"},{"it":"Server e client","en":"Server and client"},{"it":"Token e byte","en":"Tokens and bytes"}]',0,'{"it":"Vanno valutati separatamente.","en":"They must be evaluated separately."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'evaluate'),2,3,'{"it":"Che cosa fa un reranker?","en":"What does a reranker do?"}','[{"it":"Riordina i risultati con un modello più preciso","en":"Reorders results with a more precise model"},{"it":"Cancella i documenti","en":"Deletes documents"},{"it":"Traduce la domanda","en":"Translates the question"},{"it":"Aumenta il numero di blocchi passati al modello","en":"Increases the number of chunks passed to the model"}]',0,'{"it":"Prima ampio, poi preciso.","en":"Broad first, then precise."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'evaluate'),3,3,'{"it":"Che cosa significa risposta “fedele”?","en":"What does a “faithful” answer mean?"}','[{"it":"Basata solo sui documenti","en":"Based only on the documents"},{"it":"Molto lunga","en":"Very long"},{"it":"Scritta in rima","en":"Written in rhyme"},{"it":"Data velocemente","en":"Given quickly"}]',0,'{"it":"Niente aggiunte inventate.","en":"No invented additions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'hybrid'),1,3,'{"it":"In che cosa è più forte la ricerca per parole chiave?","en":"What is keyword search better at?"}','[{"it":"Capire sinonimi e parafrasi","en":"Understanding synonyms and paraphrases"},{"it":"Tradurre la domanda in altre lingue","en":"Translating the question into other languages"},{"it":"Riassumere i documenti trovati","en":"Summarising the documents found"},{"it":"Trovare codici, sigle e nomi esatti","en":"Finding exact codes, acronyms and names"}]',3,'{"it":"I vettori capiscono il senso, le parole chiave la lettera.","en":"Vectors grasp the sense, keywords the letter."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'hybrid'),2,3,'{"it":"Come assegna i punti la Reciprocal Rank Fusion?","en":"How does Reciprocal Rank Fusion assign points?"}','[{"it":"In base alla posizione in ciascuna classifica","en":"Based on position in each ranking"},{"it":"In base alla lunghezza del documento","en":"Based on document length"},{"it":"In base alla data del documento","en":"Based on document date"},{"it":"A caso, poi si fa la media","en":"At random, then averaged"}]',0,'{"it":"1 / (k + posizione).","en":"1 / (k + position)."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'hybrid'),3,3,'{"it":"Perché il reranker si usa solo sui primi candidati?","en":"Why is the reranker used only on the top candidates?"}','[{"it":"Perché funziona solo con 5 documenti","en":"Because it only works with 5 documents"},{"it":"È preciso ma lento: su milioni di documenti costerebbe troppo","en":"It is precise but slow: over millions of documents it would cost too much"},{"it":"Perché ignora la domanda dell’utente","en":"Because it ignores the user’s question"},{"it":"Perché i primi sono sempre già giusti","en":"Because the top ones are always already right"}]',1,'{"it":"Largo prima, fine dopo.","en":"Wide first, fine after."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'ingest'),1,3,'{"it":"Perché aggiungere titolo e sezione a ogni blocco prima dell’embedding?","en":"Why add title and section to each chunk before the embedding?"}','[{"it":"Per rendere i blocchi più corti","en":"To make chunks shorter"},{"it":"Per nascondere i blocchi agli utenti","en":"To hide chunks from users"},{"it":"Perché il database lo richiede","en":"Because the database requires it"},{"it":"Così il blocco non resta ambiguo fuori dal documento","en":"So the chunk is not ambiguous outside the document"}]',3,'{"it":"Il contesto viaggia con il blocco.","en":"The context travels with the chunk."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'ingest'),2,3,'{"it":"Come si impedisce a un utente di ricevere documenti riservati?","en":"How do you stop a user from getting confidential documents?"}','[{"it":"Filtrando per permessi nella query di ricerca","en":"Filtering by permissions in the search query"},{"it":"Scrivendo nel prompt di non mostrarli","en":"Writing in the prompt not to show them"},{"it":"Usando un modello più grande","en":"Using a bigger model"},{"it":"Mettendo i documenti in fondo al prompt","en":"Putting the documents at the end of the prompt"}]',0,'{"it":"Il prompt non è una barriera di sicurezza.","en":"The prompt is not a security barrier."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'ingest'),3,3,'{"it":"Un documento viene aggiornato. Che cosa fai con i suoi blocchi?","en":"A document is updated. What do you do with its chunks?"}','[{"it":"Aggiungi i nuovi e lasci anche i vecchi","en":"Add the new ones and keep the old ones too"},{"it":"Cancelli i vecchi blocchi e crei i nuovi","en":"Delete the old chunks and create the new ones"},{"it":"Non serve fare nulla","en":"Nothing needs doing"},{"it":"Riaddestri il modello linguistico","en":"Retrain the language model"}]',1,'{"it":"Niente risposte da versioni superate.","en":"No answers from outdated versions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'agentic'),1,3,'{"it":"Che cosa cambia nel RAG agentico rispetto a quello classico?","en":"What changes in agentic RAG compared with classic RAG?"}','[{"it":"Non si usano più i documenti","en":"Documents are no longer used"},{"it":"Il modello viene riaddestrato sui documenti","en":"The model is retrained on the documents"},{"it":"La ricerca è uno strumento che il modello usa quando e quanto serve","en":"Search is a tool the model uses when and as much as needed"},{"it":"Si cerca sempre una sola volta","en":"You always search just once"}]',2,'{"it":"Il modello guida la ricerca.","en":"The model drives the search."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'agentic'),2,3,'{"it":"Per quale domanda serve di più il RAG agentico?","en":"For which question does agentic RAG help most?"}','[{"it":"Una domanda in più passi che unisce più documenti","en":"A multi-step question joining several documents"},{"it":"“Che ore sono?”","en":"“What time is it?”"},{"it":"Una domanda la cui risposta sta in un solo blocco","en":"A question answered by a single chunk"},{"it":"Un saluto dell’utente","en":"A greeting from the user"}]',0,'{"it":"Cerca, legge, cerca ancora.","en":"It searches, reads, searches again."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'agentic'),3,3,'{"it":"Quale rischio va limitato nel RAG agentico?","en":"Which risk must be limited in agentic RAG?"}','[{"it":"Che il modello smetta di usare i documenti","en":"That the model stops using documents"},{"it":"Che il modello cerchi all’infinito, con costi alti","en":"That the model searches forever, at high cost"},{"it":"Che i documenti vengano cancellati","en":"That documents get deleted"},{"it":"Che le citazioni siano troppo precise","en":"That citations are too precise"}]',1,'{"it":"Serve un limite di ricerche.","en":"A search limit is needed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'what'),1,3,'{"it":"Chi decide i passi in un workflow?","en":"Who decides the steps in a workflow?"}','[{"it":"Il tuo codice","en":"Your code"},{"it":"Il modello","en":"The model"},{"it":"L’utente a ogni passo","en":"The user at each step"},{"it":"Nessuno","en":"Nobody"}]',0,'{"it":"Nell’agente li decide il modello.","en":"In an agent the model decides."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'what'),2,3,'{"it":"Quando ha senso un agente?","en":"When does an agent make sense?"}','[{"it":"Per compiti aperti e difficili da prevedere","en":"For open-ended, hard-to-predict tasks"},{"it":"Per tradurre una parola alla volta in modo preciso","en":"To translate one word at a time precisely"},{"it":"Sempre","en":"Always"},{"it":"Mai","en":"Never"}]',0,'{"it":"Altrimenti basta un flusso.","en":"Otherwise a workflow is enough."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'what'),3,3,'{"it":"Da dove conviene partire?","en":"Where should you start?"}','[{"it":"Dalla soluzione più semplice","en":"From the simplest solution"},{"it":"Dall’agente più complesso","en":"From the most complex agent"},{"it":"Da dieci agenti insieme","en":"From ten agents at once"},{"it":"Dal fine-tuning","en":"From fine-tuning"}]',0,'{"it":"Complessità solo se serve.","en":"Complexity only when needed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'loop'),1,3,'{"it":"Quando finisce il ciclo?","en":"When does the loop end?"}','[{"it":"Quando il modello non chiede più strumenti","en":"When the model stops asking for tools"},{"it":"Dopo un passo, sempre","en":"After one step, always"},{"it":"Mai","en":"Never"},{"it":"Quando l’utente spegne il PC","en":"When the user turns off the PC"}]',0,'{"it":"O quando scatta il limite.","en":"Or when the limit trips."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'loop'),2,3,'{"it":"Perché serve un limite di passi?","en":"Why do you need a step limit?"}','[{"it":"Per evitare cicli infiniti e spese","en":"To avoid endless loops and spending"},{"it":"Per far contento il modello","en":"To please the model"},{"it":"Non serve","en":"It is not needed"},{"it":"Per l’estetica","en":"For looks"}]',0,'{"it":"Sicurezza prima di tutto.","en":"Safety first."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'loop'),3,3,'{"it":"Come rimandi più risultati di strumenti?","en":"How do you send back several tool results?"}','[{"it":"Tutti insieme in un solo messaggio","en":"All together in one message"},{"it":"Uno per chiamata separata","en":"One per separate call"},{"it":"Non si rimandano","en":"You do not"},{"it":"Solo il primo","en":"Only the first"}]',0,'{"it":"Ognuno con il suo tool_use_id.","en":"Each with its tool_use_id."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'tools'),1,3,'{"it":"Che cosa deve dire la descrizione di uno strumento?","en":"What should a tool description say?"}','[{"it":"Cosa fa, quando usarlo, cosa restituisce","en":"What it does, when to use it, what it returns"},{"it":"Chi l’ha scritto e in quale data","en":"Who wrote it and on what date"},{"it":"Il prezzo","en":"The price"},{"it":"Niente, basta il nome","en":"Nothing, the name is enough"}]',0,'{"it":"È la guida del modello.","en":"It is the model’s guide."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'tools'),2,3,'{"it":"Perché i risultati devono essere brevi?","en":"Why should results be short?"}','[{"it":"Per non riempire il contesto","en":"So they do not fill the context"},{"it":"Per risparmiare inchiostro","en":"To save ink"},{"it":"Per sembrare eleganti","en":"To look elegant"},{"it":"Non devono","en":"They need not be"}]',0,'{"it":"Il contesto è prezioso.","en":"Context is precious."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'tools'),3,3,'{"it":"Che cosa restituire in caso di errore?","en":"What should you return on error?"}','[{"it":"Un messaggio che aiuti a correggersi","en":"A message that helps self-correction"},{"it":"Niente","en":"Nothing"},{"it":"Un codice incomprensibile","en":"An incomprehensible code"},{"it":"Lo stack trace intero","en":"The whole stack trace"}]',0,'{"it":"Il modello può riprovare meglio.","en":"The model can retry better."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'mcp'),1,3,'{"it":"Che cos’è MCP?","en":"What is MCP?"}','[{"it":"Uno standard per collegare modelli a strumenti e dati","en":"A standard to connect models to tools and data"},{"it":"Un modello linguistico creato da Anthropic per gli agenti","en":"A language model built by Anthropic for agents"},{"it":"Un linguaggio di programmazione","en":"A programming language"},{"it":"Un formato di immagine","en":"An image format"}]',0,'{"it":"Model Context Protocol.","en":"Model Context Protocol."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'mcp'),2,3,'{"it":"Che cosa espone un server MCP?","en":"What does an MCP server expose?"}','[{"it":"Strumenti, risorse e prompt","en":"Tools, resources and prompts"},{"it":"Solo immagini","en":"Only images"},{"it":"Password","en":"Passwords"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"In un formato comune.","en":"In a common format."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'mcp'),3,3,'{"it":"Che cosa controllare prima di installare un server MCP di terzi?","en":"What should you check before installing a third-party MCP server?"}','[{"it":"Chi l’ha scritto e quali permessi ottiene","en":"Who wrote it and what permissions it gets"},{"it":"Il colore del logo","en":"The logo colour"},{"it":"Niente","en":"Nothing"},{"it":"Solo il nome e il numero di download","en":"Only the name and the download count"}]',0,'{"it":"Agisce a tuo nome.","en":"It acts on your behalf."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'safety'),1,3,'{"it":"Quali azioni richiedono conferma umana?","en":"Which actions need human confirmation?"}','[{"it":"Quelle irreversibili","en":"Irreversible ones"},{"it":"Leggere un file","en":"Reading a file"},{"it":"Fare una somma","en":"Doing a sum"},{"it":"Nessuna","en":"None"}]',0,'{"it":"Inviare, pagare, cancellare.","en":"Sending, paying, deleting."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'safety'),2,3,'{"it":"Come va trattato un testo letto da una pagina web?","en":"How should text read from a web page be treated?"}','[{"it":"Come dato, mai come istruzione","en":"As data, never as instructions"},{"it":"Come un ordine del capo","en":"As an order from the boss"},{"it":"Va ignorato sempre","en":"Always ignored"},{"it":"Va eseguito","en":"Executed"}]',0,'{"it":"Può contenere prompt injection.","en":"It may contain prompt injection."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'safety'),3,3,'{"it":"Perché eseguire più volte la valutazione di un agente?","en":"Why run an agent’s evaluation several times?"}','[{"it":"Il comportamento varia tra un’esecuzione e l’altra","en":"Behaviour varies from run to run"},{"it":"Per spendere di più e avere più dati","en":"To spend more and get more data"},{"it":"Non serve","en":"It is not needed"},{"it":"Per stancarlo","en":"To tire it"}]',0,'{"it":"Una sola prova può ingannare.","en":"One try can mislead."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'memory'),1,3,'{"it":"Perché un contesto pieno di dettagli vecchi è un problema anche prima del limite?","en":"Why is a context full of old details a problem even before the limit?"}','[{"it":"Perché rende il modello più economico","en":"Because it makes the model cheaper"},{"it":"Perché il modello smette di usare strumenti","en":"Because the model stops using tools"},{"it":"Non è un problema finché c’è spazio","en":"It is no problem while there is room"},{"it":"Distrae il modello e costa token","en":"It distracts the model and costs tokens"}]',3,'{"it":"Più testo non vuol dire più attenzione.","en":"More text does not mean more attention."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'memory'),2,3,'{"it":"Che cosa conviene tenere nel riassunto di una compattazione?","en":"What should a compaction summary keep?"}','[{"it":"Obiettivo, decisioni prese e cosa resta da fare","en":"Goal, decisions taken and what is left to do"},{"it":"Ogni risultato di strumento parola per parola","en":"Every tool result word for word"},{"it":"Solo l’ultimo messaggio dell’utente","en":"Only the user’s last message"},{"it":"Niente: si riparte da zero","en":"Nothing: start from scratch"}]',0,'{"it":"L’essenziale per continuare.","en":"The essentials to carry on."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'memory'),3,3,'{"it":"A che cosa serve una memoria esterna per un agente?","en":"What is an external memory for an agent?"}','[{"it":"A ingrandire la finestra di contesto del modello","en":"To enlarge the model’s context window"},{"it":"A conservare progressi e decisioni da rileggere più tardi","en":"To keep progress and decisions to reread later"},{"it":"A cancellare la storia ogni dieci messaggi","en":"To delete the history every ten messages"},{"it":"A nascondere i passi all’utente","en":"To hide the steps from the user"}]',1,'{"it":"Anche tra una sessione e l’altra.","en":"Even across sessions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'multi-agent'),1,3,'{"it":"Quando conviene un sistema multi-agente?","en":"When is a multi-agent system worth it?"}','[{"it":"Per ogni compito, anche il più semplice","en":"For every task, even the simplest"},{"it":"Quando le parti dipendono strettamente l’una dall’altra","en":"When the parts depend tightly on each other"},{"it":"Quando il lavoro si divide in parti indipendenti e parallele","en":"When the work splits into independent, parallel parts"},{"it":"Quando si vuole spendere meno token","en":"When you want to spend fewer tokens"}]',2,'{"it":"Ricerca su molte fonti, per esempio.","en":"Research over many sources, for example."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'multi-agent'),2,3,'{"it":"Perché ogni sotto-agente restituisce solo una sintesi?","en":"Why does each sub-agent return only a summary?"}','[{"it":"Per non riempire il contesto dell’orchestratore","en":"So as not to fill the orchestrator’s context"},{"it":"Perché non può leggere documenti lunghi","en":"Because it cannot read long documents"},{"it":"Per nascondere le fonti all’utente","en":"To hide the sources from the user"},{"it":"Perché lo impone il protocollo MCP","en":"Because the MCP protocol requires it"}]',0,'{"it":"Legge tanto, riporta poco.","en":"It reads a lot, reports little."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'multi-agent'),3,3,'{"it":"Qual è il costo principale di più agenti?","en":"What is the main cost of several agents?"}','[{"it":"Le risposte diventano meno precise","en":"Answers become less precise"},{"it":"Molti più token consumati","en":"Many more tokens used"},{"it":"Non si possono usare strumenti","en":"Tools cannot be used"},{"it":"Serve un modello diverso per ognuno","en":"Each needs a different model"}]',1,'{"it":"Ogni agente ha il suo contesto da pagare.","en":"Each agent has its own context to pay for."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'mcp-practice'),1,3,'{"it":"Quando si usa il trasporto stdio?","en":"When is the stdio transport used?"}','[{"it":"Per un server in rete con molti utenti","en":"For a networked server with many users"},{"it":"Per inviare email agli utenti","en":"For sending emails to users"},{"it":"Solo per i server scritti in C","en":"Only for servers written in C"},{"it":"Per un server avviato come processo locale dal client","en":"For a server launched as a local process by the client"}]',3,'{"it":"Parla da standard input e output.","en":"It talks via standard input and output."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'mcp-practice'),2,3,'{"it":"Che cosa serve a un server MCP remoto con molti utenti?","en":"What does a remote MCP server with many users need?"}','[{"it":"Un’autorizzazione, di solito con OAuth","en":"Authorisation, usually with OAuth"},{"it":"Un modello linguistico installato sul server","en":"A language model installed on the server"},{"it":"Un file GGUF","en":"A GGUF file"},{"it":"Nessuna configurazione particolare","en":"No particular configuration"}]',0,'{"it":"Sapere chi chiede che cosa.","en":"Knowing who asks for what."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-agents' AND slug = 'mcp-practice'),3,3,'{"it":"Che differenza c’è tra una risorsa e uno strumento MCP?","en":"What is the difference between an MCP resource and tool?"}','[{"it":"Nessuna, sono sinonimi","en":"None, they are synonyms"},{"it":"La risorsa è un dato da leggere, lo strumento un’azione","en":"A resource is data to read, a tool is an action"},{"it":"La risorsa costa di più","en":"A resource costs more"},{"it":"Lo strumento funziona solo in stdio","en":"A tool only works over stdio"}]',1,'{"it":"Le risorse hanno un URI.","en":"Resources have a URI."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'tracking'),1,3,'{"it":"Che cosa si traccia in un esperimento?","en":"What do you track in an experiment?"}','[{"it":"Parametri, metriche, versioni e modello","en":"Parameters, metrics, versions and model"},{"it":"Solo il nome del file del modello finale","en":"Only the file name of the final model"},{"it":"L’ora di pranzo","en":"Lunch time"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Tutto quello che serve a ripeterlo.","en":"Everything needed to repeat it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'tracking'),2,3,'{"it":"Che cos’è la riproducibilità?","en":"What is reproducibility?"}','[{"it":"Stessi dati e codice danno lo stesso modello","en":"Same data and code give the same model"},{"it":"Copiare un modello altrui per confrontarlo","en":"Copying someone else’s model to compare it"},{"it":"Stampare i risultati","en":"Printing results"},{"it":"Ridurre il dataset","en":"Shrinking the dataset"}]',0,'{"it":"La base della fiducia.","en":"The basis of trust."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'tracking'),3,3,'{"it":"Che cosa fa `mlflow.log_metric`?","en":"What does `mlflow.log_metric` do?"}','[{"it":"Salva una metrica dell’esperimento","en":"Saves an experiment metric"},{"it":"Addestra il modello","en":"Trains the model"},{"it":"Cancella il run","en":"Deletes the run"},{"it":"Scarica dati","en":"Downloads data"}]',0,'{"it":"Per confrontare i run.","en":"To compare runs."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'serving'),1,3,'{"it":"Quando va caricato il modello?","en":"When should the model be loaded?"}','[{"it":"Una volta all’avvio","en":"Once at startup"},{"it":"A ogni richiesta","en":"On every request"},{"it":"Mai","en":"Never"},{"it":"Ogni ora","en":"Every hour"}]',0,'{"it":"Caricare è lento.","en":"Loading is slow."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'serving'),2,3,'{"it":"A che cosa serve Pydantic qui?","en":"What is Pydantic for here?"}','[{"it":"Validare gli input","en":"Validating inputs"},{"it":"Addestrare","en":"Training"},{"it":"Disegnare grafici","en":"Drawing charts"},{"it":"Comprimere","en":"Compressing"}]',0,'{"it":"Tipi e campi obbligatori.","en":"Types and required fields."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'serving'),3,3,'{"it":"A che cosa serve Docker?","en":"What is Docker for?"}','[{"it":"Impacchettare il servizio con le sue dipendenze","en":"Packaging the service with its dependencies"},{"it":"Addestrare il modello più in fretta sulla GPU","en":"Training the model faster on the GPU"},{"it":"Scrivere i test","en":"Writing tests"},{"it":"Gestire le password","en":"Managing passwords"}]',0,'{"it":"Gira uguale ovunque.","en":"It runs the same everywhere."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'monitoring'),1,3,'{"it":"Che cos’è il data drift?","en":"What is data drift?"}','[{"it":"I dati in ingresso cambiano rispetto all’addestramento","en":"Input data changes compared to training"},{"it":"Un furto di dati dal server di produzione","en":"A data theft from the production server"},{"it":"Un disco pieno","en":"A full disk"},{"it":"Un errore di battitura","en":"A typo"}]',0,'{"it":"Il mondo cambia.","en":"The world changes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'monitoring'),2,3,'{"it":"Che cosa si fa quando la qualità scende?","en":"What do you do when quality drops?"}','[{"it":"Si riaddestra con dati recenti","en":"Retrain with recent data"},{"it":"Si ignora","en":"Ignore it"},{"it":"Si cancella il modello","en":"Delete the model"},{"it":"Si cambia linguaggio","en":"Change language"}]',0,'{"it":"Meglio se automatico.","en":"Better if automated."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'monitoring'),3,3,'{"it":"Che cosa verifica il test KS in questo esempio?","en":"What does the KS test check in this example?"}','[{"it":"Se due distribuzioni sono diverse","en":"Whether two distributions differ"},{"it":"La velocità del server","en":"Server speed"},{"it":"L’accuratezza","en":"Accuracy"},{"it":"Il numero di righe","en":"The row count"}]',0,'{"it":"p piccolo = probabilmente diverse.","en":"Small p = probably different."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'llm-evals'),1,3,'{"it":"Perché le app LLM servono eval automatiche?","en":"Why do LLM apps need automatic evals?"}','[{"it":"Possono peggiorare senza errori visibili","en":"They can degrade without visible errors"},{"it":"Per spendere di più","en":"To spend more"},{"it":"Perché lo impone la legge per ogni app","en":"Because the law requires it for every app"},{"it":"Non servono","en":"They do not"}]',0,'{"it":"Rotture silenziose.","en":"Silent breakage."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'llm-evals'),2,3,'{"it":"Da dove prendere i casi di test migliori?","en":"Where do the best test cases come from?"}','[{"it":"Dai problemi veri degli utenti","en":"From real user problems"},{"it":"Inventati a caso","en":"Made up at random"},{"it":"Da un altro progetto","en":"From another project"},{"it":"Dal meteo","en":"From the weather"}]',0,'{"it":"Rappresentano l’uso reale.","en":"They represent real use."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'llm-evals'),3,3,'{"it":"Perché controllare a mano un campione dei voti del giudice?","en":"Why hand-check a sample of the judge’s grades?"}','[{"it":"Anche il giudice può sbagliare","en":"The judge can be wrong too"},{"it":"Per perdere tempo","en":"To waste time"},{"it":"È obbligatorio","en":"It is mandatory"},{"it":"Non serve","en":"It is not needed"}]',0,'{"it":"Fidarsi, ma verificare.","en":"Trust, but verify."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'costs'),1,3,'{"it":"Quando conviene il batch?","en":"When is batch processing worth it?"}','[{"it":"Per lavori grandi e non urgenti","en":"For big, non-urgent jobs"},{"it":"Per la chat dal vivo","en":"For live chat"},{"it":"Mai","en":"Never"},{"it":"Per una sola domanda","en":"For a single question"}]',0,'{"it":"Spesso costa molto meno.","en":"It often costs much less."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'costs'),2,3,'{"it":"Che cosa misurare per confrontare due modelli?","en":"What should you measure to compare two models?"}','[{"it":"Il costo per compito completato","en":"Cost per completed task"},{"it":"Solo il prezzo per token","en":"Only price per token"},{"it":"Il nome","en":"The name"},{"it":"La data di uscita","en":"The release date"}]',0,'{"it":"Gli errori costano.","en":"Errors cost money."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'costs'),3,3,'{"it":"Che cosa riduce i costi di un system prompt lungo e fisso?","en":"What cuts the cost of a long, fixed system prompt?"}','[{"it":"Il prompt caching","en":"Prompt caching"},{"it":"Scriverlo due volte","en":"Writing it twice"},{"it":"Usare il maiuscolo","en":"Using capitals"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Le parti fisse si riusano.","en":"Fixed parts are reused."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'registry'),1,3,'{"it":"Perché i dati non si mettono direttamente in Git?","en":"Why is data not put directly into Git?"}','[{"it":"Perché Git non accetta file CSV","en":"Because Git does not accept CSV files"},{"it":"Perché i dati non cambiano mai","en":"Because data never changes"},{"it":"Perché i dati sono sempre segreti","en":"Because data is always secret"},{"it":"Perché sono troppo grandi: in Git va solo un’impronta","en":"Because they are too big: only a fingerprint goes in Git"}]',3,'{"it":"DVC tiene i file altrove.","en":"DVC keeps the files elsewhere."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'registry'),2,3,'{"it":"A che cosa serve l’alias “produzione” nel registro?","en":"What is the “production” alias in the registry for?"}','[{"it":"Indica quale versione del modello è in uso","en":"It marks which model version is in use"},{"it":"Cancella le versioni vecchie","en":"It deletes old versions"},{"it":"Addestra una nuova versione","en":"It trains a new version"},{"it":"Rende il modello più veloce","en":"It makes the model faster"}]',0,'{"it":"Il servizio carica sempre quell’alias.","en":"The service always loads that alias."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'registry'),3,3,'{"it":"Come si torna alla versione precedente di un modello?","en":"How do you roll back to a previous model version?"}','[{"it":"Riaddestrando da zero il modello","en":"Retraining the model from scratch"},{"it":"Spostando l’alias sulla versione precedente","en":"Moving the alias to the previous version"},{"it":"Riscrivendo il codice del servizio","en":"Rewriting the service code"},{"it":"Cancellando il registro","en":"Deleting the registry"}]',1,'{"it":"Un rollback in un comando.","en":"A rollback in one command."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'ci'),1,3,'{"it":"Quale di questi è un test dei dati?","en":"Which of these is a data test?"}','[{"it":"La funzione di pulizia restituisce una tabella","en":"The cleaning function returns a table"},{"it":"Il modello nuovo ha un F1 non inferiore","en":"The new model has no lower F1"},{"it":"Le età sono tutte tra 0 e 120","en":"Ages are all between 0 and 120"},{"it":"Il servizio risponde in meno di 200 ms","en":"The service answers in under 200 ms"}]',2,'{"it":"Controlla i valori, non il codice.","en":"It checks values, not code."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'ci'),2,3,'{"it":"Che cosa fa l’integrazione continua?","en":"What does continuous integration do?"}','[{"it":"Esegue i test da sola a ogni modifica","en":"It runs the tests on its own at every change"},{"it":"Addestra un modello ogni minuto","en":"It trains a model every minute"},{"it":"Pubblica i dati su internet","en":"It publishes the data online"},{"it":"Sostituisce la revisione del codice","en":"It replaces code review"}]',0,'{"it":"Una modifica rotta non passa.","en":"A broken change does not go through."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'ci'),3,3,'{"it":"Perché il test del modello ammette un piccolo margine (−0,01)?","en":"Why does the model test allow a small margin (−0.01)?"}','[{"it":"Per accettare sempre qualsiasi modello","en":"To always accept any model"},{"it":"Per evitare blocchi dovuti a piccole oscillazioni casuali","en":"To avoid blocks due to small random fluctuations"},{"it":"Perché F1 non si può confrontare","en":"Because F1 cannot be compared"},{"it":"Per far peggiorare il modello apposta","en":"To make the model worse on purpose"}]',1,'{"it":"Rumore, non peggioramento reale.","en":"Noise, not real decline."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'rollout'),1,3,'{"it":"Che cosa succede in modalità shadow?","en":"What happens in shadow mode?"}','[{"it":"Il nuovo modello sostituisce subito il vecchio","en":"The new model replaces the old one at once"},{"it":"Il nuovo modello serve il 50% degli utenti","en":"The new model serves 50% of users"},{"it":"Il vecchio modello viene spento","en":"The old model is switched off"},{"it":"Il nuovo modello risponde ma le risposte non vengono mostrate","en":"The new model answers but its answers are not shown"}]',3,'{"it":"Si confronta senza rischio.","en":"You compare at no risk."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'rollout'),2,3,'{"it":"Perché assegnare un utente sempre allo stesso gruppo?","en":"Why always assign a user to the same group?"}','[{"it":"Per non mescolare i risultati delle due versioni","en":"So as not to mix the two versions’ results"},{"it":"Per risparmiare memoria sul server","en":"To save server memory"},{"it":"Perché lo impone il registro dei modelli","en":"Because the model registry requires it"},{"it":"Non serve: conviene cambiare a ogni richiesta","en":"No need: better switch on every request"}]',0,'{"it":"Esperienza coerente, misura pulita.","en":"Consistent experience, clean measurement."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mlops' AND slug = 'rollout'),3,3,'{"it":"Le metriche del gruppo canary peggiorano. Che cosa fai?","en":"The canary group’s metrics worsen. What do you do?"}','[{"it":"Allarghi il rilascio a tutti","en":"Widen the release to everyone"},{"it":"Rollback alla versione precedente","en":"Roll back to the previous version"},{"it":"Aspetti qualche mese senza fare nulla","en":"Wait a few months doing nothing"},{"it":"Spegni il monitoraggio","en":"Switch off monitoring"}]',1,'{"it":"Il canary serve proprio a questo.","en":"That is exactly what the canary is for."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'why'),1,3,'{"it":"Qual è il vantaggio principale dei modelli locali per la privacy?","en":"What is local models’ main privacy advantage?"}','[{"it":"I dati non escono dal computer","en":"Data never leaves the computer"},{"it":"Sono sempre più intelligenti","en":"They are always smarter"},{"it":"Non servono pesi","en":"No weights are needed"},{"it":"Hanno più token","en":"They have more tokens"}]',0,'{"it":"Niente invio a terzi.","en":"Nothing sent to third parties."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'why'),2,3,'{"it":"Che cosa significa open-weight?","en":"What does open-weight mean?"}','[{"it":"I pesi del modello sono scaricabili","en":"The model weights are downloadable"},{"it":"Il modello pesa poco","en":"The model is light"},{"it":"Tutto è open source","en":"Everything is open source"},{"it":"È gratis in cloud","en":"It is free in the cloud"}]',0,'{"it":"Ma non sempre dati e codice.","en":"But not always data and code."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'why'),3,3,'{"it":"Un limite dei modelli su portatile è…","en":"A limit of laptop models is…"}','[{"it":"Sono in genere meno capaci dei migliori in cloud","en":"They are generally less capable than the best cloud ones"},{"it":"Non funzionano offline","en":"They do not work offline"},{"it":"Mandano comunque i dati in rete al produttore","en":"They still send data online to the maker"},{"it":"Costano per token","en":"They cost per token"}]',0,'{"it":"Dipende dalla memoria disponibile.","en":"It depends on available memory."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'ollama'),1,3,'{"it":"Quale comando scarica un modello?","en":"Which command downloads a model?"}','[{"it":"ollama pull","en":"ollama pull"},{"it":"ollama get","en":"ollama get"},{"it":"ollama download","en":"ollama download"},{"it":"ollama fetch","en":"ollama fetch"}]',0,'{"it":"`run` lo scarica anche se manca.","en":"`run` also downloads it if missing."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'ollama'),2,3,'{"it":"Su quale porta risponde il server di Ollama?","en":"Which port does the Ollama server answer on?"}','[{"it":"11434","en":"11434"},{"it":"80","en":"80"},{"it":"3306","en":"3306"},{"it":"8080","en":"8080"}]',0,'{"it":"localhost:11434.","en":"localhost:11434."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'ollama'),3,3,'{"it":"A che cosa serve l’API compatibile OpenAI?","en":"What is the OpenAI-compatible API for?"}','[{"it":"Usare strumenti esistenti con un modello locale","en":"Using existing tools with a local model"},{"it":"Pagare meno OpenAI","en":"Paying OpenAI less"},{"it":"Scaricare i pesi dei modelli GPT di OpenAI","en":"Downloading the weights of OpenAI’s GPT models"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Cambi solo l’indirizzo.","en":"You only change the address."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'gguf'),1,3,'{"it":"Che cosa contiene un file GGUF?","en":"What does a GGUF file contain?"}','[{"it":"Pesi quantizzati e dati del tokenizzatore","en":"Quantised weights and tokeniser data"},{"it":"Solo il codice sorgente del modello in C++","en":"Only the model’s C++ source code"},{"it":"Un video","en":"A video"},{"it":"Le chat degli utenti","en":"Users’ chats"}]',0,'{"it":"Tutto in un file.","en":"All in one file."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'gguf'),2,3,'{"it":"Che cosa indica “7B”?","en":"What does “7B” mean?"}','[{"it":"7 miliardi di parametri","en":"7 billion parameters"},{"it":"7 byte","en":"7 bytes"},{"it":"Versione 7 beta","en":"Version 7 beta"},{"it":"7 lingue","en":"7 languages"}]',0,'{"it":"B = billion.","en":"B = billion."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'gguf'),3,3,'{"it":"Per conversare, quale variante scegli?","en":"To chat, which variant do you pick?"}','[{"it":"Instruct","en":"Instruct"},{"it":"Base","en":"Base"},{"it":"Q8","en":"Q8"},{"it":"Qualsiasi senza differenze","en":"Any, no difference"}]',0,'{"it":"Il base completa testo, non segue istruzioni.","en":"Base completes text, it does not follow instructions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'hardware'),1,3,'{"it":"Quanta memoria serve per un modello da 8B a 4 bit, circa?","en":"About how much memory does an 8B model at 4 bits need?"}','[{"it":"4 GB","en":"4 GB"},{"it":"32 GB","en":"32 GB"},{"it":"0,5 GB","en":"0,5 GB"},{"it":"64 GB","en":"64 GB"}]',0,'{"it":"8 × 4 / 8 = 4.","en":"8 × 4 / 8 = 4."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'hardware'),2,3,'{"it":"Quale memoria conta di più?","en":"Which memory matters most?"}','[{"it":"Quella della GPU o la memoria unificata","en":"GPU memory or unified memory"},{"it":"Lo spazio su disco","en":"Disk space"},{"it":"La cache del browser","en":"Browser cache"},{"it":"La RAM della stampante","en":"The printer’s RAM"}]',0,'{"it":"Il modello deve starci dentro.","en":"The model must fit in it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'hardware'),3,3,'{"it":"Un contesto più lungo…","en":"A longer context…"}','[{"it":"Richiede più memoria","en":"Needs more memory"},{"it":"Libera memoria","en":"Frees memory"},{"it":"Non cambia niente","en":"Changes nothing"},{"it":"Rende il modello più piccolo","en":"Makes the model smaller"}]',0,'{"it":"Va messo in conto un margine.","en":"Plan for a margin."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'code'),1,3,'{"it":"Perché leggere la licenza di un modello aperto?","en":"Why read an open model’s licence?"}','[{"it":"Può avere condizioni sull’uso commerciale","en":"It may have conditions on commercial use"},{"it":"Per sapere il colore","en":"To know the colour"},{"it":"Non serve","en":"It is not needed"},{"it":"Serve solo per sapere come installarlo","en":"It only tells you how to install it"}]',0,'{"it":"Non tutte sono uguali.","en":"They are not all alike."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'code'),2,3,'{"it":"Dove risponde il modello locale nell’esempio?","en":"Where does the local model answer in the example?"}','[{"it":"localhost:11434","en":"localhost:11434"},{"it":"api.openai.com","en":"api.openai.com"},{"it":"Nel browser","en":"In the browser"},{"it":"Su un server remoto","en":"On a remote server"}]',0,'{"it":"Sul tuo computer.","en":"On your computer."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'code'),3,3,'{"it":"Che rischio c’è a esporre la porta su internet?","en":"What is the risk of exposing the port to the internet?"}','[{"it":"Chiunque può usare il tuo modello e hardware","en":"Anyone can use your model and hardware"},{"it":"Nessuno","en":"None"},{"it":"Il modello diventa più veloce","en":"The model gets faster"},{"it":"Si cancellano i pesi","en":"The weights get deleted"}]',0,'{"it":"Proteggi o lascia locale.","en":"Protect it or keep it local."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'modelfile'),1,3,'{"it":"Che cosa fa un Modelfile?","en":"What does a Modelfile do?"}','[{"it":"Riaddestra il modello sui tuoi dati","en":"It retrains the model on your data"},{"it":"Scarica un modello più grande","en":"It downloads a larger model"},{"it":"Converte il modello in formato GGUF","en":"It converts the model to GGUF format"},{"it":"Crea un modello configurato a partire da uno esistente","en":"It creates a configured model from an existing one"}]',3,'{"it":"System prompt e parametri, niente addestramento.","en":"System prompt and parameters, no training."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'modelfile'),2,3,'{"it":"Che cosa regola `num_ctx`?","en":"What does `num_ctx` set?"}','[{"it":"La lunghezza del contesto in token","en":"The context length in tokens"},{"it":"Il numero di utenti contemporanei","en":"The number of concurrent users"},{"it":"La temperatura delle risposte","en":"The answers’ temperature"},{"it":"Il numero di core della CPU","en":"The number of CPU cores"}]',0,'{"it":"Più contesto, più memoria.","en":"More context, more memory."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'modelfile'),3,3,'{"it":"Quale comando crea il modello dal Modelfile?","en":"Which command creates the model from the Modelfile?"}','[{"it":"ollama build assistente","en":"ollama build assistente"},{"it":"ollama create assistente -f Modelfile","en":"ollama create assistente -f Modelfile"},{"it":"ollama pull Modelfile","en":"ollama pull Modelfile"},{"it":"ollama run -f Modelfile","en":"ollama run -f Modelfile"}]',1,'{"it":"Poi lo avvii con `ollama run`.","en":"Then you start it with `ollama run`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'servers'),1,3,'{"it":"Che cosa basta cambiare per usare un modello locale con un client compatibile OpenAI?","en":"What do you need to change to use a local model with an OpenAI-compatible client?"}','[{"it":"Tutto il codice dell’applicazione","en":"All the application code"},{"it":"Il linguaggio di programmazione","en":"The programming language"},{"it":"Il formato dei messaggi","en":"The message format"},{"it":"L’indirizzo di base del server","en":"The server’s base address"}]',3,'{"it":"Il resto del codice resta uguale.","en":"The rest of the code stays the same."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'servers'),2,3,'{"it":"Per un servizio con molti utenti insieme, quale motore è più adatto?","en":"For a service with many simultaneous users, which engine fits best?"}','[{"it":"vLLM, con il batching continuo","en":"vLLM, with continuous batching"},{"it":"Un foglio di calcolo condiviso","en":"A shared spreadsheet"},{"it":"Il terminale di Ollama in chat","en":"Ollama’s terminal chat"},{"it":"Un file GGUF aperto a mano","en":"A GGUF file opened by hand"}]',0,'{"it":"Pensato per il traffico.","en":"Built for traffic."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'servers'),3,3,'{"it":"Che cos’è LM Studio?","en":"What is LM Studio?"}','[{"it":"Un servizio cloud a pagamento","en":"A paid cloud service"},{"it":"Un’app con interfaccia grafica per modelli locali","en":"An app with a graphical interface for local models"},{"it":"Un formato di file per i pesi","en":"A file format for weights"},{"it":"Una licenza open source","en":"An open-source licence"}]',1,'{"it":"Anche lei offre un’API compatibile.","en":"It also offers a compatible API."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'local-rag'),1,3,'{"it":"Su quale endpoint Ollama calcola gli embedding?","en":"On which endpoint does Ollama compute embeddings?"}','[{"it":"/api/chat","en":"/api/chat"},{"it":"/api/pull","en":"/api/pull"},{"it":"/api/embed","en":"/api/embed"},{"it":"/api/tags","en":"/api/tags"}]',2,'{"it":"Restituisce il campo `embeddings`.","en":"It returns the `embeddings` field."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'local-llm' AND slug = 'local-rag'),2,3,'{"it":"Perché usare lo stesso modello di embedding per documenti e domande?","en":"Why use the same embedding model for documents and questions?"}','[{"it":"I vettori di modelli diversi non sono confrontabili","en":"Vectors from different models are not comparable"},{"it":"Perché Ollama ne carica solo uno","en":"Because Ollama loads only one"},{"it":"Per risparmiare spazio su disco","en":"To save disk space"},{"it":"Non serve: qualsiasi modello va bene","en":"No need: any model will do"}]',0,'{"it":"Spazi diversi, distanze senza senso.","en":"Different spaces, meaningless distances."}',NULL);
