INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'mistral' AND slug = 'work'),2,2,'{"it":"Che cosa conviene scrivere in un incarico per l’agente?","en":"What should an assignment for the agent include?"}','[{"it":"Solo il titolo del compito","en":"Only the task title"},{"it":"La password delle app collegate","en":"The connected apps’ password"},{"it":"Obiettivo, fonti, formato e azioni vietate","en":"Goal, sources, format and forbidden actions"},{"it":"Il nome del modello da usare","en":"The name of the model to use"}]',2,'{"it":"Più chiaro è l’incarico, meno sorprese.","en":"The clearer the assignment, the fewer surprises."}',NULL);
