INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'lumo' AND slug = 'intro'),2,1,'{"it":"Qual è l’idea centrale di Lumo?","en":"What is Lumo’s core idea?"}','[{"it":"La privacy","en":"Privacy"},{"it":"La pubblicità mirata","en":"Targeted ads"},{"it":"I videogiochi","en":"Video games"},{"it":"La generazione di video","en":"Video generation"}]',0,'{"it":"Niente addestramento né pubblicità con le chat.","en":"No training or ads from chats."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'lumo' AND slug = 'intro'),3,1,'{"it":"Su quali modelli si basa Lumo?","en":"Which models does Lumo rely on?"}','[{"it":"Modelli open source","en":"Open-source models"},{"it":"Solo GPT","en":"Only GPT"},{"it":"Nessun modello","en":"No model"},{"it":"Modelli segreti di Proton Mail","en":"Secret Proton Mail models"}]',0,'{"it":"Eseguiti sui server di Proton.","en":"Run on Proton’s servers."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'lumo' AND slug = 'privacy'),1,1,'{"it":"Che cosa significa cifratura ad accesso zero?","en":"What does zero-access encryption mean?"}','[{"it":"Le chat salvate sono illeggibili anche per Proton","en":"Saved chats are unreadable even to Proton"},{"it":"Nessuno può accedere a Lumo senza un invito","en":"Nobody can access Lumo without an invitation"},{"it":"Non serve una password","en":"No password is needed"},{"it":"Lumo funziona offline","en":"Lumo works offline"}]',0,'{"it":"La chiave è legata al tuo account.","en":"The key is tied to your account."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'lumo' AND slug = 'privacy'),2,1,'{"it":"Che cosa fa la modalità fantasma?","en":"What does ghost mode do?"}','[{"it":"Le chat spariscono quando le chiudi","en":"Chats vanish when you close them"},{"it":"Nasconde l’app dal telefono","en":"Hides the app from the phone"},{"it":"Cambia la voce","en":"Changes the voice"},{"it":"Disattiva il modello","en":"Turns off the model"}]',0,'{"it":"Nessuna cronologia.","en":"No history."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'lumo' AND slug = 'privacy'),3,1,'{"it":"Il modello deve comunque leggere la domanda per rispondere?","en":"Must the model still read the question to answer?"}','[{"it":"Sì, la elabora sul server","en":"Yes, it processes it on the server"},{"it":"No, mai","en":"No, never"},{"it":"Solo il lunedì","en":"Only on Mondays"},{"it":"Solo se è breve","en":"Only if it is short"}]',0,'{"it":"La privacy riguarda cosa succede dopo.","en":"Privacy is about what happens afterwards."}',NULL);
