INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'lumo' AND slug = 'use'),1,2,'{"it":"Per quale contenuto Lumo è particolarmente adatto?","en":"For which content is Lumo particularly suited?"}','[{"it":"Contenuti personali o riservati","en":"Personal or confidential content"},{"it":"Solo giochi","en":"Only games"},{"it":"Solo immagini pubbliche","en":"Only public images"},{"it":"Nessuno","en":"None"}]',0,'{"it":"Non finiscono nell’addestramento.","en":"They do not end up in training."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'lumo' AND slug = 'use'),2,2,'{"it":"Un limite possibile di Lumo è…","en":"A possible limit of Lumo is…"}','[{"it":"Sui compiti più difficili altri modelli possono essere più capaci","en":"On the hardest tasks other models may be more capable"},{"it":"Non funziona sul telefono, solo dal computer","en":"It does not work on phones, only on computers"},{"it":"Non capisce l’italiano","en":"It does not understand Italian"},{"it":"Pubblica le chat","en":"It publishes chats"}]',0,'{"it":"Dipende dai modelli disponibili.","en":"It depends on the models available."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'lumo' AND slug = 'use'),3,2,'{"it":"La privacy di Lumo sostituisce le regole della tua azienda?","en":"Does Lumo’s privacy replace your company’s rules?"}','[{"it":"No","en":"No"},{"it":"Sì, sempre","en":"Yes, always"},{"it":"Solo per le email","en":"Only for email"},{"it":"Solo nel fine settimana","en":"Only at weekends"}]',0,'{"it":"Le regole interne restano.","en":"Internal rules still apply."}',NULL);
