INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'lumo' AND slug = 'projects'),2,2,'{"it":"Chi controlla la memoria di un progetto?","en":"Who controls a project’s memory?"}','[{"it":"Proton, senza dirtelo","en":"Proton, without telling you"},{"it":"Nessuno, non si può cancellare","en":"Nobody, it cannot be deleted"},{"it":"Tu: la vedi, la correggi, la cancelli","en":"You: you view, correct and delete it"},{"it":"Gli altri utenti di Lumo","en":"Other Lumo users"}]',2,'{"it":"Memoria sotto il tuo controllo.","en":"Memory under your control."}',NULL);
