INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'deepseek' AND slug = 'privacy'),1,1,'{"it":"Dove conserva i dati il servizio online di DeepSeek, secondo la sua informativa?","en":"Where does DeepSeek’s online service store data, according to its policy?"}','[{"it":"Su server in Cina","en":"On servers in China"},{"it":"Solo sul tuo telefono","en":"Only on your phone"},{"it":"In Svizzera","en":"In Switzerland"},{"it":"Da nessuna parte","en":"Nowhere"}]',0,'{"it":"Lo dice l’informativa sulla privacy.","en":"The privacy policy says so."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'deepseek' AND slug = 'privacy'),2,1,'{"it":"Che cosa ha fatto il Garante italiano a inizio 2025?","en":"What did the Italian Garante do in early 2025?"}','[{"it":"Ha bloccato il trattamento dei dati degli utenti italiani","en":"Blocked the processing of Italian users’ data"},{"it":"Ha premiato l’app come la più sicura dell’anno","en":"Awarded the app as the safest of the year"},{"it":"Niente","en":"Nothing"},{"it":"Ha comprato DeepSeek","en":"Bought DeepSeek"}]',0,'{"it":"Per dubbi sulla privacy.","en":"Over privacy concerns."}',NULL);
