INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'deepseek' AND slug = 'api'),3,2,'{"it":"Con dati riservati, che cosa conviene?","en":"With confidential data, what is advisable?"}','[{"it":"Usare i modelli aperti in locale o presso un fornitore scelto","en":"Using the open models locally or with a chosen provider"},{"it":"Inviarli comunque all’API, che è economica","en":"Send them to the API anyway, it is cheap"},{"it":"Pubblicarli","en":"Publishing them"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Tu scegli dove vanno i dati.","en":"You choose where the data goes."}',NULL);
