INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'github-copilot' AND slug = 'agent'),1,1,'{"it":"Che cosa fa la modalità agente?","en":"What does agent mode do?"}','[{"it":"Modifica più file ed esegue comandi fino a finire il compito","en":"Edits several files and runs commands until the task is done"},{"it":"Solo completamenti di una riga, più veloci","en":"Only one-line completions, but faster"},{"it":"Traduce il codice","en":"Translates code"},{"it":"Niente di diverso","en":"Nothing different"}]',0,'{"it":"Chiedendo conferma.","en":"Asking confirmation."}',NULL);
