INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-editors' AND slug = 'safety'),2,2,'{"it":"Perché verificare le dipendenze suggerite?","en":"Why verify suggested dependencies?"}','[{"it":"Possono essere inventate o malevole","en":"They may be made up or malicious"},{"it":"Per abitudine","en":"Out of habit"},{"it":"Non serve","en":"It is not needed"},{"it":"Per velocità: le dipendenze rallentano il progetto","en":"For speed: dependencies slow the project down"}]',0,'{"it":"Nomi plausibili ma falsi.","en":"Plausible but fake names."}',NULL);
