INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-editors' AND slug = 'feature'),1,3,'{"it":"Perché spezzare il lavoro in passi piccoli?","en":"Why break work into small steps?"}','[{"it":"Ogni passo si verifica e si rivede facilmente","en":"Each step is easy to check and review"},{"it":"Per usare più token","en":"To use more tokens"},{"it":"Perché l’agente non sa fare di più","en":"Because the agent cannot do more"},{"it":"Non serve","en":"It is not needed"}]',0,'{"it":"Diff piccoli, revisioni vere.","en":"Small diffs, real reviews."}',NULL);
