INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-editors' AND slug = 'feature'),3,3,'{"it":"L’agente gira in tondo: che fai?","en":"The agent goes in circles: what do you do?"}','[{"it":"Lo fermi e dai più contesto","en":"Stop it and give more context"},{"it":"Aspetti per ore","en":"Wait for hours"},{"it":"Gli dai più permessi","en":"Give it more permissions"},{"it":"Accetti tutto","en":"Accept everything"}]',0,'{"it":"Riformulare aiuta.","en":"Rephrasing helps."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-editors' AND slug = 'parallel'),1,3,'{"it":"Perché ogni agente in parallelo dovrebbe avere il suo worktree?","en":"Why should each parallel agent have its own worktree?"}','[{"it":"Per usare meno disco","en":"To use less disk space"},{"it":"Perché le modifiche non si mescolino","en":"So that changes do not get mixed up"},{"it":"Perché git lo impone sempre","en":"Because git always requires it"},{"it":"Per avere più token gratis","en":"To get more free tokens"}]',1,'{"it":"Una cartella e un branch per agente.","en":"One folder and one branch per agent."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-editors' AND slug = 'parallel'),2,3,'{"it":"Che cosa consegna di solito un agente nel cloud?","en":"What does a cloud agent usually deliver?"}','[{"it":"Un merge diretto su main","en":"A direct merge to main"},{"it":"Un’email con il codice incollato","en":"An email with pasted code"},{"it":"Un file ZIP da scaricare","en":"A ZIP file to download"},{"it":"Una pull request da rivedere","en":"A pull request to review"}]',3,'{"it":"La revisione resta tua.","en":"Review stays yours."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-editors' AND slug = 'parallel'),3,3,'{"it":"Quanti agenti conviene avviare insieme?","en":"How many agents should you start at once?"}','[{"it":"Quanti ne riesci a rivedere davvero","en":"As many as you can really review"},{"it":"Sempre il massimo possibile","en":"Always as many as possible"},{"it":"Mai più di uno al mese","en":"Never more than one a month"},{"it":"Uno per ogni file del progetto","en":"One per project file"}]',0,'{"it":"Il collo di bottiglia è la revisione.","en":"Review is the bottleneck."}',NULL);
