INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ai-editors' AND slug = 'mcp'),3,3,'{"it":"Dove non vanno messe le chiavi di un server MCP?","en":"Where should an MCP server’s keys not go?"}','[{"it":"In una variabile d’ambiente","en":"In an environment variable"},{"it":"In un gestore di segreti","en":"In a secrets manager"},{"it":"Nel file `.env` escluso da git","en":"In the `.env` file excluded from git"},{"it":"Nel file di configurazione versionato","en":"In the versioned configuration file"}]',3,'{"it":"Chi vede il repository vedrebbe la chiave.","en":"Anyone seeing the repository would see the key."}',NULL);
