INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'huggingface' AND slug = 'datasets'),2,2,'{"it":"Come carichi un tuo file CSV?","en":"How do you load your own CSV file?"}','[{"it":"load_dataset(\\"csv\\", data_files=\\"miei.csv\\")","en":"load_dataset(\\"csv\\", data_files=\\"miei.csv\\")"},{"it":"datasets.open(\\"miei.csv\\").to_dataset()","en":"datasets.open(\\"miei.csv\\").to_dataset()"},{"it":"pipeline(\\"csv\\")","en":"pipeline(\\"csv\\")"},{"it":"Dataset.csv()","en":"Dataset.csv()"}]',0,'{"it":"Stessa libreria.","en":"Same library."}',NULL);
