INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'huggingface' AND slug = 'spaces'),1,2,'{"it":"Che cosa fa Gradio?","en":"What does Gradio do?"}','[{"it":"Crea un’interfaccia web da una funzione Python","en":"Creates a web interface from a Python function"},{"it":"Addestra modelli direttamente nel browser","en":"Trains models directly in the browser"},{"it":"Gestisce database","en":"Manages databases"},{"it":"Invia email","en":"Sends email"}]',0,'{"it":"Poche righe.","en":"A few lines."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'huggingface' AND slug = 'spaces'),2,2,'{"it":"Quali file servono per pubblicare uno Space Gradio?","en":"Which files are needed to publish a Gradio Space?"}','[{"it":"app.py e requirements.txt","en":"app.py and requirements.txt"},{"it":"index.php","en":"index.php"},{"it":"Solo un’immagine","en":"Only an image"},{"it":"Nessuno","en":"None"}]',0,'{"it":"Il resto lo fa la piattaforma.","en":"The platform does the rest."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'huggingface' AND slug = 'spaces'),3,2,'{"it":"A che cosa servono gli Spaces?","en":"What are Spaces for?"}','[{"it":"Provare e mostrare modelli dal browser","en":"Trying and showing models from the browser"},{"it":"Salvare password e chiavi in modo sicuro","en":"Storing passwords and keys securely"},{"it":"Pagare","en":"Paying"},{"it":"Scrivere email","en":"Writing email"}]',0,'{"it":"Ottimi per un portfolio.","en":"Great for a portfolio."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'huggingface' AND slug = 'finetune'),1,3,'{"it":"Che cos’è il fine-tuning?","en":"What is fine-tuning?"}','[{"it":"Adattare un modello addestrato a un compito tuo","en":"Adapting a trained model to your task"},{"it":"Addestrare da zero","en":"Training from scratch"},{"it":"Comprimere un file","en":"Compressing a file"},{"it":"Tradurre la model card","en":"Translating the model card"}]',0,'{"it":"Parti da un modello esistente.","en":"You start from an existing model."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'huggingface' AND slug = 'finetune'),2,3,'{"it":"Perché LoRA?","en":"Why LoRA?"}','[{"it":"Allena pochi parametri, serve meno memoria","en":"Trains few parameters, needs less memory"},{"it":"Rende il modello più grande","en":"Makes the model bigger"},{"it":"Elimina i dati","en":"Removes the data"},{"it":"Serve solo per le immagini","en":"Only for images"}]',0,'{"it":"Strati piccoli aggiuntivi.","en":"Small extra layers."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'huggingface' AND slug = 'finetune'),3,3,'{"it":"Perché separare dati di valutazione?","en":"Why keep evaluation data separate?"}','[{"it":"Per misurare onestamente il modello","en":"To measure the model honestly"},{"it":"Per risparmiare spazio","en":"To save space"},{"it":"Lo chiede la licenza","en":"The licence requires it"},{"it":"Non serve","en":"It is not needed"}]',0,'{"it":"Altrimenti i numeri mentono.","en":"Otherwise the numbers lie."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'huggingface' AND slug = 'auto'),1,3,'{"it":"Che cosa fa `AutoTokenizer.from_pretrained(nome)`?","en":"What does `AutoTokenizer.from_pretrained(nome)` do?"}','[{"it":"Addestra un nuovo tokenizzatore","en":"It trains a new tokeniser"},{"it":"Scarica i pesi del modello","en":"It downloads the model weights"},{"it":"Traduce il testo in inglese","en":"It translates text into English"},{"it":"Carica il tokenizzatore giusto per quel modello","en":"It loads the right tokeniser for that model"}]',3,'{"it":"Ogni modello ha il suo vocabolario.","en":"Each model has its own vocabulary."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'huggingface' AND slug = 'auto'),2,3,'{"it":"A che cosa serve `apply_chat_template`?","en":"What is `apply_chat_template` for?"}','[{"it":"A formattare i messaggi come si aspetta quel modello di chat","en":"Formatting messages the way that chat model expects"},{"it":"A tradurre i messaggi in un’altra lingua","en":"Translating messages into another language"},{"it":"A salvare la conversazione su disco","en":"Saving the conversation to disk"},{"it":"A scegliere la GPU migliore","en":"Choosing the best GPU"}]',0,'{"it":"Niente stringhe costruite a mano.","en":"No hand-built strings."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'huggingface' AND slug = 'auto'),3,3,'{"it":"Perché si tagliano i primi token dell’uscita di `generate`?","en":"Why cut the first tokens of `generate`’s output?"}','[{"it":"Perché sono sempre errori","en":"Because they are always mistakes"},{"it":"Perché contengono il prompt, non la risposta","en":"Because they hold the prompt, not the answer"},{"it":"Per ridurre il costo del modello","en":"To reduce the model’s cost"},{"it":"Perché il modello li ripete due volte","en":"Because the model repeats them twice"}]',1,'{"it":"`generate` restituisce prompt + risposta.","en":"`generate` returns prompt + answer."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'huggingface' AND slug = 'inference'),1,3,'{"it":"Che cosa permettono gli Inference Providers?","en":"What do Inference Providers allow?"}','[{"it":"Addestrare modelli gratis senza limiti","en":"Training models for free without limits"},{"it":"Scaricare i pesi più in fretta","en":"Downloading weights faster"},{"it":"Convertire i modelli in GGUF","en":"Converting models to GGUF"},{"it":"Chiamare modelli dell’Hub via API, pagando a consumo","en":"Calling Hub models via API, paying per use"}]',3,'{"it":"Niente GPU tua.","en":"No GPU of your own."}',NULL);
