INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'apple-intelligence' AND slug = 'developers'),2,2,'{"it":"Qual è un vantaggio del modello sul dispositivo?","en":"What is an advantage of the on-device model?"}','[{"it":"Funziona offline e senza costi per token","en":"Works offline with no per-token costs"},{"it":"È il modello più grande al mondo","en":"It is the world’s largest model"},{"it":"Conosce tutte le notizie di oggi","en":"It knows all of today’s news"},{"it":"Funziona su Android","en":"It works on Android"}]',0,'{"it":"E i dati restano lì.","en":"And data stays there."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'apple-intelligence' AND slug = 'developers'),3,2,'{"it":"Per quali compiti è adatto?","en":"Which tasks does it suit?"}','[{"it":"Compiti mirati come riassunti ed estrazione","en":"Focused tasks like summaries and extraction"},{"it":"Ricerche enciclopediche su qualsiasi argomento","en":"Encyclopaedic research on any topic"},{"it":"Ragionamenti lunghissimi","en":"Very long reasoning"},{"it":"Generare video","en":"Generating video"}]',0,'{"it":"È un modello piccolo.","en":"It is a small model."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'apple-intelligence' AND slug = 'limits'),1,2,'{"it":"Quali iPhone supportano Apple Intelligence?","en":"Which iPhones support Apple Intelligence?"}','[{"it":"Dalla serie 15 Pro in poi","en":"From the 15 Pro series onwards"},{"it":"Tutti gli iPhone","en":"All iPhones"},{"it":"Solo l’iPhone 11","en":"Only iPhone 11"},{"it":"Nessuno","en":"None"}]',0,'{"it":"Servono memoria e chip recenti.","en":"Recent chips and memory are needed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'apple-intelligence' AND slug = 'limits'),2,2,'{"it":"Che cosa fai con un riassunto di notifica importante?","en":"What do you do with an important notification summary?"}','[{"it":"Apri il messaggio originale","en":"Open the original message"},{"it":"Ti fidi ciecamente","en":"Trust it blindly"},{"it":"Lo cancelli","en":"Delete it"},{"it":"Lo inoltri","en":"Forward it"}]',0,'{"it":"I riassunti possono sbagliare.","en":"Summaries can be wrong."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'apple-intelligence' AND slug = 'limits'),3,2,'{"it":"Perché rileggere un testo riformulato?","en":"Why reread a rephrased text?"}','[{"it":"Può aver cambiato il senso","en":"It may have changed the meaning"},{"it":"Cambia la lingua","en":"It changes the language"},{"it":"Toglie la firma","en":"It removes the signature"},{"it":"Non serve","en":"It is not needed"}]',0,'{"it":"Il messaggio resta tuo.","en":"The message is still yours."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'apple-intelligence' AND slug = 'visual-translate'),1,2,'{"it":"Su che cosa funziona l’intelligenza visiva, oltre alla fotocamera?","en":"What does visual intelligence work on, besides the camera?"}','[{"it":"Sulle chiamate vocali","en":"On voice calls"},{"it":"Sulla cronologia di Safari","en":"On Safari history"},{"it":"Sui contenuti dello schermo, da uno screenshot","en":"On screen content, from a screenshot"},{"it":"Sui file di altri utenti","en":"On other users’ files"}]',2,'{"it":"Spiega, cerca, aggiunge eventi.","en":"It explains, searches, adds events."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'apple-intelligence' AND slug = 'visual-translate'),2,2,'{"it":"Dove può tradurre la Traduzione dal vivo?","en":"Where can Live Translation translate?"}','[{"it":"In Messaggi, FaceTime, telefonate e con gli AirPods","en":"In Messages, FaceTime, calls and with AirPods"},{"it":"Solo nei siti web in Safari","en":"Only on websites in Safari"},{"it":"Solo nei documenti Pages","en":"Only in Pages documents"},{"it":"Solo nelle email in inglese","en":"Only in English emails"}]',0,'{"it":"Mentre comunichi.","en":"While you communicate."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'apple-intelligence' AND slug = 'visual-translate'),3,2,'{"it":"Per una visita medica in un’altra lingua, che cosa conviene?","en":"For a medical visit in another language, what is advisable?"}','[{"it":"Fidarsi sempre della traduzione automatica","en":"Always trust the automatic translation"},{"it":"Spegnere il telefono","en":"Turn off the phone"},{"it":"Tradurre solo le parole difficili","en":"Translate only the hard words"},{"it":"Un interprete o una verifica umana","en":"An interpreter or a human check"}]',3,'{"it":"Gli errori lì costano cari.","en":"Mistakes there are costly."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'commits'),1,1,'{"it":"Che cosa fa `git add`?","en":"What does `git add` do?"}','[{"it":"Mette i file nell’area di stage","en":"Puts files in the staging area"},{"it":"Crea un commit","en":"Creates a commit"},{"it":"Invia al server","en":"Sends to the server"},{"it":"Cancella i file","en":"Deletes files"}]',0,'{"it":"Poi `git commit`.","en":"Then `git commit`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'commits'),2,1,'{"it":"A che cosa serve `.gitignore`?","en":"What is `.gitignore` for?"}','[{"it":"Elencare i file da non registrare","en":"Listing files not to record"},{"it":"Nascondere i commit","en":"Hiding commits"},{"it":"Ignorare gli errori","en":"Ignoring errors"},{"it":"Cancellare la storia","en":"Deleting history"}]',0,'{"it":"Come `.env` e `node_modules/`.","en":"Like `.env` and `node_modules/`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'commits'),3,1,'{"it":"Quale comando mostra cosa è cambiato?","en":"Which command shows what changed?"}','[{"it":"git status","en":"git status"},{"it":"git init","en":"git init"},{"it":"git push","en":"git push"},{"it":"git clone","en":"git clone"}]',0,'{"it":"E `git diff` per i dettagli.","en":"And `git diff` for details."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'branches'),1,1,'{"it":"Che cosa fa `git switch -c nome`?","en":"What does `git switch -c name` do?"}','[{"it":"Crea un branch e ci passa","en":"Creates a branch and switches to it"},{"it":"Cancella un branch","en":"Deletes a branch"},{"it":"Fa il merge","en":"Merges"},{"it":"Clona un repository","en":"Clones a repository"}]',0,'{"it":"-c = create.","en":"-c = create."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'branches'),2,1,'{"it":"Quando nasce un conflitto?","en":"When does a conflict arise?"}','[{"it":"Quando due branch cambiano le stesse righe","en":"When two branches change the same lines"},{"it":"A ogni merge, anche senza modifiche in comune","en":"On every merge, even with no shared changes"},{"it":"Quando il disco è pieno","en":"When the disk is full"},{"it":"Mai","en":"Never"}]',0,'{"it":"Git non sa quale versione scegliere.","en":"Git cannot pick a version."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'branches'),3,1,'{"it":"Che cosa fai dopo aver risolto un conflitto?","en":"What do you do after resolving a conflict?"}','[{"it":"git add e git commit","en":"git add and git commit"},{"it":"git init","en":"git init"},{"it":"Niente","en":"Nothing"},{"it":"Cancelli il repository","en":"Delete the repository"}]',0,'{"it":"Il merge si completa.","en":"The merge completes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'remote'),1,1,'{"it":"Che cosa fa `git push`?","en":"What does `git push` do?"}','[{"it":"Invia i commit al remote","en":"Sends commits to the remote"},{"it":"Scarica i commit","en":"Downloads commits"},{"it":"Crea un branch","en":"Creates a branch"},{"it":"Annulla un commit","en":"Undoes a commit"}]',0,'{"it":"`pull` fa il contrario.","en":"`pull` does the opposite."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'remote'),2,1,'{"it":"Che cos’è una pull request?","en":"What is a pull request?"}','[{"it":"La proposta di unire un branch, con revisione","en":"A proposal to merge a branch, with review"},{"it":"Il download di un repository sul computer","en":"Downloading a repository to your computer"},{"it":"Un errore di GitHub","en":"A GitHub error"},{"it":"Un tipo di commit","en":"A type of commit"}]',0,'{"it":"Si rivede prima del merge.","en":"It is reviewed before merging."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'remote'),3,1,'{"it":"Come si chiama di solito il remote principale?","en":"What is the main remote usually called?"}','[{"it":"origin","en":"origin"},{"it":"main","en":"main"},{"it":"master","en":"master"},{"it":"github","en":"github"}]',0,'{"it":"`main` è un branch.","en":"`main` is a branch."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'undo'),1,1,'{"it":"Come annulli un commit già pubblicato?","en":"How do you undo an already pushed commit?"}','[{"it":"git revert","en":"git revert"},{"it":"git commit --amend","en":"git commit --amend"},{"it":"git restore","en":"git restore"},{"it":"git init","en":"git init"}]',0,'{"it":"Non riscrive la storia condivisa.","en":"It does not rewrite shared history."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'undo'),2,1,'{"it":"Che cosa fa `git stash`?","en":"What does `git stash` do?"}','[{"it":"Mette da parte le modifiche","en":"Sets changes aside"},{"it":"Cancella il repository","en":"Deletes the repository"},{"it":"Pubblica le modifiche","en":"Publishes changes"},{"it":"Crea un branch","en":"Creates a branch"}]',0,'{"it":"Le riprendi con `stash pop`.","en":"Bring them back with `stash pop`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'undo'),3,1,'{"it":"Perché evitare `push --force` su un branch condiviso?","en":"Why avoid `push --force` on a shared branch?"}','[{"it":"Riscrive la storia e può cancellare il lavoro altrui","en":"It rewrites history and can erase others’ work"},{"it":"È più lento e consuma molta banda","en":"It is slower and uses a lot of bandwidth"},{"it":"Non esiste","en":"It does not exist"},{"it":"Non c’è motivo","en":"There is no reason"}]',0,'{"it":"Collaborare richiede prudenza.","en":"Collaboration needs caution."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'history'),1,1,'{"it":"Che cosa fa `git rebase main`?","en":"What does `git rebase main` do?"}','[{"it":"Riapplica i tuoi commit sopra main","en":"Replays your commits on top of main"},{"it":"Cancella main","en":"Deletes main"},{"it":"Crea un tag","en":"Creates a tag"},{"it":"Unisce con un commit di merge","en":"Merges with a merge commit"}]',0,'{"it":"Storia lineare.","en":"Linear history."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'history'),2,1,'{"it":"Quando evitare il rebase?","en":"When should you avoid rebase?"}','[{"it":"Su commit già condivisi","en":"On commits already shared"},{"it":"Sui branch locali","en":"On local branches"},{"it":"Prima di una PR","en":"Before a PR"},{"it":"Mai","en":"Never"}]',0,'{"it":"Riscrive la storia.","en":"It rewrites history."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'history'),3,1,'{"it":"A che cosa serve un tag?","en":"What is a tag for?"}','[{"it":"Dare un nome stabile a un commit, come una versione","en":"Giving a commit a stable name, like a version"},{"it":"Creare un branch","en":"Creating a branch"},{"it":"Annullare un commit","en":"Undoing a commit"},{"it":"Nascondere file","en":"Hiding files"}]',0,'{"it":"Per esempio `v1.2.0`.","en":"For example `v1.2.0`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'setup'),1,2,'{"it":"Che cosa imposta `git config --global user.email`?","en":"What does `git config --global user.email` set?"}','[{"it":"L’email a cui GitHub manda gli avvisi","en":"The email GitHub sends notifications to"},{"it":"L’email registrata come autore nei tuoi commit","en":"The email recorded as author in your commits"},{"it":"L’indirizzo del server remoto","en":"The address of the remote server"},{"it":"L’email per recuperare la password","en":"The email for password recovery"}]',1,'{"it":"Nome ed email entrano in ogni commit.","en":"Name and email go into every commit."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'setup'),2,2,'{"it":"Quale file di una chiave SSH carichi su GitHub?","en":"Which file of an SSH key do you upload to GitHub?"}','[{"it":"id_ed25519","en":"id_ed25519"},{"it":"known_hosts","en":"known_hosts"},{"it":"id_ed25519.pub","en":"id_ed25519.pub"},{"it":".gitconfig","en":".gitconfig"}]',2,'{"it":"La parte pubblica, `.pub`. La privata resta sul tuo computer.","en":"The public part, `.pub`. The private one stays on your computer."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'setup'),3,2,'{"it":"Come fai in modo che `git init` crei sempre il branch `main`?","en":"How do you make `git init` always create the `main` branch?"}','[{"it":"git branch --default main","en":"git branch --default main"},{"it":"git init --main","en":"git init --main"},{"it":"git config core.branch main","en":"git config core.branch main"},{"it":"git config --global init.defaultBranch main","en":"git config --global init.defaultBranch main"}]',3,'{"it":"Vale per tutti i nuovi repository.","en":"It applies to every new repository."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'inspect'),1,2,'{"it":"Che cosa mostra `git diff --staged`?","en":"What does `git diff --staged` show?"}','[{"it":"Le modifiche non ancora in stage","en":"Changes not yet staged"},{"it":"I commit non ancora pubblicati","en":"Commits not yet pushed"},{"it":"Le modifiche in stage, pronte per il commit","en":"Staged changes, ready for the commit"},{"it":"I file elencati in .gitignore","en":"The files listed in .gitignore"}]',2,'{"it":"Senza `--staged` vedi quelle non in stage.","en":"Without `--staged` you see the unstaged ones."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'inspect'),2,2,'{"it":"Che cosa indica `HEAD~2`?","en":"What does `HEAD~2` refer to?"}','[{"it":"Il commit due passi prima di quello corrente","en":"The commit two steps before the current one"},{"it":"Il secondo branch creato nel repository","en":"The second branch created in the repository"},{"it":"Il secondo remote configurato","en":"The second configured remote"},{"it":"I due commit più recenti di main","en":"The two latest commits on main"}]',0,'{"it":"`~` risale la storia.","en":"`~` walks back through history."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'inspect'),3,2,'{"it":"Quale comando cerca dimezzando il commit che ha introdotto un bug?","en":"Which command finds, by halving, the commit that introduced a bug?"}','[{"it":"git blame","en":"git blame"},{"it":"git bisect","en":"git bisect"},{"it":"git log -p","en":"git log -p"},{"it":"git grep","en":"git grep"}]',1,'{"it":"`blame` dice chi ha cambiato una riga, non quando è nato il bug.","en":"`blame` tells who changed a line, not when the bug appeared."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'reset-reflog'),1,2,'{"it":"Quale modo di `git reset` butta via le modifiche?","en":"Which `git reset` mode throws the changes away?"}','[{"it":"--soft","en":"--soft"},{"it":"--mixed","en":"--mixed"},{"it":"--hard","en":"--hard"},{"it":"--keep","en":"--keep"}]',2,'{"it":"`--soft` e `--mixed` le conservano.","en":"`--soft` and `--mixed` keep them."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'reset-reflog'),2,2,'{"it":"Dopo un `reset --hard` sbagliato, dove ritrovi il commit perso?","en":"After a wrong `reset --hard`, where do you find the lost commit?"}','[{"it":"Nell’elenco di `git stash list`","en":"In the `git stash list` output"},{"it":"Nel registro di `git reflog`","en":"In the `git reflog` record"},{"it":"Nel file `.gitignore` del progetto","en":"In the project’s `.gitignore` file"},{"it":"Solo nel remote, se l’avevi pubblicato","en":"Only on the remote, if you had pushed it"}]',1,'{"it":"Il reflog registra ogni spostamento di HEAD.","en":"The reflog records every move of HEAD."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'reset-reflog'),3,2,'{"it":"Che cosa fa `git cherry-pick a1b2c3d`?","en":"What does `git cherry-pick a1b2c3d` do?"}','[{"it":"Cancella quel commit dalla storia","en":"Deletes that commit from history"},{"it":"Sposta il branch corrente su quel commit","en":"Moves the current branch to that commit"},{"it":"Mostra chi ha scritto quel commit","en":"Shows who wrote that commit"},{"it":"Applica le modifiche di quel commit sul branch corrente","en":"Applies that commit’s changes to the current branch"}]',3,'{"it":"Nasce un nuovo commit con le stesse modifiche.","en":"A new commit with the same changes is created."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'sync'),1,2,'{"it":"Che differenza c’è tra `fetch` e `pull`?","en":"What is the difference between `fetch` and `pull`?"}','[{"it":"fetch pubblica i commit, pull li scarica","en":"fetch publishes commits, pull downloads them"},{"it":"Nessuna, sono due nomi dello stesso comando","en":"None, they are two names for one command"},{"it":"fetch scarica senza toccare i tuoi file, pull scarica e integra","en":"fetch downloads without touching your files, pull downloads and integrates"},{"it":"fetch funziona solo con i fork, pull solo con origin","en":"fetch only works with forks, pull only with origin"}]',2,'{"it":"pull = fetch + merge o rebase.","en":"pull = fetch + merge or rebase."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'sync'),2,2,'{"it":"In un fork, che cosa indica di solito il remote `upstream`?","en":"In a fork, what does the `upstream` remote usually point to?"}','[{"it":"La tua copia del progetto su GitHub","en":"Your own copy of the project on GitHub"},{"it":"Il repository originale da cui hai fatto il fork","en":"The original repository you forked from"},{"it":"Il branch principale del tuo computer","en":"The main branch on your computer"},{"it":"Un server di backup automatico di GitHub","en":"An automatic GitHub backup server"}]',1,'{"it":"`origin` è il tuo fork.","en":"`origin` is your fork."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'sync'),3,2,'{"it":"Perché preferire `--force-with-lease` a `--force`?","en":"Why prefer `--force-with-lease` to `--force`?"}','[{"it":"È più veloce sui repository molto grandi","en":"It is faster on very large repositories"},{"it":"Pubblica anche tutti i tag locali","en":"It also pushes all local tags"},{"it":"Funziona anche senza connessione a internet","en":"It works without an internet connection too"},{"it":"Si rifiuta se sul remote ci sono commit che non hai visto","en":"It refuses if the remote has commits you have not seen"}]',3,'{"it":"Non cancella per sbaglio il lavoro altrui.","en":"It does not erase others’ work by mistake."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'actions'),1,2,'{"it":"Dove si mettono i file dei workflow?","en":"Where do workflow files go?"}','[{"it":".git/hooks/","en":".git/hooks/"},{"it":".github/workflows/","en":".github/workflows/"},{"it":".github/actions.json","en":".github/actions.json"},{"it":"ci/workflows/","en":"ci/workflows/"}]',1,'{"it":"Un file YAML per workflow.","en":"One YAML file per workflow."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'actions'),2,2,'{"it":"Che cosa fa `on: pull_request`?","en":"What does `on: pull_request` do?"}','[{"it":"Avvia il workflow quando una PR si apre o si aggiorna","en":"Starts the workflow when a PR is opened or updated"},{"it":"Unisce la PR quando i test passano","en":"Merges the PR when the tests pass"},{"it":"Crea una pull request a ogni push","en":"Creates a pull request on every push"},{"it":"Blocca le PR senza una descrizione","en":"Blocks PRs without a description"}]',0,'{"it":"`on` elenca gli eventi che fanno partire il workflow.","en":"`on` lists the events that start the workflow."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'git' AND slug = 'actions'),3,2,'{"it":"Come deve usare un workflow un token segreto?","en":"How should a workflow use a secret token?"}','[{"it":"Scritto nel file YAML, così è versionato","en":"Written in the YAML file, so it is versioned"},{"it":"In un commento in cima al workflow","en":"In a comment at the top of the workflow"},{"it":"Come secret del repository, letto con `${{ secrets.NOME }}`","en":"As a repository secret, read with `${{ secrets.NAME }}`"},{"it":"In un file `.env` pubblicato nel repository","en":"In a `.env` file committed to the repository"}]',2,'{"it":"Il file è visibile a chi legge il repository.","en":"The file is visible to anyone reading the repository."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'navigate'),1,1,'{"it":"Quale comando mostra la cartella corrente?","en":"Which command shows the current folder?"}','[{"it":"pwd","en":"pwd"},{"it":"ls","en":"ls"},{"it":"cd","en":"cd"},{"it":"where","en":"where"}]',0,'{"it":"print working directory.","en":"print working directory."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'navigate'),2,1,'{"it":"Che cosa fa `cd ..`?","en":"What does `cd ..` do?"}','[{"it":"Sale di un livello","en":"Goes up one level"},{"it":"Torna alla home","en":"Goes home"},{"it":"Cancella la cartella","en":"Deletes the folder"},{"it":"Elenca i file","en":"Lists files"}]',0,'{"it":"`..` è la cartella genitore.","en":"`..` is the parent folder."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'navigate'),3,1,'{"it":"Dove finiscono i file cancellati con `rm`?","en":"Where do files deleted with `rm` go?"}','[{"it":"Da nessuna parte: sono cancellati","en":"Nowhere: they are gone"},{"it":"Nel cestino","en":"In the bin"},{"it":"In una cartella nascosta","en":"In a hidden folder"},{"it":"Sul server","en":"On the server"}]',0,'{"it":"Prudenza con rm -r.","en":"Careful with rm -r."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'pipes'),1,1,'{"it":"Che cosa fa la pipe `|`?","en":"What does the pipe `|` do?"}','[{"it":"Passa l’uscita al comando successivo","en":"Passes output to the next command"},{"it":"Divide due file","en":"Splits two files"},{"it":"Commenta la riga","en":"Comments the line"},{"it":"Esegue i due comandi in parallelo, insieme","en":"Runs the two commands in parallel, together"}]',0,'{"it":"Piccoli comandi, grandi risultati.","en":"Small commands, big results."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'pipes'),2,1,'{"it":"Che differenza c’è tra `>` e `>>`?","en":"What is the difference between `>` and `>>`?"}','[{"it":"> sovrascrive, >> aggiunge","en":"> overwrites, >> appends"},{"it":"Nessuna","en":"None"},{"it":">> cancella il file","en":">> deletes the file"},{"it":"> legge un file","en":"> reads a file"}]',0,'{"it":"Attenzione a non sovrascrivere.","en":"Careful not to overwrite."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'pipes'),3,1,'{"it":"Quale comando segue un log mentre cresce?","en":"Which command follows a log as it grows?"}','[{"it":"tail -f","en":"tail -f"},{"it":"head -n","en":"head -n"},{"it":"cat -f","en":"cat -f"},{"it":"grep -f","en":"grep -f"}]',0,'{"it":"Ctrl+C per uscire.","en":"Ctrl+C to exit."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'permissions'),1,1,'{"it":"Che cosa fa `chmod +x script.sh`?","en":"What does `chmod +x script.sh` do?"}','[{"it":"Lo rende eseguibile","en":"Makes it executable"},{"it":"Lo cancella","en":"Deletes it"},{"it":"Lo nasconde","en":"Hides it"},{"it":"Lo copia","en":"Copies it"}]',0,'{"it":"Poi si lancia con ./script.sh.","en":"Then run it with ./script.sh."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'permissions'),2,1,'{"it":"Che cosa significa `chmod 600`?","en":"What does `chmod 600` mean?"}','[{"it":"Solo il proprietario legge e scrive","en":"Only the owner reads and writes"},{"it":"Tutti possono tutto","en":"Everyone can do everything"},{"it":"Nessuno può leggere","en":"Nobody can read"},{"it":"Solo esecuzione","en":"Execute only"}]',0,'{"it":"Ideale per le chiavi.","en":"Ideal for keys."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'permissions'),3,1,'{"it":"Quale comando mostra i processi in esecuzione?","en":"Which command shows running processes?"}','[{"it":"ps aux","en":"ps aux"},{"it":"ls -l","en":"ls -l"},{"it":"chmod","en":"chmod"},{"it":"pwd","en":"pwd"}]',0,'{"it":"Oppure `top`.","en":"Or `top`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'scripts'),1,1,'{"it":"Con che riga inizia uno script Bash?","en":"What line does a Bash script start with?"}','[{"it":"#!/usr/bin/env bash","en":"#!/usr/bin/env bash"},{"it":"// bash","en":"// bash"},{"it":"<?bash","en":"<?bash"},{"it":"#include bash","en":"#include bash"}]',0,'{"it":"La shebang.","en":"The shebang."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'scripts'),2,1,'{"it":"Come si legge il primo argomento?","en":"How do you read the first argument?"}','[{"it":"$1","en":"$1"},{"it":"$0","en":"$0"},{"it":"arg[1]","en":"arg[1]"},{"it":"%1","en":"%1"}]',0,'{"it":"`$0` è il nome dello script.","en":"`$0` is the script name."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'scripts'),3,1,'{"it":"Perché mettere le variabili tra virgolette?","en":"Why quote variables?"}','[{"it":"Per gestire nomi con spazi","en":"To handle names with spaces"},{"it":"Per colorarle","en":"To colour them"},{"it":"Non serve","en":"It is not needed"},{"it":"Per renderle costanti","en":"To make them constant"}]',0,'{"it":"`\\"$f\\"` invece di `$f`.","en":"`\\"$f\\"` instead of `$f`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'text-tools'),1,1,'{"it":"Quale comando trova righe che contengono un testo?","en":"Which command finds lines containing some text?"}','[{"it":"grep","en":"grep"},{"it":"find","en":"find"},{"it":"cut","en":"cut"},{"it":"mv","en":"mv"}]',0,'{"it":"`-r` per cercare nelle cartelle.","en":"`-r` to search folders."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'text-tools'),2,1,'{"it":"Che cosa fa `uniq -c` dopo `sort`?","en":"What does `uniq -c` do after `sort`?"}','[{"it":"Conta le righe uguali","en":"Counts identical lines"},{"it":"Cancella il file","en":"Deletes the file"},{"it":"Ordina al contrario","en":"Sorts in reverse"},{"it":"Unisce due file","en":"Joins two files"}]',0,'{"it":"Serve l’ordinamento prima.","en":"It needs sorting first."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'text-tools'),3,1,'{"it":"Come provi un `find … -delete` in sicurezza?","en":"How do you try a `find … -delete` safely?"}','[{"it":"Prima senza `-delete`","en":"First without `-delete`"},{"it":"Con sudo","en":"With sudo"},{"it":"Due volte di fila","en":"Twice in a row"},{"it":"Non si può","en":"You cannot"}]',0,'{"it":"Vedi cosa verrebbe cancellato.","en":"You see what would be deleted."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'env'),1,2,'{"it":"Che cosa fa `export`?","en":"What does `export` do?"}','[{"it":"Salva la variabile su disco per sempre","en":"Saves the variable to disk for good"},{"it":"Rende la variabile visibile ai programmi lanciati dalla shell","en":"Makes the variable visible to programs launched by the shell"},{"it":"Stampa il valore della variabile","en":"Prints the variable’s value"},{"it":"Cancella la variabile dalla sessione","en":"Removes the variable from the session"}]',1,'{"it":"Per renderla permanente va scritta in `~/.bashrc`.","en":"To make it permanent write it in `~/.bashrc`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'env'),2,2,'{"it":"Che cos’è `PATH`?","en":"What is `PATH`?"}','[{"it":"La cartella in cui si trova il terminale","en":"The folder the terminal is in"},{"it":"Il percorso del file di configurazione","en":"The path of the configuration file"},{"it":"Il nome dell’utente collegato","en":"The name of the signed-in user"},{"it":"L’elenco di cartelle dove la shell cerca i comandi","en":"The list of folders where the shell looks for commands"}]',3,'{"it":"Separate da due punti.","en":"Separated by colons."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'env'),3,2,'{"it":"Dove scrivi un alias perché resti anche domani?","en":"Where do you write an alias so it is still there tomorrow?"}','[{"it":"~/.bash_history","en":"~/.bash_history"},{"it":"~/.bashrc","en":"~/.bashrc"},{"it":"/tmp/alias","en":"/tmp/alias"},{"it":"/etc/hosts","en":"/etc/hosts"}]',1,'{"it":"Su macOS con Zsh: `~/.zshrc`.","en":"On macOS with Zsh: `~/.zshrc`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'exit-codes'),1,2,'{"it":"Quale codice di uscita indica successo?","en":"Which exit code means success?"}','[{"it":"1","en":"1"},{"it":"0","en":"0"},{"it":"-1","en":"-1"},{"it":"255","en":"255"}]',1,'{"it":"Tutto il resto è un errore.","en":"Everything else is an error."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'exit-codes'),2,2,'{"it":"Che cosa fa `comando1 && comando2`?","en":"What does `command1 && command2` do?"}','[{"it":"Esegue il secondo solo se il primo riesce","en":"Runs the second only if the first succeeds"},{"it":"Esegue il secondo solo se il primo fallisce","en":"Runs the second only if the first fails"},{"it":"Esegue i due comandi in parallelo","en":"Runs the two commands in parallel"},{"it":"Passa l’uscita del primo al secondo","en":"Passes the first one’s output to the second"}]',0,'{"it":"`||` fa il contrario.","en":"`||` does the opposite."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'exit-codes'),3,2,'{"it":"Quale test controlla che una cartella esista?","en":"Which test checks that a folder exists?"}','[{"it":"[[ -f dati ]]","en":"[[ -f dati ]]"},{"it":"[[ -z dati ]]","en":"[[ -z dati ]]"},{"it":"[[ -d dati ]]","en":"[[ -d dati ]]"},{"it":"[[ -x dati ]]","en":"[[ -x dati ]]"}]',2,'{"it":"d = directory.","en":"d = directory."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'functions'),1,2,'{"it":"Come chiami la funzione `saluta` con l’argomento `Ada`?","en":"How do you call the `saluta` function with the argument `Ada`?"}','[{"it":"saluta(\\"Ada\\")","en":"saluta(\\"Ada\\")"},{"it":"saluta Ada","en":"saluta Ada"},{"it":"call saluta Ada","en":"call saluta Ada"},{"it":"saluta -> Ada","en":"saluta -> Ada"}]',1,'{"it":"Come un comando qualsiasi, senza parentesi.","en":"Like any command, without brackets."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'functions'),2,2,'{"it":"Che cosa fa `local` dentro una funzione?","en":"What does `local` do inside a function?"}','[{"it":"Salva la variabile in un file locale","en":"Saves the variable in a local file"},{"it":"Trasforma la variabile in una costante","en":"Turns the variable into a constant"},{"it":"Rende la variabile visibile solo nella funzione","en":"Makes the variable visible only inside the function"},{"it":"Esporta la variabile agli altri script","en":"Exports the variable to other scripts"}]',2,'{"it":"Così non sovrascrivi variabili esterne.","en":"That way you do not overwrite outside variables."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'functions'),3,2,'{"it":"In un `case`, che cosa prende `*)`?","en":"In a `case`, what does `*)` catch?"}','[{"it":"Solo un asterisco scritto dall’utente","en":"Only an asterisk typed by the user"},{"it":"Niente: è un commento","en":"Nothing: it is a comment"},{"it":"Il primo caso dell’elenco","en":"The first case in the list"},{"it":"Qualsiasi valore non preso dai casi precedenti","en":"Any value not caught by the previous cases"}]',3,'{"it":"È il caso “tutto il resto”.","en":"It is the “everything else” case."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'remote'),1,2,'{"it":"Che cosa fa `ssh-copy-id`?","en":"What does `ssh-copy-id` do?"}','[{"it":"Copia un file qualsiasi sul server","en":"Copies any file to the server"},{"it":"Copia la tua chiave pubblica sul server per entrare con la chiave","en":"Copies your public key to the server so you sign in with the key"},{"it":"Crea una nuova coppia di chiavi","en":"Creates a new key pair"},{"it":"Duplica la sessione SSH aperta","en":"Duplicates the open SSH session"}]',1,'{"it":"Le chiavi si creano con `ssh-keygen`.","en":"Keys are created with `ssh-keygen`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'remote'),2,2,'{"it":"Perché usare `rsync` per una cartella grande aggiornata spesso?","en":"Why use `rsync` for a large folder updated often?"}','[{"it":"Comprime tutto in un archivio .zip","en":"It compresses everything into a .zip archive"},{"it":"Funziona anche senza rete","en":"It works without a network"},{"it":"Cancella i file originali dopo la copia","en":"It deletes the original files after copying"},{"it":"Trasferisce solo le parti cambiate","en":"It transfers only the parts that changed"}]',3,'{"it":"Molto più veloce dalla seconda volta.","en":"Much faster from the second time on."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'bash' AND slug = 'remote'),3,2,'{"it":"Che cosa fa `tar -xzf backup.tar.gz`?","en":"What does `tar -xzf backup.tar.gz` do?"}','[{"it":"Estrae l’archivio compresso","en":"Extracts the compressed archive"},{"it":"Crea l’archivio compresso","en":"Creates the compressed archive"},{"it":"Mostra il contenuto senza estrarre","en":"Lists the contents without extracting"},{"it":"Cifra l’archivio con una password","en":"Encrypts the archive with a password"}]',0,'{"it":"x = extract.","en":"x = extract."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'containers'),1,2,'{"it":"Che differenza c’è tra immagine e container?","en":"What is the difference between image and container?"}','[{"it":"Il container è un’immagine in esecuzione","en":"The container is a running image"},{"it":"Sono la stessa cosa","en":"They are the same"},{"it":"L’immagine gira, il container no","en":"The image runs, the container does not"},{"it":"Il container è un file di testo","en":"The container is a text file"}]',0,'{"it":"Come programma e processo.","en":"Like program and process."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'containers'),2,2,'{"it":"Che cosa fa `-p 8080:80`?","en":"What does `-p 8080:80` do?"}','[{"it":"Collega la porta 8080 del computer alla 80 del container","en":"Maps host port 8080 to container port 80"},{"it":"Limita la memoria del container a 8080 MB","en":"Limits the container’s memory to 8080 MB"},{"it":"Imposta la password","en":"Sets the password"},{"it":"Avvia 80 container","en":"Starts 80 containers"}]',0,'{"it":"Ospite:container.","en":"Host:container."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'containers'),3,2,'{"it":"Perché un container è più leggero di una macchina virtuale?","en":"Why is a container lighter than a virtual machine?"}','[{"it":"Condivide il kernel dell’ospite","en":"It shares the host kernel"},{"it":"Non ha file","en":"It has no files"},{"it":"Gira solo di notte","en":"It only runs at night"},{"it":"Non lo è","en":"It is not"}]',0,'{"it":"Niente sistema operativo completo.","en":"No full operating system."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'dockerfile'),1,2,'{"it":"Quale istruzione indica l’immagine di partenza?","en":"Which instruction sets the base image?"}','[{"it":"FROM","en":"FROM"},{"it":"RUN","en":"RUN"},{"it":"CMD","en":"CMD"},{"it":"COPY","en":"COPY"}]',0,'{"it":"Di solito è la prima riga: prima può esserci solo `ARG`.","en":"It is usually the first line: only `ARG` may come before it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'dockerfile'),2,2,'{"it":"Perché copiare prima package.json e poi il codice?","en":"Why copy package.json first and then the code?"}','[{"it":"Per riusare la cache delle dipendenze","en":"To reuse the dependency cache"},{"it":"È obbligatorio","en":"It is mandatory"},{"it":"Per ordine alfabetico","en":"For alphabetical order"},{"it":"Non conta","en":"It does not matter"}]',0,'{"it":"Build molto più veloci.","en":"Much faster builds."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'dockerfile'),3,2,'{"it":"Che cosa fa `docker build -t mia-app:1.0 .`?","en":"What does `docker build -t mia-app:1.0 .` do?"}','[{"it":"Costruisce l’immagine con un nome e una versione","en":"Builds the image with a name and version"},{"it":"Avvia un container dall’immagine indicata","en":"Starts a container from the given image"},{"it":"Cancella le immagini","en":"Deletes images"},{"it":"Scarica nginx","en":"Downloads nginx"}]',0,'{"it":"-t = tag.","en":"-t = tag."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'volumes'),1,2,'{"it":"Che cosa succede ai file scritti in un container rimosso?","en":"What happens to files written in a removed container?"}','[{"it":"Spariscono, se non sono in un volume","en":"They vanish, unless in a volume"},{"it":"Restano per sempre","en":"They stay forever"},{"it":"Vanno su Docker Hub","en":"They go to Docker Hub"},{"it":"Si stampano","en":"They get printed"}]',0,'{"it":"Per questo esistono i volumi.","en":"That is why volumes exist."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'volumes'),2,2,'{"it":"Che cosa fa `-e NOME=valore`?","en":"What does `-e NAME=value` do?"}','[{"it":"Imposta una variabile d’ambiente","en":"Sets an environment variable"},{"it":"Esporta l’immagine","en":"Exports the image"},{"it":"Esegue un test","en":"Runs a test"},{"it":"Elimina il container","en":"Deletes the container"}]',0,'{"it":"Configurazione senza ricostruire.","en":"Configuration without rebuilding."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'volumes'),3,2,'{"it":"Dove non vanno scritte le password vere?","en":"Where must real passwords not be written?"}','[{"it":"Nell’immagine o nei comandi salvati","en":"In the image or saved commands"},{"it":"In un gestore di segreti","en":"In a secrets manager"},{"it":"Nella tua testa","en":"In your head"},{"it":"Da nessuna parte vale tutto","en":"Anywhere is fine"}]',0,'{"it":"Si leggono facilmente.","en":"They are easily read."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'compose'),1,2,'{"it":"Come si raggiunge il servizio db dal servizio web?","en":"How does the web service reach the db service?"}','[{"it":"Usando il nome db come indirizzo","en":"Using the name db as address"},{"it":"Con l’IP pubblico","en":"With the public IP"},{"it":"Non si può","en":"It cannot"},{"it":"Via email","en":"Via email"}]',0,'{"it":"Rete interna di Compose.","en":"Compose’s internal network."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'compose'),2,2,'{"it":"Che cosa fa `docker compose up -d`?","en":"What does `docker compose up -d` do?"}','[{"it":"Avvia tutti i servizi in background","en":"Starts all services in the background"},{"it":"Cancella i volumi","en":"Deletes volumes"},{"it":"Costruisce solo il web","en":"Only builds web"},{"it":"Aggiorna Docker","en":"Updates Docker"}]',0,'{"it":"`down` li ferma.","en":"`down` stops them."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'compose'),3,2,'{"it":"Quando passare a Kubernetes?","en":"When should you move to Kubernetes?"}','[{"it":"Con molte macchine e alta disponibilità","en":"With many machines and high availability"},{"it":"Per un progetto personale","en":"For a personal project"},{"it":"Mai","en":"Never"},{"it":"Per ogni sito","en":"For every site"}]',0,'{"it":"Compose basta per tanti casi.","en":"Compose suffices in many cases."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'production'),1,2,'{"it":"Perché un build multi-stage?","en":"Why a multi-stage build?"}','[{"it":"L’immagine finale contiene solo il necessario","en":"The final image holds only what is needed"},{"it":"Compila più lentamente","en":"It compiles more slowly"},{"it":"Serve per Windows","en":"It is for Windows"},{"it":"Evita il Dockerfile","en":"It avoids the Dockerfile"}]',0,'{"it":"Più piccola e più sicura.","en":"Smaller and safer."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'production'),2,2,'{"it":"A che cosa serve `.dockerignore`?","en":"What is `.dockerignore` for?"}','[{"it":"Escludere file dal contesto di build","en":"Excluding files from the build context"},{"it":"Ignorare gli errori","en":"Ignoring errors"},{"it":"Nascondere i container","en":"Hiding containers"},{"it":"Fermare Docker","en":"Stopping Docker"}]',0,'{"it":"Come `node_modules` e `.git`.","en":"Like `node_modules` and `.git`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'production'),3,2,'{"it":"Perché evitare il tag `latest`?","en":"Why avoid the `latest` tag?"}','[{"it":"Cambia nel tempo e rende il build imprevedibile","en":"It changes over time, making builds unpredictable"},{"it":"È più pesante","en":"It is heavier"},{"it":"Non esiste","en":"It does not exist"},{"it":"È a pagamento","en":"It costs money"}]',0,'{"it":"Fissa la versione.","en":"Pin the version."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'debug'),1,3,'{"it":"Come apri una shell nel container `web` già in esecuzione?","en":"How do you open a shell in the already running `web` container?"}','[{"it":"docker run -it web sh","en":"docker run -it web sh"},{"it":"docker exec -it web sh","en":"docker exec -it web sh"},{"it":"docker attach --shell web","en":"docker attach --shell web"},{"it":"docker logs -it web","en":"docker logs -it web"}]',1,'{"it":"`run` creerebbe un nuovo container.","en":"`run` would create a new container."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'debug'),2,3,'{"it":"Un container si ferma appena avviato. Qual è la prima cosa da fare?","en":"A container stops right after starting. What is the first thing to do?"}','[{"it":"Ricostruire l’immagine senza cache","en":"Rebuild the image without cache"},{"it":"Riavviare il computer","en":"Restart the computer"},{"it":"Leggere i suoi log con `docker logs`","en":"Read its logs with `docker logs`"},{"it":"Dargli più memoria con `--memory`","en":"Give it more memory with `--memory`"}]',2,'{"it":"Il messaggio d’errore di solito è lì.","en":"The error message is usually there."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'debug'),3,3,'{"it":"Che cosa toglie `docker system prune` senza opzioni?","en":"What does `docker system prune` remove without options?"}','[{"it":"Container fermi, reti inutilizzate, immagini orfane e cache di build","en":"Stopped containers, unused networks, dangling images and build cache"},{"it":"Tutti i volumi, compresi quelli con i dati","en":"All volumes, including those holding data"},{"it":"Solo i container in esecuzione","en":"Only the running containers"},{"it":"Le immagini ancora usate dai container attivi","en":"Images still used by running containers"}]',0,'{"it":"I volumi solo con `--volumes`.","en":"Volumes only with `--volumes`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'networks'),1,3,'{"it":"Come si raggiungono due container sulla stessa rete creata da te?","en":"How do two containers on the same network you created reach each other?"}','[{"it":"Solo con l’IP pubblico del server","en":"Only with the server’s public IP"},{"it":"Solo pubblicando le porte con -p","en":"Only by publishing ports with -p"},{"it":"Usando il nome del container come indirizzo","en":"Using the container name as address"},{"it":"Non possono: serve una rete per ciascuno","en":"They cannot: each needs its own network"}]',2,'{"it":"Il DNS interno di Docker risolve i nomi.","en":"Docker’s internal DNS resolves the names."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'networks'),2,3,'{"it":"Il database serve solo al container dell’API sulla stessa rete. Serve `-p 5432:5432`?","en":"The database is used only by the API container on the same network. Do you need `-p 5432:5432`?"}','[{"it":"Sì, altrimenti l’API non lo raggiunge","en":"Yes, otherwise the API cannot reach it"},{"it":"No: basta il nome, e non esporlo è più sicuro","en":"No: the name is enough, and not exposing it is safer"},{"it":"Sì, ma solo quando si usa Compose","en":"Yes, but only when using Compose"},{"it":"No, perché i database non usano porte","en":"No, because databases do not use ports"}]',1,'{"it":"Meno porte aperte, meno superficie d’attacco.","en":"Fewer open ports, less attack surface."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'networks'),3,3,'{"it":"Che cosa fa `-p 127.0.0.1:8080:80`?","en":"What does `-p 127.0.0.1:8080:80` do?"}','[{"it":"Rende la porta raggiungibile solo dal computer stesso","en":"Makes the port reachable only from the machine itself"},{"it":"Apre la porta a tutta la rete locale","en":"Opens the port to the whole local network"},{"it":"Blocca la porta 80 del container","en":"Blocks the container’s port 80"},{"it":"Cambia l’indirizzo IP del container","en":"Changes the container’s IP address"}]',0,'{"it":"Utile in sviluppo e dietro un proxy.","en":"Handy in development and behind a proxy."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'build-config'),1,3,'{"it":"Con `ENTRYPOINT [\\"python\\", \\"cli.py\\"]` e `CMD [\\"--help\\"]`, che cosa esegue `docker run immagine importa`?","en":"With `ENTRYPOINT [\\"python\\", \\"cli.py\\"]` and `CMD [\\"--help\\"]`, what does `docker run image importa` run?"}','[{"it":"python cli.py --help importa","en":"python cli.py --help importa"},{"it":"importa","en":"importa"},{"it":"python cli.py importa","en":"python cli.py importa"},{"it":"python cli.py --help","en":"python cli.py --help"}]',2,'{"it":"Gli argomenti di run sostituiscono CMD, non ENTRYPOINT.","en":"run’s arguments replace CMD, not ENTRYPOINT."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'build-config'),2,3,'{"it":"Che differenza c’è tra `ARG` ed `ENV`?","en":"What is the difference between `ARG` and `ENV`?"}','[{"it":"ENV vale solo durante la build, ARG resta nei container","en":"ENV applies only during the build, ARG stays in containers"},{"it":"ARG vale solo durante la build, ENV resta anche nei container","en":"ARG applies only during the build, ENV stays in containers too"},{"it":"ARG è per i numeri, ENV per i testi","en":"ARG is for numbers, ENV for text"},{"it":"Nessuna: sono due nomi della stessa istruzione","en":"None: they are two names for one instruction"}]',1,'{"it":"Ma nessuno dei due è adatto ai segreti.","en":"But neither is suitable for secrets."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'build-config'),3,3,'{"it":"Perché preferire la forma JSON `CMD [\\"node\\", \\"server.js\\"]`?","en":"Why prefer the JSON form `CMD [\\"node\\", \\"server.js\\"]`?"}','[{"it":"Occupa meno spazio nell’immagine","en":"It takes less space in the image"},{"it":"Permette di usare le variabili della shell","en":"It lets you use shell variables"},{"it":"È l’unica forma accettata da Compose","en":"It is the only form Compose accepts"},{"it":"Il processo riceve direttamente i segnali, come lo stop","en":"The process receives signals directly, such as stop"}]',3,'{"it":"Senza shell in mezzo.","en":"With no shell in between."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'compose-advanced'),1,3,'{"it":"Che cosa garantisce `depends_on` senza condizioni?","en":"What does `depends_on` without conditions guarantee?"}','[{"it":"Che il database sia pronto a rispondere","en":"That the database is ready to answer"},{"it":"Solo l’ordine di avvio dei container","en":"Only the start order of the containers"},{"it":"Che i servizi girino sulla stessa macchina","en":"That the services run on the same machine"},{"it":"Che i dati siano copiati tra i servizi","en":"That data is copied between services"}]',1,'{"it":"Avviato non vuol dire pronto.","en":"Started does not mean ready."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'compose-advanced'),2,3,'{"it":"Come fai aspettare a `web` che `db` risponda davvero?","en":"How do you make `web` wait until `db` really answers?"}','[{"it":"Aggiungendo `restart: always` al database","en":"Adding `restart: always` to the database"},{"it":"Scrivendo db prima di web nel file","en":"Writing db before web in the file"},{"it":"Con `sleep 30` nel comando di web","en":"With `sleep 30` in web’s command"},{"it":"Con un `healthcheck` su db e `condition: service_healthy`","en":"With a `healthcheck` on db and `condition: service_healthy`"}]',3,'{"it":"Niente attese a caso.","en":"No arbitrary waits."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'compose-advanced'),3,3,'{"it":"Che cosa succede a un servizio con `profiles: [strumenti]`?","en":"What happens to a service with `profiles: [strumenti]`?"}','[{"it":"Non può più essere avviato","en":"It can no longer be started"},{"it":"Parte sempre per primo","en":"It always starts first"},{"it":"Parte solo se attivi quel profilo","en":"It starts only if you enable that profile"},{"it":"Usa le risorse di un altro servizio","en":"It uses another service’s resources"}]',2,'{"it":"Con `--profile strumenti`.","en":"With `--profile strumenti`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'registry'),1,3,'{"it":"Che cosa fai prima di pubblicare su GHCR l’immagine locale `negozio:1.2.0`?","en":"What do you do before pushing the local image `negozio:1.2.0` to GHCR?"}','[{"it":"La ricostruisci con un Dockerfile diverso","en":"Rebuild it with a different Dockerfile"},{"it":"Le dai con `docker tag` un nome che contiene il registro","en":"Give it a name containing the registry with `docker tag`"},{"it":"La comprimi in un archivio con tar","en":"Compress it into an archive with tar"},{"it":"La trasformi in un volume","en":"Turn it into a volume"}]',1,'{"it":"Il nome dice dove va pubblicata.","en":"The name says where it is pushed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'registry'),2,3,'{"it":"Che differenza c’è tra tag e digest?","en":"What is the difference between a tag and a digest?"}','[{"it":"Il tag è più sicuro perché non cambia mai","en":"The tag is safer because it never changes"},{"it":"Il digest è un nome scelto da te","en":"The digest is a name you choose"},{"it":"Il tag si può spostare, il digest identifica un contenuto preciso","en":"The tag can be moved, the digest identifies one exact content"},{"it":"Sono la stessa cosa scritta in due modi","en":"They are the same thing written two ways"}]',2,'{"it":"Il digest è un’impronta del contenuto.","en":"The digest is a fingerprint of the content."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'docker' AND slug = 'registry'),3,3,'{"it":"A che cosa serve `--platform linux/amd64,linux/arm64`?","en":"What is `--platform linux/amd64,linux/arm64` for?"}','[{"it":"A pubblicare l’immagine su due registri","en":"Pushing the image to two registries"},{"it":"A renderla compatibile con Windows e Linux","en":"Making it compatible with Windows and Linux"},{"it":"A cifrarla due volte","en":"Encrypting it twice"},{"it":"A farla girare su processori sia x86 sia ARM","en":"Running it on both x86 and ARM processors"}]',3,'{"it":"Un solo nome, più architetture.","en":"One name, several architectures."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'why'),1,3,'{"it":"Che cosa descrivi nei file YAML di Kubernetes?","en":"What do you describe in Kubernetes YAML files?"}','[{"it":"Lo stato desiderato","en":"The desired state"},{"it":"I comandi da eseguire uno per uno","en":"Commands to run one by one"},{"it":"Le password degli utenti","en":"Users’ passwords"},{"it":"Il colore dell’interfaccia","en":"The UI colour"}]',0,'{"it":"Il cluster lo raggiunge da solo.","en":"The cluster reaches it by itself."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'why'),2,3,'{"it":"Che cosa fa `kubectl apply -f app.yaml`?","en":"What does `kubectl apply -f app.yaml` do?"}','[{"it":"Applica lo stato descritto nel file","en":"Applies the state described in the file"},{"it":"Cancella il cluster","en":"Deletes the cluster"},{"it":"Scarica Kubernetes","en":"Downloads Kubernetes"},{"it":"Mostra i log di tutti i pod del file","en":"Shows the logs of every pod in the file"}]',0,'{"it":"Dichiarativo.","en":"Declarative."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'why'),3,3,'{"it":"Che cosa sono i nodi?","en":"What are nodes?"}','[{"it":"Le macchine che eseguono i container","en":"The machines running containers"},{"it":"I file YAML che descrivono il cluster","en":"The YAML files describing the cluster"},{"it":"Gli utenti","en":"The users"},{"it":"Le immagini","en":"The images"}]',0,'{"it":"Il piano di controllo decide.","en":"The control plane decides."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'deployments'),1,3,'{"it":"Che cos’è un pod?","en":"What is a pod?"}','[{"it":"Uno o più container che girano insieme","en":"One or more containers running together"},{"it":"Una macchina fisica dedicata a un’app","en":"A physical machine dedicated to one app"},{"it":"Un file di log","en":"A log file"},{"it":"Un utente","en":"A user"}]',0,'{"it":"L’unità più piccola.","en":"The smallest unit."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'deployments'),2,3,'{"it":"Che cosa fa `replicas: 3`?","en":"What does `replicas: 3` do?"}','[{"it":"Tiene attivi 3 pod","en":"Keeps 3 pods running"},{"it":"Crea 3 cluster","en":"Creates 3 clusters"},{"it":"Riavvia 3 volte","en":"Restarts 3 times"},{"it":"Usa 3 immagini diverse","en":"Uses 3 different images"}]',0,'{"it":"Se uno cade, ne nasce un altro.","en":"If one falls, another is born."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'deployments'),3,3,'{"it":"Come annulli un aggiornamento andato male?","en":"How do you undo a bad update?"}','[{"it":"kubectl rollout undo deployment/web","en":"kubectl rollout undo deployment/web"},{"it":"kubectl delete cluster","en":"kubectl delete cluster"},{"it":"docker stop","en":"docker stop"},{"it":"git revert","en":"git revert"}]',0,'{"it":"Torna alla versione precedente.","en":"It goes back to the previous version."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'services'),1,3,'{"it":"A che cosa serve un Service?","en":"What is a Service for?"}','[{"it":"Dare un indirizzo stabile ai pod e distribuire il traffico","en":"Giving pods a stable address and spreading traffic"},{"it":"Salvare i file","en":"Saving files"},{"it":"Costruire le immagini dei container dal codice","en":"Building container images from code"},{"it":"Gestire gli utenti","en":"Managing users"}]',0,'{"it":"I pod cambiano, il Service resta.","en":"Pods change, the Service stays."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'services'),2,3,'{"it":"Che cosa fa un Ingress?","en":"What does an Ingress do?"}','[{"it":"Porta il traffico esterno ai servizi per dominio e percorso","en":"Routes outside traffic to services by domain and path"},{"it":"Cancella i pod","en":"Deletes pods"},{"it":"Aumenta il numero di nodi quando cresce il traffico","en":"Adds nodes when traffic grows"},{"it":"Fa i backup","en":"Makes backups"}]',0,'{"it":"E gestisce HTTPS.","en":"And handles HTTPS."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'services'),3,3,'{"it":"Che cosa succede se il selector non corrisponde alle etichette?","en":"What happens if the selector does not match the labels?"}','[{"it":"Il traffico non arriva ai pod","en":"Traffic does not reach the pods"},{"it":"Funziona lo stesso","en":"It works anyway"},{"it":"Il cluster si spegne","en":"The cluster shuts down"},{"it":"Si creano nuovi pod","en":"New pods are created"}]',0,'{"it":"Errore comune.","en":"Common mistake."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'config'),1,3,'{"it":"Dove metti una password per un pod?","en":"Where do you put a password for a pod?"}','[{"it":"In un Secret","en":"In a Secret"},{"it":"Nell’immagine","en":"In the image"},{"it":"In una ConfigMap pubblica","en":"In a public ConfigMap"},{"it":"Nel nome del pod","en":"In the pod name"}]',0,'{"it":"E proteggi l’accesso ai Secret.","en":"And protect access to Secrets."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'config'),2,3,'{"it":"I Secret di Kubernetes sono cifrati di default?","en":"Are Kubernetes Secrets encrypted by default?"}','[{"it":"No, solo codificati in base64","en":"No, only base64-encoded"},{"it":"Sì, sempre","en":"Yes, always"},{"it":"Solo il martedì","en":"Only on Tuesdays"},{"it":"Non esistono","en":"They do not exist"}]',0,'{"it":"Attiva la cifratura.","en":"Enable encryption."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'config'),3,3,'{"it":"Che cosa fa l’autoscaling?","en":"What does autoscaling do?"}','[{"it":"Adatta il numero di pod al carico","en":"Adapts pod count to load"},{"it":"Aggiorna Kubernetes","en":"Updates Kubernetes"},{"it":"Cancella i log","en":"Deletes logs"},{"it":"Cambia immagine","en":"Changes image"}]',0,'{"it":"Tra un minimo e un massimo.","en":"Between a minimum and maximum."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'debug'),1,3,'{"it":"Dove leggi gli eventi di un pod?","en":"Where do you read a pod’s events?"}','[{"it":"kubectl describe pod","en":"kubectl describe pod"},{"it":"kubectl get svc","en":"kubectl get svc"},{"it":"kubectl apply","en":"kubectl apply"},{"it":"kubectl top","en":"kubectl top"}]',0,'{"it":"In fondo all’output.","en":"At the bottom of the output."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'debug'),2,3,'{"it":"Che cosa fa la readiness probe?","en":"What does the readiness probe do?"}','[{"it":"Decide se il pod riceve traffico","en":"Decides whether the pod gets traffic"},{"it":"Riavvia il nodo","en":"Restarts the node"},{"it":"Scarica l’immagine","en":"Pulls the image"},{"it":"Cancella il pod","en":"Deletes the pod"}]',0,'{"it":"La liveness invece riavvia.","en":"Liveness restarts instead."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'debug'),3,3,'{"it":"Come torni alla versione precedente?","en":"How do you go back to the previous version?"}','[{"it":"kubectl rollout undo","en":"kubectl rollout undo"},{"it":"kubectl delete","en":"kubectl delete"},{"it":"kubectl scale --replicas=0","en":"kubectl scale --replicas=0"},{"it":"kubectl logs","en":"kubectl logs"}]',0,'{"it":"Il Deployment ricorda le versioni.","en":"The Deployment remembers versions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'storage'),1,3,'{"it":"Che cos’è un PersistentVolumeClaim?","en":"What is a PersistentVolumeClaim?"}','[{"it":"Un pod che contiene un database","en":"A pod containing a database"},{"it":"Una richiesta di spazio persistente fatta per un’app","en":"A request for persistent space made for an app"},{"it":"Un backup automatico del cluster","en":"An automatic cluster backup"},{"it":"Un nodo riservato ai dischi","en":"A node reserved for disks"}]',1,'{"it":"Il cluster la soddisfa con un PersistentVolume.","en":"The cluster fulfils it with a PersistentVolume."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'storage'),2,3,'{"it":"Perché usare uno StatefulSet per un database replicato?","en":"Why use a StatefulSet for a replicated database?"}','[{"it":"Scala più in fretta di un Deployment","en":"It scales faster than a Deployment"},{"it":"Non ha bisogno di immagini","en":"It needs no images"},{"it":"Dà nomi stabili e un volume a ogni replica","en":"It gives stable names and a volume to each replica"},{"it":"Cifra i dati in automatico","en":"It encrypts data automatically"}]',2,'{"it":"`db-0` resta `db-0`, con i suoi dati.","en":"`db-0` stays `db-0`, with its data."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'storage'),3,3,'{"it":"Che cosa significa `ReadWriteOnce`?","en":"What does `ReadWriteOnce` mean?"}','[{"it":"Il volume si può scrivere una sola volta","en":"The volume can be written only once"},{"it":"Tutti i pod leggono, uno solo scrive","en":"All pods read, only one writes"},{"it":"Il volume si cancella dopo la prima lettura","en":"The volume is deleted after the first read"},{"it":"Lo monta in scrittura un solo nodo alla volta","en":"It is mounted read-write by one node at a time"}]',3,'{"it":"Per più nodi serve ReadWriteMany.","en":"Several nodes need ReadWriteMany."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'workloads'),1,3,'{"it":"Che cosa usi per una migrazione del database da fare una volta a ogni rilascio?","en":"What do you use for a database migration to run once per release?"}','[{"it":"Deployment","en":"Deployment"},{"it":"Job","en":"Job"},{"it":"DaemonSet","en":"DaemonSet"},{"it":"Service","en":"Service"}]',1,'{"it":"Gira fino alla fine e si ferma.","en":"It runs to completion and stops."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'workloads'),2,3,'{"it":"Che cosa significa `schedule: \\"0 3 * * *\\"`?","en":"What does `schedule: \\"0 3 * * *\\"` mean?"}','[{"it":"Ogni 3 minuti","en":"Every 3 minutes"},{"it":"Il giorno 3 di ogni mese","en":"On the 3rd of every month"},{"it":"Tre volte al giorno","en":"Three times a day"},{"it":"Ogni giorno alle 3:00","en":"Every day at 3:00"}]',3,'{"it":"Minuto 0, ora 3, ogni giorno, mese e giorno della settimana.","en":"Minute 0, hour 3, every day, month and weekday."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'workloads'),3,3,'{"it":"Quale risorsa per un agente che raccoglie i log su ogni nodo?","en":"Which resource for an agent collecting logs on every node?"}','[{"it":"Job","en":"Job"},{"it":"CronJob","en":"CronJob"},{"it":"DaemonSet","en":"DaemonSet"},{"it":"StatefulSet","en":"StatefulSet"}]',2,'{"it":"Un pod per nodo, anche per quelli nuovi.","en":"One pod per node, new ones included."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'access'),1,3,'{"it":"Che cosa fa un RoleBinding?","en":"What does a RoleBinding do?"}','[{"it":"Crea un nuovo namespace","en":"Creates a new namespace"},{"it":"Collega un Service ai suoi pod","en":"Connects a Service to its pods"},{"it":"Assegna i permessi di un Role a un utente o ServiceAccount","en":"Grants a Role’s permissions to a user or ServiceAccount"},{"it":"Unisce due cluster in uno","en":"Merges two clusters into one"}]',2,'{"it":"Il Role dice cosa, il binding a chi.","en":"The Role says what, the binding to whom."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'access'),2,3,'{"it":"Quale comando verifica se un utente può fare un’azione?","en":"Which command checks whether a user may perform an action?"}','[{"it":"kubectl describe user","en":"kubectl describe user"},{"it":"kubectl auth can-i","en":"kubectl auth can-i"},{"it":"kubectl get roles --check","en":"kubectl get roles --check"},{"it":"kubectl whoami --can","en":"kubectl whoami --can"}]',1,'{"it":"Con `--as` provi per conto di un altro.","en":"With `--as` you test on someone else’s behalf."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'access'),3,3,'{"it":"Quale impostazione impedisce a un container di girare come root?","en":"Which setting stops a container from running as root?"}','[{"it":"privileged: true","en":"privileged: true"},{"it":"hostNetwork: true","en":"hostNetwork: true"},{"it":"replicas: 0","en":"replicas: 0"},{"it":"runAsNonRoot: true","en":"runAsNonRoot: true"}]',3,'{"it":"Va nel securityContext.","en":"It goes in the securityContext."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'gateway'),1,3,'{"it":"Chi gestisce di solito il Gateway e chi le HTTPRoute?","en":"Who usually manages the Gateway and who the HTTPRoutes?"}','[{"it":"Entrambi li gestisce il fornitore cloud","en":"The cloud provider manages both"},{"it":"Il Gateway il team della piattaforma, le HTTPRoute i team delle app","en":"The Gateway the platform team, the HTTPRoutes the app teams"},{"it":"Il Gateway i team delle app, le HTTPRoute nessuno","en":"The Gateway the app teams, the HTTPRoutes nobody"},{"it":"Li crea Kubernetes da solo per ogni Service","en":"Kubernetes creates them by itself for each Service"}]',1,'{"it":"Ruoli separati, permessi separati.","en":"Separate roles, separate permissions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'gateway'),2,3,'{"it":"Come mandi il 10% del traffico a una nuova versione con una HTTPRoute?","en":"How do you send 10% of traffic to a new version with an HTTPRoute?"}','[{"it":"Con 10 repliche della nuova versione","en":"With 10 replicas of the new version"},{"it":"Con un’annotazione nginx sul Service","en":"With an nginx annotation on the Service"},{"it":"Con un CronJob che cambia versione ogni ora","en":"With a CronJob switching version every hour"},{"it":"Con due backendRefs con i pesi 90 e 10","en":"With two backendRefs weighted 90 and 10"}]',3,'{"it":"Il rilascio graduale è nello standard.","en":"Gradual rollout is part of the standard."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'gateway'),3,3,'{"it":"Qual è oggi lo stato dell’Ingress?","en":"What is the state of Ingress today?"}','[{"it":"È stato rimosso da Kubernetes","en":"It has been removed from Kubernetes"},{"it":"Resta supportato ma è congelato: le novità vanno nella Gateway API","en":"It is still supported but frozen: new features go into the Gateway API"},{"it":"È diventato obbligatorio al posto dei Service","en":"It has become mandatory instead of Services"},{"it":"Funziona solo con il controller ingress-nginx","en":"It works only with the ingress-nginx controller"}]',1,'{"it":"Ma il controller ingress-nginx non è più mantenuto.","en":"But the ingress-nginx controller is no longer maintained."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'packaging'),1,3,'{"it":"Come adatta Kustomize i YAML a ogni ambiente?","en":"How does Kustomize adapt YAML to each environment?"}','[{"it":"Con template scritti in un linguaggio di programmazione","en":"With templates written in a programming language"},{"it":"Con una base e delle patch per ogni ambiente","en":"With a base and patches for each environment"},{"it":"Scaricando i file da un registro pubblico","en":"By downloading the files from a public registry"},{"it":"Creando un cluster diverso per ogni ambiente","en":"By creating a different cluster per environment"}]',1,'{"it":"Niente template: solo modifiche dichiarate.","en":"No templates: only declared changes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'packaging'),2,3,'{"it":"Dove imposti i valori di un chart Helm per un ambiente?","en":"Where do you set a Helm chart’s values for an environment?"}','[{"it":"Nel Dockerfile dell’app","en":"In the app’s Dockerfile"},{"it":"Nei log del cluster","en":"In the cluster logs"},{"it":"In un ConfigMap del namespace kube-system","en":"In a ConfigMap in the kube-system namespace"},{"it":"In un file di valori passato con -f, o con --set","en":"In a values file passed with -f, or with --set"}]',3,'{"it":"I valori riempiono i template del chart.","en":"The values fill in the chart’s templates."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'kubernetes' AND slug = 'packaging'),3,3,'{"it":"Che cos’è il GitOps?","en":"What is GitOps?"}','[{"it":"Usare Git al posto di kubectl per leggere i log","en":"Using Git instead of kubectl to read logs"},{"it":"Fare il backup del cluster dentro GitHub","en":"Backing up the cluster inside GitHub"},{"it":"Il cluster si allinea da solo ai file versionati in Git","en":"The cluster aligns itself to the files versioned in Git"},{"it":"Modificare il cluster a mano e poi fare un commit","en":"Changing the cluster by hand and then committing"}]',2,'{"it":"Git è la fonte di verità.","en":"Git is the source of truth."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'models'),1,1,'{"it":"In quale modello gestisci il sistema operativo?","en":"In which model do you manage the operating system?"}','[{"it":"IaaS","en":"IaaS"},{"it":"SaaS","en":"SaaS"},{"it":"PaaS","en":"PaaS"},{"it":"Serverless","en":"Serverless"}]',0,'{"it":"Macchine virtuali.","en":"Virtual machines."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'models'),2,1,'{"it":"Che cosa significa serverless?","en":"What does serverless mean?"}','[{"it":"I server ci sono ma non li gestisci, paghi quando il codice gira","en":"Servers exist but you do not manage them, you pay when code runs"},{"it":"Non esistono server: il codice gira nel browser dell’utente","en":"There are no servers: code runs in the user’s browser"},{"it":"Funziona offline","en":"It works offline"},{"it":"È gratis","en":"It is free"}]',0,'{"it":"E scala da solo.","en":"And it scales by itself."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'models'),3,1,'{"it":"Gmail è un esempio di…","en":"Gmail is an example of…"}','[{"it":"SaaS","en":"SaaS"},{"it":"IaaS","en":"IaaS"},{"it":"PaaS","en":"PaaS"},{"it":"Hardware","en":"Hardware"}]',0,'{"it":"Software pronto.","en":"Ready software."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'services'),1,1,'{"it":"Qual è il servizio di object storage di AWS?","en":"What is AWS’s object storage service?"}','[{"it":"S3","en":"S3"},{"it":"EC2","en":"EC2"},{"it":"Lambda","en":"Lambda"},{"it":"RDS","en":"RDS"}]',0,'{"it":"Bucket di file.","en":"Buckets of files."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'services'),2,1,'{"it":"Che vantaggio dà un database gestito?","en":"What does a managed database give you?"}','[{"it":"Backup e aggiornamenti automatici","en":"Automatic backups and updates"},{"it":"Nessun costo, è sempre incluso","en":"No cost, it is always included"},{"it":"Nessun dato","en":"No data"},{"it":"Solo velocità","en":"Only speed"}]',0,'{"it":"Meno manutenzione.","en":"Less maintenance."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'services'),3,1,'{"it":"Qual è il servizio Kubernetes gestito di Google Cloud?","en":"What is Google Cloud’s managed Kubernetes service?"}','[{"it":"GKE","en":"GKE"},{"it":"EKS","en":"EKS"},{"it":"AKS","en":"AKS"},{"it":"S3","en":"S3"}]',0,'{"it":"EKS è AWS, AKS è Azure.","en":"EKS is AWS, AKS is Azure."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'regions'),1,1,'{"it":"Che cos’è una zona di disponibilità?","en":"What is an availability zone?"}','[{"it":"Un data center separato dentro una regione","en":"A separate data centre within a region"},{"it":"Un paese in cui il fornitore ha un ufficio","en":"A country where the provider has an office"},{"it":"Un tipo di database","en":"A database type"},{"it":"Una password","en":"A password"}]',0,'{"it":"Alimentazione e rete indipendenti.","en":"Independent power and network."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'regions'),2,1,'{"it":"Perché scegliere una regione europea per dati di cittadini UE?","en":"Why choose a European region for EU citizens’ data?"}','[{"it":"Per il GDPR e la latenza","en":"For the GDPR and latency"},{"it":"Per il colore della console","en":"For the console colour"},{"it":"Non conta","en":"It does not matter"},{"it":"Perché costa sempre di più","en":"Because it always costs more"}]',0,'{"it":"Legge e vicinanza.","en":"Law and proximity."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'regions'),3,1,'{"it":"Che cosa dà distribuire l’app su più zone?","en":"What does spreading the app across zones give?"}','[{"it":"Resistenza ai guasti","en":"Fault tolerance"},{"it":"Più bug","en":"More bugs"},{"it":"Meno sicurezza","en":"Less security"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Se una zona cade, le altre reggono.","en":"If one zone falls, the others hold."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'costs'),1,1,'{"it":"Che cosa protegge il fornitore nel modello condiviso?","en":"What does the provider protect in the shared model?"}','[{"it":"L’infrastruttura fisica e la rete","en":"Physical infrastructure and network"},{"it":"I tuoi dati e accessi","en":"Your data and access"},{"it":"Le tue password","en":"Your passwords"},{"it":"Tutto","en":"Everything"}]',0,'{"it":"Il resto è tuo.","en":"The rest is yours."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'costs'),2,1,'{"it":"Qual è una causa frequente di violazioni nel cloud?","en":"What is a frequent cause of cloud breaches?"}','[{"it":"Un bucket lasciato pubblico","en":"A bucket left public"},{"it":"Troppi backup","en":"Too many backups"},{"it":"Server troppo veloci","en":"Servers too fast"},{"it":"Il colore della console","en":"The console colour"}]',0,'{"it":"Errore di configurazione.","en":"Configuration error."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'costs'),3,1,'{"it":"Come eviti sorprese sui costi?","en":"How do you avoid cost surprises?"}','[{"it":"Avvisi di budget e spegnere ciò che non serve","en":"Budget alerts and turning off what is unused"},{"it":"Ignorando la fattura","en":"Ignoring the bill"},{"it":"Usando sempre le macchine più grandi","en":"Always using the biggest machines"},{"it":"Non si può","en":"You cannot"}]',0,'{"it":"Controllo costante.","en":"Constant monitoring."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'iac'),1,2,'{"it":"Che cos’è l’infrastruttura come codice?","en":"What is infrastructure as code?"}','[{"it":"Descrivere le risorse in file versionati","en":"Describing resources in versioned files"},{"it":"Scrivere codice sul server","en":"Writing code on the server"},{"it":"Un linguaggio di programmazione","en":"A programming language"},{"it":"Un tipo di cloud","en":"A type of cloud"}]',0,'{"it":"Ripetibile e rivedibile.","en":"Repeatable and reviewable."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'iac'),2,2,'{"it":"Che cosa fa `terraform plan`?","en":"What does `terraform plan` do?"}','[{"it":"Mostra cosa cambierà","en":"Shows what will change"},{"it":"Cancella tutto","en":"Deletes everything"},{"it":"Applica subito","en":"Applies right away"},{"it":"Scrive i log","en":"Writes logs"}]',0,'{"it":"Poi `apply`.","en":"Then `apply`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'iac'),3,2,'{"it":"A che cosa servono gli avvisi di budget?","en":"What are budget alerts for?"}','[{"it":"Sapere in tempo se i costi salgono","en":"Knowing in time if costs rise"},{"it":"Pagare meno tasse","en":"Paying less tax"},{"it":"Bloccare gli utenti","en":"Blocking users"},{"it":"Velocizzare il server","en":"Speeding up the server"}]',0,'{"it":"Niente sorprese in fattura.","en":"No surprises on the bill."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'networking'),1,2,'{"it":"Che cos’è una VPC?","en":"What is a VPC?"}','[{"it":"Un tipo di macchina virtuale molto potente","en":"A very powerful type of virtual machine"},{"it":"Una rete privata e isolata per le tue risorse cloud","en":"A private, isolated network for your cloud resources"},{"it":"Un servizio che copia i file vicino agli utenti","en":"A service copying files close to users"},{"it":"Un elenco degli utenti e dei loro permessi","en":"A list of users and their permissions"}]',1,'{"it":"Su Azure si chiama VNet.","en":"On Azure it is called VNet."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'networking'),2,2,'{"it":"Dove dovrebbe stare il database di un’app web?","en":"Where should a web app’s database live?"}','[{"it":"In una subnet pubblica con un IP pubblico","en":"In a public subnet with a public IP"},{"it":"Su una CDN vicina agli utenti","en":"On a CDN close to users"},{"it":"In una subnet privata, raggiungibile solo dai server dell’app","en":"In a private subnet, reachable only from the app servers"},{"it":"In un bucket pubblico per fare prima","en":"In a public bucket to be quicker"}]',2,'{"it":"Meno è esposto, meno è attaccabile.","en":"The less exposed, the less attackable."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'networking'),3,2,'{"it":"Che cosa fa una CDN?","en":"What does a CDN do?"}','[{"it":"Copia i file statici su server vicini agli utenti","en":"Copies static files to servers close to users"},{"it":"Cifra il contenuto del database","en":"Encrypts the database contents"},{"it":"Traduce i domini in indirizzi IP","en":"Translates domains into IP addresses"},{"it":"Assegna i permessi agli utenti","en":"Assigns permissions to users"}]',0,'{"it":"Tradurre i domini è il lavoro del DNS.","en":"Translating domains is DNS’s job."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'iam'),1,2,'{"it":"Che cosa dice il principio del privilegio minimo?","en":"What does the principle of least privilege say?"}','[{"it":"Gli amministratori devono essere pochi utenti","en":"Administrators must be few users"},{"it":"Si dà a tutti il ruolo di amministratore per non bloccare il lavoro","en":"Everyone gets the admin role so work is never blocked"},{"it":"Il team usa una sola password condivisa","en":"The team uses a single shared password"},{"it":"Ogni identità ha solo i permessi che le servono","en":"Every identity has only the permissions it needs"}]',3,'{"it":"Così un account violato fa meno danni.","en":"That way a breached account does less damage."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'iam'),2,2,'{"it":"Come dovrebbe accedere a un bucket un’app che gira su una VM?","en":"How should an app running on a VM access a bucket?"}','[{"it":"Con chiavi di accesso scritte nel codice","en":"With access keys written in the code"},{"it":"Con le credenziali dell’account root","en":"With the root account’s credentials"},{"it":"Con un ruolo che le dà credenziali temporanee","en":"With a role giving it temporary credentials"},{"it":"Rendendo il bucket pubblico","en":"By making the bucket public"}]',2,'{"it":"Niente segreti da custodire nel codice.","en":"No secrets to keep in the code."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'iam'),3,2,'{"it":"Trovi una chiave di accesso in un repository pubblico. Che cosa fai?","en":"You find an access key in a public repository. What do you do?"}','[{"it":"La revochi subito e ne crei una nuova se serve","en":"Revoke it at once and create a new one if needed"},{"it":"Cancelli il file nel prossimo commit","en":"Delete the file in the next commit"},{"it":"Rendi privato il repository e basta","en":"Make the repository private and nothing more"},{"it":"Aspetti di vedere se qualcuno la usa","en":"Wait to see whether anyone uses it"}]',0,'{"it":"I bot cercano chiavi nei repository di continuo.","en":"Bots search repositories for keys all the time."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'scaling'),1,2,'{"it":"Che cosa vuol dire scalare in orizzontale?","en":"What does scaling horizontally mean?"}','[{"it":"Passare a un server con più CPU e RAM","en":"Moving to a server with more CPU and RAM"},{"it":"Aggiungere server uguali dietro un load balancer","en":"Adding identical servers behind a load balancer"},{"it":"Spostare l’app in un’altra regione","en":"Moving the app to another region"},{"it":"Comprimere i dati del database","en":"Compressing the database data"}]',1,'{"it":"Il verticale invece ingrandisce una macchina.","en":"Vertical scaling instead enlarges one machine."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'scaling'),2,2,'{"it":"Perché per scalare in orizzontale l’app deve essere senza stato?","en":"Why must the app be stateless to scale horizontally?"}','[{"it":"Per consumare meno CPU","en":"To use less CPU"},{"it":"Perché i load balancer non accettano cookie","en":"Because load balancers do not accept cookies"},{"it":"Per non dover usare un database","en":"So as not to need a database"},{"it":"Perché ogni richiesta può arrivare a un server diverso","en":"Because each request may reach a different server"}]',3,'{"it":"Le sessioni vanno in un servizio condiviso.","en":"Sessions go in a shared service."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cloud-base' AND slug = 'scaling'),3,2,'{"it":"Che cos’è l’RPO?","en":"What is the RPO?"}','[{"it":"Quanti dati al massimo puoi permetterti di perdere","en":"How much data at most you can afford to lose"},{"it":"In quanto tempo il servizio deve ripartire","en":"How quickly the service must be back"},{"it":"Il numero di server in una regione","en":"The number of servers in a region"},{"it":"Il costo mensile dei backup","en":"The monthly cost of backups"}]',0,'{"it":"Il tempo per ripartire è l’RTO.","en":"The time to recover is the RTO."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'basics'),1,1,'{"it":"Da quale funzione parte un programma Go?","en":"Which function does a Go program start from?"}','[{"it":"main","en":"main"},{"it":"start","en":"start"},{"it":"init","en":"init"},{"it":"run","en":"run"}]',0,'{"it":"Nel pacchetto main.","en":"In the main package."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'basics'),2,1,'{"it":"Che cosa fa `:=`?","en":"What does `:=` do?"}','[{"it":"Dichiara e assegna deducendo il tipo","en":"Declares and assigns inferring the type"},{"it":"Confronta due valori e restituisce un booleano","en":"Compares two values and returns a boolean"},{"it":"Crea una costante","en":"Creates a constant"},{"it":"Importa un pacchetto","en":"Imports a package"}]',0,'{"it":"Solo dentro le funzioni.","en":"Only inside functions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'basics'),3,1,'{"it":"Che cosa succede con una variabile non usata?","en":"What happens with an unused variable?"}','[{"it":"Errore di compilazione","en":"Compile error"},{"it":"Niente","en":"Nothing"},{"it":"Un avviso ignorabile","en":"An ignorable warning"},{"it":"Viene cancellata","en":"It gets deleted"}]',0,'{"it":"Codice pulito per forza.","en":"Clean code by force."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'errors'),1,1,'{"it":"Come segnala un errore una funzione Go?","en":"How does a Go function signal an error?"}','[{"it":"Restituendo un valore error diverso da nil","en":"Returning a non-nil error value"},{"it":"Lanciando un’eccezione","en":"Throwing an exception"},{"it":"Stampando in rosso","en":"Printing in red"},{"it":"Chiudendo il programma sempre","en":"Always exiting the program"}]',0,'{"it":"Niente eccezioni.","en":"No exceptions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'errors'),2,1,'{"it":"Che cosa fa `defer f.Close()`?","en":"What does `defer f.Close()` do?"}','[{"it":"Chiude il file alla fine della funzione","en":"Closes the file at the end of the function"},{"it":"Chiude subito il file, prima di leggerlo","en":"Closes the file at once, before reading it"},{"it":"Non lo chiude mai","en":"Never closes it"},{"it":"Cancella il file","en":"Deletes the file"}]',0,'{"it":"Anche se la funzione esce prima.","en":"Even if the function returns early."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'errors'),3,1,'{"it":"A che cosa serve `%w` in `fmt.Errorf`?","en":"What is `%w` for in `fmt.Errorf`?"}','[{"it":"Avvolgere l’errore originale aggiungendo contesto","en":"Wrapping the original error adding context"},{"it":"Stampare una parola","en":"Printing a word"},{"it":"Formattare numeri","en":"Formatting numbers"},{"it":"Ignorare l’errore e continuare l’esecuzione","en":"Ignoring the error and carrying on"}]',0,'{"it":"w = wrap.","en":"w = wrap."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'structs'),1,1,'{"it":"Come si dichiara che un tipo implementa un’interfaccia?","en":"How do you declare a type implements an interface?"}','[{"it":"Non serve: basta avere i metodi","en":"No need: having the methods is enough"},{"it":"Con la parola chiave implements dopo il nome","en":"With the implements keyword after the name"},{"it":"Con extends","en":"With extends"},{"it":"Con un commento","en":"With a comment"}]',0,'{"it":"Implementazione implicita.","en":"Implicit implementation."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'structs'),2,1,'{"it":"Un campo che inizia con la maiuscola è…","en":"A field starting with a capital is…"}','[{"it":"Esportato, visibile da altri pacchetti","en":"Exported, visible from other packages"},{"it":"Una costante","en":"A constant"},{"it":"Privato, visibile solo nel suo file","en":"Private, visible only in its file"},{"it":"Un errore","en":"An error"}]',0,'{"it":"Minuscolo = privato.","en":"Lowercase = private."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'structs'),3,1,'{"it":"Quando usare un ricevitore puntatore?","en":"When should you use a pointer receiver?"}','[{"it":"Quando il metodo modifica la struct","en":"When the method modifies the struct"},{"it":"Mai","en":"Never"},{"it":"Solo per stampare","en":"Only to print"},{"it":"Sempre per le interfacce vuote","en":"Always for empty interfaces"}]',0,'{"it":"`func (r *T)`.","en":"`func (r *T)`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'concurrency'),1,1,'{"it":"Come si avvia una goroutine?","en":"How do you start a goroutine?"}','[{"it":"go funzione()","en":"go funzione()"},{"it":"async funzione()","en":"async funzione()"},{"it":"thread funzione()","en":"thread funzione()"},{"it":"run funzione()","en":"run funzione()"}]',0,'{"it":"Leggerissime.","en":"Very lightweight."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'concurrency'),2,1,'{"it":"Che cosa fa `<-ch`?","en":"What does `<-ch` do?"}','[{"it":"Riceve dal canale, aspettando","en":"Receives from the channel, waiting"},{"it":"Chiude il canale","en":"Closes the channel"},{"it":"Invia al canale","en":"Sends to the channel"},{"it":"Cancella il canale","en":"Deletes the channel"}]',0,'{"it":"`ch <- v` invia.","en":"`ch <- v` sends."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'concurrency'),3,1,'{"it":"Che cosa serve per aspettare un gruppo di goroutine?","en":"What is used to wait for a group of goroutines?"}','[{"it":"sync.WaitGroup","en":"sync.WaitGroup"},{"it":"time.Sleep sempre","en":"time.Sleep sempre"},{"it":"fmt.Wait","en":"fmt.Wait"},{"it":"os.Exit","en":"os.Exit"}]',0,'{"it":"Add, Done, Wait.","en":"Add, Done, Wait."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'http'),1,1,'{"it":"Quale pacchetto avvia un server web?","en":"Which package starts a web server?"}','[{"it":"net/http","en":"net/http"},{"it":"fmt","en":"fmt"},{"it":"os","en":"os"},{"it":"strings","en":"strings"}]',0,'{"it":"Con `ListenAndServe`.","en":"With `ListenAndServe`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'http'),2,1,'{"it":"A che cosa serve `json:\\"titolo\\"`?","en":"What is `json:\\"titolo\\"` for?"}','[{"it":"Dà il nome al campo nel JSON","en":"Names the field in the JSON"},{"it":"Commenta il campo","en":"Comments the field"},{"it":"Rende il campo privato","en":"Makes the field private"},{"it":"Lo cifra","en":"Encrypts it"}]',0,'{"it":"È un tag della struct.","en":"It is a struct tag."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'http'),3,1,'{"it":"Come lanci tutti i test?","en":"How do you run all tests?"}','[{"it":"go test ./...","en":"go test ./..."},{"it":"go run test","en":"go run test"},{"it":"go build -t","en":"go build -t"},{"it":"go vet","en":"go vet"}]',0,'{"it":"I file finiscono in `_test.go`.","en":"Files end in `_test.go`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'control-flow'),1,2,'{"it":"Come si scrive un “while” in Go?","en":"How do you write a “while” in Go?"}','[{"it":"while n > 0 { }","en":"while n > 0 { }"},{"it":"for n > 0 { }","en":"for n > 0 { }"},{"it":"loop n > 0 { }","en":"loop n > 0 { }"},{"it":"do { } while n > 0","en":"do { } while n > 0"}]',1,'{"it":"`for` con la sola condizione.","en":"`for` with just the condition."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'control-flow'),2,2,'{"it":"Quali numeri produce `for i := range 3`?","en":"Which numbers does `for i := range 3` produce?"}','[{"it":"1, 2, 3","en":"1, 2, 3"},{"it":"0, 1, 2, 3","en":"0, 1, 2, 3"},{"it":"0, 1, 2","en":"0, 1, 2"},{"it":"3","en":"3"}]',2,'{"it":"Si parte da 0 e ci si ferma prima di 3.","en":"It starts at 0 and stops before 3."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'control-flow'),3,2,'{"it":"Uno `switch` di Go passa al caso successivo dopo averne eseguito uno?","en":"Does a Go `switch` move on to the next case after running one?"}','[{"it":"Sì, sempre","en":"Yes, always"},{"it":"Solo se manca default","en":"Only if default is missing"},{"it":"Solo con le stringhe","en":"Only with strings"},{"it":"No, a meno di scrivere fallthrough","en":"No, unless you write fallthrough"}]',3,'{"it":"Il contrario di C e Java.","en":"The opposite of C and Java."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'slices-maps'),1,2,'{"it":"Come aggiungi 5 alla slice `s`?","en":"How do you add 5 to the slice `s`?"}','[{"it":"s.push(5)","en":"s.push(5)"},{"it":"append(s, 5)","en":"append(s, 5)"},{"it":"s = append(s, 5)","en":"s = append(s, 5)"},{"it":"s += 5","en":"s += 5"}]',2,'{"it":"`append` restituisce la nuova slice.","en":"`append` returns the new slice."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'slices-maps'),2,2,'{"it":"Che cosa dà `m[\\"x\\"]` su una `map[string]int` senza la chiave \\"x\\"?","en":"What does `m[\\"x\\"]` give on a `map[string]int` without the key \\"x\\"?"}','[{"it":"nil","en":"nil"},{"it":"0","en":"0"},{"it":"Un panic","en":"A panic"},{"it":"-1","en":"-1"}]',1,'{"it":"Lo zero value di `int`.","en":"The zero value of `int`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'slices-maps'),3,2,'{"it":"Che cosa contiene `ok` in `v, ok := m[k]`?","en":"What does `ok` hold in `v, ok := m[k]`?"}','[{"it":"Se la chiave esiste","en":"Whether the key exists"},{"it":"Il numero di chiavi","en":"The number of keys"},{"it":"Un errore","en":"An error"},{"it":"La chiave stessa","en":"The key itself"}]',0,'{"it":"Un booleano.","en":"A boolean."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'pointers'),1,2,'{"it":"Che cosa fa `&x`?","en":"What does `&x` do?"}','[{"it":"Prende l’indirizzo di x","en":"Takes the address of x"},{"it":"Copia x","en":"Copies x"},{"it":"Confronta x con zero","en":"Compares x with zero"},{"it":"Cancella x","en":"Deletes x"}]',0,'{"it":"Il risultato è di tipo `*int` se x è un int.","en":"The result is of type `*int` if x is an int."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'pointers'),2,2,'{"it":"Perché `incrementaCopia(c)` non cambia `c`?","en":"Why does `incrementaCopia(c)` not change `c`?"}','[{"it":"Perché Valore è privato","en":"Because Valore is private"},{"it":"Perché la funzione riceve una copia della struct","en":"Because the function receives a copy of the struct"},{"it":"Perché manca return","en":"Because return is missing"},{"it":"Perché Go non permette di modificare le struct","en":"Because Go does not allow changing structs"}]',1,'{"it":"Serve un puntatore per cambiare l’originale.","en":"A pointer is needed to change the original."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'pointers'),3,2,'{"it":"Che cosa succede leggendo `*p` se `p` è `nil`?","en":"What happens reading `*p` if `p` is `nil`?"}','[{"it":"Restituisce 0","en":"It returns 0"},{"it":"Restituisce nil","en":"It returns nil"},{"it":"Il programma va in panic","en":"The program panics"},{"it":"Niente, viene ignorato","en":"Nothing, it is ignored"}]',2,'{"it":"Controlla sempre i puntatori che potrebbero essere nil.","en":"Always check pointers that might be nil."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'modules'),1,2,'{"it":"Quale comando crea il file `go.mod`?","en":"Which command creates the `go.mod` file?"}','[{"it":"go new","en":"go new"},{"it":"go mod init","en":"go mod init"},{"it":"go init mod","en":"go init mod"},{"it":"go create","en":"go create"}]',1,'{"it":"Seguito dal percorso del modulo.","en":"Followed by the module path."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'modules'),2,2,'{"it":"Che cosa fa `go mod tidy`?","en":"What does `go mod tidy` do?"}','[{"it":"Formatta il codice","en":"Formats the code"},{"it":"Esegue i test","en":"Runs the tests"},{"it":"Cancella la cartella vendor","en":"Deletes the vendor folder"},{"it":"Aggiunge le dipendenze mancanti e toglie quelle inutili","en":"Adds missing dependencies and removes unused ones"}]',3,'{"it":"Tiene in ordine `go.mod` e `go.sum`.","en":"It keeps `go.mod` and `go.sum` tidy."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-base' AND slug = 'modules'),3,2,'{"it":"Come chiami da `main` la funzione `InFahrenheit` del pacchetto `temperatura`?","en":"How do you call the `InFahrenheit` function of the `temperatura` package from `main`?"}','[{"it":"InFahrenheit(20)","en":"InFahrenheit(20)"},{"it":"temperatura::InFahrenheit(20)","en":"temperatura::InFahrenheit(20)"},{"it":"temperatura.InFahrenheit(20)","en":"temperatura.InFahrenheit(20)"},{"it":"import.temperatura.InFahrenheit(20)","en":"import.temperatura.InFahrenheit(20)"}]',2,'{"it":"Nome del pacchetto, punto, nome esportato.","en":"Package name, dot, exported name."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'generics'),1,2,'{"it":"Che cosa significa `[T cmp.Ordered]`?","en":"What does `[T cmp.Ordered]` mean?"}','[{"it":"T è un tipo che si può confrontare con < e >","en":"T is a type that can be compared with < and >"},{"it":"T è un tipo ordinato alfabeticamente","en":"T is an alphabetically sorted type"},{"it":"T deve essere una slice","en":"T must be a slice"},{"it":"T è una costante","en":"T is a constant"}]',0,'{"it":"Numeri e stringhe soddisfano il vincolo.","en":"Numbers and strings satisfy the constraint."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'generics'),2,2,'{"it":"Quale vincolo accetta qualsiasi tipo?","en":"Which constraint accepts any type?"}','[{"it":"comparable","en":"comparable"},{"it":"any","en":"any"},{"it":"interface{ int }","en":"interface{ int }"},{"it":"cmp.Ordered","en":"cmp.Ordered"}]',1,'{"it":"`any` è un altro nome di `interface{}`.","en":"`any` is another name for `interface{}`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'generics'),3,2,'{"it":"Che cosa include `~int` in un vincolo?","en":"What does `~int` include in a constraint?"}','[{"it":"Solo int","en":"Only int"},{"it":"Tutti i numeri","en":"All numbers"},{"it":"int e i tipi definiti sopra int, come type Euro int","en":"int and types defined on int, such as type Euro int"},{"it":"Gli int negativi","en":"Negative ints"}]',2,'{"it":"La tilde guarda al tipo sottostante.","en":"The tilde looks at the underlying type."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'errors-advanced'),1,2,'{"it":"Perché usare `errors.Is` invece di `err == ErrNonTrovato`?","en":"Why use `errors.Is` instead of `err == ErrNonTrovato`?"}','[{"it":"È più veloce","en":"It is faster"},{"it":"Trova l’errore anche quando è avvolto con %w","en":"It finds the error even when wrapped with %w"},{"it":"Funziona solo con i panic","en":"It only works with panics"},{"it":"Converte l’errore in stringa","en":"It converts the error to a string"}]',1,'{"it":"`==` vede solo l’errore più esterno.","en":"`==` only sees the outermost error."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'errors-advanced'),2,2,'{"it":"Che cosa serve per creare un tipo errore?","en":"What do you need to create an error type?"}','[{"it":"Ereditare da Exception","en":"Inheriting from Exception"},{"it":"La parola chiave errortype","en":"The errortype keyword"},{"it":"Un campo Message","en":"A Message field"},{"it":"Un metodo Error() string","en":"An Error() string method"}]',3,'{"it":"Così soddisfa l’interfaccia `error`.","en":"That way it satisfies the `error` interface."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'errors-advanced'),3,2,'{"it":"Quando usare `panic`?","en":"When should you use `panic`?"}','[{"it":"Per ogni file che non si apre","en":"For every file that will not open"},{"it":"Per i dati sbagliati inseriti dall’utente","en":"For wrong data entered by the user"},{"it":"Per un bug irrecuperabile del programma","en":"For an unrecoverable bug in the program"},{"it":"Mai, in Go non esiste","en":"Never, it does not exist in Go"}]',2,'{"it":"Gli errori previsti si restituiscono come `error`.","en":"Expected errors are returned as `error`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'embedding'),1,2,'{"it":"Come si incorpora `Registro` in `Servizio`?","en":"How do you embed `Registro` in `Servizio`?"}','[{"it":"Servizio extends Registro","en":"Servizio extends Registro"},{"it":"Con un campo senza nome di tipo Registro nella struct","en":"With an unnamed field of type Registro in the struct"},{"it":"implements Registro","en":"implements Registro"},{"it":"import Registro","en":"import Registro"}]',1,'{"it":"Basta scrivere il tipo da solo.","en":"Writing the type on its own is enough."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'embedding'),2,2,'{"it":"Che cosa significa che un metodo è “promosso”?","en":"What does it mean that a method is “promoted”?"}','[{"it":"Diventa pubblico","en":"It becomes public"},{"it":"Viene eseguito per primo","en":"It runs first"},{"it":"Si può chiamare direttamente sulla struct esterna","en":"It can be called directly on the outer struct"},{"it":"Diventa statico","en":"It becomes static"}]',2,'{"it":"Senza scrivere il campo intermedio.","en":"Without writing the intermediate field."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'embedding'),3,2,'{"it":"Che cosa fa `interface { io.Reader; io.Writer }`?","en":"What does `interface { io.Reader; io.Writer }` do?"}','[{"it":"Unisce i metodi delle due interfacce","en":"Combines the methods of both interfaces"},{"it":"Sceglie una delle due interfacce","en":"Picks one of the two interfaces"},{"it":"Crea due interfacce separate","en":"Creates two separate interfaces"},{"it":"Dà errore di compilazione","en":"Causes a compile error"}]',0,'{"it":"È esattamente `io.ReadWriter`.","en":"It is exactly `io.ReadWriter`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'select-context'),1,2,'{"it":"Che cosa fa `select`?","en":"What does `select` do?"}','[{"it":"Sceglie un elemento a caso da una slice","en":"Picks a random item from a slice"},{"it":"Aspetta su più canali e prosegue con il primo pronto","en":"Waits on several channels and goes on with the first ready"},{"it":"Filtra le righe di un database","en":"Filters database rows"},{"it":"Chiude tutti i canali","en":"Closes every channel"}]',1,'{"it":"Come uno switch per i canali.","en":"Like a switch for channels."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'select-context'),2,2,'{"it":"Dove va il `context.Context` in una funzione?","en":"Where does `context.Context` go in a function?"}','[{"it":"Come ultimo parametro","en":"As the last parameter"},{"it":"In una variabile globale","en":"In a global variable"},{"it":"Come primo parametro, di solito chiamato ctx","en":"As the first parameter, usually called ctx"},{"it":"Sempre dentro una struct","en":"Always inside a struct"}]',2,'{"it":"È una convenzione seguita da tutta la libreria standard.","en":"It is a convention followed by the whole standard library."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'select-context'),3,2,'{"it":"Perché scrivere `defer cancel()`?","en":"Why write `defer cancel()`?"}','[{"it":"Per rilasciare le risorse del context anche se si finisce prima","en":"To release the context’s resources even when finishing early"},{"it":"Per annullare subito la richiesta","en":"To cancel the request at once"},{"it":"Per riavviare il timer","en":"To restart the timer"},{"it":"Non serve a niente","en":"It serves no purpose"}]',0,'{"it":"`go vet` segnala un cancel dimenticato.","en":"`go vet` flags a forgotten cancel."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'sync'),1,3,'{"it":"Che cosa fa `mu.Lock()`?","en":"What does `mu.Lock()` do?"}','[{"it":"Blocca il programma per sempre","en":"Blocks the program forever"},{"it":"Lascia entrare una sola goroutine alla volta nella sezione","en":"Lets only one goroutine at a time into the section"},{"it":"Chiude il canale","en":"Closes the channel"},{"it":"Cifra i dati","en":"Encrypts the data"}]',1,'{"it":"Le altre aspettano l’Unlock.","en":"The others wait for Unlock."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'sync'),2,3,'{"it":"A che cosa serve `go test -race`?","en":"What is `go test -race` for?"}','[{"it":"A eseguire i test più in fretta","en":"Running tests faster"},{"it":"A misurare la memoria","en":"Measuring memory"},{"it":"A lanciare i test in ordine casuale","en":"Running tests in random order"},{"it":"A trovare accessi concorrenti non protetti","en":"Finding unprotected concurrent access"}]',3,'{"it":"Le data race sono bug difficili da riprodurre.","en":"Data races are bugs that are hard to reproduce."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'sync'),3,3,'{"it":"Una `map` normale è sicura se più goroutine la scrivono insieme?","en":"Is a plain `map` safe if several goroutines write it at once?"}','[{"it":"Sì, sempre","en":"Yes, always"},{"it":"Solo se è piccola","en":"Only if it is small"},{"it":"No: serve un mutex o sync.Map","en":"No: it needs a mutex or sync.Map"},{"it":"Solo con chiavi stringa","en":"Only with string keys"}]',2,'{"it":"Il runtime può anche fermare il programma con un errore fatale.","en":"The runtime may even stop the program with a fatal error."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'io'),1,3,'{"it":"Perché `contaRighe` accetta un `io.Reader` invece di un `*os.File`?","en":"Why does `contaRighe` accept an `io.Reader` instead of an `*os.File`?"}','[{"it":"Perché è più veloce","en":"Because it is faster"},{"it":"Funziona con file, stringhe e rete, e si testa facilmente","en":"It works with files, strings and network, and is easy to test"},{"it":"Perché os.File non si può leggere","en":"Because os.File cannot be read"},{"it":"Perché lo impone il compilatore","en":"Because the compiler requires it"}]',1,'{"it":"Chiedi il minimo indispensabile.","en":"Ask for the bare minimum."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'io'),2,3,'{"it":"Quale funzione legge un file intero?","en":"Which function reads a whole file?"}','[{"it":"os.ReadFile","en":"os.ReadFile"},{"it":"io.ReadAll(path)","en":"io.ReadAll(path)"},{"it":"bufio.Read","en":"bufio.Read"},{"it":"os.Open","en":"os.Open"}]',0,'{"it":"`os.Open` apre soltanto.","en":"`os.Open` only opens."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'io'),3,3,'{"it":"Che cosa fa `json.Unmarshal(dati, &cfg)`?","en":"What does `json.Unmarshal(dati, &cfg)` do?"}','[{"it":"Scrive cfg in un file JSON","en":"Writes cfg to a JSON file"},{"it":"Converte cfg in testo","en":"Converts cfg to text"},{"it":"Riempie cfg con i valori del JSON","en":"Fills cfg with the JSON’s values"},{"it":"Controlla solo che il JSON sia valido","en":"Only checks that the JSON is valid"}]',2,'{"it":"Per questo serve il puntatore.","en":"That is why the pointer is needed."}',NULL);
