INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'iterators'),2,3,'{"it":"Che cosa significa `yield` che restituisce `false`?","en":"What does `yield` returning `false` mean?"}','[{"it":"Che il valore non era valido","en":"That the value was not valid"},{"it":"Che il ciclo è stato interrotto e bisogna fermarsi","en":"That the loop was interrupted and you must stop"},{"it":"Che la slice è vuota","en":"That the slice is empty"},{"it":"Che c’è stato un errore di rete","en":"That there was a network error"}]',1,'{"it":"Continuare a chiamare yield causerebbe un panic.","en":"Calling yield again would cause a panic."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'iterators'),3,3,'{"it":"Come ottieni le chiavi di una mappa in ordine?","en":"How do you get a map’s keys in order?"}','[{"it":"slices.Sorted(maps.Keys(m))","en":"slices.Sorted(maps.Keys(m))"},{"it":"sort(m.keys())","en":"sort(m.keys())"},{"it":"maps.Keys(m).Sort()","en":"maps.Keys(m).Sort()"},{"it":"range m sorted","en":"range m sorted"}]',0,'{"it":"`maps.Keys` dà un iteratore, `slices.Sorted` lo raccoglie ordinato.","en":"`maps.Keys` gives an iterator, `slices.Sorted` collects it sorted."}',NULL);
