INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'go-intermediate' AND slug = 'benchmarks'),3,3,'{"it":"A che cosa serve il fuzzing?","en":"What is fuzzing for?"}','[{"it":"A formattare il codice","en":"Formatting code"},{"it":"A generare input inattesi per trovare bug","en":"Generating unexpected inputs to find bugs"},{"it":"A misurare la memoria","en":"Measuring memory"},{"it":"A rendere i test più leggibili","en":"Making tests more readable"}]',1,'{"it":"Gli input che falliscono vengono salvati per ripetere il test.","en":"Failing inputs are saved to repeat the test."}',NULL);
