INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-base' AND slug = 'methods'),2,2,'{"it":"Che cosa fa `Saluta(\\"Bea\\", saluto: \\"Hey\\")`?","en":"What does `Saluta(\\"Bea\\", saluto: \\"Hey\\")` do?"}','[{"it":"Passa il parametro saluto per nome","en":"Passes the saluto parameter by name"},{"it":"Crea una variabile globale","en":"Creates a global variable"},{"it":"Dà errore perché l’ordine è sbagliato","en":"Fails because the order is wrong"},{"it":"Ignora il secondo argomento","en":"Ignores the second argument"}]',0,'{"it":"Rende chiare le chiamate con molti parametri.","en":"It makes calls with many parameters clear."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-base' AND slug = 'methods'),3,2,'{"it":"Che cosa significa `static double Area(double b, double h) => b * h;`?","en":"What does `static double Area(double b, double h) => b * h;` mean?"}','[{"it":"Un campo di sola lettura","en":"A read-only field"},{"it":"Una lambda salvata in una variabile","en":"A lambda stored in a variable"},{"it":"Un metodo che restituisce b * h, in forma breve","en":"A method returning b * h, in short form"},{"it":"Una proprietà calcolata","en":"A computed property"}]',2,'{"it":"`=>` sostituisce `{ return …; }`.","en":"`=>` replaces `{ return …; }`."}',NULL);
