INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-base' AND slug = 'inheritance'),2,2,'{"it":"Che cosa deve fare una classe figlia con un metodo `abstract`?","en":"What must a child class do with an `abstract` method?"}','[{"it":"Niente, è facoltativo","en":"Nothing, it is optional"},{"it":"Scriverlo con override","en":"Write it with override"},{"it":"Chiamarlo nel costruttore","en":"Call it in the constructor"},{"it":"Renderlo static","en":"Make it static"}]',1,'{"it":"Altrimenti anche la figlia deve essere astratta.","en":"Otherwise the child must be abstract too."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-base' AND slug = 'inheritance'),3,2,'{"it":"Quante interfacce può implementare una classe?","en":"How many interfaces can a class implement?"}','[{"it":"Una sola","en":"Only one"},{"it":"Al massimo due","en":"At most two"},{"it":"Nessuna, solo le struct possono","en":"None, only structs can"},{"it":"Quante ne vuole","en":"As many as it likes"}]',3,'{"it":"Separate da virgole dopo la classe base.","en":"Separated by commas after the base class."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-base' AND slug = 'exceptions'),1,2,'{"it":"In che ordine vanno i blocchi `catch`?","en":"In what order do `catch` blocks go?"}','[{"it":"Dal più specifico al più generico","en":"From the most specific to the most general"},{"it":"Dal più generico al più specifico","en":"From the most general to the most specific"},{"it":"In ordine alfabetico","en":"In alphabetical order"},{"it":"L’ordine non conta","en":"Order does not matter"}]',0,'{"it":"Un `catch (Exception)` in cima catturerebbe tutto.","en":"A `catch (Exception)` at the top would catch everything."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-base' AND slug = 'exceptions'),2,2,'{"it":"Che cosa fa `using var f = ...;`?","en":"What does `using var f = ...;` do?"}','[{"it":"Importa uno spazio dei nomi","en":"Imports a namespace"},{"it":"Rende f immutabile","en":"Makes f immutable"},{"it":"Crea una copia di f","en":"Creates a copy of f"},{"it":"Chiude la risorsa da sola alla fine del blocco","en":"Closes the resource by itself at the end of the block"}]',3,'{"it":"Anche se nel frattempo arriva un’eccezione.","en":"Even if an exception arrives meanwhile."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-base' AND slug = 'exceptions'),3,2,'{"it":"Che differenza c’è tra `throw;` e `throw ex;` in un catch?","en":"What is the difference between `throw;` and `throw ex;` in a catch?"}','[{"it":"Nessuna","en":"None"},{"it":"`throw;` mantiene la traccia originale dello stack","en":"`throw;` keeps the original stack trace"},{"it":"`throw ex;` è più veloce","en":"`throw ex;` is faster"},{"it":"`throw;` ignora l’eccezione","en":"`throw;` ignores the exception"}]',1,'{"it":"La traccia dice dove è nato l’errore.","en":"The trace tells where the error began."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'generics'),1,2,'{"it":"Che cosa significa `where T : IComparable<T>`?","en":"What does `where T : IComparable<T>` mean?"}','[{"it":"T deve essere un intero","en":"T must be an integer"},{"it":"T deve implementare IComparable<T>","en":"T must implement IComparable<T>"},{"it":"T deve essere una classe astratta","en":"T must be an abstract class"},{"it":"T deve avere un costruttore vuoto","en":"T must have an empty constructor"}]',1,'{"it":"Così dentro il metodo si può chiamare CompareTo.","en":"So inside the method you can call CompareTo."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'generics'),2,2,'{"it":"Che cosa dà `lista[^1]`?","en":"What does `lista[^1]` give?"}','[{"it":"Il primo elemento","en":"The first item"},{"it":"Un errore di sintassi","en":"A syntax error"},{"it":"La lunghezza della lista","en":"The list’s length"},{"it":"L’ultimo elemento","en":"The last item"}]',3,'{"it":"`^` conta dalla fine.","en":"`^` counts from the end."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'generics'),3,2,'{"it":"Si può scrivere `List<int>` in C#?","en":"Can you write `List<int>` in C#?"}','[{"it":"Sì, e i valori int sono salvati senza boxing","en":"Yes, and the int values are stored without boxing"},{"it":"No, serve List<Integer>","en":"No, it needs List<Integer>"},{"it":"Solo nel codice unsafe","en":"Only in unsafe code"},{"it":"Solo nelle versioni vecchie","en":"Only in old versions"}]',0,'{"it":"Una differenza importante rispetto a Java.","en":"An important difference from Java."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'delegates-events'),1,2,'{"it":"In `Func<int, string>`, che cosa è `string`?","en":"In `Func<int, string>`, what is `string`?"}','[{"it":"Il tipo del parametro","en":"The parameter type"},{"it":"Il tipo restituito","en":"The return type"},{"it":"Il nome della funzione","en":"The function’s name"},{"it":"Un vincolo generico","en":"A generic constraint"}]',1,'{"it":"L’ultimo tipo è sempre il risultato.","en":"The last type is always the result."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'delegates-events'),2,2,'{"it":"Che differenza c’è tra `Action` e `Func`?","en":"What is the difference between `Action` and `Func`?"}','[{"it":"Action non restituisce nulla, Func restituisce un valore","en":"Action returns nothing, Func returns a value"},{"it":"Func è più veloce","en":"Func is faster"},{"it":"Action accetta solo stringhe","en":"Action only takes strings"},{"it":"Nessuna","en":"None"}]',0,'{"it":"Action è come un metodo void.","en":"Action is like a void method."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'delegates-events'),3,2,'{"it":"Come ci si iscrive a un evento?","en":"How do you subscribe to an event?"}','[{"it":"evento = gestore","en":"evento = gestore"},{"it":"evento.Add(gestore)","en":"evento.Add(gestore)"},{"it":"evento += gestore","en":"evento += gestore"},{"it":"subscribe(evento, gestore)","en":"subscribe(evento, gestore)"}]',2,'{"it":"E con `-=` ci si disiscrive.","en":"And `-=` unsubscribes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'linq-advanced'),1,2,'{"it":"Che cosa contiene `g.Key` dentro un `GroupBy`?","en":"What does `g.Key` hold inside a `GroupBy`?"}','[{"it":"Il primo elemento del gruppo","en":"The group’s first item"},{"it":"Il valore della chiave di raggruppamento","en":"The value of the grouping key"},{"it":"Il numero di elementi","en":"The number of items"},{"it":"L’indice del gruppo","en":"The group’s index"}]',1,'{"it":"Il gruppo stesso si scorre come una sequenza.","en":"The group itself is iterated like a sequence."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'linq-advanced'),2,2,'{"it":"Che cosa fanno `Skip(20).Take(10)`?","en":"What do `Skip(20).Take(10)` do?"}','[{"it":"Saltano 20 elementi e ne prendono 10","en":"Skip 20 items and take 10"},{"it":"Prendono 20 elementi e ne saltano 10","en":"Take 20 items and skip 10"},{"it":"Ripetono la query 10 volte","en":"Repeat the query 10 times"},{"it":"Ordinano gli elementi dal 20 al 30","en":"Sort items 20 to 30"}]',0,'{"it":"La terza pagina da 10 elementi.","en":"The third page of 10 items."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'linq-advanced'),3,2,'{"it":"Quando viene eseguita una query LINQ su una lista?","en":"When does a LINQ query on a list run?"}','[{"it":"Quando viene scritta","en":"When it is written"},{"it":"Solo al riavvio dell’app","en":"Only when the app restarts"},{"it":"Quando la scorri o la materializzi, ad esempio con ToList","en":"When you iterate or materialise it, for example with ToList"},{"it":"Mai, LINQ prepara solo SQL","en":"Never, LINQ only prepares SQL"}]',2,'{"it":"È l’esecuzione differita.","en":"That is deferred execution."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'ef-core'),1,2,'{"it":"Che cosa fa EF Core con una query LINQ su un DbSet?","en":"What does EF Core do with a LINQ query on a DbSet?"}','[{"it":"La esegue in memoria su tutte le righe","en":"Runs it in memory over every row"},{"it":"La traduce in SQL e la esegue nel database","en":"Translates it to SQL and runs it in the database"},{"it":"La salva in un file","en":"Saves it to a file"},{"it":"La manda a un servizio esterno","en":"Sends it to an external service"}]',1,'{"it":"Arrivano solo le righe che servono.","en":"Only the rows you need come back."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'ef-core'),2,2,'{"it":"A che cosa servono le migrazioni?","en":"What are migrations for?"}','[{"it":"A spostare il database su un altro server","en":"Moving the database to another server"},{"it":"A fare il backup dei dati","en":"Backing up the data"},{"it":"A tenere la struttura del database allineata alle classi","en":"Keeping the database structure in step with the classes"},{"it":"A cifrare le colonne","en":"Encrypting columns"}]',2,'{"it":"Ogni migrazione è un passo che si può applicare o annullare.","en":"Each migration is a step you can apply or undo."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'ef-core'),3,2,'{"it":"Che cosa fa `SaveChangesAsync()`?","en":"What does `SaveChangesAsync()` do?"}','[{"it":"Scrive nel database le modifiche tracciate","en":"Writes the tracked changes to the database"},{"it":"Ricarica tutte le tabelle","en":"Reloads every table"},{"it":"Annulla le modifiche","en":"Undoes the changes"},{"it":"Crea una migrazione","en":"Creates a migration"}]',0,'{"it":"Tutte insieme, in una transazione.","en":"All together, in one transaction."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'dependency-injection'),1,3,'{"it":"Quale durata crea un oggetto per ogni richiesta HTTP?","en":"Which lifetime creates one object per HTTP request?"}','[{"it":"Singleton","en":"Singleton"},{"it":"Transient","en":"Transient"},{"it":"Scoped","en":"Scoped"},{"it":"Static","en":"Static"}]',2,'{"it":"Il DbContext di solito è Scoped.","en":"The DbContext is usually Scoped."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'dependency-injection'),2,3,'{"it":"Perché registrare un’interfaccia invece della classe concreta?","en":"Why register an interface instead of the concrete class?"}','[{"it":"È obbligatorio in C#","en":"It is required in C#"},{"it":"Si può sostituire l’implementazione, ad esempio nei test","en":"You can swap the implementation, for example in tests"},{"it":"Rende il codice più veloce","en":"It makes code faster"},{"it":"Evita di scrivere il costruttore","en":"It avoids writing the constructor"}]',1,'{"it":"Il codice dipende dal contratto, non dai dettagli.","en":"Code depends on the contract, not the details."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'dependency-injection'),3,3,'{"it":"Dove si mettono le password in sviluppo, senza finire nel repository?","en":"Where do passwords go in development, without ending up in the repository?"}','[{"it":"In Program.cs","en":"In Program.cs"},{"it":"In un appsettings.json pubblicato","en":"In a published appsettings.json"},{"it":"In un commento nel codice","en":"In a code comment"},{"it":"Negli user secrets o nelle variabili d’ambiente","en":"In user secrets or environment variables"}]',3,'{"it":"Si gestiscono con `dotnet user-secrets`.","en":"You manage them with `dotnet user-secrets`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'async-advanced'),1,3,'{"it":"Che cosa fa `await Task.WhenAll(a, b)`?","en":"What does `await Task.WhenAll(a, b)` do?"}','[{"it":"Esegue a e poi b, uno dopo l’altro","en":"Runs a and then b, one after the other"},{"it":"Aspetta che finiscano entrambi, eseguiti insieme","en":"Waits for both to finish, run together"},{"it":"Aspetta solo il primo che finisce","en":"Waits only for the first to finish"},{"it":"Annulla entrambi","en":"Cancels both"}]',1,'{"it":"Per il primo che finisce c’è `Task.WhenAny`.","en":"For the first to finish there is `Task.WhenAny`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'async-advanced'),2,3,'{"it":"A che cosa serve un `CancellationToken`?","en":"What is a `CancellationToken` for?"}','[{"it":"A segnalare che un’operazione va annullata","en":"Signalling that an operation should be cancelled"},{"it":"A cifrare la richiesta","en":"Encrypting the request"},{"it":"A contare i Task","en":"Counting Tasks"},{"it":"A misurare il tempo","en":"Measuring time"}]',0,'{"it":"Il metodo che lo riceve decide quando fermarsi.","en":"The method receiving it decides when to stop."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'async-advanced'),3,3,'{"it":"Come si scorre un `IAsyncEnumerable<T>`?","en":"How do you iterate an `IAsyncEnumerable<T>`?"}','[{"it":"foreach async","en":"foreach async"},{"it":"for await","en":"for await"},{"it":"await foreach","en":"await foreach"},{"it":"Parallel.ForEach","en":"Parallel.ForEach"}]',2,'{"it":"Ogni giro può attendere il valore successivo.","en":"Each round can await the next value."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'xunit'),1,3,'{"it":"Che differenza c’è tra `[Fact]` e `[Theory]`?","en":"What is the difference between `[Fact]` and `[Theory]`?"}','[{"it":"Theory ripete il test con dati diversi","en":"Theory repeats the test with different data"},{"it":"Fact è più lento","en":"Fact is slower"},{"it":"Theory non usa Assert","en":"Theory does not use Assert"},{"it":"Nessuna","en":"None"}]',0,'{"it":"I dati arrivano da `[InlineData]`.","en":"The data comes from `[InlineData]`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'xunit'),2,3,'{"it":"Come verifichi che venga lanciata un’eccezione?","en":"How do you check an exception is thrown?"}','[{"it":"Assert.Error","en":"Assert.Error"},{"it":"Assert.Catch","en":"Assert.Catch"},{"it":"Expect.Exception","en":"Expect.Exception"},{"it":"Assert.Throws<T>(...)","en":"Assert.Throws<T>(...)"}]',3,'{"it":"Riceve una lambda con il codice da provare.","en":"It takes a lambda with the code to try."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'xunit'),3,3,'{"it":"Quale comando esegue i test?","en":"Which command runs the tests?"}','[{"it":"dotnet run --tests","en":"dotnet run --tests"},{"it":"dotnet test","en":"dotnet test"},{"it":"dotnet check","en":"dotnet check"},{"it":"dotnet xunit","en":"dotnet xunit"}]',1,'{"it":"Trova i progetti di test e li esegue.","en":"It finds the test projects and runs them."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'modern-csharp'),1,3,'{"it":"Che cosa crea `int[] tutti = [..a, ..b];`?","en":"What does `int[] tutti = [..a, ..b];` create?"}','[{"it":"Un array con gli elementi di a seguiti da quelli di b","en":"An array with a’s items followed by b’s"},{"it":"Un array di due array","en":"An array of two arrays"},{"it":"Un intervallo da a a b","en":"A range from a to b"},{"it":"Un errore di sintassi","en":"A syntax error"}]',0,'{"it":"`..` espande una sequenza dentro un’altra.","en":"`..` spreads one sequence into another."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'modern-csharp'),2,3,'{"it":"A che cosa serve `field` in un accessor di proprietà (C# 14)?","en":"What is `field` for in a property accessor (C# 14)?"}','[{"it":"Dichiara un nuovo campo pubblico","en":"Declares a new public field"},{"it":"Indica il campo nascosto creato dal compilatore per la proprietà","en":"Refers to the hidden field the compiler creates for the property"},{"it":"Rende la proprietà statica","en":"Makes the property static"},{"it":"Legge un valore dal database","en":"Reads a value from the database"}]',1,'{"it":"Niente più campo privato scritto a mano.","en":"No more hand-written private field."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'modern-csharp'),3,3,'{"it":"Che cosa permette un blocco `extension(string s)`?","en":"What does an `extension(string s)` block allow?"}','[{"it":"Ereditare dalla classe string","en":"Inheriting from the string class"},{"it":"Modificare il codice sorgente di .NET","en":"Changing .NET’s source code"},{"it":"Aggiungere metodi e proprietà al tipo string senza modificarlo","en":"Adding methods and properties to string without changing it"},{"it":"Creare una sottoclasse anonima","en":"Creating an anonymous subclass"}]',2,'{"it":"Si usano come se fossero del tipo stesso.","en":"They are used as if they belonged to the type itself."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'hello'),1,2,'{"it":"Che cosa fa `#include <stdio.h>`?","en":"What does `#include <stdio.h>` do?"}','[{"it":"Include le funzioni di input/output","en":"Includes input/output functions"},{"it":"Crea un file","en":"Creates a file"},{"it":"Avvia il programma","en":"Starts the program"},{"it":"Commenta il codice","en":"Comments the code"}]',0,'{"it":"Come printf.","en":"Like printf."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'hello'),2,2,'{"it":"Che cosa significa `return 0` in main?","en":"What does `return 0` in main mean?"}','[{"it":"Il programma è terminato con successo","en":"The program ended successfully"},{"it":"Errore grave: il programma va riavviato","en":"Serious error: the program must restart"},{"it":"Ricomincia","en":"Restart"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Diverso da 0 = errore.","en":"Non-zero = error."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'hello'),3,2,'{"it":"Perché compilare con -Wall -Wextra?","en":"Why compile with -Wall -Wextra?"}','[{"it":"Per vedere gli avvisi su possibili errori","en":"To see warnings about possible mistakes"},{"it":"Per rendere il programma più lento","en":"To make the program slower"},{"it":"Per cifrarlo","en":"To encrypt it"},{"it":"Non serve","en":"It is not needed"}]',0,'{"it":"Avvisi gratis.","en":"Free warnings."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'types'),1,2,'{"it":"Quanto fa `7 / 2` tra interi in C?","en":"What is `7 / 2` between integers in C?"}','[{"it":"3","en":"3"},{"it":"3.5","en":"3.5"},{"it":"4","en":"4"},{"it":"Errore","en":"Error"}]',0,'{"it":"La parte decimale si perde.","en":"The decimal part is lost."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'types'),2,2,'{"it":"Quale segnaposto stampa un intero?","en":"Which placeholder prints an integer?"}','[{"it":"%d","en":"%d"},{"it":"%s","en":"%s"},{"it":"%f","en":"%f"},{"it":"%c","en":"%c"}]',0,'{"it":"d = decimal integer.","en":"d = decimal integer."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'types'),3,2,'{"it":"Che cosa è falso in una condizione C?","en":"What is false in a C condition?"}','[{"it":"0","en":"0"},{"it":"1","en":"1"},{"it":"-1","en":"-1"},{"it":"42","en":"42"}]',0,'{"it":"Tutto il resto è vero.","en":"Everything else is true."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'arrays'),1,2,'{"it":"Qual è l’indice dell’ultimo elemento di `int v[5]`?","en":"What is the index of the last element of `int v[5]`?"}','[{"it":"4","en":"4"},{"it":"5","en":"5"},{"it":"6","en":"6"},{"it":"0","en":"0"}]',0,'{"it":"Si parte da 0.","en":"It starts from 0."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'arrays'),2,2,'{"it":"Con che cosa finisce una stringa C?","en":"What does a C string end with?"}','[{"it":"Con il carattere nullo \\\\0","en":"With the null character \\\\0"},{"it":"Con un punto","en":"With a full stop"},{"it":"Con \\\\n","en":"With \\\\n"},{"it":"Con niente","en":"With nothing"}]',0,'{"it":"Un byte in più.","en":"One extra byte."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'arrays'),3,2,'{"it":"Che cos’è un buffer overflow?","en":"What is a buffer overflow?"}','[{"it":"Scrivere oltre la fine di un array","en":"Writing past the end of an array"},{"it":"Un file troppo grande","en":"A file too big"},{"it":"Una rete lenta","en":"A slow network"},{"it":"Un tipo di ciclo","en":"A kind of loop"}]',0,'{"it":"C non controlla i limiti.","en":"C does not check bounds."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'pointers'),1,2,'{"it":"Che cosa dà `&x`?","en":"What does `&x` give?"}','[{"it":"L’indirizzo di x","en":"The address of x"},{"it":"Il valore di x","en":"The value of x"},{"it":"x raddoppiato","en":"x doubled"},{"it":"Un errore","en":"An error"}]',0,'{"it":"`*p` legge il valore.","en":"`*p` reads the value."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'pointers'),2,2,'{"it":"Che cosa succede se dimentichi `free`?","en":"What happens if you forget `free`?"}','[{"it":"Un memory leak","en":"A memory leak"},{"it":"Niente","en":"Nothing"},{"it":"Il programma è più veloce","en":"The program is faster"},{"it":"Il file si cancella","en":"The file is deleted"}]',0,'{"it":"Memoria persa.","en":"Lost memory."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'pointers'),3,2,'{"it":"Che cosa controllare dopo `malloc`?","en":"What should you check after `malloc`?"}','[{"it":"Che non abbia restituito NULL","en":"That it did not return NULL"},{"it":"Il colore","en":"The colour"},{"it":"Niente","en":"Nothing"},{"it":"Che sia zero","en":"That it is zero"}]',0,'{"it":"La memoria può finire.","en":"Memory can run out."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'structs-files'),1,2,'{"it":"Che cosa restituisce `malloc` se fallisce?","en":"What does `malloc` return if it fails?"}','[{"it":"NULL","en":"NULL"},{"it":"0 byte","en":"0 byte"},{"it":"-1","en":"-1"},{"it":"Un errore di compilazione","en":"A compile error"}]',0,'{"it":"Controllalo sempre.","en":"Always check it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'structs-files'),2,2,'{"it":"Che cosa succede senza `free`?","en":"What happens without `free`?"}','[{"it":"Una perdita di memoria","en":"A memory leak"},{"it":"Il programma è più veloce","en":"The program is faster"},{"it":"Niente mai","en":"Never anything"},{"it":"Il file si chiude","en":"The file closes"}]',0,'{"it":"Memory leak.","en":"Memory leak."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'structs-files'),3,2,'{"it":"Come raggiungi un campo da un puntatore a struct?","en":"How do you reach a field from a pointer to a struct?"}','[{"it":"p->x","en":"p->x"},{"it":"p.x","en":"p.x"},{"it":"p::x","en":"p::x"},{"it":"p[x]","en":"p[x]"}]',0,'{"it":"`->` equivale a `(*p).x`.","en":"`->` equals `(*p).x`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'functions'),1,3,'{"it":"Se `prova` assegna 100 al suo parametro, quanto vale `x` dopo `prova(x)`?","en":"If `prova` assigns 100 to its parameter, what is `x` after `prova(x)`?"}','[{"it":"100","en":"100"},{"it":"5","en":"5"},{"it":"0","en":"0"},{"it":"Un valore casuale","en":"A random value"}]',1,'{"it":"La funzione ha cambiato solo la sua copia.","en":"The function changed only its own copy."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'functions'),2,3,'{"it":"A che cosa serve un prototipo come `double media(int a, int b);`?","en":"What is a prototype like `double media(int a, int b);` for?"}','[{"it":"A dichiarare la funzione prima di usarla","en":"Declaring the function before using it"},{"it":"A renderla più veloce","en":"Making it faster"},{"it":"A renderla privata del file","en":"Making it private to the file"},{"it":"A eseguirla all’avvio","en":"Running it at start-up"}]',0,'{"it":"Così il compilatore conosce tipi e parametri.","en":"That way the compiler knows its types and parameters."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'functions'),3,3,'{"it":"Che cosa fa `static` davanti a una variabile locale?","en":"What does `static` do in front of a local variable?"}','[{"it":"La rende costante","en":"Makes it constant"},{"it":"La mette nello heap","en":"Puts it on the heap"},{"it":"La rende visibile a tutto il programma","en":"Makes it visible to the whole program"},{"it":"Le fa conservare il valore tra una chiamata e l’altra","en":"Makes it keep its value between calls"}]',3,'{"it":"Viene inizializzata una volta sola.","en":"It is initialised only once."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'input'),1,3,'{"it":"Perché si usa `fgets` e non `gets`?","en":"Why use `fgets` and not `gets`?"}','[{"it":"`fgets` è più veloce","en":"`fgets` is faster"},{"it":"`gets` legge solo numeri","en":"`gets` reads only numbers"},{"it":"`gets` non conosce la dimensione del buffer ed è stata tolta dal linguaggio","en":"`gets` does not know the buffer size and was removed from the language"},{"it":"Non c’è nessuna differenza","en":"There is no difference at all"}]',2,'{"it":"`gets` è sparita con il C11.","en":"`gets` was removed in C11."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'input'),2,3,'{"it":"Che cosa restituisce `scanf(\\"%d\\", &n)` se l’utente scrive «ciao»?","en":"What does `scanf(\\"%d\\", &n)` return if the user types “ciao”?"}','[{"it":"0","en":"0"},{"it":"1","en":"1"},{"it":"-1","en":"-1"},{"it":"Il numero 0 messo in n","en":"The number 0 stored in n"}]',0,'{"it":"Nessun campo letto; `n` resta com’era.","en":"No field read; `n` stays as it was."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'input'),3,3,'{"it":"A che cosa serve il secondo argomento di `strtol(riga, &fine, 10)`?","en":"What is the second argument of `strtol(riga, &fine, 10)` for?"}','[{"it":"A indicare la base del numero","en":"Giving the number’s base"},{"it":"A dire dove si è fermata la conversione","en":"Telling where the conversion stopped"},{"it":"A fissare la lunghezza massima","en":"Setting the maximum length"},{"it":"A ignorare gli spazi","en":"Ignoring spaces"}]',1,'{"it":"La base è il terzo argomento, 10.","en":"The base is the third argument, 10."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'strings'),1,3,'{"it":"Come controlli se due stringhe C sono uguali?","en":"How do you check whether two C strings are equal?"}','[{"it":"a == b","en":"a == b"},{"it":"strcmp(a, b) == 0","en":"strcmp(a, b) == 0"},{"it":"a.equals(b)","en":"a.equals(b)"},{"it":"strlen(a) == strlen(b)","en":"strlen(a) == strlen(b)"}]',1,'{"it":"`==` confronta gli indirizzi, non il testo.","en":"`==` compares addresses, not the text."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'strings'),2,3,'{"it":"Quanto vale `strlen(\\"ciao\\")`?","en":"What is `strlen(\\"ciao\\")`?"}','[{"it":"5","en":"5"},{"it":"3","en":"3"},{"it":"4","en":"4"},{"it":"Dipende dall’array","en":"It depends on the array"}]',2,'{"it":"Il terminatore non viene contato.","en":"The terminator is not counted."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'strings'),3,3,'{"it":"Che cosa restituisce `strchr` se il carattere non c’è?","en":"What does `strchr` return if the character is not there?"}','[{"it":"-1","en":"-1"},{"it":"0","en":"0"},{"it":"La lunghezza della stringa","en":"The string’s length"},{"it":"NULL","en":"NULL"}]',3,'{"it":"Restituisce un puntatore: `NULL` se non trova nulla.","en":"It returns a pointer: `NULL` when nothing is found."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'enums-typedef'),1,3,'{"it":"Quanto vale `GIALLO` in `enum { ROSSO, GIALLO, VERDE }`?","en":"What is `GIALLO` in `enum { ROSSO, GIALLO, VERDE }`?"}','[{"it":"0","en":"0"},{"it":"1","en":"1"},{"it":"2","en":"2"},{"it":"La stringa «GIALLO»","en":"The string “GIALLO”"}]',1,'{"it":"Si conta da 0.","en":"Counting starts at 0."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'enums-typedef'),2,3,'{"it":"A che cosa serve `typedef struct { … } Giocatore;`?","en":"What is `typedef struct { … } Giocatore;` for?"}','[{"it":"A usare `Giocatore` come nome del tipo, senza scrivere `struct`","en":"Using `Giocatore` as the type name, without writing `struct`"},{"it":"A creare una variabile globale","en":"Creating a global variable"},{"it":"A copiare una struct","en":"Copying a struct"},{"it":"A rendere costante la struct","en":"Making the struct constant"}]',0,'{"it":"È solo un nuovo nome per il tipo.","en":"It is just a new name for the type."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'enums-typedef'),3,3,'{"it":"Che cosa ha di speciale una `union`?","en":"What is special about a `union`?"}','[{"it":"Può contenere solo interi","en":"It can hold only integers"},{"it":"Si libera da sola","en":"It frees itself"},{"it":"È sempre più grande di una struct","en":"It is always larger than a struct"},{"it":"Tutti i campi condividono la stessa memoria","en":"All fields share the same memory"}]',3,'{"it":"È grande quanto il campo più grande.","en":"It is as large as its largest field."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'pointer-arithmetic'),1,2,'{"it":"A che cosa equivale `v[3]`?","en":"What is `v[3]` equivalent to?"}','[{"it":"*(v + 3)","en":"*(v + 3)"},{"it":"*v + 3","en":"*v + 3"},{"it":"&v + 3","en":"&v + 3"},{"it":"v * 3","en":"v * 3"}]',0,'{"it":"`*v + 3` sommerebbe 3 al primo elemento.","en":"`*v + 3` would add 3 to the first element."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'pointer-arithmetic'),2,2,'{"it":"`p` punta a un `int` all’indirizzo 1000 e un int occupa 4 byte: dove punta `p + 1`?","en":"`p` points to an `int` at address 1000 and an int takes 4 bytes: where does `p + 1` point?"}','[{"it":"1001","en":"1001"},{"it":"1004","en":"1004"},{"it":"1008","en":"1008"},{"it":"1000","en":"1000"}]',1,'{"it":"L’aritmetica dei puntatori conta in elementi.","en":"Pointer arithmetic counts in elements."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'pointer-arithmetic'),3,2,'{"it":"Perché una funzione che riceve un array ha bisogno anche della lunghezza?","en":"Why does a function receiving an array also need its length?"}','[{"it":"Per andare più veloce","en":"To run faster"},{"it":"Perché gli array C hanno sempre 10 elementi","en":"Because C arrays always have 10 elements"},{"it":"Perché il compilatore lo impone sempre","en":"Because the compiler always demands it"},{"it":"Perché riceve solo un puntatore e la dimensione si perde","en":"Because it receives only a pointer and the size is lost"}]',3,'{"it":"Per questo si usa la coppia puntatore e `size_t n`.","en":"That is why the pointer and `size_t n` pair is used."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'function-pointers'),1,2,'{"it":"Che cosa deve restituire la funzione di confronto di `qsort`?","en":"What must `qsort`’s comparison function return?"}','[{"it":"true o false","en":"true or false"},{"it":"Un numero negativo, zero o positivo","en":"A negative number, zero or a positive number"},{"it":"L’elemento più grande","en":"The larger element"},{"it":"L’indice dell’elemento","en":"The element’s index"}]',1,'{"it":"Negativo se a viene prima di b.","en":"Negative if a comes before b."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'function-pointers'),2,2,'{"it":"Come dichiari `p`, puntatore a una funzione che riceve un `double` e restituisce un `double`?","en":"How do you declare `p`, a pointer to a function taking a `double` and returning a `double`?"}','[{"it":"double *p(double);","en":"double *p(double);"},{"it":"double p*(double);","en":"double p*(double);"},{"it":"function<double> p;","en":"function<double> p;"},{"it":"double (*p)(double);","en":"double (*p)(double);"}]',3,'{"it":"La prima forma dichiara una funzione che restituisce un puntatore.","en":"The first form declares a function returning a pointer."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'function-pointers'),3,2,'{"it":"Perché `qsort` usa `const void *`?","en":"Why does `qsort` use `const void *`?"}','[{"it":"Perché deve funzionare con dati di qualsiasi tipo","en":"Because it must work with data of any type"},{"it":"Perché così è più veloce","en":"Because it is faster that way"},{"it":"Perché i dati non esistono","en":"Because the data does not exist"},{"it":"Per impedire di ordinare gli interi","en":"To prevent sorting integers"}]',0,'{"it":"Il tipo vero lo conosce solo la tua funzione.","en":"Only your function knows the real type."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'linked-list'),1,2,'{"it":"Dove punta il campo `prossimo` dell’ultimo nodo?","en":"Where does the last node’s `prossimo` field point?"}','[{"it":"NULL","en":"NULL"},{"it":"Al primo nodo","en":"To the first node"},{"it":"A sé stesso","en":"To itself"},{"it":"A un indirizzo casuale","en":"To a random address"}]',0,'{"it":"Così il ciclo di lettura sa quando fermarsi.","en":"That way the reading loop knows when to stop."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'linked-list'),2,2,'{"it":"Perché in `libera` si salva `testa->prossimo` prima di `free(testa)`?","en":"Why does `libera` save `testa->prossimo` before `free(testa)`?"}','[{"it":"Per andare più veloce","en":"To run faster"},{"it":"Perché free cancella tutta la lista","en":"Because free deletes the whole list"},{"it":"Perché dopo free quel nodo non si può più leggere","en":"Because after free that node can no longer be read"},{"it":"Non serve: è solo una questione di stile","en":"It is not needed: it is just style"}]',2,'{"it":"Sarebbe un use-after-free.","en":"It would be a use-after-free."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'linked-list'),3,2,'{"it":"Che cosa costa poco in una lista collegata rispetto a un array?","en":"What is cheap in a linked list compared with an array?"}','[{"it":"Leggere l’elemento numero 500","en":"Reading item number 500"},{"it":"Inserire un elemento in testa","en":"Inserting an item at the head"},{"it":"Ordinare con qsort","en":"Sorting with qsort"},{"it":"Usare meno memoria per elemento","en":"Using less memory per item"}]',1,'{"it":"Ogni nodo in più occupa anche lo spazio di un puntatore.","en":"Each node also takes the space of a pointer."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'bits'),1,2,'{"it":"Come accendi il bit FLAG in `x` senza toccare gli altri?","en":"How do you turn on the FLAG bit in `x` without touching the others?"}','[{"it":"x &= FLAG","en":"x &= FLAG"},{"it":"x |= FLAG","en":"x |= FLAG"},{"it":"x ^= ~FLAG","en":"x ^= ~FLAG"},{"it":"x = FLAG","en":"x = FLAG"}]',1,'{"it":"`x = FLAG` spegnerebbe tutti gli altri bit.","en":"`x = FLAG` would turn off every other bit."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'bits'),2,2,'{"it":"Come controlli se il bit FLAG è acceso?","en":"How do you check whether the FLAG bit is on?"}','[{"it":"if (x | FLAG)","en":"if (x | FLAG)"},{"it":"if (x == FLAG)","en":"if (x == FLAG)"},{"it":"if (x & FLAG)","en":"if (x & FLAG)"},{"it":"if (x ^ FLAG)","en":"if (x ^ FLAG)"}]',2,'{"it":"`x == FLAG` sarebbe vero solo se fosse l’unico bit acceso.","en":"`x == FLAG` would be true only if it were the only bit on."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'bits'),3,2,'{"it":"Quanto vale `1u << 3`?","en":"What is `1u << 3`?"}','[{"it":"3","en":"3"},{"it":"4","en":"4"},{"it":"16","en":"16"},{"it":"8","en":"8"}]',3,'{"it":"1 spostato di tre posizioni: 0b1000.","en":"1 shifted three places: 0b1000."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'multifile'),1,3,'{"it":"Che cosa va in un file header `.h`?","en":"What goes in a `.h` header file?"}','[{"it":"Le dichiarazioni condivise: prototipi, tipi, costanti","en":"Shared declarations: prototypes, types, constants"},{"it":"La funzione main","en":"The main function"},{"it":"Il codice già compilato","en":"The compiled code"},{"it":"Solo commenti","en":"Only comments"}]',0,'{"it":"Le definizioni restano nei file `.c`.","en":"Definitions stay in the `.c` files."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'multifile'),2,3,'{"it":"A che cosa servono `#ifndef`, `#define` e `#endif` in un header?","en":"What are `#ifndef`, `#define` and `#endif` for in a header?"}','[{"it":"A velocizzare il programma","en":"Speeding up the program"},{"it":"A nascondere il codice","en":"Hiding the code"},{"it":"A evitare che l’header venga incluso due volte","en":"Preventing the header from being included twice"},{"it":"A definire il main","en":"Defining main"}]',2,'{"it":"Molti compilatori accettano anche `#pragma once`.","en":"Many compilers also accept `#pragma once`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'multifile'),3,3,'{"it":"Che cosa fa `make` se cambi un solo file `.c`?","en":"What does `make` do if you change a single `.c` file?"}','[{"it":"Ricompila tutto da zero","en":"Rebuilds everything from scratch"},{"it":"Ricompila solo ciò che dipende da quel file","en":"Rebuilds only what depends on that file"},{"it":"Niente: serve prima `make clean`","en":"Nothing: you need `make clean` first"},{"it":"Cancella il Makefile","en":"Deletes the Makefile"}]',1,'{"it":"Confronta le date dei file.","en":"It compares file timestamps."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'debugging'),1,3,'{"it":"Quale opzione di gcc attiva AddressSanitizer?","en":"Which gcc option enables AddressSanitizer?"}','[{"it":"-O3","en":"-O3"},{"it":"-fsanitize=address","en":"-fsanitize=address"},{"it":"-Wall","en":"-Wall"},{"it":"-lm","en":"-lm"}]',1,'{"it":"Si abbina bene a `-g`.","en":"It pairs well with `-g`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'debugging'),2,3,'{"it":"Quale di questi è comportamento indefinito in C?","en":"Which of these is undefined behaviour in C?"}','[{"it":"Dividere due double","en":"Dividing two doubles"},{"it":"Chiamare free(NULL)","en":"Calling free(NULL)"},{"it":"Confrontare due puntatori con ==","en":"Comparing two pointers with =="},{"it":"Superare INT_MAX in un int con segno","en":"Going past INT_MAX in a signed int"}]',3,'{"it":"`free(NULL)` invece è permesso e non fa nulla.","en":"`free(NULL)` is allowed and does nothing."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'debugging'),3,3,'{"it":"Che cosa mostra `backtrace` in gdb?","en":"What does `backtrace` show in gdb?"}','[{"it":"La catena di chiamate che ha portato fin lì","en":"The chain of calls that led there"},{"it":"Il codice assembly","en":"The assembly code"},{"it":"Le variabili globali","en":"The global variables"},{"it":"L’uso della memoria","en":"Memory usage"}]',0,'{"it":"Utilissimo dopo un crash.","en":"Very useful after a crash."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'c23'),1,3,'{"it":"Che cosa sostituisce `nullptr` nel C23?","en":"What does `nullptr` replace in C23?"}','[{"it":"NULL","en":"NULL"},{"it":"0.0","en":"0.0"},{"it":"void","en":"void"},{"it":"free","en":"free"}]',0,'{"it":"Ha un tipo suo, `nullptr_t`, e non si confonde con un intero.","en":"It has its own type, `nullptr_t`, and is not mistaken for an integer."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'c23'),2,3,'{"it":"Che cosa fa `[[nodiscard]]` su una funzione?","en":"What does `[[nodiscard]]` do on a function?"}','[{"it":"La rende inline","en":"Makes it inline"},{"it":"Le impedisce di restituire valori","en":"Stops it returning values"},{"it":"Fa avvisare il compilatore se il risultato viene ignorato","en":"Makes the compiler warn if the result is ignored"},{"it":"La esegue all’avvio","en":"Runs it at start-up"}]',2,'{"it":"Ottimo per funzioni che restituiscono errori.","en":"Great for functions that return errors."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'c23'),3,3,'{"it":"Nel C23 per usare `bool` serve ancora `#include <stdbool.h>`?","en":"In C23, do you still need `#include <stdbool.h>` to use `bool`?"}','[{"it":"Sì, sempre","en":"Yes, always"},{"it":"Solo su Windows","en":"Only on Windows"},{"it":"Solo per `false`","en":"Only for `false`"},{"it":"No: `bool`, `true` e `false` sono parole chiave","en":"No: `bool`, `true` and `false` are keywords"}]',3,'{"it":"Includerlo resta innocuo.","en":"Including it is still harmless."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'intro'),1,2,'{"it":"Che cosa aggiunge C++ a C?","en":"What does C++ add to C?"}','[{"it":"Classi, template e una ricca libreria standard","en":"Classes, templates and a rich standard library"},{"it":"Niente","en":"Nothing"},{"it":"Solo commenti","en":"Only comments"},{"it":"Un garbage collector obbligatorio","en":"A mandatory garbage collector"}]',0,'{"it":"Mantenendo le prestazioni.","en":"While keeping performance."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'intro'),2,2,'{"it":"Che cosa fa `std::cout << \\"ciao\\"`?","en":"What does `std::cout << \\"ciao\\"` do?"}','[{"it":"Stampa ciao","en":"Prints ciao"},{"it":"Legge ciao","en":"Reads ciao"},{"it":"Cancella ciao","en":"Deletes ciao"},{"it":"Confronta","en":"Compares"}]',0,'{"it":"Output standard.","en":"Standard output."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'intro'),3,2,'{"it":"Che cos’è `std::`?","en":"What is `std::`?"}','[{"it":"Lo spazio dei nomi della libreria standard","en":"The standard library namespace"},{"it":"Un tipo di variabile per i testi","en":"A variable type for text"},{"it":"Un errore","en":"An error"},{"it":"Un commento","en":"A comment"}]',0,'{"it":"Evita conflitti di nomi.","en":"It avoids name clashes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'stl'),1,2,'{"it":"Quale contenitore è un array che cresce?","en":"Which container is a growing array?"}','[{"it":"std::vector","en":"std::vector"},{"it":"std::map","en":"std::map"},{"it":"std::set","en":"std::set"},{"it":"std::pair","en":"std::pair"}]',0,'{"it":"push_back aggiunge in fondo.","en":"push_back appends."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'stl'),2,2,'{"it":"Che cosa fa `std::sort(v.begin(), v.end())`?","en":"What does `std::sort(v.begin(), v.end())` do?"}','[{"it":"Ordina il vettore","en":"Sorts the vector"},{"it":"Cancella il vettore","en":"Deletes the vector"},{"it":"Conta gli elementi","en":"Counts the elements"},{"it":"Inverte il vettore","en":"Reverses the vector"}]',0,'{"it":"Algoritmo standard.","en":"Standard algorithm."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'stl'),3,2,'{"it":"Perché preferire `at(i)` a `[i]` quando sei incerto?","en":"Why prefer `at(i)` over `[i]` when unsure?"}','[{"it":"at controlla i limiti","en":"at checks bounds"},{"it":"È più veloce","en":"It is faster"},{"it":"Non c’è differenza","en":"There is no difference"},{"it":"[i] non esiste","en":"[i] does not exist"}]',0,'{"it":"Lancia un’eccezione fuori dai limiti.","en":"It throws outside bounds."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'classes'),1,2,'{"it":"Quando viene chiamato il distruttore?","en":"When is the destructor called?"}','[{"it":"Quando l’oggetto esce dallo scope","en":"When the object goes out of scope"},{"it":"Mai automaticamente","en":"Never automatically"},{"it":"All’avvio del programma","en":"At program start"},{"it":"Solo con delete del file","en":"Only with file deletion"}]',0,'{"it":"Anche in caso di eccezione.","en":"Even on exceptions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'classes'),2,2,'{"it":"Che cosa significa RAII?","en":"What does RAII mean?"}','[{"it":"La risorsa si acquisisce nel costruttore e si rilascia nel distruttore","en":"The resource is acquired in the constructor and released in the destructor"},{"it":"Un tipo di ciclo che ripete finché una risorsa è libera","en":"A kind of loop repeating while a resource is free"},{"it":"Un compilatore","en":"A compiler"},{"it":"Una libreria grafica","en":"A graphics library"}]',0,'{"it":"Niente dimenticanze.","en":"No forgetting."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'classes'),3,2,'{"it":"Che cosa sono i membri private?","en":"What are private members?"}','[{"it":"Dati nascosti all’esterno della classe","en":"Data hidden from outside the class"},{"it":"Dati pubblici visibili da tutto il programma","en":"Public data visible to the whole program"},{"it":"Commenti","en":"Comments"},{"it":"Errori","en":"Errors"}]',0,'{"it":"Incapsulamento.","en":"Encapsulation."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'modern'),1,2,'{"it":"Quanti proprietari ha uno std::unique_ptr?","en":"How many owners does a std::unique_ptr have?"}','[{"it":"Uno","en":"One"},{"it":"Due","en":"Two"},{"it":"Infiniti","en":"Unlimited"},{"it":"Nessuno","en":"None"}]',0,'{"it":"Unico, appunto.","en":"Unique, indeed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'modern'),2,2,'{"it":"Quando libera la memoria uno std::shared_ptr?","en":"When does a std::shared_ptr free memory?"}','[{"it":"Quando sparisce l’ultimo proprietario","en":"When the last owner goes"},{"it":"Subito","en":"At once"},{"it":"Mai","en":"Never"},{"it":"A ogni copia","en":"On every copy"}]',0,'{"it":"Conta i riferimenti.","en":"It counts references."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'modern'),3,2,'{"it":"Che cosa usare al posto di new e delete?","en":"What should you use instead of new and delete?"}','[{"it":"Smart pointer e contenitori","en":"Smart pointers and containers"},{"it":"malloc e free","en":"malloc and free"},{"it":"Variabili globali","en":"Global variables"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"RAII ovunque.","en":"RAII everywhere."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'algorithms'),1,2,'{"it":"Che cosa fa `std::count_if`?","en":"What does `std::count_if` do?"}','[{"it":"Conta gli elementi che rispettano una condizione","en":"Counts elements meeting a condition"},{"it":"Ordina il vettore","en":"Sorts the vector"},{"it":"Cancella elementi","en":"Deletes elements"},{"it":"Conta i byte","en":"Counts bytes"}]',0,'{"it":"La condizione è spesso una lambda.","en":"The condition is often a lambda."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'algorithms'),2,2,'{"it":"Che cos’è una lambda?","en":"What is a lambda?"}','[{"it":"Una funzione scritta al volo","en":"A function written on the spot"},{"it":"Un tipo di vettore","en":"A vector type"},{"it":"Una macro","en":"A macro"},{"it":"Un puntatore nullo","en":"A null pointer"}]',0,'{"it":"`[](int x) { … }`.","en":"`[](int x) { … }`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'algorithms'),3,2,'{"it":"A che cosa servono i template?","en":"What are templates for?"}','[{"it":"Scrivere codice valido per più tipi","en":"Writing code valid for many types"},{"it":"Formattare il testo","en":"Formatting text"},{"it":"Gestire i file","en":"Handling files"},{"it":"Velocizzare la compilazione","en":"Speeding up compilation"}]',0,'{"it":"Il compilatore genera le versioni.","en":"The compiler generates the versions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'references'),1,3,'{"it":"Che cosa succede a `x` dopo `raddoppia(x)` se il parametro è `int& n`?","en":"What happens to `x` after `raddoppia(x)` if the parameter is `int& n`?"}','[{"it":"Resta uguale","en":"It stays the same"},{"it":"Raddoppia","en":"It doubles"},{"it":"Diventa 0","en":"It becomes 0"},{"it":"Errore di compilazione","en":"Compile error"}]',1,'{"it":"`n` è solo un altro nome per `x`.","en":"`n` is just another name for `x`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'references'),2,3,'{"it":"Perché passare un vettore come `const std::vector<int>&`?","en":"Why pass a vector as `const std::vector<int>&`?"}','[{"it":"Per evitare la copia senza permettere modifiche","en":"To avoid the copy without allowing changes"},{"it":"Per poterlo modificare","en":"To be able to change it"},{"it":"Per renderlo globale","en":"To make it global"},{"it":"Perché i vector non si possono passare per valore","en":"Because vectors cannot be passed by value"}]',0,'{"it":"Per valore si potrebbe, ma copierebbe tutto.","en":"By value is possible, but it would copy everything."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'references'),3,3,'{"it":"Che cosa è vero per un riferimento?","en":"What is true of a reference?"}','[{"it":"Può restare non inizializzato","en":"It can stay uninitialised"},{"it":"Può essere nullo come un puntatore","en":"It can be null like a pointer"},{"it":"Si può far riferire a un’altra variabile in seguito","en":"It can later be made to refer to another variable"},{"it":"Va inizializzato subito e resta legato a quella variabile","en":"It must be initialised at once and stays bound to that variable"}]',3,'{"it":"Assegnargli un valore cambia la variabile, non il legame.","en":"Assigning to it changes the variable, not the binding."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'strings-io'),1,3,'{"it":"Che cosa restituisce `s.find(\\"x\\")` se la x non c’è?","en":"What does `s.find(\\"x\\")` return if there is no x?"}','[{"it":"-1","en":"-1"},{"it":"0","en":"0"},{"it":"std::string::npos","en":"std::string::npos"},{"it":"nullptr","en":"nullptr"}]',2,'{"it":"È il valore massimo di `size_t`.","en":"It is the largest value of `size_t`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'strings-io'),2,3,'{"it":"Come leggi una riga intera, spazi compresi?","en":"How do you read a whole line, spaces included?"}','[{"it":"std::cin >> riga","en":"std::cin >> riga"},{"it":"std::getline(std::cin, riga)","en":"std::getline(std::cin, riga)"},{"it":"scanf(\\"%s\\", riga)","en":"scanf(\\"%s\\", riga)"},{"it":"std::read(riga)","en":"std::read(riga)"}]',1,'{"it":"`>>` si ferma al primo spazio.","en":"`>>` stops at the first space."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'strings-io'),3,3,'{"it":"Che cosa produce `std::format(\\"{} + {} = {}\\", 2, 3, 5)`?","en":"What does `std::format(\\"{} + {} = {}\\", 2, 3, 5)` produce?"}','[{"it":"\\"2 + 3 = 5\\"","en":"\\"2 + 3 = 5\\""},{"it":"\\"{} + {} = {}\\"","en":"\\"{} + {} = {}\\""},{"it":"\\"235\\"","en":"\\"235\\""},{"it":"Un errore di compilazione","en":"A compile error"}]',0,'{"it":"Ogni coppia di graffe prende il valore successivo.","en":"Each pair of braces takes the next value."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'inheritance'),1,3,'{"it":"Che cosa fa `override`?","en":"What does `override` do?"}','[{"it":"Rende il metodo più veloce","en":"Makes the method faster"},{"it":"Nasconde il metodo della base","en":"Hides the base method"},{"it":"Fa controllare al compilatore che il metodo ridefinisca un virtual della base","en":"Makes the compiler check the method redefines a virtual of the base"},{"it":"Rende la classe astratta","en":"Makes the class abstract"}]',2,'{"it":"Un errore di battitura nel nome diventa un errore di compilazione.","en":"A typo in the name becomes a compile error."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'inheritance'),2,3,'{"it":"Che cosa significa `virtual double area() const = 0;`?","en":"What does `virtual double area() const = 0;` mean?"}','[{"it":"Il metodo restituisce sempre 0","en":"The method always returns 0"},{"it":"Il metodo è puramente virtuale: la classe è astratta","en":"The method is pure virtual: the class is abstract"},{"it":"Il metodo è statico","en":"The method is static"},{"it":"Il metodo è privato","en":"The method is private"}]',1,'{"it":"Le derivate concrete devono implementarlo.","en":"Concrete derived classes must implement it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'inheritance'),3,3,'{"it":"Perché una base polimorfica ha il distruttore `virtual`?","en":"Why does a polymorphic base have a `virtual` destructor?"}','[{"it":"Perché distruggere una derivata attraverso la base sia corretto","en":"So that destroying a derived object through the base is correct"},{"it":"Per velocità","en":"For speed"},{"it":"Per vietare le copie","en":"To forbid copies"},{"it":"Non serve mai","en":"It is never needed"}]',0,'{"it":"Altrimenti il distruttore della derivata non viene chiamato.","en":"Otherwise the derived destructor is not called."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'exceptions'),1,3,'{"it":"In che ordine si scrivono i `catch`?","en":"In what order do you write the `catch` blocks?"}','[{"it":"Dal più generale al più specifico","en":"From the most general to the most specific"},{"it":"In ordine alfabetico","en":"In alphabetical order"},{"it":"L’ordine non conta","en":"The order does not matter"},{"it":"Dal più specifico al più generale","en":"From the most specific to the most general"}]',3,'{"it":"Il primo che corrisponde vince.","en":"The first that matches wins."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'exceptions'),2,3,'{"it":"Che cosa succede agli oggetti locali quando un’eccezione esce dalla funzione?","en":"What happens to local objects when an exception leaves the function?"}','[{"it":"Vengono distrutti e i loro distruttori chiamati","en":"They are destroyed and their destructors called"},{"it":"Restano in memoria","en":"They stay in memory"},{"it":"Vengono copiati nel catch","en":"They are copied into the catch"},{"it":"Il programma si ferma sempre","en":"The program always stops"}]',0,'{"it":"È lo stack unwinding.","en":"It is stack unwinding."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-base' AND slug = 'exceptions'),3,3,'{"it":"Che cosa promette `noexcept`?","en":"What does `noexcept` promise?"}','[{"it":"Che la funzione è più veloce","en":"That the function is faster"},{"it":"Che la funzione non lancia eccezioni","en":"That the function throws no exceptions"},{"it":"Che la funzione restituisce un errore","en":"That the function returns an error"},{"it":"Che il risultato va usato","en":"That the result must be used"}]',1,'{"it":"Se lanciasse comunque, il programma terminerebbe.","en":"If it threw anyway, the program would terminate."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'move-semantics'),1,2,'{"it":"Che cosa fa davvero `std::move(a)`?","en":"What does `std::move(a)` really do?"}','[{"it":"Sposta subito la memoria di a","en":"Moves a’s memory at once"},{"it":"Tratta a come un valore temporaneo, così può essere spostato","en":"Treats a as a temporary value, so it can be moved"},{"it":"Cancella a","en":"Deletes a"},{"it":"Copia a più in fretta","en":"Copies a faster"}]',1,'{"it":"Lo spostamento vero lo fa il costruttore o l’assegnamento che riceve il risultato.","en":"The actual move is done by the constructor or assignment receiving the result."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'move-semantics'),2,2,'{"it":"In che stato resta un `std::vector` dopo essere stato spostato?","en":"What state is a `std::vector` in after being moved from?"}','[{"it":"Valido ma non specificato, di solito vuoto","en":"Valid but unspecified, usually empty"},{"it":"Distrutto: usarlo non compila","en":"Destroyed: using it does not compile"},{"it":"Identico a prima","en":"The same as before"},{"it":"Pieno di zeri","en":"Full of zeros"}]',0,'{"it":"Puoi riassegnarlo o svuotarlo e riusarlo.","en":"You can reassign or clear it and reuse it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'move-semantics'),3,2,'{"it":"Che cosa dice la regola dello zero?","en":"What does the rule of zero say?"}','[{"it":"Una classe deve avere zero metodi","en":"A class must have zero methods"},{"it":"Inizializza tutto a zero","en":"Initialise everything to zero"},{"it":"Non usare mai std::move","en":"Never use std::move"},{"it":"Se i membri si gestiscono da soli, non scrivere distruttore, copie e spostamenti","en":"If the members manage themselves, write no destructor, copies or moves"}]',3,'{"it":"Meno codice, meno errori.","en":"Less code, fewer bugs."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'templates-concepts'),1,2,'{"it":"Che cosa succede chiamando `somma_fino(2.5)`?","en":"What happens when calling `somma_fino(2.5)`?"}','[{"it":"Restituisce 3.5","en":"It returns 3.5"},{"it":"Arrotonda a 2","en":"It rounds to 2"},{"it":"Errore di compilazione: double non soddisfa std::integral","en":"Compile error: double does not satisfy std::integral"},{"it":"Errore a runtime","en":"Runtime error"}]',2,'{"it":"Il concept blocca il tipo prima di generare il codice.","en":"The concept rejects the type before generating code."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'templates-concepts'),2,2,'{"it":"A che cosa serve un concept?","en":"What is a concept for?"}','[{"it":"A descrivere i requisiti di un tipo nei template","en":"Describing a type’s requirements in templates"},{"it":"A creare classi astratte","en":"Creating abstract classes"},{"it":"A gestire la memoria","en":"Managing memory"},{"it":"A velocizzare il programma","en":"Speeding up the program"}]',0,'{"it":"È un controllo in compilazione.","en":"It is a compile-time check."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'templates-concepts'),3,2,'{"it":"Perché il codice dei template sta di solito negli header?","en":"Why does template code usually live in headers?"}','[{"it":"Solo per abitudine","en":"Only out of habit"},{"it":"Perché il compilatore deve vederlo per generare ogni versione","en":"Because the compiler must see it to generate each version"},{"it":"Perché i file .cpp non accettano template","en":"Because .cpp files do not accept templates"},{"it":"Per nasconderlo agli altri file","en":"To hide it from other files"}]',1,'{"it":"Ogni file che lo usa genera le versioni che gli servono.","en":"Each file using it generates the versions it needs."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'ranges'),1,2,'{"it":"Che cosa fa l’operatore `|` tra views?","en":"What does the `|` operator do between views?"}','[{"it":"Calcola un OR tra i bit","en":"Computes a bitwise OR"},{"it":"Concatena le trasformazioni in una pipeline","en":"Chains the transformations into a pipeline"},{"it":"Unisce due vettori","en":"Joins two vectors"},{"it":"Ordina il range","en":"Sorts the range"}]',1,'{"it":"Si legge da sinistra a destra.","en":"It reads left to right."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'ranges'),2,2,'{"it":"Quando calcola i valori una view come `views::transform`?","en":"When does a view such as `views::transform` compute its values?"}','[{"it":"Mentre la scorri, uno alla volta","en":"While you walk it, one at a time"},{"it":"Appena la crei, tutti insieme","en":"As soon as it is created, all at once"},{"it":"Mai: va convertita prima","en":"Never: it must be converted first"},{"it":"Solo in modalità release","en":"Only in release mode"}]',0,'{"it":"È pigra.","en":"It is lazy."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'ranges'),3,2,'{"it":"Come ordini `v` con i ranges?","en":"How do you sort `v` with ranges?"}','[{"it":"v.sort()","en":"v.sort()"},{"it":"std::sort(v)","en":"std::sort(v)"},{"it":"std::views::sort(v)","en":"std::views::sort(v)"},{"it":"std::ranges::sort(v)","en":"std::ranges::sort(v)"}]',3,'{"it":"`std::sort` vuole ancora `begin` ed `end`.","en":"`std::sort` still wants `begin` and `end`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'operators'),1,2,'{"it":"Che cosa genera `auto operator<=>(const Data&) const = default;`?","en":"What does `auto operator<=>(const Data&) const = default;` generate?"}','[{"it":"Solo l’operatore <=>","en":"Only the <=> operator"},{"it":"Una copia della classe","en":"A copy of the class"},{"it":"Tutti gli operatori di confronto, membro per membro","en":"Every comparison operator, member by member"},{"it":"Un costruttore","en":"A constructor"}]',2,'{"it":"L’ordine dei membri decide il confronto.","en":"The order of the members decides the comparison."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'operators'),2,2,'{"it":"Perché `operator<<` restituisce `std::ostream&`?","en":"Why does `operator<<` return `std::ostream&`?"}','[{"it":"Per poter concatenare più `<<` di seguito","en":"To chain several `<<` in a row"},{"it":"Per velocità","en":"For speed"},{"it":"Perché è obbligatorio per tutti gli operatori","en":"Because every operator must"},{"it":"Per chiudere lo stream","en":"To close the stream"}]',0,'{"it":"`std::cout << a << b` usa il risultato del primo `<<`.","en":"`std::cout << a << b` uses the result of the first `<<`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'operators'),3,2,'{"it":"Che cosa restituisce di solito `operator+=`?","en":"What does `operator+=` usually return?"}','[{"it":"void","en":"void"},{"it":"Un oggetto nuovo","en":"A new object"},{"it":"bool","en":"bool"},{"it":"Un riferimento all’oggetto stesso, *this","en":"A reference to the object itself, *this"}]',3,'{"it":"Come fanno i tipi predefiniti.","en":"As built-in types do."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'vocabulary-types'),1,3,'{"it":"Quale tipo rappresenta un valore che può mancare?","en":"Which type represents a value that may be missing?"}','[{"it":"std::variant","en":"std::variant"},{"it":"std::span","en":"std::span"},{"it":"std::optional","en":"std::optional"},{"it":"std::string_view","en":"std::string_view"}]',2,'{"it":"Vuoto si scrive `std::nullopt`.","en":"Empty is written `std::nullopt`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'vocabulary-types'),2,3,'{"it":"Che cosa è pericoloso con `std::string_view`?","en":"What is dangerous with `std::string_view`?"}','[{"it":"Usarla dopo che la stringa a cui si riferisce è stata distrutta","en":"Using it after the string it refers to has been destroyed"},{"it":"Passarla per valore","en":"Passing it by value"},{"it":"Leggerne la lunghezza","en":"Reading its length"},{"it":"Confrontarla con ==","en":"Comparing it with =="}]',0,'{"it":"È solo una vista: punta a memoria di altri.","en":"It is only a view: it points at someone else’s memory."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'vocabulary-types'),3,3,'{"it":"Che cosa contiene uno `std::expected<int, std::string>`?","en":"What does a `std::expected<int, std::string>` hold?"}','[{"it":"Sempre entrambi","en":"Always both"},{"it":"Un int e un elenco di errori","en":"An int and a list of errors"},{"it":"Niente fino al C++26","en":"Nothing until C++26"},{"it":"Un int oppure un messaggio di errore","en":"An int or an error message"}]',3,'{"it":"Si controlla con `has_value()` o `value_or`.","en":"You check it with `has_value()` or `value_or`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'concurrency'),1,3,'{"it":"Che differenza c’è tra `std::jthread` e `std::thread`?","en":"What is the difference between `std::jthread` and `std::thread`?"}','[{"it":"jthread è più veloce","en":"jthread is faster"},{"it":"jthread viene aspettato da solo quando è distrutto","en":"jthread is waited for automatically when destroyed"},{"it":"jthread non accetta lambda","en":"jthread does not accept lambdas"},{"it":"Nessuna","en":"None"}]',1,'{"it":"Un `std::thread` non unito alla distruzione termina il programma.","en":"A `std::thread` not joined at destruction terminates the program."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'concurrency'),2,3,'{"it":"Che cosa fa `std::scoped_lock lock(m);`?","en":"What does `std::scoped_lock lock(m);` do?"}','[{"it":"Blocca il mutex e lo sblocca alla fine del blocco","en":"Locks the mutex and unlocks it at the end of the block"},{"it":"Crea un nuovo thread","en":"Creates a new thread"},{"it":"Distrugge il mutex","en":"Destroys the mutex"},{"it":"Blocca il mutex per sempre","en":"Locks the mutex forever"}]',0,'{"it":"È RAII applicato ai lock.","en":"It is RAII applied to locks."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'concurrency'),3,3,'{"it":"Che cosa restituisce `std::async`?","en":"What does `std::async` return?"}','[{"it":"Il risultato, subito","en":"The result, at once"},{"it":"Un thread","en":"A thread"},{"it":"Un mutex","en":"A mutex"},{"it":"Un std::future da cui leggere il risultato","en":"A std::future to read the result from"}]',3,'{"it":"`get()` aspetta se il risultato non è pronto.","en":"`get()` waits if the result is not ready."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'cmake'),1,3,'{"it":"Quale file descrive un progetto CMake?","en":"Which file describes a CMake project?"}','[{"it":"Makefile","en":"Makefile"},{"it":"CMakeLists.txt","en":"CMakeLists.txt"},{"it":"meson.build","en":"meson.build"},{"it":"project.json","en":"project.json"}]',1,'{"it":"Uno nella radice, e altri nelle sottocartelle se serve.","en":"One at the root, and others in subfolders if needed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'cmake'),2,3,'{"it":"Che cosa fa `target_link_libraries(app PRIVATE geometria)`?","en":"What does `target_link_libraries(app PRIVATE geometria)` do?"}','[{"it":"Collega la libreria geometria all’eseguibile app","en":"Links the geometria library to the app executable"},{"it":"Scarica geometria da internet","en":"Downloads geometria from the internet"},{"it":"Rende privato il codice di app","en":"Makes app’s code private"},{"it":"Compila soltanto geometria","en":"Builds only geometria"}]',0,'{"it":"`PRIVATE`: serve ad app ma non a chi usa app.","en":"`PRIVATE`: app needs it but app’s users do not."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'cpp-intermediate' AND slug = 'cmake'),3,3,'{"it":"Che cosa fa `cmake -S . -B build`?","en":"What does `cmake -S . -B build` do?"}','[{"it":"Compila ed esegue il programma","en":"Builds and runs the program"},{"it":"Cancella la cartella build","en":"Deletes the build folder"},{"it":"Installa CMake","en":"Installs CMake"},{"it":"Configura il progetto e genera i file di compilazione in build","en":"Configures the project and generates the build files in build"}]',3,'{"it":"Poi si compila con `cmake --build build`.","en":"Then you build with `cmake --build build`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'why'),1,2,'{"it":"Quali test dovrebbero essere i più numerosi?","en":"Which tests should be the most numerous?"}','[{"it":"Unitari","en":"Unit"},{"it":"End-to-end","en":"End-to-end"},{"it":"Manuali","en":"Manual"},{"it":"Nessuno","en":"None"}]',0,'{"it":"La base della piramide.","en":"The pyramid’s base."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'why'),2,2,'{"it":"Che vantaggio danno i test quando modifichi il codice?","en":"What do tests give you when changing code?"}','[{"it":"Scopri subito se hai rotto qualcosa","en":"You find out at once if you broke something"},{"it":"Il codice diventa più lungo","en":"Code gets longer"},{"it":"Niente","en":"Nothing"},{"it":"Rallentano tutto","en":"They slow everything"}]',0,'{"it":"Modificare senza paura.","en":"Change without fear."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'why'),3,2,'{"it":"Perché i test end-to-end sono pochi?","en":"Why are end-to-end tests few?"}','[{"it":"Sono lenti e fragili","en":"They are slow and brittle"},{"it":"Sono inutili","en":"They are useless"},{"it":"Sono vietati","en":"They are forbidden"},{"it":"Sono troppo veloci","en":"They are too fast"}]',0,'{"it":"Ma molto realistici.","en":"But very realistic."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'unit'),1,2,'{"it":"Che cosa significa Arrange, Act, Assert?","en":"What does Arrange, Act, Assert mean?"}','[{"it":"Prepara, esegui, verifica","en":"Prepare, run, verify"},{"it":"Scrivi, cancella, ripeti","en":"Write, delete, repeat"},{"it":"Compila, avvia, chiudi","en":"Compile, start, close"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Lo schema di ogni test.","en":"The pattern of every test."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'unit'),2,2,'{"it":"Quale di questi è un caso limite?","en":"Which of these is an edge case?"}','[{"it":"Una lista vuota","en":"An empty list"},{"it":"Una lista di tre elementi normali","en":"A list of three normal items"},{"it":"Il nome del file","en":"The file name"},{"it":"Il colore del test","en":"The test colour"}]',0,'{"it":"Lì si nascondono i bug.","en":"Bugs hide there."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'unit'),3,2,'{"it":"Quale libreria si usa spesso per i test in Python?","en":"Which library is often used for tests in Python?"}','[{"it":"pytest","en":"pytest"},{"it":"pandas","en":"pandas"},{"it":"Django","en":"Django"},{"it":"NumPy","en":"NumPy"}]',0,'{"it":"Con semplici assert.","en":"With simple asserts."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'mocks'),1,2,'{"it":"A che cosa serve un mock?","en":"What is a mock for?"}','[{"it":"Sostituire una dipendenza esterna nei test","en":"Replacing an external dependency in tests"},{"it":"Cancellare il database prima di ogni test","en":"Deleting the database before each test"},{"it":"Velocizzare la produzione","en":"Speeding up production"},{"it":"Scrivere documentazione","en":"Writing documentation"}]',0,'{"it":"Niente email vere nei test.","en":"No real email in tests."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'mocks'),2,2,'{"it":"Che cosa verifica un test di integrazione?","en":"What does an integration test verify?"}','[{"it":"Che più parti funzionino insieme","en":"That several parts work together"},{"it":"Una sola funzione isolata","en":"One isolated function"},{"it":"Il colore della pagina","en":"The page colour"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"API + database, per esempio.","en":"API + database, for example."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'mocks'),3,2,'{"it":"Che rischio c’è con troppi mock?","en":"What is the risk with too many mocks?"}','[{"it":"Il test non dimostra che il sistema reale funziona","en":"The test does not prove the real system works"},{"it":"I test diventano troppo lenti da eseguire","en":"Tests become too slow to run"},{"it":"Nessun rischio","en":"No risk"},{"it":"Il codice si cancella","en":"The code gets deleted"}]',0,'{"it":"Equilibrio.","en":"Balance."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'e2e-ci'),1,2,'{"it":"Che cosa fa Playwright?","en":"What does Playwright do?"}','[{"it":"Automatizza un browser per i test end-to-end","en":"Automates a browser for end-to-end tests"},{"it":"Gestisce i database di test in container","en":"Manages test databases in containers"},{"it":"Compila C++","en":"Compiles C++"},{"it":"Disegna grafici","en":"Draws charts"}]',0,'{"it":"Simula l’utente.","en":"It simulates the user."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'e2e-ci'),2,2,'{"it":"Qual è l’ordine del TDD?","en":"What is the TDD order?"}','[{"it":"Rosso, verde, refactor","en":"Red, green, refactor"},{"it":"Verde, rosso, cancella","en":"Green, red, delete"},{"it":"Codice, poi test un anno dopo","en":"Code, then tests a year later"},{"it":"Refactor, rosso, verde","en":"Refactor, red, green"}]',0,'{"it":"Prima il test che fallisce.","en":"Failing test first."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'e2e-ci'),3,2,'{"it":"Che cosa fa la CI con i test?","en":"What does CI do with tests?"}','[{"it":"Li esegue a ogni push e pull request","en":"Runs them on every push and pull request"},{"it":"Li cancella","en":"Deletes them"},{"it":"Li scrive da sola leggendo il codice","en":"Writes them by itself by reading the code"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Niente merge se rosso.","en":"No merge if red."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'quality'),1,3,'{"it":"Che cosa misura la copertura?","en":"What does coverage measure?"}','[{"it":"Le righe eseguite dai test","en":"The lines run by the tests"},{"it":"I bug trovati","en":"Bugs found"},{"it":"La velocità","en":"Speed"},{"it":"La qualità dei controlli","en":"The quality of assertions"}]',0,'{"it":"Eseguito non vuol dire verificato.","en":"Run does not mean checked."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'quality'),2,3,'{"it":"Quale è un caso limite?","en":"Which one is an edge case?"}','[{"it":"Una lista vuota","en":"An empty list"},{"it":"Una lista di tre numeri normali","en":"A list of three normal numbers"},{"it":"Il nome del file","en":"The file name"},{"it":"Il colore del report","en":"The report colour"}]',0,'{"it":"I bug si nascondono ai bordi.","en":"Bugs hide at the edges."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'quality'),3,3,'{"it":"Come si cura un test fragile legato all’ora?","en":"How do you cure a flaky test tied to the time?"}','[{"it":"Fissando l’orologio nel test","en":"By fixing the clock in the test"},{"it":"Rilanciandolo finché passa","en":"Rerunning it until it passes"},{"it":"Aggiungendo uno sleep","en":"Adding a sleep"},{"it":"Cancellandolo","en":"Deleting it"}]',0,'{"it":"Il test deve essere ripetibile.","en":"The test must be repeatable."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'async-time'),1,3,'{"it":"Che succede se dimentichi `await` su `expect(…).rejects`?","en":"What happens if you forget `await` on `expect(…).rejects`?"}','[{"it":"Il test diventa più veloce e preciso","en":"The test gets faster and more precise"},{"it":"Vitest aggiunge `await` da solo","en":"Vitest adds `await` by itself"},{"it":"Il test può passare anche se il codice è sbagliato","en":"The test can pass even if the code is wrong"},{"it":"Il test viene saltato","en":"The test is skipped"}]',2,'{"it":"Il controllo arriva dopo la fine del test.","en":"The check arrives after the test has ended."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'async-time'),2,3,'{"it":"A che cosa serve `vi.advanceTimersByTime(2000)`?","en":"What is `vi.advanceTimersByTime(2000)` for?"}','[{"it":"Aspetta davvero 2 secondi","en":"Really waits 2 seconds"},{"it":"Fa avanzare il tempo finto di 2 secondi","en":"Moves fake time forward by 2 seconds"},{"it":"Rallenta il test","en":"Slows the test down"},{"it":"Cambia il fuso orario","en":"Changes the time zone"}]',1,'{"it":"I timer scattano subito, senza attesa reale.","en":"Timers fire at once, with no real wait."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'async-time'),3,3,'{"it":"Come rendi ripetibile un test che dipende dalla data di oggi?","en":"How do you make a test that depends on today’s date repeatable?"}','[{"it":"Eseguendolo sempre alla stessa ora","en":"By always running it at the same time"},{"it":"Con uno `sleep`","en":"With a `sleep`"},{"it":"Togliendo il test","en":"By removing the test"},{"it":"Con `vi.setSystemTime(…)`","en":"With `vi.setSystemTime(…)`"}]',3,'{"it":"La data finta è la stessa a ogni esecuzione.","en":"The fake date is the same on every run."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'network-mocks'),1,3,'{"it":"Che cosa fa MSW?","en":"What does MSW do?"}','[{"it":"Velocizza il server vero","en":"Speeds up the real server"},{"it":"Scrive i test da solo","en":"Writes the tests by itself"},{"it":"Sostituisce il database","en":"Replaces the database"},{"it":"Intercetta le richieste di rete e dà risposte finte","en":"Intercepts network requests and gives fake responses"}]',3,'{"it":"Il codice non sa di parlare con un finto server.","en":"The code does not know it is talking to a fake server."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'network-mocks'),2,3,'{"it":"A che cosa serve `server.resetHandlers()` dopo ogni test?","en":"What is `server.resetHandlers()` after each test for?"}','[{"it":"Spegne il server","en":"Shuts down the server"},{"it":"Toglie le risposte cambiate con `server.use`","en":"Removes the responses changed with `server.use`"},{"it":"Cancella i test","en":"Deletes the tests"},{"it":"Svuota la cache del browser","en":"Clears the browser cache"}]',1,'{"it":"Ogni test riparte dalle risposte di base.","en":"Each test restarts from the base responses."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'network-mocks'),3,3,'{"it":"Che vantaggio ha MSW su un mock scritto a mano di `fetch`?","en":"What advantage does MSW have over a hand-written `fetch` mock?"}','[{"it":"I test restano validi anche se cambi libreria HTTP","en":"Tests stay valid even if you change HTTP library"},{"it":"Non servono più test","en":"Tests are no longer needed"},{"it":"È sempre più veloce di tutto","en":"It is always faster than anything"},{"it":"Funziona senza JavaScript","en":"It works without JavaScript"}]',0,'{"it":"Simula la rete, non una funzione precisa.","en":"It fakes the network, not one specific function."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'ui-components'),1,3,'{"it":"Quale ricerca aspetta un elemento che apparirà dopo una richiesta?","en":"Which query waits for an element that will appear after a request?"}','[{"it":"getByText","en":"getByText"},{"it":"queryByText","en":"queryByText"},{"it":"findByText","en":"findByText"},{"it":"getAllByText","en":"getAllByText"}]',2,'{"it":"`findBy…` restituisce una promessa.","en":"`findBy…` returns a promise."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'ui-components'),2,3,'{"it":"Come verifichi che un messaggio di errore NON ci sia?","en":"How do you check that an error message is NOT there?"}','[{"it":"expect(screen.getByText(\\"Errore\\")).toBeNull()","en":"expect(screen.getByText(\\"Errore\\")).toBeNull()"},{"it":"expect(screen.queryByText(\\"Errore\\")).toBeNull()","en":"expect(screen.queryByText(\\"Errore\\")).toBeNull()"},{"it":"expect(findByText(\\"Errore\\")).toBe(false)","en":"expect(findByText(\\"Errore\\")).toBe(false)"},{"it":"expect(screen).not.toBe(\\"Errore\\")","en":"expect(screen).not.toBe(\\"Errore\\")"}]',1,'{"it":"`getBy…` lancerebbe un errore prima del controllo.","en":"`getBy…` would throw before the check."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'ui-components'),3,3,'{"it":"Perché preferire `getByRole` a una classe CSS?","en":"Why prefer `getByRole` over a CSS class?"}','[{"it":"Trova gli elementi come un utente e premia l’accessibilità","en":"It finds elements like a user and rewards accessibility"},{"it":"È l’unico metodo che esiste","en":"It is the only method there is"},{"it":"È sempre più veloce da scrivere","en":"It is always quicker to write"},{"it":"Le classi non funzionano nei test","en":"Classes do not work in tests"}]',0,'{"it":"Il test sopravvive anche se cambi lo stile.","en":"The test survives even if you change the styling."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'principles'),1,2,'{"it":"Che cosa dice il principio DRY?","en":"What does the DRY principle say?"}','[{"it":"Non duplicare la logica","en":"Do not duplicate logic"},{"it":"Scrivi meno commenti","en":"Write fewer comments"},{"it":"Usa solo variabili globali","en":"Use only global variables"},{"it":"Non testare","en":"Do not test"}]',0,'{"it":"Don’t Repeat Yourself.","en":"Don’t Repeat Yourself."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'principles'),2,2,'{"it":"Che cosa significa la S di SOLID?","en":"What does the S in SOLID mean?"}','[{"it":"Singola responsabilità","en":"Single responsibility"},{"it":"Sicurezza","en":"Security"},{"it":"Semplicità","en":"Simplicity"},{"it":"Sintassi","en":"Syntax"}]',0,'{"it":"Un solo motivo per cambiare.","en":"One reason to change."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'principles'),3,2,'{"it":"Perché i nomi chiari sono importanti?","en":"Why do clear names matter?"}','[{"it":"Il codice si legge molte più volte di quante si scriva","en":"Code is read far more often than written"},{"it":"Occupano meno spazio nel file compilato","en":"They take less space in the compiled file"},{"it":"Il compilatore lo richiede","en":"The compiler requires it"},{"it":"Non lo sono","en":"They do not"}]',0,'{"it":"Leggibilità prima di tutto.","en":"Readability first."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'creational'),1,2,'{"it":"Che cosa fa una Factory?","en":"What does a Factory do?"}','[{"it":"Decide quale classe istanziare","en":"Decides which class to instantiate"},{"it":"Cancella oggetti","en":"Deletes objects"},{"it":"Ordina un elenco","en":"Sorts a list"},{"it":"Stampa log","en":"Prints logs"}]',0,'{"it":"Il chiamante non deve saperlo.","en":"The caller need not know."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'creational'),2,2,'{"it":"Quando è utile un Builder?","en":"When is a Builder useful?"}','[{"it":"Per oggetti complessi con molte opzioni","en":"For complex objects with many options"},{"it":"Per numeri interi","en":"For integers"},{"it":"Mai","en":"Never"},{"it":"Per cancellare oggetti non più usati","en":"For deleting objects no longer used"}]',0,'{"it":"Passo dopo passo.","en":"Step by step."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'creational'),3,2,'{"it":"Perché usare il Singleton con parsimonia?","en":"Why use the Singleton sparingly?"}','[{"it":"È stato globale e complica i test","en":"It is global state and complicates tests"},{"it":"È troppo veloce","en":"It is too fast"},{"it":"Non esiste in TypeScript","en":"It does not exist in TypeScript"},{"it":"Consuma troppa memoria","en":"It uses too much memory"}]',0,'{"it":"Meglio passare le dipendenze.","en":"Better to pass dependencies."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'structural'),1,2,'{"it":"Che cosa fa un Adapter?","en":"What does an Adapter do?"}','[{"it":"Fa parlare interfacce incompatibili","en":"Makes incompatible interfaces talk"},{"it":"Cancella una classe","en":"Deletes a class"},{"it":"Cifra i dati","en":"Encrypts data"},{"it":"Duplica gli oggetti per usarli in parallelo","en":"Duplicates objects to use them in parallel"}]',0,'{"it":"Come una presa da viaggio.","en":"Like a travel plug."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'structural'),2,2,'{"it":"Come aggiunge comportamento un Decorator?","en":"How does a Decorator add behaviour?"}','[{"it":"Avvolgendo l’oggetto originale","en":"By wrapping the original object"},{"it":"Modificando la classe originale","en":"By modifying the original class"},{"it":"Copiando il codice","en":"By copying code"},{"it":"Non lo aggiunge","en":"It does not"}]',0,'{"it":"Stessa interfaccia, più funzioni.","en":"Same interface, more features."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'structural'),3,2,'{"it":"A che cosa serve una Facade?","en":"What is a Facade for?"}','[{"it":"Un’interfaccia semplice per un sistema complesso","en":"A simple interface for a complex system"},{"it":"Una facciata grafica per l’interfaccia utente","en":"A graphical facade for the user interface"},{"it":"Un database","en":"A database"},{"it":"Un test","en":"A test"}]',0,'{"it":"Nasconde la complessità.","en":"It hides complexity."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'behavioral'),1,2,'{"it":"Che cosa incapsula una Strategy?","en":"What does a Strategy encapsulate?"}','[{"it":"Algoritmi intercambiabili","en":"Interchangeable algorithms"},{"it":"Una password","en":"A password"},{"it":"Un database","en":"A database"},{"it":"Uno stile CSS","en":"A CSS style"}]',0,'{"it":"Stessa interfaccia, calcolo diverso.","en":"Same interface, different calculation."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'behavioral'),2,2,'{"it":"Quale pattern è alla base di addEventListener?","en":"Which pattern underlies addEventListener?"}','[{"it":"Observer","en":"Observer"},{"it":"Singleton","en":"Singleton"},{"it":"Builder","en":"Builder"},{"it":"Adapter","en":"Adapter"}]',0,'{"it":"Ascoltatori avvisati.","en":"Listeners notified."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'behavioral'),3,2,'{"it":"A che cosa è utile il pattern Command?","en":"What is the Command pattern useful for?"}','[{"it":"Code di lavori e funzione annulla","en":"Job queues and undo"},{"it":"Disegnare forme","en":"Drawing shapes"},{"it":"Leggere file","en":"Reading files"},{"it":"Compilare","en":"Compiling"}]',0,'{"it":"L’azione diventa un oggetto.","en":"The action becomes an object."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'architecture'),1,2,'{"it":"Che cosa fa l’iniezione delle dipendenze?","en":"What does dependency injection do?"}','[{"it":"Passa all’oggetto ciò di cui ha bisogno","en":"Hands the object what it needs"},{"it":"Crea tutto dentro la classe","en":"Creates everything inside the class"},{"it":"Inietta codice malevolo","en":"Injects malicious code"},{"it":"Cancella le dipendenze","en":"Deletes dependencies"}]',0,'{"it":"Così si testa con un finto.","en":"So it can be tested with a fake."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'architecture'),2,2,'{"it":"Che cosa non deve cambiare in un refactoring?","en":"What must not change in a refactoring?"}','[{"it":"Il comportamento","en":"The behaviour"},{"it":"I nomi","en":"The names"},{"it":"La struttura","en":"The structure"},{"it":"I file","en":"The files"}]',0,'{"it":"Solo la forma migliora.","en":"Only the shape improves."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'architecture'),3,2,'{"it":"Quale è un code smell?","en":"Which is a code smell?"}','[{"it":"Codice copiato in più punti","en":"Code copied in several places"},{"it":"Una funzione con un nome chiaro","en":"A function with a clear name"},{"it":"Un test verde","en":"A green test"},{"it":"Un commento utile","en":"A useful comment"}]',0,'{"it":"La duplicazione va tolta.","en":"Duplication should go."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'composition'),1,3,'{"it":"Perché preferire la composizione all’ereditarietà?","en":"Why prefer composition to inheritance?"}','[{"it":"Perché le classi figlie sono più lente","en":"Because child classes are slower"},{"it":"Perché unisce parti piccole e indipendenti, senza gerarchie rigide","en":"Because it joins small, independent parts, without rigid hierarchies"},{"it":"Perché TypeScript non permette l’ereditarietà","en":"Because TypeScript does not allow inheritance"},{"it":"Perché così non servono più le interfacce","en":"Because then interfaces are no longer needed"}]',1,'{"it":"Meno legami, più flessibilità.","en":"Fewer ties, more flexibility."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'composition'),2,3,'{"it":"Quale pattern tratta un gruppo di oggetti come un oggetto solo?","en":"Which pattern treats a group of objects as a single object?"}','[{"it":"Proxy","en":"Proxy"},{"it":"Singleton","en":"Singleton"},{"it":"Composite","en":"Composite"},{"it":"Builder","en":"Builder"}]',2,'{"it":"Come una cartella che contiene cartelle.","en":"Like a folder containing folders."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'composition'),3,3,'{"it":"Che differenza c’è tra Proxy e Decorator?","en":"What is the difference between Proxy and Decorator?"}','[{"it":"Il Proxy cambia interfaccia, il Decorator no","en":"The Proxy changes the interface, the Decorator does not"},{"it":"Il Decorator funziona solo con le classi astratte","en":"The Decorator only works with abstract classes"},{"it":"Nessuna: sono due nomi dello stesso pattern","en":"None: they are two names for one pattern"},{"it":"Il Proxy controlla l’accesso, il Decorator aggiunge comportamento","en":"The Proxy controls access, the Decorator adds behaviour"}]',3,'{"it":"Stessa forma, scopo diverso.","en":"Same shape, different purpose."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'state'),1,3,'{"it":"Quale problema risolve il pattern State?","en":"Which problem does the State pattern solve?"}','[{"it":"Oggetti troppo grandi da salvare nel database","en":"Objects too large to store in the database"},{"it":"Classi che non si possono istanziare","en":"Classes that cannot be instantiated"},{"it":"Comportamento che cambia con lo stato, senza if sparsi ovunque","en":"Behaviour that changes with state, without ifs scattered everywhere"},{"it":"Funzioni chiamate troppe volte di seguito","en":"Functions called too many times in a row"}]',2,'{"it":"Stati e transizioni diventano espliciti.","en":"States and transitions become explicit."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'state'),2,3,'{"it":"Con la tabella dell’esempio, che cosa succede chiamando `passaA(\\"pagato\\")` su un ordine consegnato?","en":"With the example’s table, what happens when calling `passaA(\\"pagato\\")` on a delivered order?"}','[{"it":"L’ordine torna allo stato pagato","en":"The order goes back to paid"},{"it":"Viene lanciato un errore: la transizione non è ammessa","en":"An error is thrown: the transition is not allowed"},{"it":"Non succede niente, in silenzio","en":"Nothing happens, silently"},{"it":"L’ordine viene cancellato","en":"The order is deleted"}]',1,'{"it":"Da consegnato non si va da nessuna parte.","en":"From delivered you go nowhere."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'state'),3,3,'{"it":"Perché usare `Record<Stato, Stato[]>` per la tabella?","en":"Why use `Record<Stato, Stato[]>` for the table?"}','[{"it":"Per salvare gli ordini nel database","en":"To save the orders in the database"},{"it":"Per ordinare gli stati in ordine alfabetico","en":"To sort the states alphabetically"},{"it":"Per rendere gli stati modificabili da chiunque","en":"To make the states editable by anyone"},{"it":"Perché il compilatore controlli che ogni stato abbia le sue transizioni","en":"So the compiler checks that every state has its transitions"}]',3,'{"it":"Uno stato dimenticato è un errore di compilazione.","en":"A forgotten state is a compile error."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'chain'),1,3,'{"it":"Che cosa succede se un middleware non chiama `avanti()`?","en":"What happens if a middleware does not call `avanti()`?"}','[{"it":"La catena si ferma e risponde quel middleware","en":"The chain stops and that middleware answers"},{"it":"Il framework lo richiama da solo dopo un po’","en":"The framework calls it again by itself after a while"},{"it":"Viene saltato e si passa al successivo","en":"It is skipped and the next one runs"},{"it":"Si genera sempre un errore 500","en":"A 500 error is always raised"}]',0,'{"it":"Così l’autenticazione blocca chi non è entrato.","en":"That is how authentication blocks those not signed in."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'chain'),2,3,'{"it":"Perché mettere l’autenticazione prima del gestore finale?","en":"Why put authentication before the final handler?"}','[{"it":"Per rendere la risposta più veloce","en":"To make the response faster"},{"it":"Perché così i log sono più corti","en":"Because then the logs are shorter"},{"it":"Perché il framework non accetta altri ordini","en":"Because the framework accepts no other order"},{"it":"Per bloccare chi non è autenticato prima che arrivi ai dati","en":"To block unauthenticated users before they reach the data"}]',3,'{"it":"L’ordine della catena è una scelta di sicurezza.","en":"The order of the chain is a security choice."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'chain'),3,3,'{"it":"Quale pattern c’è dietro i middleware?","en":"Which pattern lies behind middleware?"}','[{"it":"Singleton","en":"Singleton"},{"it":"Catena di responsabilità","en":"Chain of responsibility"},{"it":"Factory","en":"Factory"},{"it":"Composite","en":"Composite"}]',1,'{"it":"Ogni anello decide se rispondere o passare.","en":"Each link decides whether to answer or pass on."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'layers'),1,3,'{"it":"Che cosa nasconde un Repository?","en":"What does a Repository hide?"}','[{"it":"L’interfaccia grafica dell’app","en":"The app’s user interface"},{"it":"I dettagli dell’archivio dati, come le query SQL","en":"The details of data storage, such as SQL queries"},{"it":"Le regole di business del dominio","en":"The domain’s business rules"},{"it":"I test automatici del progetto","en":"The project’s automated tests"}]',1,'{"it":"Il resto del codice vede solo `trova` e `salva`.","en":"The rest of the code sees only `trova` and `salva`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'layers'),2,3,'{"it":"Nell’architettura esagonale, dove va il codice specifico del database?","en":"In the hexagonal architecture, where does database-specific code go?"}','[{"it":"Nel nucleo, insieme alle regole","en":"In the core, with the rules"},{"it":"Dentro i test","en":"Inside the tests"},{"it":"In un adattatore che realizza una porta del nucleo","en":"In an adapter implementing one of the core’s ports"},{"it":"Nel file di configurazione del framework","en":"In the framework’s configuration file"}]',2,'{"it":"Il nucleo resta pulito.","en":"The core stays clean."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'design-patterns' AND slug = 'layers'),3,3,'{"it":"Che cosa dice YAGNI?","en":"What does YAGNI say?"}','[{"it":"Ogni classe deve avere la sua interfaccia","en":"Every class must have its own interface"},{"it":"Bisogna prevedere ogni possibile uso futuro","en":"You must foresee every possible future use"},{"it":"Le funzioni devono avere al massimo tre righe","en":"Functions must have at most three lines"},{"it":"Non aggiungere ciò che non serve ancora","en":"Do not add what is not needed yet"}]',3,'{"it":"Astrazioni quando servono, non prima.","en":"Abstractions when needed, not before."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'classes'),1,1,'{"it":"Che cosa trova `\\\\d`?","en":"What does `\\\\d` match?"}','[{"it":"Una cifra","en":"A digit"},{"it":"Una lettera","en":"A letter"},{"it":"Uno spazio","en":"A space"},{"it":"Un punto","en":"A dot"}]',0,'{"it":"d = digit.","en":"d = digit."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'classes'),2,1,'{"it":"Che cosa trova `[^0-9]`?","en":"What does `[^0-9]` match?"}','[{"it":"Qualsiasi carattere tranne le cifre","en":"Any character except digits"},{"it":"Solo le cifre","en":"Only digits"},{"it":"L’inizio della riga","en":"Start of line"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"^ dentro le quadre nega.","en":"^ inside brackets negates."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'classes'),3,1,'{"it":"Come trovi un punto vero?","en":"How do you match a real dot?"}','[{"it":"\\\\.","en":"\\\\."},{"it":".","en":"."},{"it":"\\\\s","en":"\\\\s"},{"it":"\\\\d","en":"\\\\d"}]',0,'{"it":"Il punto da solo vale qualsiasi carattere.","en":"A bare dot means any character."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'quantifiers'),1,1,'{"it":"Che cosa significa `+`?","en":"What does `+` mean?"}','[{"it":"Una o più volte","en":"One or more times"},{"it":"Zero o più volte","en":"Zero or more times"},{"it":"Esattamente una volta","en":"Exactly once"},{"it":"Una somma","en":"A sum"}]',0,'{"it":"`*` permette anche zero.","en":"`*` also allows zero."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'quantifiers'),2,1,'{"it":"Perché usare `^` e `$` nella validazione?","en":"Why use `^` and `$` in validation?"}','[{"it":"Per controllare tutto il campo, non una parte","en":"To check the whole field, not a part"},{"it":"Per rendere la regex più veloce da eseguire","en":"To make the regex faster to run"},{"it":"Non servono","en":"They are not needed"},{"it":"Per i colori","en":"For colours"}]',0,'{"it":"Altrimenti “abc12345xyz” passerebbe per un CAP.","en":"Otherwise “abc12345xyz” would pass as a postcode."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'quantifiers'),3,1,'{"it":"Che cosa fa `\\\\b`?","en":"What does `\\\\b` do?"}','[{"it":"Indica un confine di parola","en":"Marks a word boundary"},{"it":"Trova una b","en":"Matches a b"},{"it":"Trova uno spazio","en":"Matches a space"},{"it":"Indica la fine del file","en":"Marks end of file"}]',0,'{"it":"Parole intere.","en":"Whole words."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'groups'),1,1,'{"it":"Che cosa fa `|` in una regex?","en":"What does `|` do in a regex?"}','[{"it":"Indica un’alternativa","en":"Means an alternative"},{"it":"Una pipe di Bash","en":"A Bash pipe"},{"it":"Fine della riga","en":"End of line"},{"it":"Un carattere qualsiasi","en":"Any character"}]',0,'{"it":"`jpg|png`.","en":"`jpg|png`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'groups'),2,1,'{"it":"Come si richiama il primo gruppo in una sostituzione JavaScript?","en":"How do you reference the first group in a JavaScript replacement?"}','[{"it":"$1","en":"$1"},{"it":"\\\\0","en":"\\\\0"},{"it":"%1","en":"%1"},{"it":"#1","en":"#1"}]',0,'{"it":"In Python `\\\\1`.","en":"In Python `\\\\1`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'groups'),3,1,'{"it":"Che cosa fa `(?:…)`?","en":"What does `(?:…)` do?"}','[{"it":"Raggruppa senza catturare","en":"Groups without capturing"},{"it":"Cattura due volte","en":"Captures twice"},{"it":"Nega il gruppo","en":"Negates the group"},{"it":"Commenta","en":"Comments"}]',0,'{"it":"Solo per raggruppare.","en":"Just for grouping."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'code'),1,1,'{"it":"Che cosa fa il flag `g` in JavaScript?","en":"What does the `g` flag do in JavaScript?"}','[{"it":"Trova tutte le occorrenze","en":"Finds all occurrences"},{"it":"Ignora maiuscole","en":"Ignores case"},{"it":"Rende la regex più veloce","en":"Makes the regex faster"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"g = global.","en":"g = global."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'code'),2,1,'{"it":"Perché in Python si usano le stringhe raw `r\\"…\\"`?","en":"Why use raw strings `r\\"…\\"` in Python?"}','[{"it":"Per non raddoppiare le barre rovesciate","en":"To avoid doubling backslashes"},{"it":"Sono più veloci","en":"They are faster"},{"it":"Sono obbligatorie per legge","en":"They are legally required"},{"it":"Per i colori","en":"For colours"}]',0,'{"it":"`r\\"\\\\d\\"` invece di `\\"\\\\\\\\d\\"`.","en":"`r\\"\\\\d\\"` instead of `\\"\\\\\\\\d\\"`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'code'),3,1,'{"it":"Che cosa restituisce `re.findall`?","en":"What does `re.findall` return?"}','[{"it":"L’elenco di tutte le corrispondenze","en":"The list of all matches"},{"it":"Solo la prima","en":"Only the first"},{"it":"Un booleano","en":"A boolean"},{"it":"Il testo sostituito","en":"The replaced text"}]',0,'{"it":"Una lista.","en":"A list."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'lookaround'),1,2,'{"it":"Che cosa fa `(?=\\\\d)`?","en":"What does `(?=\\\\d)` do?"}','[{"it":"Controlla che segua una cifra senza consumarla","en":"Checks a digit follows without consuming it"},{"it":"Cattura una cifra","en":"Captures a digit"},{"it":"Esclude le cifre","en":"Excludes digits"},{"it":"Cerca all’indietro","en":"Looks backwards"}]',0,'{"it":"È un lookahead.","en":"It is a lookahead."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'lookaround'),2,2,'{"it":"Come si scrive un gruppo con nome?","en":"How do you write a named group?"}','[{"it":"(?<nome>…)","en":"(?<nome>…)"},{"it":"(nome:…)","en":"(nome:…)"},{"it":"{nome}…","en":"{nome}…"},{"it":"[nome]…","en":"[nome]…"}]',0,'{"it":"In JavaScript lo leggi con `groups.nome`; Python usa `(?P<nome>…)`.","en":"In JavaScript you read it with `groups.nome`; Python uses `(?P<nome>…)`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'lookaround'),3,2,'{"it":"Quale modello rischia il backtracking catastrofico?","en":"Which pattern risks catastrophic backtracking?"}','[{"it":"(a+)+$","en":"(a+)+$"},{"it":"^a+$","en":"^a+$"},{"it":"\\\\d{4}","en":"\\\\d{4}"},{"it":"[a-z]","en":"[a-z]"}]',0,'{"it":"Quantificatori annidati.","en":"Nested quantifiers."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'unicode'),1,2,'{"it":"Quale flag fa prendere al punto anche l’a capo, in JavaScript?","en":"Which flag makes the dot match newlines too, in JavaScript?"}','[{"it":"g","en":"g"},{"it":"m","en":"m"},{"it":"s","en":"s"},{"it":"i","en":"i"}]',2,'{"it":"s = dotAll.","en":"s = dotAll."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'unicode'),2,2,'{"it":"Che cosa trova `\\\\p{L}` con il flag `u`?","en":"What does `\\\\p{L}` match with the `u` flag?"}','[{"it":"Solo le lettere latine senza accenti","en":"Only Latin letters without accents"},{"it":"Una lettera di qualsiasi alfabeto, anche accentata","en":"A letter of any alphabet, accented too"},{"it":"Un segno di punteggiatura","en":"A punctuation mark"},{"it":"La lettera L maiuscola","en":"The capital letter L"}]',1,'{"it":"L = letter, nelle categorie Unicode.","en":"L = letter, in the Unicode categories."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'unicode'),3,2,'{"it":"Che cosa trova `\\\\b(\\\\w+)\\\\s+\\\\1\\\\b`?","en":"What does `\\\\b(\\\\w+)\\\\s+\\\\1\\\\b` match?"}','[{"it":"Due parole qualsiasi separate da uno spazio","en":"Any two words separated by a space"},{"it":"Una parola seguita dal numero 1","en":"A word followed by the number 1"},{"it":"Una parola all’inizio della riga","en":"A word at the start of the line"},{"it":"La stessa parola ripetuta due volte di fila","en":"The same word repeated twice in a row"}]',3,'{"it":"`\\\\1` ripete il testo del gruppo 1.","en":"`\\\\1` repeats group 1’s text."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'tools'),1,2,'{"it":"Perché `grep -E \\"\\\\d+\\"` può non funzionare come ti aspetti?","en":"Why might `grep -E \\"\\\\d+\\"` not work as you expect?"}','[{"it":"Perché grep cerca solo testo esatto","en":"Because grep searches exact text only"},{"it":"Perché -E disattiva le regex","en":"Because -E turns regex off"},{"it":"Perché le regex POSIX estese non conoscono `\\\\d`: si usa `[0-9]`","en":"Because POSIX extended regex do not know `\\\\d`: you use `[0-9]`"},{"it":"Perché `\\\\d` funziona solo sulle lettere","en":"Because `\\\\d` only works on letters"}]',2,'{"it":"Oppure `[[:digit:]]`.","en":"Or `[[:digit:]]`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'tools'),2,2,'{"it":"Nella sostituzione di `sed -E`, come richiami il gruppo 1?","en":"In a `sed -E` replacement, how do you refer to group 1?"}','[{"it":"$1","en":"$1"},{"it":"\\\\1","en":"\\\\1"},{"it":"%1","en":"%1"},{"it":"{1}","en":"{1}"}]',1,'{"it":"`$1` si usa in JavaScript e negli editor.","en":"`$1` is used in JavaScript and editors."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'tools'),3,2,'{"it":"Quale motore garantisce un tempo lineare ma non ha lookaround?","en":"Which engine guarantees linear time but has no lookarounds?"}','[{"it":"PCRE","en":"PCRE"},{"it":"Il motore di JavaScript","en":"JavaScript’s engine"},{"it":"Il modulo re di Python","en":"Python’s re module"},{"it":"RE2","en":"RE2"}]',3,'{"it":"Niente backtracking, niente ReDoS.","en":"No backtracking, no ReDoS."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'rest'),1,2,'{"it":"Qual è un buon percorso REST per gli utenti?","en":"What is a good REST path for users?"}','[{"it":"/utenti","en":"/utenti"},{"it":"/getUtenti","en":"/getUtenti"},{"it":"/creaUtente","en":"/creaUtente"},{"it":"/utente_lista_tutti","en":"/utente_lista_tutti"}]',0,'{"it":"Nomi, non verbi.","en":"Nouns, not verbs."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'rest'),2,2,'{"it":"Quale metodo crea una nuova risorsa?","en":"Which method creates a new resource?"}','[{"it":"POST","en":"POST"},{"it":"GET","en":"GET"},{"it":"DELETE","en":"DELETE"},{"it":"HEAD","en":"HEAD"}]',0,'{"it":"Con i dati nel corpo.","en":"With data in the body."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'rest'),3,2,'{"it":"Che cosa significa che PUT è idempotente?","en":"What does it mean that PUT is idempotent?"}','[{"it":"Ripeterlo dà lo stesso risultato","en":"Repeating it gives the same result"},{"it":"È più veloce","en":"It is faster"},{"it":"Non modifica niente","en":"It changes nothing"},{"it":"Crea duplicati","en":"It creates duplicates"}]',0,'{"it":"POST invece no.","en":"POST is not."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'status'),1,2,'{"it":"Quale codice per una risorsa appena creata?","en":"Which code for a newly created resource?"}','[{"it":"201","en":"201"},{"it":"200","en":"200"},{"it":"204","en":"204"},{"it":"302","en":"302"}]',0,'{"it":"Created.","en":"Created."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'status'),2,2,'{"it":"Che differenza c’è tra 401 e 403?","en":"What is the difference between 401 and 403?"}','[{"it":"401 non autenticato, 403 autenticato ma senza permesso","en":"401 not authenticated, 403 authenticated but not allowed"},{"it":"Nessuna","en":"None"},{"it":"403 è un errore del server, 401 del client","en":"403 is a server error, 401 a client one"},{"it":"401 significa successo","en":"401 means success"}]',0,'{"it":"Chi sei vs cosa puoi fare.","en":"Who you are vs what you may do."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'status'),3,2,'{"it":"Che cosa indicano i codici 5xx?","en":"What do 5xx codes mean?"}','[{"it":"Errori del server","en":"Server errors"},{"it":"Successo","en":"Success"},{"it":"Errori del client","en":"Client errors"},{"it":"Redirezioni","en":"Redirects"}]',0,'{"it":"4xx sono del client.","en":"4xx are client errors."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'practices'),1,2,'{"it":"Perché paginare una lista?","en":"Why paginate a list?"}','[{"it":"Per non restituire migliaia di elementi insieme","en":"To avoid returning thousands of items at once"},{"it":"Per abbellirla","en":"To make it pretty"},{"it":"È vietato non farlo","en":"It is forbidden not to"},{"it":"Per cifrare i dati pagina per pagina","en":"To encrypt the data page by page"}]',0,'{"it":"Risposte leggere.","en":"Light responses."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'practices'),2,2,'{"it":"Dove si mette il token di accesso?","en":"Where does the access token go?"}','[{"it":"Nell’intestazione Authorization","en":"In the Authorization header"},{"it":"Nell’URL","en":"In the URL"},{"it":"Nel nome del file","en":"In the file name"},{"it":"In un commento","en":"In a comment"}]',0,'{"it":"Mai nell’URL, finisce nei log.","en":"Never in the URL, it ends up in logs."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'practices'),3,2,'{"it":"Quando creare una nuova versione dell’API?","en":"When should you create a new API version?"}','[{"it":"Quando un cambiamento rompe i client esistenti","en":"When a change breaks existing clients"},{"it":"Ogni giorno","en":"Every day"},{"it":"Mai","en":"Never"},{"it":"Quando cambi il logo","en":"When you change the logo"}]',0,'{"it":"E mantieni la vecchia per un po’.","en":"And keep the old one a while."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'graphql'),1,2,'{"it":"Quanti endpoint ha di solito un’API GraphQL?","en":"How many endpoints does a GraphQL API usually have?"}','[{"it":"Uno","en":"One"},{"it":"Uno per risorsa","en":"One per resource"},{"it":"Nessuno","en":"None"},{"it":"Uno per campo","en":"One per field"}]',0,'{"it":"La query dice cosa vuoi.","en":"The query says what you want."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'graphql'),2,2,'{"it":"Come si modificano i dati in GraphQL?","en":"How is data changed in GraphQL?"}','[{"it":"Con le mutation","en":"With mutations"},{"it":"Con GET","en":"With GET"},{"it":"Con le query","en":"With queries"},{"it":"Non si può","en":"You cannot"}]',0,'{"it":"Query leggono, mutation modificano.","en":"Queries read, mutations change."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'graphql'),3,2,'{"it":"Qual è un vantaggio di GraphQL?","en":"What is an advantage of GraphQL?"}','[{"it":"Il client chiede esattamente i campi che servono","en":"The client asks for exactly the fields it needs"},{"it":"Si mette in cache più facilmente di REST","en":"It caches more easily than REST"},{"it":"Non ha bisogno di uno schema","en":"It needs no schema"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Niente dati in più.","en":"No extra data."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'docs'),1,2,'{"it":"Che cosa descrive un file OpenAPI?","en":"What does an OpenAPI file describe?"}','[{"it":"Rotte, parametri, risposte ed errori","en":"Routes, parameters, responses and errors"},{"it":"Il database","en":"The database"},{"it":"Il design grafico","en":"The graphic design"},{"it":"I server fisici","en":"The physical servers"}]',0,'{"it":"Da lì nascono documentazione e client.","en":"Docs and clients come from it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'docs'),2,2,'{"it":"Quale codice indica troppe richieste?","en":"Which code means too many requests?"}','[{"it":"429","en":"429"},{"it":"404","en":"404"},{"it":"500","en":"500"},{"it":"201","en":"201"}]',0,'{"it":"Con `Retry-After`.","en":"With `Retry-After`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'docs'),3,2,'{"it":"Perché verificare la firma di un webhook?","en":"Why verify a webhook’s signature?"}','[{"it":"Per sapere che arriva davvero dal servizio","en":"To know it really comes from the service"},{"it":"Per renderlo più veloce","en":"To make it faster"},{"it":"Per tradurlo","en":"To translate it"},{"it":"Non serve","en":"It is not needed"}]',0,'{"it":"Chiunque può fare una POST.","en":"Anyone can send a POST."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'caching'),1,3,'{"it":"Che cosa significa `304 Not Modified`?","en":"What does `304 Not Modified` mean?"}','[{"it":"La risorsa non esiste più","en":"The resource no longer exists"},{"it":"La copia del client è ancora valida: niente corpo da scaricare","en":"The client’s copy is still valid: no body to download"},{"it":"Il server non ha capito la richiesta","en":"The server did not understand the request"},{"it":"La modifica è stata rifiutata","en":"The change was rejected"}]',1,'{"it":"Si risparmiano banda e tempo.","en":"Bandwidth and time are saved."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'caching'),2,3,'{"it":"Quale intestazione per una risposta con dati personali da non salvare mai?","en":"Which header for a response with personal data never to be stored?"}','[{"it":"Cache-Control: public, max-age=3600","en":"Cache-Control: public, max-age=3600"},{"it":"ETag: \\"v1\\"","en":"ETag: \\"v1\\""},{"it":"Cache-Control: no-store","en":"Cache-Control: no-store"},{"it":"Retry-After: 60","en":"Retry-After: 60"}]',2,'{"it":"Né browser né CDN la conservano.","en":"Neither browsers nor CDNs keep it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'caching'),3,3,'{"it":"Un PUT con `If-Match: \\"v7\\"` arriva quando la risorsa è già a `\\"v8\\"`. Che cosa succede?","en":"A PUT with `If-Match: \\"v7\\"` arrives when the resource is already at `\\"v8\\"`. What happens?"}','[{"it":"Il server sovrascrive comunque la versione nuova","en":"The server overwrites the new version anyway"},{"it":"Il server crea una seconda copia della risorsa","en":"The server creates a second copy of the resource"},{"it":"Il server risponde 304 Not Modified","en":"The server answers 304 Not Modified"},{"it":"Il server risponde 412 Precondition Failed","en":"The server answers 412 Precondition Failed"}]',3,'{"it":"Così non cancelli il lavoro di un altro.","en":"That way you do not wipe someone else’s work."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'idempotency'),1,3,'{"it":"Perché mandare una `Idempotency-Key` con il POST di un pagamento?","en":"Why send an `Idempotency-Key` with a payment POST?"}','[{"it":"Per cifrare l’importo del pagamento","en":"To encrypt the payment amount"},{"it":"Per ottenere una risposta più veloce","en":"To get a faster response"},{"it":"Per non addebitare due volte se la richiesta viene ripetuta","en":"To avoid charging twice if the request is repeated"},{"it":"Per saltare l’autenticazione","en":"To skip authentication"}]',2,'{"it":"Stessa chiave, stesso risultato.","en":"Same key, same result."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'idempotency'),2,3,'{"it":"Per quali errori ha senso riprovare in automatico?","en":"For which errors does an automatic retry make sense?"}','[{"it":"400 Bad Request e 422","en":"400 Bad Request and 422"},{"it":"401 Unauthorized e 403 Forbidden","en":"401 Unauthorized and 403 Forbidden"},{"it":"404 Not Found","en":"404 Not Found"},{"it":"Timeout, 429 e 503","en":"Timeouts, 429 and 503"}]',3,'{"it":"Gli errori del client non cambiano riprovando.","en":"Client errors do not change by retrying."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'idempotency'),3,3,'{"it":"Che cosa significa `202 Accepted`?","en":"What does `202 Accepted` mean?"}','[{"it":"La risorsa è stata creata subito","en":"The resource was created at once"},{"it":"La richiesta è accettata e verrà completata più tardi","en":"The request is accepted and will be completed later"},{"it":"La richiesta è stata rifiutata","en":"The request was refused"},{"it":"Il client deve prima autenticarsi","en":"The client must authenticate first"}]',1,'{"it":"Con un indirizzo dove seguire lo stato.","en":"With an address to follow the status."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'auth'),1,3,'{"it":"Quale flusso OAuth per un’app mobile in cui l’utente accede?","en":"Which OAuth flow for a mobile app where the user signs in?"}','[{"it":"Client credentials","en":"Client credentials"},{"it":"Implicit","en":"Implicit"},{"it":"Authorization code + PKCE","en":"Authorization code + PKCE"},{"it":"Password grant","en":"Password grant"}]',2,'{"it":"PKCE protegge il codice anche senza un segreto nell’app.","en":"PKCE protects the code even without a secret in the app."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'auth'),2,3,'{"it":"Il contenuto di un JWT è segreto?","en":"Is a JWT’s content secret?"}','[{"it":"Sì, è cifrato con la chiave del server","en":"Yes, it is encrypted with the server’s key"},{"it":"No: è solo firmato, chiunque può leggerlo","en":"No: it is only signed, anyone can read it"},{"it":"Sì, se dura meno di un’ora","en":"Yes, if it lasts less than an hour"},{"it":"Solo il campo exp si può leggere","en":"Only the exp field can be read"}]',1,'{"it":"La firma prova che nessuno l’ha modificato.","en":"The signature proves nobody changed it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'auth'),3,3,'{"it":"Che cosa esprime uno scope come `ordini:leggi`?","en":"What does a scope like `ordini:leggi` express?"}','[{"it":"Il server che ha emesso il token","en":"The server that issued the token"},{"it":"La durata del token in secondi","en":"The token’s lifetime in seconds"},{"it":"Il nome dell’utente collegato","en":"The signed-in user’s name"},{"it":"Che cosa il token permette di fare","en":"What the token allows you to do"}]',3,'{"it":"Il server controlla lo scope a ogni richiesta.","en":"The server checks the scope on every request."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'api-security'),1,3,'{"it":"Che cos’è la BOLA?","en":"What is BOLA?"}','[{"it":"Un attacco che rallenta il server con troppe richieste","en":"An attack slowing the server with too many requests"},{"it":"Leggere o cambiare oggetti di altri cambiando l’id nella richiesta","en":"Reading or changing others’ objects by changing the id in the request"},{"it":"Un errore nel formato JSON delle risposte","en":"An error in the responses’ JSON format"},{"it":"Una password debole dell’amministratore","en":"A weak administrator password"}]',1,'{"it":"Il primo rischio della lista API di OWASP.","en":"The top risk on OWASP’s API list."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'api-security'),2,3,'{"it":"Un `PATCH /utenti/7` con il corpo `{\\"ruolo\\": \\"admin\\"}` promuove l’utente. Qual è il problema?","en":"A `PATCH /utenti/7` with the body `{\\"ruolo\\": \\"admin\\"}` promotes the user. What is the problem?"}','[{"it":"Una SQL injection nella query","en":"An SQL injection in the query"},{"it":"Un cross-site scripting nella pagina","en":"Cross-site scripting in the page"},{"it":"Mass assignment: il server accetta campi che non dovrebbe","en":"Mass assignment: the server accepts fields it should not"},{"it":"Un attacco CSRF da un altro sito","en":"A CSRF attack from another site"}]',2,'{"it":"Accetta solo i campi che l’utente può cambiare.","en":"Accept only the fields the user may change."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'api-security'),3,3,'{"it":"Il CORS protegge la tua API da chi usa curl?","en":"Does CORS protect your API from someone using curl?"}','[{"it":"Sì, blocca tutte le richieste da altre origini","en":"Yes, it blocks every request from other origins"},{"it":"Sì, se aggiungi Allow-Credentials","en":"Yes, if you add Allow-Credentials"},{"it":"Solo per le richieste POST","en":"Only for POST requests"},{"it":"No: lo applicano solo i browser, gli altri client lo ignorano","en":"No: only browsers enforce it, other clients ignore it"}]',3,'{"it":"La protezione vera è l’autorizzazione sul server.","en":"The real protection is server-side authorisation."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'keys'),1,2,'{"it":"Dove tiene i dati Redis?","en":"Where does Redis keep data?"}','[{"it":"In memoria","en":"In memory"},{"it":"Solo su carta","en":"Only on paper"},{"it":"In un foglio Excel","en":"In an Excel sheet"},{"it":"Solo su disco, mai in memoria","en":"Only on disk, never in memory"}]',0,'{"it":"Per questo è velocissimo.","en":"That is why it is so fast."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'keys'),2,2,'{"it":"Che cosa fa `EX 3600` in un SET?","en":"What does `EX 3600` do in a SET?"}','[{"it":"Fa scadere la chiave dopo un’ora","en":"Expires the key after an hour"},{"it":"Esporta i dati","en":"Exports the data"},{"it":"Crea 3600 copie","en":"Creates 3600 copies"},{"it":"Cifra il valore","en":"Encrypts the value"}]',0,'{"it":"In secondi.","en":"In seconds."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'keys'),3,2,'{"it":"Perché INCR è sicuro con tante richieste insieme?","en":"Why is INCR safe with many simultaneous requests?"}','[{"it":"È un’operazione atomica","en":"It is an atomic operation"},{"it":"È lento","en":"It is slow"},{"it":"Usa un lucchetto manuale","en":"It uses a manual lock"},{"it":"Non lo è","en":"It is not"}]',0,'{"it":"Nessun conteggio perso.","en":"No lost counts."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'structures'),1,2,'{"it":"Quale struttura è perfetta per una classifica?","en":"Which structure is perfect for a leaderboard?"}','[{"it":"Sorted set","en":"Sorted set"},{"it":"Lista","en":"Lista"},{"it":"Stringa","en":"Stringa"},{"it":"Hash","en":"Hash"}]',0,'{"it":"Ordinato per punteggio.","en":"Ordered by score."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'structures'),2,2,'{"it":"Che cosa garantisce un set?","en":"What does a set guarantee?"}','[{"it":"Nessun doppione","en":"No duplicates"},{"it":"Ordine di inserimento","en":"Insertion order"},{"it":"Scadenza automatica","en":"Automatic expiry"},{"it":"Cifratura","en":"Encryption"}]',0,'{"it":"Elementi unici.","en":"Unique items."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'structures'),3,2,'{"it":"A che cosa serve un hash?","en":"What is a hash for?"}','[{"it":"Un oggetto con più campi","en":"An object with several fields"},{"it":"Una password cifrata","en":"An encrypted password"},{"it":"Una coda","en":"A queue"},{"it":"Un numero casuale","en":"A random number"}]',0,'{"it":"HSET e HGET.","en":"HSET and HGET."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'cache'),1,2,'{"it":"Che cosa fa il pattern cache-aside?","en":"What does the cache-aside pattern do?"}','[{"it":"Cerca in cache, altrimenti calcola e salva","en":"Looks in cache, otherwise computes and stores"},{"it":"Salva tutto solo su disco","en":"Stores everything on disk only"},{"it":"Cancella il database","en":"Deletes the database"},{"it":"Non usa scadenze","en":"Uses no expiry"}]',0,'{"it":"Il più usato.","en":"The most used."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'cache'),2,2,'{"it":"Perché dare una scadenza ai dati in cache?","en":"Why give cached data an expiry?"}','[{"it":"Per non servire dati vecchi per sempre","en":"So stale data is not served forever"},{"it":"Per occupare più memoria","en":"To use more memory"},{"it":"Non serve","en":"It is not needed"},{"it":"Per renderli segreti","en":"To make them secret"}]',0,'{"it":"E liberare memoria.","en":"And free memory."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'cache'),3,2,'{"it":"A che cosa serve il pub/sub?","en":"What is pub/sub for?"}','[{"it":"Inviare messaggi in tempo reale agli iscritti","en":"Sending real-time messages to subscribers"},{"it":"Pubblicare libri","en":"Publishing books"},{"it":"Fare backup automatici su un altro server","en":"Making automatic backups to another server"},{"it":"Comprimere dati","en":"Compressing data"}]',0,'{"it":"Notifiche e chat.","en":"Notifications and chats."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'ops'),1,2,'{"it":"Che cosa succede a Redis senza persistenza dopo un riavvio?","en":"What happens to Redis without persistence after a restart?"}','[{"it":"Perde tutti i dati","en":"It loses all data"},{"it":"Niente","en":"Nothing"},{"it":"Raddoppia i dati","en":"Doubles the data"},{"it":"Li manda per email","en":"Emails them"}]',0,'{"it":"Ok per una cache.","en":"Fine for a cache."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'ops'),2,2,'{"it":"Perché evitare `KEYS *` in produzione?","en":"Why avoid `KEYS *` in production?"}','[{"it":"Blocca il server con molte chiavi","en":"It blocks the server with many keys"},{"it":"Cancella le chiavi che non corrispondono","en":"It deletes keys that do not match"},{"it":"Non esiste","en":"It does not exist"},{"it":"È a pagamento","en":"It costs money"}]',0,'{"it":"Usa SCAN.","en":"Use SCAN."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'ops'),3,2,'{"it":"Che cosa fa `maxmemory-policy allkeys-lru`?","en":"What does `maxmemory-policy allkeys-lru` do?"}','[{"it":"Toglie le chiavi usate meno di recente quando la memoria finisce","en":"Removes least recently used keys when memory runs out"},{"it":"Cifra le chiavi","en":"Encrypts keys"},{"it":"Fa un backup","en":"Makes a backup"},{"it":"Blocca le scritture quando la memoria è piena","en":"Blocks writes when memory is full"}]',0,'{"it":"Perfetto per una cache.","en":"Perfect for a cache."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'realtime'),1,3,'{"it":"Che cosa succede a un messaggio Pub/Sub se nessuno ascolta?","en":"What happens to a Pub/Sub message if nobody listens?"}','[{"it":"Va perso","en":"It is lost"},{"it":"Resta in coda","en":"It stays queued"},{"it":"Torna al mittente","en":"It goes back to the sender"},{"it":"Finisce in uno stream","en":"It goes into a stream"}]',0,'{"it":"Pub/Sub non conserva.","en":"Pub/Sub does not store."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'realtime'),2,3,'{"it":"Quale comando aggiunge a uno stream?","en":"Which command adds to a stream?"}','[{"it":"XADD","en":"XADD"},{"it":"PUBLISH","en":"PUBLISH"},{"it":"LPUSH","en":"LPUSH"},{"it":"SET","en":"SET"}]',0,'{"it":"`*` genera l’ID.","en":"`*` generates the ID."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'realtime'),3,3,'{"it":"Come fai una finestra di 60 secondi per un contatore?","en":"How do you make a 60-second window for a counter?"}','[{"it":"EXPIRE chiave 60","en":"EXPIRE chiave 60"},{"it":"TTL chiave 60","en":"TTL chiave 60"},{"it":"WAIT 60","en":"WAIT 60"},{"it":"SLEEP 60","en":"SLEEP 60"}]',0,'{"it":"Con `INCR` prima.","en":"With `INCR` first."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'transactions'),1,3,'{"it":"Che cosa fa `EXEC` dopo `MULTI`?","en":"What does `EXEC` do after `MULTI`?"}','[{"it":"Annulla tutti i comandi in coda","en":"Cancels every queued command"},{"it":"Esegue di fila tutti i comandi in coda","en":"Runs every queued command in a row"},{"it":"Salva i dati sul disco","en":"Saves the data to disk"},{"it":"Apre una nuova connessione","en":"Opens a new connection"}]',1,'{"it":"`DISCARD` invece svuota la coda.","en":"`DISCARD` empties the queue instead."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'transactions'),2,3,'{"it":"Che cosa succede se una chiave sotto `WATCH` cambia prima di `EXEC`?","en":"What happens if a key under `WATCH` changes before `EXEC`?"}','[{"it":"La transazione viene eseguita due volte","en":"The transaction runs twice"},{"it":"Redis si blocca finché la chiave torna com’era","en":"Redis blocks until the key goes back"},{"it":"La chiave viene cancellata","en":"The key is deleted"},{"it":"La transazione si annulla ed `EXEC` restituisce nil","en":"The transaction aborts and `EXEC` returns nil"}]',3,'{"it":"L’app riprova da capo.","en":"The app retries from the start."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'transactions'),3,3,'{"it":"Se un comando dentro `MULTI` dà errore, che cosa succede agli altri?","en":"If a command inside `MULTI` errors, what happens to the others?"}','[{"it":"Vengono eseguiti lo stesso","en":"They still run"},{"it":"Vengono annullati tutti","en":"They are all rolled back"},{"it":"Vengono rimandati di un’ora","en":"They are postponed by an hour"},{"it":"Diventano uno script Lua","en":"They become a Lua script"}]',0,'{"it":"Redis non ha rollback.","en":"Redis has no rollback."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'json-search'),1,3,'{"it":"Che cosa fa `JSON.GET prodotto:1 $.nome`?","en":"What does `JSON.GET prodotto:1 $.nome` do?"}','[{"it":"Cancella il campo nome","en":"Deletes the name field"},{"it":"Crea un indice sul nome","en":"Creates an index on the name"},{"it":"Legge il campo nome del documento","en":"Reads the document’s name field"},{"it":"Rinomina la chiave","en":"Renames the key"}]',2,'{"it":"`$` è la radice del documento.","en":"`$` is the document root."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'json-search'),2,3,'{"it":"Quali chiavi indicizza `FT.CREATE … PREFIX 1 prodotto:`?","en":"Which keys does `FT.CREATE … PREFIX 1 prodotto:` index?"}','[{"it":"Solo le chiavi già presenti","en":"Only the keys already present"},{"it":"Tutte le chiavi che iniziano con `prodotto:`, anche le future","en":"Every key starting with `prodotto:`, future ones too"},{"it":"Solo la chiave `prodotto:1`","en":"Only the key `prodotto:1`"},{"it":"Tutte le chiavi del database","en":"Every key in the database"}]',1,'{"it":"L’indice si aggiorna da solo.","en":"The index updates itself."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'json-search'),3,3,'{"it":"Da quale versione JSON e Query Engine sono inclusi in Redis?","en":"Since which version are JSON and the Query Engine included in Redis?"}','[{"it":"Redis 8","en":"Redis 8"},{"it":"Redis 2","en":"Redis 2"},{"it":"Redis 5","en":"Redis 5"},{"it":"Non sono mai inclusi","en":"They are never included"}]',0,'{"it":"Prima servivano i moduli di Redis Stack.","en":"Before, you needed the Redis Stack modules."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'redis' AND slug = 'licensing'),1,3,'{"it":"Che cos’è Valkey?","en":"What is Valkey?"}','[{"it":"Un client grafico per Redis","en":"A graphical client for Redis"},{"it":"Un fork open source di Redis, con licenza BSD","en":"An open source fork of Redis, under BSD"},{"it":"Il nuovo nome commerciale di Redis","en":"Redis’s new commercial name"},{"it":"Un database SQL basato su Redis","en":"An SQL database based on Redis"}]',1,'{"it":"Nato nel 2024 sotto la Linux Foundation.","en":"Born in 2024 under the Linux Foundation."}',NULL);
