INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'algorithms' AND slug = 'dp-greedy'),1,2,'{"it":"Che cosa fa la memoizzazione?","en":"What does memoisation do?"}','[{"it":"Salva i risultati già calcolati","en":"Saves results already computed"},{"it":"Ordina i dati","en":"Sorts data"},{"it":"Cancella la ricorsione","en":"Deletes recursion"},{"it":"Usa meno variabili","en":"Uses fewer variables"}]',0,'{"it":"Niente calcoli ripetuti.","en":"No repeated work."}',NULL);
