INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'algorithms' AND slug = 'dp-greedy'),3,2,'{"it":"Un algoritmo greedy è sempre ottimo?","en":"Is a greedy algorithm always optimal?"}','[{"it":"No, dipende dal problema","en":"No, it depends on the problem"},{"it":"Sì, sempre","en":"Yes, always"},{"it":"Solo con i numeri pari","en":"Only with even numbers"},{"it":"Solo se ricorsivo","en":"Only if recursive"}]',0,'{"it":"Vedi l’esempio delle monete.","en":"See the coin example."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'algorithms' AND slug = 'bst'),1,3,'{"it":"In un BST, dove stanno i valori più piccoli di un nodo?","en":"In a BST, where are the values smaller than a node?"}','[{"it":"Nel sottoalbero di destra","en":"In the right subtree"},{"it":"Nel sottoalbero di sinistra","en":"In the left subtree"},{"it":"Sempre nella radice","en":"Always in the root"},{"it":"Sparsi nelle foglie a caso","en":"Scattered randomly in the leaves"}]',1,'{"it":"Sinistra minori, destra maggiori.","en":"Smaller left, larger right."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'algorithms' AND slug = 'bst'),2,3,'{"it":"Che cosa dà la visita in ordine di un BST?","en":"What does an in-order traversal of a BST yield?"}','[{"it":"I valori in ordine casuale","en":"The values in random order"},{"it":"Solo le foglie","en":"Only the leaves"},{"it":"I valori in ordine crescente","en":"The values in ascending order"},{"it":"Solo la radice e i suoi figli","en":"Only the root and its children"}]',2,'{"it":"Sinistra, nodo, destra.","en":"Left, node, right."}',NULL);
