INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'algorithms' AND slug = 'heaps'),1,3,'{"it":"Che cosa restituisce `heappop` da un min-heap?","en":"What does `heappop` return from a min-heap?"}','[{"it":"L’elemento più grande","en":"The largest element"},{"it":"L’ultimo elemento inserito","en":"The last element inserted"},{"it":"L’elemento più piccolo","en":"The smallest element"},{"it":"Un elemento a caso","en":"A random element"}]',2,'{"it":"Il minimo sta sempre in cima.","en":"The minimum is always on top."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'algorithms' AND slug = 'heaps'),2,3,'{"it":"Quanto costa inserire un elemento in un heap?","en":"What does inserting an element into a heap cost?"}','[{"it":"O(1)","en":"O(1)"},{"it":"O(log n)","en":"O(log n)"},{"it":"O(n)","en":"O(n)"},{"it":"O(n log n)","en":"O(n log n)"}]',1,'{"it":"Risale l’albero fino al suo posto.","en":"It climbs the tree to its place."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'algorithms' AND slug = 'heaps'),3,3,'{"it":"`heapq` è un min-heap. Come ottieni prima il massimo?","en":"`heapq` is a min-heap. How do you get the maximum first?"}','[{"it":"Con la funzione `heapq.reverse`","en":"With the `heapq.reverse` function"},{"it":"Ordinando la lista dopo ogni inserimento","en":"Sorting the list after every insertion"},{"it":"Non si può fare in Python","en":"It cannot be done in Python"},{"it":"Inserendo i numeri cambiati di segno","en":"Inserting the numbers with their sign flipped"}]',3,'{"it":"Il più grande diventa il più piccolo.","en":"The largest becomes the smallest."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'algorithms' AND slug = 'two-pointers'),1,3,'{"it":"Perché la ricerca della coppia con due puntatori vuole una lista ordinata?","en":"Why does the two-pointer pair search need a sorted list?"}','[{"it":"Perché Python non sa scorrere liste disordinate","en":"Because Python cannot loop over unsorted lists"},{"it":"Per poter usare la ricerca binaria dentro il ciclo","en":"To be able to use binary search inside the loop"},{"it":"Per sapere quale puntatore spostare in base alla somma","en":"To know which pointer to move based on the sum"},{"it":"Per avere meno elementi da controllare","en":"To have fewer elements to check"}]',2,'{"it":"Somma troppo piccola: avanza a sinistra; troppo grande: arretra a destra.","en":"Sum too small: move left forward; too large: move right back."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'algorithms' AND slug = 'two-pointers'),2,3,'{"it":"Quanto costa la finestra scorrevole su n elementi?","en":"What does the sliding window cost over n items?"}','[{"it":"O(n·k)","en":"O(n·k)"},{"it":"O(n²)","en":"O(n²)"},{"it":"O(log n)","en":"O(log n)"},{"it":"O(n)","en":"O(n)"}]',3,'{"it":"Ogni elemento entra ed esce una volta.","en":"Each item enters and leaves once."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'algorithms' AND slug = 'two-pointers'),3,3,'{"it":"Nella finestra scorrevole, che cosa fai a ogni passo?","en":"In the sliding window, what do you do at each step?"}','[{"it":"Ricalcoli la somma di tutta la finestra","en":"Recompute the sum of the whole window"},{"it":"Aggiungi l’elemento che entra e togli quello che esce","en":"Add the item coming in and remove the one going out"},{"it":"Riordini tutta la lista","en":"Re-sort the whole list"},{"it":"Raddoppi la larghezza della finestra","en":"Double the window’s width"}]',1,'{"it":"Da O(k) a O(1) per passo.","en":"From O(k) to O(1) per step."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'algorithms' AND slug = 'dijkstra'),1,3,'{"it":"Perché la BFS non basta su una mappa con i chilometri?","en":"Why is BFS not enough on a map with kilometres?"}','[{"it":"Perché il percorso con meno tappe non è sempre il più corto","en":"Because the path with fewest stops is not always the shortest"},{"it":"Perché la BFS funziona solo sugli alberi","en":"Because BFS only works on trees"},{"it":"Perché la BFS non usa una coda","en":"Because BFS does not use a queue"},{"it":"Perché le mappe hanno troppi nodi","en":"Because maps have too many nodes"}]',0,'{"it":"La BFS conta i passi, non i pesi.","en":"BFS counts steps, not weights."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'algorithms' AND slug = 'dijkstra'),2,3,'{"it":"Quale struttura usa Dijkstra per scegliere il nodo più vicino?","en":"Which structure does Dijkstra use to pick the nearest node?"}','[{"it":"Una pila","en":"A stack"},{"it":"Un set","en":"A set"},{"it":"Una coda con priorità (heap)","en":"A priority queue (heap)"},{"it":"Una lista riordinata a mano a ogni passo","en":"A list re-sorted by hand at every step"}]',2,'{"it":"Estrarre il minimo costa O(log n).","en":"Extracting the minimum costs O(log n)."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'algorithms' AND slug = 'dijkstra'),3,3,'{"it":"Quando Dijkstra dà risultati sbagliati?","en":"When does Dijkstra give wrong results?"}','[{"it":"Con grafi molto grandi","en":"With very large graphs"},{"it":"Con nodi chiamati con delle lettere","en":"With nodes named with letters"},{"it":"Con grafi senza cicli","en":"With graphs without cycles"},{"it":"Con archi di peso negativo","en":"With negative-weight edges"}]',3,'{"it":"Allora serve Bellman-Ford.","en":"Then you need Bellman-Ford."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'injection'),1,2,'{"it":"Che cos’è una SQL injection?","en":"What is SQL injection?"}','[{"it":"Dati dell’utente interpretati come codice SQL","en":"User data interpreted as SQL code"},{"it":"Un database lento per troppe richieste","en":"A database slowed by too many requests"},{"it":"Un backup","en":"A backup"},{"it":"Un errore di battitura","en":"A typo"}]',0,'{"it":"Può esporre tutto il database.","en":"It can expose the whole database."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'injection'),2,2,'{"it":"Qual è la difesa principale?","en":"What is the main defence?"}','[{"it":"Query preparate con parametri","en":"Prepared statements with parameters"},{"it":"Togliere gli spazi","en":"Removing spaces"},{"it":"Usare il maiuscolo","en":"Using capitals"},{"it":"Nascondere il form","en":"Hiding the form"}]',0,'{"it":"Il dato resta dato.","en":"Data stays data."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'injection'),3,2,'{"it":"Che cos’è l’OWASP Top 10?","en":"What is the OWASP Top 10?"}','[{"it":"L’elenco dei rischi più critici per le app web","en":"The list of the most critical web app risks"},{"it":"Una classifica dei linguaggi più sicuri","en":"A ranking of the safest languages"},{"it":"Un framework","en":"A framework"},{"it":"Un antivirus","en":"An antivirus"}]',0,'{"it":"Aggiornato periodicamente.","en":"Updated periodically."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'xss'),1,2,'{"it":"Che cosa fa un attacco XSS?","en":"What does an XSS attack do?"}','[{"it":"Esegue JavaScript dell’attaccante nel browser della vittima","en":"Runs the attacker’s JavaScript in the victim’s browser"},{"it":"Rallenta il server con richieste ripetute","en":"Slows the server with repeated requests"},{"it":"Cancella il disco","en":"Wipes the disk"},{"it":"Cambia la password del Wi-Fi","en":"Changes the Wi-Fi password"}]',0,'{"it":"Può rubare le sessioni.","en":"It can steal sessions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'xss'),2,2,'{"it":"Che cosa usare al posto di innerHTML per testo dell’utente?","en":"What to use instead of innerHTML for user text?"}','[{"it":"textContent","en":"textContent"},{"it":"outerHTML","en":"outerHTML"},{"it":"eval","en":"eval"},{"it":"document.write","en":"document.write"}]',0,'{"it":"Il testo resta testo.","en":"Text stays text."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'xss'),3,2,'{"it":"Che cosa fa una Content Security Policy?","en":"What does a Content Security Policy do?"}','[{"it":"Limita da dove possono arrivare gli script","en":"Limits where scripts can come from"},{"it":"Cifra il database","en":"Encrypts the database"},{"it":"Blocca le immagini sempre","en":"Always blocks images"},{"it":"Velocizza il sito","en":"Speeds up the site"}]',0,'{"it":"Una seconda difesa.","en":"A second defence."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'auth'),1,2,'{"it":"Come si salvano le password?","en":"How should passwords be stored?"}','[{"it":"Con un hash lento e con salt come bcrypt","en":"With a slow, salted hash like bcrypt"},{"it":"In chiaro","en":"In plain text"},{"it":"Con MD5, veloce e facile da verificare","en":"With MD5, fast and easy to verify"},{"it":"In un file di testo","en":"In a text file"}]',0,'{"it":"`password_hash` in PHP.","en":"`password_hash` in PHP."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'auth'),2,2,'{"it":"Che cosa fa il flag `httponly` di un cookie?","en":"What does a cookie’s `httponly` flag do?"}','[{"it":"Impedisce a JavaScript di leggerlo","en":"Prevents JavaScript from reading it"},{"it":"Lo rende pubblico","en":"Makes it public"},{"it":"Lo cancella subito","en":"Deletes it at once"},{"it":"Lo cifra con la password","en":"Encrypts it with the password"}]',0,'{"it":"Così uno script iniettato con l’XSS non può rubare la sessione.","en":"That way a script injected through XSS cannot steal the session."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'auth'),3,2,'{"it":"Nascondere un pulsante basta a proteggere una funzione?","en":"Is hiding a button enough to protect a feature?"}','[{"it":"No, serve il controllo sul server","en":"No, a server-side check is needed"},{"it":"Sì","en":"Yes"},{"it":"Solo su mobile","en":"Only on mobile"},{"it":"Sì, se lo nascondi anche con il CSS","en":"Yes, if you also hide it with CSS"}]',0,'{"it":"Le richieste si possono fare a mano.","en":"Requests can be crafted by hand."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'csrf'),1,2,'{"it":"Che cosa sfrutta un attacco CSRF?","en":"What does a CSRF attack exploit?"}','[{"it":"La sessione già aperta della vittima","en":"The victim’s already open session"},{"it":"Una password debole scelta dalla vittima","en":"A weak password chosen by the victim"},{"it":"Un server lento","en":"A slow server"},{"it":"Il Wi-Fi pubblico","en":"Public Wi-Fi"}]',0,'{"it":"Il browser invia i cookie da solo.","en":"The browser sends cookies by itself."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'csrf'),2,2,'{"it":"Che cosa fa l’intestazione HSTS?","en":"What does the HSTS header do?"}','[{"it":"Obbliga il browser a usare HTTPS","en":"Forces the browser to use HTTPS"},{"it":"Blocca i cookie","en":"Blocks cookies"},{"it":"Cifra il database","en":"Encrypts the database"},{"it":"Nasconde il sito","en":"Hides the site"}]',0,'{"it":"Strict-Transport-Security.","en":"Strict-Transport-Security."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'csrf'),3,2,'{"it":"Quale difesa contro il CSRF?","en":"Which defence against CSRF?"}','[{"it":"Token CSRF nei moduli e cookie SameSite","en":"CSRF tokens in forms and SameSite cookies"},{"it":"Password più lunghe e cambiate spesso","en":"Longer passwords changed often"},{"it":"Più RAM","en":"More RAM"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Il server verifica il token.","en":"The server checks the token."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'ssrf-supply'),1,2,'{"it":"Che cos’è la SSRF?","en":"What is SSRF?"}','[{"it":"Far scaricare al server un indirizzo scelto dall’attaccante","en":"Making the server fetch an attacker-chosen address"},{"it":"Un attacco al browser","en":"An attack on the browser"},{"it":"Un tipo di password","en":"A kind of password"},{"it":"Un errore CSS","en":"A CSS error"}]',0,'{"it":"Spesso verso indirizzi interni.","en":"Often towards internal addresses."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'ssrf-supply'),2,2,'{"it":"Dove salvi i file caricati?","en":"Where do you store uploaded files?"}','[{"it":"Fuori dalla cartella pubblica, senza esecuzione","en":"Outside the public folder, never executed"},{"it":"Nella cartella del codice","en":"In the code folder"},{"it":"Con il nome originale ovunque","en":"With the original name anywhere"},{"it":"Nel database come codice","en":"In the database as code"}]',0,'{"it":"Un file .php caricato non deve girare.","en":"An uploaded .php file must not run."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'ssrf-supply'),3,2,'{"it":"A che cosa serve `npm audit`?","en":"What is `npm audit` for?"}','[{"it":"Trovare dipendenze con falle note","en":"Finding dependencies with known flaws"},{"it":"Pubblicare un pacchetto","en":"Publishing a package"},{"it":"Avviare il server","en":"Starting the server"},{"it":"Comprimere il codice","en":"Minifying code"}]',0,'{"it":"Le falle note hanno una correzione.","en":"Known flaws have a fix."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'top10-2025'),1,3,'{"it":"Che cosa c’è al primo posto della OWASP Top 10 2025?","en":"What is in first place in the OWASP Top 10 2025?"}','[{"it":"Injection","en":"Injection"},{"it":"Broken Access Control","en":"Broken Access Control"},{"it":"Security Misconfiguration","en":"Security Misconfiguration"},{"it":"Cryptographic Failures","en":"Cryptographic Failures"}]',1,'{"it":"Per la quarta edizione di fila.","en":"For the fourth edition in a row."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'top10-2025'),2,3,'{"it":"Che cosa vuol dire “fallire chiusi”?","en":"What does “fail closed” mean?"}','[{"it":"Spegnere il server durante la notte","en":"Switching the server off at night"},{"it":"Chiudere la connessione dopo ogni richiesta","en":"Closing the connection after every request"},{"it":"Se qualcosa va storto si nega l’accesso invece di concederlo","en":"If something goes wrong access is denied instead of granted"},{"it":"Nascondere tutti i messaggi di errore","en":"Hiding every error message"}]',2,'{"it":"Un errore non deve aprire porte.","en":"An error must not open doors."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'top10-2025'),3,3,'{"it":"Dove è finita la SSRF nell’edizione 2025?","en":"Where did SSRF end up in the 2025 edition?"}','[{"it":"È stata tolta perché non esiste più","en":"It was dropped because it no longer exists"},{"it":"Dentro Injection","en":"Inside Injection"},{"it":"Dentro Cryptographic Failures","en":"Inside Cryptographic Failures"},{"it":"Dentro Broken Access Control","en":"Inside Broken Access Control"}]',3,'{"it":"Era la A10 del 2021.","en":"It was A10 in 2021."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'modern-auth'),1,3,'{"it":"Secondo il NIST (2025), che cosa un sito NON deve imporre?","en":"According to NIST (2025), what must a site NOT impose?"}','[{"it":"Una lunghezza minima","en":"A minimum length"},{"it":"Il confronto con le password già violate","en":"The check against breached passwords"},{"it":"Il cambio periodico obbligatorio della password","en":"A mandatory periodic password change"},{"it":"Il permesso di usare gestori di password","en":"Permission to use password managers"}]',2,'{"it":"Si cambia solo se c’è un sospetto di furto.","en":"You change it only if theft is suspected."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'modern-auth'),2,3,'{"it":"Perché le passkey resistono al phishing?","en":"Why do passkeys resist phishing?"}','[{"it":"Perché sono più lunghe delle password","en":"Because they are longer than passwords"},{"it":"Perché sono legate al dominio: su un sito falso non funzionano","en":"Because they are bound to the domain: they do not work on a fake site"},{"it":"Perché cambiano ogni giorno da sole","en":"Because they change by themselves every day"},{"it":"Perché arrivano via SMS","en":"Because they arrive by SMS"}]',1,'{"it":"Il browser le offre solo al dominio giusto.","en":"The browser offers them only to the right domain."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'modern-auth'),3,3,'{"it":"Che cosa conserva il server per una passkey?","en":"What does the server keep for a passkey?"}','[{"it":"La chiave privata dell’utente","en":"The user’s private key"},{"it":"L’impronta digitale dell’utente","en":"The user’s fingerprint"},{"it":"L’hash di una password","en":"A password hash"},{"it":"Solo la chiave pubblica","en":"Only the public key"}]',3,'{"it":"Un furto del database non rivela segreti.","en":"A database theft reveals no secrets."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'crypto-secrets'),1,3,'{"it":"Come generi un token per reimpostare la password?","en":"How do you generate a password-reset token?"}','[{"it":"Con `Math.random()` e la data di oggi","en":"With `Math.random()` and today’s date"},{"it":"Con un generatore crittografico come `crypto.randomBytes`","en":"With a cryptographic generator such as `crypto.randomBytes`"},{"it":"Con un hash MD5 dell’email","en":"With an MD5 hash of the email"},{"it":"Con un contatore che cresce di uno","en":"With a counter that grows by one"}]',1,'{"it":"Deve essere impossibile da indovinare.","en":"It must be impossible to guess."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'crypto-secrets'),2,3,'{"it":"Quale di queste è una configurazione sbagliata?","en":"Which of these is a security misconfiguration?"}','[{"it":"Usare query preparate","en":"Using prepared statements"},{"it":"Attivare HSTS","en":"Turning on HSTS"},{"it":"Cifrare i backup","en":"Encrypting backups"},{"it":"Lasciare attiva la modalità debug in produzione","en":"Leaving debug mode on in production"}]',3,'{"it":"Il debug mostra dettagli interni a chiunque.","en":"Debug shows internal details to anyone."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'crypto-secrets'),3,3,'{"it":"Dove va la password del database di produzione?","en":"Where does the production database password go?"}','[{"it":"In un gestore di segreti o in una variabile d’ambiente","en":"In a secrets manager or an environment variable"},{"it":"Nel codice, in una costante","en":"In the code, in a constant"},{"it":"In un commento del file di configurazione","en":"In a comment in the configuration file"},{"it":"Nel README del repository","en":"In the repository’s README"}]',0,'{"it":"Fuori dal codice e fuori da Git.","en":"Out of the code and out of Git."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'cors-clickjacking'),1,3,'{"it":"Che cosa fa il CORS?","en":"What does CORS do?"}','[{"it":"Permette ai browser di leggere risposte da origini scelte dal server","en":"Lets browsers read responses from origins chosen by the server"},{"it":"Blocca le richieste fatte con curl","en":"Blocks requests made with curl"},{"it":"Cifra le risposte del server","en":"Encrypts the server’s responses"},{"it":"Sostituisce l’autenticazione","en":"Replaces authentication"}]',0,'{"it":"È un permesso per i browser, non una barriera.","en":"It is a permission for browsers, not a barrier."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'cors-clickjacking'),2,3,'{"it":"Quale configurazione è pericolosa?","en":"Which configuration is dangerous?"}','[{"it":"Allow-Origin con un elenco preciso di origini","en":"Allow-Origin with an exact list of origins"},{"it":"Allow-Origin: * su dati pubblici senza credenziali","en":"Allow-Origin: * on public data without credentials"},{"it":"Rimandare qualsiasi Origin insieme ad Allow-Credentials: true","en":"Echoing any Origin together with Allow-Credentials: true"},{"it":"Aggiungere Vary: Origin alla risposta","en":"Adding Vary: Origin to the response"}]',2,'{"it":"Qualsiasi sito leggerebbe i dati dei tuoi utenti.","en":"Any site could read your users’ data."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'cors-clickjacking'),3,3,'{"it":"Quale intestazione blocca il clickjacking?","en":"Which header blocks clickjacking?"}','[{"it":"Strict-Transport-Security","en":"Strict-Transport-Security"},{"it":"Content-Security-Policy: frame-ancestors ''none''","en":"Content-Security-Policy: frame-ancestors ''none''"},{"it":"X-Content-Type-Options: nosniff","en":"X-Content-Type-Options: nosniff"},{"it":"Referrer-Policy: no-referrer","en":"Referrer-Policy: no-referrer"}]',1,'{"it":"Nessuno può mettere la pagina in un iframe.","en":"Nobody can put the page in an iframe."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'passwords'),1,1,'{"it":"Che cosa rende forte una password?","en":"What makes a password strong?"}','[{"it":"Essere lunga e unica","en":"Being long and unique"},{"it":"Contenere il tuo nome","en":"Containing your name"},{"it":"Essere corta e facile","en":"Being short and easy"},{"it":"Essere uguale ovunque","en":"Being the same everywhere"}]',0,'{"it":"Lunghezza e unicità.","en":"Length and uniqueness."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'passwords'),2,1,'{"it":"Perché non riutilizzare le password?","en":"Why not reuse passwords?"}','[{"it":"Un furto su un sito apre anche gli altri account","en":"One breach opens your other accounts too"},{"it":"Perché le password si consumano con l’uso","en":"Because passwords wear out with use"},{"it":"Non c’è motivo","en":"There is no reason"},{"it":"Perché sono a pagamento","en":"Because they cost money"}]',0,'{"it":"Effetto domino.","en":"Domino effect."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'passwords'),3,1,'{"it":"Che cosa fa un gestore di password?","en":"What does a password manager do?"}','[{"it":"Genera, conserva cifrate e compila le password","en":"Generates, stores encrypted and fills passwords"},{"it":"Pubblica le password","en":"Publishes passwords"},{"it":"Le stampa","en":"Prints them"},{"it":"Le cambia a caso ogni giorno su tutti i siti","en":"Changes them randomly every day on every site"}]',0,'{"it":"Una sola password da ricordare.","en":"One password to remember."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = '2fa'),1,1,'{"it":"Che vantaggio dà il 2FA?","en":"What does 2FA give you?"}','[{"it":"Una password rubata non basta per entrare","en":"A stolen password is not enough to get in"},{"it":"Non serve più la password","en":"The password is no longer needed"},{"it":"Internet più veloce","en":"Faster internet"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Serve una seconda prova.","en":"A second proof is needed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = '2fa'),2,1,'{"it":"Quale secondo fattore è il più debole?","en":"Which second factor is weakest?"}','[{"it":"SMS","en":"SMS"},{"it":"Chiave di sicurezza","en":"Security key"},{"it":"App di autenticazione","en":"Authenticator app"},{"it":"Passkey","en":"Passkey"}]',0,'{"it":"Attaccabile con lo scambio di SIM.","en":"Vulnerable to SIM swapping."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = '2fa'),3,1,'{"it":"Qualcuno al telefono ti chiede il codice di verifica appena ricevuto. Che fai?","en":"Someone on the phone asks for the verification code you just got. What do you do?"}','[{"it":"Non lo do e riattacco","en":"Do not give it and hang up"},{"it":"Glielo leggo","en":"Read it out"},{"it":"Glielo mando per SMS","en":"Text it to them"},{"it":"Lo pubblico","en":"Post it"}]',0,'{"it":"È sempre una truffa.","en":"It is always a scam."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'phishing'),1,1,'{"it":"Qual è un segnale tipico di phishing?","en":"What is a typical phishing sign?"}','[{"it":"Urgenza e richiesta di dati","en":"Urgency and a request for data"},{"it":"Un messaggio di un amico che conosci, senza richieste","en":"A message from a friend with no requests"},{"it":"Una newsletter a cui sei iscritto","en":"A newsletter you subscribed to"},{"it":"Una fattura attesa dal portale ufficiale","en":"An expected invoice from the official portal"}]',0,'{"it":"Fretta = attenzione.","en":"Hurry = caution."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'phishing'),2,1,'{"it":"Ricevi un SMS dalla “banca” con un link. Che fai?","en":"You get an SMS from the “bank” with a link. What do you do?"}','[{"it":"Apro io l’app ufficiale senza usare il link","en":"Open the official app myself without the link"},{"it":"Clicco subito","en":"Click at once"},{"it":"Rispondo chiedendo se il messaggio è vero","en":"Reply asking whether the message is genuine"},{"it":"Inoltro a tutti","en":"Forward to everyone"}]',0,'{"it":"Mai i link del messaggio.","en":"Never the message’s links."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'phishing'),3,1,'{"it":"Che cosa fare se hai inserito la password su un sito falso?","en":"What to do if you entered your password on a fake site?"}','[{"it":"Cambiarla subito e attivare il 2FA","en":"Change it at once and enable 2FA"},{"it":"Niente","en":"Nothing"},{"it":"Aspettare un mese","en":"Wait a month"},{"it":"Cancellare il browser","en":"Delete the browser"}]',0,'{"it":"Prima si agisce, meglio è.","en":"The sooner the better."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'devices'),1,1,'{"it":"Perché installare gli aggiornamenti?","en":"Why install updates?"}','[{"it":"Chiudono falle di sicurezza note","en":"They close known security holes"},{"it":"Per cambiare i colori","en":"To change colours"},{"it":"Rallentano il dispositivo","en":"They slow the device"},{"it":"Non servono","en":"They are not needed"}]',0,'{"it":"Meglio automatici.","en":"Better automatic."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'devices'),2,1,'{"it":"Che cosa dice la regola 3-2-1 dei backup?","en":"What does the 3-2-1 backup rule say?"}','[{"it":"Tre copie, due supporti, una fuori casa","en":"Three copies, two media, one off-site"},{"it":"Tre password, due email, un telefono","en":"Three passwords, two emails, one phone"},{"it":"Un backup ogni tre anni","en":"One backup every three years"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Contro guasti e ransomware.","en":"Against failures and ransomware."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'devices'),3,1,'{"it":"Che cos’è il ransomware?","en":"What is ransomware?"}','[{"it":"Malware che cifra i file e chiede un riscatto","en":"Malware that encrypts files and demands ransom"},{"it":"Un antivirus che blocca i file sospetti","en":"An antivirus that blocks suspicious files"},{"it":"Un tipo di backup","en":"A kind of backup"},{"it":"Una rete Wi-Fi","en":"A Wi-Fi network"}]',0,'{"it":"Il backup è la difesa migliore.","en":"Backup is the best defence."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'networks'),1,2,'{"it":"Che cosa aiuta su una Wi-Fi pubblica?","en":"What helps on public Wi-Fi?"}','[{"it":"HTTPS e una VPN affidabile","en":"HTTPS and a trustworthy VPN"},{"it":"Condividere i file","en":"Sharing files"},{"it":"Disattivare gli aggiornamenti","en":"Turning off updates"},{"it":"Usare la stessa password","en":"Using the same password"}]',0,'{"it":"Il traffico resta cifrato.","en":"Traffic stays encrypted."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'networks'),2,2,'{"it":"Primo passo dopo un account violato?","en":"First step after a hacked account?"}','[{"it":"Cambiare la password da un dispositivo sicuro","en":"Change the password from a safe device"},{"it":"Aspettare","en":"Wait"},{"it":"Cancellare il computer","en":"Wipe the computer"},{"it":"Rispondere all’attaccante","en":"Reply to the attacker"}]',0,'{"it":"Poi 2FA e sessioni.","en":"Then 2FA and sessions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'networks'),3,2,'{"it":"Quale protezione Wi-Fi usare a casa?","en":"Which Wi-Fi protection should you use at home?"}','[{"it":"WPA2 o WPA3","en":"WPA2 o WPA3"},{"it":"WEP","en":"WEP"},{"it":"Nessuna","en":"None"},{"it":"Bluetooth","en":"Bluetooth"}]',0,'{"it":"WEP è superata.","en":"WEP is obsolete."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'apps'),1,2,'{"it":"Da dove conviene scaricare le app?","en":"Where should you download apps from?"}','[{"it":"Da un link ricevuto in chat","en":"From a link received in a chat"},{"it":"Dagli store ufficiali o dal sito dello sviluppatore","en":"From official stores or the developer’s website"},{"it":"Da siti che offrono versioni “craccate” gratis","en":"From sites offering free “cracked” versions"},{"it":"Da un allegato email inatteso","en":"From an unexpected email attachment"}]',1,'{"it":"Le fonti ufficiali controllano ciò che pubblicano.","en":"Official sources check what they publish."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'apps'),2,2,'{"it":"Un’app torcia chiede l’accesso ai contatti e al microfono. Che cosa fai?","en":"A torch app asks for access to your contacts and microphone. What do you do?"}','[{"it":"Accetto, altrimenti non funziona","en":"Accept, otherwise it will not work"},{"it":"Accetto solo il microfono","en":"Accept only the microphone"},{"it":"Nego i permessi o non la installo","en":"Deny the permissions or do not install it"},{"it":"La installo su un altro telefono","en":"Install it on another phone"}]',2,'{"it":"Permessi senza senso sono un campanello d’allarme.","en":"Pointless permissions are a warning sign."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'apps'),3,2,'{"it":"Perché installare poche estensioni del browser?","en":"Why install few browser extensions?"}','[{"it":"Perché rallentano solo la connessione","en":"Because they only slow the connection"},{"it":"Perché occupano molto spazio sul disco","en":"Because they take a lot of disk space"},{"it":"Perché cambiano il colore delle pagine","en":"Because they change the colour of pages"},{"it":"Perché possono leggere tutto quello che visiti","en":"Because they can read everything you visit"}]',3,'{"it":"Un’estensione venduta a un malintenzionato diventa una spia.","en":"An extension sold to a crook becomes a spy."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'privacy'),1,2,'{"it":"Perché non pubblicare la foto di una carta d’imbarco?","en":"Why not post a photo of a boarding pass?"}','[{"it":"Perché le foto dei biglietti sono vietate","en":"Because photos of tickets are forbidden"},{"it":"Perché consuma troppi dati","en":"Because it uses too much data"},{"it":"Perché il codice contiene i dati per gestire la prenotazione","en":"Because the code holds the data to manage the booking"},{"it":"Non c’è nessun motivo","en":"There is no reason at all"}]',2,'{"it":"Con quei dati si può cambiare o cancellare il volo.","en":"With that data the flight can be changed or cancelled."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'privacy'),2,2,'{"it":"Davanti a un banner dei cookie, qual è la scelta che protegge di più la privacy?","en":"Faced with a cookie banner, which choice protects your privacy most?"}','[{"it":"Accetta tutto","en":"Accept all"},{"it":"Rifiuta i cookie non essenziali","en":"Refuse non-essential cookies"},{"it":"Accetta e poi cancella la cronologia","en":"Accept and then clear the history"},{"it":"Ignora il banner e continua","en":"Ignore the banner and carry on"}]',1,'{"it":"I cookie tecnici restano, i tracker no.","en":"Technical cookies stay, trackers do not."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'privacy'),3,2,'{"it":"Quale diritto ti dà il GDPR?","en":"Which right does the GDPR give you?"}','[{"it":"Vedere i dati degli altri utenti","en":"Seeing other users’ data"},{"it":"Avere tutti i servizi gratis","en":"Getting every service for free"},{"it":"Obbligare un sito a non usare cookie tecnici","en":"Forcing a site not to use technical cookies"},{"it":"Sapere quali dati ha un’azienda su di te e chiederne la cancellazione","en":"Knowing which data a company holds about you and requesting its deletion"}]',3,'{"it":"Accesso e cancellazione sono diritti tuoi.","en":"Access and deletion are your rights."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'shopping'),1,2,'{"it":"Il lucchetto (HTTPS) basta per fidarsi di un negozio?","en":"Is the padlock (HTTPS) enough to trust a shop?"}','[{"it":"Sì, garantisce che il negozio è onesto","en":"Yes, it guarantees the shop is honest"},{"it":"No: indica solo una connessione cifrata, anche i siti truffa ce l’hanno","en":"No: it only means an encrypted connection, scam sites have it too"},{"it":"Sì, se il prezzo è molto basso","en":"Yes, if the price is very low"},{"it":"Solo se il sito è in inglese","en":"Only if the site is in English"}]',1,'{"it":"Cifrato non vuol dire onesto.","en":"Encrypted does not mean honest."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'shopping'),2,2,'{"it":"Qual è il modo più sicuro per pagare un venditore online che non conosci?","en":"What is the safest way to pay an online seller you do not know?"}','[{"it":"Un bonifico istantaneo","en":"An instant bank transfer"},{"it":"Delle carte regalo","en":"Gift cards"},{"it":"Delle criptovalute","en":"Cryptocurrency"},{"it":"Carta di credito o un metodo con tutela per l’acquirente","en":"Credit card or a method with buyer protection"}]',3,'{"it":"Un addebito su carta si può contestare.","en":"A card charge can be disputed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'security-basics' AND slug = 'shopping'),3,2,'{"it":"Un “operatore della banca” ti chiede di spostare i soldi su un conto sicuro. Che cosa fai?","en":"A “bank operator” asks you to move your money to a safe account. What do you do?"}','[{"it":"Riattacco e chiamo io il numero ufficiale della banca","en":"Hang up and call the bank’s official number myself"},{"it":"Sposto subito i soldi","en":"Move the money at once"},{"it":"Gli detto il codice per confermare","en":"Read out the code to confirm"},{"it":"Gli chiedo di richiamarmi più tardi","en":"Ask him to call me back later"}]',0,'{"it":"Nessuna banca chiede di spostare soldi per proteggerli.","en":"No bank asks you to move money to protect it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'why'),1,1,'{"it":"Che cos’è uno screen reader?","en":"What is a screen reader?"}','[{"it":"Un software che legge ad alta voce la pagina","en":"Software reading the page aloud"},{"it":"Un monitor speciale","en":"A special monitor"},{"it":"Un’estensione per i colori","en":"A colour extension"},{"it":"Un browser per bambini","en":"A browser for children"}]',0,'{"it":"Usato da chi non vede.","en":"Used by blind people."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'why'),2,1,'{"it":"Quali sono i quattro principi WCAG?","en":"What are the four WCAG principles?"}','[{"it":"Percepibile, utilizzabile, comprensibile, robusto","en":"Perceivable, operable, understandable, robust"},{"it":"Veloce, bello, economico, nuovo","en":"Fast, pretty, cheap, new"},{"it":"Rosso, verde, blu, nero","en":"Red, green, blue, black"},{"it":"Nessuno","en":"None"}]',0,'{"it":"POUR in inglese.","en":"POUR in English."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'why'),3,1,'{"it":"Quale legge europea rende obbligatoria l’accessibilità per molti servizi digitali?","en":"Which European law makes accessibility mandatory for many digital services?"}','[{"it":"European Accessibility Act","en":"European Accessibility Act"},{"it":"GDPR","en":"GDPR"},{"it":"AI Act","en":"AI Act"},{"it":"Digital Markets Act","en":"Digital Markets Act"}]',0,'{"it":"Applicata dal giugno 2025.","en":"Applied since June 2025."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'semantic'),1,1,'{"it":"Perché usare `<button>` invece di un `<div>` cliccabile?","en":"Why use `<button>` instead of a clickable `<div>`?"}','[{"it":"È accessibile da tastiera e annunciato come pulsante","en":"It is keyboard-accessible and announced as a button"},{"it":"È più colorato","en":"It is more colourful"},{"it":"Non c’è differenza","en":"There is no difference"},{"it":"Il div è più veloce da disegnare per il browser","en":"The div is faster for the browser to draw"}]',0,'{"it":"Semantica gratis.","en":"Free semantics."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'semantic'),2,1,'{"it":"Che alt dare a un’immagine solo decorativa?","en":"What alt should a purely decorative image get?"}','[{"it":"alt vuoto: alt=\\"\\"","en":"Empty alt: alt=\\"\\""},{"it":"alt=\\"immagine\\"","en":"alt=\\"image\\""},{"it":"Nessun attributo","en":"No attribute"},{"it":"Il nome del file","en":"The file name"}]',0,'{"it":"Lo screen reader la salta.","en":"The screen reader skips it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'semantic'),3,1,'{"it":"Qual è un buon testo per un link?","en":"What is good link text?"}','[{"it":"Scarica il listino prezzi 2026 (PDF)","en":"Download the 2026 price list (PDF)"},{"it":"Clicca qui per il documento","en":"Click here for the document"},{"it":"Link","en":"Link"},{"it":"Qui","en":"Here"}]',0,'{"it":"Chiaro anche fuori contesto.","en":"Clear even out of context."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'keyboard'),1,1,'{"it":"Quale tasto sposta il focus all’elemento successivo?","en":"Which key moves focus to the next element?"}','[{"it":"Tab","en":"Tab"},{"it":"Esc","en":"Esc"},{"it":"F5","en":"F5"},{"it":"Ctrl","en":"Ctrl"}]',0,'{"it":"Maiusc+Tab torna indietro.","en":"Shift+Tab goes back."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'keyboard'),2,1,'{"it":"Qual è il contrasto minimo AA per il testo normale?","en":"What is the minimum AA contrast for normal text?"}','[{"it":"4,5:1","en":"4,5:1"},{"it":"1:1","en":"1:1"},{"it":"2:1","en":"2:1"},{"it":"10:1","en":"10:1"}]',0,'{"it":"3:1 per il testo grande.","en":"3:1 for large text."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'keyboard'),3,1,'{"it":"Perché non usare solo il colore per segnalare un errore?","en":"Why not use colour alone to signal an error?"}','[{"it":"Chi non distingue i colori non lo vede","en":"People with colour blindness miss it"},{"it":"Il rosso è vietato dalle linee guida","en":"Red is forbidden by the guidelines"},{"it":"Costa di più","en":"It costs more"},{"it":"Non c’è motivo","en":"There is no reason"}]',0,'{"it":"Aggiungi testo o icona.","en":"Add text or an icon."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'forms'),1,1,'{"it":"Perché il placeholder non basta come etichetta?","en":"Why is a placeholder not enough as a label?"}','[{"it":"Sparisce mentre scrivi e non sempre viene letto","en":"It vanishes while typing and is not always read"},{"it":"È troppo lungo per i campi piccoli","en":"It is too long for small fields"},{"it":"È vietato","en":"It is forbidden"},{"it":"Basta sempre","en":"It is always enough"}]',0,'{"it":"Serve un label collegato.","en":"A linked label is needed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'forms'),2,1,'{"it":"Qual è la prima regola di ARIA?","en":"What is the first rule of ARIA?"}','[{"it":"Usa un elemento HTML adatto se esiste","en":"Use a suitable HTML element if one exists"},{"it":"Metti ARIA ovunque","en":"Put ARIA everywhere"},{"it":"Non usare mai HTML","en":"Never use HTML"},{"it":"ARIA sostituisce il CSS","en":"ARIA replaces CSS"}]',0,'{"it":"HTML prima di ARIA.","en":"HTML before ARIA."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'forms'),3,1,'{"it":"Gli strumenti automatici trovano tutti i problemi di accessibilità?","en":"Do automated tools find every accessibility problem?"}','[{"it":"No, solo una parte","en":"No, only some"},{"it":"Sì, tutti","en":"Yes, all"},{"it":"Solo quelli di colore","en":"Only colour ones"},{"it":"Nessuno","en":"None"}]',0,'{"it":"Servono anche prove manuali.","en":"Manual tests are needed too."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'aria'),1,1,'{"it":"Qual è la prima regola di ARIA?","en":"What is the first rule of ARIA?"}','[{"it":"Preferire l’HTML nativo","en":"Prefer native HTML"},{"it":"Usare ARIA ovunque","en":"Use ARIA everywhere"},{"it":"Mettere role su ogni div","en":"Put role on every div"},{"it":"Nascondere tutto ai lettori","en":"Hide everything from readers"}]',0,'{"it":"Un `<button>` vero fa già tutto.","en":"A real `<button>` already does it all."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'aria'),2,1,'{"it":"Che cosa annuncia `aria-live=\\"polite\\"`?","en":"What does `aria-live=\\"polite\\"` announce?"}','[{"it":"Gli aggiornamenti della zona, senza interrompere","en":"Updates to the region, without interrupting"},{"it":"Solo gli errori","en":"Only errors"},{"it":"Niente","en":"Nothing"},{"it":"I titoli","en":"Headings"}]',0,'{"it":"Utile per i risultati di ricerca.","en":"Useful for search results."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'aria'),3,1,'{"it":"Come dai un nome a un pulsante con sola icona?","en":"How do you name an icon-only button?"}','[{"it":"aria-label","en":"aria-label"},{"it":"title soltanto","en":"title soltanto"},{"it":"alt sul button","en":"alt sul button"},{"it":"role=\\"name\\"","en":"role=\\"name\\""}]',0,'{"it":"E l’icona con `aria-hidden`.","en":"And the icon with `aria-hidden`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'structure'),1,2,'{"it":"A che cosa serve `lang=\\"it\\"` su `<html>`?","en":"What is `lang=\\"it\\"` on `<html>` for?"}','[{"it":"A tradurre la pagina in automatico","en":"To translate the page automatically"},{"it":"A scegliere il carattere tipografico","en":"To choose the typeface"},{"it":"A far leggere il testo con la pronuncia giusta","en":"To have the text read with the right pronunciation"},{"it":"A migliorare la velocità","en":"To improve speed"}]',2,'{"it":"Senza, uno screen reader inglese leggerebbe l’italiano con l’accento sbagliato.","en":"Without it, an English screen reader would read Italian with the wrong accent."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'structure'),2,2,'{"it":"Perché serve un link «Vai al contenuto»?","en":"Why is a “Skip to content” link needed?"}','[{"it":"Per saltare il menu con la tastiera","en":"To skip the menu with the keyboard"},{"it":"Per migliorare la grafica","en":"To improve the design"},{"it":"Per tornare alla home","en":"To go back home"},{"it":"Per stampare la pagina","en":"To print the page"}]',0,'{"it":"Va messo per primo nella pagina.","en":"It goes first on the page."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'structure'),3,2,'{"it":"Quale `<title>` è più utile?","en":"Which `<title>` is most useful?"}','[{"it":"Pagina","en":"Pagina"},{"it":"Home","en":"Home"},{"it":"Fucina","en":"Fucina"},{"it":"Carrello (3 articoli) · Fucina","en":"Cart (3 items) · Fucina"}]',3,'{"it":"Prima ciò che è specifico, poi il nome del sito.","en":"First what is specific, then the site name."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'wcag22'),1,2,'{"it":"Qual è la dimensione minima AA di un bersaglio nelle WCAG 2.2?","en":"What is the minimum AA target size in WCAG 2.2?"}','[{"it":"10×10px","en":"10×10px"},{"it":"16×16px","en":"16×16px"},{"it":"24×24px","en":"24×24px"},{"it":"100×100px","en":"100×100px"}]',2,'{"it":"Oppure abbastanza spazio libero intorno al bersaglio.","en":"Or enough free space around the target."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'wcag22'),2,2,'{"it":"Che cosa chiede il criterio sui movimenti di trascinamento?","en":"What does the dragging movements criterion ask for?"}','[{"it":"Di vietare il trascinamento","en":"To ban dragging"},{"it":"Un’alternativa con un semplice tocco o clic","en":"An alternative with a simple tap or click"},{"it":"Di trascinare solo in orizzontale","en":"To drag only horizontally"},{"it":"Di usare sempre il mouse","en":"To always use a mouse"}]',1,'{"it":"Non tutti riescono a tenere premuto e muovere insieme.","en":"Not everyone can press and move at the same time."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'wcag22'),3,2,'{"it":"Che cosa vieta l’autenticazione accessibile?","en":"What does accessible authentication forbid?"}','[{"it":"Le password lunghe","en":"Long passwords"},{"it":"Il login con l’email","en":"Logging in with email"},{"it":"I gestori di password","en":"Password managers"},{"it":"Prove di memoria o enigmi senza alternative","en":"Memory tests or puzzles without alternatives"}]',3,'{"it":"Incollare la password o usare un gestore deve essere possibile.","en":"Pasting the password or using a manager must be possible."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'focus-management'),1,2,'{"it":"Dove deve tornare il focus quando una modale si chiude?","en":"Where should focus go when a modal closes?"}','[{"it":"In cima alla pagina","en":"To the top of the page"},{"it":"Sul pulsante che l’ha aperta","en":"To the button that opened it"},{"it":"Sull’ultimo link della pagina","en":"To the last link on the page"},{"it":"Da nessuna parte","en":"Nowhere"}]',1,'{"it":"Così chi usa la tastiera riprende da dove era.","en":"So keyboard users carry on from where they were."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'focus-management'),2,2,'{"it":"Che cosa fa l’attributo `inert`?","en":"What does the `inert` attribute do?"}','[{"it":"Rende l’elemento più veloce","en":"It makes the element faster"},{"it":"Lo rende trasparente","en":"It makes it transparent"},{"it":"Rende il contenuto non raggiungibile né cliccabile","en":"It makes the content unreachable and unclickable"},{"it":"Blocca l’animazione","en":"It stops the animation"}]',2,'{"it":"Anche gli screen reader lo ignorano.","en":"Screen readers ignore it too."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'focus-management'),3,2,'{"it":"Quale tasto dovrebbe chiudere una modale o un menu aperto?","en":"Which key should close an open modal or menu?"}','[{"it":"Tab","en":"Tab"},{"it":"Invio","en":"Invio"},{"it":"Spazio","en":"Spazio"},{"it":"Esc","en":"Esc"}]',3,'{"it":"Il `<dialog>` modale lo gestisce da solo.","en":"The modal `<dialog>` handles it by itself."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'media-motion'),1,2,'{"it":"Di che cosa ha bisogno un podcast per essere accessibile?","en":"What does a podcast need to be accessible?"}','[{"it":"Di una trascrizione","en":"A transcript"},{"it":"Di un volume più alto","en":"A louder volume"},{"it":"Di una copertina colorata","en":"A colourful cover"},{"it":"Di un player più grande","en":"A bigger player"}]',0,'{"it":"Chi non sente può leggere ciò che si dice.","en":"People who cannot hear can read what is said."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'media-motion'),2,2,'{"it":"Quante volte al secondo può lampeggiare al massimo un contenuto?","en":"At most how many times a second may content flash?"}','[{"it":"Dieci","en":"Ten"},{"it":"Senza limiti, se è breve","en":"No limit, if it is short"},{"it":"Una sola volta al minuto","en":"Only once a minute"},{"it":"Tre","en":"Three"}]',3,'{"it":"Oltre, il rischio di crisi epilettiche cresce.","en":"Beyond that, the risk of seizures grows."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'media-motion'),3,2,'{"it":"Che cosa serve a un carosello che scorre da solo?","en":"What does a self-scrolling carousel need?"}','[{"it":"Più immagini","en":"More images"},{"it":"Un comando per metterlo in pausa","en":"A control to pause it"},{"it":"Una velocità più alta","en":"A higher speed"},{"it":"Un audio di sottofondo","en":"Background audio"}]',1,'{"it":"Vale per tutto ciò che si muove da solo per più di cinque secondi.","en":"This applies to anything moving by itself for more than five seconds."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'crawling'),1,1,'{"it":"Qual è l’ordine delle fasi di un motore di ricerca?","en":"What is the order of a search engine’s phases?"}','[{"it":"Scansione, indicizzazione, ranking","en":"Crawling, indexing, ranking"},{"it":"Ranking, scansione, indicizzazione","en":"Ranking, crawling, indexing"},{"it":"Indicizzazione, ranking, scansione","en":"Indexing, ranking, crawling"},{"it":"Scansione, ranking, indicizzazione","en":"Crawling, ranking, indexing"}]',0,'{"it":"Prima si scopre, poi si archivia, poi si ordina.","en":"First discover, then store, then sort."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'crawling'),2,1,'{"it":"Come scopre nuove pagine un crawler?","en":"How does a crawler discover new pages?"}','[{"it":"Seguendo i link delle pagine già visitate","en":"By following links in pages it already visited"},{"it":"Leggendo la mente dei webmaster","en":"By reading webmasters’ minds"},{"it":"Provando indirizzi a caso","en":"By trying random addresses"},{"it":"Solo dai pagamenti dei siti","en":"Only from sites’ payments"}]',0,'{"it":"Il web è un grafo di link.","en":"The web is a graph of links."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'crawling'),3,1,'{"it":"Che cos’è una pagina orfana?","en":"What is an orphan page?"}','[{"it":"Una pagina senza link in entrata","en":"A page with no inbound links"},{"it":"Una pagina senza immagini","en":"A page with no images"},{"it":"Una pagina con troppi link","en":"A page with too many links"},{"it":"Una pagina in un’altra lingua","en":"A page in another language"}]',0,'{"it":"Nessuno la indica, il crawler non la trova.","en":"Nobody points to it, the crawler cannot find it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'robots'),1,1,'{"it":"A che cosa serve `Disallow` in robots.txt?","en":"What is `Disallow` for in robots.txt?"}','[{"it":"Chiede di non scansionare un percorso","en":"Asks not to crawl a path"},{"it":"Protegge il percorso con una password","en":"Protects the path with a password"},{"it":"Cancella la pagina dal server","en":"Deletes the page from the server"},{"it":"Velocizza la pagina","en":"Speeds up the page"}]',0,'{"it":"È un’indicazione per i bot.","en":"It is a hint for bots."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'robots'),2,1,'{"it":"Come si tiene una pagina fuori dall’indice?","en":"How do you keep a page out of the index?"}','[{"it":"Con il meta tag robots `noindex`","en":"With the robots meta tag `noindex`"},{"it":"Con un titolo vuoto","en":"With an empty title"},{"it":"Con una sitemap più lunga","en":"With a longer sitemap"},{"it":"Con più parole chiave","en":"With more keywords"}]',0,'{"it":"noindex agisce sull’indice.","en":"noindex acts on the index."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'robots'),3,1,'{"it":"Che cosa contiene una sitemap XML?","en":"What does an XML sitemap contain?"}','[{"it":"Gli URL da far conoscere e le loro date","en":"URLs to make known and their dates"},{"it":"Le password del sito","en":"The site’s passwords"},{"it":"Il CSS delle pagine","en":"The pages’ CSS"},{"it":"Gli indirizzi email dei visitatori","en":"Visitors’ email addresses"}]',0,'{"it":"Una mappa per i crawler.","en":"A map for crawlers."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'indexing'),1,1,'{"it":"Che cos’è un indice invertito?","en":"What is an inverted index?"}','[{"it":"Per ogni parola, le pagine che la contengono","en":"For each word, the pages that contain it"},{"it":"Le pagine in ordine alfabetico inverso","en":"Pages in reverse alphabetical order"},{"it":"Una pagina scritta al contrario","en":"A page written backwards"},{"it":"L’elenco dei siti bannati","en":"The list of banned sites"}]',0,'{"it":"Come l’indice di un libro.","en":"Like a book’s index."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'indexing'),2,1,'{"it":"Perché tenere i contenuti importanti nell’HTML?","en":"Why keep important content in the HTML?"}','[{"it":"Il rendering del JavaScript è più lento e limitato","en":"JavaScript rendering is slower and limited"},{"it":"Il JavaScript è vietato dai motori","en":"JavaScript is banned by engines"},{"it":"L’HTML pesa sempre meno","en":"HTML always weighs less"},{"it":"Per non usare il CSS","en":"To avoid using CSS"}]',0,'{"it":"Il rendering arriva dopo.","en":"Rendering comes later."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'indexing'),3,1,'{"it":"A che cosa servono i dati strutturati JSON-LD?","en":"What is JSON-LD structured data for?"}','[{"it":"Descrivere esplicitamente il contenuto","en":"Describing the content explicitly"},{"it":"Rendere la pagina più colorata","en":"Making the page more colourful"},{"it":"Bloccare i crawler","en":"Blocking crawlers"},{"it":"Comprimere le immagini","en":"Compressing images"}]',0,'{"it":"schema.org dà il vocabolario.","en":"schema.org gives the vocabulary."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'ranking'),1,1,'{"it":"Che cosa misurava l’idea del PageRank?","en":"What did the PageRank idea measure?"}','[{"it":"L’autorevolezza tramite i link ricevuti","en":"Authority through received links"},{"it":"Il numero di parole della pagina","en":"The page’s word count"},{"it":"La velocità del server","en":"The server’s speed"},{"it":"I colori del sito","en":"The site’s colours"}]',0,'{"it":"Un link è come un voto.","en":"A link is like a vote."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'ranking'),2,1,'{"it":"Quale pratica viene penalizzata?","en":"Which practice is penalised?"}','[{"it":"Testo nascosto e link comprati","en":"Hidden text and bought links"},{"it":"Usare HTTPS","en":"Using HTTPS"},{"it":"URL leggibili","en":"Readable URLs"},{"it":"Pagine veloci","en":"Fast pages"}]',0,'{"it":"Niente scorciatoie.","en":"No shortcuts."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'ranking'),3,1,'{"it":"A che cosa serve `hreflang`?","en":"What is `hreflang` for?"}','[{"it":"Indicare le versioni in altre lingue","en":"Pointing to versions in other languages"},{"it":"Cambiare il font","en":"Changing the font"},{"it":"Vietare la scansione","en":"Disallowing crawling"},{"it":"Comprimere l’HTML","en":"Compressing HTML"}]',0,'{"it":"Il risultato giusto per ogni lingua.","en":"The right result for each language."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'structured'),1,2,'{"it":"In che formato si scrivono di solito i dati strutturati?","en":"In what format is structured data usually written?"}','[{"it":"JSON-LD","en":"JSON-LD"},{"it":"CSV","en":"CSV"},{"it":"XML-RPC","en":"XML-RPC"},{"it":"YAML","en":"YAML"}]',0,'{"it":"Dentro uno `<script type=\\"application/ld+json\\">`.","en":"Inside a `<script type=\\"application/ld+json\\">`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'structured'),2,2,'{"it":"Quale vocabolario si usa?","en":"Which vocabulary is used?"}','[{"it":"schema.org","en":"schema.org"},{"it":"w3schools","en":"w3schools"},{"it":"MDN","en":"MDN"},{"it":"OpenAPI","en":"OpenAPI"}]',0,'{"it":"Tipi come Course, Article, Event.","en":"Types like Course, Article, Event."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'structured'),3,2,'{"it":"Che cosa trovi in Search Console?","en":"What do you find in Search Console?"}','[{"it":"Pagine indicizzate, query ed errori","en":"Indexed pages, queries and errors"},{"it":"Il codice sorgente di Google","en":"Google’s source code"},{"it":"Le password degli utenti","en":"Users’ passwords"},{"it":"Gli annunci a pagamento soltanto","en":"Paid ads only"}]',0,'{"it":"Lo sguardo di Google sul sito.","en":"Google’s view of the site."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'http-status'),1,2,'{"it":"Quale codice usi quando una pagina ha cambiato indirizzo per sempre?","en":"Which code do you use when a page has changed address for good?"}','[{"it":"200","en":"200"},{"it":"302","en":"302"},{"it":"301","en":"301"},{"it":"404","en":"404"}]',2,'{"it":"`302` e `307` sono per gli spostamenti temporanei.","en":"`302` and `307` are for temporary moves."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'http-status'),2,2,'{"it":"Che cos’è un soft 404?","en":"What is a soft 404?"}','[{"it":"Una pagina «non trovato» che risponde 200","en":"A “not found” page that answers 200"},{"it":"Un 404 con un bel disegno","en":"A 404 with a nice drawing"},{"it":"Un reindirizzamento lento","en":"A slow redirect"},{"it":"Un errore del browser","en":"A browser error"}]',0,'{"it":"Il codice deve dire la verità: se non c’è, `404` o `410`.","en":"The code must tell the truth: if it is not there, `404` or `410`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'http-status'),3,2,'{"it":"Quale risposta usi durante una manutenzione breve?","en":"Which response do you use during short maintenance?"}','[{"it":"`404` su tutte le pagine","en":"`404` on every page"},{"it":"`200` con una pagina vuota","en":"`200` with an empty page"},{"it":"`301` verso la home","en":"`301` to the home page"},{"it":"`503` con `Retry-After`","en":"`503` with `Retry-After`"}]',3,'{"it":"Il crawler capisce che è temporaneo e non toglie le pagine dall’indice.","en":"The crawler understands it is temporary and does not drop the pages from the index."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'ai-crawlers'),1,2,'{"it":"Come si riconosce un crawler in `robots.txt`?","en":"How do you identify a crawler in `robots.txt`?"}','[{"it":"Dal suo indirizzo IP soltanto","en":"By its IP address alone"},{"it":"Dal nome nel suo `User-agent`","en":"By the name in its `User-agent`"},{"it":"Dal colore del logo","en":"By its logo colour"},{"it":"Non si può","en":"You cannot"}]',1,'{"it":"Ogni regola parte da `User-agent:`.","en":"Every rule starts with `User-agent:`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'ai-crawlers'),2,2,'{"it":"Che cosa succede se blocchi `Google-Extended`?","en":"What happens if you block `Google-Extended`?"}','[{"it":"Il sito sparisce dalla Ricerca Google","en":"The site disappears from Google Search"},{"it":"Googlebot smette di visitare il sito","en":"Googlebot stops visiting the site"},{"it":"Chiedi di non usare i contenuti per i modelli Gemini","en":"You ask for the content not to be used for Gemini models"},{"it":"Il sito diventa più veloce","en":"The site becomes faster"}]',2,'{"it":"La Ricerca continua a funzionare come prima.","en":"Search keeps working as before."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'ai-crawlers'),3,2,'{"it":"Che cos’è oggi `llms.txt`?","en":"What is `llms.txt` today?"}','[{"it":"Uno standard obbligatorio del W3C","en":"A mandatory W3C standard"},{"it":"Il sostituto di `robots.txt`","en":"The replacement for `robots.txt`"},{"it":"Un file che blocca tutte le AI","en":"A file that blocks every AI"},{"it":"Una proposta per riassumere un sito ai modelli","en":"A proposal to summarise a site for models"}]',3,'{"it":"Utile forse, ma non garantito.","en":"Perhaps useful, but not guaranteed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'js-mobile'),1,2,'{"it":"Quale versione del sito guarda Google per indicizzarlo?","en":"Which version of the site does Google look at to index it?"}','[{"it":"Quella per computer","en":"The desktop one"},{"it":"Quella mobile","en":"The mobile one"},{"it":"Quella stampata","en":"The printed one"},{"it":"Quella in cache del browser","en":"The browser cache one"}]',1,'{"it":"Si chiama indicizzazione mobile-first.","en":"It is called mobile-first indexing."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'js-mobile'),2,2,'{"it":"Quale elemento segue sicuramente il crawler?","en":"Which element does the crawler surely follow?"}','[{"it":"<span onclick=\\"…\\">","en":"<span onclick=\\"…\\">"},{"it":"<button onclick=\\"…\\">","en":"<button onclick=\\"…\\">"},{"it":"<div data-url=\\"…\\">","en":"<div data-url=\\"…\\">"},{"it":"<a href=\\"/corsi\\">","en":"<a href=\\"/corsi\\">"}]',3,'{"it":"I link veri sono la strada del crawler.","en":"Real links are the crawler’s road."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'js-mobile'),3,2,'{"it":"Perché il rendering lato server aiuta la SEO?","en":"Why does server-side rendering help SEO?"}','[{"it":"L’HTML arriva già completo, senza aspettare il JavaScript","en":"The HTML arrives complete, without waiting for JavaScript"},{"it":"Il server paga i motori di ricerca","en":"The server pays the search engines"},{"it":"Nasconde il codice ai concorrenti","en":"It hides the code from competitors"},{"it":"Toglie la necessità di un titolo","en":"It removes the need for a title"}]',0,'{"it":"Ed è più veloce anche per chi visita.","en":"And it is faster for visitors too."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'formulas'),1,1,'{"it":"Con che carattere inizia una formula?","en":"What character does a formula start with?"}','[{"it":"=","en":"="},{"it":"+","en":"+"},{"it":"#","en":"#"},{"it":"$","en":"$"}]',0,'{"it":"Sempre.","en":"Always."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'formulas'),2,1,'{"it":"Che cosa fa il dollaro in `$F$1`?","en":"What does the dollar in `$F$1` do?"}','[{"it":"Rende fisso il riferimento quando copi","en":"Keeps the reference fixed when copying"},{"it":"Indica che la cella contiene una valuta","en":"Shows the cell holds a currency"},{"it":"Cancella la cella","en":"Clears the cell"},{"it":"Somma la colonna","en":"Sums the column"}]',0,'{"it":"Riferimento assoluto.","en":"Absolute reference."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'formulas'),3,1,'{"it":"Come si separano gli argomenti nell’Excel italiano?","en":"How are arguments separated in Italian Excel?"}','[{"it":"Con il punto e virgola","en":"With semicolons"},{"it":"Con la virgola sempre","en":"Always with commas"},{"it":"Con gli spazi","en":"With spaces"},{"it":"Con i trattini","en":"With dashes"}]',0,'{"it":"=SOMMA(A1;A2)","en":"=SOMMA(A1;A2)"}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'functions'),1,1,'{"it":"Che cosa fa `SE` / `IF`?","en":"What does `IF` / `SE` do?"}','[{"it":"Restituisce un valore o un altro secondo una condizione","en":"Returns one value or another based on a condition"},{"it":"Somma una colonna solo se non è vuota","en":"Sums a column only if it is not empty"},{"it":"Ordina i dati","en":"Sorts data"},{"it":"Crea un grafico","en":"Creates a chart"}]',0,'{"it":"Condizione, se vero, se falso.","en":"Condition, if true, if false."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'functions'),2,1,'{"it":"Quale funzione somma solo le righe che rispettano dei criteri?","en":"Which function sums only rows meeting criteria?"}','[{"it":"SUMIFS / SOMMA.PIÙ.SE","en":"SUMIFS / SOMMA.PIÙ.SE"},{"it":"SUM / SOMMA","en":"SUM / SOMMA"},{"it":"COUNT / CONTA.NUMERI","en":"COUNT / CONTA.NUMERI"},{"it":"MAX","en":"MAX"}]',0,'{"it":"Più criteri insieme.","en":"Several criteria at once."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'functions'),3,1,'{"it":"Che cosa indica l’errore `#NOME?` (in inglese `#NAME?`)?","en":"What does the `#NAME?` error mean?"}','[{"it":"Nome di funzione non riconosciuto","en":"Function name not recognised"},{"it":"Divisione per zero","en":"Division by zero"},{"it":"Valore non trovato","en":"Value not found"},{"it":"Foglio pieno","en":"Sheet full"}]',0,'{"it":"Spesso inglese nell’Excel italiano.","en":"Often English names in Italian Excel."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'lookup'),1,1,'{"it":"Che cosa fa CERCA.X / XLOOKUP?","en":"What does XLOOKUP / CERCA.X do?"}','[{"it":"Cerca un valore e restituisce il corrispondente di un’altra colonna","en":"Looks up a value and returns the matching one from another column"},{"it":"Ordina i dati di una colonna dal più piccolo al più grande","en":"Sorts a column from smallest to largest"},{"it":"Cancella i doppioni","en":"Removes duplicates"},{"it":"Crea una tabella pivot","en":"Creates a pivot table"}]',0,'{"it":"Come una piccola query.","en":"Like a small query."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'lookup'),2,1,'{"it":"Perché preferirlo a CERCA.VERT?","en":"Why prefer it to VLOOKUP?"}','[{"it":"Non si rompe inserendo colonne e cerca in ogni direzione","en":"It does not break on inserted columns and searches any direction"},{"it":"È più vecchio e quindi più compatibile con tutti i file","en":"It is older, so more compatible with every file"},{"it":"Non c’è differenza","en":"There is no difference"},{"it":"Funziona solo su Mac","en":"It only works on Mac"}]',0,'{"it":"Più robusto.","en":"More robust."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'lookup'),3,1,'{"it":"A che cosa serve il quarto argomento?","en":"What is the fourth argument for?"}','[{"it":"Il valore da mostrare se non trova niente","en":"The value shown if nothing is found"},{"it":"Il colore della cella quando trova il valore","en":"The cell colour when the value is found"},{"it":"Il numero di righe","en":"The number of rows"},{"it":"Il nome del foglio","en":"The sheet name"}]',0,'{"it":"Niente #N/D.","en":"No #N/A."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'pivot'),1,1,'{"it":"Che cosa fa una tabella pivot?","en":"What does a pivot table do?"}','[{"it":"Riassume i dati per categorie","en":"Summarises data by categories"},{"it":"Disegna immagini","en":"Draws images"},{"it":"Cancella righe","en":"Deletes rows"},{"it":"Invia email","en":"Sends email"}]',0,'{"it":"Righe, colonne, valori.","en":"Rows, columns, values."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'pivot'),2,1,'{"it":"Quale grafico per l’andamento nel tempo?","en":"Which chart for trends over time?"}','[{"it":"A linee","en":"Line"},{"it":"A torta","en":"Pie"},{"it":"A dispersione 3D","en":"3D scatter"},{"it":"Nessuno","en":"None"}]',0,'{"it":"Le barre confrontano categorie.","en":"Bars compare categories."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'pivot'),3,1,'{"it":"Che cosa evitare nei dati da analizzare?","en":"What should you avoid in data to analyse?"}','[{"it":"Le celle unite","en":"Merged cells"},{"it":"Le intestazioni","en":"Headers"},{"it":"Una riga per record","en":"One row per record"},{"it":"I numeri","en":"Numbers"}]',0,'{"it":"Rompono filtri e pivot.","en":"They break filters and pivots."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'dynamic'),1,1,'{"it":"Che cosa fa `UNICI` (UNIQUE)?","en":"What does `UNIQUE` do?"}','[{"it":"Toglie i doppioni","en":"Removes duplicates"},{"it":"Conta le celle","en":"Counts cells"},{"it":"Ordina","en":"Sorts"},{"it":"Somma","en":"Sums"}]',0,'{"it":"Spesso insieme a ORDINA.","en":"Often with SORT."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'dynamic'),2,1,'{"it":"Che cosa fa `SE.ERRORE` (IFERROR)?","en":"What does `IFERROR` do?"}','[{"it":"Sostituisce un errore con un valore","en":"Replaces an error with a value"},{"it":"Crea un errore","en":"Creates an error"},{"it":"Cancella la riga","en":"Deletes the row"},{"it":"Colora la cella","en":"Colours the cell"}]',0,'{"it":"Niente #N/D nei report.","en":"No #N/A in reports."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'dynamic'),3,1,'{"it":"Che cosa significa che una formula si “espande”?","en":"What does it mean that a formula “spills”?"}','[{"it":"I risultati riempiono le celle vicine","en":"Results fill neighbouring cells"},{"it":"Diventa più lenta","en":"It gets slower"},{"it":"Si copia in un altro file","en":"It copies to another file"},{"it":"Dà errore","en":"It errors"}]',0,'{"it":"È una matrice dinamica.","en":"It is a dynamic array."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'text-dates'),1,2,'{"it":"Che cosa fa `ANNULLA.SPAZI` / `TRIM`?","en":"What does `TRIM` / `ANNULLA.SPAZI` do?"}','[{"it":"Cancella la cella","en":"Clears the cell"},{"it":"Toglie gli spazi in più dal testo","en":"Removes extra spaces from the text"},{"it":"Taglia il testo a 10 caratteri","en":"Cuts the text to 10 characters"},{"it":"Mette il testo in maiuscolo","en":"Puts the text in capitals"}]',1,'{"it":"Utile sui dati copiati da altri sistemi.","en":"Useful on data copied from other systems."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'text-dates'),2,2,'{"it":"Che cosa dà `=D2-C2` se le celle contengono due date?","en":"What does `=D2-C2` give if the cells hold two dates?"}','[{"it":"Un errore","en":"An error"},{"it":"Il testo delle due date unite","en":"The two dates joined as text"},{"it":"Il numero di giorni tra le due date","en":"The number of days between the two dates"},{"it":"L’anno più recente","en":"The latest year"}]',2,'{"it":"Le date sono numeri.","en":"Dates are numbers."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'text-dates'),3,2,'{"it":"Quale funzione unisce un intervallo di celle con un separatore?","en":"Which function joins a range of cells with a separator?"}','[{"it":"`TEXTJOIN` / `TESTO.UNISCI`","en":"`TEXTJOIN` / `TESTO.UNISCI`"},{"it":"`SUM` / `SOMMA`","en":"`SUM` / `SOMMA`"},{"it":"`LEFT` / `SINISTRA`","en":"`LEFT` / `SINISTRA`"},{"it":"`TODAY` / `OGGI`","en":"`TODAY` / `OGGI`"}]',0,'{"it":"Il secondo argomento salta le celle vuote.","en":"The second argument skips empty cells."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'format-validation'),1,2,'{"it":"A che cosa serve la formattazione condizionale?","en":"What is conditional formatting for?"}','[{"it":"A bloccare le celle in modifica","en":"Locking cells against editing"},{"it":"A ordinare la tabella in automatico","en":"Sorting the table automatically"},{"it":"A cambiare il formato del file","en":"Changing the file format"},{"it":"A colorare le celle in base al loro valore","en":"Colouring cells based on their value"}]',3,'{"it":"Le anomalie saltano all’occhio.","en":"Anomalies jump out."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'format-validation'),2,2,'{"it":"Come crei un elenco a discesa in una cella?","en":"How do you create a drop-down list in a cell?"}','[{"it":"Con la convalida dei dati, tipo Elenco","en":"With data validation, List type"},{"it":"Con una tabella pivot","en":"With a pivot table"},{"it":"Con la formattazione condizionale","en":"With conditional formatting"},{"it":"Unendo più celle","en":"By merging several cells"}]',0,'{"it":"Dati → Convalida dati → Elenco.","en":"Data → Data Validation → List."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'format-validation'),3,2,'{"it":"Nella regola `=$E2<OGGI()`, perché il dollaro solo davanti alla E?","en":"In the rule `=$E2<TODAY()`, why the dollar only before the E?"}','[{"it":"Per rendere la regola più veloce","en":"To make the rule faster"},{"it":"Per indicare una valuta","en":"To indicate a currency"},{"it":"Per bloccare la colonna e lasciar scorrere la riga","en":"To lock the column and let the row move"},{"it":"Per bloccare sia riga sia colonna","en":"To lock both row and column"}]',2,'{"it":"Così ogni riga controlla la sua data.","en":"So each row checks its own date."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'let-lambda'),1,2,'{"it":"Che cosa fa `LET`?","en":"What does `LET` do?"}','[{"it":"Blocca la cella per gli altri utenti","en":"Locks the cell for other users"},{"it":"Crea una tabella pivot","en":"Creates a pivot table"},{"it":"Unisce più fogli di lavoro","en":"Merges several worksheets"},{"it":"Dà un nome a un calcolo dentro la formula","en":"Gives a name to a calculation inside the formula"}]',3,'{"it":"Lo calcoli una volta e lo riusi.","en":"You compute it once and reuse it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'let-lambda'),2,2,'{"it":"In `=LET(x; A1*2; x+1)` qual è il risultato?","en":"In `=LET(x, A1*2, x+1)` what is the result?"}','[{"it":"A1 per 2","en":"A1 times 2"},{"it":"A1 per 2, più 1","en":"A1 times 2, plus 1"},{"it":"Il testo «x»","en":"The text “x”"},{"it":"Un errore","en":"An error"}]',1,'{"it":"L’ultimo argomento è il risultato.","en":"The last argument is the result."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'let-lambda'),3,2,'{"it":"Dove salvi una `LAMBDA` per usarla come funzione?","en":"Where do you save a `LAMBDA` to use it as a function?"}','[{"it":"In Gestione nomi, con un nome","en":"In the Name Manager, with a name"},{"it":"In una macro VBA","en":"In a VBA macro"},{"it":"Nelle opzioni di stampa","en":"In the print options"},{"it":"Non si può salvare","en":"It cannot be saved"}]',0,'{"it":"Poi la chiami come `=CONIVA(B2)`.","en":"Then you call it like `=CONIVA(B2)`."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'modern'),1,2,'{"it":"Che cosa restituisce `REGEXTEST`?","en":"What does `REGEXTEST` return?"}','[{"it":"Il testo trovato","en":"The text found"},{"it":"La posizione del testo","en":"The position of the text"},{"it":"VERO o FALSO, se il modello corrisponde","en":"TRUE or FALSE, whether the pattern matches"},{"it":"Il numero di parole","en":"The number of words"}]',2,'{"it":"`REGEXEXTRACT` restituisce il testo.","en":"`REGEXEXTRACT` returns the text."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'modern'),2,2,'{"it":"Qual è il vantaggio di `GROUPBY` rispetto a una tabella pivot?","en":"What is the advantage of `GROUPBY` over a pivot table?"}','[{"it":"Disegna grafici in 3D","en":"It draws 3D charts"},{"it":"Funziona anche in Excel 2010","en":"It also works in Excel 2010"},{"it":"Non ha bisogno di dati","en":"It needs no data"},{"it":"È una formula che si aggiorna da sola","en":"It is a formula that updates by itself"}]',3,'{"it":"La pivot va aggiornata a mano.","en":"A pivot has to be refreshed by hand."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'excel' AND slug = 'modern'),3,2,'{"it":"Che cosa conviene fare con le formule proposte da Copilot?","en":"What should you do with the formulas Copilot suggests?"}','[{"it":"Controllarle prima di fidarti","en":"Check them before trusting them"},{"it":"Usarle senza guardarle","en":"Use them without looking"},{"it":"Stamparle e cancellarle","en":"Print and delete them"},{"it":"Trasformarle in macro","en":"Turn them into macros"}]',0,'{"it":"L’IA può sbagliare riferimenti e criteri.","en":"AI can get references and criteria wrong."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'query'),1,1,'{"it":"A che cosa serve Power Query?","en":"What is Power Query for?"}','[{"it":"Pulire e trasformare i dati prima dell’analisi","en":"Cleaning and transforming data before analysis"},{"it":"Disegnare loghi","en":"Drawing logos"},{"it":"Inviare email","en":"Sending email"},{"it":"Scrivere documenti partendo dai dati","en":"Writing documents from data"}]',0,'{"it":"L’editor delle trasformazioni.","en":"The transformation editor."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'query'),2,1,'{"it":"Che cosa succede ai passaggi di Power Query quando aggiorni i dati?","en":"What happens to Power Query steps when you refresh data?"}','[{"it":"Vengono ripetuti automaticamente","en":"They are repeated automatically"},{"it":"Si perdono","en":"They are lost"},{"it":"Vanno rifatti a mano","en":"They must be redone by hand"},{"it":"Si cancellano i dati","en":"Data is deleted"}]',0,'{"it":"Tutto registrato.","en":"All recorded."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'query'),3,1,'{"it":"Dove si crea un report di solito?","en":"Where is a report usually built?"}','[{"it":"Power BI Desktop","en":"Power BI Desktop"},{"it":"Paint","en":"Paint"},{"it":"Outlook","en":"Outlook"},{"it":"Il blocco note","en":"Notepad"}]',0,'{"it":"Poi si pubblica online.","en":"Then published online."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'model'),1,1,'{"it":"Che cosa c’è al centro di uno schema a stella?","en":"What sits at the centre of a star schema?"}','[{"it":"La tabella dei fatti","en":"The fact table"},{"it":"La tabella dei colori","en":"The colour table"},{"it":"Un grafico","en":"A chart"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Le dimensioni intorno.","en":"Dimensions around it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'model'),2,1,'{"it":"Che tipo di relazione collega Prodotti e Vendite?","en":"What relationship type links Products and Sales?"}','[{"it":"Uno-a-molti","en":"One-to-many"},{"it":"Molti-a-molti sempre","en":"Always many-to-many"},{"it":"Nessuna","en":"None"},{"it":"Uno-a-uno sempre","en":"Always one-to-one"}]',0,'{"it":"Un prodotto, tante vendite.","en":"One product, many sales."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'model'),3,1,'{"it":"Perché serve una tabella Calendario?","en":"Why is a Calendar table needed?"}','[{"it":"Per analizzare l’andamento nel tempo","en":"To analyse trends over time"},{"it":"Per le ferie","en":"For holidays"},{"it":"Per i compleanni","en":"For birthdays"},{"it":"Non serve","en":"It is not needed"}]',0,'{"it":"Anno, mese, trimestre…","en":"Year, month, quarter…"}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'dax'),1,1,'{"it":"Che cosa fa CALCULATE?","en":"What does CALCULATE do?"}','[{"it":"Calcola una misura cambiando i filtri","en":"Computes a measure while changing filters"},{"it":"Somma due numeri scritti nella formula","en":"Adds two numbers written in the formula"},{"it":"Crea una tabella","en":"Creates a table"},{"it":"Ordina i dati","en":"Sorts data"}]',0,'{"it":"Il cuore di DAX.","en":"The heart of DAX."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'dax'),2,1,'{"it":"Perché usare DIVIDE invece di /?","en":"Why use DIVIDE instead of /?"}','[{"it":"Gestisce la divisione per zero","en":"It handles division by zero"},{"it":"È più veloce sempre","en":"It is always faster"},{"it":"È obbligatorio","en":"It is mandatory"},{"it":"Non c’è motivo","en":"There is no reason"}]',0,'{"it":"Niente errori nei visual.","en":"No errors in visuals."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'dax'),3,1,'{"it":"Le funzioni DAX hanno nomi italiani nella versione italiana?","en":"Do DAX functions have Italian names in the Italian version?"}','[{"it":"No, restano in inglese","en":"No, they stay in English"},{"it":"Sì, sempre","en":"Yes, always"},{"it":"Solo SUM","en":"Only SUM"},{"it":"Dipende dal giorno","en":"It depends on the day"}]',0,'{"it":"A differenza di Excel.","en":"Unlike Excel."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'report'),1,1,'{"it":"Che cos’è uno slicer?","en":"What is a slicer?"}','[{"it":"Un filtro visivo che l’utente usa nel report","en":"A visual filter the user uses in the report"},{"it":"Un tipo di grafico a torta tagliato","en":"A kind of sliced pie chart"},{"it":"Un errore","en":"An error"},{"it":"Un file","en":"A file"}]',0,'{"it":"Per esplorare i dati.","en":"To explore data."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'report'),2,1,'{"it":"Che cosa fa la sicurezza a livello di riga?","en":"What does row-level security do?"}','[{"it":"Mostra a ciascuno solo i propri dati","en":"Shows each person only their own data"},{"it":"Cifra il computer di chi apre il report","en":"Encrypts the computer of whoever opens the report"},{"it":"Cancella le righe","en":"Deletes rows"},{"it":"Blocca il report","en":"Locks the report"}]',0,'{"it":"Per regione, reparto…","en":"By region, department…"}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'report'),3,1,'{"it":"Che cosa mettere in alto in un report?","en":"What goes at the top of a report?"}','[{"it":"I numeri chiave","en":"The key numbers"},{"it":"I dettagli di ogni riga","en":"Every row’s details"},{"it":"Il logo enorme","en":"A huge logo"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Poi andamenti e dettagli.","en":"Then trends and details."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'time-security'),1,2,'{"it":"Che cosa serve per l’intelligenza temporale?","en":"What is needed for time intelligence?"}','[{"it":"Una tabella calendario collegata","en":"A linked calendar table"},{"it":"Un grafico a torta","en":"A pie chart"},{"it":"Un file Excel","en":"An Excel file"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Segnata come tabella di date.","en":"Marked as a date table."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'time-security'),2,2,'{"it":"Che cosa calcola `SAMEPERIODLASTYEAR`?","en":"What does `SAMEPERIODLASTYEAR` compute?"}','[{"it":"Lo stesso periodo dell’anno prima","en":"The same period last year"},{"it":"L’anno prossimo","en":"Next year"},{"it":"La media mensile","en":"The monthly average"},{"it":"Il totale generale","en":"The grand total"}]',0,'{"it":"Dentro CALCULATE.","en":"Inside CALCULATE."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'time-security'),3,2,'{"it":"A che cosa serve la RLS?","en":"What is RLS for?"}','[{"it":"Mostrare a ognuno solo i suoi dati","en":"Showing each person only their data"},{"it":"Velocizzare i grafici","en":"Speeding up charts"},{"it":"Cambiare i colori","en":"Changing colours"},{"it":"Esportare in PDF","en":"Exporting to PDF"}]',0,'{"it":"Ruoli con filtri DAX.","en":"Roles with DAX filters."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'dax-vars'),1,2,'{"it":"Quando serve `SUMX` invece di `SUM`?","en":"When do you need `SUMX` instead of `SUM`?"}','[{"it":"Quando la colonna contiene testo","en":"When the column holds text"},{"it":"Quando devi calcolare un’espressione su ogni riga prima di sommare","en":"When you must compute an expression on each row before summing"},{"it":"Quando la tabella è vuota","en":"When the table is empty"},{"it":"Mai, sono identiche","en":"Never, they are identical"}]',1,'{"it":"Per esempio quantità × prezzo.","en":"For example quantity × price."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'dax-vars'),2,2,'{"it":"Che cosa fa `ALL(Prodotti)` dentro `CALCULATE`?","en":"What does `ALL(Prodotti)` do inside `CALCULATE`?"}','[{"it":"Seleziona solo il primo prodotto","en":"Selects only the first product"},{"it":"Cancella la tabella Prodotti","en":"Deletes the Products table"},{"it":"Conta tutti i prodotti","en":"Counts every product"},{"it":"Toglie i filtri sulla tabella Prodotti","en":"Removes the filters on the Products table"}]',3,'{"it":"Serve per i totali generali e le percentuali.","en":"It is used for grand totals and percentages."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'dax-vars'),3,2,'{"it":"Quale parola chiude una misura con variabili?","en":"Which word closes a measure with variables?"}','[{"it":"RETURN","en":"RETURN"},{"it":"END","en":"END"},{"it":"RESULT","en":"RESULT"},{"it":"DONE","en":"DONE"}]',0,'{"it":"`VAR` definisce, `RETURN` restituisce.","en":"`VAR` defines, `RETURN` returns."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'service'),1,2,'{"it":"Che cos’è un’area di lavoro?","en":"What is a workspace?"}','[{"it":"Lo spazio condiviso di un team nel servizio","en":"A team’s shared space in the service"},{"it":"La pagina di un report","en":"A page of a report"},{"it":"Un tipo di grafico","en":"A kind of chart"},{"it":"Una cartella sul tuo computer","en":"A folder on your computer"}]',0,'{"it":"Con ruoli diversi per i membri.","en":"With different roles for its members."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'service'),2,2,'{"it":"A che cosa serve il gateway dati locale?","en":"What is the on-premises data gateway for?"}','[{"it":"A disegnare report sul telefono","en":"Drawing reports on the phone"},{"it":"A cifrare i file `.pbix`","en":"Encrypting `.pbix` files"},{"it":"A tradurre DAX in Excel","en":"Translating DAX into Excel"},{"it":"A collegare il cloud ai dati che stanno in azienda","en":"Connecting the cloud to data kept on company premises"}]',3,'{"it":"Senza, l’aggiornamento pianificato non li raggiunge.","en":"Without it, scheduled refresh cannot reach them."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'service'),3,2,'{"it":"Qual è il modo migliore per distribuire un report a tutta l’azienda?","en":"What is the best way to distribute a report to the whole company?"}','[{"it":"Mandare il `.pbix` per email","en":"Emailing the `.pbix`"},{"it":"Stampare ogni pagina","en":"Printing every page"},{"it":"Pubblicare un’app da un’area di lavoro","en":"Publishing an app from a workspace"},{"it":"Fare uno screenshot","en":"Taking a screenshot"}]',2,'{"it":"Una versione sola, aggiornata.","en":"One version, kept up to date."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'modern'),1,2,'{"it":"Che cosa fa la modalità Direct Lake?","en":"What does Direct Lake mode do?"}','[{"it":"Copia i dati in un file Excel","en":"Copies the data into an Excel file"},{"it":"Legge i dati direttamente da OneLake senza importarli","en":"Reads the data directly from OneLake without importing it"},{"it":"Disattiva l’aggiornamento","en":"Turns off refresh"},{"it":"Mostra i report solo offline","en":"Shows reports offline only"}]',1,'{"it":"Prestazioni da importazione, dati sempre aggiornati.","en":"Import-like performance, data always fresh."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'modern'),2,2,'{"it":"Perché usare il formato PBIP?","en":"Why use the PBIP format?"}','[{"it":"Per stampare meglio i report","en":"To print reports better"},{"it":"Per cifrare il modello","en":"To encrypt the model"},{"it":"Per ridurre il numero di visual","en":"To reduce the number of visuals"},{"it":"Per salvare il report come file di testo da gestire con Git","en":"To save the report as text files managed with Git"}]',3,'{"it":"Così si vedono le differenze e si lavora in team.","en":"So you see the differences and work as a team."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'powerbi' AND slug = 'modern'),3,2,'{"it":"A che cosa servono le funzioni DAX definite dall’utente?","en":"What are DAX user-defined functions for?"}','[{"it":"A riusare la stessa logica in molte misure","en":"Reusing the same logic in many measures"},{"it":"A cambiare i colori del tema","en":"Changing the theme colours"},{"it":"A creare utenti nel servizio","en":"Creating users in the service"},{"it":"A importare file CSV","en":"Importing CSV files"}]',0,'{"it":"Si scrivono una volta e si chiamano ovunque.","en":"Written once, called anywhere."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'what'),1,1,'{"it":"Che differenza c’è tra UX e UI?","en":"What is the difference between UX and UI?"}','[{"it":"La UX è l’esperienza intera, la UI l’interfaccia","en":"UX is the whole experience, UI the interface"},{"it":"Sono la stessa cosa con due nomi","en":"They are the same thing with two names"},{"it":"La UI è l’esperienza, la UX la grafica","en":"UI is the experience, UX the graphics"},{"it":"La UX riguarda solo i colori","en":"UX is only about colours"}]',0,'{"it":"La UI è una parte della UX.","en":"UI is one part of UX."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'what'),2,1,'{"it":"Che cosa significa design centrato sull’utente?","en":"What does user-centred design mean?"}','[{"it":"Partire dai bisogni delle persone","en":"Starting from people’s needs"},{"it":"Partire dalle funzioni da costruire","en":"Starting from features to build"},{"it":"Copiare i concorrenti","en":"Copying competitors"},{"it":"Seguire i gusti del capo","en":"Following the boss’s taste"}]',0,'{"it":"Prima le persone.","en":"People first."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'what'),3,1,'{"it":"Quale di queste è una qualità della buona UX?","en":"Which of these is a quality of good UX?"}','[{"it":"È accessibile a tutti","en":"It is accessible to everyone"},{"it":"Ha più animazioni possibili","en":"It has as many animations as possible"},{"it":"Ha tutte le funzioni in una schermata","en":"It has every feature on one screen"},{"it":"Usa solo il colore preferito del team","en":"It uses only the team’s favourite colour"}]',0,'{"it":"Utile, usabile, accessibile, piacevole.","en":"Useful, usable, accessible, pleasant."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'users'),1,1,'{"it":"Che cos’è una persona nella UX?","en":"What is a persona in UX?"}','[{"it":"Un ritratto di utente tipico basato sui dati","en":"A data-based portrait of a typical user"},{"it":"Un cliente reale con nome e cognome","en":"A real customer with full name"},{"it":"Il designer del progetto","en":"The project’s designer"},{"it":"Un personaggio dei fumetti","en":"A comic book character"}]',0,'{"it":"Immaginaria, ma fondata.","en":"Imaginary, but grounded."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'users'),2,1,'{"it":"Che cos’è un punto di dolore?","en":"What is a pain point?"}','[{"it":"Un ostacolo che frustra l’utente","en":"An obstacle that frustrates the user"},{"it":"Un errore nel codice","en":"A bug in the code"},{"it":"Il prezzo del prodotto","en":"The product’s price"},{"it":"Una pagina di errore 404","en":"A 404 error page"}]',0,'{"it":"Là c’è un’opportunità.","en":"There lies an opportunity."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'users'),3,1,'{"it":"Quale formato descrive un job to be done?","en":"Which format describes a job to be done?"}','[{"it":"Quando… voglio… così posso…","en":"When… I want to… so I can…"},{"it":"Se… allora… altrimenti…","en":"If… then… else…"},{"it":"Chi… dove… quando…","en":"Who… where… when…"},{"it":"Prima… poi… infine…","en":"First… then… finally…"}]',0,'{"it":"Situazione, motivazione, risultato.","en":"Situation, motivation, outcome."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'process'),1,1,'{"it":"Quali sono le quattro fasi del Double Diamond?","en":"What are the four phases of the Double Diamond?"}','[{"it":"Scoprire, definire, sviluppare, consegnare","en":"Discover, define, develop, deliver"},{"it":"Disegnare, colorare, stampare, vendere","en":"Draw, colour, print, sell"},{"it":"Codificare, testare, rilasciare, chiudere","en":"Code, test, release, close"},{"it":"Ideare, votare, copiare, pubblicare","en":"Ideate, vote, copy, publish"}]',0,'{"it":"Due rombi, quattro fasi.","en":"Two diamonds, four phases."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'process'),2,1,'{"it":"Che cos’è un wireframe?","en":"What is a wireframe?"}','[{"it":"Uno schema semplice della struttura","en":"A simple layout of the structure"},{"it":"La versione finale colorata","en":"The final coloured version"},{"it":"Il codice della pagina","en":"The page’s code"},{"it":"Un cavo di rete","en":"A network cable"}]',0,'{"it":"Struttura prima della grafica.","en":"Structure before visuals."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'process'),3,1,'{"it":"Perché il design è iterativo?","en":"Why is design iterative?"}','[{"it":"Testare e correggere presto costa meno","en":"Testing and fixing early costs less"},{"it":"Per allungare i tempi","en":"To stretch the timeline"},{"it":"Perché i designer cambiano idea a caso","en":"Because designers change their minds randomly"},{"it":"Non lo è","en":"It is not"}]',0,'{"it":"Errori su carta, non nel codice.","en":"Mistakes on paper, not in code."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'heuristics'),1,1,'{"it":"Una barra di avanzamento durante il caricamento applica quale euristica?","en":"A progress bar while loading applies which heuristic?"}','[{"it":"Visibilità dello stato del sistema","en":"Visibility of system status"},{"it":"Estetica minimalista","en":"Minimalist aesthetics"},{"it":"Flessibilità d’uso","en":"Flexibility of use"},{"it":"Documentazione","en":"Documentation"}]',0,'{"it":"L’utente sa che cosa succede.","en":"The user knows what is happening."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'heuristics'),2,1,'{"it":"Che cosa significa “riconoscere invece di ricordare”?","en":"What does “recognition over recall” mean?"}','[{"it":"Mostrare le opzioni invece di farle ricordare","en":"Showing options instead of making users remember them"},{"it":"Ricordare la password dell’utente","en":"Remembering the user’s password"},{"it":"Riconoscere il volto dell’utente","en":"Recognising the user’s face"},{"it":"Usare un tutorial lungo","en":"Using a long tutorial"}]',0,'{"it":"Meno carico sulla memoria.","en":"Less load on memory."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'heuristics'),3,1,'{"it":"Quanti utenti bastano per un primo test che trovi molti problemi?","en":"How many users are enough for a first test that finds many problems?"}','[{"it":"Circa 5","en":"About 5"},{"it":"Almeno 500","en":"At least 500"},{"it":"Nessuno, basta il team","en":"None, the team is enough"},{"it":"Esattamente 1","en":"Exactly 1"}]',0,'{"it":"Pochi, ma ripetuti.","en":"Few, but repeated."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'writing'),1,2,'{"it":"Quale etichetta di pulsante è migliore?","en":"Which button label is better?"}','[{"it":"Salva la bozza","en":"Save draft"},{"it":"OK","en":"OK"},{"it":"Invia dati","en":"Submit data"},{"it":"Clicca qui","en":"Click here"}]',0,'{"it":"Dice cosa succede.","en":"It says what happens."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'writing'),2,2,'{"it":"Che cosa deve dire un messaggio d’errore?","en":"What should an error message say?"}','[{"it":"Cosa è successo e come rimediare","en":"What happened and how to fix it"},{"it":"Il codice tecnico soltanto","en":"Only the technical code"},{"it":"Che l’utente ha sbagliato","en":"That the user was wrong"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Senza colpe.","en":"Without blame."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'writing'),3,2,'{"it":"Perché usare sempre le stesse parole?","en":"Why always use the same words?"}','[{"it":"Per non confondere le persone","en":"So people are not confused"},{"it":"Per risparmiare spazio","en":"To save space"},{"it":"Per la SEO","en":"For SEO"},{"it":"Non serve","en":"It is not needed"}]',0,'{"it":"Coerenza = fiducia.","en":"Consistency = trust."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'norman'),1,2,'{"it":"Che cos’è un segnale (signifier)?","en":"What is a signifier?"}','[{"it":"Un oggetto in 3D","en":"A 3D object"},{"it":"L’indizio che comunica come usare qualcosa","en":"The clue that communicates how to use something"},{"it":"Un messaggio d’errore del sistema","en":"A system error message"},{"it":"La firma del designer sul progetto","en":"The designer’s signature on the project"}]',1,'{"it":"Dice «tira», «tocca», «trascina».","en":"It says “pull”, “tap”, “drag”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'norman'),2,2,'{"it":"Una porta ha una maniglia da tirare, ma va spinta. Che problema ha?","en":"A door has a pull handle, but must be pushed. What is wrong with it?"}','[{"it":"Il feedback arriva troppo tardi","en":"The feedback arrives too late"},{"it":"Ha troppi colori diversi","en":"It has too many different colours"},{"it":"Il segnale suggerisce l’azione sbagliata","en":"The signifier suggests the wrong action"},{"it":"Manca un modello mentale del designer","en":"The designer lacks a mental model"}]',2,'{"it":"Si chiama «porta di Norman».","en":"It is called a “Norman door”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'norman'),3,2,'{"it":"Che cosa vuol dire mappatura?","en":"What does mapping mean?"}','[{"it":"Disegnare la mappa del sito","en":"Drawing the site map"},{"it":"Tradurre l’interfaccia in più lingue","en":"Translating the interface into several languages"},{"it":"Salvare la posizione GPS dell’utente","en":"Saving the user’s GPS position"},{"it":"Disporre i comandi come ciò che controllano","en":"Laying out controls like what they control"}]',3,'{"it":"Come le manopole dei fornelli.","en":"Like hob knobs."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'accessibility'),1,2,'{"it":"Che cosa significa POUR nelle WCAG?","en":"What does POUR mean in WCAG?"}','[{"it":"Pubblico, ordinato, utile, rapido","en":"Public, orderly, useful, rapid"},{"it":"Pagina, oggetto, utente, ruolo","en":"Page, object, user, role"},{"it":"Percepibile, utilizzabile, comprensibile, robusto","en":"Perceivable, operable, understandable, robust"},{"it":"Prova, osserva, usa, rifai","en":"Probe, observe, use, redo"}]',2,'{"it":"I quattro principi dell’accessibilità.","en":"The four principles of accessibility."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'accessibility'),2,2,'{"it":"Che dimensione minima chiedono le WCAG 2.2 (livello AA) per un target?","en":"What minimum target size does WCAG 2.2 (level AA) ask for?"}','[{"it":"12×12 px CSS","en":"12×12 CSS px"},{"it":"24×24 px CSS, o spazio intorno","en":"24×24 CSS px, or space around it"},{"it":"64×64 px CSS","en":"64×64 CSS px"},{"it":"Nessuna regola sui target","en":"No rule on targets"}]',1,'{"it":"Criterio 2.5.8. Apple e Material chiedono anche di più.","en":"Criterion 2.5.8. Apple and Material ask for even more."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-base' AND slug = 'accessibility'),3,2,'{"it":"Quando conviene pensare all’accessibilità?","en":"When is it best to think about accessibility?"}','[{"it":"Solo dopo il lancio","en":"Only after launch"},{"it":"Quando qualcuno si lamenta","en":"When someone complains"},{"it":"Solo per i siti della pubblica amministrazione","en":"Only for public administration sites"},{"it":"Dall’inizio del progetto","en":"From the start of the project"}]',3,'{"it":"Dopo costa molto di più.","en":"Later it costs much more."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'research'),1,2,'{"it":"Che cosa dice soprattutto la ricerca quantitativa?","en":"What does quantitative research mainly tell you?"}','[{"it":"Dove e quanto succede qualcosa","en":"Where and how often something happens"},{"it":"Perché le persone si comportano così","en":"Why people behave that way"},{"it":"Che colore preferiscono","en":"What colour they prefer"},{"it":"Niente di utile","en":"Nothing useful"}]',0,'{"it":"I numeri indicano il dove.","en":"Numbers point to the where."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'research'),2,2,'{"it":"Quale domanda d’intervista è migliore?","en":"Which interview question is better?"}','[{"it":"Raccontami l’ultima volta che l’hai fatto","en":"Tell me about the last time you did it"},{"it":"Non trovi comodo questo tasto?","en":"Don’t you find this button handy?"},{"it":"Lo compreresti sicuramente, vero?","en":"You would surely buy it, right?"},{"it":"Ti piace il nostro logo nuovo?","en":"Do you like our new logo?"}]',0,'{"it":"Fatti passati, non guidati.","en":"Past facts, not led."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'research'),3,2,'{"it":"Perché osservare oltre a chiedere?","en":"Why observe as well as ask?"}','[{"it":"Detto e fatto spesso non coincidono","en":"What is said and done often differ"},{"it":"Osservare è più veloce sempre","en":"Observing is always faster"},{"it":"Le interviste sono vietate","en":"Interviews are forbidden"},{"it":"Per non parlare con gli utenti","en":"To avoid talking to users"}]',0,'{"it":"Il comportamento non mente.","en":"Behaviour does not lie."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'ia'),1,2,'{"it":"Che cosa decide l’architettura dell’informazione?","en":"What does information architecture decide?"}','[{"it":"Come organizzare ed etichettare i contenuti","en":"How to organise and label content"},{"it":"Il colore dei pulsanti","en":"The buttons’ colour"},{"it":"Il server su cui pubblicare","en":"The server to publish on"},{"it":"Il prezzo dei prodotti","en":"Product prices"}]',0,'{"it":"Trovare ciò che si cerca.","en":"Finding what you look for."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'ia'),2,2,'{"it":"Che differenza c’è tra card sorting aperto e chiuso?","en":"What is the difference between open and closed card sorting?"}','[{"it":"Nell’aperto gli utenti creano i gruppi","en":"In open sorting users create the groups"},{"it":"Nel chiuso le schede sono girate","en":"In closed sorting cards are face down"},{"it":"L’aperto si fa all’aperto","en":"Open sorting is done outdoors"},{"it":"Nessuna","en":"None"}]',0,'{"it":"Aperto: nuove categorie.","en":"Open: new categories."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'ia'),3,2,'{"it":"A che cosa serve il tree testing?","en":"What is tree testing for?"}','[{"it":"Verificare una gerarchia senza grafica","en":"Checking a hierarchy without visuals"},{"it":"Testare la velocità del sito","en":"Testing site speed"},{"it":"Disegnare alberi","en":"Drawing trees"},{"it":"Contare i link","en":"Counting links"}]',0,'{"it":"Solo struttura ed etichette.","en":"Structure and labels only."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'flows'),1,2,'{"it":"Che cosa descrive uno user flow?","en":"What does a user flow describe?"}','[{"it":"I passi per completare un compito","en":"The steps to complete a task"},{"it":"Il flusso di dati nel server","en":"Data flow on the server"},{"it":"L’andamento delle vendite","en":"The sales trend"},{"it":"Le ore di lavoro del team","en":"The team’s working hours"}]',0,'{"it":"Schermate e scelte.","en":"Screens and choices."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'flows'),2,2,'{"it":"Che cos’è un touchpoint?","en":"What is a touchpoint?"}','[{"it":"Un punto di contatto tra persona e servizio","en":"A point of contact between person and service"},{"it":"Uno schermo touch","en":"A touch screen"},{"it":"Un tipo di icona","en":"A kind of icon"},{"it":"Un pulsante grande","en":"A big button"}]',0,'{"it":"Sito, negozio, email…","en":"Site, shop, email…"}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'flows'),3,2,'{"it":"Che cosa aggiunge la journey map rispetto a un flow?","en":"What does a journey map add compared to a flow?"}','[{"it":"Tutte le fasi e le emozioni della persona","en":"All phases and the person’s emotions"},{"it":"Il codice delle schermate","en":"The screens’ code"},{"it":"I colori del brand","en":"Brand colours"},{"it":"Il numero di pixel","en":"The pixel count"}]',0,'{"it":"Una visione d’insieme.","en":"A big-picture view."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'testing'),1,2,'{"it":"Quando usare un prototipo a bassa fedeltà?","en":"When to use a low-fidelity prototype?"}','[{"it":"Per testare struttura e flussi presto","en":"To test structure and flows early"},{"it":"Per scegliere la tonalità di un colore","en":"To choose a colour shade"},{"it":"Per misurare la velocità del server","en":"To measure server speed"},{"it":"Mai","en":"Never"}]',0,'{"it":"Veloce da fare e da buttare.","en":"Quick to make and discard."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'testing'),2,2,'{"it":"Quale compito di test è scritto meglio?","en":"Which test task is written better?"}','[{"it":"Trova un regalo sotto 30 € per sabato","en":"Find a gift under €30 for Saturday"},{"it":"Clicca su Regali e poi su Filtri","en":"Click Gifts and then Filters"},{"it":"Guarda la home e dimmi se ti piace","en":"Look at the home page and say if you like it"},{"it":"Prova tutti i pulsanti","en":"Try every button"}]',0,'{"it":"Uno scopo, non istruzioni.","en":"A goal, not instructions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'testing'),3,2,'{"it":"Che cos’è il SUS?","en":"What is the SUS?"}','[{"it":"Un questionario standard di usabilità","en":"A standard usability questionnaire"},{"it":"Un software di prototipazione","en":"A prototyping tool"},{"it":"Un errore di sistema","en":"A system error"},{"it":"Un tipo di font","en":"A kind of font"}]',0,'{"it":"System Usability Scale.","en":"System Usability Scale."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'synthesis'),1,3,'{"it":"A che cosa serve una mappa di affinità?","en":"What is an affinity map for?"}','[{"it":"Raggruppare le note in temi","en":"Grouping notes into themes"},{"it":"Disegnare il sito","en":"Drawing the site"},{"it":"Calcolare il budget","en":"Calculating the budget"},{"it":"Scegliere i colori","en":"Choosing colours"}]',0,'{"it":"Dal caos ai temi.","en":"From chaos to themes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'synthesis'),2,3,'{"it":"Che cos’è un insight?","en":"What is an insight?"}','[{"it":"Un comportamento con il suo perché","en":"A behaviour with its why"},{"it":"Una citazione qualsiasi","en":"Any quote"},{"it":"Un numero di visite","en":"A visit count"},{"it":"Una richiesta di funzione","en":"A feature request"}]',0,'{"it":"Spiega, non solo descrive.","en":"It explains, not just describes."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'synthesis'),3,3,'{"it":"Che cosa va fatto prima nella matrice impatto/sforzo?","en":"What goes first in the impact/effort matrix?"}','[{"it":"Alto impatto, basso sforzo","en":"High impact, low effort"},{"it":"Basso impatto, alto sforzo","en":"Low impact, high effort"},{"it":"Tutto insieme","en":"Everything together"},{"it":"Ciò che piace al capo","en":"What the boss likes"}]',0,'{"it":"Le vittorie rapide.","en":"Quick wins."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'surveys'),1,3,'{"it":"Che problema ha la domanda «L’app è veloce e facile da usare?»","en":"What is wrong with the question “Is the app fast and easy to use?”"}','[{"it":"È troppo corta per essere utile","en":"It is too short to be useful"},{"it":"Usa parole troppo tecniche","en":"It uses words that are too technical"},{"it":"Chiede due cose in una","en":"It asks two things in one"},{"it":"Non ha una scala numerica","en":"It has no numeric scale"}]',2,'{"it":"Una domanda, un concetto.","en":"One question, one concept."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'surveys'),2,3,'{"it":"Che cosa mostra una heatmap?","en":"What does a heatmap show?"}','[{"it":"La temperatura del telefono","en":"The phone’s temperature"},{"it":"Dove si clicca e fin dove si scorre","en":"Where people click and how far they scroll"},{"it":"Il tempo di caricamento delle pagine","en":"Page loading times"},{"it":"Le vendite divise per regione","en":"Sales split by region"}]',1,'{"it":"Più caldo = più attenzione.","en":"Hotter = more attention."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'surveys'),3,3,'{"it":"Perché provare un questionario con 2-3 persone prima di inviarlo?","en":"Why try a survey with 2-3 people before sending it?"}','[{"it":"Per scoprire le domande confuse in tempo","en":"To find confusing questions in time"},{"it":"Per avere più risposte in totale","en":"To get more answers overall"},{"it":"Perché è obbligatorio per legge","en":"Because the law requires it"},{"it":"Per scegliere il colore del modulo","en":"To choose the form’s colour"}]',0,'{"it":"Dopo l’invio non si torna indietro.","en":"Once sent, there is no going back."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'ideation'),1,3,'{"it":"Quale domanda è nel formato «Come potremmo…?»","en":"Which question is in the “How might we…?” format?"}','[{"it":"Perché gli utenti sbagliano sempre?","en":"Why do users always get it wrong?"},{"it":"Come potremmo aiutare chi viaggia a trovare un treno in 30 secondi?","en":"How might we help travellers find a train in 30 seconds?"},{"it":"Quanto costerà questo progetto?","en":"How much will this project cost?"},{"it":"Chi ha disegnato questa schermata?","en":"Who designed this screen?"}]',1,'{"it":"Un problema diventa un invito.","en":"A problem becomes an invitation."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'ideation'),2,3,'{"it":"Che cos’è il Crazy 8?","en":"What are Crazy 8s?"}','[{"it":"Otto riunioni in un giorno","en":"Eight meetings in one day"},{"it":"Un test con otto utenti","en":"A test with eight users"},{"it":"Otto idee abbozzate in otto minuti","en":"Eight ideas sketched in eight minutes"},{"it":"Una griglia di layout a otto colonne","en":"An eight-column layout grid"}]',2,'{"it":"Oltre la prima idea ovvia.","en":"Past the first obvious idea."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-intermediate' AND slug = 'ideation'),3,3,'{"it":"Quanto dura un design sprint classico?","en":"How long does a classic design sprint last?"}','[{"it":"Un’ora","en":"One hour"},{"it":"Sei mesi","en":"Six months"},{"it":"Un anno","en":"One year"},{"it":"Cinque giorni","en":"Five days"}]',3,'{"it":"Esistono anche varianti da quattro giorni.","en":"Four-day variants also exist."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'laws'),1,3,'{"it":"Che cosa dice la legge di Hick?","en":"What does Hick’s law say?"}','[{"it":"Più opzioni, più tempo per scegliere","en":"More options, more time to choose"},{"it":"I bersagli grandi sono più lenti","en":"Large targets are slower"},{"it":"Gli utenti leggono tutto","en":"Users read everything"},{"it":"Il blu è il colore più cliccato","en":"Blue is the most clicked colour"}]',0,'{"it":"Riduci e raggruppa.","en":"Reduce and group."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'laws'),2,3,'{"it":"Quale legge giustifica pulsanti principali grandi e vicini?","en":"Which law justifies big, nearby main buttons?"}','[{"it":"Legge di Fitts","en":"Fitts’s law"},{"it":"Legge di Hick","en":"Hick’s law"},{"it":"Legge di Jakob","en":"Jakob’s law"},{"it":"Legge di Murphy","en":"Murphy’s law"}]',0,'{"it":"Dimensione e distanza.","en":"Size and distance."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'laws'),3,3,'{"it":"Perché un numero di telefono si mostra a gruppi?","en":"Why is a phone number shown in groups?"}','[{"it":"Il chunking riduce il carico cognitivo","en":"Chunking reduces cognitive load"},{"it":"Per occupare più spazio","en":"To take up more space"},{"it":"Per motivi legali","en":"For legal reasons"},{"it":"Per renderlo più difficile","en":"To make it harder"}]',0,'{"it":"Blocchi più facili da tenere a mente.","en":"Blocks easier to hold in mind."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'metrics'),1,3,'{"it":"Che cosa misura la R di HEART?","en":"What does the R in HEART measure?"}','[{"it":"Quanti utenti tornano","en":"How many users come back"},{"it":"Le recensioni negative","en":"Negative reviews"},{"it":"La velocità di risposta","en":"Response speed"},{"it":"I ricavi pubblicitari","en":"Ad revenue"}]',0,'{"it":"Retention.","en":"Retention."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'metrics'),2,3,'{"it":"A che cosa serve un funnel?","en":"What is a funnel for?"}','[{"it":"Trovare il passo dove si perdono più utenti","en":"Finding the step where most users drop"},{"it":"Filtrare il caffè","en":"Filtering coffee"},{"it":"Contare i pixel","en":"Counting pixels"},{"it":"Ordinare i prodotti","en":"Sorting products"}]',0,'{"it":"Il calo più forte.","en":"The biggest drop."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'metrics'),3,3,'{"it":"Che cosa serve a un A/B test affidabile?","en":"What does a reliable A/B test need?"}','[{"it":"Ipotesi chiara e abbastanza utenti","en":"A clear hypothesis and enough users"},{"it":"Tante metriche scelte dopo il test","en":"Many metrics chosen after the test"},{"it":"Due utenti per gruppo","en":"Two users per group"},{"it":"Fermarlo appena vince una versione","en":"Stopping as soon as one version wins"}]',0,'{"it":"Niente risultati per caso.","en":"No results by chance."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'ethics'),1,3,'{"it":"Che cos’è il confirmshaming?","en":"What is confirmshaming?"}','[{"it":"Colpevolizzare chi rifiuta un’offerta","en":"Guilt-tripping people who decline an offer"},{"it":"Confermare un ordine due volte","en":"Confirming an order twice"},{"it":"Un messaggio di benvenuto","en":"A welcome message"},{"it":"Un tipo di captcha","en":"A kind of captcha"}]',0,'{"it":"“No grazie, odio risparmiare”.","en":"“No thanks, I hate saving”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'ethics'),2,3,'{"it":"Che cos’è il roach motel?","en":"What is the roach motel?"}','[{"it":"Facile entrare, difficile uscire","en":"Easy to get in, hard to get out"},{"it":"Un hotel per sviluppatori","en":"A hotel for developers"},{"it":"Una pagina 404 simpatica","en":"A funny 404 page"},{"it":"Un menu a scomparsa","en":"A collapsing menu"}]',0,'{"it":"Abbonamenti trappola.","en":"Trap subscriptions."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'ethics'),3,3,'{"it":"Che cosa dice il GDPR sulle caselle di consenso?","en":"What does the GDPR say about consent boxes?"}','[{"it":"Non devono essere già spuntate","en":"They must not be pre-ticked"},{"it":"Devono essere già spuntate","en":"They must be pre-ticked"},{"it":"Devono essere nascoste","en":"They must be hidden"},{"it":"Non dice nulla","en":"It says nothing"}]',0,'{"it":"Consenso libero e attivo.","en":"Free, active consent."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'service'),1,3,'{"it":"Che cosa separa la linea di visibilità in un blueprint?","en":"What does the line of visibility separate in a blueprint?"}','[{"it":"Ciò che l’utente vede da ciò che non vede","en":"What the user sees from what they do not"},{"it":"Il desktop dal mobile","en":"Desktop from mobile"},{"it":"I colori chiari da quelli scuri","en":"Light colours from dark ones"},{"it":"Il prezzo dal costo","en":"Price from cost"}]',0,'{"it":"Front stage e back stage.","en":"Front stage and back stage."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'service'),2,3,'{"it":"Che cosa guarda il service design?","en":"What does service design look at?"}','[{"it":"Persone, processi e sistemi oltre lo schermo","en":"People, processes and systems beyond the screen"},{"it":"Solo l’interfaccia dell’app","en":"Only the app interface"},{"it":"Solo il logo","en":"Only the logo"},{"it":"Solo il codice","en":"Only the code"}]',0,'{"it":"L’esperienza intera.","en":"The whole experience."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'service'),3,3,'{"it":"Che cosa significa ricerca continua?","en":"What does continuous research mean?"}','[{"it":"Parlare con gli utenti regolarmente","en":"Talking to users regularly"},{"it":"Una grande ricerca all’anno","en":"One big study a year"},{"it":"Leggere solo le recensioni","en":"Only reading reviews"},{"it":"Chiedere al team","en":"Asking the team"}]',0,'{"it":"Ogni settimana, poco alla volta.","en":"Every week, a little at a time."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'inclusive'),1,3,'{"it":"Che esempio è “un neonato in braccio”?","en":"What kind of example is “holding a baby”?"}','[{"it":"Disabilità situazionale","en":"Situational disability"},{"it":"Disabilità permanente","en":"Permanent disability"},{"it":"Nessun limite","en":"No limit"},{"it":"Un bug","en":"A bug"}]',0,'{"it":"Una mano sola per un momento.","en":"One hand for a moment."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'inclusive'),2,3,'{"it":"Perché i sottotitoli aiutano tutti?","en":"Why do subtitles help everyone?"}','[{"it":"Servono anche in luoghi rumorosi o silenziosi","en":"They help in noisy or quiet places too"},{"it":"Rendono il video più corto","en":"They make video shorter"},{"it":"Migliorano i colori","en":"They improve colours"},{"it":"Non aiutano tutti","en":"They do not help everyone"}]',0,'{"it":"Il limite estremo migliora il comune.","en":"The extreme improves the common."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'inclusive'),3,3,'{"it":"Che cosa evitare?","en":"What should you avoid?"}','[{"it":"Informazioni affidate solo al colore","en":"Information conveyed by colour only"},{"it":"Testi alternativi","en":"Alternative text"},{"it":"Più modi di agire","en":"Several ways to act"},{"it":"Ricerca con persone diverse","en":"Research with diverse people"}]',0,'{"it":"Aggiungi testo o icone.","en":"Add text or icons."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'ai-ux'),1,3,'{"it":"Che cos’è la fiducia calibrata?","en":"What is calibrated trust?"}','[{"it":"Fidarsi sempre di ciò che dice l’IA","en":"Always trusting what the AI says"},{"it":"Non fidarsi mai di un’IA","en":"Never trusting an AI"},{"it":"Fidarsi quanto il sistema merita davvero","en":"Trusting as much as the system really deserves"},{"it":"Una misura della velocità del modello","en":"A measure of the model’s speed"}]',2,'{"it":"Né cieca né nulla.","en":"Neither blind nor absent."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'ai-ux'),2,3,'{"it":"Che cosa deve succedere prima che un assistente IA invii un’email per l’utente?","en":"What should happen before an AI assistant sends an email for the user?"}','[{"it":"Niente, conta la velocità","en":"Nothing, speed matters"},{"it":"L’utente la rivede e conferma","en":"The user reviews and confirms it"},{"it":"Lo decide l’IA da sola","en":"The AI decides on its own"},{"it":"Si invia e poi si avvisa","en":"It is sent and the user told later"}]',1,'{"it":"Human in the loop.","en":"Human in the loop."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'ai-ux'),3,3,'{"it":"Perché mostrare le fonti di una risposta generata?","en":"Why show the sources of a generated answer?"}','[{"it":"Per riempire lo spazio vuoto","en":"To fill empty space"},{"it":"Per nascondere gli errori","en":"To hide mistakes"},{"it":"Perché ogni testo lo richiede","en":"Because every text requires it"},{"it":"Per permettere di verificare","en":"To allow checking"}]',3,'{"it":"La verifica calibra la fiducia.","en":"Checking calibrates trust."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'influence'),1,3,'{"it":"Qual è un buon modo per coinvolgere gli stakeholder?","en":"What is a good way to involve stakeholders?"}','[{"it":"Mandare un report di 80 pagine alla fine","en":"Sending an 80-page report at the end"},{"it":"Invitarli a osservare i test dal vivo","en":"Inviting them to watch tests live"},{"it":"Mostrare i risultati solo al team di design","en":"Showing results only to the design team"},{"it":"Chiedere solo un’approvazione finale","en":"Asking only for a final sign-off"}]',1,'{"it":"Vedere un utente in difficoltà convince più di un grafico.","en":"Seeing a user struggle convinces more than a chart."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'influence'),2,3,'{"it":"Come si calcola il punteggio RICE?","en":"How is the RICE score calculated?"}','[{"it":"Portata + impatto + fiducia + sforzo","en":"Reach + impact + confidence + effort"},{"it":"Sforzo ÷ portata","en":"Effort ÷ reach"},{"it":"Impatto × sforzo","en":"Impact × effort"},{"it":"Portata × impatto × fiducia ÷ sforzo","en":"Reach × impact × confidence ÷ effort"}]',3,'{"it":"Lo sforzo divide, il resto moltiplica.","en":"Effort divides, the rest multiplies."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-advanced' AND slug = 'influence'),3,3,'{"it":"Come si racconta il ROI della UX?","en":"How do you tell the ROI of UX?"}','[{"it":"Con il numero di schermate disegnate","en":"With the number of screens drawn"},{"it":"Con le ore di lavoro del team","en":"With the team’s working hours"},{"it":"Con il prima e il dopo su metriche concrete","en":"With before and after on concrete metrics"},{"it":"Con i premi di design vinti","en":"With design awards won"}]',2,'{"it":"Risultati, non attività.","en":"Outcomes, not activities."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'context'),1,2,'{"it":"Com’è tipicamente una sessione su mobile?","en":"What is a typical mobile session like?"}','[{"it":"Breve, in movimento, con distrazioni","en":"Short, on the move, with distractions"},{"it":"Lunga e alla scrivania","en":"Long and at a desk"},{"it":"Sempre con il Wi-Fi veloce","en":"Always on fast Wi-Fi"},{"it":"Sempre con due mani libere","en":"Always with both hands free"}]',0,'{"it":"Il contesto conta.","en":"Context matters."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'context'),2,2,'{"it":"Che cosa significa mobile first?","en":"What does mobile first mean?"}','[{"it":"Progettare prima per lo schermo piccolo","en":"Designing for the small screen first"},{"it":"Fare solo la app, mai il sito","en":"Making only the app, never the site"},{"it":"Togliere pezzi al sito desktop","en":"Cutting pieces off the desktop site"},{"it":"Usare solo telefoni nuovi","en":"Using only new phones"}]',0,'{"it":"Obbliga a scegliere l’essenziale.","en":"It forces choosing the essential."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'context'),3,2,'{"it":"Quale stato va progettato anche su mobile?","en":"Which state should also be designed on mobile?"}','[{"it":"Offline e rete lenta","en":"Offline and slow network"},{"it":"Solo il caso perfetto","en":"Only the perfect case"},{"it":"Solo la modalità aereo dei piloti","en":"Only pilots’ aeroplane mode"},{"it":"Nessuno","en":"None"}]',0,'{"it":"Il mondo reale è imperfetto.","en":"The real world is imperfect."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'touch'),1,2,'{"it":"Quale zona dello schermo è più comoda per il pollice?","en":"Which screen area is most comfortable for the thumb?"}','[{"it":"In basso al centro","en":"Lower centre"},{"it":"In alto a sinistra","en":"Top left"},{"it":"In alto a destra","en":"Top right"},{"it":"Tutte allo stesso modo","en":"All equally"}]',0,'{"it":"Lì vanno le azioni principali.","en":"Main actions go there."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'touch'),2,2,'{"it":"Quanto deve essere grande almeno un target touch secondo Material?","en":"How big must a touch target be at least per Material?"}','[{"it":"48×48 dp","en":"48×48 dp"},{"it":"16×16 dp","en":"16×16 dp"},{"it":"24×24 dp","en":"24×24 dp"},{"it":"100×100 dp","en":"100×100 dp"}]',0,'{"it":"Apple indica 44×44 punti.","en":"Apple says 44×44 points."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'touch'),3,2,'{"it":"Perché non affidarsi all’hover su mobile?","en":"Why not rely on hover on mobile?"}','[{"it":"Sul touch l’hover non esiste","en":"Hover does not exist on touch"},{"it":"Rallenta il telefono","en":"It slows the phone"},{"it":"È vietato dagli store","en":"Stores forbid it"},{"it":"Consuma batteria","en":"It drains battery"}]',0,'{"it":"Il dito tocca, non sorvola.","en":"A finger taps, it does not hover."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'navigation'),1,2,'{"it":"Quante voci ha di solito una tab bar?","en":"How many items does a tab bar usually have?"}','[{"it":"Da 3 a 5","en":"3 to 5"},{"it":"Da 8 a 12","en":"8 to 12"},{"it":"Una sola","en":"Just one"},{"it":"Più di 20","en":"More than 20"}]',0,'{"it":"Poche e sempre visibili.","en":"Few and always visible."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'navigation'),2,2,'{"it":"Qual è il limite del menu hamburger?","en":"What is the hamburger menu’s limit?"}','[{"it":"Nasconde le voci, che si usano meno","en":"It hides items, which get used less"},{"it":"È troppo colorato","en":"It is too colourful"},{"it":"Non funziona su Android","en":"It does not work on Android"},{"it":"Occupa tutto lo schermo sempre","en":"It always fills the screen"}]',0,'{"it":"Lontano dagli occhi…","en":"Out of sight…"}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'navigation'),3,2,'{"it":"Che cosa serve a ogni gesto personalizzato?","en":"What does every custom gesture need?"}','[{"it":"Un’alternativa visibile","en":"A visible alternative"},{"it":"Un suono","en":"A sound"},{"it":"Una vibrazione forte","en":"A strong vibration"},{"it":"Un tutorial di dieci pagine","en":"A ten-page tutorial"}]',0,'{"it":"I gesti non si vedono.","en":"Gestures are invisible."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'forms'),1,2,'{"it":"Quale attributo mostra la tastiera numerica?","en":"Which attribute shows the numeric keypad?"}','[{"it":"inputmode=\\"numeric\\"","en":"inputmode=\\"numeric\\""},{"it":"type=\\"text\\"","en":"type=\\"text\\""},{"it":"lang=\\"num\\"","en":"lang=\\"num\\""},{"it":"role=\\"number\\"","en":"role=\\"number\\""}]',0,'{"it":"Anche type=\\"tel\\" per i telefoni.","en":"Also type=\\"tel\\" for phones."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'forms'),2,2,'{"it":"Quando chiedere il permesso della posizione?","en":"When to ask for location permission?"}','[{"it":"Quando serve e se ne capisce il motivo","en":"When needed and its reason is clear"},{"it":"Appena si apre l’app","en":"As soon as the app opens"},{"it":"Mai, si attiva da sola","en":"Never, it turns on by itself"},{"it":"Dopo l’acquisto","en":"After purchase"}]',0,'{"it":"Contesto prima della richiesta.","en":"Context before the request."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'forms'),3,2,'{"it":"Che rischio hanno troppe notifiche?","en":"What is the risk of too many notifications?"}','[{"it":"Vengono disattivate o l’app disinstallata","en":"They get turned off or the app uninstalled"},{"it":"Il telefono si rompe","en":"The phone breaks"},{"it":"Migliora la retention","en":"Retention improves"},{"it":"Nessuno","en":"None"}]',0,'{"it":"Poche e utili.","en":"Few and useful."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'performance'),1,3,'{"it":"Che cos’è uno skeleton?","en":"What is a skeleton?"}','[{"it":"La sagoma della pagina mentre carica","en":"The page outline while loading"},{"it":"Un errore","en":"An error"},{"it":"Un font","en":"A font"},{"it":"Un’animazione di festa","en":"A celebration animation"}]',0,'{"it":"Sembra già quasi pronta.","en":"It already looks almost ready."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'performance'),2,3,'{"it":"Che cosa fa un aggiornamento ottimistico?","en":"What does an optimistic update do?"}','[{"it":"Mostra subito il risultato e lo annulla se fallisce","en":"Shows the result at once and undoes it if it fails"},{"it":"Aspetta sempre il server","en":"Always waits for the server"},{"it":"Ignora gli errori","en":"Ignores errors"},{"it":"Ricarica la pagina","en":"Reloads the page"}]',0,'{"it":"Reattività percepita.","en":"Perceived responsiveness."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'performance'),3,3,'{"it":"Come gestisci un’azione fatta offline?","en":"How do you handle an action done offline?"}','[{"it":"La metti in coda e la invii dopo","en":"Queue it and send it later"},{"it":"La cancelli","en":"Delete it"},{"it":"Blocchi l’app","en":"Block the app"},{"it":"Mostri un errore e basta","en":"Just show an error"}]',0,'{"it":"Nulla va perso.","en":"Nothing is lost."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'accessibility'),1,3,'{"it":"Come si chiama il lettore di schermo di Android?","en":"What is Android’s screen reader called?"}','[{"it":"VoiceOver","en":"VoiceOver"},{"it":"Assistente vocale","en":"Narrator"},{"it":"TalkBack","en":"TalkBack"},{"it":"Siri","en":"Siri"}]',2,'{"it":"VoiceOver è quello di iOS.","en":"VoiceOver is the iOS one."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'accessibility'),2,3,'{"it":"Che cosa serve a un pulsante con solo un’icona?","en":"What does an icon-only button need?"}','[{"it":"Un colore più acceso","en":"A brighter colour"},{"it":"Un’etichetta che dica che cosa fa","en":"A label saying what it does"},{"it":"Un’animazione al tocco","en":"An animation on tap"},{"it":"Un bordo più spesso","en":"A thicker border"}]',1,'{"it":"Il lettore di schermo legge l’etichetta.","en":"The screen reader reads the label."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'accessibility'),3,3,'{"it":"Che cosa chiedono le WCAG per un’azione che si fa trascinando?","en":"What does WCAG ask for an action done by dragging?"}','[{"it":"Niente di particolare","en":"Nothing in particular"},{"it":"Un suono di conferma","en":"A confirmation sound"},{"it":"Di toglierla dall’app","en":"Removing it from the app"},{"it":"Un’alternativa senza trascinamento","en":"An alternative without dragging"}]',3,'{"it":"Per esempio pulsanti su e giù per riordinare.","en":"For example up and down buttons to reorder."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'beyond'),1,3,'{"it":"Quanto dura di solito un’interazione con lo smartwatch?","en":"How long does a smartwatch interaction usually last?"}','[{"it":"Mezz’ora","en":"Half an hour"},{"it":"Pochi secondi","en":"A few seconds"},{"it":"Un’ora","en":"An hour"},{"it":"Tutta la giornata","en":"All day"}]',1,'{"it":"A colpo d’occhio.","en":"At a glance."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'beyond'),2,3,'{"it":"Che cosa evitare in un’app per l’auto durante la guida?","en":"What should a car app avoid while driving?"}','[{"it":"I comandi vocali","en":"Voice commands"},{"it":"Le icone grandi","en":"Large icons"},{"it":"Testi lunghi e tastiera","en":"Long text and the keyboard"},{"it":"Pochi elementi per schermata","en":"Few elements per screen"}]',2,'{"it":"Occhi sulla strada.","en":"Eyes on the road."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-mobile' AND slug = 'beyond'),3,3,'{"it":"Che cosa deve fare un’interfaccia vocale dopo un comando?","en":"What should a voice interface do after a command?"}','[{"it":"Confermare che cosa ha capito","en":"Confirm what it understood"},{"it":"Restare in silenzio","en":"Stay silent"},{"it":"Elencare venti opzioni","en":"List twenty options"},{"it":"Chiedere la password","en":"Ask for the password"}]',0,'{"it":"E permettere di correggere.","en":"And allow corrections."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'layout'),1,2,'{"it":"Che cos’è lo schema lista-dettaglio?","en":"What is the list-detail pattern?"}','[{"it":"Una lista e accanto il dettaglio dell’elemento scelto","en":"A list with the chosen item’s detail beside it"},{"it":"Una lista della spesa","en":"A shopping list"},{"it":"Un menu a tendina","en":"A dropdown menu"},{"it":"Una sola colonna centrata","en":"A single centred column"}]',0,'{"it":"Come le app di posta.","en":"Like email apps."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'layout'),2,2,'{"it":"Quanti caratteri per riga si leggono meglio?","en":"How many characters per line read best?"}','[{"it":"Circa 60-80","en":"About 60-80"},{"it":"Circa 200","en":"About 200"},{"it":"Meno di 10","en":"Fewer than 10"},{"it":"Tutta la larghezza dello schermo","en":"The full screen width"}]',0,'{"it":"Righe troppo lunghe stancano.","en":"Lines too long tire the eye."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'layout'),3,2,'{"it":"Quando ha senso una densità compatta?","en":"When does compact density make sense?"}','[{"it":"In app per professionisti con molti dati","en":"In professional apps with lots of data"},{"it":"Sempre, per tutti","en":"Always, for everyone"},{"it":"Mai su desktop","en":"Never on desktop"},{"it":"Solo nei giochi","en":"Only in games"}]',0,'{"it":"La densità segue l’uso.","en":"Density follows use."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'pointer'),1,2,'{"it":"Che cosa non va mai nascosto solo dietro l’hover?","en":"What should never be hidden only behind hover?"}','[{"it":"Le azioni essenziali","en":"Essential actions"},{"it":"Le decorazioni","en":"Decorations"},{"it":"Le ombre","en":"Shadows"},{"it":"Le animazioni","en":"Animations"}]',0,'{"it":"Tastiera e touch non hanno hover.","en":"Keyboard and touch have no hover."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'pointer'),2,2,'{"it":"Che cosa apre il clic destro?","en":"What does right-click open?"}','[{"it":"Il menu contestuale","en":"The context menu"},{"it":"Il browser","en":"The browser"},{"it":"Le impostazioni di sistema","en":"System settings"},{"it":"Una nuova finestra sempre","en":"A new window, always"}]',0,'{"it":"Azioni sull’elemento.","en":"Actions on the item."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'pointer'),3,2,'{"it":"Che cosa serve per un buon drag and drop?","en":"What does good drag and drop need?"}','[{"it":"Mostrare dove rilasciare e poter annullare","en":"Showing where to drop and allowing undo"},{"it":"Nessuna indicazione visiva","en":"No visual cues"},{"it":"Un tempo limite","en":"A time limit"},{"it":"Il doppio clic","en":"A double-click"}]',0,'{"it":"Feedback e sicurezza.","en":"Feedback and safety."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'keyboard'),1,2,'{"it":"Quale tasto chiude di solito una finestra di dialogo?","en":"Which key usually closes a dialog?"}','[{"it":"Esc","en":"Esc"},{"it":"Tab","en":"Tab"},{"it":"Shift","en":"Shift"},{"it":"F5","en":"F5"}]',0,'{"it":"Una convenzione universale.","en":"A universal convention."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'keyboard'),2,2,'{"it":"Che cos’è una command palette?","en":"What is a command palette?"}','[{"it":"Una ricerca di comandi da tastiera","en":"A keyboard command search"},{"it":"Una tavolozza di colori","en":"A colour palette"},{"it":"Un menu a icone","en":"An icon menu"},{"it":"Un tipo di grafico","en":"A kind of chart"}]',0,'{"it":"Spesso con Ctrl/Cmd+K.","en":"Often with Ctrl/Cmd+K."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'keyboard'),3,2,'{"it":"Perché mostrare le scorciatoie accanto alle voci di menu?","en":"Why show shortcuts next to menu items?"}','[{"it":"Perché gli utenti le imparino","en":"So users learn them"},{"it":"Per riempire lo spazio","en":"To fill space"},{"it":"Per obbligo di legge","en":"By legal obligation"},{"it":"Per nasconderle","en":"To hide them"}]',0,'{"it":"Dal menu alla velocità.","en":"From menu to speed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'windows'),1,2,'{"it":"A quali finestre deve adattarsi il layout desktop?","en":"Which windows should a desktop layout adapt to?"}','[{"it":"Anche a quelle strette e affiancate","en":"Also narrow, side-by-side ones"},{"it":"Solo a schermo intero","en":"Only full screen"},{"it":"Solo a 1920 pixel","en":"Only 1920 pixels"},{"it":"A nessuna","en":"None"}]',0,'{"it":"Il multitasking stringe le finestre.","en":"Multitasking narrows windows."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'windows'),2,2,'{"it":"Come gestire un’esportazione lunga?","en":"How to handle a long export?"}','[{"it":"In background con avanzamento visibile","en":"In the background with visible progress"},{"it":"Bloccando tutta l’app","en":"Blocking the whole app"},{"it":"Senza dire nulla","en":"Without saying anything"},{"it":"Chiedendo di non toccare il mouse","en":"Asking not to touch the mouse"}]',0,'{"it":"L’utente continua a lavorare.","en":"The user keeps working."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'windows'),3,2,'{"it":"Perché il salvataggio automatico?","en":"Why autosave?"}','[{"it":"Il lavoro viene spesso interrotto","en":"Work is often interrupted"},{"it":"Per occupare disco","en":"To use disk space"},{"it":"Per rallentare l’app","en":"To slow the app"},{"it":"Non serve","en":"It is not needed"}]',0,'{"it":"Niente lavoro perso.","en":"No lost work."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'data'),1,3,'{"it":"Come si allineano i numeri in una tabella?","en":"How are numbers aligned in a table?"}','[{"it":"A destra","en":"Right"},{"it":"A sinistra","en":"Left"},{"it":"Al centro","en":"Centre"},{"it":"A caso","en":"Randomly"}]',0,'{"it":"Così le cifre si confrontano.","en":"So digits line up."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'data'),2,3,'{"it":"Perché preferire Annulla a “Sei sicuro?”","en":"Why prefer Undo to “Are you sure?”"}','[{"it":"La conferma si clicca per abitudine","en":"Confirmation gets clicked out of habit"},{"it":"Annulla è più bello","en":"Undo is prettier"},{"it":"Le conferme sono vietate","en":"Confirmations are forbidden"},{"it":"Non c’è differenza","en":"There is no difference"}]',0,'{"it":"L’annulla rimedia davvero.","en":"Undo really fixes it."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'data'),3,3,'{"it":"Come selezioni un intervallo di righe?","en":"How do you select a range of rows?"}','[{"it":"Clic, poi Maiusc+clic","en":"Click, then Shift+click"},{"it":"Doppio clic","en":"Double-click"},{"it":"Tasto destro","en":"Right-click"},{"it":"Trascinando la finestra","en":"Dragging the window"}]',0,'{"it":"Ctrl/Cmd per righe sparse.","en":"Ctrl/Cmd for scattered rows."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'learning'),1,3,'{"it":"Che cos’è la divulgazione progressiva?","en":"What is progressive disclosure?"}','[{"it":"Mostrare tutte le funzioni subito","en":"Showing every feature at once"},{"it":"Mostrare l’essenziale e rivelare il resto quando serve","en":"Showing the essentials and revealing the rest when needed"},{"it":"Nascondere per sempre le funzioni avanzate","en":"Hiding advanced features forever"},{"it":"Un tutorial obbligatorio all’avvio","en":"A mandatory tutorial at launch"}]',1,'{"it":"Semplice per chi inizia, completo per chi è esperto.","en":"Simple for beginners, complete for experts."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'learning'),2,3,'{"it":"Perché offrire modelli e progetti di esempio?","en":"Why offer templates and sample projects?"}','[{"it":"Per occupare spazio su disco","en":"To take up disk space"},{"it":"Per imporre uno stile unico","en":"To impose a single style"},{"it":"Per non partire dal foglio bianco","en":"So nobody starts from a blank page"},{"it":"Per vendere più licenze","en":"To sell more licences"}]',2,'{"it":"Si impara modificando.","en":"You learn by editing."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'learning'),3,3,'{"it":"Che problema hanno i tour obbligatori lunghi?","en":"What is the problem with long mandatory tours?"}','[{"it":"Sono troppo brevi","en":"They are too short"},{"it":"Funzionano solo su Mac","en":"They only work on Mac"},{"it":"Insegnano troppo in fretta","en":"They teach too quickly"},{"it":"Si saltano e si dimenticano","en":"People skip and forget them"}]',3,'{"it":"Meglio aiutare nel momento giusto.","en":"Better to help at the right moment."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'web-native'),1,3,'{"it":"Che cos’è una PWA?","en":"What is a PWA?"}','[{"it":"Un linguaggio di programmazione","en":"A programming language"},{"it":"Un tipo di monitor","en":"A kind of monitor"},{"it":"Una web app installabile che può funzionare offline","en":"An installable web app that can work offline"},{"it":"Un plugin di un programma di grafica","en":"A plug-in for a graphics program"}]',2,'{"it":"Progressive Web App.","en":"Progressive Web App."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'web-native'),2,3,'{"it":"Che cosa usa un’app ibrida fatta con Electron?","en":"What does a hybrid app built with Electron use?"}','[{"it":"Tecnologie web dentro una finestra nativa","en":"Web technologies inside a native window"},{"it":"Solo codice assembly","en":"Only assembly code"},{"it":"Solo il terminale","en":"Only the terminal"},{"it":"Un emulatore Android","en":"An Android emulator"}]',0,'{"it":"Come Visual Studio Code.","en":"Like Visual Studio Code."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-desktop' AND slug = 'web-native'),3,3,'{"it":"Che cosa deve offrire una web app installata, senza la barra del browser?","en":"What must an installed web app offer, without the browser bar?"}','[{"it":"Più pubblicità","en":"More advertising"},{"it":"Un suo indietro e link condivisibili","en":"Its own back button and shareable links"},{"it":"Solo il tema scuro","en":"Only a dark theme"},{"it":"Una finestra più piccola","en":"A smaller window"}]',1,'{"it":"Il browser non c’è più ad aiutare.","en":"The browser is no longer there to help."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'presence'),1,3,'{"it":"Che differenza c’è tra VR e AR?","en":"What is the difference between VR and AR?"}','[{"it":"La VR sostituisce il mondo, l’AR lo arricchisce","en":"VR replaces the world, AR enriches it"},{"it":"Sono la stessa cosa","en":"They are the same"},{"it":"L’AR richiede sempre un visore","en":"AR always requires a headset"},{"it":"La VR funziona solo all’aperto","en":"VR works only outdoors"}]',0,'{"it":"Sostituire o aggiungere.","en":"Replace or add."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'presence'),2,3,'{"it":"Che cos’è la presenza?","en":"What is presence?"}','[{"it":"La sensazione di essere davvero lì","en":"The feeling of really being there"},{"it":"Il numero di utenti online","en":"The number of online users"},{"it":"La batteria del visore","en":"The headset battery"},{"it":"Un tipo di controller","en":"A kind of controller"}]',0,'{"it":"Fragile e preziosa.","en":"Fragile and precious."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'presence'),3,3,'{"it":"Che cosa rompe la presenza?","en":"What breaks presence?"}','[{"it":"Latenza e frame rate basso","en":"Latency and low frame rate"},{"it":"Un buon audio spaziale","en":"Good spatial audio"},{"it":"Mani tracciate bene","en":"Well-tracked hands"},{"it":"Ombre realistiche","en":"Realistic shadows"}]',0,'{"it":"Le prestazioni sono UX.","en":"Performance is UX."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'comfort'),1,3,'{"it":"Da che cosa nasce la chinetosi in VR?","en":"What causes motion sickness in VR?"}','[{"it":"Gli occhi vedono movimento, il corpo no","en":"Eyes see motion, the body does not"},{"it":"Dal volume troppo alto","en":"From volume too high"},{"it":"Dai colori troppo vivaci","en":"From colours too bright"},{"it":"Dal visore troppo leggero","en":"From a headset too light"}]',0,'{"it":"Un conflitto dei sensi.","en":"A sensory conflict."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'comfort'),2,3,'{"it":"Quale locomozione è più comoda per molti utenti?","en":"Which locomotion is more comfortable for many users?"}','[{"it":"Il teletrasporto","en":"Teleportation"},{"it":"Il movimento fluido veloce","en":"Fast smooth movement"},{"it":"Le montagne russe automatiche","en":"Automatic roller coasters"},{"it":"La rotazione continua della telecamera","en":"Continuous camera rotation"}]',0,'{"it":"Niente accelerazioni percepite.","en":"No perceived acceleration."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'comfort'),3,3,'{"it":"Che cos’è il braccio da gorilla?","en":"What is gorilla arm?"}','[{"it":"La fatica di tenere le braccia alzate","en":"The fatigue of holding arms up"},{"it":"Un avatar scimmia","en":"A monkey avatar"},{"it":"Un controller grande","en":"A big controller"},{"it":"Un gesto di vittoria","en":"A victory gesture"}]',0,'{"it":"Interfacce in basso e vicine.","en":"Interfaces low and close."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'spatial'),1,3,'{"it":"Dove posizionare un pannello di testo in VR?","en":"Where to place a text panel in VR?"}','[{"it":"A 1-3 metri, nel campo visivo centrale","en":"At 1-3 metres, in the central field of view"},{"it":"Incollato agli occhi","en":"Glued to the eyes"},{"it":"Dietro l’utente","en":"Behind the user"},{"it":"In un angolo in alto","en":"In a top corner"}]',0,'{"it":"Comodo da leggere.","en":"Comfortable to read."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'spatial'),2,3,'{"it":"Che cos’è un’interfaccia diegetica?","en":"What is a diegetic interface?"}','[{"it":"Un’interfaccia che fa parte del mondo","en":"An interface that is part of the world"},{"it":"Un menu di pausa","en":"A pause menu"},{"it":"Un HUD fisso","en":"A fixed HUD"},{"it":"Un sottotitolo","en":"A subtitle"}]',0,'{"it":"Come un orologio al polso.","en":"Like a watch on the wrist."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'spatial'),3,3,'{"it":"A che cosa serve l’audio spaziale?","en":"What is spatial audio for?"}','[{"it":"Guidare l’attenzione fuori dalla vista","en":"Guiding attention out of view"},{"it":"Risparmiare batteria","en":"Saving battery"},{"it":"Sostituire i testi","en":"Replacing text"},{"it":"Nulla","en":"Nothing"}]',0,'{"it":"Il suono indica la direzione.","en":"Sound points the way."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'input'),1,3,'{"it":"Come si interagisce con un oggetto lontano?","en":"How do you interact with a distant object?"}','[{"it":"Puntandolo con un raggio","en":"Pointing at it with a ray"},{"it":"Camminando per chilometri","en":"Walking for kilometres"},{"it":"Non si può","en":"You cannot"},{"it":"Solo a voce, sempre","en":"Only by voice, always"}]',0,'{"it":"Vicino si tocca, lontano si punta.","en":"Near you touch, far you point."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'input'),2,3,'{"it":"Che cos’è il problema del Re Mida con lo sguardo?","en":"What is the Midas touch problem with gaze?"}','[{"it":"Si attiva tutto ciò che si guarda","en":"Everything you look at activates"},{"it":"Gli oggetti diventano d’oro","en":"Objects turn to gold"},{"it":"Lo sguardo non viene tracciato","en":"Gaze is not tracked"},{"it":"Il visore si scarica","en":"The headset runs flat"}]',0,'{"it":"Serve una conferma.","en":"A confirmation is needed."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'input'),3,3,'{"it":"Che cosa manca alle mani tracciate rispetto ai controller?","en":"What do tracked hands lack compared to controllers?"}','[{"it":"Il feedback tattile","en":"Tactile feedback"},{"it":"La naturalezza","en":"Naturalness"},{"it":"Le dita","en":"Fingers"},{"it":"Il colore","en":"Colour"}]',0,'{"it":"Il feedback arriva da vista e suono.","en":"Feedback comes from sight and sound."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'onboarding'),1,3,'{"it":"Come si insegnano i gesti al primo accesso?","en":"How are gestures taught on first run?"}','[{"it":"Uno alla volta, provandoli subito","en":"One at a time, trying them right away"},{"it":"Tutti in un video lungo","en":"All in a long video"},{"it":"In un manuale PDF","en":"In a PDF manual"},{"it":"Non si insegnano","en":"They are not taught"}]',0,'{"it":"Imparare facendo.","en":"Learning by doing."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'onboarding'),2,3,'{"it":"Quale è una scelta accessibile in VR?","en":"Which is an accessible choice in VR?"}','[{"it":"Una modalità seduta","en":"A seated mode"},{"it":"Solo comandi a due mani","en":"Two-handed controls only"},{"it":"Movimento fluido obbligatorio","en":"Mandatory smooth movement"},{"it":"Nessun sottotitolo","en":"No subtitles"}]',0,'{"it":"Non tutti possono stare in piedi.","en":"Not everyone can stand."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'onboarding'),3,3,'{"it":"Come devono essere le sessioni di test?","en":"How should test sessions be?"}','[{"it":"Brevi, osservando il malessere","en":"Short, watching for discomfort"},{"it":"Lunghe ore senza pause","en":"Long hours without breaks"},{"it":"Senza visore","en":"Without a headset"},{"it":"Solo con questionari","en":"Only with questionnaires"}]',0,'{"it":"Il comfort prima di tutto.","en":"Comfort first."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'platforms'),1,3,'{"it":"Che cos’è un volume in visionOS?","en":"What is a volume in visionOS?"}','[{"it":"Una finestra 2D di vetro","en":"A 2D glass window"},{"it":"Un contenuto 3D da osservare da ogni lato","en":"A 3D content you view from every side"},{"it":"Il livello dell’audio spaziale","en":"The spatial audio level"},{"it":"Uno spazio vuoto tra le finestre","en":"An empty space between windows"}]',1,'{"it":"Finestre, volumi, spazi.","en":"Windows, volumes, spaces."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'platforms'),2,3,'{"it":"Quale area minima chiede visionOS per un elemento da guardare?","en":"What minimum area does visionOS ask for an element to look at?"}','[{"it":"20 punti","en":"20 points"},{"it":"44 punti","en":"44 points"},{"it":"60 punti","en":"60 points"},{"it":"200 punti","en":"200 points"}]',2,'{"it":"Gli occhi sono meno precisi di un dito.","en":"Eyes are less precise than a finger."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'platforms'),3,3,'{"it":"Che cos’è un orbiter in Android XR?","en":"What is an orbiter in Android XR?"}','[{"it":"Un satellite per il GPS","en":"A GPS satellite"},{"it":"Un modello di visore","en":"A headset model"},{"it":"Una modalità a tutto schermo","en":"A full-screen mode"},{"it":"Controlli che fluttuano accanto a un pannello","en":"Controls floating next to a panel"}]',3,'{"it":"Simile agli ornament di visionOS.","en":"Similar to visionOS ornaments."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'social'),1,3,'{"it":"Che cos’è la bolla personale?","en":"What is a personal boundary?"}','[{"it":"Un effetto grafico decorativo","en":"A decorative graphic effect"},{"it":"Uno spazio intorno a te in cui gli altri non possono entrare","en":"A space around you others cannot enter"},{"it":"Una chat privata","en":"A private chat"},{"it":"Un tipo di visore","en":"A kind of headset"}]',1,'{"it":"Distanza garantita dagli altri avatar.","en":"Guaranteed distance from other avatars."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'social'),2,3,'{"it":"Che cos’è la uncanny valley?","en":"What is the uncanny valley?"}','[{"it":"Una mappa di un gioco","en":"A game map"},{"it":"Una zona senza segnale","en":"An area with no signal"},{"it":"Il disagio davanti a figure quasi umane ma innaturali","en":"The unease before almost-human but unnatural figures"},{"it":"Una tecnica di locomozione","en":"A locomotion technique"}]',2,'{"it":"Meglio uno stile semplice che un realismo rigido.","en":"A simple style beats stiff realism."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ux-vr' AND slug = 'social'),3,3,'{"it":"Perché i dati raccolti da un visore sono sensibili?","en":"Why is the data collected by a headset sensitive?"}','[{"it":"Sono pochissimi","en":"There is very little of it"},{"it":"Sono sempre pubblici","en":"It is always public"},{"it":"Occupano molto spazio","en":"It takes up a lot of space"},{"it":"Includono movimenti, sguardo e ambiente di casa","en":"It includes movements, gaze and the home surroundings"}]',3,'{"it":"Dicono molto su chi sei.","en":"It reveals a lot about who you are."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'hierarchy'),1,1,'{"it":"Quale strumento non crea gerarchia visiva?","en":"Which tool does not create visual hierarchy?"}','[{"it":"Il nome del file","en":"The file name"},{"it":"La dimensione","en":"Size"},{"it":"Il contrasto","en":"Contrast"},{"it":"La posizione","en":"Position"}]',0,'{"it":"Il resto guida l’occhio.","en":"The rest guides the eye."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'hierarchy'),2,1,'{"it":"Quante azioni principali dovrebbe avere una schermata?","en":"How many main actions should a screen have?"}','[{"it":"Una, ben evidente","en":"One, clearly prominent"},{"it":"Tutte quelle possibili","en":"As many as possible"},{"it":"Nessuna","en":"None"},{"it":"Almeno cinque","en":"At least five"}]',0,'{"it":"Le altre sono secondarie.","en":"Others are secondary."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'hierarchy'),3,1,'{"it":"Che cosa dice il principio di vicinanza?","en":"What does the proximity principle say?"}','[{"it":"Elementi vicini sembrano collegati","en":"Close elements seem related"},{"it":"Gli elementi lontani sono più importanti","en":"Distant elements are more important"},{"it":"Bisogna avvicinare lo schermo","en":"Move the screen closer"},{"it":"I colori vicini si mescolano","en":"Nearby colours blend"}]',0,'{"it":"Gestalt.","en":"Gestalt."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'color'),1,1,'{"it":"Che contrasto minimo chiede la WCAG per il testo normale?","en":"What minimum contrast does WCAG require for normal text?"}','[{"it":"4,5:1","en":"4,5:1"},{"it":"1,5:1","en":"1,5:1"},{"it":"2:1","en":"2:1"},{"it":"10:1","en":"10:1"}]',0,'{"it":"3:1 per il testo grande.","en":"3:1 for large text."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'color'),2,1,'{"it":"Perché il colore non deve essere l’unico segnale?","en":"Why must colour not be the only signal?"}','[{"it":"Molte persone distinguono male i colori","en":"Many people struggle to tell colours apart"},{"it":"I colori costano","en":"Colours cost money"},{"it":"Gli schermi non mostrano il rosso","en":"Screens cannot show red"},{"it":"È più veloce","en":"It is faster"}]',0,'{"it":"Icona e testo in aiuto.","en":"Icon and text to help."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'color'),3,1,'{"it":"Che cosa indica di solito il rosso in un’interfaccia?","en":"What does red usually mean in an interface?"}','[{"it":"Errore o pericolo","en":"Error or danger"},{"it":"Successo","en":"Success"},{"it":"Informazione neutra","en":"Neutral information"},{"it":"Elemento disattivato","en":"Disabled element"}]',0,'{"it":"Colori semantici.","en":"Semantic colours."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'type'),1,1,'{"it":"Che cos’è una scala tipografica?","en":"What is a type scale?"}','[{"it":"Dimensioni che crescono con un rapporto fisso","en":"Sizes growing by a fixed ratio"},{"it":"Una bilancia per i font","en":"A scale for weighing fonts"},{"it":"L’elenco dei font installati","en":"The list of installed fonts"},{"it":"Una sola dimensione per tutto","en":"A single size for everything"}]',0,'{"it":"Coerenza tra i livelli.","en":"Consistency between levels."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'type'),2,1,'{"it":"Che interlinea è adatta al testo del corpo?","en":"What line height suits body text?"}','[{"it":"Circa 1,4-1,6","en":"About 1.4-1.6"},{"it":"Circa 0,8","en":"About 0.8"},{"it":"Esattamente 3","en":"Exactly 3"},{"it":"Zero","en":"Zero"}]',0,'{"it":"I titoli più stretti.","en":"Headings tighter."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'type'),3,1,'{"it":"Perché evitare paragrafi lunghi in maiuscolo?","en":"Why avoid long paragraphs in capitals?"}','[{"it":"Si leggono più lentamente","en":"They read more slowly"},{"it":"Pesano di più","en":"They weigh more"},{"it":"Non si possono stampare","en":"They cannot be printed"},{"it":"Sono vietati","en":"They are forbidden"}]',0,'{"it":"Le forme delle parole si perdono.","en":"Word shapes get lost."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'spacing'),1,1,'{"it":"Quale serie segue la griglia a 8 punti?","en":"Which series does the 8-point grid follow?"}','[{"it":"8, 16, 24, 32","en":"8, 16, 24, 32"},{"it":"5, 10, 15, 20","en":"5, 10, 15, 20"},{"it":"7, 13, 19, 23","en":"7, 13, 19, 23"},{"it":"3, 9, 27, 81","en":"3, 9, 27, 81"}]',0,'{"it":"Con 4 per i dettagli.","en":"With 4 for details."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'spacing'),2,1,'{"it":"Come si usa lo spazio per raggruppare?","en":"How is space used to group?"}','[{"it":"Meno dentro il gruppo, più tra i gruppi","en":"Less within the group, more between groups"},{"it":"Lo stesso spazio ovunque","en":"The same space everywhere"},{"it":"Più dentro, meno fuori","en":"More within, less outside"},{"it":"Nessuno spazio","en":"No space at all"}]',0,'{"it":"Vicinanza della Gestalt.","en":"Gestalt proximity."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'spacing'),3,1,'{"it":"Che cos’è il gutter?","en":"What is the gutter?"}','[{"it":"Lo spazio tra le colonne","en":"The space between columns"},{"it":"Il bordo della pagina","en":"The page border"},{"it":"Una colonna larga","en":"A wide column"},{"it":"Un tipo di font","en":"A kind of font"}]',0,'{"it":"Respiro tra i contenuti.","en":"Breathing room between content."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'gestalt'),1,2,'{"it":"Che cosa dice il principio di vicinanza?","en":"What does the proximity principle say?"}','[{"it":"Elementi vicini sembrano collegati","en":"Close elements seem related"},{"it":"Elementi grandi sono importanti","en":"Large elements are important"},{"it":"I colori caldi avanzano","en":"Warm colours advance"},{"it":"Il testo va centrato","en":"Text should be centred"}]',0,'{"it":"Etichetta vicina al suo campo.","en":"Label near its field."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'gestalt'),2,2,'{"it":"Perché il margine dopo il campo è più grande di quello tra etichetta e campo?","en":"Why is the gap after a field larger than the label-field gap?"}','[{"it":"Per raggruppare etichetta e campo","en":"To group label and field"},{"it":"Per riempire lo spazio","en":"To fill space"},{"it":"Per la SEO","en":"For SEO"},{"it":"Non conta","en":"It does not matter"}]',0,'{"it":"Lo spazio crea i gruppi.","en":"Space creates groups."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'gestalt'),3,2,'{"it":"Perché evitare testo centrato su più righe?","en":"Why avoid multi-line centred text?"}','[{"it":"Manca un bordo fisso per l’occhio","en":"There is no fixed edge for the eye"},{"it":"Occupa più spazio","en":"It takes more space"},{"it":"Non si stampa","en":"It cannot be printed"},{"it":"È vietato","en":"It is forbidden"}]',0,'{"it":"Leggere diventa faticoso.","en":"Reading gets tiring."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'controls'),1,2,'{"it":"Quando usare un link invece di un pulsante?","en":"When should you use a link instead of a button?"}','[{"it":"Per salvare un modulo","en":"To save a form"},{"it":"Per portare a un’altra pagina","en":"To take you to another page"},{"it":"Per eliminare un elemento","en":"To delete an item"},{"it":"Per inviare un pagamento","en":"To send a payment"}]',1,'{"it":"Il pulsante agisce, il link porta altrove.","en":"Buttons act, links go elsewhere."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'controls'),2,2,'{"it":"Se è il bordo a far riconoscere un campo, che contrasto minimo deve avere con lo sfondo?","en":"If the border is what identifies a field, what minimum contrast must it have with the background?"}','[{"it":"1,5:1","en":"1,5:1"},{"it":"2:1","en":"2:1"},{"it":"3:1","en":"3:1"},{"it":"7:1","en":"7:1"}]',2,'{"it":"WCAG 1.4.11, contrasto degli elementi non testuali.","en":"WCAG 1.4.11, non-text contrast."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'controls'),3,2,'{"it":"Perché un link nel testo va anche sottolineato?","en":"Why should a link in text also be underlined?"}','[{"it":"È più elegante","en":"It is more elegant"},{"it":"Lo impone il browser","en":"The browser requires it"},{"it":"Rende il testo più corto","en":"It makes the text shorter"},{"it":"Il colore da solo non basta a riconoscerlo","en":"Colour alone is not enough to recognise it"}]',3,'{"it":"Pensa a chi distingue male i colori.","en":"Think of people who struggle with colours."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'responsive'),1,2,'{"it":"Dove conviene mettere un breakpoint?","en":"Where is it best to put a breakpoint?"}','[{"it":"Alla larghezza dell’iPhone più venduto","en":"At the width of the best-selling iPhone"},{"it":"Dove il contenuto si rompe","en":"Where the content breaks"},{"it":"Ogni 100 px esatti","en":"Every 100 px exactly"},{"it":"Solo a 1920 px","en":"Only at 1920 px"}]',1,'{"it":"Il contenuto decide.","en":"The content decides."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'responsive'),2,2,'{"it":"Che cosa fa una media query `min-width: 768px` in un approccio mobile first?","en":"What does a `min-width: 768px` media query do in a mobile-first approach?"}','[{"it":"Si applica solo ai telefoni","en":"It applies only to phones"},{"it":"Nasconde la pagina sugli schermi grandi","en":"It hides the page on large screens"},{"it":"Aggiunge regole da 768 px in su","en":"It adds rules from 768 px up"},{"it":"Cambia il font di sistema","en":"It changes the system font"}]',2,'{"it":"Si parte dallo stretto e si aggiunge.","en":"Start narrow and add."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-base' AND slug = 'responsive'),3,2,'{"it":"Che cosa fa `repeat(auto-fit, minmax(240px, 1fr))`?","en":"What does `repeat(auto-fit, minmax(240px, 1fr))` do?"}','[{"it":"Crea sempre tre colonne","en":"It always creates three columns"},{"it":"Blocca ogni colonna a 240 px","en":"It locks every column at 240 px"},{"it":"Nasconde le card in eccesso","en":"It hides the extra cards"},{"it":"Crea tante colonne quante ne entrano, larghe almeno 240 px","en":"It creates as many columns as fit, at least 240 px wide"}]',3,'{"it":"Una griglia che si adatta da sola.","en":"A grid that adapts by itself."}',NULL);
