INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-intermediate' AND slug = 'states'),2,2,'{"it":"Che cosa deve fare uno stato vuoto?","en":"What should an empty state do?"}','[{"it":"Spiegare e invitare all’azione","en":"Explain and invite action"},{"it":"Restare completamente bianco","en":"Stay completely blank"},{"it":"Mostrare un errore","en":"Show an error"},{"it":"Ricaricare la pagina","en":"Reload the page"}]',0,'{"it":"Un inizio, non un vicolo cieco.","en":"A start, not a dead end."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-intermediate' AND slug = 'states'),3,2,'{"it":"Che cos’è uno skeleton screen?","en":"What is a skeleton screen?"}','[{"it":"Una sagoma del contenuto durante il caricamento","en":"A content outline while loading"},{"it":"Una schermata di Halloween","en":"A Halloween screen"},{"it":"Un wireframe stampato","en":"A printed wireframe"},{"it":"Un errore del server","en":"A server error"}]',0,'{"it":"Il caricamento sembra più breve.","en":"Loading feels shorter."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-intermediate' AND slug = 'tokens'),1,2,'{"it":"Che cos’è un design token?","en":"What is a design token?"}','[{"it":"Una decisione di stile con un nome","en":"A named style decision"},{"it":"Una moneta per comprare font","en":"A coin to buy fonts"},{"it":"Un’icona del sistema","en":"A system icon"},{"it":"Una password del designer","en":"A designer’s password"}]',0,'{"it":"Come --color-primary.","en":"Like --color-primary."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-intermediate' AND slug = 'tokens'),2,2,'{"it":"Che vantaggio danno i token semantici?","en":"What do semantic tokens give?"}','[{"it":"Indicano il ruolo e facilitano i temi","en":"They state the role and ease theming"},{"it":"Rendono il CSS più lungo","en":"They make CSS longer"},{"it":"Sostituiscono i componenti","en":"They replace components"},{"it":"Nessuno","en":"None"}]',0,'{"it":"Ruolo, non valore.","en":"Role, not value."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-intermediate' AND slug = 'tokens'),3,2,'{"it":"Che cosa contiene un design system?","en":"What does a design system contain?"}','[{"it":"Token, componenti e linee guida","en":"Tokens, components and guidelines"},{"it":"Solo un logo","en":"Only a logo"},{"it":"Solo il codice del backend","en":"Only backend code"},{"it":"Solo le foto del team","en":"Only team photos"}]',0,'{"it":"Un’unica fonte di verità.","en":"A single source of truth."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-intermediate' AND slug = 'icons'),1,2,'{"it":"Che cosa rende coerente un set di icone?","en":"What makes an icon set consistent?"}','[{"it":"Stesso stile, tratto e griglia","en":"Same style, stroke and grid"},{"it":"Colori tutti diversi","en":"All different colours"},{"it":"Icone da famiglie diverse","en":"Icons from different families"},{"it":"Dimensioni a caso","en":"Random sizes"}]',0,'{"it":"Una famiglia sola.","en":"A single family."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-intermediate' AND slug = 'icons'),2,2,'{"it":"Quando un’icona ha bisogno di un’etichetta?","en":"When does an icon need a label?"}','[{"it":"Quando il significato non è ovvio","en":"When its meaning is not obvious"},{"it":"Mai","en":"Never"},{"it":"Solo se è blu","en":"Only if it is blue"},{"it":"Solo su desktop","en":"Only on desktop"}]',0,'{"it":"Le icone sono spesso ambigue.","en":"Icons are often ambiguous."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-intermediate' AND slug = 'icons'),3,2,'{"it":"Come garantire leggibilità del testo su una foto?","en":"How to ensure text readability over a photo?"}','[{"it":"Con una sovrapposizione scura o sfumata","en":"With a dark or gradient overlay"},{"it":"Con un font più sottile","en":"With a thinner font"},{"it":"Con più colori nel testo","en":"With more colours in the text"},{"it":"Non si può","en":"It cannot be done"}]',0,'{"it":"Contrasto prima di tutto.","en":"Contrast first."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-intermediate' AND slug = 'motion'),1,2,'{"it":"Quanto dura di solito una transizione di interfaccia?","en":"How long does a UI transition usually last?"}','[{"it":"Tra 100 e 300 ms","en":"Between 100 and 300 ms"},{"it":"Tra 2 e 5 secondi","en":"Between 2 and 5 seconds"},{"it":"Un minuto","en":"One minute"},{"it":"Meno di 1 ms","en":"Under 1 ms"}]',0,'{"it":"Breve e utile.","en":"Short and useful."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-intermediate' AND slug = 'motion'),2,2,'{"it":"A che cosa serve `prefers-reduced-motion`?","en":"What is `prefers-reduced-motion` for?"}','[{"it":"Rispettare chi chiede meno animazioni","en":"Respecting those who ask for less animation"},{"it":"Velocizzare il server","en":"Speeding up the server"},{"it":"Nascondere le immagini","en":"Hiding images"},{"it":"Aumentare le animazioni","en":"Increasing animations"}]',0,'{"it":"Accessibilità del movimento.","en":"Motion accessibility."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-intermediate' AND slug = 'motion'),3,2,'{"it":"Quale curva è naturale per un elemento che entra?","en":"Which curve feels natural for an entering element?"}','[{"it":"ease-out","en":"ease-out"},{"it":"linear","en":"linear"},{"it":"step-end","en":"step-end"},{"it":"ease-in","en":"ease-in"}]',0,'{"it":"Veloce all’inizio, morbida alla fine.","en":"Fast at first, soft at the end."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-intermediate' AND slug = 'handoff'),1,3,'{"it":"Che cosa fa l’auto layout di Figma?","en":"What does Figma’s auto layout do?"}','[{"it":"Fa crescere il componente con il contenuto","en":"Makes the component grow with its content"},{"it":"Esporta il codice","en":"Exports code"},{"it":"Sceglie i colori","en":"Chooses colours"},{"it":"Anima le pagine","en":"Animates pages"}]',0,'{"it":"Come il flexbox.","en":"Like flexbox."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-intermediate' AND slug = 'handoff'),2,3,'{"it":"A che cosa servono le varianti?","en":"What are variants for?"}','[{"it":"Raccogliere taglie e stati di un componente","en":"Gathering a component’s sizes and states"},{"it":"Creare pagine","en":"Creating pages"},{"it":"Tradurre i testi","en":"Translating text"},{"it":"Fare i test","en":"Running tests"}]',0,'{"it":"Un solo componente, molte forme.","en":"One component, many forms."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-intermediate' AND slug = 'handoff'),3,3,'{"it":"Quale stato si dimentica spesso nel design?","en":"Which state is often forgotten in design?"}','[{"it":"Il testo lunghissimo o l’errore","en":"Very long text or the error"},{"it":"Lo stato normale","en":"The normal state"},{"it":"Il logo","en":"The logo"},{"it":"Il titolo","en":"The title"}]',0,'{"it":"I casi reali rompono i layout.","en":"Real cases break layouts."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-intermediate' AND slug = 'dataviz'),1,3,'{"it":"Quale grafico per mostrare le vendite mese per mese in un anno?","en":"Which chart shows sales month by month over a year?"}','[{"it":"Una torta","en":"A pie chart"},{"it":"Un grafico a linee","en":"A line chart"},{"it":"Una dispersione","en":"A scatter plot"},{"it":"Una card KPI","en":"A KPI card"}]',1,'{"it":"Andamento nel tempo.","en":"Trend over time."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-intermediate' AND slug = 'dataviz'),2,3,'{"it":"Perché l’asse di un grafico a barre parte da zero?","en":"Why does a bar chart’s axis start at zero?"}','[{"it":"Per avere più colori","en":"To have more colours"},{"it":"Perché lo impone il foglio di calcolo","en":"Because the spreadsheet requires it"},{"it":"Altrimenti le differenze sembrano più grandi","en":"Otherwise differences look bigger"},{"it":"Per risparmiare spazio","en":"To save space"}]',2,'{"it":"La lunghezza della barra è il dato.","en":"The bar’s length is the data."}',NULL);
