INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-intermediate' AND slug = 'type-advanced'),1,3,'{"it":"Che cosa contiene un font variabile?","en":"What does a variable font contain?"}','[{"it":"Un solo peso fisso","en":"A single fixed weight"},{"it":"Tante varianti lungo degli assi, in un file","en":"Many variants along axes, in one file"},{"it":"Solo caratteri decorativi","en":"Only decorative characters"},{"it":"Un’immagine del testo","en":"An image of the text"}]',1,'{"it":"Peso, larghezza, dimensione ottica…","en":"Weight, width, optical size…"}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-intermediate' AND slug = 'type-advanced'),2,3,'{"it":"Che cosa fa `clamp(1.5rem, 1rem + 2vw, 2.5rem)`?","en":"What does `clamp(1.5rem, 1rem + 2vw, 2.5rem)` do?"}','[{"it":"Fissa il testo a 2vw","en":"Fixes the text at 2vw"},{"it":"Nasconde il testo su mobile","en":"Hides the text on mobile"},{"it":"Fa crescere il testo con lo schermo tra un minimo e un massimo","en":"Grows the text with the screen between a minimum and a maximum"},{"it":"Converte i rem in pixel","en":"Converts rem to pixels"}]',2,'{"it":"Fluido ma con limiti.","en":"Fluid but bounded."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-intermediate' AND slug = 'type-advanced'),3,3,'{"it":"Perché mettere una parte in `rem` nel valore fluido?","en":"Why include a `rem` part in the fluid value?"}','[{"it":"Per renderlo più corto","en":"To make it shorter"},{"it":"È obbligatorio in CSS","en":"CSS requires it"},{"it":"Serve ai font variabili","en":"Variable fonts need it"},{"it":"Perché lo zoom del testo dell’utente funzioni ancora","en":"So the user’s text zoom still works"}]',3,'{"it":"Solo vw ignorerebbe le preferenze.","en":"Pure vw would ignore preferences."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-mobile' AND slug = 'units'),1,2,'{"it":"Perché si progetta in pt o dp invece che in pixel fisici?","en":"Why design in pt or dp instead of physical pixels?"}','[{"it":"Per avere la stessa dimensione su densità diverse","en":"For the same size across densities"},{"it":"Perché i pixel sono a pagamento","en":"Because pixels cost money"},{"it":"Per rendere le immagini sfocate","en":"To make images blurry"},{"it":"Non c’è differenza","en":"There is no difference"}]',0,'{"it":"Il sistema moltiplica per la densità.","en":"The system multiplies by density."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-mobile' AND slug = 'units'),2,2,'{"it":"Quale unità segue la dimensione del testo scelta dall’utente su Android?","en":"Which unit follows the user’s text size on Android?"}','[{"it":"sp","en":"sp"},{"it":"px","en":"px"},{"it":"pt fissi","en":"pt fissi"},{"it":"cm","en":"cm"}]',0,'{"it":"Scale-independent pixels.","en":"Scale-independent pixels."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-mobile' AND slug = 'units'),3,2,'{"it":"Quale formato resta nitido a ogni scala?","en":"Which format stays sharp at every scale?"}','[{"it":"SVG","en":"SVG"},{"it":"JPEG","en":"JPEG"},{"it":"PNG piccolo","en":"Small PNG"},{"it":"GIF","en":"GIF"}]',0,'{"it":"Vettoriale.","en":"Vector."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-mobile' AND slug = 'safe'),1,2,'{"it":"Che cos’è la safe area?","en":"What is the safe area?"}','[{"it":"La zona libera da notch e barre di sistema","en":"The zone free of notches and system bars"},{"it":"Una zona protetta da password","en":"A password-protected zone"},{"it":"Lo sfondo dell’app","en":"The app background"},{"it":"La memoria del telefono","en":"The phone’s memory"}]',0,'{"it":"Lì vanno i controlli.","en":"Controls go there."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-mobile' AND slug = 'safe'),2,2,'{"it":"Che cosa può estendersi fino ai bordi?","en":"What may extend to the edges?"}','[{"it":"Gli sfondi","en":"Backgrounds"},{"it":"I pulsanti principali","en":"Main buttons"},{"it":"I campi di testo","en":"Text fields"},{"it":"I link","en":"Links"}]',0,'{"it":"Decorazione sì, controlli no.","en":"Decoration yes, controls no."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-mobile' AND slug = 'safe'),3,2,'{"it":"Che cosa fare quando compare la tastiera?","en":"What to do when the keyboard appears?"}','[{"it":"Tenere visibili campo e pulsante di invio","en":"Keep the field and submit button visible"},{"it":"Nascondere il campo attivo","en":"Hide the active field"},{"it":"Chiudere l’app","en":"Close the app"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Il layout si adatta.","en":"The layout adapts."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-mobile' AND slug = 'components'),1,2,'{"it":"Che cos’è un bottom sheet?","en":"What is a bottom sheet?"}','[{"it":"Un pannello che sale dal basso","en":"A panel rising from the bottom"},{"it":"Il fondo della pagina web","en":"The bottom of a web page"},{"it":"Un foglio di calcolo","en":"A spreadsheet"},{"it":"Una notifica di sistema","en":"A system notification"}]',0,'{"it":"Vicino al pollice.","en":"Near the thumb."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-mobile' AND slug = 'components'),2,2,'{"it":"A che cosa serve una snackbar?","en":"What is a snackbar for?"}','[{"it":"Una breve conferma, a volte con un’azione","en":"A brief confirmation, sometimes with an action"},{"it":"Un menu di cibo","en":"A food menu"},{"it":"Un errore bloccante","en":"A blocking error"},{"it":"La navigazione principale","en":"Main navigation"}]',0,'{"it":"“Messaggio eliminato · Annulla”.","en":"“Message deleted · Undo”."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-mobile' AND slug = 'components'),3,2,'{"it":"Quando usare una modale a tutto schermo?","en":"When to use a full-screen modal?"}','[{"it":"Per un compito breve e chiuso","en":"For a short, self-contained task"},{"it":"Per ogni scelta, anche minima","en":"For every choice, however small"},{"it":"Per la navigazione principale","en":"For main navigation"},{"it":"Mai","en":"Never"}]',0,'{"it":"Interrompe: con giudizio.","en":"It interrupts: use with care."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-mobile' AND slug = 'platforms'),1,2,'{"it":"Perché evitare il nero puro come sfondo scuro?","en":"Why avoid pure black as a dark background?"}','[{"it":"Troppo contrasto e sbavature su OLED","en":"Too much contrast and smearing on OLED"},{"it":"Consuma più batteria","en":"It uses more battery"},{"it":"Non esiste su CSS","en":"It does not exist in CSS"},{"it":"È vietato da Apple","en":"Apple forbids it"}]',0,'{"it":"Meglio grigi molto scuri.","en":"Very dark greys are better."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-mobile' AND slug = 'platforms'),2,2,'{"it":"Come si mostra l’elevazione nel tema scuro?","en":"How is elevation shown in dark theme?"}','[{"it":"Con superfici più chiare","en":"With lighter surfaces"},{"it":"Con ombre nere più forti","en":"With stronger black shadows"},{"it":"Con bordi rossi","en":"With red borders"},{"it":"Non si mostra","en":"It is not shown"}]',0,'{"it":"Più in alto, più chiaro.","en":"Higher, lighter."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-mobile' AND slug = 'platforms'),3,2,'{"it":"Che cosa deve rispettare un’app multipiattaforma?","en":"What must a cross-platform app respect?"}','[{"it":"I comportamenti attesi su ogni sistema","en":"The expected behaviours on each system"},{"it":"Solo le regole di iOS ovunque","en":"Only iOS rules everywhere"},{"it":"Nessuna convenzione","en":"No convention"},{"it":"Solo il brand","en":"Only the brand"}]',0,'{"it":"Brand unico, comportamenti nativi.","en":"Single brand, native behaviours."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-mobile' AND slug = 'first-run'),1,3,'{"it":"Che cosa serve in uno stato vuoto?","en":"What does an empty state need?"}','[{"it":"Spiegazione e pulsante per iniziare","en":"An explanation and a button to start"},{"it":"Solo la scritta “Vuoto”","en":"Just the word “Empty”"},{"it":"Un errore","en":"An error"},{"it":"Niente","en":"Nothing"}]',0,'{"it":"Guida il primo passo.","en":"It guides the first step."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-mobile' AND slug = 'first-run'),2,3,'{"it":"Com’è un buon onboarding?","en":"What is good onboarding like?"}','[{"it":"Corto e saltabile","en":"Short and skippable"},{"it":"Dieci schermate obbligatorie","en":"Ten mandatory screens"},{"it":"Un video di 5 minuti","en":"A 5-minute video"},{"it":"Un modulo lungo","en":"A long form"}]',0,'{"it":"Meglio imparare usando.","en":"Better to learn by using."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-mobile' AND slug = 'first-run'),3,3,'{"it":"Quando chiedere il permesso per le notifiche?","en":"When should you ask for notification permission?"}','[{"it":"Quando serve, spiegando il perché","en":"When needed, explaining why"},{"it":"Appena si apre l’app","en":"As soon as the app opens"},{"it":"Mai","en":"Never"},{"it":"Dopo un anno","en":"After a year"}]',0,'{"it":"Un no è difficile da recuperare.","en":"A no is hard to recover."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-mobile' AND slug = 'adaptive'),1,3,'{"it":"Che cosa succede spesso alla tab bar su uno schermo largo?","en":"What often happens to the tab bar on a wide screen?"}','[{"it":"Sparisce del tutto","en":"It disappears entirely"},{"it":"Diventa una barra laterale o una rail","en":"It becomes a sidebar or a rail"},{"it":"Si raddoppia","en":"It doubles"},{"it":"Va in alto a destra","en":"It moves to the top right"}]',1,'{"it":"La navigazione si sposta di lato.","en":"Navigation moves to the side."}',NULL);
