INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-mobile' AND slug = 'app-icon'),1,3,'{"it":"Che cosa rende efficace un’icona d’app?","en":"What makes an app icon effective?"}','[{"it":"Tanto testo descrittivo","en":"Plenty of descriptive text"},{"it":"Una foto ricca di dettagli","en":"A highly detailed photo"},{"it":"Una forma semplice e riconoscibile","en":"A simple, recognisable shape"},{"it":"Tutti i colori del brand insieme","en":"All the brand colours together"}]',2,'{"it":"Deve leggersi anche piccolissima.","en":"It must read even when tiny."}',NULL);
INSERT INTO `fc_questions` (lesson_id, `sort`,`difficulty`,`q`,`options`,`answer`,`why`,`hint`) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'ui-mobile' AND slug = 'app-icon'),2,3,'{"it":"Che cos’è un’icona adattiva su Android?","en":"What is an adaptive icon on Android?"}','[{"it":"Un’icona animata","en":"An animated icon"},{"it":"Un’icona con primo piano e sfondo separati che il launcher ritaglia","en":"An icon with separate foreground and background that the launcher crops"},{"it":"Un’icona che cambia ogni giorno","en":"An icon that changes every day"},{"it":"Un’icona solo in bianco e nero","en":"A black-and-white-only icon"}]',1,'{"it":"Cerchio, quadrato arrotondato, goccia…","en":"Circle, squircle, teardrop…"}',NULL);
