INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'logical'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"In arabo `inline-start` è a destra","en":"In Arabic `inline-start` is on the right"},true],[{"it":"In italiano `block` è la direzione orizzontale","en":"In English `block` is the horizontal direction"},false],[{"it":"`padding-inline: 8px` vale per entrambi i lati","en":"`padding-inline: 8px` applies to both sides"},true],[{"it":"Le proprietà logiche richiedono JavaScript","en":"Logical properties need JavaScript"},false]],"why":{"it":"Scrivi una volta, vale per ogni lingua.","en":"Write once, it works for every language."}}');
