INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'layers'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"In un livello successivo un selettore di tag batte un id di un livello precedente","en":"In a later layer a tag selector beats an id from an earlier layer"},true],[{"it":"`:where()` aumenta la specificità","en":"`:where()` raises specificity"},false],[{"it":"`:is(h1, h2)` sceglie sia gli `h1` sia gli `h2`","en":"`:is(h1, h2)` picks both `h1` and `h2`"},true],[{"it":"Per usare `@layer` serve un preprocessore","en":"`@layer` needs a preprocessor"},false]],"why":{"it":"Livelli nativi del browser: niente strumenti in più.","en":"Native browser layers: no extra tools."}}');
