INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-advanced' AND slug = 'colors-modern'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"In `oklch` passi uguali di luminosità sembrano equidistanti","en":"In `oklch` equal lightness steps look evenly spaced"},true],[{"it":"`light-dark()` funziona anche senza `color-scheme`","en":"`light-dark()` works without `color-scheme` too"},false],[{"it":"`color-mix()` richiede Sass","en":"`color-mix()` needs Sass"},false],[{"it":"`oklch(65% 0.2 40)` è un colore valido","en":"`oklch(65% 0.2 40)` is a valid colour"},true]],"why":{"it":"Il CSS ora sa fare da solo i conti sui colori.","en":"CSS can now do colour maths by itself."}}');
