INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'architecture'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`_bottoni.scss` è un parziale","en":"`_bottoni.scss` is a partial"},true],[{"it":"Ogni parziale diventa un `.css`","en":"Every partial becomes a `.css`"},false],[{"it":"`@use` si scrive in cima al file","en":"`@use` goes at the top of the file"},true],[{"it":"Dividere i file rallenta il sito","en":"Splitting files slows the site down"},false]],"why":{"it":"Tanti file per chi scrive, uno solo per chi visita.","en":"Many files for the author, one for the visitor."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'content-blocks'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"@mixin hover-sicuro {\\n  @media (hover: hover) {\\n    &:hover { ___; }\\n  }\\n}\\n.btn {\\n  ___ hover-sicuro { color: red; }\\n}","gaps":["@content","@include"],"extra":["@return","@extend","@use"],"why":{"it":"Il mixin incornicia, `@include` porta il blocco.","en":"The mixin frames, `@include` brings the block."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'content-blocks'),2,'order','{"prompt":{"it":"Rimetti le righe nell’ordine giusto.","en":"Put the lines back in the right order."},"lines":["@mixin schermo($min) {","  @media (min-width: $min) {","    @content;","  }","}"],"why":{"it":"Il mixin avvolge la media query, che avvolge `@content`.","en":"The mixin wraps the media query, which wraps `@content`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'control-flow'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["@if",{"it":"Applica una condizione","en":"Applies a condition"}],["@else",{"it":"Il caso contrario","en":"The opposite case"}],["from 1 through 3",{"it":"1, 2 e 3","en":"1, 2 and 3"}],["from 1 to 3",{"it":"1 e 2","en":"1 and 2"}],["@while",{"it":"Ripete finché è vero","en":"Repeats while true"}]],"why":{"it":"La logica gira nel compilatore, non nel browser.","en":"The logic runs in the compiler, not in the browser."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'control-flow'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["@for $i from 1 through 3 {","  .mt-$i { margin-top: $i * 4px; }","}"],"bug":1,"fix":"  .mt-#{$i} { margin-top: $i * 4px; }","why":{"it":"In un selettore la variabile va interpolata con `#{}`.","en":"In a selector the variable must be interpolated with `#{}`."}}');
