INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'forward-config'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`with` funziona solo con variabili dichiarate con `!default`","en":"`with` only works on variables declared with `!default`"},true],[{"it":"`@forward` rende i membri visibili dentro il file che lo scrive","en":"`@forward` makes the members visible inside the file that writes it"},false],[{"it":"`as s` permette di scrivere `s.$raggio`","en":"`as s` lets you write `s.$raggio`"},true],[{"it":"`@import` è il modo consigliato per caricare i moduli","en":"`@import` is the recommended way to load modules"},false]],"why":{"it":"`@forward` inoltra ad altri: per usare i membri nel file stesso serve anche `@use`.","en":"`@forward` passes members on: to use them in the file itself you also need `@use`."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'maps-sass'),1,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["$colore: red",".card {","  color: $colore","}"],"bug":1,"fix":".card","why":{"it":"In Sass non ci sono graffe: basta il rientro.","en":"There are no braces in Sass: the indent is enough."}}');
