INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'sass' AND slug = 'multiline'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Da Dart Sass 1.84 una mappa può stare su più righe","en":"Since Dart Sass 1.84 a map can span several lines"},true],[{"it":"In Sass i commenti `//` finiscono nel CSS","en":"In Sass `//` comments end up in the CSS"},false],[{"it":"Un `;` finale oggi è tollerato","en":"A trailing `;` is tolerated today"},true],[{"it":"In Sass un blocco si può aprire con `{`","en":"In Sass a block can open with `{`"},false]],"why":{"it":"Più comodità, stesse regole di fondo.","en":"More comfort, the same basic rules."}}');
