INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-base' AND slug = 'numbers'),1,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`typeof 3.5` è `\\"number\\"`","en":"`typeof 3.5` is `\\"number\\"`"},true],[{"it":"`Number(\\"\\")` dà `NaN`","en":"`Number(\\"\\")` gives `NaN`"},false],[{"it":"`0.1 + 0.2 === 0.3` è vero","en":"`0.1 + 0.2 === 0.3` is true"},false],[{"it":"`Math.max(2, 8)` vale 8","en":"`Math.max(2, 8)` is 8"},true]],"why":{"it":"Un solo tipo per i numeri. E occhio: `Number(\\"\\")` vale 0.","en":"One type for all numbers. And watch out: `Number(\\"\\")` is 0."}}');
