INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-base' AND slug = 'numbers'),3,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["const prezzo = \\"10\\";","const spedizione = 5;","const totale = prezzo + spedizione;","console.log(totale); // \\"105\\""],"bug":2,"fix":"const totale = Number(prezzo) + spedizione;","why":{"it":"Con una stringa `+` unisce i testi: prima va convertita.","en":"With a string `+` joins the texts: convert it first."}}');
