INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-intermediate' AND slug = 'dates-errors'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`setTimeout` parte una volta sola","en":"`setTimeout` runs only once"},true],[{"it":"`setInterval` si ripete","en":"`setInterval` repeats"},true],[{"it":"`setTimeout(f, 1)` aspetta un secondo","en":"`setTimeout(f, 1)` waits one second"},false],[{"it":"`try` senza `catch` o `finally` è valido","en":"`try` without `catch` or `finally` is valid"},false]],"why":{"it":"Un `try` ha sempre bisogno di `catch` o `finally`.","en":"A `try` always needs `catch` or `finally`."}}');
