INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-intermediate' AND slug = 'sort-copy'),1,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["const prezzi = [5, 20, 100];","prezzi.sort();","console.log(prezzi[0]); // il più basso"],"bug":1,"fix":"prezzi.sort((a, b) => a - b);","why":{"it":"Senza funzione `\\"100\\"` viene prima di `\\"20\\"` e di `\\"5\\"`.","en":"Without a function `\\"100\\"` comes before `\\"20\\"` and `\\"5\\"`."}}');
