INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'js-advanced' AND slug = 'prototypes'),1,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["class Timer {","  constructor() { this.secondi = 0; }","  avvia() {","    setInterval(function () { this.secondi++; }, 1000);","  }","}"],"bug":3,"fix":"    setInterval(() => { this.secondi++; }, 1000);","why":{"it":"Una `function` normale perde `this`: l’arrow function usa quello del metodo.","en":"A regular `function` loses `this`: the arrow function uses the method’s one."}}');
