INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'property-hooks'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"public string $titolo {\\n    ___(string $v) {\\n        $this->titolo = ucfirst($v);\\n    }\\n}\\npublic ___(set) int $voti = 0;\\npublic string $sigla {\\n    ___ => strtoupper($this->titolo);\\n}","gaps":["set","private","get"],"extra":["put","readonly","read"],"why":{"it":"Hook in scrittura, visibilità asimmetrica, hook in lettura.","en":"Write hook, asymmetric visibility, read hook."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'property-hooks'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Gli hook evitano molti getter e setter scritti a mano","en":"Hooks avoid many hand-written getters and setters"},true],[{"it":"`private(set)` impedisce anche la lettura da fuori","en":"`private(set)` also blocks reading from outside"},false],[{"it":"Una proprietà virtuale non occupa spazio nell’oggetto","en":"A virtual property takes no space in the object"},true],[{"it":"Gli hook si possono mettere anche sulle proprietà `static`","en":"Hooks can also go on `static` properties"},false]],"why":{"it":"Logica dentro la proprietà, non in metodi a parte.","en":"Logic inside the property, not in separate methods."}}');
