INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'static-analysis'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"PHPStan deve eseguire il codice per trovare errori","en":"PHPStan must run the code to find errors"},false],[{"it":"I commenti `@return` possono descrivere la forma di un array","en":"`@return` comments can describe an array’s shape"},true],[{"it":"Conviene partire da un livello basso e alzarlo","en":"It pays to start at a low level and raise it"},true],[{"it":"L’analisi statica sostituisce del tutto i test","en":"Static analysis fully replaces tests"},false]],"why":{"it":"Analisi statica e test si completano.","en":"Static analysis and tests complement each other."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-advanced' AND slug = 'performance'),1,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["$corsi = $pdo->query(\\"SELECT * FROM corsi\\")->fetchAll();","foreach ($corsi as $c) {","    $n = $pdo->query(\\"SELECT COUNT(*) FROM lezioni WHERE corso_id = \\" . (int) $c[\\"id\\"])->fetchColumn();","}"],"bug":2,"fix":"    $n = $conteggi[$c[\\"id\\"]] ?? 0; // da una sola query con GROUP BY","why":{"it":"Una query per ogni corso: con 1000 corsi sono 1001 query. Meglio contarle tutte con una sola query e `GROUP BY`.","en":"One query per course: with 1000 courses that is 1001 queries. Better to count them all with one query and `GROUP BY`."}}');
