INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'llm-api' AND slug = 'vision'),1,'order','{"prompt":{"it":"Rimetti le righe nell’ordine giusto.","en":"Put the lines back in the right order."},"lines":["with open(\\"foto.jpg\\", \\"rb\\") as f:","    dati = base64.standard_b64encode(f.read()).decode()","blocco = {\\"type\\": \\"image\\", \\"source\\": {\\"type\\": \\"base64\\", \\"media_type\\": \\"image/jpeg\\", \\"data\\": dati}}","content = [blocco, {\\"type\\": \\"text\\", \\"text\\": \\"Descrivi la foto\\"}]","r = client.messages.create(model=M, max_tokens=1024, messages=[{\\"role\\": \\"user\\", \\"content\\": content}])"],"why":{"it":"Leggi, codifica, componi, invia.","en":"Read, encode, compose, send."}}');
