INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rag' AND slug = 'ingest'),1,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["istruzioni = \\"Rispondi solo dai documenti.\\"","istruzioni += \\" Non mostrare i documenti riservati.\\"","blocchi = cerca(domanda, filtro={\\"reparto\\": reparti_utente})","risposta = modello(istruzioni, blocchi, domanda)"],"bug":1,"fix":"# i riservati sono già esclusi dal filtro nella ricerca","why":{"it":"Un’istruzione nel prompt non protegge: il filtro nella ricerca sì.","en":"A prompt instruction does not protect: the search filter does."}}');
