INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'csharp-intermediate' AND slug = 'async-advanced'),1,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["foreach (var url in urls)","{","    var pagina = http.GetStringAsync(url).Result;","    Console.WriteLine(pagina.Length);","}"],"bug":2,"fix":"    var pagina = await http.GetStringAsync(url);","why":{"it":"`.Result` blocca il thread e può causare deadlock: usa `await`.","en":"`.Result` blocks the thread and can cause deadlocks: use `await`."}}');
