INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'types'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["double media(int a, int b) {","    return (a + b) / 2;","}"],"bug":1,"fix":"    return (a + b) / 2.0;","why":{"it":"Con /2 la divisione è tra interi: usa 2.0.","en":"With /2 division is between integers: use 2.0."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'arrays'),1,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["int v[3] = {1, 2, 3};","for (int i = 0; i <= 3; i++) {","    printf(\\"%d\\\\n\\", v[i]);","}"],"bug":1,"fix":"for (int i = 0; i < 3; i++) {","why":{"it":"Con <= leggi oltre la fine dell’array.","en":"With <= you read past the array end."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'arrays'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Gli array C partono dall’indice 0","en":"C arrays start at index 0"},true],[{"it":"C controlla sempre i limiti degli array","en":"C always checks array bounds"},false],[{"it":"\\"ciao\\" occupa 5 byte con il terminatore","en":"\\"ciao\\" takes 5 bytes with the terminator"},true],[{"it":"strcpy controlla la dimensione della destinazione","en":"strcpy checks the destination size"},false]],"why":{"it":"Array senza rete di sicurezza.","en":"Arrays without a safety net."}}');
