INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'pointers'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["int *p = malloc(sizeof *p);","free(p);","*p = 10;"],"bug":2,"fix":"p = NULL;","why":{"it":"Dopo free la memoria non va più usata.","en":"After free the memory must not be used."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'structs-files'),1,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["FILE *f = fopen(\\"dati.txt\\", \\"w\\");","if (f = NULL) return 1;","fprintf(f, \\"ciao\\");","fclose(f);"],"bug":1,"fix":"if (f == NULL) return 1;","why":{"it":"`=` assegna, `==` confronta: così f diventa NULL.","en":"`=` assigns, `==` compares: this way f becomes NULL."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'structs-files'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Ogni malloc richiede un free","en":"Every malloc needs a free"},true],[{"it":"fopen non può mai fallire","en":"fopen can never fail"},false],[{"it":"\\"a\\" aggiunge in fondo al file","en":"\\"a\\" appends to the end of the file"},true],[{"it":"p.x funziona con un puntatore","en":"p.x works with a pointer"},false]],"why":{"it":"Memoria e file.","en":"Memory and files."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'functions'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[[{"it":"Prototipo","en":"Prototype"},{"it":"Dichiarazione prima dell’uso","en":"Declaration before use"}],[{"it":"Per valore","en":"By value"},{"it":"La funzione riceve una copia","en":"The function gets a copy"}],[{"it":"static (locale)","en":"static (local)"},{"it":"Conserva il valore tra le chiamate","en":"Keeps its value between calls"}],[{"it":"static (globale)","en":"static (global)"},{"it":"Visibile solo nel file","en":"Visible only in the file"}],["void",{"it":"Nessun parametro o nessun risultato","en":"No parameters or no result"}]],"why":{"it":"Funzioni in C.","en":"Functions in C."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'functions'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"In C gli argomenti passano per valore","en":"In C arguments are passed by value"},true],[{"it":"Una variabile locale sopravvive alla fine della funzione","en":"A local variable outlives the end of the function"},false],[{"it":"Un prototipo finisce con il punto e virgola","en":"A prototype ends with a semicolon"},true],[{"it":"Per modificare una variabile di chi chiama serve un puntatore","en":"To change a caller’s variable you need a pointer"},true]],"why":{"it":"Le variabili locali muoiono con la chiamata.","en":"Local variables die with the call."}}');
