INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'strings'),1,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["char a[] = \\"pane\\";","char b[] = \\"pane\\";","if (a == b) printf(\\"Uguali\\\\n\\");"],"bug":2,"fix":"if (strcmp(a, b) == 0) printf(\\"Uguali\\\\n\\");","why":{"it":"`a == b` confronta due indirizzi diversi: è sempre falso.","en":"`a == b` compares two different addresses: it is always false."}}');
