INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'enums-typedef'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"typedef ___ { PICCOLO, MEDIO, GRANDE } Taglia;\\ntypedef ___ {\\n    char nome[20];\\n    Taglia taglia;\\n} Maglia;\\nMaglia m = { ___ = \\"Blu\\", .taglia = MEDIO };","gaps":["enum","struct",".nome"],"extra":["define","class","nome:"],"why":{"it":"Enum, struct, inizializzatore designato.","en":"Enum, struct, designated initialiser."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-base' AND slug = 'enums-typedef'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Il primo valore di un enum vale 0 se non indicato","en":"An enum’s first value is 0 unless given"},true],[{"it":"`typedef` crea un tipo nuovo con regole diverse","en":"`typedef` creates a new type with different rules"},false],[{"it":"Gli inizializzatori designati scelgono i campi per nome","en":"Designated initialisers pick fields by name"},true],[{"it":"In una union si usa un campo alla volta","en":"In a union you use one field at a time"},true]],"why":{"it":"`typedef` dà solo un altro nome a un tipo esistente.","en":"`typedef` only gives another name to an existing type."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'pointer-arithmetic'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["v[i]",{"it":"Uguale a *(v + i)","en":"Same as *(v + i)"}],["p + 1",{"it":"Elemento successivo","en":"Next element"}],["const int *p",{"it":"Valori in sola lettura","en":"Read-only values"}],["sizeof v / sizeof v[0]",{"it":"Numero di elementi dell’array","en":"Number of elements in the array"}],["size_t",{"it":"Tipo per dimensioni e indici","en":"Type for sizes and indices"}]],"why":{"it":"Puntatori e array.","en":"Pointers and arrays."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'pointer-arithmetic'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Il nome di un array diventa un puntatore al primo elemento","en":"An array name becomes a pointer to the first element"},true],[{"it":"`p + 1` avanza sempre di un byte","en":"`p + 1` always moves one byte"},false],[{"it":"Dentro una funzione, `sizeof` di un parametro array dà la dimensione dell’array","en":"Inside a function, `sizeof` of an array parameter gives the array’s size"},false],[{"it":"Si può confrontare un puntatore con `v + n`","en":"You can compare a pointer with `v + n`"},true]],"why":{"it":"Nella funzione l’array è solo un puntatore.","en":"Inside the function the array is just a pointer."}}');
