INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'c-intermediate' AND slug = 'linked-list'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Ogni nodo creato con malloc va liberato con free","en":"Every node created with malloc must be freed with free"},true],[{"it":"In una lista collegata l’n-esimo elemento si legge all’istante","en":"In a linked list the n-th item is read instantly"},false],[{"it":"`p->prossimo` equivale a `(*p).prossimo`","en":"`p->prossimo` is the same as `(*p).prossimo`"},true],[{"it":"Inserire in testa non richiede di scorrere la lista","en":"Inserting at the head does not require walking the list"},true]],"why":{"it":"Per l’n-esimo bisogna scorrere.","en":"For the n-th you must walk."}}');
