INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'why'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Un test automatico si può rieseguire quante volte vuoi","en":"An automated test can be rerun as often as you like"},true],[{"it":"I test end-to-end sono i più veloci","en":"End-to-end tests are the fastest"},false],[{"it":"I test documentano il comportamento atteso","en":"Tests document expected behaviour"},true],[{"it":"Con i test non serve mai rileggere il codice","en":"With tests you never need to review code"},false]],"why":{"it":"Fiducia automatica.","en":"Automated confidence."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'unit'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["describe",{"it":"Raggruppa i test","en":"Groups tests"}],["it",{"it":"Un singolo test","en":"A single test"}],["expect",{"it":"Valore da verificare","en":"Value to check"}],["toBe",{"it":"Uguaglianza","en":"Equality"}],["toThrow",{"it":"Deve lanciare un errore","en":"Must throw an error"}]],"why":{"it":"Il vocabolario dei test.","en":"Test vocabulary."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'unit'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["it(\\"calcola lo sconto\\", () => {","  const prezzo = sconta(100, 0.2);","  console.log(prezzo);","});"],"bug":2,"fix":"  expect(prezzo).toBe(80);","why":{"it":"Un test senza asserzione non verifica niente.","en":"A test without an assertion verifies nothing."}}');
