INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'mocks'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Un mock può registrare come è stato chiamato","en":"A mock can record how it was called"},true],[{"it":"I test unitari devono mandare email vere","en":"Unit tests must send real email"},false],[{"it":"Un database di test si può avviare in un container","en":"A test database can run in a container"},true],[{"it":"Più mock significa sempre test migliori","en":"More mocks always means better tests"},false]],"why":{"it":"Isolare con giudizio.","en":"Isolate wisely."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'e2e-ci'),1,'order','{"prompt":{"it":"Rimetti le righe nell’ordine giusto.","en":"Put the lines back in the right order."},"lines":[{"it":"Scrivi un test che fallisce (rosso)","en":"Write a failing test (red)"},{"it":"Scrivi il codice minimo per farlo passare (verde)","en":"Write minimal code to pass it (green)"},{"it":"Migliora il codice tenendo i test verdi (refactor)","en":"Improve the code keeping tests green (refactor)"}],"why":{"it":"Il ciclo del TDD.","en":"The TDD cycle."}}');
