INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'quality'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[[{"it":"Copertura","en":"Coverage"},{"it":"Righe eseguite","en":"Lines run"}],[{"it":"Caso limite","en":"Edge case"},{"it":"Lista vuota, zero","en":"Empty list, zero"}],[{"it":"Test fragile","en":"Flaky test"},{"it":"Passa a caso","en":"Passes at random"}],["test.each",{"it":"Molti casi in un test","en":"Many cases in one test"}]],"why":{"it":"Test di qualità.","en":"Quality tests."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'quality'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"100% di copertura non garantisce zero bug","en":"100% coverage does not guarantee zero bugs"},true],[{"it":"Un sleep rende un test più stabile","en":"A sleep makes a test more stable"},false],[{"it":"I test dovrebbero essere indipendenti tra loro","en":"Tests should be independent of each other"},true],[{"it":"Un test fragile si sistema rilanciandolo","en":"A flaky test is fixed by rerunning it"},false]],"why":{"it":"Fiducia nei test.","en":"Trust in tests."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'testing' AND slug = 'async-time'),1,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["it(\\"carica i dati\\", () => {","  expect(carica()).resolves.toEqual([1, 2]);","});"],"bug":1,"fix":"  return expect(carica()).resolves.toEqual([1, 2]);","why":{"it":"Senza `await` o `return` il test non aspetta la promessa.","en":"Without `await` or `return` the test does not wait for the promise."}}');
