INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'regex' AND slug = 'quantifiers'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["// valida un codice di 6 cifre","const valido = /\\\\d{6}/.test(codice);"],"bug":1,"fix":"const valido = /^\\\\d{6}$/.test(codice);","why":{"it":"Senza ancore passa anche “abc1234567”.","en":"Without anchors “abc1234567” passes too."}}');
