INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'api-design' AND slug = 'api-security'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["app.get(\\"/ordini/:id\\", autentica, async (req, res) => {","  const ordine = await db.ordini.trova(req.params.id);","  res.json(ordine);","});"],"bug":1,"fix":"  const ordine = await db.ordini.trova(req.params.id, { utenteId: req.utente.id });","why":{"it":"Senza il filtro sull’utente chiunque legge gli ordini degli altri: è la BOLA.","en":"Without the user filter anyone reads others’ orders: that is BOLA."}}');
