INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'algorithms' AND slug = 'dp-greedy'),1,'order','{"prompt":{"it":"Rimetti le righe nell’ordine giusto.","en":"Put the lines back in the right order."},"lines":["function fib(n) {","  if (n < 2) return n;","  if (memo.has(n)) return memo.get(n);","  const r = fib(n - 1) + fib(n - 2);","  memo.set(n, r);","  return r;","}"],"why":{"it":"Caso base, cache, calcolo, salvataggio.","en":"Base case, cache, compute, save."}}');
