INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'auth'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["$id = (int)$_GET[\\"ordine\\"];","$st = $pdo->prepare(\\"SELECT * FROM ordini WHERE id = ?\\");","$st->execute([$id]);"],"bug":1,"fix":"$st = $pdo->prepare(\\"SELECT * FROM ordini WHERE id = ? AND utente_id = ?\\");","why":{"it":"Manca il controllo che l’ordine sia dell’utente.","en":"The check that the order belongs to the user is missing."}}');
