INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'web-security' AND slug = 'crypto-secrets'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["const crypto = require(\\"node:crypto\\");","const token = Math.random().toString(36).slice(2);","salvaTokenReset(utente, token);"],"bug":1,"fix":"const token = crypto.randomBytes(32).toString(\\"base64url\\");","why":{"it":"`Math.random()` è prevedibile: per i token serve un generatore crittografico.","en":"`Math.random()` is predictable: tokens need a cryptographic generator."}}');
