INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'keyboard'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Un sito deve funzionare solo con la tastiera","en":"A site must work with the keyboard alone"},true],[{"it":"outline: none senza alternative è una buona pratica","en":"outline: none without an alternative is good practice"},false],[{"it":"Il testo grande richiede almeno 3:1 di contrasto","en":"Large text needs at least 3:1 contrast"},true],[{"it":"Un bordo rosso basta a segnalare un errore","en":"A red border alone signals an error"},false]],"why":{"it":"Visibile per tutti.","en":"Visible to all."}}');
