INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'forms'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Ogni campo dovrebbe avere un’etichetta","en":"Every field should have a label"},true],[{"it":"ARIA va usato al posto dell’HTML semantico","en":"ARIA should replace semantic HTML"},false],[{"it":"VoiceOver è uno screen reader","en":"VoiceOver is a screen reader"},true],[{"it":"Un punteggio Lighthouse di 100 garantisce un sito accessibile","en":"A Lighthouse score of 100 guarantees an accessible site"},false]],"why":{"it":"Verificare davvero.","en":"Really checking."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'aria'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["aria-expanded",{"it":"Menu aperto o chiuso","en":"Menu open or closed"}],["aria-label",{"it":"Nome accessibile","en":"Accessible name"}],["aria-live",{"it":"Annuncia gli aggiornamenti","en":"Announces updates"}],["aria-hidden",{"it":"Nasconde ai lettori","en":"Hides from readers"}],["VoiceOver",{"it":"Lettore di Apple","en":"Apple’s reader"}]],"why":{"it":"ARIA con giudizio.","en":"ARIA with judgement."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'aria'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Un button nativo è meglio di un div con role","en":"A native button beats a div with role"},true],[{"it":"Più ARIA rende sempre una pagina più accessibile","en":"More ARIA always makes a page more accessible"},false],[{"it":"aria-hidden toglie un elemento ai lettori di schermo","en":"aria-hidden removes an element from screen readers"},true],[{"it":"I lettori di schermo esistono solo su Windows","en":"Screen readers exist only on Windows"},false]],"why":{"it":"Accessibilità dinamica.","en":"Dynamic accessibility."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'structure'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["lang",{"it":"Lingua e pronuncia","en":"Language and pronunciation"}],["<title>",{"it":"Dove ti trovi","en":"Where you are"}],["<main>",{"it":"Il contenuto principale","en":"The main content"}],["<nav>",{"it":"La navigazione","en":"Navigation"}],[{"it":"Vai al contenuto","en":"Skip to content"},{"it":"Salta il menu","en":"Skips the menu"}]],"why":{"it":"Una pagina che si capisce prima ancora di leggerla.","en":"A page you understand before you even read it."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'structure'),2,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["<!doctype html>","<html>","<head>","  <title>Corsi · Fucina</title>","</head>"],"bug":1,"fix":"<html lang=\\"it\\">","why":{"it":"Senza `lang` lo screen reader non sa con che pronuncia leggere.","en":"Without `lang` the screen reader does not know which pronunciation to use."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'wcag22'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[[{"it":"Dimensione del bersaglio","en":"Target size"},{"it":"Almeno 24×24 pixel","en":"At least 24×24 pixels"}],[{"it":"Focus non nascosto","en":"Focus not obscured"},{"it":"Niente barre sopra il focus","en":"No bars covering the focus"}],[{"it":"Trascinamento","en":"Dragging"},{"it":"Alternativa con un tocco","en":"Alternative with a tap"}],[{"it":"Autenticazione accessibile","en":"Accessible authentication"},{"it":"Niente enigmi per entrare","en":"No puzzles to log in"}],[{"it":"Dati ridondanti","en":"Redundant entry"},{"it":"Non chiedere due volte lo stesso dato","en":"Do not ask for the same data twice"}]],"why":{"it":"Criteri nati dall’uso quotidiano del web.","en":"Criteria born from everyday web use."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'wcag22'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Le WCAG 2.2 sono uscite nel 2023","en":"WCAG 2.2 came out in 2023"},true],[{"it":"Una barra fissa può coprire l’elemento con il focus senza problemi","en":"A sticky bar may cover the focused element with no problem"},false],[{"it":"Impedire di incollare la password ostacola l’accessibilità","en":"Blocking password pasting harms accessibility"},true],[{"it":"Un bersaglio di 12×12 pixel senza spazio intorno rispetta il livello AA","en":"A 12×12 pixel target with no space around it meets level AA"},false]],"why":{"it":"Più spazio per le dita, meno fatica per la memoria.","en":"More room for fingers, less strain on memory."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'focus-management'),1,'order','{"prompt":{"it":"Rimetti le righe nell’ordine giusto.","en":"Put the lines back in the right order."},"lines":[{"it":"Il pulsante apre la modale","en":"The button opens the modal"},{"it":"Il focus entra nella modale","en":"Focus moves into the modal"},{"it":"Tab resta dentro la modale","en":"Tab stays inside the modal"},{"it":"Esc chiude la modale","en":"Esc closes the modal"},{"it":"Il focus torna al pulsante","en":"Focus returns to the button"}],"why":{"it":"Il percorso del focus in una modale fatta bene.","en":"The focus path in a well-made modal."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'focus-management'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Un `<dialog>` aperto con `showModal()` si chiude con Esc","en":"A `<dialog>` opened with `showModal()` closes with Esc"},true],[{"it":"Con una modale aperta, Tab può finire sulla pagina dietro","en":"With a modal open, Tab may land on the page behind"},false],[{"it":"`inert` toglie un blocco anche agli screen reader","en":"`inert` removes a block from screen readers too"},true],[{"it":"Dopo la chiusura il focus può restare perso","en":"After closing, focus may stay lost"},false]],"why":{"it":"Il focus è il cursore di chi usa la tastiera: non perderlo mai.","en":"Focus is the keyboard user’s cursor: never lose it."}}');
