INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'a11y' AND slug = 'media-motion'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Un audio che parte da solo può coprire lo screen reader","en":"Audio that starts by itself can drown out the screen reader"},true],[{"it":"I sottotitoli servono solo ai video in lingua straniera","en":"Captions are only for foreign-language videos"},false],[{"it":"Un carosello automatico deve potersi fermare","en":"An automatic carousel must be stoppable"},true],[{"it":"Un lampeggio veloce è solo un problema estetico","en":"Fast flashing is only an aesthetic problem"},false]],"why":{"it":"Contenuti ricchi, ma per tutti.","en":"Rich content, but for everyone."}}');
