INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'http-status'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Un 301 trasferisce il valore al nuovo indirizzo","en":"A 301 passes the value on to the new address"},true],[{"it":"Una pagina d’errore deve rispondere 200","en":"An error page should answer 200"},false],[{"it":"Le catene di reindirizzamenti sprecano budget di scansione","en":"Redirect chains waste crawl budget"},true],[{"it":"Un 503 lungo mesi non ha conseguenze","en":"A 503 lasting months has no consequences"},false]],"why":{"it":"Codici sinceri, crawler contenti.","en":"Honest codes, happy crawlers."}}');
