INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'ai-crawlers'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Alcuni bot AI addestrano i modelli, altri cercano risposte","en":"Some AI bots train models, others look for answers"},true],[{"it":"Bloccare `Google-Extended` toglie il sito da Google","en":"Blocking `Google-Extended` removes the site from Google"},false],[{"it":"`robots.txt` protegge i dati riservati","en":"`robots.txt` protects private data"},false],[{"it":"Ogni crawler può avere regole diverse","en":"Each crawler can have different rules"},true]],"why":{"it":"Decidi tu chi può usare i tuoi contenuti, e per che cosa.","en":"You decide who can use your content, and for what."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'crawler' AND slug = 'js-mobile'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[[{"it":"Mobile-first","en":"Mobile-first"},{"it":"Si indicizza la versione per telefono","en":"The phone version is indexed"}],["<a href>",{"it":"Link che il crawler segue","en":"Link the crawler follows"}],[{"it":"Rendering lato client","en":"Client-side rendering"},{"it":"La pagina si costruisce nel browser","en":"The page is built in the browser"}],[{"it":"Rendering lato server","en":"Server-side rendering"},{"it":"L’HTML arriva completo","en":"The HTML arrives complete"}]],"why":{"it":"Ciò che il crawler non vede, per lui non esiste.","en":"What the crawler cannot see does not exist for it."}}');
