INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'fluent' AND slug = 'code'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"I componenti Fluent UI React sono già accessibili","en":"Fluent UI React components are already accessible"},true],[{"it":"WinUI 3 serve per i siti web","en":"WinUI 3 is for websites"},false],[{"it":"I token rendono facile il tema scuro","en":"Tokens make dark theme easy"},true],[{"it":"FluentProvider va messo dentro ogni pulsante","en":"FluentProvider goes inside every button"},false]],"why":{"it":"Fluent per sviluppatori.","en":"Fluent for developers."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'fluent' AND slug = 'type-icons'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["Regular",{"it":"Icona a contorno","en":"Outlined icon"}],["Filled",{"it":"Icona piena, stato attivo","en":"Filled icon, active state"}],["4 px",{"it":"Base della spaziatura","en":"Spacing base"}],["Body",{"it":"Testo del corpo","en":"Body text"}],["Display",{"it":"Il testo più grande","en":"The largest text"}]],"why":{"it":"Testo, icone e spazio.","en":"Text, icons and space."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'fluent' AND slug = 'type-icons'),2,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"card: {\\n  padding: tokens.___,\\n  fontSize: tokens.___,\\n}","gaps":["spacingHorizontalM","fontSizeBase300"],"extra":["padding12","font14px"],"why":{"it":"I token di spaziatura e di testo.","en":"The spacing and text tokens."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'fluent' AND slug = 'a11y'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[[{"it":"Tema a contrasto","en":"Contrast theme"},{"it":"Pochi colori scelti dall’utente","en":"A few colours chosen by the user"}],[{"it":"Focus visivo","en":"Focus visual"},{"it":"Doppio bordo visibile ovunque","en":"Double border visible anywhere"}],[{"it":"Tasti di accesso","en":"Access keys"},{"it":"Lettere che compaiono con Alt","en":"Letters shown with Alt"}],[{"it":"Acceleratore","en":"Accelerator"},"Ctrl+S"],[{"it":"Assistente vocale","en":"Narrator"},{"it":"Lettore di schermo","en":"Screen reader"}]],"why":{"it":"Windows per tutti.","en":"Windows for everyone."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'fluent' AND slug = 'a11y'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Le icone personalizzate vanno controllate nei temi a contrasto","en":"Custom icons must be checked in contrast themes"},true],[{"it":"Il focus visivo si può nascondere per estetica","en":"Focus visuals can be hidden for aesthetics"},false],[{"it":"Windows permette di ingrandire il testo fino al 225%","en":"Windows lets you enlarge text up to 225%"},true],[{"it":"I controlli personalizzati vengono annunciati bene senza etichette","en":"Custom controls are announced well without labels"},false]],"why":{"it":"Accessibilità in Fluent.","en":"Accessibility in Fluent."}}');
